T('[검수 11-17 #339] 거래 전 캡 심사는 보내는 선수의 잔여 계약금도 포함한다',()=>{fresh();G.day=KD(12,10);G.rolled=G.year;const p=domestic(G.user)[0],b=otherT();p.ctT=G.user;p.capB={a:900,until:G.year+3};const pre=capPayAs(G.user,[],[p.id]);tradeTerms(p);p.team=b;mvLog('트레이드',p,G.user,b);ok(pre===capPayNext(G.user),'예상 캡과 실제 캡 불일치: '+pre+'/'+capPayNext(G.user));});
