T('[검수 11-17 #345] 웨이버 승계 뒤 이전 구단의 조정 신청을 끝낸다',()=>{fresh();const p=domestic(otherT())[0],a=p.team;p.sal=80;p.arbP={club:550,player:600,tid:a};p.team=null;G.day=G.cal.open+10;p.wv={from:a,end:G.day,ok:true,cl:[G.user],c:{sal:80,yrs:1}};const wants=wvWants,ord=wvOrder;try{wvWants=()=>false;wvOrder=()=>[G.user,a];wvDaily();}finally{wvWants=wants;wvOrder=ord;}ok(p.team===G.user,'웨이버 준비');arbLeftDecide();ok(p.sal===80&&!p.arbP,'이전 조정이 승계 계약을 덮어씀');});
