T('[검수 11-17 #367] 연봉 필터도 확정된 다음 시즌 계약으로 판단한다',()=>{fresh();G.day=KD(12,10);G.rolled=G.year;G.last={y:G.year};const a=domestic(G.user)[0],b=domestic(otherT())[0];a.sal=100;b.sal=100;b.extNext={annual:700,years:2};const f={...TRO_F0,bal:-1e9,sal:0};ok(troCheck({from:b.team,give:[b.id],get:[a.id]},f).includes('연봉'),'다음 시즌 연봉 증가 제안 통과');});
T('[검수 11-17 #368] 윈나우 필터는 현재 기용할 수 없는 선수를 즉시 전력에서 뺀다',()=>{fresh();const a=domestic(G.user)[0],b=domestic(otherT())[0];a.injOut=0;b.injOut=90;const old=ovr;try{ovr=p=>p.id===a.id?68:p.id===b.id?73:old(p);ok(troCheck({from:b.team,give:[b.id],get:[a.id]},{...TRO_F0,bal:-1e9,dir:'win'}),'90일 부상 선수 윈나우 통과');}finally{ovr=old;}});

T('[검수 11-17 #335 저장] 남아 있는 계약 총액과 이동 기록으로 잔여 캡을 난수 없이 한 번 복원한다',()=>{fresh();G.day=KD(12,10);G.rolled=G.year;G.last={y:G.year};const p=domestic(G.user)[0],from=otherT();p.ctT=G.user;p.ctB={b:3600,sy:G.year,years:4,tid:from};p.cyrs=4;delete p.capB;G.moves=[{pid:p.id,t:'2차 드래프트',from,to:G.user,y:G.year,d:G.day-10}];const rng=__rngState();sdContractFix();const L=(G.capDeadF||[]).filter(x=>x.pid===p.id&&x.t===from);ok(L.length===3&&L.every(x=>x.a===900),'잔여 계약금 복원 오류');const snap=JSON.stringify(G.capDeadF);sdContractFix();ok(__rngState()===rng&&JSON.stringify(G.capDeadF)===snap,'복원 난수 또는 중복');});
T('[검수 11-17 #338 저장] 방출 뒤 새 계약의 옛 의무를 불러올 때 한 번 종료한다',()=>{fresh();const p=domestic(otherT())[0],o=revOb(p);p.relT=o.to;p.relD=G.day;p.team=G.teams.find(t=>t.id!==o.from&&t.id!==o.to).id;const rng=__rngState();sdObFix();ok(!p.sd2&&G.sd2.seq[0].ob==='rel','옛 의무 정리 누락');const snap=JSON.stringify(G.sd2);sdObFix();ok(__rngState()===rng&&JSON.stringify(G.sd2)===snap,'옛 의무 정리 멱등성');});
T('[추가 리뷰] 2차 지명 전 같은 해 방출 이력은 새 의무를 없애지 않는다',()=>{fresh();G.day=G.cal.end+10;const p=domestic(otherT())[0],old=p.team;p.relD=G.day-120;p.relT=G.teams.find(t=>t.id!==old&&t.id!==G.user).id;p.tLog=[{y:G.year,d:p.relD,f:p.relT,t:null,s:p.sal},{y:G.year,d:p.relD+10,f:null,t:old,s:p.sal}];const s=revPick(G.user);G.sd2={y:G.year,stage:'done',seq:[s]};sdTake(s,p.id);ok(p.sd2,'지명 직후 의무 준비');sdObFix();ok(p.sd2,'지명 전 방출 이력 때문에 저장 복원 시 새 등록 의무 소멸: '+JSON.stringify(s));});
T('[추가 리뷰] 사임 직후 같은 구단 재취임도 구단 드래프트 업무를 복원한다',()=>{const L=revPool(),a=G.user;G.shortlist=[L[1].id,L[0].id];G.dplan={y:G.year,C:1};draftRestSet('board');L[0].rchkA={건강:{tid:a,t:'저장된답',d:G.day}};firedFlow(G.year,'검수 사임','resign');ok(G.unemp&&G.dClub[a]?.shortlist[0]===L[1].id,'사임 저장 준비');switchTeam(a);ok(G.shortlist[0]===L[1].id&&dplanOf().C===1&&draftRestPre()?.mode==='board'&&L[0].rchkA?.건강,'같은 구단 재취임 시 보드/목표/자동지명/답변 복원 누락');});
T('[추가 리뷰] 구버전 2차 지명 뒤 방출 이력은 새 계약에서 의무를 제거한다',()=>{fresh();G.day=G.cal.end+10;const p=domestic(otherT())[0],old=p.team,s=revPick(G.user);G.sd2={y:G.year,stage:'done',seq:[s]};sdTake(s,p.id);delete p.sd2.d;p.relD=G.day+1;p.relT=G.user;p.tLog.push({y:G.year,d:p.relD,f:G.user,t:null,s:p.sal});p.team=old;sdObFix();ok(!p.sd2&&s.ob==='rel','구버전 지명 이후 방출 이력이 새 계약 의무에 남음');});
T('[추가 리뷰] 시즌 중 웨이버는 다음 개막 여유와 별개로 현재 정원을 지킨다',()=>{fresh();G.day=G.cal.open+10;revFull(G.user);const incoming=domestic(otherT())[0];incoming.team=null;incoming.wv={from:otherT(),end:G.day+3,ok:true,cl:[],c:{sal:MIN_SAL,yrs:1}};const late=Object.values(G.players).find(p=>p.team===G.user&&p.joinY>G.year);delete late.joinY;const dep=domestic(G.user).find(p=>!p.mil);enlist(dep,'상무',KD(12,10));ok(rosterN(G.user)===68&&rosterProj(G.user)===67,'현재68/내년67 준비 실패 '+rosterN(G.user)+'/'+rosterProj(G.user));const c=wvCapCheck;try{wvCapCheck=()=>null;wvClaim(incoming.id);}finally{wvCapCheck=c;}ok(!incoming.wv.cl.includes(G.user),'현재 정원68명인데 겨울 입대 예정자를 빼고 시즌중 양수 승인');});
T('[추가 리뷰] 시즌 중 웨이버 결정일에도 현재 정원을 재검사한다',()=>{fresh();G.day=G.cal.open+10;revFull(G.user);const incoming=domestic(otherT())[0],from=incoming.team;incoming.team=null;incoming.wv={from,end:G.day,ok:true,cl:[G.user],c:{sal:MIN_SAL,yrs:1}};const late=Object.values(G.players).find(p=>p.team===G.user&&p.joinY>G.year);delete late.joinY;const dep=domestic(G.user).find(p=>!p.mil);enlist(dep,'상무',KD(12,10));const c=wvCapCheck,w=wvWants,o=wvOrder;try{wvCapCheck=()=>null;wvWants=()=>false;wvOrder=()=>[G.user,from];wvDaily();}finally{wvCapCheck=c;wvWants=w;wvOrder=o;}ok(incoming.team!==G.user&&rosterN(G.user)===68,'결정일에 현재 정원 초과 양수: '+rosterN(G.user));});

const ffinSetup=()=>{ fresh(); G.day=G.cal.end+8; G.rolled=G.year; G.fa={pool:[],offers:{},ai:{},open:true,openDay:G.day-10,closed:false,results:[],cap:3,outN:{},y0:G.year}; };
const ffinP=(tid,grade='C')=>{ const p=newPlayer({age:28,isP:false,base:56,pot:58,team:tid}); p.team=null;p.sal=100;p.faFrom=tid;p.faGrade=grade;p.faPrevSal=100;p.ask={annual:300,years:3};p.ask0=300;G.fa.pool.push(p.id); return p; };
T('[검수 11-17 #382] 구버전 영입 한도는 시장 명단 감소 뒤에도 고정 [FA재정검수]',()=>{ ffinSetup(); delete G.fa.cap; G.fa.pool=Array.from({length:21},(_,i)=>800000+i); ok(faCapN()===3,'초기 한도'); G.fa.pool.pop(); ok(faCapN()===3,'시장 도중 영입 한도가 감소'); delete G.fa.cap; G.fa.results=[{id:800020}];ok(faCapN()===3,'체결 기록으로 최초 시장 인원 복구 못함'); });
T('[검수 11-17 #383] FA 예정 태그는 다음 계약과 불가능한 등록일수를 제외 [FA재정검수]',()=>{ fresh(); const p=domestic(G.user).find(q=>!q.foreign);p.svc=faSvc(p)-1;p.faC=false;p.lastFA=null;p.extNext={annual:300,years:3};ok(!lifeTags(p).some(x=>x.l==='FA 예정'),'다음 다년계약이 확정됐는데 태그');delete p.extNext;G.regTrk=G.year;G.day=G.cal.end-5;p.regD={y:G.year,n:20};p.svcD=0;ok(!faUpcoming().some(x=>x.p.id===p.id),'남은 등록일수로 불가능한 자격을 예고');ok(!lifeTags(p).some(x=>x.l==='FA 예정'),'불가능한 자격 태그'); });
T('[검수 11-17 #384] 예상 등급과 결산 순위는 동일한 다년계약 제외 기준 [FA재정검수]',()=>{ fresh();const p=domestic(G.user).find(q=>!q.foreign);p.age=28;p.faN=0;delete p.lastFA;p.faC=false;p.salH=[{s:500}]; const L=[p];for(let i=0;i<3;i++)L.push({id:990000+i,team:p.team,foreign:false,age:28,faC:true,ext:true,yrs:2,salH:[{s:800}]}); const a=faGradeOf(p,L);const S=new Map(L.map(q=>[q.id,{...q,yrs:q.faC?q.yrs-1:q.yrs,gradeYrs:q.yrs}]));const b=faGradeOf(p,L,S);ok(a===b&&a==='A','예상 '+a+' / 결산 '+b); });
T('[검수 11-17 #385] 구버전 두번째 FA 계약은 누적 2회로 저장 [FA재정검수]',()=>{ ffinSetup();const p=ffinP(G.user,'B');p.lastFA=G.year-5;delete p.faN; faSign(p,[{tid:G.user,annual:300,years:3}]);ok(p.team===G.user&&p.faN===2,'누적 FA 횟수 '+p.faN);p.faC=false;p.age=33;ok(faGradeOf(p,[p])==='C','세번째 FA가 C가 아님'); });
T('[검수 11-17 #386] AI FA 계약은 실제 입찰액으로 상한 재검사 [FA재정검수]',()=>{ ffinSetup();const tid=otherT(),p=ffinP(G.user);const t=team(tid);t.indie=false;t.cash=100000;t.owner='win';t.trust=80; const lim=Math.floor(capOf(sponSeason())*(1+capOwnerLim(t))), bid=lim+1000;faSign(p,[{tid,annual:bid,years:3}]);ok(p.team==null,'실제 입찰로 캡 한도 넘는 AI 계약');faSign(p,[{tid,annual:300,years:3}]);ok(p.team===tid,'허용 한도 안의 AI 계약도 막음'); });
T('[검수 11-17 #387] AI 계약금 분할은 보장 총액과 장부 금액 보존 [FA재정검수]',()=>{ ffinSetup();const tid=otherT(),p=ffinP(G.user);p.team=tid;p.sal=715;const tot=p.sal*4;aiFaBonus(p,{tid,annual:p.sal,years:4});ok(p.ctB&&p.ctB.b+p.sal*4===tot,'계약금 분할 총액 '+(p.ctB?.b+p.sal*4)+' / '+tot); });
T('[검수 11-17 #388] 독립구단은 계약금과 보상금 모두 지급 가능해야 수락 [FA재정검수]',()=>{ ffinSetup();const p=ffinP(otherT());team(G.user).indie=true;team(G.user).cash=0;p.faPrevSal=400;const n=negOf(p.id);n.counter={annual:1000,years:3,terms:{annual:300,bonus:800,years:3,opt:0}};const before=JSON.stringify(n.counter);faAcceptCounter(p.id);ok(p.team==null,'현금0인데 14억 약정 계약');ok(JSON.stringify(n.counter)===before,'자금 부족인데 역제안 소멸'); });
T('[검수 11-17 #389] 미결 외부FA 보상금은 최대 현금보상액만큼 유보 [FA재정검수]',()=>{ ffinSetup();team(G.user).indie=true;team(G.user).cash=2000;const p=ffinP(otherT(),'A');p.faPrevSal=500;faSign(p,[{tid:G.user,annual:300,years:3}]);ok(p.team===G.user,'준비 계약 실패');ok(sdCash(G.user)===500,'미결보상금 유보 안됨 '+sdCash(G.user));const q=ffinP(otherT(),'A');q.faPrevSal=500;faSign(q,[{tid:G.user,annual:300,years:3}]);ok(q.team==null,'유보자금을 두번째 FA에 중복 사용');const c=G.comp.find(x=>x.pid===p.id);c.stage='pick';c.prot=[];compResolve(c,null);ok(sdCash(G.user)===500,'정산 후 유보금 이중 차감 '+sdCash(G.user)); });
T('[검수 11-17 #390] 겨울FA는 다음 개막 입단자까지 정원 검사 [FA재정검수]',()=>{ ffinSetup();while(rosterN(G.user)<ROSTER_MAX-1)newPlayer({age:22,isP:false,base:40,pot:42,team:G.user});trimRoster(G.user,ROSTER_MAX-1);const next=newPlayer({age:19,isP:false,base:40,pot:42,team:G.user});next.joinY=G.year+1;const p=ffinP(otherT());negOf(p.id).counter={annual:300,years:3};faAcceptCounter(p.id);ok(p.team==null,'내년 입단자를 빼고 FA 체결');faSign(p,[{tid:G.user,annual:300,years:3}]);ok(p.team==null,'일반 계약도 예정정원 초과');next.joinY=G.year;const m=domestic(G.user).find(q=>q!==next&&!q.ys&&!q.foreign);m.mil={unit:'현역',from:G.day+1,until:G.day+1000};ok(rosterN(G.user)===ROSTER_MAX&&rosterProj(G.user)<ROSTER_MAX,'즉시 정원 준비 실패');negOf(p.id).counter={annual:300,years:3};faAcceptCounter(p.id);ok(p.team==null&&negOf(p.id).counter,'개막 정원만 보고 현재 정원을 초과'); });

const cpCase=()=>{ fresh(); G.day=KD(12,10);G.rolled=G.year; const to=otherT(),q=compPool(to).slice(-1)[0]; ok(q,'후보 준비'); const c={id:'cpReview',pid:-999,name:'검수 FA',grade:'A',from:G.user,to,prev:300,day:G.day,stage:'pick',prot:[],pool0:[q.id],away0:[]}; G.comp=[c];return {c,q}; };
T('[검수 11-17 #391] 구단주 허용 캡을 넘는 보상선수는 지급과 이적 전에 거절한다 [보상검수]',()=>{ const {c,q}=cpCase();q.sal=30000;delete q.newSal;delete q.extNext;const before=JSON.stringify(G.spend),tid=q.team;compResolve(c,q.id);ok(c.stage==='pick'&&q.team===tid&&JSON.stringify(G.spend)===before,'캡 초과 지명 승인 또는 보상금 선지급'); });
T('[검수 11-17 #392] 보상 지명은 다음 개막 합류 확정 인원을 포함한다 [보상검수]',()=>{ const {c,q}=cpCase();revFull(G.user);ok(rosterN(G.user)===67&&rosterProj(G.user)===68,'정원 준비');compResolve(c,q.id);ok(q.team===c.to&&c.stage==='pick','내년 69명인데 지명 승인'); });
T('[검수 11-17 #393] 보상선수 원구단의 계약금 캡은 잔여 기간 보존한다 [보상검수]',()=>{const {c,q}=cpCase();q.sal=100;delete q.newSal;q.ctT=c.to;q.capB={a:750,until:G.year+3};const pred=capPayAs(G.user,[q.id],[]);compResolve(c,q.id);ok(q.team===G.user,'이적 준비 실패');ok((G.capDeadF||[]).some(x=>x.pid===q.id&&x.t===c.to&&x.a===750&&x.y===G.year+1),'계약금 캡 소멸');ok(pred===capPayNext(G.user),'지명 전 심사와 실제 캡 불일치 '+pred+'/'+capPayNext(G.user));});
T('[검수 11-17 #394] 한 번 지명한 보상선수 영입 장부는 원구단과 함께 한 건이다 [보상검수]',()=>{const {c,q}=cpCase();q.sal=100;delete q.newSal;G.mineL=[];compResolve(c,q.id);const L=G.mineL.filter(x=>x.id===q.id);ok(L.length===1&&q.acq.from===c.to,'중복 영입 또는 원구단 소멸 '+L.length);});
T('[검수 11-17 #395] 거절한 빈 보호명단은 재사용 명단을 덮어쓰지 않는다 [보상검수]',()=>{const {c}=cpCase();c.to=G.user;c.from=otherT();c.stage='protect';const p=compPool(G.user)[0];G.protLast={y:stoveY(),tid:G.user,ids:[p.id]};const before=JSON.stringify(G.protLast);compSubmit(c.id,[]);ok(JSON.stringify(G.protLast)===before&&c.stage==='protect','거절한 명단이 저장됨');});
T('[검수 11-17 #396] 이직과 복귀 뒤 구단별 보호명단을 재사용한다 [보상검수]',()=>{const {c}=cpCase(),a=G.user,b=otherT(),p=compPool(a)[0],q=compPool(b)[0];c.to=a;c.from=b;c.stage='protect';compSubmit(c.id,[p.id]);switchTeam(b);const d={...c,id:'cpOther',to:b,from:a,stage:'protect'};G.comp.push(d);compSubmit(d.id,[q.id]);switchTeam(a);ok(compProtLast(a).ids.includes(p.id)&&!compProtLast(a).ids.includes(q.id),'복귀 구단 보호명단 소실');});
T('[검수 11-17 #397] AI끼리 즉시 마친 보상 건은 사용자 완료 기록을 밀어내지 않는다 [보상검수]',()=>{fresh();const [a,b]=G.teams.filter(t=>t.id!==G.user).slice(0,2).map(t=>t.id);G.comp=Array.from({length:30},(_,i)=>({id:'mine'+i,stage:'done',from:G.user,to:a}));const p=domestic(a)[0];p.faGrade='A';p.faPrevSal=300;compStart(p,a,b,{id:'review'});ok(G.comp.length===30&&G.comp.every(c=>c.id.startsWith('mine')),'AI 건 때문에 사용자 기록 소실 '+G.comp.length);});
T('[검수 11-17 #391 예측] 보상 지명 전 계산과 실제 캡은 계약금과 승계 연봉까지 같다 [보상검수]',()=>{ const {c,q}=cpCase();q.sal=100;q.ctT=c.to;q.capB={a:750,until:G.year+3};q.extNext={annual:450,years:2,terms:{annual:450,years:2,bonus:600,opt:100,ntc:true}};const expected=capPayAs(G.user,[q.id],[]),rng=__rngState();const chk=compPickCheck(c,q.id);ok(chk.ok&&chk.pay===expected&&__rngState()===rng,'심사 계산 또는 난수');compResolve(c,q.id);ok(q.team===G.user&&capInfo(G.user).pay===expected,'실제 캡 불일치 '+expected+'/'+capInfo(G.user).pay); });
T('[검수 11-17 #391 AI] AI도 허용 한도를 넘는 선수 대신 현금을 받는다 [보상검수]',()=>{ const {c,q}=cpCase();c.from=G.teams.find(t=>t.id!==G.user&&t.id!==c.to).id;q.sal=30000;delete q.extNext;delete q.newSal;compResolve(c,q.id);ok(c.stage==='done'&&!c.cpid&&q.team===c.to&&c.cash===900,'AI 초과 지명 또는 현금 보상 누락');});
T('[검수 11-17 #396 구버전] 단일 보호명단은 다른 구단의 새 제출 전에 보존하며 복원을 반복해도 같다 [보상검수]',()=>{const {c}=cpCase(),a=G.user,b=otherT(),p=compPool(a)[0],q=compPool(b)[0];delete G.protByTeam;G.protLast={y:stoveY(),ids:[p.id]};switchTeam(b);c.to=b;c.from=a;c.stage='protect';compSubmit(c.id,[q.id]);ok(compProtLast(a).ids.includes(p.id),'구버전 원구단 명단 소실');const n=JSON.stringify(G.protByTeam),rng=__rngState();compProtLast(a);compProtLast(a);ok(JSON.stringify(G.protByTeam)===n&&__rngState()===rng,'복원 멱등 또는 난수');});
T('[검수 11-17 #392 현재정원] 입대 예정으로 개막 인원이 줄어도 당일 정원을 넘겨 지명할 수 없다 [보상검수]',()=>{const {c,q}=cpCase();revFull(G.user);const incoming=Object.values(G.players).find(p=>p.team===G.user&&p.joinY===G.year+1);delete incoming.joinY;enlist(domestic(G.user)[0],'상무',KD(12,15));ok(rosterN(G.user)===68&&rosterProj(G.user)===67,'현재·개막 정원 준비');compResolve(c,q.id);ok(c.stage==='pick'&&q.team===c.to,'당일 69명 지명 승인');});

const FAN_FA=(star=false)=>{ fresh(); G.day=KD(12,12); G.fa={pool:[],offers:{},ai:{},open:true,openDay:KD(11,6),closed:false,results:[],cap:3,outN:{},y0:G.year}; const p=newPlayer({age:28,isP:false,base:star?72:55,pot:75,team:G.user}); p.team=null;p.faFrom=G.user;p.faGrade='C';p.faPrevSal=100;p.sal=100;p.ask={annual:800,years:3};p.ask0=800; p.agId=agInit().findIndex(a=>a.style==='rel'&&a.size!=='big');G.fa.pool=[p.id];G.fa.ai[p.id]={};negOf(p.id).mood=50;return p; };
const FAN_FULL=tid=>{while(rosterN(tid)<ROSTER_MAX){const base=domestic(tid)[0],q=JSON.parse(JSON.stringify(base));q.id=Math.max(...Object.keys(G.players).map(Number))+1;delete q.mil;delete q.joinY;delete q.frehab;q.ys=false;G.players[q.id]=q;}};
const FAN_O=(p,k=1.1)=>({annual:Math.round(faWantFor(p,G.user)*.97*k/(1+.06*(p.ask.years-1))),years:p.ask.years});
const FAN_T=(p,k)=>{const D=termsDemand(p,'fa',{annual:faWantA(p),years:p.ask.years});const T={...D};delete T.ov;T.annual=Math.round(faWantFor(p,G.user)*.97*k/(1+.06*(T.years-1))/termsMul(T,D)-(T.bonus||0)*CT_BON/T.years);return T;};
T('[검수 11-17 #369] 마감 계약 실패도 무적 시장에 편입합니다 [FA협상검수]',()=>{for(const mode of ['full','owner']){const p=FAN_FA(),n=negOf(p.id);G.fa.offers[p.id]=FAN_O(p);const cc=faCapCheck;try{if(mode==='full')FAN_FULL(G.user);else faCapCheck=()=>({ok:false,msg:'검수 거절'});faClose();}finally{faCapCheck=cc;}ok(G.fa.closed&&p.team==null&&isFree(p),'계약 실패 뒤 무적 시장에서 누락: '+mode);ok(!G.fa.pool.includes(p.id),'닫힌 FA 명단에 잔존');}});
T('[검수 11-17 #370] 안내된 1월 24일에 협상할 수 있습니다 [FA협상검수]',()=>{const p=FAN_FA();G.day=KD(1,23);const old=faDay;try{faDay=()=>{};processDay();}finally{faDay=old;}ok(!G.fa.closed,'마감일 진입 즉시 폐장');ok(faNegotiate(p.id,FAN_O(p)).st==='wait','마감일 협상 불가');processDay();ok(G.fa.closed,'마감 다음날에도 열림');});
T('[검수 11-17 #371] 지연 공시는 실제 협상 개장일을 안내합니다 [FA협상검수]',()=>{FAN_FA();G.day=KD(11,9);G.mail=[];faAnnounce();ok(G.fa.openDay===KD(11,10),'늦은 공시 개장일');ok(G.mail.some(m=>(m.body||'').includes('11월 10일')),'메일이 실제 개장일을 안내하지 않음');});
T('[검수 11-17 #372] 시장 확인 0회 선수는 마감에 바로 사인하지 않습니다 [FA협상검수]',()=>{const p=FAN_FA(true),mk=agMk(p);ok(mk&&mk.need>0,'시장 확인 준비');G.fa.offers[p.id]=FAN_O(p,2);faClose();ok(p.team==null&&isFree(p),'시장 확인을 건너뛰고 마감 사인');ok(mk.round===0,'마감이 확인 라운드를 날조');});
T('[검수 11-17 #373] 라스트 룩 만료는 시장 보고 라운드를 늘리지 않습니다 [FA협상검수]',()=>{const p=FAN_FA(true),mk=agMk(p);mk.round=mk.need;mk.next=G.day;mk.ll={tid:G.user,until:G.day-1,annual:900,years:3};G.fa.offers[p.id]=FAN_O(p);agShopTick(p,mk,{},G.day);ok(mk.round===mk.need&&mk.done,'라스트 룩 뒤 초과 라운드 '+mk.round+'/'+mk.need);ok(!negOf(p.id).log.some(l=>(l.t||'').includes((mk.need+1)+'/'+mk.need)),'초과 시장 보고');});
T('[검수 11-17 #374] 동일 조건 재제출로 분위기를 올릴 수 없습니다 [FA협상검수]',()=>{const p=FAN_FA(),o=FAN_O(p);faNegotiate(p.id,o);const n=negOf(p.id),m=n.mood,l=n.log.length;for(let i=0;i<6;i++)faNegotiate(p.id,o);ok(n.mood===m&&n.log.length===l,'동일 제안이 분위기 또는 기록을 반복 변경');n.fold=G.day+14;ok(faNegotiate(p.id,o).st==='cool','동일 조건이 냉각을 우회');delete n.fold;n.closed=true;n.rounds=99;G.day=G.fa.openDay+60;n.lastD=G.day-15;ok(faNegotiate(p.id,o).st==='wait'&&n.lastD===G.day,'재개한 협상에서 같은 조건을 평가하지 않음');});
T('[검수 11-17 #375] 같은 역제안 직접 제출도 수락 버튼처럼 사인합니다 [FA협상검수]',()=>{const p=FAN_FA();const n=negOf(p.id);agMk(p).done=true;n.counter=FAN_O(p,1.1);faNegotiate(p.id,{...n.counter});ok(p.team===G.user,'직접 낸 역제안은 즉시 사인하지 않음');});
T('[검수 11-17 #376] 무효 경쟁 제안은 일반 협상 비교에서 제외합니다 [FA협상검수]',()=>{const p=FAN_FA(),b=otherT(),o=FAN_O(p,1.03);G.fa.ai[p.id]={[b]:{annual:9999,years:4}};FAN_FULL(b);const r=faNegotiate(p.id,o);ok(r.st==='wait','무효 제안으로 거절: '+r.st);});
T('[검수 11-17 #377] 무효 경쟁 제안은 역제안 수락을 막지 않습니다 [FA협상검수]',()=>{const p=FAN_FA(),b=otherT();agMk(p).done=true;negOf(p.id).counter=FAN_O(p,1.1);G.fa.ai[p.id]={[b]:{annual:9999,years:4}};FAN_FULL(b);faAcceptCounter(p.id);ok(p.team===G.user,'무효 경쟁 제안이 즉시 사인을 막음');});
T('[검수 11-17 #378] 개장 전 조건의 잠금이 개장 처리에도 유지됩니다 [FA협상검수]',()=>{const p=FAN_FA();const T=FAN_T(p,.95),lock=['annual','bonus','years','opt','role','ntc','cOpt'];G.fa.offers[p.id]={annual:Math.round(termsVal(T,termsDemand(p,'fa',{annual:faWantA(p),years:p.ask.years}))),years:T.years,terms:T,lock};delete G.fa.neg[p.id];G.fa.openDay=G.day;const fi=faInterest;try{faInterest=()=>0;faDay(G.day);}finally{faInterest=fi;}ok(!negOf(p.id).counter,'개장 처리에서 잠금이 사라짐');ok(negOf(p.id).log.some(l=>(l.t||'').includes('잠금')),'잠금 해제 안내 누락');});
T('[검수 11-17 #379] 잠금으로 역제안도 불가한 조건은 사인 대상에서 빠집니다 [FA협상검수]',()=>{const p=FAN_FA();const r=faNegotiate(p.id,{terms:FAN_T(p,.95),lock:['annual','bonus','years','opt','role','ntc','cOpt']});ok(r.st==='no'&&!negOf(p.id).counter,'잠금 준비');ok(!faOfferLive(p.id),'거절 조건이 여전히 유효');faClose();ok(p.team!==G.user,'거절한 조건으로 사인');});
T('[검수 11-17 #380] 원소속 유예는 이미 거절한 원안을 되살리지 않습니다 [FA협상검수]',()=>{const p=FAN_FA(),n=negOf(p.id);G.fa.offers[p.id]={...FAN_O(p,.8),rej:true};n.mood=26;const r=faNegotiate(p.id,FAN_O(p,.5));ok(r.st==='grace','유예 준비');ok(!r.msg.includes('걸어 두신 제안은 그대로'),'거절 원안을 살아 있는 제안처럼 안내');ok(!G.fa.offers[p.id],'거절 원안 복원');});
T('[검수 11-17 #369] 닫힌 구버전 FA 유실 복구는 무난수 멱등입니다 [FA협상검수]',()=>{const p=FAN_FA();G.fa.closed=true;const yr=G.year,tm=rosterN(G.user),r0=__rngState();ok(faClosedFix()===1&&isFree(p)&&p.team==null&&!G.fa.pool.includes(p.id),'옛 미계약 선수 복구 실패');ok(__rngState()===r0&&rosterN(G.user)===tm&&p.freeSince===yr,'복구가 난수·정원·해를 변경');const saved=JSON.stringify(G);ok(faClosedFix()===0&&JSON.stringify(G)===saved&&__rngState()===r0,'복구가 멱등하지 않음');});

T('[교차검토] 독립구단의 AI 계약금 미지급액은 부임 뒤에도 다음 FA 자금에서 제외한다',()=>{fresh();G.day=KD(12,10);G.rolled=G.year;const a=G.user,b=otherT(),t=team(b);t.indie=true;t.cash=2000;G.fa={pool:[],offers:{},ai:{},neg:{},results:[],open:true,closed:false,outN:{},capN:3};const p=domestic(b)[0];p.team=null;p.faFrom=b;p.faGrade='C';p.faPrevSal=100;p.ask={annual:1000,years:4};G.fa.pool.push(p.id);faSign(p,[{tid:b,annual:1000,years:4}]);ok(p.team===b&&t.faBDue>0,'AI 계약금 약정 준비');const due=t.faBDue;switchTeam(b);const q=domestic(a)[0];q.team=null;q.faFrom=a;q.faGrade='C';q.faPrevSal=1333;q.ask={annual:100,years:1};G.fa.pool.push(q.id);const offer={tid:b,annual:100,years:1,terms:{annual:100,years:1,bonus:0,opt:0}};const fc=faFundsCheck(q,offer);console.log('교차검토 자료 '+JSON.stringify({cash:t.cash,due,available:spendable(b),need:2000,blocked:!!fc}));if(!fc){faSign(q,[offer]);console.log('교차검토 실제계약 '+JSON.stringify({signed:q.team===b,comp:G.spend.comp||0,due:t.faBDue,cashAfterCommitted:t.cash-(G.spend.comp||0)-(t.faBDue||0)}));}ok(fc,'AI 계약금 미지급액을 부임 뒤 가용자금에서 누락');});
T('[교차검토] 기존 보상 유보와 새 FA 비용은 한 번씩만 계산하고 정산 즉시 차액을 푼다',()=>{fresh();G.day=KD(12,10);G.rolled=G.year;const t=team(G.user);t.indie=true;t.cash=2000;G.spend={};const p=domestic(otherT())[0];p.faPrevSal=400;const c={id:'crossReserve',pid:p.id,name:p.name,grade:'A',from:otherT(),to:G.user,prev:400,stage:'pick',prot:[]};G.comp=[c];const q=domestic(otherT())[1];q.faFrom=otherT();q.faGrade='C';q.faPrevSal=400;const o={annual:100,years:1,terms:{annual:100,years:1,bonus:200,opt:0}};ok(spendable(G.user)===800&&!faFundsCheck(q,o),'유보금과 신규비용 이중 계산');compResolve(c,null);ok(faCompReserve(G.user)===0&&spendable(G.user)===800&&!faFundsCheck(q,o),'현금정산 뒤 유보금 이중 차감 또는 해제 누락');});

const MCT_PLAYER=(base=62)=>{fresh();const p=newPlayer({age:27,isP:false,base,pot:base+2,team:G.user});p.mil=null;p.sal=100;p.yrs=1;p.svc=9;delete p.extNext;delete p.lastFA;delete p.hold;return p;};
T('[검수 11-17 #400] 새해 현역 예약 취소 뒤에도 강제 입대 일정이 남습니다 [병역계약검수]',()=>{const p=MCT_PLAYER();const y=G.year;G.day=dnum(y,12,29);enlist(p,'현역',dnum(y+1,1,12));p.mil.byGM=true;G.day=dnum(y+1,1,1);newYear();ok(p.age===28,'나이 증가 준비');G.day=dnum(G.year,1,2);ok(enlistCancel(p.id)==='','예약 취소 준비');ok(p.mil&&p.mil.from===dnum(G.year,1,20)&&!p.mil.byGM,'28세 강제 일정 누락');G.day=dnum(G.year,1,20);milDaily();ok(milServing(p),'강제 입대일에도 미필');});
T('[검수 11-17 #401] 새해 FA 합류자도 28세 미필이면 입대합니다 [병역계약검수]',()=>{const p=MCT_PLAYER();p.age=28;p.team=null;p.faFrom=G.user;p.ask={annual:300,years:2};p.ask0=300;p.faGrade='C';G.day=KD(1,10);G.fa={pool:[p.id],offers:{},ai:{},results:[],cap:3,outN:{},open:true,closed:false};faSign(p,[{tid:G.user,annual:300,years:2}]);ok(p.team===G.user,'FA 계약 준비');ok(p.mil&&p.mil.from===G.day+14,'FA 합류 뒤 입대 일정 누락');});
T('[검수 11-17 #402] 복무로 미뤄진 옵트아웃 기회가 다음 결산에 남습니다 [병역계약검수]',()=>{const p=MCT_PLAYER(70);G.day=KD(11,10);p.faC=true;p.yrs=3;p.ctT=G.user;p.pOut={y:G.year};p.mil={unit:'현역',from:KD(4,1),until:dnum(G.year+1,4,1)};offseason();ok(p.pOut&&!p.pOut.used&&p.pOut.y===G.year+1&&p.yrs===3,'복무 중 옵트아웃 날짜 미이월');});
T('[검수 11-17 #403] 복무로 멈춘 계약은 기한부 조항도 함께 이월합니다 [병역계약검수]',()=>{const p=MCT_PLAYER();G.day=KD(11,10);p.faC=true;p.yrs=2;termsApply(p,{years:2,annual:100,bonus:600,opt:100,optC:'g',ntc:true,cOpt:1,role:0},'fa',G.year,true);const old={ntc:p.ntc,cap:p.capB.until,opt:p.opt.until,club:p.cOpt.at,role:p.roleProm.until};p.mil={unit:'현역',from:KD(4,1),until:dnum(G.year+1,4,1)};offseason();ok(p.yrs===2&&p.ntc===old.ntc+1&&p.capB.until===old.cap+1&&p.opt.until===old.opt+1&&p.cOpt.at===old.club+1&&p.roleProm.until===old.role+1,'계약 연수와 조항 만료가 따로 진행');});
T('[검수 11-17 #404] 개막 전 전역자는 겨울 연봉 협상에 참가합니다 [병역계약검수]',()=>{const p=MCT_PLAYER();G.day=KD(12,1);const C=buildCalendar(G.year+1);p.mil={unit:'상무',from:KD(4,1),until:C.open-2};p.newSal=430;G.contract={y:G.year,tid:G.user,ended:[p.id],done:false};salTalkInit();ok(G.contract.neg[p.id].st==='open'&&!G.contract.neg[p.id].mil&&p.newSal===430,'개막 전 전역 선수의 협상을 동결');});
T('[검수 11-17 #405] 복무 중 미계약자는 개막 전 자동 합의에서 빠집니다 [병역계약검수]',()=>{const p=MCT_PLAYER();G.contract=null;G.day=G.cal.open-30;holdStart(p,100,420,true);enlist(p,'현역',G.day+14);G.day=G.cal.open-2;holdDaily(G.day);ok(p.sal===100&&p.hold&&milServing(p),'복무 중 자동 계약으로 연봉 변경');});
T('[검수 11-17 #406] 방출 정산은 복무 기간의 지급하지 않는 연봉을 제외합니다 [병역계약검수]',()=>{const p=MCT_PLAYER();G.day=KD(6,1);p.sal=900;p.faC=false;p.mil={unit:'현역',from:KD(1,1),until:dnum(G.year+1,8,1)};ok(payFrac(p,G.year)===0,'연중 복무 준비');ok(relCost(p).tot===0,'지급 연봉 0원인데 방출 정산금 발생');p.mil.until=KD(6,15);const [a,b]=payWin(G.year),expected=Math.round(p.sal*(b-p.mil.until)/(b-a));ok(relCost(p).tot===expected,'시즌 중 전역 뒤 지급분 정산 불일치');});
T('[검수 11-17 #407] 겨울 지급 연봉 전망도 실제 개막일을 사용합니다 [병역계약검수]',()=>{const p=MCT_PLAYER();G.day=KD(12,1);const y=G.year+1,C=buildCalendar(y);p.sal=1200;p.mil={unit:'상무',from:KD(6,10),until:dnum(y,3,25)};ok(C.open>=p.mil.until,'개막 전 전역 준비');_payWinC.clear();const r=__rngState(),before=payFrac(p,y);ok(before===1,'겨울 전망이 임시 개막일로 복무를 차감');G.cal=C;ok(payFrac(p,y)===before&&__rngState()===r,'일정 생성 전후 지급 비율 변동 또는 난수 소비');});
T('[검수 11-17 #417] FA 전망은 지연 결산일의 실제 복무 상태를 봅니다 [병역계약검수]',()=>{const p=MCT_PLAYER();G.day=KD(11,10);delete G.rolled;G.fa=null;p.age=28;p.faC=true;p.ext=false;p.yrs=1;p.ctT=G.user;p.mil={unit:'상무',from:KD(1,1),until:KD(11,5)};ok(faUpcoming(p).length===1,'결산 전 전역자를 FA 전망에서 제외');p.mil={unit:'현역',from:KD(11,5),until:dnum(G.year+2,5,5)};ok(faUpcoming(p).length===0,'결산 전 입대자를 FA 전망에 포함');});
T('[검수 11-17 #403] 근거가 남은 구버전 계약 조항 복구는 무난수 멱등입니다 [병역계약검수]',()=>{const p=MCT_PLAYER();const y=G.year;G.year=y+2;G.day=dnum(G.year,1,10);G.cal=buildCalendar(G.year);p.faC=true;p.yrs=2;p.ctT=G.user;p.lastFA=y;p.ctB={sy:y,b:600};p.capB={until:y+1,a:300};p.ntc=y+1;p.opt={until:y+1,a:100};p.pOut={y:y+1};p.mil={unit:'현역',from:dnum(y+1,1,20),until:dnum(y+2,7,21)};p.milPause=1;const r=__rngState();ok(ctMilClauseFix(p)===1&&p.ntc===y+2&&p.capB.until===y+2&&p.pOut.y===y+2,'입대기간과 계약시작이 확인되는 옛 휴지연차 복구 실패');const saved=JSON.stringify(p);ok(ctMilClauseFix(p)===0&&JSON.stringify(p)===saved&&__rngState()===r,'옛 조항 복구가 무난수 멱등 아님');termsApply(p,{years:3,annual:100,bonus:300,ntc:true},'fa',G.year,true);ok(!p.milPause&&ctMilClauseFix(p)===0,'새 계약이 옛 휴지 연차를 승계');});
T('[검수 11-17 #404] 이미 동결된 구버전 전역 예정자 협상을 복구합니다 [병역계약검수]',()=>{const p=MCT_PLAYER();G.day=KD(12,1);const C=buildCalendar(G.year+1);p.mil={unit:'상무',from:KD(4,1),until:C.open-2};p.newSal=100;G.contract={y:G.year,tid:G.user,ended:[p.id],done:false,neg:{[p.id]:{off:430,ask:500,st:'ok',cur:null,mil:true,milPrev:{st:'open',ns:430,has:true}}}};const r=__rngState();salMilFix();ok(G.contract.neg[p.id].st==='open'&&!G.contract.neg[p.id].mil&&p.newSal===430,'옛 동결 협상 복구 실패');const saved=JSON.stringify(G.contract);salMilFix();ok(JSON.stringify(G.contract)===saved&&__rngState()===r,'옛 동결 복구가 무난수 멱등 아님');});

const mrUI=()=>eval((typeof __milRosterTestUISrc==='function'?__milRosterTestUISrc():__milRosterPlanSrc())+';({planPay,cgCell,milOut})');
const mrFill=(tid,n,ys=false)=>{for(const p of Object.values(G.players))if(p.team===tid){delete p.mil;delete p.joinY;delete p.frehab;p.ys=false;}const L=Object.values(G.players).filter(p=>p.team===tid);for(const p of L.slice(n))p.team=null;while(rosterN(tid)<n){const p=JSON.parse(JSON.stringify(L[0]));p.id=Math.max(...Object.keys(G.players).map(Number))+1;G.players[p.id]=p;}return Object.values(G.players).filter(p=>p.team===tid);};
const mrReturn=(tid,until,ys=false)=>{const q=domestic(G.teams.find(t=>t.id!==tid).id)[0];q.team=tid;q.ys=ys;q.mil={unit:'상무',from:until-548,until};return q;};
T('[검수 11-17 #408] 계획 연봉 합계는 현재와 다음해 복무 지급비율을 반영한다 [병역정원검수]',()=>{fresh();const p=domestic(G.user)[0];for(const q of Object.values(G.players))if(q.team===G.user&&q!==p)q.team=null;p.sal=700;p.faC=true;p.yrs=3;p.mil={unit:'상무',from:dnum(G.year,1,1),until:dnum(G.year+2,1,1)};const U=mrUI();ok(U.planPay(0).fix===0&&U.planPay(1).fix===0,'계획표에 복무연봉 포함');});
T('[검수 11-17 #409] 복무로 계약 연차가 멈추면 장기 연봉표도 FA를 미룬다 [병역정원검수]',()=>{fresh();const p=domestic(G.user)[0];p.faC=true;p.yrs=1;p.sal=700;p.mil={unit:'상무',from:dnum(G.year,1,1),until:dnum(G.year+1,8,1)};const U=mrUI();ok(U.cgCell(p,1,G.year).t==='fix','복무 중 계약을 내년FA로 표시');});
T('[검수 11-17 #410] 강제 입대 예상은 두번째 시즌 7월 공백도 표시한다 [병역정원검수]',()=>{fresh();const p=domestic(G.user)[0];p.age=27;p.foreign=false;p.mil=null;const U=mrUI();ok(U.milOut(p,G.year+1)&&U.milOut(p,G.year+2),'두번째 시즌 공백 누락');});
T('[검수 11-17 #411] 연말 전역 경고는 새해 합류자를 포함한다 [병역정원검수]',()=>{fresh();G.day=dnum(G.year,12,28);mrFill(G.user,67);const p=mrReturn(G.user,dnum(G.year+1,1,3));const q=mrReturn(G.user,dnum(G.year+1,10,1));delete q.mil;q.joinY=G.year+1;G.mail=[];milRetWarn(G.day);ok(G.mail.some(m=>m.subj?.includes('자리 부족')),'새해69명 경고 누락');});
T('[검수 11-17 #412] 복귀 7일전 이후 영입해도 초과 경고를 다시 확인한다 [병역정원검수]',()=>{fresh();G.day=G.cal.open+30;mrFill(G.user,67);mrReturn(G.user,G.day+7);G.mail=[];milRetWarn(G.day);ok(!G.mail.some(m=>m.subj?.includes('자리 부족')),'여유있는 정원 경고');G.day++;const q=domestic(otherT())[0];q.team=G.user;milRetWarn(G.day);ok(G.mail.some(m=>m.subj?.includes('자리 부족')),'후속 영입후 경고 누락');const n=G.mail.length;G.day++;milRetWarn(G.day);ok(G.mail.length===n,'동일 복귀전망 매일 중복통보');});
T('[검수 11-17 #413] 전역 5일전 부임한 구단도 초과 경고를 받는다 [병역정원검수]',()=>{fresh();G.day=G.cal.open+30;const b=otherT();mrFill(b,68);mrReturn(b,G.day+5);switchTeam(b);G.mail=[];milRetWarn(G.day);ok(G.mail.some(m=>m.subj?.includes('자리 부족')),'새구단 임박 복귀 경고 누락');});
T('[검수 11-17 #414] 육성 전역도 정원 경고와 초과 진행 제한에 포함한다 [병역정원검수]',()=>{fresh();G.day=G.cal.open+30;const L=mrFill(G.user,40);for(const p of L.slice(0,15))p.ys=true;const p=mrReturn(G.user,G.day+3,true);G.mail=[];milRetWarn(G.day);ok(G.mail.some(m=>m.subj?.includes('육성')),'육성16명 경고 누락');G.day=p.mil.until;milDaily();ok(ysN(G.user)===16&&String(blocker()).includes('육성'),'육성초과 진행제한 누락');p.team=null;ok(!String(blocker()).includes('육성'),'육성정리후 제한 남음');});
T('[검수 11-17 #415] 복무 육성의 정식전환은 전역일 초과도 막는다 [병역정원검수]',()=>{fresh();G.day=KD(5,10);mrFill(G.user,68);const p=mrReturn(G.user,KD(7,20),true);fromYS(p.id);ok(p.ys,'전역후69명인데 미리 정식전환 허용');const q=Object.values(G.players).find(q=>q.team===G.user&&!q.ys&&!milServing(q));q.team=null;fromYS(p.id);ok(!p.ys,'전역정원68명인데 정식전환 거절');});
T('[검수 11-17 #416] 정원에 기여하지 않는 복무 선수는 정원68명에도 양수한다 [병역정원검수]',()=>{fresh();G.day=G.cal.open+20;mrFill(G.user,68);const p=domestic(otherT())[0],from=p.team;p.team=null;p.mil={unit:'상무',from:G.day-10,until:rosterOpenDay()+100};p.wv={from,end:G.day+3,ok:true,cl:[],c:{sal:MIN_SAL,yrs:1}};const c=wvCapCheck;try{wvCapCheck=()=>null;wvClaim(p.id);}finally{wvCapCheck=c;}ok(p.wv.cl.includes(G.user),'현재/개막0명 기여 복무자 양수 거절');const w=wvWants,o=wvOrder;G.day=p.wv.end;try{wvWants=()=>false;wvOrder=()=>[G.user,from];wvDaily();}finally{wvWants=w;wvOrder=o;}ok(p.team===G.user&&rosterN(G.user)===68,'복무 양수 결정 또는 인원 오류');const q=domestic(from)[0];q.team=null;q.mil={unit:'상무',from:G.day-10,until:rosterOpenDay()-1};q.wv={from,end:G.day+3,ok:true,cl:[],c:{sal:MIN_SAL,yrs:1}};try{wvCapCheck=()=>null;wvClaim(q.id);}finally{wvCapCheck=c;}ok(!q.wv.cl.includes(G.user),'개막전 전역으로69명될 양수는 거절해야함');});

const mtPlayer=()=>{ const p=domestic(G.user).find(p=>!p.isP); p.mil=null;p.age=24;p.injOut=0;p.hold=null;delete p.joinY;return p; };
const mtSeed=()=>{fresh();G.year=2028;G.day=KD(4,10);for(const p of Object.values(G.players)){p.mil=null;if(p.team!==G.user){p.age=24;p.e1=false;p.injOut=0;}}};
T('[검수 11-17 #418] 상무 보충은 지난 시즌 지급 연봉을 바꾸지 않는다 [병역성장검수]',()=>{mtSeed();const L=Object.values(G.players).filter(p=>p.team!=null&&p.team!==G.user),before=L.map(p=>payFrac(p,G.year-1));ok(flSeedSM()>0,'보충 준비');ok(L.every((p,i)=>payFrac(p,G.year-1)===before[i]),'지난해 연봉 소급 변경');});
T('[검수 11-17 #419] 상무 보충 복무일은 확정된 전날 경기와 겹치지 않는다 [병역성장검수]',()=>{mtSeed();flSeedSM();const L=Object.values(G.players).filter(p=>milServing(p));ok(L.length&&L.every(p=>!milOn(p,G.day-1)&&p.mil.from===G.day),'과거 출장일을 복무로 변경');});
T('[검수 11-17 #420] 상무 자동 보충은 합류 전 선수를 제외한다 [병역성장검수]',()=>{mtSeed();for(const p of Object.values(G.players))if(p.team!==G.user)p.joinY=G.year+1;ok(flSeedSM()===0,'미합류 선수가 입대');ok(flPool(FL_SM,G.day).B.length===0,'미합류 선수가 상무 명단에 포함');});
T('[검수 11-17 #421] 원구단 퓨처스 경기는 상무 휴식 순서를 바꾸지 않는다 [병역성장검수]',()=>{fresh();G.day=G.cal.open+1;const B=domestic(G.user).filter(p=>!p.isP).slice(0,12),P=domestic(G.user).filter(p=>p.isP).slice(0,8);for(const p of [...B,...P]){p.mil={unit:'상무',from:G.day-1,until:G.day+500};p.injOut=0;p.fat=0;p.ld=[];p.hist=[];}G.fl={rot:{}};const pool=flPool;try{flPool=()=>({B,P});const rng=__rngState(),side=flSide(FL_SM,G.day),ids=side.start.map(x=>x.id),a=ids.slice().sort().join(',');const target=B.find(p=>ids.includes(p.id));addTo(lineFor(target,G.year,G.user,'퓨처스'),{g:90,pa:300});G.fl.rot={};__seed(rng);const b=flSide(FL_SM,G.day).start.map(x=>x.id).sort().join(',');ok(a===b,'원구단 출장으로 상무 선발 변경');}finally{flPool=pool;for(const id of FL_TMP)delete G.players[id];FL_TMP=[];}});
T('[검수 11-17 #422] 상무 퓨처스 성적도 원구단 월간 리포트에 포함한다 [병역성장검수]',()=>{fresh();const p=mtPlayer();G.day=KD(5,1);p.mil={unit:'상무',from:G.day-10,until:G.day+500};p.hist=[{...ZB,y:G.year,t:G.user,lvl:'퓨처스',g:60,pa:200,ab:180,h:150,bb:20,tb:210}];G.mail=[];futuresReport();ok(G.mail.some(m=>m.body&&m.body.includes(p.name)),'상무 성적 리포트 누락');});
T('[검수 11-17 #423] 현역 복무에는 겨울에 예약한 양의 분기 성장을 지급하지 않는다 [병역성장검수]',()=>{fresh();const p=mtPlayer();G.day=KD(5,1);p.devQ={y:G.year,D:{con:3,pow:-1},w:[.3,.3,.4],i:0};p.mil={unit:'현역',from:G.day-10,until:G.day+500};const con=p.r.con,pow=p.r.pow;devQDaily();ok(p.r.con<=con&&p.r.pow<=pow,'현역 능력이 성장');G.day=p.mil.until;devQApply(p,1);ok(p.r.con<=con,'전역 뒤 복무 중 성장 몫 부활');});
T('[검수 11-17 #424] 원구단 개인 캠프 보너스는 상무에 적용하지 않는다 [병역성장검수]',()=>{fresh();const p=mtPlayer();p.mil={unit:'상무',from:G.day-1,until:G.day+500};delete p.form;const a=boostOf(p);p.form={b:3,until:G.day+100};ok(boostOf(p)===a,'복무 중 원구단 캠프 보너스');});
T('[검수 11-17 #425] 입대 예약 취소는 신청 마감 뒤에도 기존 연수 예약을 복원한다 [병역성장검수]',()=>{fresh();const p=mtPlayer();G.day=KD(11,9);G.ovs=[];G.spend.dev=0;ok(!setOvs(p.id,'abl'),'연수 준비');ok(!enlistNow(p.id),'입대 준비');const reservation=p.mil;ok(!G.ovs.length,'자동 취소 준비');G.day=KD(11,11);ok(!ovsOpen('abl'),'마감 준비');ok(!enlistCancel(p.id),'입대 취소');ok(G.ovs.some(x=>x.pid===p.id&&x.prog==='abl')&&G.spend.dev===OVS.abl.c,'기존 연수 복원 실패');ovsEnlBack(p,reservation);ok(G.ovs.length===1&&G.spend.dev===OVS.abl.c,'예약 또는 비용 중복 복원');G.day=KD(11,15);tabDaily(G.day);ok(G.ovs[0].go&&G.spend.dev===OVS.abl.c+OVS.abl.fix,'복원 후 출국 기간 또는 비용 오류');G.ovs=[];G.spend.dev=0;G.day=KD(11,30);setOvs(p.id,'us');enlistNow(p.id);const m=p.mil;G.day=KD(12,1);enlistCancel(p.id);ok(G.ovs.length===1&&ovsAbroad(p)&&G.ovs[0].goD===G.day,'미국 마감 다음날 출국당일 합류 실패');ok(G.spend.dev===OVS.us.c+OVS.us.fix,'미국 복원 비용 오류');ovsEnlBack(p,m);tabDaily(G.day);ok(G.spend.dev===OVS.us.c+OVS.us.fix,'출국당일 동행비 중복');enlistNow(p.id);enlistCancel(p.id);ok(G.ovs.length===1&&ovsAbroad(p)&&G.spend.dev===OVS.us.c+OVS.us.fix,'재예약·재취소로 연수 또는 비용 중복');});
T('[검수 11-17 #426] 해외 체류 중 입대하면 즉시 귀국하고 미진행 비용을 정리한다 [병역성장검수]',()=>{fresh();const p=mtPlayer();G.day=KD(11,30);G.ovs=[];G.spend.dev=0;setOvs(p.id,'us');G.day=KD(12,1);tabDaily(G.day);ok(ovsAbroad(p),'출국 준비');enlistNow(p.id);G.day=p.mil.from;milDaily();ok(!ovsAbroad(p),'복무와 해외 체류 동시 유지');const total=OVS.us.c+OVS.us.fix,elapsed=(G.day-KD(12,1))/(dnum(G.year+1,1,5)-KD(12,1));ok(Math.abs(G.spend.dev-total*elapsed)<.02,'미진행 연수비 정산 오류 또는 진행 비용 환급');const cost=G.spend.dev;ovsEnlCheck(p);ok(G.spend.dev===cost,'귀국 비용 중복 환급');});
T('[검수 11-17 #427] 상무 지원자 연수 자격은 개별과 일괄 신청이 같다 [병역성장검수]',()=>{fresh();const p=mtPlayer();G.day=KD(9,10);p.mil={app:'dec'};ok(!!setOvs(p.id,'us'),'개별 신청이 상무 지원을 허용');ok(!ovsBulkView('us').rows.some(x=>x.id===p.id),'일괄 신청이 상무 지원을 허용');});
T('[검수 11-17 #428] 취소된 예약 이력은 실제 입대로 기록하지 않는다 [병역성장검수]',()=>{fresh();const p=mtPlayer();p.story=[];enlistNow(p.id);enlistCancel(p.id);const s=JSON.stringify(p.story);ok(s.includes('입대 예정')&&!s.includes('현역 입대 ('),'예약을 실제 입대로 기록');});
T('[검수 11-17 #429] 전역일이 지난 옛 저장은 군필 표시와 일일 정리가 일치한다 [병역성장검수]',()=>{fresh();const p=mtPlayer();p.mil={unit:'현역',from:G.day-550,until:G.day-2};const rng=__rngState();ok(milText(p)==='군필'&&milState(p).k==='done','병역 화면 불일치');milDaily();ok(p.mil.done&&p.mil.pu===G.day-2,'경과 전역 미정리');const n=JSON.stringify(p.mil);milDaily();ok(JSON.stringify(p.mil)===n&&__rngState()===rng,'경과 전역 정리 비멱등 또는 난수');});

T('[검수 11-17 #376] 세부조건 경쟁 요구액도 무효 제안을 제외합니다 [FA협상검수]',()=>{const p=FAN_FA(),b=otherT(),before=faWantA(p),T=FAN_T(p,1.03);FAN_FULL(b);G.fa.ai[p.id]={[b]:{annual:9999,years:4}};ok(faWantA(p)===before,'무효 경쟁 입찰이 세부조건 요구액을 인상');const P=faPreview(p.id,{terms:T});ok(P&&P.st==='ok','무효 경쟁 입찰이 세부조건 미리보기를 변경');const r=faNegotiate(p.id,{terms:T});ok(r.st==='wait','무효 경쟁 입찰이 세부조건 협상을 거절: '+r.st);});

T('[검수 11-17 #322 화면] 실시간 한 명 진행도 후보 소진 시 모든 잔여 순번을 건너뜀으로 마친다',()=>{const L=revPool().slice(0,1);revLive(L,[revPick(G.user),revPick(otherT()),revPick(G.user,2)]);doPick(L[0].id);amStep();ok(G.draft.done&&G.draft.cur===G.draft.picks.length&&G.draft.picks.slice(1).every(k=>k.pass&&k.pid===-1),'실시간 진행에서 잔여 지명이 빈칸');});

