/* contract-786-tests.txt */
const contract786Case=(ai=false)=>{ fresh(); G.day=KD(6,1); G.rolled=G.year-1; G.last=null; const tid=ai?otherT():G.user; const p=domestic(tid).find(q=>!q.isP&&isRegular(q)&&!milServing(q)&&!q.prospect); ok(p,'준비: 건강한 주전 야수'); for(const q of Object.values(G.players)){ if(q.team===tid){ delete q.opt; delete q.extNext; } } G.sea.optPd={}; p.ctT=tid; delete p.joinY; delete p.mil; return {p,tid,y:G.year}; };
T('[검수 11-18 #786] 시즌 중 합의한 규정타석 타율 옵션이 실제 다음 계약에도 그대로 적용된다 [계약옵션검수]',()=>{ const {p,y}=contract786Case(); for(const q of domestic(G.user))q.sal=MIN_SAL; p.age=27;p.faC=false;p.ext=false;p.yrs=1;delete p.extNext;delete p.ys;delete p.hold;const T0={annual:3000,years:4,bonus:0,opt:130,optC:'avg',role:null}; const r=offerExtension(p.id,T0.annual,T0.years,false,T0);ok(r.ok&&p.extNext,'준비: 실제 시즌 중 합의 '+JSON.stringify(r));ok(T0.optC==='avg'&&p.extNext.terms.optC==='avg','선택한 타율 기준을 덮어씀 '+JSON.stringify(p.extNext)); const copy=JSON.parse(JSON.stringify(p.extNext));p.extNext=copy;extNextApply(p,y+1);ok(p.opt.c==='avg'&&p.opt.a===130&&p.opt.from===y+1,'적용 후 계약 조건 변경'); G.year=y+1;G.day=dnum(G.year,9,25);G.sea.rec[p.team]={w:72,l:72,t:0};p.hist=[Object.assign({y:G.year,t:p.team,lvl:'1군'},ZB,{g:144,pa:500,ab:450,h:125})];ok(!optEarned(p),'타율 3할 미달인데 400타석만으로 옵션 지급');p.hist[0].h=135;ok(optEarned(p),'규정타석 3할 달성 옵션 미지급'); });
T('[검수 11-18 #787] 계약 시작 전 옵션은 올해 전망에서 제외하고 시작 연도부터 계산한다 [계약옵션검수]',()=>{ const {p,tid,y}=contract786Case();termsApply(p,{years:2,annual:p.sal,opt:230,optC:'b'},'fa',y+1,true);p.hist=[Object.assign({y,t:tid,lvl:'1군'},ZB,{g:120,pa:420,ab:380,h:120})];G.sea.rec[tid]={w:60,l:60,t:0};ok(!optEarned(p),'준비: 시작 전 지급');ok(optProj(tid,y)===0,'시작 전 옵션이 올해 전망에 포함');ok(optProj(tid,y+1)===230,'시작 시즌 전망 누락');ok(optProj(tid,y+3)===0,'만료 후 전망 포함'); });
T('[검수 11-18 #788] 옵션 없는 확정 연장은 옛 옵션을 미래 예산에서 즉시 대체한다 [계약옵션검수]',()=>{ const {p,tid,y}=contract786Case();termsApply(p,{years:3,annual:p.sal,opt:230,optC:'b'},'fa',y,true); for(const terms of [{annual:700,years:2,opt:0,bonus:0},null]){p.extNext={annual:700,years:2,...(terms?{terms}:{})};ok(optProj(tid,y+1)===0,'무옵션 다음 계약에도 옛 옵션 잔류'); }ok(optProj(tid,y)===230,'올해 유효한 옛 옵션까지 제거');extNextApply(p,y+1);ok(optProj(tid,y+1)===0&&!p.opt,'적용 전후 무옵션 전망 불일치'); });
T('[검수 11-18 #789] 골든글러브 옵션 전망은 계약 적용 전후 모두 수상 대기다 [계약옵션검수]',()=>{ const {p,tid,y}=contract786Case();p.extNext={annual:700,years:3,terms:{annual:700,years:3,opt:230,optC:'gg',bonus:0}};const a=optProj(tid,y+1);ok(a===0,'대기 중 골든글러브 옵션을 주전이라 전액 예상');extNextApply(p,y+1);const b=optProj(tid,y+1);ok(a===b&&b===0&&p.opt.c==='gg','적용 전후 수상 기준 분기 변경');G.year=y+1;G.day=dnum(G.year,12,15);const t=team(tid),due=t.optDue||0;optAward(p,y+1);optAward(p,y+1);ok(t.optDue===due+230,'실제 수상 옵션이 한 번 지급 장부에 반영되지 않음'); });
T('[검수 11-18 계약 옵션] 사용자와 AI의 미래 계약은 같은 종류별 전망과 기간을 사용한다 [계약옵션검수]',()=>{ for(const ai of [false,true]){const {p,tid,y}=contract786Case(ai);for(const c of ['b','bg','avg','ops','gg','as']){p.extNext={annual:700,years:2,terms:{annual:700,years:2,opt:230,optC:c,bonus:0}};const a=optProj(tid,y+1);ok(a===(c==='b'||c==='bg'?230:0),'종류별 미래 전망 '+c+'/'+a);ok(optProj(tid,y+3)===0,'미래 계약기간 밖 전망 '+c);extNextApply(p,y+1);ok(optProj(tid,y+1)===a,'사용자/AI 적용 전후 전망 '+ai+'/'+c);}} });
T('[검수 11-18 계약 옵션] 구형 기준 없는 계약과 이미 지급한 옵션은 무난수 반복 조회에도 보존된다 [계약옵션검수]',()=>{const {p,tid,y}=contract786Case();p.opt={a:230,until:y+2};const r=__rngState(),saved=JSON.stringify(G);ok(optProj(tid,y+1)===230&&optProj(tid,y+1)===230,'구형 옵션 기본 기준 소실');ok(__rngState()===r&&JSON.stringify(G)===saved,'옵션 전망이 저장 또는 난수 변경');p.extNext={annual:700,years:2,terms:{annual:700,years:2,opt:150}};const r2=__rngState(),s2=JSON.stringify(G);ok(optProj(tid,y+1)===150&&optProj(tid,y+1)===150,'구형 다음 계약 기본 기준 소실');ok(__rngState()===r2&&JSON.stringify(G)===s2,'다음 옵션 조회가 저장 또는 난수 변경');delete p.extNext;p.opt.paidY=y;ok(optProj(tid,y)===0,'이미 지급한 현재 옵션 재계상');G.sea.optPd[tid]=230;ok(optProj(tid,y)===230,'선지급 장부가 전망에서 소실');});

/* trade-value-792-tests.txt */
function v792(fn){fresh();const U=G.user,V=otherT(),P=domestic(U).filter(p=>!p.isP).slice(0,3),Q=domestic(V).filter(p=>!p.isP).sort((a,b)=>ovr(a)-ovr(b)).slice(0,3),S={aiInterest,teamCtx,leagueSlots,startersOf,tvCore6,tval,tradeNeed,aiCapTake,capInfo,capPayAs,domTradeTax,planOf,projO,seasonWorth,seenDelta,slotGain,slotBase};const L=G.teams.map(()=>Object.fromEntries(PSLOTS.map(k=>[k,{ps:[],v:80}]))),R=new Set(),seen={};for(const p of [...P,...Q]){p.age=30;p.pot=40;p.pos='SS';p.isP=false;p.pexp={};p._vv=1;delete p.aiListed;delete p.aiUrg;delete p.aiLd;}let sd=0;try{aiInterest=()=>[];teamCtx=()=>({contend:false,money:1,H:2,now:1});leagueSlots=()=>L;startersOf=()=>R;tvCore6=()=>new Set();tval=(t,p,dir)=>{if(!p)return 0;const f=roleFactor(t,p,dir);if(dir==='in'&&seen[p.id]==null)seen[p.id]=f;return p._vv;};tradeNeed=()=>0;aiCapTake=()=>null;capInfo=()=>({pay:0});capPayAs=()=>0;domTradeTax=()=>({k:sd,refuse:false});planOf=()=>null;projO=()=>0;seasonWorth=()=>0;seenDelta=()=>0;G.cfg={...(G.cfg||{}),hard:false};slotGain=(k,p)=>p._sv?.[k]??40;slotBase=(tid,k)=>L[tid][k].v;return fn({U,V,P,Q,L,R,seen,dom:k=>sd=k});}finally{({aiInterest,teamCtx,leagueSlots,startersOf,tvCore6,tval,tradeNeed,aiCapTake,capInfo,capPayAs,domTradeTax,planOf,projO,seasonWorth,seenDelta,slotGain,slotBase}=S);}}
T('[검수 11-18 #792] 값0.6 매물은 묶인 일반선수10의 가격과 최소마진을 없애지 않는다 [트레이드가치검수]',()=>v792(({V,P,Q,R})=>{R.add(Q[1].id);P[0]._vv=10.1;Q[0]._vv=.6;Q[1]._vv=10;const a=evalTrade(V,[P[0].id],[Q[0].id,Q[1].id]);Q[0].aiListed=true;const b=evalTrade(V,[P[0].id],[Q[0].id,Q[1].id]);ok(!a.ok&&!b.ok,'싼 매물 표시가 일반선수까지 헐값으로 수락 '+JSON.stringify([a,b]));ok(b.need>=.3-1e-9,'일반10 가치의 최소3%가 사라짐 '+b.need); }));
T('[검수 11-18 #793] 급매9를 일반4에 더해도 독주 웃돈은 일반4의0.8만이다 [트레이드가치검수]',()=>v792(({V,P,Q,R,dom})=>{R.add(Q[0].id);P[0]._vv=20;Q[0]._vv=4;Q[1]._vv=9;Q[1].aiListed=true;Q[1].aiUrg=true;Q[1].aiLd=G.day;dom(.2);const a=evalTrade(V,[P[0].id],[Q[0].id]),b=evalTrade(V,[P[0].id],[Q[0].id,Q[1].id]);ok(Math.abs(a.parts.domV-.8)<1e-9&&Math.abs(b.parts.domV-.8)<1e-9,'급매에 독주 웃돈 '+a.parts.domV+'/'+b.parts.domV); }));
T('[검수 11-18 #794] 유격수의 실제 가능한 보조2루 보강도 주전교환 할인에 포함한다 [트레이드가치검수]',()=>v792(({V,P,Q,L,R})=>{R.add(Q[0].id);L[V].SS.ps=[Q[0]];P[0].pos='SS';P[0].pexp={'2B':90};P[0]._sv={'2B':106.4,SS:40};const e=evalTrade(V,[P[0].id],[Q[0].id]);ok(e.parts.fit,'보조2루26.4 보강 누락 '+JSON.stringify(e.parts)); }));
T('[검수 11-18 #795] 실제2루 주전을 내주고2루를 받으면 다른자리 보강할인이 아니다 [트레이드가치검수]',()=>v792(({V,P,Q,L,R})=>{Q[0].pos='3B';L[V]['2B'].ps=[Q[0]];R.add(Q[0].id);P[0].pos='2B';P[0]._sv={'2B':100};const e=evalTrade(V,[P[0].id],[Q[0].id]);ok(!e.parts.fit,'실제 나가는2루를 다른자리로 판정 '+JSON.stringify(e.parts)); }));
T('[검수 11-18 #796] 백업 한자리 교환은 같은자리 영입 둘중 한명에게만0.90을 배정한다 [트레이드가치검수]',()=>v792(({V,P,Q,seen})=>{const a=P[0],b=P[1];evalTrade(V,[a.id,b.id],[Q[0].id]);const first=[seen[a.id],seen[b.id]].sort();ok(first[0]===.6&&first[1]===.9,'한자리로 두선수 보너스 '+first);delete seen[a.id];delete seen[b.id];evalTrade(V,[b.id,a.id],[Q[0].id]);ok([seen[a.id],seen[b.id]].sort().join()===first.join(),'제시 순서가 자리수를 바꿈'); }));
T('[검수 11-18 #794~796 자리계획] 보조포지션 둘도 빠지는 한자리만 채우고 반복 조회가 저장·주난수를 바꾸지 않는다 [트레이드가치검수]',()=>v792(({V,P,Q,L,R})=>{Q[0].pos='3B';L[V]['2B'].ps=[Q[0]];R.add(Q[0].id);P[0].pos='SS';P[0].pexp={'2B':90};P[1].pos='SS';P[1].pexp={'2B':80};delete P[2].pexp;const raw=JSON.stringify(G),rng=__rngState();tradeSlotsOf(P[2]);const t=team(V),a=tradeRolePlan(t,[P[0].id,P[1].id],[Q[0].id],false),b=tradeRolePlan(t,[P[1].id,P[0].id],[Q[0].id],false);ok([...a.values()].sort().join()===[.6,1.05].join(),'주전 한자리 동시배정 '+JSON.stringify([...a]));ok(JSON.stringify([...a])===JSON.stringify([...b]),'제시순서에 따라 자리계획 변경');evalTrade(V,[P[0].id,P[1].id],[Q[0].id]);evalTrade(V,[P[1].id,P[0].id],[Q[0].id]);ok(JSON.stringify(G)===raw&&__rngState()===rng,'자리계획/평가 조회가 저장·난수 변경'); }));
T('[검수 11-18 공통평가 관심선수] 명시한 거래 주체의 관심선수와 AI 재영입 제외도 같은 식을 쓴다 [트레이드가치검수]',()=>{fresh();const A=G.teams.find(t=>t.id!==G.user),B=G.teams.find(t=>t.id!==G.user&&t.id!==A.id);const x=aiInterest(B.id,A.id),u=aiInterest(B.id);ok(x.length&&x.every(id=>G.players[id].team===A.id),'명시한 AI주체 대신 사용자선수를 관심목록에 사용 '+JSON.stringify(x));ok(u.every(id=>G.players[id].team===G.user),'기본 사용자 관심목록이 AI로 오염');const id=x[0];G.lgTrades=[{y:G.year,d:G.day,a:A.id,b:B.id,ag:[id],bg:[]}];ok(!aiInterest(B.id,A.id).includes(id),'AI가 올해 보낸 선수를 다시 관심후보로 삼음');const raw=JSON.stringify(G),rng=__rngState();aiInterest(B.id,A.id);aiInterest(B.id);ok(JSON.stringify(G)===raw&&__rngState()===rng,'관심조회가 저장/난수 변경');});

/* trade-guard-790-tests.txt */
const guardTradeFixture=()=>{ fresh(); G.day=G.cal.open+10; G.trades=[]; G.lgTrades=[]; G.last=null; G.ps=null; const t=G.teams.find(x=>x.id!==G.user), give=domestic(G.user).filter(p=>!p.foreign&&!p.ys&&!hasNtc(p)&&!recentTr(p)).slice(0,3), get=domestic(t.id).filter(p=>!p.foreign&&!p.ys&&!hasNtc(p)&&!recentTr(p)).slice(0,3); ok(give.length===3&&get.length===3,'준비: 거래 선수 부족'); return {t,give,get}; };
T('[검수 11-18 #790] 저장된 역제안도 현재 독주 주전 거래 금지를 우회하지 않는다 [거래안전검수]',()=>{ const {t,give,get}=guardTradeFixture(), g=[give[0].id], q=[get[0].id], n=negTurn(t.id), sig=tsig(g,q,0)+pkSig(); n.ctr={[sig]:G.day}; const ev=evalTrade, oc=tradeOwnerCheck,cc=tradeCapCheck,co=counterOffer; const before=[give[0].team,get[0].team]; try{ evalTrade=()=>({ok:false,gain:10,need:10,outV:4,theirN:rosterN(t.id),dom:{k:.2,v:.8,refuse:true},parts:{}}); tradeOwnerCheck=()=>null;tradeCapCheck=()=>null;counterOffer=()=>[]; const r=proposeTrade(t.id,g,q); ok(!r.ok,'유효 역제안이 현재 금지된 주전 거래를 체결'); ok(give[0].team===before[0]&&get[0].team===before[1],'금지 거래로 선수 이동'); }finally{evalTrade=ev;tradeOwnerCheck=oc;tradeCapCheck=cc;counterOffer=co;} });
T('[검수 11-18 #791] 거래 조회는 독주 견제 통계와 저장 및 주 난수를 변경하지 않는다 [거래안전검수]',()=>{const {t,give,get}=guardTradeFixture(); const dt=domTradeTax,tv=tval; try{ domTradeTax=()=>({k:.2,refuse:true}); tval=(t,p,dir)=>dir==='in'?1000:1; const before=JSON.stringify(G),seed=__rngState(); const e=evalTrade(t.id,[give[0].id],[get[0].id]); ok(e.dom&&e.dom.refuse&&!e.ok,'준비: 독주 거절 분기 미진입'); evalTrade(t.id,[give[0].id],[get[0].id]); ok(JSON.stringify(G)===before,'조회만으로 저장 또는 견제 통계 변경 '+Object.keys(G).filter(k=>JSON.stringify(G[k])!==JSON.stringify(JSON.parse(before)[k])).join(',')+' '+Object.values(G.players).filter(p=>JSON.stringify(p)!==JSON.stringify(JSON.parse(before).players[p.id])).slice(0,3).map(p=>p.id+':'+Object.keys(p).filter(k=>JSON.stringify(p[k])!==JSON.stringify(JSON.parse(before).players[p.id][k])).join('/')).join(',')); ok(__rngState()===seed,'조회가 주 난수 변경'); }finally{domTradeTax=dt;tval=tv;} });
T('[검수 11-18 #801] 같은 상대의 새 역제안은 아직 유효한 다른 선수 안을 지우지 않는다 [거래안전검수]',()=>{const {t,give,get}=guardTradeFixture(),ev=evalTrade,oc=tradeOwnerCheck,cc=tradeCapCheck,co=counterOffer;try{evalTrade=()=>({ok:false,gain:0,need:1,outV:2,theirN:rosterN(t.id),parts:{}});tradeOwnerCheck=()=>null;tradeCapCheck=()=>null;counterOffer=(tid,g,q,c,pk)=>[{give:[...g],get:[...q],cash:100,pk:pkNorm(pk)}];const r1=proposeTrade(t.id,[give[0].id],[get[0].id]),s1=tsig([give[0].id],[get[0].id],100)+pkSig();ok(r1.counters&&r1.counters.length,'준비: 첫 역제안 없음');const r2=proposeTrade(t.id,[give[1].id],[get[1].id]),s2=tsig([give[1].id],[get[1].id],100)+pkSig();ok(r2.counters&&r2.counters.length,'준비: 둘째 역제안 없음');const n=negTurn(t.id);ok(n.ctr[s1]===G.day&&n.ctr[s2]===G.day,'새 역제안이 첫 안의7일 유효기록 삭제');G.day+=8; const r3=proposeTrade(t.id,[give[2].id],[get[2].id]);ok(r3.counters,'준비: 만료뒤 역제안 없음');ok(!Object.hasOwn(negTurn(t.id).ctr,s1)&&!Object.hasOwn(negTurn(t.id).ctr,s2),'만료 역제안 미정리');}finally{evalTrade=ev;tradeOwnerCheck=oc;tradeCapCheck=cc;counterOffer=co;} });
T('[검수 11-18 #802] 같은 날짜 다른 저장의 부상 라인업으로 트레이드 주전을 다시 고른다 [거래안전검수]',()=>{fresh();const tid=otherT(),a=[...startersOf(tid)],pid=a.find(id=>!G.players[id].isP);ok(pid,'준비: 야수 주전 없음');const seed=__rngState();G=JSON.parse(JSON.stringify(G));G.players[pid].injOut=90;const d=depth(tid);ok(!d.start.some(p=>p.id===pid),'준비: 실제 부상선수가 여전히 주전');const before=JSON.stringify(G);ok(!startersOf(tid).has(pid),'이전 저장 주전 캐시 재사용');ok(JSON.stringify(G)===before&&__rngState()===seed,'주전 조회가 저장 또는 주 난수 변경');});
T('[검수 11-18 #802 당일] 같은 저장 당일 부상과 라인업 수정도 주전 평가에 반영한다 [거래안전검수]',()=>{fresh();const tid=otherT(),pid=[...startersOf(tid)].find(id=>!G.players[id].isP);ok(pid,'준비');G.players[pid].injOut=90;ok(!startersOf(tid).has(pid),'당일 부상 전 주전캐시 재사용');G.players[pid].injOut=0;ok(depth(tid).start.some(p=>p.id===pid),'준비: 건강회복뒤 실제주전아님');ok(startersOf(tid).has(pid),'당일 건강회복전 캐시 재사용');});
T('[검수 11-18 #803] 다른 저장에서 합의한 연장은 이전 FA 거래 잠금을 물려받지 않는다 [거래안전검수]',()=>{fresh();G.last={y:G.year};const p=domestic(otherT()).find(p=>!p.foreign&&!p.ys);p.svc=faSvc(p);p.faC=true;p.yrs=1;p.ext=false;p.hist=p.hist||[];p.age=28;delete p.extNext;delete p.lastFA;delete p.faTrY;delete p.mil;_faLk={k:null,s:null};ok(faLock(p),'준비: 첫 저장 FA만료 잠금 없음');G=JSON.parse(JSON.stringify(G));const q=G.players[p.id];q.extNext={annual:130,years:3};ok(!faUpcoming(q).length,'준비: 새 저장 연장이 FA명단에 남음');const before=JSON.stringify(G),seed=__rngState();ok(!faLock(q),'이전 저장 FA잠금 재사용');ok(JSON.stringify(G)===before&&__rngState()===seed,'FA조회가 저장/주난수 변경');});
T('[검수 11-18 #803 당일] 같은 저장에서 합의한 다년연장도 즉시 FA 거래 잠금에서 뺀다 [거래안전검수]',()=>{fresh();G.last={y:G.year};const p=domestic(otherT()).find(p=>!p.foreign&&!p.ys);p.svc=faSvc(p);p.faC=true;p.yrs=1;p.ext=false;p.age=28;delete p.extNext;delete p.lastFA;delete p.faTrY;delete p.mil;_faLk={k:null,s:null};ok(faLock(p),'준비: 계약만료잠금없음');p.extNext={annual:130,years:3};ok(!faLock(p),'연장 합의뒤 당일FA잠금 유지');});
T('[검수 11-18 #791 수비 조회] 옛 선수의 파생 숙련·다재다능 조회는 읽기 전용이며 실제 훈련은 저장한다 [거래안전검수]',()=>{fresh();const p=domestic(G.user).find(p=>!p.isP),seed=__rngState();delete p.pexp;delete p.vers;const before=JSON.stringify(p),e=JSON.stringify(pexpOf(p)),v=versOf(p);ok(JSON.stringify(p)===before,'숙련/다재다능 조회가 저장 변경');ok(JSON.stringify(pexpOf(p))===e&&versOf(p)===v&&__rngState()===seed,'반복조회 값/주난수 변화');const pos=POS_F.find(k=>k!==p.pos),pre=posExp(p,pos);posGain(p,pos,10);ok(p.pexp&&p.pexp[pos]>pre,'읽기전용 변경으로 실제 숙련 훈련 누락');const saved=JSON.stringify(p.pexp);G=JSON.parse(JSON.stringify(G));ok(JSON.stringify(pexpOf(G.players[p.id]))===saved,'훈련 숙련 JSON복원 소실');});
T('[검수 11-18 #791 제출] 견제 집계는 실제 거절만 세며 다른 저장의 당일 집계를 막지 않는다 [거래안전검수]',()=>{const {t,give,get}=guardTradeFixture(),ev=evalTrade,oc=tradeOwnerCheck,cc=tradeCapCheck,co=counterOffer;try{evalTrade=()=>({ok:false,gain:10,need:10,outV:4,theirN:rosterN(t.id),dom:{k:.2,v:.8,refuse:true},parts:{}});tradeOwnerCheck=()=>null;tradeCapCheck=()=>null;counterOffer=()=>[];delete G.domLog;const r=proposeTrade(t.id,[give[0].id],[get[0].id]);ok(!r.ok&&G.domLog[G.year].ref===1,'실제 견제거절 집계 누락');const y=G.year,d=G.day,key=G.user+':'+t.id+':'+get[0].id;domLog('ref',key);ok(G.domLog[y].ref===1,'같은 저장 당일 동일거절 중복집계');G=JSON.parse(JSON.stringify(G));G.day=d;G.domLog={};domLog('ref',key);ok(G.domLog[y].ref===1,'다른 저장의 당일 집계가 이전 중복캐시에 막힘');}finally{evalTrade=ev;tradeOwnerCheck=oc;tradeCapCheck=cc;counterOffer=co;}});

/* trade-recommend-797-tests.txt */
const recCashCase=(start,target,cap,run)=>{ fresh(); const tid=otherT(),give=[domestic(G.user)[0].id],get=[domestic(tid)[0].id],T=team(tid); const old={evalTrade,tradeCtrOk,tradeAddable,pkHeld,pkHeldF,planOf,gmTrait,teamCtx}; let calls=0,checks=0; try{ teamCtx=()=>({money:1}); tradeAddable=()=>false; pkHeld=()=>[]; pkHeldF=()=>[]; /* 0e98bef0(미래 지명권)부터 역제안 지명권 후보는 pkHeldF로 고른다 */ planOf=()=>''; gmTrait=()=>null; const value=c=>cashVal(T,c)-cashCost(T,c); evalTrade=(_t,_g,_o,c)=>(calls++,{need:0,gain:value(c)-value(target),outV:cap/.22,cashV:cashVal(T,c),cashCap:cap,theirN:50,ok:value(c)>=value(target)}); tradeCtrOk=(_t,c)=>(checks++,c.give.join()===give.join()&&c.get.join()===get.join()&&evalTrade(tid,c.give,c.get,c.cash).ok); const before=JSON.stringify(G),rng=__rngState(); const L=counterOffer(tid,give,get,start);run(L,{tid,give,get,before,after:JSON.stringify(G),rng,rngAfter:__rngState(),calls,checks}); }finally{ evalTrade=old.evalTrade;tradeCtrOk=old.tradeCtrOk;tradeAddable=old.tradeAddable;pkHeld=old.pkHeld;pkHeldF=old.pkHeldF;planOf=old.planOf;gmTrait=old.gmTrait;teamCtx=old.teamCtx; } };
T('[추천역제안검수] [검수 11-18 #797] 6억을 얹은 안의 역제안은 누진 현금 가치로 실제 성사되는 8억을 찾는다',()=>recCashCase(600,800,20,L=>{ const c=L.find(x=>x.cash===800); ok(c,'6억 이후 35% 환율의 현금 역제안 누락'); }));
T('[추천역제안검수] [검수 11-18 #798] 받을 현금을 줄이는 역제안은 양의 현금 한도와 별도로 찾는다',()=>recCashCase(-450,-250,.66,L=>{ const c=L.find(x=>x.cash===-250); ok(c,'받을 현금 4.5억→2.5억 안 누락'); }));
T('[추천역제안검수] [검수 11-18 #797 경계] 첫 5억과 15억 경계를 넘는 현금 역제안도 최소 성사 금액을 찾는다',()=>{ for(const [a,b] of [[450,650],[1450,1700]])recCashCase(a,b,30,L=>ok(L.some(x=>x.cash===b),'누진 경계 역제안 누락 '+a+'→'+b)); });
T('[추천역제안검수] [검수 11-18 #798 경계] 받을 현금을 전부 포기하는 역제안도 찾는다',()=>recCashCase(-450,0,20,L=>ok(L.some(x=>x.cash===0),'받을 현금 전액 포기 역제안 누락')));
const recPackageCase=run=>{ fresh(); const tid=otherT(),p=domestic(tid)[0],q=domestic(G.user)[0],core=new Set(domestic(G.user).filter(x=>x.id!==q.id).map(x=>x.id)); const old={tval,tradeNeed,evalTrade,tradeCtrOk,faLock,recentTr}; try{ tval=(_t,x)=>x.id===p.id?.4:x.id===q.id?1:0; tradeNeed=()=>1.5; evalTrade=()=>({ok:true,theirN:50,need:.3,inV:1,outV:.4}); tradeCtrOk=()=>true;faLock=()=>false;recentTr=()=>false; q.ys=false;q.injOut=0;q.susp=0;delete q.joinY;delete q.ntc;delete q.hold;delete q.fLeave;delete q.frehab;delete p.ntc;run({tid,p,q,core}); }finally{ tval=old.tval;tradeNeed=old.tradeNeed;evalTrade=old.evalTrade;tradeCtrOk=old.tradeCtrOk;faLock=old.faLock;recentTr=old.recentTr; } };
T('[추천역제안검수] [검수 11-18 #799] 추천 조합은 옛 기본 요구치로 실제 수락 가능한 비주전 맞교환을 버리지 않는다',()=>recPackageCase(({tid,p,q,core})=>{ const L=buildPackage(team(tid),p,core);ok(L&&L.length===1&&L[0]===q.id,'실제 수락 1.0 대0.4 추천 누락'); }));
T('[추천역제안검수] [검수 11-18 #800 최근] 추천 유효성은 상대 선수의 최근 이적 잠금을 제출과 같이 검사한다',()=>{ fresh();const tid=otherT(),p=domestic(tid)[0],q=domestic(G.user)[0],old={evalTrade,tradeCtrOk,ntcOf,tradeCool,recentTr};try{evalTrade=()=>({ok:true});ntcOf=()=>null;tradeCool=()=>null;recentTr=x=>x.id===p.id;tradeCtrOk=(_t,c)=>!c.get.some(id=>recentTr(G.players[id]));ok(!tsugValid({tid,id:p.id,give:[q.id]}),'최근 이적 상대 추천이 제출 잠금 우회');}finally{evalTrade=old.evalTrade;tradeCtrOk=old.tradeCtrOk;ntcOf=old.ntcOf;tradeCool=old.tradeCool;recentTr=old.recentTr;} });
T('[추천역제안검수] [검수 11-18 #800 FA] 추천 유효성은 FA 계약 뒤 개막 전 잠금을 제출과 같이 검사한다',()=>{ fresh();const tid=otherT(),p=domestic(tid)[0],q=domestic(G.user)[0],old={evalTrade,tradeCtrOk,ntcOf,tradeCool,recentTr};try{evalTrade=()=>({ok:true});ntcOf=()=>null;tradeCool=()=>null;recentTr=()=>false;p.faTrY=G.year;G.day=G.cal.open-1;tradeCtrOk=(_t,c)=>![...c.give,...c.get].some(id=>faSignLock(G.players[id]));ok(!tsugValid({tid,id:p.id,give:[q.id]}),'FA 개막 전 상대 추천이 제출 잠금 우회');}finally{evalTrade=old.evalTrade;tradeCtrOk=old.tradeCtrOk;ntcOf=old.ntcOf;tradeCool=old.tradeCool;recentTr=old.recentTr;} });
T('[추천역제안검수] [검수 11-18 #799 대안] 가장 싼 추천 안이 잠기면 다음 실제 제출 가능한 조합을 찾는다',()=>recPackageCase(({tid,p,q,core})=>{ const r=JSON.parse(JSON.stringify(q));r.id=Math.max(...Object.keys(G.players).map(Number))+1;G.players[r.id]=r;tval=(_t,x)=>x.id===p.id?.4:x.id===q.id?1:1.1;tradeCtrOk=(_t,c)=>c.give.length===1&&c.give[0]===r.id;const L=buildPackage(team(tid),p,core);ok(L&&L.length===1&&L[0]===r.id,'막힌 최저가 다음의 성사안 검색 누락'); }));

T('[추천역제안검수] [검수 11-18 #797 최소] 현금 역제안은 50백만원 격자로 예산 안 최소 성사액을 건너뛰지 않는다',()=>recCashCase(600,801,20,L=>ok(L.some(x=>x.cash===801),'백만원 단위 최소 성사액 누락')));
T('[추천역제안검수] [검수 11-18 #797 순수성] 총액 이분 검색은 저장과 주 난수를 보존하며 경제성 검사를 16회 이하로 제한한다',()=>recCashCase(600,800,20,(L,s)=>{ok(L.length&&s.before===s.after&&s.rng===s.rngAfter,'현금 조회가 저장이나 난수를 변경');ok(s.calls<=16,'현금 탐색 선형 평가 '+s.calls);ok(s.checks<=10,'현금 외 최종 후보 포함 검사 과다 '+s.checks);}));
T('[추천역제안검수] [검수 11-18 #800 실제최근] 최근 이적 선수 추천과 실제 제출은 같은 잠금 사유로 거절한다',()=>{fresh();G.day=G.cal.open+40;const tid=otherT(),p=domestic(tid)[0],q=domestic(G.user)[0];p.trD=G.day-5;const before=JSON.stringify(G),rng=__rngState();ok(!tsugValid({tid,id:p.id,give:[q.id]}),'실제 최근 잠금 추천 통과');const r=proposeTrade(tid,[q.id],[p.id]);ok(!r.ok&&r.msg.includes('최근 트레이드'),'실제 제출 잠금 사유 다름');ok(before===JSON.stringify(G)&&rng===__rngState(),'거절 조회가 저장 난수를 변경');});
T('[추천역제안검수] [검수 11-18 #800 실제FA] FA 계약 선수 추천과 실제 제출은 개막 전 잠금을 함께 적용한다',()=>{fresh();G.day=G.cal.open-1;const tid=otherT(),p=domestic(tid)[0],q=domestic(G.user)[0];p.faTrY=G.year;delete p.trD;delete q.trD;const before=JSON.stringify(G),rng=__rngState();ok(!tsugValid({tid,id:p.id,give:[q.id]}),'실제 FA잠금 추천 통과');const r=proposeTrade(tid,[q.id],[p.id]);ok(!r.ok&&r.msg.includes('FA로 계약'),'실제 제출 FA잠금 사유 다름');ok(before===JSON.stringify(G)&&rng===__rngState(),'FA거절 조회가 저장 난수를 변경');});

T('[추천역제안검수] [검수 11-18 #798 방향] 받을 현금을 포기하고 돈을 얹는 안은 실제 지급할 총액을 안내한다',()=>recCashCase(-450,250,20,L=>{const c=L.find(x=>x.cash===250);ok(c&&c.why.includes(money(250))&&!c.why.includes(money(700)),'받을 돈 포기분을 지급액으로 안내');}));
T('[추천역제안검수] [검수 11-18 #797~798 실제평가] 누진 현금과 감액 역제안은 공통 실제 평가·제출 자격을 통과한다',()=>{for(const [from,to] of [[600,800],[-450,-250]]){fresh();G.day=G.cal.open+40;const tid=otherT(),p=domestic(tid).filter(x=>!x.ys&&!startersOf(tid).has(x.id)&&!tvCore6(tid).has(x.id)).sort((a,b)=>ovr(a)-ovr(b))[0],q=domestic(G.user).find(x=>!x.ys&&!hasNtc(x)&&healthy(x));ok(p&&q,'실제 평가 선수 준비');delete p.ntc;delete p.trD;delete q.trD;p.age=30;delete p.aiListed;delete p.aiUrg;p.sal=q.sal=30;team(tid).cash=5000;team(tid).gm.trait='data';G.gmc[tid]={};G.trades=[];G.lgTrades=[];G.draft={...G.draft,done:false};const old={tval,aiInterest,tradeOwnerCheck,tradeCapCheck};let v=0;try{tval=(_t,x)=>x.id===p.id?30:x.id===q.id?v:0;aiInterest=()=>[];tradeOwnerCheck=()=>null;tradeCapCheck=()=>null;const base=evalTrade(tid,[q.id],[p.id],to);v=base.outV+base.need-base.cashV+1e-7;ok(!evalTrade(tid,[q.id],[p.id],from).ok&&evalTrade(tid,[q.id],[p.id],to).ok,'기존 현금 거절·목표 현금 수락 준비');const L=counterOffer(tid,[q.id],[p.id],from),c=L.find(x=>x.cash===to&&x.give.join()===String(q.id)&&x.get.join()===String(p.id));ok(c,'실제 공통 평가의 현금 역제안 누락 '+from+'→'+to);ok(tradeCtrOk(tid,c),'실제 제출 자격 불일치');}finally{tval=old.tval;aiInterest=old.aiInterest;tradeOwnerCheck=old.tradeOwnerCheck;tradeCapCheck=old.tradeCapCheck;}}});

/* trade-ai-805-tests.txt */
/* 검수 786~809: AI 거래도 실제 전체 묶음의 공통 판정을 따른다. */
function tradeAi805Case(extra){ fresh(); G.day=G.cal.open+30; G.trades=[]; G.gmc={}; const A=G.teams.find(t=>t.id!==G.user), B=G.teams.find(t=>t.id!==G.user&&t.id!==A.id), q=domestic(A.id).filter(p=>!p.isP)[0], p=domestic(B.id).filter(p=>!p.isP)[0], r=domestic(B.id).filter(p=>!p.isP)[1];
  G.lgTrades=G.teams.filter(t=>![A.id,B.id,G.user].includes(t.id)).flatMap(t=>Array.from({length:5},()=>({y:G.year,a:t.id,b:t.id,ag:[],bg:[]})));
  for(const s of Object.values(G.players))if(s.team===A.id||s.team===B.id)s.foreign=true; for(const s of [p,q,...(extra?[r]:[])]){ s.foreign=false; s.isP=false;s.pos='SS';s.sub=[];s.ys=false;s.age=30;delete s.trD;delete s.ntc;delete s.faTrY;delete s.mil;s.injOut=0;s.susp=0;delete s.hold;delete s.frehab;delete s.fLeave;delete s.aiListed;for(const k of Object.keys(s.r||{}))if(typeof s.r[k]==='number')s.r[k]=s===r?80:30;s.pot=30; }
  if(extra){r.aiListed=true;r.aiLd=G.day;} A.mode=B.mode='normal'; const old={}; const patch=(name,fn)=>{old[name]=eval(name);eval(name+'=fn');};
  patch('slotRanks',()=>Object.fromEntries(PSLOTS.map(k=>[k,{rank:k==='SS'?9:1}])));patch('slotBase',()=>30);patch('slotGain',(k,s)=>s===p?60:s===r?35:40);patch('teamCtx',()=>({contend:false,money:1}));patch('gmHeat',()=>0);patch('tval',(t,s,d)=>extra?(s===q?(d==='in'?5.5:1):s===r?4:1):1);patch('domTradeTax',()=>({k:0,refuse:false}));patch('startersOf',tid=>new Set(extra&&tid===B.id?[r.id]:[]));patch('tvCore6',()=>new Set());patch('relTradeRefuse',()=>false);patch('relAsRel',()=>50);patch('tradeNeed',(t,v)=>extra&&v>1?4:0);patch('corePool',tid=>tid===A.id?[q]:[]);patch('aiInterest',()=>[]);patch('capPayAs',()=>0);patch('aiCapTake',()=>null);patch('capInfo',()=>({pay:0,cap:20000,over:0}));patch('planOf',()=> 'normal');patch('seenDelta',()=>0);patch('potSeenD',()=>0);
  return {A,B,p,q,r,restore:()=>{for(const [name,fn]of Object.entries(old))eval(name+'=fn');}};
}
T('[검수 11-18 #805] AI끼리의 1대1 비매물 맞교환도 사용자와 같은 비주전 최소 마진을 적용한다',()=>{const f=tradeAi805Case(false);try{const e=evalTrade(f.B.id,[f.q.id],[f.p.id]);ok(!e.ok&&e.need>=TR_TUNE.midMin&&e.gain===0,'동가 거래 준비가 사용자 최소 마진으로 거절되지 않음');globalThis.__seed(7);const n=G.lgTrades.length;const z=aiTradeTry(f.A.id);ok(!z&&G.lgTrades.length===n&&f.p.team===f.B.id&&f.q.team===f.A.id,'AI 거래가 같은 1:1 값을 최소 마진 없이 수락');}finally{f.restore();}});
T('[검수 11-18 #806] AI의 두 번째 매물에 주전이 섞이면 전체 묶음의 요구치를 다시 평가한다',()=>{const f=tradeAi805Case(true);try{const e=evalTrade(f.B.id,[f.q.id],[f.p.id,f.r.id]);ok(!e.ok&&!e.parts.bench&&e.need>e.gain,'주전 포함 묶음이 실제 공통 가치 판정으로 거절되지 않음');globalThis.__seed(7);aiTradeTry(f.A.id);ok(!(G.lgTrades||[]).some(t=>t.a===f.A.id&&t.b===f.B.id&&t.ag.includes(f.p.id)&&t.ag.includes(f.r.id)),'첫 백업 요구치만으로 주전이 섞인 묶음을 수락');}finally{f.restore();}});
T('[검수 11-18 #807] 마감 소식으로 올린 새 매물은 등록일을 저장하고 6주 뒤에는 부상 여부와 무관하게 만료한다',()=>{fresh();G.day=KD(7,24);const st=standingsNow(),t=st.slice(6).map(x=>x.tid).find(x=>x!==G.user),p=domestic(t).filter(q=>!q.ys&&!hasNtc(q)&&!faLock(q)&&!mvRecent(q)).sort((a,b)=>ovr(b)-ovr(a))[0];ok(p,'마감 매물 후보 없음');p.age=33;for(const k of Object.keys(p.r))if(typeof p.r[k]==='number')p.r[k]=70;delete p.aiListed;delete p.aiLd;delete p.aiWhy;deadlineRumors(true);ok(p.aiListed&&p.aiLd===G.day,'마감 매물에 등록일이 없음');G.day+=122;p.injOut=90;aiBlockWeekly();ok(!p.aiListed&&!p.aiLd&&!p.aiWhy&&!p.aiUrg,'122일 지난 부상 매물이 남음');});
T('[검수 11-18 #807 호환] 날짜 없는 옛 마감 매물과 0일 등록은 불러오기 정리를 반복해도 영구 매물이 되지 않는다',()=>{fresh();G.day=KD(11,23);const p=domestic(otherT())[0],q=domestic(otherT())[1];p.aiListed=true;p.injOut=90;delete p.aiLd;delete p.aiWhy;q.aiListed=true;q.aiWhy='sal';q.aiLd=0;aiBlockWeekly();ok(!p.aiListed&&!q.aiListed,'옛 날짜 없음 또는 0일 매물이 만료되지 않음');const j=JSON.stringify(G),r=globalThis.__rngState();ok(aiBlockDates()===0&&aiBlockDates()===0&&JSON.stringify(G)===j&&globalThis.__rngState()===r,'매물 복원이 멱등·난수 보존을 어김');});
T('[검수 11-18 #808] 맞대결 배너는 실제 협상 잔여 횟수와 소진 뒤 재개일을 안내한다',()=>{fresh();G.day=G.cal.open+30;const b=otherT();G.cal.sched[G.day]=[[G.user,b]];const n=negTurn(b);n.neg=0;const ui=eval(globalThis.__tradeAiUiSrc()),ni=negInfo(b);ok(ni.free&&ni.left>0,'맞대결 협상 준비');for(const small of [false,true]){const h=ui.vsBanner(small);ok(!h.includes('무제한')&&!h.includes('횟수 제한 없이')&&h.includes(ni.left+'/'+ni.cap),'배너가 실제 잔여 횟수를 표시하지 않음');}n.neg=ni.cap;const end=negInfo(b);for(const small of [false,true]){const h=ui.vsBanner(small);ok(end.left===0&&h.includes('모두 사용')&&h.includes(end.next),'소진된 맞대결 배너가 추가 협상을 안내');}});
T('[검수 11-18 #809] 지명권이 없는 AI 거래의 현금도 리그 성적표에 한 번 표시한다',()=>{fresh();const a=otherT(),b=G.teams.find(t=>t.id!==a&&t.id!==G.user).id,p=domestic(a)[0],q=domestic(b)[0];G.trades=[];G.lgTrades=[{y:G.year,d:G.day,a,b,ag:[p.id],bg:[q.id],an:[p.name],bn:[q.name,'현금 '+money(500)],cash:500}];const ui=eval(globalThis.__tradeAiUiSrc()),j=JSON.stringify(G),h=ui.tcReport();ok(h.includes(p.name)&&h.includes(q.name)&&h.includes('현금 '+money(500)),'현금만 얹은 거래에서 현금 누락');ok(ui.lgTradeExtras(G.lgTrades[0]).filter(x=>String(x).includes('현금 ')).length===1,'현금 중복 표시');G.lgTrades[0].bn=[q.name];ok(ui.tcReport().includes('현금 '+money(500)),'명시된 현금의 예전 이름 꼬리가 없으면 누락');G.lgTrades[0].bn.push('현금 '+money(500));ok(JSON.stringify(G)===j,'성적표 조회가 거래 기록을 변경');});
T('[검수 11-18 #805 친분] 같은 높은 친분의 기본 요구치는 사용자·AI 호출에서 같고 최종 최소 마진은 유지한다',()=>{fresh();const t=team(otherT()),a=G.teams.find(x=>x.id!==G.user&&x.id!==t.id),p=domestic(t.id)[0],q=domestic(G.user)[0];t.rel=95;t.gm.trait='loyal';t.gm.ab={eye:60,neg:30,plan:60,money:60};const n=tradeNeed(t,1),n2=tradeNeed(t,1,95);ok(n<0&&n===n2,'같은 친분을 AI에 전달하면 기본 요구치가 0으로 잘림');const old=[tval,aiInterest,domTradeTax,relAsRel];try{tval=()=>1;aiInterest=()=>[];domTradeTax=()=>({k:0,refuse:false});relAsRel=()=>95;delete p.aiListed;G.trades=[];G.lgTrades=[];G.gmc={};const x=evalTrade(t.id,[q.id],[p.id]),y=evalTrade(t.id,[q.id],[p.id],0,undefined,a.id);ok(x.need===y.need&&x.ok===y.ok&&x.need>=Math.max(0,x.outV)*.03,'공통 최종 마진 또는 사용자·AI 동일 친분 판정 불일치');}finally{[tval,aiInterest,domTradeTax,relAsRel]=old;}});
T('[검수 11-18 #805 위임] 운영 방향 보강도 후보의 할인 목표값만으로 공통 최종 판정을 우회하지 않는다',()=>{const f=tradeAi805Case(false),rt=teamRating,cp=capPay;try{G.lgTrades=[];f.A.stance='win';capPay=()=>0;f.p.age=33;f.q.age=25;for(const k of Object.keys(f.p.r))if(typeof f.p.r[k]==='number')f.p.r[k]=70;const extras=Object.values(G.players).filter(p=>p.team===f.A.id&&p.id!==f.q.id).slice(0,7);for(const p of extras){p.foreign=false;p.age=35;for(const k of Object.keys(p.r))if(typeof p.r[k]==='number')p.r[k]=80;}teamRating=tid=>tid===f.A.id&&f.p.team===f.A.id?100:90;tval=(t,p,d)=>p===f.p?10:p===f.q?6:20;const e=evalTrade(f.B.id,[f.q.id],[f.p.id]);ok(!e.ok&&e.gain<e.need,'보강 안이 실제 공통 판정에서 거절되지 않음');const n=G.lgTrades.length,z=fdStrengthen({buyers:[f.A],sellers:[f.B],per:1,wantF:.4});ok(z===0&&G.lgTrades.length===n&&f.p.team===f.B.id,'운영 방침 보강이 공통 가치 판정을 우회');}finally{teamRating=rt;capPay=cp;f.restore();}});

