/* 독립 교차 검수: 실제 저장·평가·제출 경로를 묶어 확인한다. */
const C786_WORLD=()=>{ globalThis.__seed(786802); buildWorld({lite:true}); claimTeam(6); G.day=G.cal.open+40; G.entryY=G.year; for(const t of G.teams)setEntry(t.id); G.stops=[]; G.offers=[]; G.trades=[]; G.lgTrades=[]; G.gmc={}; return G; };
T('[검수 11-18 교차 #802~803] JSON으로 바꾼 같은 날 저장의 부상·연장계약은 실제 뎁스와 FA 잠금을 함께 바꾼다 [거래교차]',()=>{ C786_WORLD(); const tid=G.teams.find(t=>t.id!==G.user).id,p=depth(tid).start.find(q=>q&&!q.foreign&&!q.isP); ok(p,'준비: 선발 야수'); G.day=G.cal.end+1; G.last={y:G.year}; G.fa=null; delete G.rolled; p.age=29;p.faC=true;p.yrs=1;p.ctT=tid;p.svc=faSvc(p);p.lastFA=G.year-5;delete p.mil;delete p.extNext; ok(depth(tid).start.some(q=>q.id===p.id)&&startersOf(tid).has(p.id),'준비: 저장 A 주전');ok(faUpcoming(p).length===1&&faLock(p),'준비: 저장 A FA'); const id=p.id,other=JSON.parse(JSON.stringify(G));other.players[id].injOut=90;other.players[id].extNext={years:3,annual:150};G=other;const q=G.players[id];ok(!depth(tid).start.some(x=>x.id===id)&&faUpcoming(q).length===0,'준비: 저장 B 실제 판정');const j=JSON.stringify(G),r=globalThis.__rngState(); const a=startersOf(tid).has(id),b=faLock(q);ok(!a&&!b,'저장 A 캐시 전이: 주전='+a+' FA='+b);ok(startersOf(tid).has(id)===a&&faLock(q)===b&&JSON.stringify(G)===j&&globalThis.__rngState()===r,'반복 판정이 저장·난수를 변경'); });
T('[검수 11-18 교차 #791~800] 추천 유효성 확인과 반복 가치 조회는 독주 거절·협상 장부와 경기 난수를 변경하지 않는다 [거래교차]',()=>{ C786_WORLD(); const tid=G.teams.find(t=>t.id!==G.user).id,a=domestic(G.user).find(p=>!p.isP),b=domestic(tid).find(p=>!p.isP),olds=[tval,tradeNeed,domTradeTax,aiInterest];try{tval=(t,p,d)=>d==='in'?20:1;tradeNeed=()=>0;domTradeTax=()=>({k:.2,refuse:true});aiInterest=()=>[];delete a.ntc;delete b.ntc;delete a.faTrY;delete b.faTrY;delete a.extNext;delete b.extNext;evalTrade(tid,[a.id],[b.id]);delete G.domLog;_domSeen={d:-1,s:new Set()};const j=JSON.stringify(G),r=globalThis.__rngState();for(let i=0;i<3;i++){const e=evalTrade(tid,[a.id],[b.id]);ok(!e.ok&&e.dom&&e.dom.refuse&&e.gain>=e.need,'준비: 금액은 충족하지만 독주 거절');ok(!tsugValid({id:b.id,tid,give:[a.id]}),'추천이 거래 금지를 통과');}ok(JSON.stringify(G)===j,'평가·추천 조회가 영구 장부를 변경');ok(globalThis.__rngState()===r,'평가·추천 조회가 주 난수를 변경');}finally{[tval,tradeNeed,domTradeTax,aiInterest]=olds;} });
T('[검수 11-18 교차 #790] JSON 복원 역제안도 새 독주 거절에서는 선수·현금·지명권을 원자적으로 보존한다 [거래교차]',()=>{ C786_WORLD();const tid=G.teams.find(t=>t.id!==G.user).id,a=domestic(G.user).find(p=>!p.isP),b=domestic(tid).find(p=>!p.isP),olds=[tval,tradeNeed,domTradeTax,aiInterest,tradeOwnerCheck,tradeCapCheck];try{tval=(t,p,d)=>d==='in'?20:1;tradeNeed=()=>0;domTradeTax=()=>({k:.2,refuse:true});aiInterest=()=>[];tradeOwnerCheck=()=>null;tradeCapCheck=()=>null;for(const p of [a,b]){delete p.ntc;delete p.faTrY;delete p.joinY;p.sal=100;}const give=[a.id],get=[b.id],cash=100,pk=pkNorm(),n=negTurn(tid);n.ctr={[tsig(give,get,cash)+pkSig(pk)]:G.day};G=JSON.parse(JSON.stringify(G));const e=evalTrade(tid,give,get,cash,pk);ok(!e.ok&&e.dom.refuse&&e.gain>=e.need,'준비: 독주 금지');const teams=[G.players[a.id].team,G.players[b.id].team],money0=G.teams.map(t=>t.cash),picks=JSON.stringify(G.pkOwn||{}),trades=G.trades.length;const x=proposeTrade(tid,give,get,cash,pk);ok(!x.ok,'복원된 옛 역제안이 금지를 우회');ok(JSON.stringify([G.players[a.id].team,G.players[b.id].team])===JSON.stringify(teams),'거절했지만 선수 이동');ok(JSON.stringify(G.teams.map(t=>t.cash))===JSON.stringify(money0)&&JSON.stringify(G.pkOwn||{})===picks&&G.trades.length===trades,'거절했지만 현금·권리·거래 기록 변경');}finally{[tval,tradeNeed,domTradeTax,aiInterest,tradeOwnerCheck,tradeCapCheck]=olds;} });

T('[검수 11-18 교차 #805~806] 실제 로스터에서 확정한 AI 묶음 거래는 거래 직전 양 구단의 공통 평가를 모두 충족한다 [거래교차]',()=>{C786_WORLD();for(const t of G.teams){if(t.id===G.user)continue;for(const p of domestic(t.id)){if(p.ys)continue;p.aiListed=true;p.aiLd=G.day;delete p.aiUrg;}}const start=JSON.stringify(G);let found=null;const tr0=tradeTerms;try{for(let pass=0;pass<2&&!found;pass++)for(const t of G.teams){if(t.id===G.user)continue;G=JSON.parse(start);let pre=null;tradeTerms=p=>{if(!pre)pre=JSON.stringify(G);return tr0(p);};globalThis.__seed(786805+pass*20+t.id);const yes=aiTradeTry(t.id);if(yes){found={pre,tr:G.lgTrades[0]};break;}}}finally{tradeTerms=tr0;}ok(found&&found.pre,'정상 수치 로스터에서 합법 거래를 찾지 못함');G=JSON.parse(found.pre);const x=found.tr,relB=relAsRel(x.b,x.a),relA=relAsRel(x.a,x.b),j=JSON.stringify(G),r=globalThis.__rngState(),b=evalTrade(x.b,x.bg,x.ag,x.cash||0,undefined,x.a,relB),a=evalTrade(x.a,x.ag,x.bg,-(x.cash||0),undefined,x.b,relA);ok(a.ok&&b.ok,'실제 확정본의 양방 평가 불일치: A '+a.gain+'/'+a.need+' ('+a.ok+'), B '+b.gain+'/'+b.need+' ('+b.ok+')');ok(JSON.stringify(G)===j&&globalThis.__rngState()===r,'거래 직전 양방 평가가 저장·난수를 변경');});

