T('[검수 11-18 #807 실제불러오기] 날짜 없는 옛 마감 매물은 실제 저장 정리에서 만료되고 반복 불러오기는 난수를 쓰지 않는다 [거래불러오기검수]',()=>{ fresh(); migrateDraft(); const p=domestic(otherT()).find(q=>!q.ys&&!q.foreign);ok(p,'준비: AI 선수'); G.day=KD(11,23);G.formY=G.year;G.entryY=G.year;p.aiListed=true;delete p.aiWhy;delete p.aiLd;delete p.aiUrg;const id=p.id;G=JSON.parse(JSON.stringify(G));const r=globalThis.__rngState();migrateDraft();ok(!G.players[id].aiListed&&!G.players[id].aiLd,'옛 마감 매물이 실제 불러오기에 영구 잔류');ok(globalThis.__rngState()===r,'매물 수리 중 주 난수 변경');const j=JSON.stringify(G),r2=globalThis.__rngState();migrateDraft();ok(JSON.stringify(G)===j&&globalThis.__rngState()===r2,'불러오기 수리 반복 시 저장·난수 변경'); });

/* trade-value-792-basecache-tests.txt */
T('[검수 11-18 거래 기준값 캐시] 후보 작업의 캐시와 매번 새 계산은 실제 묶음·자리·음수 가치·매물·부상에서 같은 판정과 난수다 [트레이드기준캐시검수]',()=>{globalThis.__seed(786792);buildWorld({lite:true});claimTeam(6);G.day=G.cal.open+40;G.entryY=G.year;for(const t of G.teams)setEntry(t.id);G.trades=[];G.lgTrades=[];const A=team(G.user),B=G.teams.find(t=>t.id!==G.user),ps=domestic(A.id).filter(p=>!p.isP).slice(0,3),qs=domestic(B.id).filter(p=>!p.isP).slice(0,3),saved=tradeHoldState,ci=capInfo;const cases=[()=>{},()=>{ps[0].sal=10000;ps[0].faC=true;ps[0].yrs=5;},()=>{qs[0].aiListed=true;qs[0].aiUrg=true;qs[0].aiLd=G.day;},()=>{ps[1].injOut=180;ps[1].pexp={'2B':90};}];for(const prep of cases){prep();slotsHold(()=>{const args=[B.id,ps.map(p=>p.id),qs.map(p=>p.id),0,null,A.id];let a;try{tradeHoldState=()=>null;a=evalTrade(...args);}finally{tradeHoldState=saved;}let calls=0;try{capInfo=(...x)=>{calls++;return ci(...x);};const b=evalTrade(...args),raw=JSON.stringify(G),rng=__rngState(),n=calls,c=evalTrade(...args);ok(JSON.stringify(a)===JSON.stringify(b)&&JSON.stringify(b)===JSON.stringify(c),'캐시 유무로 묶음 판정 변경');ok(calls===n&&_slHold.ev.base.has(B.id)&&_slHold.ev.count.has(A.id),'반복 묶음이 구단 기준값을 재계산');ok(JSON.stringify(G)===raw&&__rngState()===rng,'캐시 조회가 저장/난수 변경');}finally{capInfo=ci;}});}ok(!_slHold,'작업 밖에 캐시 문맥 잔류');});
T('[검수 11-18 거래 기준값 캐시 문맥] 같은 작업의 이동·영입·날짜·로스터 객체·새 저장은 구단 기준값을 다시 계산한다 [트레이드기준캐시검수]',()=>{globalThis.__seed(786793);buildWorld({lite:true});claimTeam(6);const tid=G.teams.find(t=>t.id!==G.user).id,p=domestic(tid)[0];slotsHold(()=>{tradeBaseOf(tid);let prior=_slHold.ev;for(const key of ['mvN','acqSeq']){G[key]=(G[key]||0)+1;tradeBaseOf(tid);ok(_slHold.ev!==prior,key+' 이동문맥 캐시 재사용');prior=_slHold.ev;}G.trades.push({y:G.year,me:G.user,with:tid});tradeBaseOf(tid);ok(_slHold.ev!==prior,'직접거래후 캐시 재사용');prior=_slHold.ev;G.lgTrades.push({y:G.year,a:G.user,b:tid});tradeBaseOf(tid);ok(_slHold.ev!==prior,'AI거래후 캐시 재사용');prior=_slHold.ev;G.day++;tradeBaseOf(tid);ok(_slHold.ev!==prior,'날짜변경후 캐시 재사용');prior=_slHold.ev;G.players={...G.players};tradeBaseOf(tid);ok(_slHold.ev!==prior,'로스터 객체 변경후 캐시 재사용');p.team=G.user;G.acqSeq++;const b=tradeBaseOf(tid);ok(b.n===rosterN(tid)&&b.pay===capInfo(tid).pay&&tradeActorCount(tid)===Object.values(G.players).filter(q=>q.team===tid).length,'실제 이동후 인원·급여 기준값 불일치');prior=_slHold.ev;G=JSON.parse(JSON.stringify(G));tradeBaseOf(tid);ok(_slHold.ev!==prior&&_slHold.ev.g===G,'다른 저장 캐시 재사용');});});
T('[검수 11-18 거래 기준값 캐시 실거래] 실제 AI 후보 탐색도 캐시 유무로 선수·현금·기록·주난수가 바뀌지 않는다 [트레이드기준캐시검수]',()=>{globalThis.__seed(786802);buildWorld({lite:true});claimTeam(6);G.day=G.cal.open+40;G.entryY=G.year;for(const t of G.teams)setEntry(t.id);G.trades=[];G.lgTrades=[];G.gmc={};const state=JSON.stringify(G),id=G.teams.find(t=>t.id!==G.user).id,saved=tradeHoldState;for(const listed of [false,true]){let oracle;for(const cache of [false,true]){G=JSON.parse(state);if(listed)for(const p of Object.values(G.players))if(p.team!==G.user&&p.team!=null&&!p.ys){p.aiListed=true;p.aiLd=G.day;}globalThis.__seed(786805+id);try{tradeHoldState=cache?saved:()=>null;const z=aiTradeTry(id),got={z,g:JSON.stringify(G),rng:__rngState()};if(!cache){ok(z===true,'실제 AI 성사 준비 실패 listed='+listed);oracle=got;}else ok(got.z===oracle.z&&got.g===oracle.g&&got.rng===oracle.rng,'실제 AI거래가 캐시로 변경 listed='+listed);}finally{tradeHoldState=saved;}}}});

