const pwPitch=()=>{fresh();G.day=G.cal.open+70;const p=playersOf(G.user).find(q=>q.isP);p.role='RP';p.r.sta=50;p.ld=[];p.lsD=[];p.armw=0;delete p.lastApp;delete p.lastStart;return p;};
T('[검수 11-18 #454] DH 구원 합계가 긴 한 등판의 팔 한도가 되지 않는다 [투수운용검수]',()=>{const p=pwPitch();pitchApp(p,G.day,30,false);pitchApp(p,G.day,30,false);ok(armCap(p)===540,'DH30+30 한도 '+armCap(p));ok(p.lastPc===60&&pc7(p,G.day+1)===60,'하루 총량 소실');p.ld=[[G.day,60,2]];const old=JSON.stringify(p.ld);ok(armCap(p)===540&&armCap(p)===540,'옛 DH기록의 합계로 한도 확대');ok(JSON.stringify(p.ld)===old,'구기록 조회가 원본변경');pitchApp(p,G.day,15,false);ok(p.ld[0][1]===75&&p.ld[0][2]===3&&p.ld[0][3].length===3,'구기록에 새등판 추가 호환');});
