T('[검수 11-18 #456] 짧은 열 등판 뒤에도 60일 긴 등판 노출을 보존한다 [투수운용검수]',()=>{const p=pwPitch(),d=G.day;pitchApp(p,d,80,false);for(let i=1;i<=10;i++)pitchApp(p,d+i*2,10,false);G.day=d+20;ok(Math.abs(armCap(p)-(540+610*2/3))<.001,'20일 긴등판 소실 '+armCap(p));G.day=d+60;ok(armCap(p)===540,'60일 노출 만료 실패');});
T('[검수 11-18 #457] 선발 전 구원 가산은 개별 등판과 보직을 본다 [투수운용검수]',()=>{const p=pwPitch(),d=G.day;pitchApp(p,d-3,40,true);pitchApp(p,d-3,25,false);const w=p.armw;pitchApp(p,d,90,true);ok(Math.abs(p.armw-w-153)<.001,'SP40+RP25 뒤 SP 가산 '+(p.armw-w));const total=p.armw;p.ld=[];p.lsD=[];p.armw=0;pitchApp(p,d,90,true);pitchApp(p,d-3,25,false);pitchApp(p,d-3,40,true);ok(Math.abs(p.armw-total)<.001,'기록입력 순서가 role가산 변경');p.ld=[];p.lsD=[];p.armw=0;pitchApp(p,d-3,11,false);pitchApp(p,d-3,11,false);const q=p.armw;pitchApp(p,d,90,true);ok(Math.abs(p.armw-q-90)<.001,'RP11+11을20구등판으로 '+(p.armw-q));});
