T('[검수 11-18 #460] 오늘 등판한 투수만 남으면 선발 후보가 없다 [투수운용검수]',()=>{pwPitch();const t=G.user,d=depth(t);for(const p of playersOf(t).filter(q=>q.isP))p.lastApp=G.day;ok(pickStarter(t,d,G.day,null)===null,'당일선발 재사용');});
T('[검수 11-18 #461] 투수관리 비상교체도 당일 등판을 제외하고 계속투구를 표시한다 [투수운용검수]',()=>{pwPitch();const t=G.user,op=G.teams.find(q=>q.id!==t).id;G.entryY=G.year;for(const tm of G.teams)setEntry(tm.id);const d=depth(t),s=d.sp[0];ok(s,'선발 준비');for(const p of playersOf(t).filter(q=>q.isP))p.lastApp=G.day;s.lastApp=G.day-6;s.lastStart=G.day-6;team(t).rot=0;const m=G.mgr[t];m.interim=false;G.mgrDir={arm:{ok:true,mid:m.id}};const oo=outcome,os=stealTry;let g;try{outcome=()=>{LBIP=null;return 'K';};stealTry=()=>0;g=withRng(461,()=>simGame(G.day,t,op,false));}finally{outcome=oo;stealTry=os;}const fs=g.S.h;ok(fs.pitchers.length===1,'당일투수 비상재사용 '+fs.pitchers.length);ok((fs.armEmergency||[]).some(x=>x.id===s.id),'비상계속투구 표시 없음');ok(g.ev.some(e=>e.t.includes('비상 계속 투구')),'중계 비상표시 없음');});
T('[검수 11-18 #462] DH 4연투 경고는 날짜마다 한번이다 [투수운용검수]',()=>{const p=pwPitch();p.e1=true;for(let i=3;i>=1;i--)pitchApp(p,G.day-i,12,false);const n=()=>G.mail.filter(m=>m.body.includes('4일 연속 등판')&&m.ref===p.id).length;const b=n();pitchApp(p,G.day,15,false);pitchApp(p,G.day,15,false);ok(n()===b+1,'DH 경고 '+(n()-b));});

T('[검수 11-18 #463] 중계 전 선수 화면은 부상 직후 구속과 팔 부하를 숨기고 닫으면 실제 상태를 복구한다 [중계상태검수]',()=>{ fresh(); G.day=G.cal.open; const p=playersOf(G.user).find(p=>p.isP);ok(p,'1군 투수 준비');p.e1=true;p.velo=153-146-(p.r.stf-41.5)*VELO_K;p.armw=120;p.ld=[];p.injOut=0;delete p.injK;delete p.injFx;const r=JSON.stringify(p.r), v=p.velo, pre=loadText(p);spoilSnapTake(G.day,[G.user]);p.velo-=2;p.r.stf-=4;p.armw=600;p.injOut=353;p.injK='tj';p.injFx=[{k:'tj',L:{stf:4},need:100,got:0}];pitchApp(p,G.day,60,true);const after=JSON.stringify(p),g={day:G.day,box:{h:{pit:[{id:p.id,pc:60}],bat:[]},a:{pit:[],bat:[]}}};const UI={sheet:p.id};const F=eval(globalThis.__spoilMaskSrc());const un=F.mask();ok(p.velo===v&&veloOf(p)===153&&JSON.stringify(p.r)===r,'경기 후 구속 또는 능력이 미리 노출');ok(p.armw===120&&loadText(p)===pre,'경기 후 팔 부하 또는 등판이 미리 노출');ok(!p.injOut&&!p.injFx,'경기 후 부상/후유증이 미리 노출');un();ok(JSON.stringify(p)===after,'선수 화면을 닫은 뒤 실제 상태가 달라짐'); });
T('[검수 11-18 #463 저장] 새로고침한 중계도 저장된 경기 전 구속·능력·팔 부하를 표시한다 [중계상태검수]',()=>{ fresh();G.day=G.cal.open;const p=playersOf(G.user).find(p=>p.isP);p.e1=true;p.velo=153-146-(p.r.stf-41.5)*VELO_K;p.armw=120;p.ld=[];p.injOut=0;spoilSnapTake(G.day,[G.user]);const ps=JSON.parse(JSON.stringify({[p.id]:Object.fromEntries(SPOIL_K.filter(spoilLite).map(k=>[k,SPOIL_SNAP.P[p.id][k]]))}));p.velo-=2;p.armw=600;p.r.stf-=4;p.injOut=353;pitchApp(p,G.day,60,true);const after=JSON.stringify(p),g={gid:463,day:G.day,kind:'정규시즌',box:{h:{pit:[{id:p.id,pc:60}],bat:[]},a:{pit:[],bat:[]}}};G.castHold={gid:g.gid,ps};SPOIL_SNAP=null;const UI={sheet:p.id};const F=eval(globalThis.__spoilMaskSrc());const un=F.mask();ok(veloOf(p)===153&&p.armw===120&&!p.injOut,'불러온 중계에서 경기 후 몸 상태 노출');un();ok(JSON.stringify(p)===after,'저장 중계의 실제 상태 복구 실패'); });
T('[검수 11-18 #463 호환] 예전 중계 사본에 없는 필수 능력값은 지우지 않는다 [중계상태검수]',()=>{fresh();G.day=G.cal.open;const p=playersOf(G.user).find(p=>p.isP);const r=p.r,v=p.velo,pot=p.pot;const g={gid:463,day:G.day,kind:'정규시즌',box:{h:{pit:[],bat:[]},a:{pit:[],bat:[]}}};G.castHold={gid:g.gid,ps:{[p.id]:{injOut:0,ld:[]}}};SPOIL_SNAP=null;const UI={sheet:p.id};const F=eval(globalThis.__spoilMaskSrc());const un=F.mask();ok(p.r===r&&p.velo===v&&p.pot===pot&&Number.isFinite(veloOf(p)),'옛 중계 사본이 능력값을 손상');un();ok(p.r===r&&p.velo===v&&p.pot===pot,'옛 중계 복원 실패');});

const istSetup=()=>{ fresh(); G.day=G.cal.open+10; G.evs=[]; G.evf=[]; G.mail=[]; G.stops=[]; const p=domestic(G.user).find(p=>!p.ys&&!p.foreign&&!milServing(p)); p.injOut=0; p.injHist=[]; return p; };
const istHurt=(p,k,days,day=G.day)=>{ const a=injPick,b=INJ[k].d,c=recMult; try{ injPick=()=>k; INJ[k].d=[days,days]; recMult=()=>1; withRng(430,()=>injure(p,day)); }finally{injPick=a;INJ[k].d=b;recMult=c;} };
T('[검수 11-18 #430] 옛 조기복귀 카드는 새 수술을 줄이지 않는다 [부상상태검수]',()=>{ const p=istSetup(); istHurt(p,'back',18); evInjury(p,18,true); const e=G.evs.find(e=>e.k==='inj'); istHurt(p,'tj',353); evPick(e.id,0); ok(p.injOut===353&&p.injK==='tj','새 수술이 옛 카드로 '+p.injOut+'일'); });
T('[검수 11-18 #431] 옛 정밀검진은 확정 수술을 덮지 않는다 [부상상태검수]',()=>{ istSetup(); const p=foreignOf(G.user)[0]; p.injOut=0;p.injHist=[]; fDramaUser(p,'fake'); const e=G.evs.find(e=>e.k==='fdrama'); istHurt(p,'tj',353); for(let s=1;s<100;s++){ const q=JSON.parse(JSON.stringify(p)); withRng(s,()=>EVH.fdrama.pick(e,0)); ok(p.injOut===353&&p.injK==='tj','검진이 수술 덮음'); Object.assign(p,q); } });
T('[검수 11-18 #432] 연수 부상 결과는 긴 기존 재활을 유지한다 [부상상태검수]',()=>{ const p=istSetup(); istHurt(p,'tj',353); p.inj=.4; withRng(432,()=>ovsRoll(p,{...OVS.us,inj:1,form:0,big:0,good:0},50)); ok(p.injOut===353&&p.injK==='tj','연수 결과로 '+p.injOut+'일'); });
T('[검수 11-18 #433] 새 진단은 옛 조기복귀 위험을 종료한다 [부상상태검수]',()=>{ const p=istSetup();istHurt(p,'back',18);evInjury(p,18,true);evPick(G.evs.find(e=>e.k==='inj').id,0);istHurt(p,'ankle',10);ok(!p.rush&&!p.rushRet,'새 진단에 옛 위험 남음'); });
T('[검수 11-18 #434] 겹친 재활 결장일은 달력 합집합이다 [부상상태검수]',()=>{ const p=istSetup(); p.injOut=20;p.injHist=[{y:G.year,d:G.day-6,days:30,k:'tj'},{y:G.year,d:G.day-5,days:20,ovs:1}];ok(injDays2(p)===6,'6일을 '+injDays2(p)+'일로 계산'); });
T('[검수 11-18 #435] 두 주전은 각자 부상 결정을 받는다 [부상상태검수]',()=>{ const a=istSetup(),b=domestic(G.user).find(p=>p!==a&&!p.ys&&!p.foreign); a.injOut=b.injOut=18; a.injHist=[{d:G.day,days:18,y:G.year}];b.injHist=[{d:G.day,days:18,y:G.year}];evInjury(a,18,true);evInjury(b,18,true);ok(evOpen().filter(e=>e.k==='inj').length===2,'두번째 카드 누락'); });
T('[검수 11-18 #436] 부상 전 주전 판단으로 경고한다 [부상상태검수]',()=>{ const p=istSetup(),f=isRegular;try{ isRegular=q=>q===p&&!(q.injOut>0);istHurt(p,'back',10);ok(G.mail.some(m=>m.kind==='부상'&&m.imp),'주전 경고 없음'); G.mail=[];G.stops=[];G.day=G.cal.end+1;G.ps={done:false};p.injOut=0;istHurt(p,'back',18);ok(G.mail.some(m=>m.kind==='부상'&&m.imp),'PS 주전 경고 없음'); }finally{isRegular=f;} });
T('[검수 11-18 #437] 이직 뒤에도 조기복귀 후속 결과를 남긴다 [부상상태검수]',()=>{ const p=istSetup();istHurt(p,'back',18);evInjury(p,18,true);const e=G.evs.find(e=>e.k==='inj');evPick(e.id,0);const due=G.evf[0].day;switchTeam(otherT());ok(G.evf.some(f=>f.k==='inj'),'이직 때 후속 삭제');p.injOut=0;delete p.rushRet;p.rush=due-1;G.day=due;evDaily();ok(G.evlog.some(l=>l.id===e.id&&l.f),'후속 결과 없음'); });
T('[검수 11-18 #438] 재활 선수 영입 즉시 제휴병원을 적용한다 [부상상태검수]',()=>{ istSetup();setHospital('a');const p=domestic(otherT()).find(p=>!p.ys&&!milServing(p)),from=p.team;p.injOut=30;p.injK='back';p.injHist=[{y:G.year,d:G.day,days:30,t:from}];p.injC=from;p.team=G.user;mvLog('트레이드',p,from,G.user);ok(p.injOut===23,'영입 재활 '+p.injOut+'일'); });
T('[검수 11-18 #439] 훈련 부상에도 받은 병원효과만 되돌린다 [부상상태검수]',()=>{ const p=istSetup();setHospital('a');p.inj=.4;withRng(439,()=>ovsRoll(p,{...OVS.us,inj:1,form:0,big:0,good:0},50));const days=p.injOut,h=p.injHist[p.injHist.length-1];ok(h&&h.hosp==='a','진단 때 병원효과 기준 누락');setHospital('none');ok(p.injOut>=days&&p.injOut<=60,'훈련 재활 잘못 역산 '+days+'→'+p.injOut); });
T('[검수 11-18 #440] 소급 부상 시즌아웃 판정은 실제 복귀일이다 [부상상태검수]',()=>{ const p=istSetup();G.day=G.cal.end-2;p.sal=1000;istHurt(p,'ham2',30,G.day-28);ok(!G.mail.some(m=>m.body.includes('사실상 끝났')||m.body.includes('시즌 아웃')),'최종일 복귀를 시즌아웃 보도'); });
T('[검수 11-18 #441] 재활 변경은 원본 결정메일도 갱신한다 [부상상태검수]',()=>{ const p=istSetup();G.med.hosp='none';istHurt(p,'back',39);evInjury(p,39,true);const e=G.evs.find(e=>e.k==='inj'),m=G.mail.find(m=>m.id===e.mid);setHospital('a');ok(m.body.includes('약 '+p.injOut+'일'),'병원 변경 뒤 원본메일 옛 기간');evPick(e.id,0);ok(m.body.includes('예상 복귀 '+injRetTxt(p)),'조기복귀 뒤 원본메일 옛 복귀일'); });
T('[검수 11-18 #434] 같은 날짜 부상 상태 정리는 멱등이다 [부상상태검수]',()=>{const p=istSetup();istHurt(p,'back',18);const n=p.injOut;injDaily();injDaily();ok(p.injOut===n,'진단일 중복 회복');G.day++;injRecoveryTick(p);const left=p.injOut;injRecoveryTick(p);ok(p.injOut===left&&left===n-1,'동일 날짜 중복 회복');p.injOut=0;p.reInj={k:'back',d:G.day-1,left:30,m:1.6};injDaily();injDaily();ok(p.reInj.left===29,'동일 날짜 재발기간 중복 차감');const h=JSON.stringify(p.injHist),rng=__rngState();injEpisode(p);injEpisode(p);ok(h===JSON.stringify(p.injHist)&&rng===__rngState(),'구버전 ID 복원 멱등/무난수');});
T('[검수 11-18 #439] 옛 연수 및 자비훈련 재활은 병원할인을 받았다고 역산하지 않는다 [부상상태검수]',()=>{const p=istSetup();G.med.hosp='a';p.injOut=32;p.injK=null;p.injHist=[{y:G.year,d:G.day,days:32,ovs:1,t:G.user}];delete p.injB;delete p.injC;setHospital('none');ok(p.injOut===32,'옛 연수 재활 '+p.injOut+'일');G.med.hosp='a';p.injOut=18;p.injHist=[{y:G.year,d:G.day,days:18,t:G.user}];delete p.injB;delete p.injC;setHospital('none');ok(p.injOut===18,'옛 개인 훈련 재활 '+p.injOut+'일');});
T('[검수 11-18 #434 #441] 겹부상 병원 변경은 모든 복귀일과 현재 진단메일을 함께 갱신한다 [부상상태검수]',()=>{const p=istSetup();G.med.hosp='none';istHurt(p,'back',30);const m=G.mail.find(m=>m.kind==='부상'),d=G.day;G.day+=5;p.injOut=25;injStart(p,{days:20,hosp:'none',extra:{ovs:1}});setHospital('a');const ret=G.day+p.injOut;ok(p.injHist.every(h=>h.ret<=ret),'겹진단보다 빠른 복귀');ok(m.body.includes('예상 복귀 '+injRetTxt(p)),'현재진단 원본메일 미갱신');for(let i=0;i<30;i++){G.day++;injRecoveryTick(p);}ok(injDays2(p)===ret-d,'복귀 이후 겹재활 결장일 추가 '+injDays2(p)+'/'+(ret-d));});
T('[검수 11-18 #438] 이동 기록이 소속 변경보다 먼저여도 새 병원 소유권을 남긴다 [부상상태검수]',()=>{istSetup();setHospital('a');const p=domestic(otherT()).find(p=>!p.ys&&!milServing(p)),from=p.team;p.injOut=0;p.injHist=[];istHurt(p,'back',30);mvLog('트레이드',p,from,G.user);p.team=G.user;ok(p.injOut===23&&p.injC===G.user,'영입 병원 소유권 틀림');setHospital('none');ok(p.injOut===30,'새 병원 해지 복원 실패 '+p.injOut);});
T('[검수 11-18 #439] 진단 기준이 생겨도 짧은 부상 병원변경 제외를 지킨다 [부상상태검수]',()=>{const p=istSetup();G.med.hosp='none';istHurt(p,'blister',7);setHospital('a');ok(p.injOut===7,'짧은 부상이 병원변경으로 단축 '+p.injOut);});

const ieSetup=()=>{ fresh(); G.day=G.cal.open+20; G.entryY=G.year; G.regTrk=G.year; G.res=null; G.live=null; G.evs=[]; const d=G.day+1; G.cal.sched[d]=[[G.user,otherT()]]; const L=Object.values(G.players).filter(p=>p.team===G.user&&!p.prospect); for(const p of L){ p.e1=false;p.ys=false;p.injOut=100;delete p.mil;delete p.ntAway;delete p.joinY;delete p.frehab;delete p.hold;delete p.susp;delete p.boy;delete p.fLeave;delete p.downDay; } const B=L.filter(p=>!p.isP), P=L.filter(p=>p.isP); for(const p of B.slice(0,9).concat(P.slice(0,8))){p.injOut=0;p.e1=true;} return {L,B,P}; };
T('[검수 11-18 #450] 훈련불참과 귀국휴가는 실제 경기와 사전검사에 같은 자격을 쓴다 [출전자격검수]',()=>{ for(const key of ['boy','fLeave']){ const {B}=ieSetup(); B[8][key]=G.day+4; ok(blocker().includes('야수'),'결장 야수를 아홉번째로 세어 사전검사 통과 '+key); ok(!healthy(B[8]),'실제 건강판정 통과 '+key); } });
T('[검수 11-18 #451] 하루 뒤 낫는 2군 선발수업은 부족한 1군투수로 세지 않는다 [출전자격검수]',()=>{ const {P}=ieSetup(); P[7].injOut=1; const old=rpPlanOf; try{rpPlanOf=(tid,p)=>p===P[7]?'sp2':old(tid,p);ok(blocker().includes('투수'),'2군 선발수업 복귀자로 8명 통과');}finally{rpPlanOf=old;} });
T('[검수 11-18 #450] 정상 부상복귀와 대표복귀는 내일 경기 인원에 포함한다 [출전자격검수]',()=>{ const {B,P}=ieSetup(); B[8].injOut=1; P[7].injOut=1; ok(!blocker(),'하루 남은 정상 부상복귀를 못 셈 '+blocker()); B[8].injOut=0;B[8].ntFrom=G.day-5;B[8].ntAway=G.day+1;ok(!blocker(),'내일 대표복귀를 못 셈 '+blocker()); });
T('[검수 11-18 #449] 백업포수 자리는 단기 부상포수부터 말소한다 [출전자격검수]',()=>{ const {L,B,P}=ieSetup(); for(const p of L){p.e1=false;p.injOut=0;} const C=B.slice(0,3);C.forEach(p=>p.pos='C');B.slice(3).forEach(p=>p.pos='RF');const ent=C.slice(0,2).concat(B.slice(3),P).slice(0,entryLimit());for(const p of ent){p.e1=true;p.upDay=G.day;}C[1].injOut=3;ok(ent.length===entryLimit(),'엔트리 준비');entryManage(G.user,false,true);ok(C[2].e1&&!C[1].e1,'건강한 야수를 내리고 부상포수를 남김'); });
T('[검수 11-18 #452] 콜업 거절 사유가 귀국휴가와 훈련불참을 가리킨다 [출전자격검수]',()=>{ const {B}=ieSetup(); const p=B[10];p.injOut=0;p.downDay=G.day-12;p.fLeave=G.day+5;ok(!canUp(p)&&upWhy(p).includes('귀국'),'귀국휴가가 부상으로 표시 '+upWhy(p));delete p.fLeave;p.boy=G.day+3;ok(!canUp(p)&&upWhy(p).includes('훈련'),'훈련불참을 재등록 대기로 표시 '+upWhy(p)); });
T('[검수 11-18 #453] 당일 말소 뒤 퓨처스 부상은 1군 부상등록일을 주지 않는다 [출전자격검수]',()=>{ const {B}=ieSetup();const p=B[0];p.e1=false;p.downDay=G.day;p.e1L=G.day-1;p.e1T=p.team;p.injOut=20;p.injHist=[{k:'ankle',d:G.day,days:20,t:p.team,farm:true}];p.regD={y:G.year,n:10,il:0};regDaily();ok(p.regD.n===10&&p.regD.il===0,'2군 부상에 1군 등록 인정'); });
T('[검수 11-18 #443] 사구없는 경기에서 사구타박상을 진단하지 않는다 [출전자격검수]',()=>{ fresh();const p=domestic(G.user).find(p=>!p.isP);delete p.reInj;let found=false;for(let seed=0;seed<250;seed++)if(withRng(seed,()=>injPick(p,{hbp:0}))==='contus')found=true;ok(!found,'사구0인데 사구타박상');p.reInj={k:'contus',left:10};ok(withRng(1,()=>injPick(p,{hbp:0}))!=='contus','사구0인데 사구타박상 재발'); });
T('[검수 11-18 #444] 토미존 기록의 구속변화는 실제 복귀 구속과 일치한다 [출전자격검수]',()=>{ fresh();const p=domestic(G.user).find(p=>p.isP);const v=veloOf(p),f=withRng(9,()=>injApply(p,'tj',370));ok(f.preVel===v,'수술전 구속 없음');ok(f.v===veloOf(p)-v,'실측 구속과 안내가 다름 '+f.v+'/'+(veloOf(p)-v)); });
T('[검수 11-18 #445] 어깨수술 영구구속은 구위 손실만 계산한다 [출전자격검수]',()=>{ fresh();const p=domestic(G.user).find(p=>p.isP);const v=veloOf(p),f=withRng(5,()=>injApply(p,'cuffS',250));ok(f.preVel===v&&f.v===veloOf(p)-v,'수술후 즉시 구속 변화 오류');const final=veloOf({...p,r:{...p.r,stf:p.r.stf+f.L.stf}});ok(f.finalVel===final,'실전회복후 구속에 제구손실 혼입'); });
T('[검수 11-18 #448] 재수술한 날 과거 복귀성공 기사를 내지 않는다 [출전자격검수]',()=>{ fresh();G.day=KD(7,1);slInit();const p=domestic(G.user).find(p=>!p.isP);const s=slStart('cb',p.team,[p.id],'back',{tot:100,d0:G.day-130,bd:G.day-28,ik:'acl',sn:{}});p.injOut=260;p.injK='acl';p.hist.push({...ZB,y:G.year,lvl:'1군',t:p.team,g:20,pa:100,ab:80,h:40,d:10,bb:20,hr:5});SLH.cb.week(s);ok(s.x.b!=='good','재수술 당일 재기성공'); });
T('[검수 11-18 #442] 휴식일 출전지시로 즉시 부상하지 않고 실제출장 위험만 예약한다 [출전자격검수]',()=>{ fresh();G.day=G.cal.open+20;const p=foreignOf(G.user)[0];ok(p,'외국인 준비');initPers(p);p.injOut=0;G.cal.sched[G.day]=[];let seed=0;while(withRng(seed,()=>R())>=.12)seed++;const old=injure;let n=0;try{injure=()=>n++;withRng(seed,()=>EVH.fdrama.pick({data:{pid:p.id,keys:['play']}},0));ok(n===0&&p.injOut===0,'경기0 휴식일에 즉시진단');ok(p.fPlayInj,'위험당첨 시드 준비실패');}finally{injure=old;}ok(injGameRisk(p,G.day+1),'실제출장 위험을 소비하지 못함');ok(!injGameRisk(p,G.day+1),'같은 위험이 중복발동'); });
T('[검수 11-18 #446] 상무부상 메일은 원구단병원 치료·정밀검진을 표시하지 않는다 [출전자격검수]',()=>{ fresh();G.day=G.cal.open+20;const p=domestic(G.user).find(p=>!p.foreign&&!p.isP);G.med.hosp='a';p.mil={unit:'상무',from:G.day-10,until:G.day+400};G.mail=[];withRng(1,()=>injure(p,G.day,{farm:1,hbp:0}));const msg=G.mail.map(m=>m.body||'').join(' ');ok(msg.includes(p.name),'메일 없음');ok(!msg.includes('정밀 검진 결과')&&!msg.includes(HOSP.a.name),'원구단 병원혜택 문구 '+msg); });
T('[검수 11-18 #453] 실제 2군진단은 등록일에서 제외하고 1군진단 후 말소는 인정한다 [출전자격검수]',()=>{ const {B}=ieSetup();const p=B[0];p.e1=false;p.injOut=0;p.downDay=G.day;p.e1L=G.day-1;p.e1T=p.team;p.regD={y:G.year,n:10,il:0};withRng(4,()=>injure(p,G.day,{farm:1,hbp:0}));regDaily();ok(p.regD.n===10&&p.regD.il===0,'실제 퓨처스진단 등록 인정');const q=B[1];q.injOut=0;q.e1=true;q.e1L=G.day-1;q.e1T=q.team;q.regD={y:G.year,n:10,il:0};withRng(4,()=>injure(q,G.day,{hbp:0}));q.e1=false;q.downDay=G.day;regDaily();ok(q.regD.n===11&&q.regD.il===1,'1군 부상후 말소 등록 인정이 깨짐'); });
T('[검수 11-18 #444 #445] 복귀메일과 실전회복후 구속이 같은 실제 수치를 안내한다 [출전자격검수]',()=>{ fresh();const p=domestic(G.user).find(p=>p.isP);for(const k of ['tj','cuffS']){const f=withRng(9,()=>injApply(p,k,k==='tj'?370:250));p.injK=k;const txt=injReturnVelText(p);ok(txt.includes(String(veloOf(p))+'km/h')&&txt.includes(String(f.preVel)+'km/h'),'복귀메일 실제구속 불일치 '+txt);const expected=f.finalVel;injRecover(p,f.need);ok(veloOf(p)===expected,'실전회복후 예상구속 불일치 '+veloOf(p)+'/'+expected);} });
T('[검수 11-18 #450 #451] 가득찬 엔트리도 사전검사에서 센 8번째 건강투수를 실제 콜업한다 [출전자격검수]',()=>{ const {B,P}=ieSetup();while(B.length<entryLimit()-7){const p=JSON.parse(JSON.stringify(B[0]));p.id=G.nextId++;G.players[p.id]=p;B.push(p);}for(const p of Object.values(G.players).filter(p=>p.team===G.user))p.e1=false;for(const p of B.slice(0,entryLimit()-7).concat(P.slice(0,7))){p.injOut=0;p.e1=true;}P[7].injOut=0;ok(!blocker(),'사전검사 8번째투수를 못셈 '+blocker());entryManage(G.user,false,true);ok(actOf(G.user).filter(p=>p.isP&&healthy(p)).length>=8,'사전검사 통과 후 실제투수7명');ok(actOf(G.user).filter(p=>!p.isP&&healthy(p)).length>=9,'투수보충으로 야수9명 깨짐'); });
T('[검수 11-18 #453] 2군 겹진단은 기존 1군 부상 등록인정을 지우거나 늘리지 않는다 [출전자격검수]',()=>{ const {B}=ieSetup();const p=B[0];p.e1=false;p.e1L=G.day-1;p.e1T=p.team;p.regD={y:G.year,n:10,il:0};p.injOut=30;const h={id:'first',k:'back',d:G.day-1,days:31,ret:G.day+30,t:p.team};p.injHist=[h];p.injId=h.id;injStart(p,{days:3,k:'ankle',extra:{farm:true}});regDaily();ok(p.regD.n===11,'2군 겹진단이 1군인정을 삭제');h.ret=G.day-1;p.injOut=20;p.injHist[1].ret=G.day+20;regDaily();ok(p.regD.n===11,'끝난 1군부상 인정을 2군부상으로 연장'); });
const r464_prep=()=>{ fresh(); const t=team(G.user), S=stadOf(t.id); S.build=[]; S.xq=null; S.proj=null; delete S.debt; t.cash=30000; return {t,S,id:t.id,from:t.city}; };
const r464_legacy=(o)=>{ const P=r464_prep(), {t,S,id,from}=P, d=G.day-200; G.tnames={[id]:[{y0:-Infinity,y1:G.year-1,city:from,nick:t.nick},{y0:G.year,y1:null,d0:d,city:'제주',nick:t.nick}]}; t.city='제주'; S.built=2015; S.dome=true; S.name='옛 '+from+' 슈퍼돔'; Object.assign(S,o||{}); return {...P,d}; };
T('[검수 11-18 #464] 결산 직후 이전의 일시 상환은 다음 회계연도 현금 장부에 남는다 [이전구장검수]',()=>{ const {t,S,id}=r464_prep(); G.last={y:G.year}; S.debt={cost:9000,paid:6000}; const cash=t.cash; clubRebrand(id,{city:'제주'},'검수'); const H=G.hoL&&G.hoL[fyNow()+':'+id]; ok(H&&Object.values(H.exp).includes(3000),'남은 분담금 지출 없음'); ok(t.cash-cash===H.net,'현금과 장부 불일치'); });
T('[검수 11-18 #465] 이전 일시 상환도 모기업 70퍼센트 출자를 받고 독립구단은 전액 부담한다 [이전구장검수]',()=>{ for(const indie of [false,true]){ const {t,S,id}=r464_prep(); t.indie=indie; S.debt={cost:9000,paid:6000}; const cash=t.cash; clubRebrand(id,{city:'제주'}); ok(t.cash===cash-(indie?3000:900),'부담금 '+(cash-t.cash)); const H=G.hoL[fyNow()+':'+id]; ok(sum(Object.values(H.inc))===(indie?0:2100),'출자 명세'); } });
T('[검수 11-18 #466] 이전 시설 공사 환급은 실제 돌아온 현금만 수입 장부에 남긴다 [이전구장검수]',()=>{ const {t,S,id}=r464_prep(); G.last={y:G.year}; S.build=[{k:'fnb',lv:3,st:G.day-30,done:G.day+60,c:1200}]; const cash=t.cash; clubRebrand(id,{city:'제주'}); const H=G.hoL&&G.hoL[fyNow()+':'+id]; ok(t.cash===cash+800&&H&&sum(Object.values(H.inc))===800,'환급 수입 누락'); });
T('[검수 11-18 #467] 구버전 이전 공사는 불러온 날 대신 이전일 기준으로 환급하고 재불러오기는 멱등이다 [이전구장검수]',()=>{ const {t,S,d}=r464_legacy(); S.build=[{k:'fnb',lv:3,st:d-10,done:d+80,c:1200}]; S.xq={k:'of',stage:'build',st:d-10,pm:d+5,done:d+115,c:4200}; const cash=t.cash, rng=globalThis.__rngState(); ciMigrate(); ok(t.cash===cash+1067+4200,'이전일 환급 '+(t.cash-cash)); const save=JSON.stringify(G); ciMigrate(); ok(JSON.stringify(G)===save&&globalThis.__rngState()===rng,'반복 복구 또는 난수 변경'); });
T('[검수 11-18 #468] 이전 복구는 옛 도시 구장 이름을 새 도시 기본 이름으로 바꾸고 장소 이력을 남긴다 [이전구장검수]',()=>{ const {S,id,from,d}=r464_legacy(); ciMigrate(); ok(stadName(id)==='제주 야구장','옛 도시 이름 '+stadName(id)); ok(S.names.some(x=>x.until===d&&x.n.includes(from)),'옛 장소 이력 없음'); });
T('[검수 11-18 #469] 이전 이후 담장 공사와 새 도시 관계는 구버전 복구가 보존한다 [이전구장검수]',()=>{ const {t,S,d}=r464_legacy(); t.cityRel=82; S.dim={lf:98,cf:128,rf:98,wl:3,wc:8,wr:3}; S.fenceH=[{d:d+20,y:G.year,to:{...S.dim}}]; S.fenceY=G.year; ciMigrate(); ok(t.cityRel===82&&S.dim.cf===128&&S.dim.wc===8,'이후 관계·담장 덮어씀'); ok(S.fenceY===G.year,'새 담장 제한 지움'); });
T('[검수 11-18 #470] 이전과 같은 해에 연 새 구장의 분납금과 구장 속성은 복구가 보존한다 [이전구장검수]',()=>{ const {t,S,d}=r464_legacy(); S.built=G.year; S.name='제주 새 야구장'; S.names=[{n:'제주 야구장',until:d+30}]; S.cap=25600; S.nk='big'; S.ncap=25000; S.debt={cost:9000,paid:3000}; S.dim={lf:100,cf:125,rf:100,wl:3,wc:3,wr:3}; const cash=t.cash, debt=JSON.stringify(S.debt); ciMigrate(); ok(t.cash===cash&&JSON.stringify(S.debt)===debt&&S.cap===25600&&S.dim.cf===125,'새 구장 빚·속성 변경'); ok(S.reloc&&S.reloc.to==='제주','이전 복구 표시 누락'); });
T('[검수 11-18 #471] 초대형 구장에서 이전하면 규모 선택의 현재 좌석도 새 도시 실제 기본 좌석이다 [이전구장검수]',()=>{ const {S,id}=r464_prep(); S.cap=30600; S.nk='mega'; S.ncap=30000; S.mega=true; S.mx=5000; clubRebrand(id,{city:'제주'}); ok(stadCap(id)===17000&&newStadBase(id)===17000&&newStadKind(id)!=='mega','설계 규모 잔존 '+newStadLimTxt(id)); });
T('[검수 11-18 #472] 같은 이전 도시는 옛 구장 규모와 무관하게 같은 기본 좌석을 쓴다 [이전구장검수]',()=>{ const caps=[]; for(const cap of [23000,16000]){ const {S,id}=r464_prep(); S.cap=cap; clubRebrand(id,{city:'제주'}); caps.push(stadCap(id)); } ok(caps[0]===17000&&caps[1]===17000,'출발 구장 의존 '+caps); });
T('[검수 11-18 #473] 옛 구장 담장 공사 제한은 새 구장 첫 공사를 막지 않는다 [이전구장검수]',()=>{ const {S,id}=r464_prep(); S.fenceY=sponSeason(); S.fenceH=[{y:G.year,d:G.day-1}]; clubRebrand(id,{city:'제주'}); const D={...stadDim(id),cf:128}; ok(fenceSet(D)==='','새 담장 공사 차단'); ok(S.fenceH.length===2,'옛 담장 이력 손실'); });
T('[검수 11-18 #474] 이전 뒤 관중 일일 보관과 증설 심사에 옛 구장 매진이 살아나지 않는다 [이전구장검수]',()=>{ const {S,id}=r464_prep(); G.day=G.cal.end+1; G.sea.att={[id]:{n:72,sum:1512000,cap:1728000,so:58}}; S.xd={y:G.year,occ:.875,n:72,so:58}; S.xdh=[S.xd]; clubRebrand(id,{city:'제주'}); G.day++; stadXpDaily(); ok(!S.xd&&stadXpDem(id)===null,'옛 실적 재생 '+JSON.stringify(S.xd)); ok(G.sea.att[id].n===72,'재정용 시즌 관중을 지움'); });
T('[검수 11-18 #475] 관중 결산은 이전 전 관중의 실제 구장 이름을 발표한다 [이전구장검수]',()=>{ const {S,id,from}=r464_prep(); G.sea.att={[id]:{n:72,sum:1512000,cap:1728000,so:58}}; const old=stadName(id); clubRebrand(id,{city:'원주'}); let body=''; const M=mail; try{ mail=(a,b,c)=>{body=c;}; stadSeasonNote(); }finally{mail=M;} ok(body.includes(old),'옛 장소 누락 '+body); ok(!body.includes('올해 원주 야구장 홈 72경기'),'새 장소로 오보'); });
