T('[검수 11-18 #464·#466] 사람과 AI의 결산 전후 이전 현금 장부는 예산과 실제 결산에 한 번 반영되고 정리된다 [이전구장검수]',()=>{ for(const ai of [false,true])for(const after of [false,true]){ const P=r464_prep(), t=ai?G.teams.find(x=>x.id!==G.user&&!x.indie):P.t, id=t.id, S=stadOf(id); t.indie=false; t.cash=30000; S.build=[{k:'fnb',lv:3,st:G.day-30,done:G.day+60,c:1200}]; S.xq=null; S.proj=null; S.debt={cost:9000,paid:6000}; if(after)G.last={y:G.year}; const fy=fyNow(), base=t.cash; clubRebrand(id,{city:'제주'}); const H=G.hoL[fy+':'+id]; ok(H.net===-100&&t.cash===base-100,'즉시 현금 '+ai+'/'+after); if(!ai){ const B=budget(); ok(B.exp.some(r=>r[0].includes('일시 정산')&&r[1]===3000)&&B.inc.some(r=>r[0]==='연고 이전 공사 환급'&&r[1]===800),'예산 명세 누락'); } if(after){ G.year++; G.sea.y=G.year; } r464_ps(); settlement(); const F=G.last.fins[id]; ok(F.exp.filter(r=>r[0].includes('일시 정산')).length===1&&F.exp.find(r=>r[0].includes('일시 정산'))[1]===3000,'분담금 결산 중복'); ok(F.inc.find(r=>r[0]==='연고 이전 공사 환급')[1]===800,'환급 결산 누락'); ok(Math.abs(F.cash-(base+F.net-(F.div||0)-(F.sweep||0)))<1e-6,'결산 이중 현금 '+F.cash); ok(!G.hoL[fy+':'+id],'사용 장부 미정리'); } });
