T('[검수 11-18 #482] 실제 반려 당일 재설득은 약속 비용 전에 착공하고 대기 제한은 유지한다 [구단주교섭검수]',()=>{fresh();facInit();const t=team(G.user);t.indie=false;t.trust=70;const k=FACK.find(k=>!facCanStart(G.user,k)),cash=t.cash,oldOdds=capexOdds;try{capexOdds=()=>0;capexAsk('fac',k);}finally{capexOdds=oldOdds;}const e=G.evs.find(e=>e.k==='opush'&&!e.done);ok(e,'준비 실패: 실제 반려 안건');const i=e.data.args.indexOf('promise');ok(i>=0,'준비 실패: 약속');const tr=t.trust,n=opSt(t.id).prom.length;OP_TEST=[0];try{ok(evPick(e.id,i)==='다시 설득했습니다.','재설득 실패');}finally{OP_TEST=null;}ok(G.fac.bld[k]&&G.fac.bld[k].cap,'성공했는데 공사가 없음');ok(t.cash===cash&&t.trust===tr-1&&opSt(t.id).prom.length===n+1,'비용/약속 불일치');ok(t.capexY===sponSeason()&&capexWait(t.id)>G.day,'재요청 제한/연간 횟수 누락');ok((G.fac.hist||[]).filter(h=>h.k===k&&h.src==='cap').length===1,'착공 이력 중복');});
T('[검수 11-18 #482] 착공이 막힌 성공 판정은 신뢰 약속 경고를 남기지 않는다 [구단주교섭검수]',()=>{fresh();facInit();const t=team(G.user),k=FACK.find(k=>!facCanStart(G.user,k));ownPushOffer({k:'cap',fk:k,amt:FACI[k].c[G.fac.it[k]+1]},'시설 반려','본문');const e=G.evs.find(e=>e.k==='opush'&&!e.done),i=e.data.args.indexOf('promise'),tr=t.trust,before=JSON.stringify(opSt(t.id)),ask=capexAsk;capexAsk=()=> '착공을 시작할 수 없습니다.';OP_TEST=[0];try{evPick(e.id,i);}finally{OP_TEST=null;capexAsk=ask;}ok(t.trust===tr&&JSON.stringify(opSt(t.id))===before&&!G.fac.bld[k],'착공 없이 비용/약속 발생');ok(!G.mail.some(m=>m.subj.startsWith('구단주 승인(재설득)')),'착공 없이 성공 메일');});
T('[검수 11-18 #483] 회장이 바뀌면 전임 반려 시설 자금 안건은 직접 자동 선택 모두 무효 [구단주교섭검수]',()=>{fresh();facInit();const tid=G.user,t=team(tid),k=FACK.find(k=>!facCanStart(tid,k));ownPushOffer({k:'cap',fk:k,amt:FACI[k].c[G.fac.it[k]+1]},'시설 반려','본문');const cap=G.evs.find(e=>e.k==='opush'&&!e.done);const g={y:sponSeason(),d:G.day,amt:1000,pur:null,ok:false,by:'gm',st:'no',tid};grantAdd(g);ownPushOffer({k:'fund',amt:1000},'자금 반려','본문',g);const fund=G.evs.filter(e=>e.k==='opush'&&!e.done).at(-1);G.day++;o482_change(tid);const tr=t.trust,cash=t.cash;for(const e of [cap,fund]){ok(e.done&&e.void||EVH.opush.can(e,0),'전임 카드가 활성 상태');OP_TEST=[0];try{EVH.opush.pick(e,0);}finally{OP_TEST=null;}}ok(t.trust===tr&&t.cash===cash&&!G.fac.bld[k]&&!g.ok,'전임 안건 실행으로 새 회장 비용/투자');ok(opLevel(tid)===0,'전임 카드로 경고 누적');});
T('[검수 11-18 #484 #485] 사람 AI 모두 교체 후 경고 성적 약속 사퇴 기억이 현 회장별로 분리 [구단주교섭검수]',()=>{fresh();for(const t of [team(G.user),G.teams.find(t=>t.id!==G.user&&!t.indie)]){const ctx={k:'fund',amt:1000};t.trust=60;opRun(t.id,ctx,{k:'fan',s:.8},[.99]);opRun(t.id,ctx,{k:'promise',s:.8,y:sponSeason(),tgt:3,l:'3위'},[0]);opRun(t.id,ctx,{k:'resign',s:1},[0]);ok(opLevel(t.id)===2&&!opPromiseOf(t.id),'준비 실패: 경고/약속');G.day++;o482_change(t.id);ok(opLevel(t.id)===0&&!opRecent(t.id).length,'전임 경고가 새 회장에 남음');ok(opPromiseOf(t.id)&&!opResignWhy(t.id),'전임 약속/사퇴 카드를 새 회장에 적용');ok(opPromSettle(t.id,sponSeason(),7)===0,'전임 약속이 신임 신뢰를 깎음');const r=opRun(t.id,ctx,{k:'fan',s:.8},[.99,0]);ok(!r.out&&opLevel(t.id)===1,'새 회장 첫 반려가 사퇴 권고');}});
T('[검수 11-18 #483 #484 #485] 구버전 기록은 소유권 이력으로 귀속하고 재복구는 난수 없이 동일 [구단주교섭검수]',()=>{fresh();const tid=G.user;facInit();const k=FACK.find(k=>!facCanStart(tid,k));ownPushOffer({k:'cap',fk:k,amt:FACI[k].c[G.fac.it[k]+1]},'시설 반려','본문');const e=G.evs.find(e=>e.k==='opush'&&!e.done);opRun(tid,{k:'fund',amt:1000},opPromiseOf(tid),[0]);opRun(tid,{k:'fund',amt:1000},{k:'fan',s:.8},[.99]);const S=opSt(tid);G.day++;o482_change(tid);for(const x of [...S.L,...S.prom,...(S.rs||[]),S.warn,e.data,e.data.ctx].filter(Boolean)){delete x.ownerId;delete x.owner;}e.done=false;delete e.void;G=JSON.parse(JSON.stringify(G));const rng=__rngState();ok(opLevel(tid)===0&&opPromSettle(tid,sponSeason(),8)===0,'구버전 전임 기록 귀속 실패');ok(EVH.opush.can(G.evs.find(z=>z.id===e.id),0),'구버전 전임 안건 실행 가능');const a=JSON.stringify(G);opLevel(tid);opPromSettle(tid,sponSeason(),8);ok(JSON.stringify(G)===a&&__rngState()===rng,'재복구가 난수/상태를 바꿈');});
T('[검수 11-18 #493] 신뢰 경고는 현 구단 현 회장의 최신 보고만 인용 [구단주교섭검수]',()=>{fresh();const tid=G.user,t=team(tid);G.ownerLog=[{d:G.day,txt:'전임 회장 비용 절감'}];G.trW={tid,ownerId:bossOf(tid).own.id,lv:2,fy:G.year};G.day++;o482_change(tid);t.trust=20;ownerTrustWatch();let m=G.mail.find(m=>m.subj.includes('경고')&&m.body.includes('구단주 신뢰'));ok(m&&!m.body.includes('전임 회장 비용 절감'),'신임 경고 억제 또는 전임 지시 인용');G.ownerLog.unshift({tid,ownerId:bossOf(tid).own.id,d:G.day,txt:'신임 회장 보고'});G.ownerLog.unshift({tid:G.teams.find(t=>t.id!==tid).id,ownerId:bossOf(tid).own.id,d:G.day,txt:'다른 구단 보고'});G.trW=null;ownerTrustWatch();m=G.mail.find(m=>m.subj.includes('경고')&&m.body.includes('신임 회장 보고'));ok(m&&!m.body.includes('다른 구단 보고'),'현재 회장 최신 보고 선택 실패');});

const f486_setup=(ai=false)=>{fresh();ownershipInit();const id=ai?G.teams.find(t=>t.id!==G.user&&!t.indie).id:G.user;const ids=[id,...G.teams.map(t=>t.id).filter(x=>x!==id)],order=ids.map((tid,i)=>({tid,w:90-i*4,l:54+i*4,t:0}));for(const o of order)G.sea.rec[o.tid]={w:o.w,l:o.l,t:0};G.day=G.cal.end+25;G.ps={order,seeds:ids.slice(0,5),champ:ids[0],runner:ids[1],res:{wc:[ids[3],ids[4],1,0],spo:[ids[2],ids[3],3,1],po:[ids[1],ids[2],3,1],ks:[ids[0],ids[1],4,2]},done:true,finDay:G.day};for(const t of G.teams)t.trust=80;asSnap();return id;};
const f486_change=(tid,policy)=>{const s=G.ownership.clubs[tid],g=s.generation+1;let seed='';for(let i=0;i<100;i++){const k='f486:'+i;if(['win','pr','profit'][Math.floor(seededRand(k+':'+g+':policy')()*3)]===policy){seed=k;break;}}ok(seed,'승계 성향 준비');ownershipReplace(tid,{id:'f486-owner',fy:G.year+1,seed},false);};
T('[검수 11-18 #486] 인수 출자는 영업 흑자와 유보금 회수에서 제외한다 [재정결산검수]',()=>{const tid=f486_setup();team(tid).cash=10000;const s=JSON.stringify(G);withRng(486,()=>settlement());const a=G.last.fins[tid];G=JSON.parse(s);ownershipCapital(tid,'f486-cap',2000,'인수기업 운영자금');withRng(486,()=>settlement());const b=G.last.fins[tid];ok(b.cash-a.cash===2000,'출자 2000 중 실제 현금 증가 '+(b.cash-a.cash));ok(b.back===a.back&&b.sweep===a.sweep,'출자를 흑자/유보금 회수');});
T('[검수 11-18 #486 AI] 적자 AI의 인수 출자도 부채지원과 회수 계산에 섞지 않는다 [재정결산검수]',()=>{const tid=f486_setup(true);team(tid).cash=-50000;const s=JSON.stringify(G);withRng(4861,()=>settlement());const a=G.last.fins[tid];G=JSON.parse(s);ownershipCapital(tid,'f486-ai',2000,'인수기업 운영자금');withRng(4861,()=>settlement());const b=G.last.fins[tid];ok(b.cash-a.cash===2000,'AI 출자 증가 '+(b.cash-a.cash));ok(b.support===a.support,'출자가 기존 부채 지원을 상쇄');});
T('[검수 11-18 #487] 같은 지원 정책의 재확정은 승인한 지원 목표를 더 늘리지 않는다 [재정결산검수]',()=>{fresh();ownershipInit();setGoals();const t=team(G.user),fy=sponSeason(),pct=ownershipSupportPct(t,fy),a=budget().goalSup;grantApply(2000);const b=budget().goalSup;ownershipSetSupport(G.user,pct,fy);const c=budget().goalSup;ok(Math.abs(b-a-2000)<=1,'최초 추가 지원 목표 불일치');ok(Math.abs(c-b)<=1,'재확정 뒤 추가 승인 없이 목표 '+(c-b)+' 증가');});
T('[검수 11-18 #488] 시즌 중 구단주 승계 후에도 우승 보너스는 약속한 시즌 기준이다 [재정결산검수]',()=>{const tid=f486_setup();team(tid).owner='profit';G.goals={...(G.goals||{}),y:G.year,owner:'profit',rank:5,sup:.6,fan:50};f486_change(tid,'win');withRng(488,()=>settlement());const f=G.last.fins[tid],paid=(f.inc.find(x=>x[0]==='모기업 우승 보너스')||[0,0])[1];ok(paid===Math.round(G.last.pool*.5*.6),'우승보너스에 신임 구단주 기준 적용 '+paid);});
T('[검수 11-18 #489] 결산 다음날 승계가 끝난 AI 시즌의 우승 포상을 바꾸지 않는다 [재정결산검수]',()=>{const tid=f486_setup(true);team(tid).owner='profit';withRng(489,()=>settlement());const h=G.history[G.history.length-1];G.day++;f486_change(tid,'win');const cash=team(tid).cash;aiOwnerYear(h);ok(team(tid).cash===cash,'종료 시즌에 새 구단주 FA 포상 추가 '+(team(tid).cash-cash));});
T('[검수 11-18 #490] 모기업 기말현금 전망은 흑자 조정과 유보금 회수를 표시한다 [재정결산검수]',()=>{fresh();const t=team(G.user);t.cash=60000;t.owner='win';const b=budget(),pre=t.cash+b.I+b.support-b.E,rate=.4+(HARD()?.1:0),back=Math.min(Math.round(Math.max(0,b.I+b.support-b.E)*rate),Math.max(0,Math.round(pre))),sweep=Math.round(Math.max(0,pre-back-Math.round(RES_CAP*ecoIdx(sponSeason())))*RES_RATE);ok(b.sweepEst===sweep&&sweep>0,'유보금 회수 전망 없음 '+b.sweepEst+'/'+sweep);ok(b.endCash===pre-back-sweep,'회수 후 기말현금 불일치');});
T('[검수 11-18 #491] 독립구단 배당 전망은 결산 회계연도의 경제 지수를 쓴다 [재정결산검수]',()=>{fresh();G.year=2028;G.day=dnum(2028,6,1);const t=team(G.user);t.indie=true;t.cash=60000;G.spend.etc=40000;const b=budget(),raw=t.cash+b.I+b.support-b.E;ok(b.I-b.E<0&&raw>INDIE_DIV_T*ecoIdx(2028),'배당 경계 준비 실패');const div=Math.round((raw-Math.round(INDIE_DIV_T*ecoIdx(2028)))*INDIE_DIV_R);ok(b.divEst===div&&b.endCash===raw-div,'경제 지수 배당 불일치 '+b.divEst+'/'+div);});
T('[검수 11-18 #492] 하드 모드 독립구단 흑자 배당 명세는 실제 60퍼센트다 [재정결산검수]',()=>{const tid=f486_setup();const t=team(tid);t.indie=true;t.cash=100000;G.cfg={...(G.cfg||{}),hard:true};G.sea.att=G.sea.att||{};G.sea.att[tid]={n:72,sum:17000*72,cap:17000*72,so:72,best:17000,tk:90000,fb:0,pn:72,pm:0,ad:0,up:0};withRng(492,()=>settlement());const f=G.last.fins[tid],r=f.exp.find(x=>x[0].startsWith('투자사 배당'));ok(r&&r[1]>0,'배당 발생 준비');ok(r[0].includes('60%'),'실제60퍼센트 배당 명세 '+r[0]);});
T('[검수 11-18 #488 전망] 우승 보너스 예상도 합의한 시즌 구단주 기준을 쓴다 [재정결산검수]',()=>{const tid=f486_setup();team(tid).owner='profit';G.goals={...(G.goals||{}),y:G.year,owner:'profit',rank:5,sup:.6,fan:50};f486_change(tid,'win');const b=budget(),r=b.inc.find(x=>x[0]==='모기업 우승 보너스(예상)');ok(r&&r[1]===Math.round(14500*.6*.5*.6),'예상 보너스에 새 성향 적용 '+JSON.stringify(r));});
T('[검수 11-18 #487 호환] 옛 추가지원 목표의 기본 비율은 기존 확정 장부에서 복원한다 [재정결산검수]',()=>{fresh();ownershipInit();setGoals();budget();grantApply(2000);const lock=G.bLocks[G.user],gf=lock.gf;delete G.goals.baseSup;team(G.user).trust-=10;const rng=__rngState();budget();ok(G.goals.baseSup===gf,'기존 확정 기본 비율을 현재 한도로 역산');const s=JSON.stringify(G.goals);budget();ok(JSON.stringify(G.goals)===s&&__rngState()===rng,'기본 지원 복원 멱등/난수');});
T('[검수 11-18 #489 호환] 구버전 결산의 구단주 기준도 승계 이력에서 찾는다 [재정결산검수]',()=>{const tid=f486_setup(true);team(tid).owner='profit';withRng(4891,()=>settlement());const h=G.history[G.history.length-1];delete h.fins[tid].owner;delete h.fins[tid].ownerId;G.day++;f486_change(tid,'win');const cash=team(tid).cash;aiOwnerYear(h);ok(team(tid).cash===cash,'옛 결산에 신임 포상 지급');});

T('[검수 11-18 #468·#470] 이전 후 단장 헌정 이름만 받은 옛 구장은 신축으로 오인하지 않고 이름을 보존해 복구한다 [이전구장검수][헌정구장복구]',()=>{ const {t,S,id}=r464_legacy(); S.mega=true; S.mx=5000; S.nk='mega'; S.ncap=30000; S.debt={cost:9000,paid:3000}; G.gmLeg=G.gmLeg||{}; legStadSet(id,'검수 단장 기념 구장'); const cash=t.cash, rng=globalThis.__rngState(); ciMigrate(); ok(S.name==='검수 단장 기념 구장','헌정 이름 손실'); ok(S.dome===false&&!S.mega&&!S.nk&&S.built===G.year,'명명 이력을 신축으로 오인'); ok(!S.debt&&t.cash===cash-1800,'옛 구장 분담금 미정산'); const save=JSON.stringify(G); ciMigrate(); ok(JSON.stringify(G)===save&&globalThis.__rngState()===rng,'복구 반복 또는 난수 사용'); });

T('[검수 11-18 #476·#477] 이름 시작일 복구 전에도 실제 이전 연대기로 보조금·신청 도시를 판단한다 [연고행정검수]',()=>{ fresh(); facInit(); const t=team(G.user), old=t.city, move=dnum(G.year,11,20), ask=move-10; G.day=move+10; t.city='제주'; t.facAsk={city:ask}; delete t.facAskCity; delete t.facAskCities; t.cityOb=[{k:'indoor',y0:G.year,d:ask,y1:G.year+3,help:400,prog:30,miss:0}]; G.fac.hist=[]; const S=stadOf(t.id); delete S.reloc; G.tnames={[t.id]:[{y0:-Infinity,city:old,nick:t.nick},{y0:G.year+1,city:'제주',nick:t.nick}]}; G.chron.push({tid:t.id,y:G.year+1,d:move,k:'rebrand',t:'연고 이전',source:'rebrand:'+t.id+':'+(G.year+1)}); const rng=__rngState(); ciMigrate(); ok(G.tnames[t.id][1].d0===move,'실제 이전일 복구 실패'); ok(t.cityOb[0].city===old,'시작일 복구 전 보조금을 새 도시로 잘못 확정'); ok(facRouteWait(t.id,'city')===0&&t.facAskCities[old]===ask,'시작일 복구 전 신청 대기를 새 도시로 승계'); const before=JSON.stringify({grant:t.cityOb,ask:t.facAsk,cities:t.facAskCities,scope:t.facAskCity}); ciMigrate(); ok(JSON.stringify({grant:t.cityOb,ask:t.facAsk,cities:t.facAskCities,scope:t.facAskCity})===before&&__rngState()===rng,'복구 반복·난수 부작용'); });
const cr494_c=(role,o)=>Object.assign(mkCoach(role),{ob:null,res:null,age:50,from:null,fromY:null,clan:null,sal:60,sk:80,dv:80,raidSafe:0},o||{});
const cr494_offer=(c,tid,sal)=>({id:c.id,role:c.role,tid,to:c.role,sal:sal??c.sal,exp:G.day+7,from:G.user,occ:coachSeatId(tid,c.role)});
const cr494_axprep=tid=>{const a=axSlots,b=pcN,p=planOf;axSlots=()=>1;pcN=()=>0;planOf=()=> 'win';team(tid).cash=10000;orgOf(tid).coachX=[];return ()=>{axSlots=a;pcN=b;planOf=p;};};
T('[검수 11-18 #494] 빈자리 65세 계약은 우리 AI 모두 1년이며 본 난수를 보존 [코치계약검수]',()=>{fresh();const A=otherT();for(const tid of [G.user,A]){G.coach[tid].pc=null;let c;for(let i=0;i<40;i++){c=cr494_c('pc',{age:65});if(withRng(cvacSeed('yrs',tid,c.id),()=>ri(1,3))>1)break;}G.cmarket=[c];const r=__rngState();const h=cvacHire(tid,c);ok(h===c&&c.yrs===1,'65세 자동 계약 실패/다년: '+tid+' / '+c.yrs);ok(__rngState()===r,'본 난수 사용');}});
T('[검수 11-18 #495] AI 겨울 64세부터 1년 재계약 [코치계약검수]',()=>{fresh();const A=otherT();G.day=KD(11,15);for(const t of G.teams)for(const c of Object.values(G.coach[t.id]))if(c){c.age=50;c.yrs=5;delete c.ob;}const c=cr494_c('pc',{age:64});staffCt(c,1,G.year);G.coach[A].pc=c;G.cmarket=[];const vac=coachVacRound,refresh=refreshCoachMarket;coachVacRound=()=>[];refreshCoachMarket=()=>{};try{let seed;for(let i=0;i<100;i++)if(withRng(i,()=>R()<.55&&ri(1,2)===2)){seed=i;break;}ok(seed!=null,'준비 실패: 난수');withRng(seed,()=>coachYear());ok(G.coach[A].pc===c&&c.yrs===1,'65세 겨울 재계약 '+c.yrs+'년');}finally{coachVacRound=vac;refreshCoachMarket=refresh;}});
T('[검수 11-18 #496] 보조 코치도 은퇴 나이 거절 고령 1년 AI 동일 [코치계약검수]',()=>{fresh();const A=otherT(),slots=axSlots;axSlots=()=>3;G.coachX=[];try{for(const [age,y] of [[70,3],[65,2]]){const c=cr494_c('pc',{age});G.cmarket=[c];ok(hireAsst(c.id,y)&&!G.coachX.includes(c)&&G.cmarket.includes(c),'고령 보조 계약 허용 '+age);}const c=cr494_c('pc',{age:65});G.cmarket=[c];ok(!hireAsst(c.id,1)&&c.yrs===1,'65세 1년 거절');}finally{axSlots=slots;}const restore=cr494_axprep(A);try{const c=cr494_c('pc',{age:65});G.cmarket=[c];let seed;for(let i=0;i<100;i++)if(withRng(i,()=>R()<=.5&&ri(1,3)>1)){seed=i;break;}ok(seed!=null,'준비 실패: 난수');withRng(seed,()=>aiAsstMonthly(A,true));ok(axOf(A).includes(c)&&c.yrs===1,'AI 65세 보조 다년/미영입 '+c.yrs);}finally{restore();}});
T('[검수 11-18 #497] 보조 채용도 제3구단 우선 협상권을 지키고 본인 구단만 영입 [코치계약검수]',()=>{fresh();const [A,B]=G.teams.filter(t=>t.id!==G.user).map(t=>t.id),slots=axSlots;axSlots=()=>3;G.coachX=[];try{const c=cr494_c('pc',{res:A});G.cmarket=[c];ok(hireAsst(c.id,1)&&G.cmarket.includes(c),'우리 보조가 타 구단 우선 협상 우회');}finally{axSlots=slots;}const restore=cr494_axprep(A);try{const c=cr494_c('pc',{res:B});G.cmarket=[c];for(let i=0;i<30;i++)withRng(i,()=>aiAsstMonthly(A,true));ok(!axOf(A).includes(c)&&G.cmarket.includes(c),'AI 보조가 제3구단 우선 협상 우회');c.res=A;for(let i=0;i<30&&!axOf(A).length;i++)withRng(i,()=>aiAsstMonthly(A,true));ok(axOf(A).includes(c),'본인 우선 협상 거절');}finally{restore();}});
T('[검수 11-18 #498] 65세 현직 코치 직접 영입과 제안 수락 모두 1년 [코치계약검수]',()=>{fresh();G.day=KD(12,1);const A=otherT(),counter=cmCounter,terms=poachTerms,vac=coachVacFill;cmCounter=()=>null;poachTerms=(...a)=>{const t=terms(...a);if(t)t.chance=1;return t;};coachVacFill=()=>[];try{const c=cr494_c('pc',{age:65});staffCt(c,2,G.year);G.coach[A].pc=c;poachCoach(A,'pc','pc');ok(G.coach[G.user].pc===c&&c.yrs===1,'직접 영입 65세 '+c.yrs+'년');const d=cr494_c('pc',{age:65});staffCt(d,2,G.year);G.coach[G.user].pc=d;G.coach[A].pc=null;G.cmRaid=[cr494_offer(d,A)];cmLet(d.id);ok(G.coach[A].pc===d&&d.yrs===1,'제안 수락 65세 '+d.yrs+'년');}finally{cmCounter=counter;poachTerms=terms;coachVacFill=vac;}});
T('[검수 11-18 #498] AI끼리도 65세 코치를 승격 영입할 때 1년 [코치계약검수]',()=>{fresh();G.day=KD(12,1);const [A,B]=G.teams.filter(t=>t.id!==G.user).map(t=>t.id),vac=coachVacRound,fill=coachVacFill,score=cmScore,plan=stAiPlan;coachVacRound=()=>[];coachVacFill=()=>[];cmScore=(c,tid)=>tid===B?1000:0;stAiPlan=()=>({rich:1});G.teams=G.teams.filter(t=>[G.user,A,B].includes(t.id));const c=cr494_c('pc',{age:65,sk:90,dv:90});staffCt(c,2,G.year);G.coach[A]={pc:c};G.coach[B]={hc:cr494_c('hc',{sk:40,dv:40})};G.cmarket=[];try{for(let i=0;i<100&&G.coach[A].pc===c;i++)withRng(i,()=>cmAiMonthly());ok(G.coach[B].hc===c&&c.yrs===1,'AI 65세 승격 영입 '+c.yrs+'년');}finally{coachVacRound=vac;coachVacFill=fill;cmScore=score;stAiPlan=plan;}});
T('[검수 11-18 #499] 은퇴 나이 코치는 제안 생성과 낡은 제안 수락에서 제외 [코치계약검수]',()=>{fresh();G.day=KD(12,1);const A=otherT(),c=cr494_c('pc',{age:71,sk:99,dv:99,amb:99,loy:0});staffCt(c,2,G.year);G.coach[G.user]=Object.fromEntries(CKEYS.map(k=>[k,k==='pc'?c:null]));for(const t of G.teams)if(t.id!==G.user)G.coach[t.id]=Object.fromEntries(CKEYS.map(k=>[k,null]));for(let i=0;i<100;i++)withRng(i,()=>cmRaid());ok(!G.cmRaid.some(r=>r.id===c.id),'71세 현직 제안 생성');G.cmRaid=[cr494_offer(c,A)];cmLet(c.id);ok(G.coach[G.user].pc===c&&G.coach[A].pc!==c,'71세 낡은 제안 수락');});
T('[검수 11-18 #500] AI 제안 생성과 수락은 실제 제안 연봉 여력을 재검사 [코치계약검수]',()=>{fresh();G.day=KD(12,1);const A=otherT(),c=cr494_c('pc',{sal:800,sk:99,dv:99,amb:99,loy:0}),plan=stAiPlan;stAiPlan=()=>({rich:-5});staffCt(c,2,G.year);G.coach[G.user]=Object.fromEntries(CKEYS.map(k=>[k,k==='pc'?c:null]));for(const t of G.teams)if(t.id!==G.user)G.coach[t.id]=Object.fromEntries(CKEYS.map(k=>[k,null]));try{for(let i=0;i<100;i++)withRng(i,()=>cmRaid());ok(!G.cmRaid.some(r=>r.id===c.id),'감당 불가 고액 제안 생성');G.cmRaid=[cr494_offer(c,A,960)];const cash=team(A).cash,sp=JSON.stringify(G.spend);cmLet(c.id);ok(G.coach[G.user].pc===c&&G.coach[A].pc!==c&&team(A).cash===cash&&JSON.stringify(G.spend)===sp,'여력 없는 낡은 제안 수락/정산');}finally{stAiPlan=plan;}});
T('[검수 11-18 #518] 직접 이적도 전 소속 기본 충성도 대신 15로 새 출발 [코치계약검수]',()=>{fresh();G.day=KD(12,1);const A=otherT(),counter=cmCounter,terms=poachTerms,vac=coachVacFill;cmCounter=()=>null;poachTerms=(...a)=>{const t=terms(...a);if(t)t.chance=1;return t;};coachVacFill=()=>[];try{const c=cr494_c('pc',{loy:98});staffCt(c,2,G.year);G.coach[A].pc=c;poachCoach(A,'pc','pc');ok(G.coach[G.user].pc===c&&coachSupportView(c,G.user).base===15,'직접 이적 충성도 '+c.loy);}finally{cmCounter=counter;poachTerms=terms;coachVacFill=vac;}});
T('[검수 11-18 #519] 노리는 구단은 월간 채용 협상/시즌/계약중 교체 기준과 일치 [코치계약검수]',()=>{fresh();G.day=G.cal.open+20;const A=otherT(),c=cr494_c('pc',{sk:55,dv:55}),cur=cr494_c('pc',{sk:50,dv:50});staffCt(cur,2,G.year);for(const t of G.teams)if(t.id!==G.user&&t.id!==A)G.coach[t.id].pc=cr494_c('pc',{sk:99,dv:99});G.coach[A].pc=cur;c.bid={exp:G.day+3};ok(!cmRivals(c).some(x=>x.tid===A),'협상 중 후보 경쟁 표시');delete c.bid;ok(!cmRivals(c).some(x=>x.tid===A),'시즌 +10 경쟁 표시');c.sk=65;ok(cmRivals(c).some(x=>x.tid===A),'시즌 +20 합법 후보 누락');G.day=KD(12,1);c.sk=56;c.dv=56;ok(!cmRivals(c).some(x=>x.tid===A),'비시즌 유계약 +12 경쟁 표시');cur.yrs=0;ok(cmRivals(c).some(x=>x.tid===A),'비시즌 만료 +12 합법 후보 누락');});

const co501_setup=(o={})=>{ fresh(); G.day=G.cal.end+10; G.poachN={}; G.cmRaid=[]; const tid=G.teams.find(t=>t.id!==G.user).id; const c=mkCoach('pc'); Object.assign(c,{sal:100,age:48,sk:85,dv:85,loy:20,raidSafe:0,...o}); staffCt(c,3,G.year); G.coach[G.user].pc=c; G.coach[tid].pc=null; const r={id:c.id,role:'pc',tid,to:'pc',sal:155,exp:G.day+7,from:G.user,occ:null}; G.cmRaid=[r]; return {c,tid,r}; };
T('[검수 11-18 #501] 연장 보호를 수락 직전 다시 검사한다 [코치제안검수]',()=>{ const {c,tid}=co501_setup(); c.raidSafe=G.day+365; const a=JSON.stringify(G.spend),cash=team(tid).cash; cmLet(c.id); ok(G.coach[G.user].pc===c&&G.coach[tid].pc===null,'보호 코치가 옛 제안으로 이적'); ok(JSON.stringify(G.spend)===a&&team(tid).cash===cash,'무효 제안 정산'); ok(!G.cmRaid.length,'무효 제안 남음'); });
T('[검수 11-18 #502] 옛 메일은 같은 코치의 새 제안을 처리하지 않는다 [코치제안검수]',()=>{ const {c,tid,r}=co501_setup(); const old=typeof cmRaidValue==='function'?cmRaidValue(r):c.id+'::'+r.exp; const dest=G.teams.find(t=>t.id!==G.user&&t.id!==tid).id; G.coach[dest].pc=null; G.cmRaid=[{...r,tid:dest}]; ok(!mailLiveAct({},{a:'cmLet',v:old}),'옛 메일이 새 업무로 남음'); const co501_body=globalThis.__co501Actions().split('cmLet(v){')[1].split('save(); render(); },')[0]; const co501_act=eval('({cmLet(v){'+co501_body+'save(); render(); }})'); const save=()=>{},toast=()=>{},render=()=>{}; co501_act.cmLet(old); ok(G.coach[G.user].pc===c&&G.cmRaid.length===1,'옛 메일이 새 제안 수락'); const co501_keepBody=globalThis.__co501Actions().split('cmKeep(v){')[1].split('}, cmLet(v){')[0]; const co501_keep=eval('({cmKeep(v){'+co501_keepBody+'}})'); const sal0=c.sal; co501_keep.cmKeep(typeof cmRaidValue==='function'?cmRaidValue(r,'1'):c.id+':1:'+r.exp); ok(c.sal===sal0&&G.cmRaid.length===1,'옛 붙잡기 버튼이 새 제안 처리'); if(typeof cmRaidValue==='function'){ const prev=G.cmRaid[0],before=cmRaidValue(prev); G.cmRaid=[{...prev,key:'co501-reissued'}]; cmLet(before); ok(G.coach[G.user].pc===c&&G.cmRaid.length===1,'같은 날 같은 조건의 새 제안을 옛 메일이 수락'); } const now=G.cmRaid[0]; const token=typeof cmRaidValue==='function'?cmRaidValue(now):c.id; cmLet(token); ok(G.coach[dest].pc===c,'현재 메일 수락 실패'); });
T('[검수 11-18 #503] 옛 제안의 알 수 없는 현직은 현재 현직으로 추정하지 않는다 [코치제안검수]',()=>{ const {c,tid,r}=co501_setup(); delete r.occ; const x=mkCoach('pc'); x.age=45; staffCt(x,4,G.year); G.coach[tid].pc=x; const cash=team(tid).cash,sp=JSON.stringify(G.spend); coachRulesMigrate(); const before=JSON.stringify(G.cmRaid); coachRulesMigrate(); ok(JSON.stringify(G.cmRaid)===before,'복구 멱등성'); cmLet(c.id); ok(G.coach[G.user].pc===c&&G.coach[tid].pc===x&&x.yrs===4,'새 현직을 옛 제안의 현직으로 둔갑'); ok(team(tid).cash===cash&&JSON.stringify(G.spend)===sp,'무효 제안 정산'); });
T('[검수 11-18 #504] 유효한 역제안 조건은 일반·사단 코치 모두 확정 수락한다 [코치제안검수]',()=>{ for(const clan of [false,true]){ const {c,tid}=co501_setup(); G.coach[G.user].pc=null; G.coach[tid].pc=c; if(clan)c.clan=G.mgr[tid].id; G.poachCtr={[c.id]:{tid,by:G.user,to:'pc',need:155,exp:G.day+5}}; const R0=FO_RNG; try{FO_RNG=()=>.999999; const msg=poachCoach(tid,'pc','pc'); ok(G.coach[G.user].pc===c&&c.sal===155,'맞춘 조건 거절: '+msg); }finally{FO_RNG=R0;} } });
T('[검수 11-18 #505] 역제안 생성은 실제 계약 연봉을 바꾸지 않는다 [코치제안검수]',()=>{ const {c,tid}=co501_setup(); const R0=FO_RNG,P=stAiPlan; try{ FO_RNG=()=>0; stAiPlan=()=>({rich:1}); const sal=c.sal; for(const toRole of ['pc','hc']){ const msg=cmCounter(tid,c,{sal:135,toRole}); ok(msg&&c.sal===sal,'역제안만으로 실제 연봉 인상'); G.day+=6; } }finally{FO_RNG=R0;stAiPlan=P;} });
T('[검수 11-18 #506] 코치 보상금은 선수 보상금과 분리하고 예산·결산·이직에서 한 번만 잡는다 [코치제안검수]',()=>{ const {c,tid}=co501_setup(); const cash=team(tid).cash,comp=coachPoachComp(c),b0=budget().I; const old=G.spend.compIn||0; cmLet(c.id); ok(G.coach[tid].pc===c,'이적 준비'); ok(G.spend.coachCompIn===comp&&(G.spend.compIn||0)===old,'코치 보상금 장부 분리 안 됨'); const b=budget(); ok(b.inc.some(x=>x[0]==='코치 보상금'&&x[1]===comp),'예산 코치 항목 없음'); ok(b.I-b0>0,'예산 수입 누락'); ok(Math.abs(cash-team(tid).cash-comp)<1,'상대 현금'); const saveG=JSON.stringify(G),prev=team(G.user).cash; G.spend={coachCompIn:comp}; G.unemp0=true; spendHandOff(G.user); ok(team(G.user).cash===prev+comp,'이직 정산 수입 누락'); G=JSON.parse(saveG); const ord=G.teams.map(t=>t.id); SP17ps(ord.slice(0,5),ord.slice(5),ord[0]); settlement(); ok(G.last.fins[G.user].inc.filter(x=>x[0]==='코치 보상금').reduce((a,x)=>a+x[1],0)===comp,'결산 수입 누락·중복'); ok(!G.spend.coachCompIn,'결산 뒤 장부 잔류'); });

T('[검수 11-18 #507] AI 코치 교체 시 해임된 대행은 현직에서 빠진다 [코치근무검수]',()=>{fresh();const tid=otherT(),C=G.coach[tid],c=C.hc;delete c.jy;delete c.cs;G.mgr[tid]=mkInterim(tid);coachRelease(tid,c,'검수 교체',true);C.hc=mkCoach('hc');ok(G.mgr[tid].cid!==c.id,'해임한 코치가 대행으로 남음');});
T('[검수 11-18 #508] AI 은퇴 대행은 겨울 정리 직후 현직 코치로 바뀐다 [코치근무검수]',()=>{fresh();const tid=otherT(),C=G.coach[tid],c=C.hc;Object.assign(c,{age:71,yrs:3});delete c.ob;delete c.jy;delete c.cs;G.mgr[tid]=mkInterim(tid);coachYear();ok(C.hc!==c,'준비: 은퇴 실패');ok(G.mgr[tid].cid!==c.id,'은퇴 코치가 대행으로 남음');});
T('[검수 11-18 #509] AI 대행의 겨울 인사는 정식 감독 선임으로 처리한다 [코치근무검수]',()=>{fresh();const tid=otherT(),c=G.coach[tid].hc;delete c.jy;delete c.cs;G.mgr[tid]=mkInterim(tid);const ca507_r=FO_RNG;FO_RNG=()=>.1;try{offseasonMgr();}finally{FO_RNG=ca507_r;}ok(!G.mgr[tid].interim,'대행을 정식 감독 계약처럼 재계약함');ok(G.mgr[tid].sal>0,'정식 감독 연봉이 없음');});
T('[검수 11-18 #510] 시작 시즌만 남은 옛 계약도 합류 전 근무와 승격을 막는다 [코치근무검수]',()=>{fresh();const c=G.coach[G.user].fp;c.cs=G.year+1;delete c.jy;ok(staffPending(c),'준비: 합류 전 아님');ok(!coachActiveNow(c)&&effC(c,G.user,'dv')===45&&trnCoachV(c,G.user,'ctl')===45,'합류 전 코치가 지도함');ok(typeof promoteCoach('fp')==='string','합류 전 코치를 승격함');});
T('[검수 11-18 #511] 합류 전 1군 계약 보직은 현재 코치 승격으로 바뀌지 않는다 [코치근무검수]',()=>{fresh();const C=G.coach[G.user],c=C.fp,o=C.pc;delete c.jy;delete c.cs;staffCt(o,2,G.year+1);const before=JSON.stringify([c,o]);const r=promoteCoach('fp');ok(typeof r==='string'&&r,'미래 계약 자리에 승격을 허용함');ok(C.fp===c&&C.pc===o&&JSON.stringify([c,o])===before,'미래 계약 보직 또는 현직을 변경함');});
T('[검수 11-18 #520] 해외 연수는 당일 근무 가능한 코치 육성력만 쓴다 [코치근무검수]',()=>{fresh();const p=playersOf(G.user).find(p=>!p.isP),c=G.coach[G.user].fm;c.dv=90;c.sisAway=G.day+10;G.ovs=[{pid:p.id,prog:'abl',go:true}];const ca507_roll=ovsRoll;let got;ovsRoll=(p,o,dv)=>{got=dv;return {txt:'검수',t:'flat'};};try{ovsFin('abl');}finally{ovsRoll=ca507_roll;}ok(got===45,'연수 중 코치 원래 육성력 사용: '+got);});
T('[검수 11-18 #521] 코치 성장 비중은 현재 구단의 당해 출전만 센다 [코치근무검수]',()=>{fresh();for(const isP of [false,true]){const p=playersOf(G.user).find(p=>!!p.isP===isP),k=isP?'outs':'pa';p.hist=[{y:G.year,lvl:'1군',t:otherT(),[k]:450},{y:G.year,lvl:'퓨처스',t:G.user,[k]:10}];ok(oneShare(p)===0,'전 소속 기록을 현재 코치 비중에 합침: '+oneShare(p));p.hist.push({y:G.year,lvl:'1군',t:G.user,[k]:10});ok(oneShare(p)===.5,'현재 구단 기록 비중 오류');}});
T('[검수 11-18 #522] 은퇴한 연수 코치는 수료 이력만 남기고 잔류 보고를 보내지 않는다 [코치근무검수]',()=>{fresh();const C=G.coach[G.user],c=C.fp,T={key:'ca507_retired',id:c.id,name:c.name,tid:G.user,y:G.year,program:'dom',focus:'yng',to:G.day,coachSnapshot:JSON.parse(JSON.stringify(c))};C.fp=null;G.cmarket=G.cmarket.filter(x=>x.id!==c.id);G.mail=[];sisCtBack(T);const h=G.sis.studyHistory.find(x=>x.key===T.key);ok(T.done&&h,'수료 이력이 없음');ok(h.loyalty===0&&!G.mail.some(m=>m.body&&m.body.includes('남으려는 마음')),'은퇴한 코치에게 잔류 지원 효과를 적용함');});
T('[검수 11-18 #523] 보조 코치 시설 축소는 일일 정산하며 음수 정원과 육성 효과를 남기지 않는다 [코치근무검수]',()=>{fresh();facInit();for(const k of FACK)G.fac.it[k]=1;G.pcoach={};const c=mkCoach('fp');staffCt(c,3,G.year);c.ax=true;c.dv=70;G.coachX=[c];const p=playersOf(G.user).find(p=>p.isP);ok(axRoom(G.user)===0,'남은 정원이 음수');ok(axBoost(p)===1,'정원 밖 보조 코치 육성 효과');const due=coachSev(c),s=G.spend.coach||0;processDay();ok(!G.coachX.includes(c)&&c.yrs===0,'일일 정원 조정 누락');ok((G.spend.coach||0)>=s+due-1,'잔여 계약 정산 누락');const after=G.spend.coach;processDay();ok((G.spend.coach||0)<after+due,'중복 해지 정산');});
T('[검수 11-18 #507] 시장 영입과 다른 구단 코치 이적 모두 현직 대행을 유지한다 [코치근무검수]',()=>{fresh();G.day=dnum(G.year,2,1);const tid=otherT(),C=G.coach[tid],old=C.hc,n=mkCoach('hc');Object.assign(old,{sk:30,dv:30,yrs:3,cs:G.year});delete old.jy;Object.assign(n,{sk:90,dv:90,sal:100,age:50,res:tid});G.cmarket=[n];G.mgr[tid]=mkInterim(tid);cmAiMonthly();ok(C.hc===n,'준비: AI 시장 교체 실패');ok(G.mgr[tid].cid!==old.id,'시장 영입 뒤 퇴임 대행 유지');G.mgr[tid]=mkInterim(tid);const c=G.coach[G.user].pc;Object.assign(c,{age:50,yrs:2,cs:G.year});delete c.jy;delete c.raidSafe;G.poachCtr={};const r={id:c.id,from:G.user,role:'pc',tid,to:'hc',sal:100,exp:G.day+7,occ:n.id};cmLeave(r);ok(C.hc===c,'준비: AI 이적 교체 실패');ok(G.mgr[tid].cid!==n.id,'이적 영입 뒤 퇴임 대행 유지');const m=G.mgr[tid],rng=__rngState();interimRefresh(tid);interimRefresh(tid);ok(G.mgr[tid]===m&&__rngState()===rng,'대행 재검증 중복·난수 변경');});
T('[검수 11-18 #510] 옛 미래 계약 대행은 저장 정리 때 한 번 교체하고 합류일부터 일한다 [코치근무검수]',()=>{fresh();const tid=otherT(),c=G.coach[tid].hc;delete c.jy;delete c.cs;G.mgr[tid]=mkInterim(tid);c.cs=G.year+1;coachRulesMigrate();ok(G.mgr[tid].cid!==c.id,'미합류 대행을 복구하지 않음');const m=G.mgr[tid],rng=__rngState();coachRulesMigrate();ok(G.mgr[tid]===m&&__rngState()===rng,'저장 정리 중복·난수 변경');G.year++;ok(coachActiveNow(c),'합류 시즌이 와도 근무하지 않음');c.sisAway=G.day+1;ok(!coachActiveNow(c),'연수 중 근무');G.day++;ok(coachActiveNow(c),'귀국일에도 근무 차단');});
T('[검수 11-18 #507] 중복 인물 저장 정리로 교체된 AI 코치도 대행에서 빠진다 [코치근무검수]',()=>{fresh();const tid=otherT(),own=G.coach[G.user].hc,c=G.coach[tid].hc;own.ob=c.ob='ca507_duplicate_ob';delete c.jy;delete c.cs;G.mgr[tid]=mkInterim(tid);coachDedupe();ok(G.coach[G.user].hc===own&&G.coach[tid].hc!==c,'준비: 중복 코치 정리 실패');ok(G.mgr[tid].cid!==c.id,'중복 인물 정리 후 옛 대행 유지');const m=G.mgr[tid],rng=__rngState();coachDedupe();ok(G.mgr[tid]===m&&__rngState()===rng,'중복 정리 재실행 부작용');});

const cc512_other=()=>G.teams.filter(t=>t.id!==G.user).map(t=>t.id);
const cc512_c=(role,o)=>Object.assign(mkCoach(role),{id:'cc512_'+role+'_'+G.day,name:'동반검수',age:45,sal:60,sk:90,dv:90,yrs:0},o||{});
const cc512_follow=(o)=>{const s=cc512_c('pc',o);s.gmFol={k:'me',y:G.year,d:G.day,from:cc512_other()[0]};G.cmarket=[s];return s;};
T('[검수 11-18 #512] 감독 사단도 은퇴 나이·고령 기간·타 구단 우선권을 지킨다 [동반합류검수]',()=>{fresh();const A=cc512_other()[0],B=cc512_other()[1];team(A).cash=999999;const cs=[cc512_c('pc',{age:71}),cc512_c('bc',{age:65}),cc512_c('dc',{res:B})],m={id:'cc512_mgr',name:'동반감독',yrs:3,clan:cs};const before=cs.map(c=>G.coach[A][c.role]);aiClanInstall(m,A);ok(G.coach[A].pc===before[0]&&G.coach[A].dc===before[2],'AI 사단이 은퇴 나이/타 구단 우선권을 우회');ok(G.coach[A].bc===cs[1]&&cs[1].yrs===1,'AI 고령 사단 기간 초과');m.clan=[cc512_c('pc',{age:71}),cc512_c('bc',{age:65}),cc512_c('dc',{res:B})];G.cmarket=m.clan.slice();const own=G.coach[G.user].pc,od=G.coach[G.user].dc;hireClan(m,3);ok(G.coach[G.user].pc===own&&G.coach[G.user].dc===od,'우리 사단이 나이/우선권 우회');ok(G.coach[G.user].bc===m.clan[1]&&m.clan[1].yrs===1,'우리 고령 사단 기간 초과');});
T('[검수 11-18 #513] 감독 사단은 합류 전 코치 계약을 밀어내지 않는다 [동반합류검수]',()=>{fresh();const A=cc512_other()[0],old=G.coach[A].pc;staffCt(old,3,G.year+1);old.sal=200;const cash=team(A).cash,s=cc512_c('pc'),m={id:'cc513_mgr',name:'동반감독',yrs:3,clan:[s]};aiClanInstall(m,A);ok(G.coach[A].pc===old&&old.yrs===3&&team(A).cash===cash,'AI 사단이 합류 전 계약 취소/정산');});
T('[검수 11-18 #514] 동반 합류 수락은 메일 당시 퇴임 상대와 계약 조건을 재검사한다 [동반합류검수]',()=>{fresh();const s=cc512_follow();meLoyalOffer(G.user);const e=G.evs.find(e=>e.k==='loyFol'&&e.data.id===s.id);ok(e,'준비: 동반 메일');const b=cc512_c('pc',{id:'cc514_new',sal:400});staffCt(b,4,G.year);G.coach[G.user].pc=b;const spent=G.spend.coach||0;ok(EVH.loyFol.can(e,0),'교체된 상대인데 수락 가능');EVH.loyFol.pick(e,0);ok(G.coach[G.user].pc===b&&b.yrs===4&&(G.spend.coach||0)===spent&&G.cmarket.includes(s),'옛 메일이 새 코치 해임/정산');});
T('[검수 11-18 #515] 단장 동반 메일은 고령 1년 조건 그대로 성립하고 AI는 타 구단 우선권을 지킨다 [동반합류검수]',()=>{fresh();const s=cc512_follow({age:65});meLoyalOffer(G.user);const e=G.evs.find(e=>e.k==='loyFol'&&e.data.id===s.id);ok(e&&JSON.stringify(e).includes('1년'),'65세 메일이 1년 조건을 안내하지 않음');const r=EVH.loyFol.pick(e,0);ok(G.coach[G.user].pc===s&&s.yrs===1,'안내된 1년 계약 실패 '+r);const A=cc512_other()[0],B=cc512_other()[1],g=team(A).gm,k=gmFolKey(g),c=cc512_c('pc',{age:65,res:B});c.gmFol={k,y:G.year,d:G.day,from:B};G.cmarket=[c];G.coach[A].pc=null;team(A).cash=999999;gmLoyalJoin(A,g);ok(G.coach[A].pc!==c&&G.cmarket.includes(c),'AI 단장 동반이 우선권 우회');delete c.res;gmLoyalJoin(A,g);ok(G.coach[A].pc===c&&c.yrs===1,'AI 고령 동반 기간 초과');});
T('[검수 11-18 #516] 옛 구단을 포함한 모든 우선권 후보는 시장 재생성·월간 상한에도 남는다 [동반합류검수]',()=>{fresh();const A=cc512_other()[0],c=cc512_c('pc',{res:A});G.cmarket=[c];refreshCoachMarket();ok(G.cmarket.includes(c),'옛 구단 우선권 후보 재생성 소실');G.cmarket=[c,...Array.from({length:130},(_,i)=>cc512_c('bc',{id:'cc516_'+i}))];for(let i=0;i<24;i++){delete G.cmMonth;coachMarketMonth();}ok(G.cmarket.includes(c),'옛 구단 우선권 후보 월간 정리/상한 소실');});
T('[검수 11-18 #517] 감독을 기다리는 사단 후보는 재생성·월간 상한에도 남는다 [동반합류검수]',()=>{fresh();const m={id:'cc517_mgr'},c=cc512_c('pc',{folM:{id:m.id,y:G.year}});G.cmarket=[c];refreshCoachMarket();ok(G.cmarket.includes(c)&&clanFol(m).includes(c),'감독 대기 후보 재생성 소실');G.cmarket=[c,...Array.from({length:130},(_,i)=>cc512_c('bc',{id:'cc517_'+i}))];for(let i=0;i<24;i++){delete G.cmMonth;coachMarketMonth();}ok(G.cmarket.includes(c),'감독 대기 후보 월간 정리/상한 소실');});
T('[검수 11-18 #514] 같은 퇴임 상대의 재계약·증액·후보 조건 변경과 구버전 메일은 비용 없이 거절한다 [동반합류검수]',()=>{fresh();const s=cc512_follow(),old=G.coach[G.user].pc;staffCt(old,2,G.year);meLoyalOffer(G.user);const e=G.evs.find(e=>e.k==='loyFol'&&e.data.id===s.id),snap=JSON.parse(JSON.stringify(old)),sal=s.sal;ok(e&&e.data.ct,'준비: 계약 스냅샷');const rng=__rngState();for(const change of [()=>old.sal+=100,()=>old.yrs++,()=>old.cs++,()=>s.sal+=10,()=>{delete e.data.ct;}]){const data=JSON.parse(JSON.stringify(e.data)),spent=G.spend.coach||0;change();ok(EVH.loyFol.can(e,0),'변경된 계약을 수락 가능');EVH.loyFol.pick(e,0);ok(G.coach[G.user].pc===old&&(G.spend.coach||0)===spent&&G.cmarket.includes(s),'변경된 계약으로 해임/비용');Object.assign(old,snap);s.sal=sal;e.data=data;}ok(__rngState()===rng,'스냅샷 검증이 난수 소비');G=JSON.parse(JSON.stringify(G));const saved=G.evs.find(x=>x.id===e.id),c=G.cmarket.find(c=>c.id===s.id);G.day++;ok(!EVH.loyFol.can(saved,0),'하루 뒤 자연 정산 감소가 유효 계약을 취소');const r=EVH.loyFol.pick(saved,0);ok(G.coach[G.user].pc===c&&c.yrs===2,'저장/로드 뒤 유효 조건 수락 실패 '+r);});
T('[검수 11-18 #513 #515] 우리 동반 제안도 합류 전 자리와 타 구단 우선권을 보호한다 [동반합류검수]',()=>{fresh();const s=cc512_follow(),old=G.coach[G.user].pc;staffCt(old,3,G.year+1);ok(meLoyalOffer(G.user)===0&&!s.gmFol.ask,'합류 전 자리에 교체 제안 생성');staffCt(old,2,G.year);s.res=cc512_other()[1];ok(meLoyalOffer(G.user)===0&&!s.gmFol.ask,'타 구단 우선권 제안 생성');delete s.res;ok(meLoyalOffer(G.user)===1,'해제 후 유효 제안 없음');const e=G.evs.find(e=>e.k==='loyFol'&&e.data.id===s.id),spent=G.spend.coach||0;s.res=cc512_other()[1];EVH.loyFol.pick(e,0);ok(G.coach[G.user].pc===old&&G.cmarket.includes(s)&&(G.spend.coach||0)===spent,'메일 뒤 새 우선권을 무시');});
T('[검수 11-18 #513] 감독 퇴임에 따른 사단 사임도 합류 전 계약을 취소하지 않는다 [동반합류검수]',()=>{fresh();const A=cc512_other()[0],m=G.mgr[A],C=G.coach[A],c=C.pc;m.age=50;for(const s of Object.values(C))if(s)s.clan=null;c.clan=m.id;staffCt(c,3,G.year+1);const cash=team(A).cash;for(let i=0;i<40;i++)clanLeave(m,A,'fire');ok(C.pc===c&&c.yrs===3&&team(A).cash===cash&&!G.cmarket.includes(c),'합류 전 사단 계약이 감독 퇴임으로 취소');});
const cc512_winterOB=()=>{const ob=obCands('coach')[0];ok(ob,'준비: 자유계약 OB');ob.age=65;G.ob=[ob];const c=obCoach(ob);c.fromY=G.year;for(const t of G.teams)for(const k of CKEYS){const s=G.coach[t.id][k]||(G.coach[t.id][k]=mkCoach(k));delete s.ob;s.age=40;staffCt(s,3,G.year);}const normal=cc512_c('pc',{id:'cc512_normal65',age:65,fromY:G.year});G.cmarket=[c,normal];return {c,normal};};
T('[검수 11-18 #516] 겨울 OB 보호: 타 구단 우선권 65세 후보는 본인과 권리를 유지하고 중복 생성되지 않는다 [동반합류검수]',()=>{fresh();const {c,normal}=cc512_winterOB(),A=cc512_other()[0];c.res=A;coachYear();ok(G.cmarket.includes(c)&&c.res===A,'겨울 중복 제거가 옛 구단 우선권 OB 원본을 삭제');ok(G.cmarket.filter(x=>x.ob===c.ob).length===1,'우선권 OB 중복 생성');ok(!G.cmarket.includes(normal),'일반 65세 만료 후보 유지 범위를 넓힘');});
T('[검수 11-18 #517] 겨울 OB 보호: 감독을 기다리는 65세 사단 후보는 원본으로 남고 중복 생성되지 않는다 [동반합류검수]',()=>{fresh();const {c,normal}=cc512_winterOB(),m={id:'cc517_winter_mgr'};c.folM={id:m.id,y:G.year};c.clan=m.id;coachYear();ok(G.cmarket.includes(c)&&clanFol(m).includes(c),'겨울 중복 제거가 유효 사단 대기 OB 원본을 삭제');ok(G.cmarket.filter(x=>x.ob===c.ob).length===1,'사단 대기 OB 중복 생성');ok(!G.cmarket.includes(normal),'일반 65세 만료 후보 유지 범위를 넓힘');});
function r524_setup(day){ fresh(); G.day=day; G.cal.open=Math.min(G.cal.open,day-1); G.cal.end=day+5; G.cal.rE0=day+5; G.cal.sched={}; G.cal.mk={}; G.cal.rain={}; G.makeup=[]; G.noRain=false; for(const t of G.teams)setEntry(t.id); }
T('[검수 11-18 #524] 순연은 공동 구장 홈경기와 겹치지 않는다 [우천편성검수]',()=>{ fresh();const day=KD(7,15);G.day=day;G.cal.rE0=day+4;G.cal.end=day+4;G.cal.sched={};G.cal.sched[day+5]=[[1,3]]; const r=rainPlace(0,2,day);ok(r.d!==day+5,'공동 구장에 두 홈구단 동시 편성');G.cal.sched={};G.cal.rE0=day;G.makeup=[{y:G.year,h:1,a:3,d:day-1}];ok(rainPlace(0,2,day).d!==day+1,'공동 구장 재시도 경기와 충돌');G.makeup=[{y:G.year,h:4,a:2,d:day-1}];ok(rainPlace(0,2,day).d!==day+1,'원정 구단 재시도 경기와 충돌'); });
T('[검수 11-18 #525] 확정 우천 취소는 야수 부족을 막지 않고 조회는 순수하다 [우천편성검수]',()=>{ fresh();G.noRain=false;let d=G.cal.open;while(d<=G.cal.end&&!rainOut(G.user,d))d++;ok(d<=G.cal.end,'우천 날짜 없음');G.day=d-1;G.cal.sched[d]=[[G.user,7]];G.res=null;G.live=null;for(const p of playersOf(G.user))if(!p.isP)p.injOut=100;const before=JSON.stringify(G),rng=__rngState(),why=blocker();ok(!why,'취소 경기 선수 부족으로 정지: '+why);ok(JSON.stringify(G)===before&&__rngState()===rng,'우천 사전 확인이 상태/난수를 변경'); });
T('[검수 11-18 #526] 재시도 경기에도 같은 날 구장 우천이 적용된다 [우천편성검수]',()=>{ fresh();let d=G.cal.open;while(d<=G.cal.end&&!rainOut(6,d))d++;ok(d<=G.cal.end,'우천 날짜 없음');r524_setup(d);G.makeup=[{y:G.year,h:6,a:7,d:d-1}];G.cal.sched[d]=[[6,7]];const n=rainDay(d);ok(n===2,'재시도 우천 취소 누락: '+n);ok(!G.makeup.length,'우천 취소한 재시도 잔존');ok((G.cal.rain[d]||[]).length===2,'취소 이력 누락'); });
T('[검수 11-18 #527] 재시도와 정규 경기를 함께 더블헤더로 센다 [우천편성검수]',()=>{ fresh();const d=G.cal.open;r524_setup(d);G.noRain=true;G.makeup=[{y:G.year,h:6,a:7,d:d-1}];G.cal.sched[d]=[[6,7]];ok(rainGameInfo(d,6,7,1).dh===1&&rainGameInfo(d,6,7,2).dh===2,'혼합 더블헤더 번호 누락');const fn=stadGame,m=[];try{stadGame=(...args)=>{m.push(rainAttM(args[1],args[0]));return fn(...args);};playDay(d);}finally{stadGame=fn;}const records=G.games.filter(g=>g.day===d);ok(records.length===2&&records.some(g=>g.dh===1)&&records.some(g=>g.dh===2),'실제 경기 DH 꼬리표 누락');ok(m.length===2&&m[0]===.9&&m[1]===.8,'실제 관중 DH 배율 누락'); });
T('[검수 11-18 #528] 정규 더블헤더와 재시도는 하루 두 경기만 치른다 [우천편성검수]',()=>{ fresh();const d=G.cal.open;r524_setup(d);G.noRain=true;G.makeup=[{y:G.year,h:6,a:7,d:d-1}];G.cal.sched[d]=[[6,7],[6,7]];const r=G.sea.rec[6],before=r.w+r.l+(r.t||0);playDay(d);ok(r.w+r.l+(r.t||0)-before===2,'하루 세 경기 실제 반영');ok(G.makeup.length===1,'넘친 경기 미래 대기 누락'); });
T('[검수 11-18 #532] 서로 다른 날로 옮긴 모든 취소 경기를 알린다 [우천편성검수]',()=>{ fresh();let d=KD(7,1);while(d<KD(9,1)&&!rainOut(6,d))d++;ok(d<KD(9,1),'여름 우천 날짜 없음');r524_setup(d);G.mail=[];G.stops=[];G.cal.sched[d]=[[6,7],[6,7]];rainDay(d);const rows=G.cal.rain[d]||[];ok(rows.length===2&&rows[0].to!==rows[1].to,'두 취소 경기의 서로 다른 재편성 준비 실패');const text=JSON.stringify(G.mail);ok(rows.every(r=>text.includes(rainWhere(r.to))),'두 취소 경기 중 하나의 새 날짜만 안내'); });
T('[검수 11-18 #524] 2027 실제 날씨 전체 시즌 공동 구장과 팀 일일 상한 [우천편성검수]',()=>{ fresh();G.year=2027;G.cal=buildCalendar(2027);G.noRain=false;G.makeup=[];let total=0;for(let d=G.cal.open;d<=G.cal.end;d++){G.day=d;total+=rainDay(d);}ok(total>0,'실제 우천 취소 없음');for(const d of Object.keys(G.cal.sched)){const count={},venues={};for(const [h,a] of G.cal.sched[d]){count[h]=(count[h]||0)+1;count[a]=(count[a]||0)+1;const v=rainVenue(h,+d);ok(venues[v]==null||venues[v]===h,'공동구장 두 홈경기 '+dmd(+d));venues[v]=h;}ok(Object.values(count).every(n=>n<=2),'팀 하루 세 경기 편성 '+dmd(+d));} });
T('[검수 11-18 #525] 옛 저장 경기 조회와 우천 수리는 난수 보존·멱등 [우천편성검수]',()=>{fresh();const d=G.cal.open;G.day=d-1;G.makeup=[{y:G.year,h:6,a:7,d:d-2}];G.cal.sched[d]=[[6,7]];delete team(6).stad;const before=JSON.stringify(G),rng=__rngState();if(typeof rainGames==='function'){const rows=rainGames(d);ok(rows.length===2&&rows[0].origin==='retry','옛 재시도 읽기 실패');}rainOut(6,d);ok(JSON.stringify(G)===before&&__rngState()===rng,'옛 저장 우천 조회가 상태/난수 변경');G.cal.rain={[d]:[{h:6,a:7,to:d+2}]};G.cal.mk={[d]:[{h:6,a:7,from:d-3}]};rainMigrate();const snap=JSON.stringify(G);ok(rainMigrate()===0&&JSON.stringify(G)===snap,'우천 수리 반복 변경');});

const rr536_setup=()=>{fresh();G.noRain=true;G.day=G.cal.open+10;for(const t of G.teams)setEntry(t.id);const h=G.user,a=otherT(),d=G.day;G.cal.sched={[d]:[[h,a]]};G.makeup=[];G.mail=[];G.stops=[];G.evs=[];G.evf=[];G.evlog=[];return {h,a,d};};
const rr536_canon=x=>JSON.stringify(x,(_,v)=>v&&typeof v==='object'&&!Array.isArray(v)?Object.fromEntries(Object.keys(v).filter(k=>k!=='gc'&&k!=='gcD').sort().map(k=>[k,v[k]])):v);
const rr536_fail=(fn,run)=>{const old=applyGame;try{applyGame=fn(old);return run();}finally{applyGame=old;}};
T('[검수 11-18 #536] 재처리 순연에도 원래 우천 취소일과 예약 차전을 보존한다 [재처리검수]',()=>{const {h,a,d}=rr536_setup(),from=d-6;G.cal.mk={[d]:[{h,a,from,dh:0,k:'reserve'}]};rr536_fail(old=>(...args)=>{throw Error('rr536 before commit');},()=>playDay(d));ok(G.makeup.length===1,'재처리 누락');G.day=d+1;withRng(536,()=>playDay(d+1));const rec=G.games.find(g=>g.day===d+1&&g.home===h&&g.away===a);ok(rec&&rec.rmk===from,'원래 우천 취소일 소실 '+(rec&&rec.rmk));const n=G.sea.rec[h].w+G.sea.rec[h].l+G.sea.rec[h].t;playDay(d+1);ok(n===G.sea.rec[h].w+G.sea.rec[h].l+G.sea.rec[h].t,'재시도 중복 결과');});
T('[검수 11-18 #537] 두번째 경기 반영 실패는 완료 더블헤더로 집계하지 않는다 [재처리검수]',()=>{const {h,a,d}=rr536_setup();G.cal.sched[d].push([h,a]);let n=0;rr536_fail(old=>(...args)=>{if(++n===2)throw Error('rr536 DH2');return old(...args);},()=>withRng(537,()=>playDay(d)));ok(G.makeup.length===1,'DH2 순연 누락');ok(rainSum().dhN===0,'한 경기만 완료했는데 DH 집계');G.day=d+1;withRng(5371,()=>playDay(d+1));ok(rainSum().dhN===0,'서로 다른 날 경기 DH 집계');const N=G.sea.rec[h].w+G.sea.rec[h].l+G.sea.rec[h].t;playDay(d);ok(N===G.sea.rec[h].w+G.sea.rec[h].l+G.sea.rec[h].t,'원래 날짜 재진입 중복');});
T('[검수 11-18 #538] 일군 전경기 우천 취소일도 퓨처스 일정과 라운드는 유지한다 [재처리검수]',()=>{const {d}=rr536_setup();let day=d;while(!flDay(day))day++;G.day=day;const P=G.teams.filter(t=>t.id!==G.user).map(t=>t.id);G.cal.sched[day]=[];for(let i=0;i+1<P.length;i+=2)G.cal.sched[day].push([P[i],P[i+1]]);const F=flInit(),r=F.round,forecast=flPairsR(F,r),old=rainOut;G.noRain=false;try{rainOut=()=>true;rainDay(day);}finally{rainOut=old;}ok(!G.cal.sched[day],'전경기 취소 준비 실패');ok(flOpenOn(day),'우천 취소로 퓨처스 휴일');withRng(538,()=>flPlayDay(day));ok(F.round===r+1,'취소일 퓨처스 라운드 건너뜀');const ng=F.games.length;flPlayDay(day);ok(F.round===r+1&&F.games.length===ng,'퓨처스 재진입 중복');let extra=G.cal.end+10;while(!flDay(extra))extra++;G.cal.end=extra;G.cal.sched[extra]=[[P[0],P[1]]];ok(!flOpenOn(extra),'일군 예비일이 퓨처스 달력을 변경');ok(F.games.some(x=>x.d===day),'퓨처스 결과 없음');for(const g of F.games.filter(x=>x.d===day))ok(forecast.some(p=>p[0]===g.h&&p[1]===g.a),'퓨처스 대진 변동');});
T('[검수 11-18 #553] 반영 도중 부상 뒤 오류는 선수와 메일 결정 뉴스 장부를 함께 되돌린다 [재처리검수]',()=>{const {h,a,d}=rr536_setup(),story0=storyGame,pick0=injPick,range=INJ.back.d,rec0=recMult,reg0=isRegular,sim0=simGame,simulated=withRng(553,()=>simGame(d,h,a,false));let injured=null;const keys=['mail','stops','evs','evf','evlog','evRecent','evSeq','news','newsSeq','pr','wire','iv','ivSeq','spend'];const state=()=>JSON.stringify(keys.map(k=>G[k]));const before=state(),players=rr536_canon(G.players),w=G.sea.rec[h].w+G.sea.rec[h].l+G.sea.rec[h].t;try{simGame=()=>simulated;injPick=()=> 'back';INJ.back.d=[24,24];recMult=()=>1;isRegular=()=>true;storyGame=(p,...args)=>{injured=p;injure(p,d);throw Error('rr536 injury then fail');};withRng(553,()=>playDay(d));}finally{simGame=sim0;storyGame=story0;injPick=pick0;INJ.back.d=range;recMult=rec0;isRegular=reg0;}ok(injured&&G.makeup.length===1,'실패 주입 미실행');ok(rr536_canon(G.players)===players,'선수/기록 롤백 불일치');ok(state()===before,'부상 메일 결정 뉴스 장부 유령 부작용');ok(w===G.sea.rec[h].w+G.sea.rec[h].l+G.sea.rec[h].t,'실패 승패 누적');G.day=d+1;withRng(5531,()=>playDay(d+1));ok(w+1===G.sea.rec[h].w+G.sea.rec[h].l+G.sea.rec[h].t,'재처리 경기 미완료');});
T('[검수 11-18 #553] 승패 반영 뒤 언론 오류는 완료 경기를 재처리하지 않는다 [재처리검수]',()=>{const {h,d}=rr536_setup(),w=G.sea.rec[h].w+G.sea.rec[h].l+G.sea.rec[h].t;rr536_fail(old=>(...args)=>{old(...args);throw Error('rr536 committed media');},()=>withRng(5532,()=>playDay(d)));ok(!G.makeup.length,'완료 경기 재처리 등록');ok(w+1===G.sea.rec[h].w+G.sea.rec[h].l+G.sea.rec[h].t,'완료 경기 롤백');const games=G.games.length;playDay(d);ok(w+1===G.sea.rec[h].w+G.sea.rec[h].l+G.sea.rec[h].t&&games===G.games.length,'완료 경기 재진입 중복');});
T('[검수 11-18 #553] 승패 일부만 반영된 실패도 원자적으로 되돌린다 [재처리검수]',()=>{const {h,a,d}=rr536_setup(),before=JSON.stringify(G.sea.rec);rr536_fail(old=>(...args)=>{G.sea.rec[h].w++;throw Error('rr536 partial win');},()=>playDay(d));ok(JSON.stringify(G.sea.rec)===before,'한쪽 승수만 남음');ok(G.makeup.length===1&&!G.games.some(g=>g.day===d),'부분 반영 경기를 완료로 취급');G.day=d+1;withRng(5533,()=>playDay(d+1));ok((G.sea.tl[h]||[]).filter(x=>x[4]===a&&x[5]===d+1).length===1,'재처리 로그 중복/누락');});
T('[검수 11-18 #553] 장기 부상의 기사 여론과 공유 메일 참조까지 복구한다 [재처리검수]',()=>{const {h,a,d}=rr536_setup(),g=withRng(5534,()=>simGame(d,h,a,false)),p=[...g.S.h.box.keys()].map(id=>G.players[id]).find(p=>!p.isP),pick0=injPick,range=INJ.back.d,rec0=recMult;const m=stop('기록','rr536 기존 공유 메일');if(!G.stops.includes(m))G.stops.push(m);const state=rr536_canon([G.mail,G.stops,G.news,G.pr,G.evs,G.spend]),before=rr536_canon(p),back=boxSnap(g);try{injPick=()=> 'back';INJ.back.d=[36,36];recMult=()=>1;p.sal=1000;withRng(5535,()=>injure(p,d));ok((G.news||[]).some(n=>n.ref===p.id),'장기 부상 기사 준비 실패');back();}finally{injPick=pick0;INJ.back.d=range;recMult=rec0;}ok(rr536_canon([G.mail,G.stops,G.news,G.pr,G.evs,G.spend])===state&&rr536_canon(p)===before,'장기 부상 기사/여론/선수 잔류');ok(G.mail.includes(m)&&G.stops.includes(m),'기존 메일 객체 공유 손상');});
T('[검수 11-18 #538] 옛 저장의 우천 예비일도 퓨처스 원래 편성일로 오인하지 않는다 [재처리검수]',()=>{const {h,a,d}=rr536_setup(),c=G.cal;let from=d;while(!flDay(from))from++;let reserve=from+10;while(!flDay(reserve))reserve++;let extended=c.end+10;while(!flDay(extended))extended++;delete c.flDays;c.rE0=c.end;c.sched={[extended]:[[h,a]]};c.mk={[reserve]:[{h,a,from,dh:0,k:'reserve'}],[extended]:[{h,a,from:reserve,dh:0,k:'ext'}]};c.rain={[from]:[{h,a,to:reserve}],[reserve]:[{h,a,to:extended}]};c.end=extended;ok(flOpenOn(from),'옛 저장 원래 취소일 퓨처스 제외');ok(!flOpenOn(reserve)&&!flOpenOn(extended),'옛 저장 예비일/연장일 퓨처스 추가');});

function bk529_setup(){ fresh(); const d=G.cal.open+10,h=G.user,a=G.teams.find(t=>t.id!==h).id; G.day=d-2; G.cal.sched[d]=[[h,a]]; G.cal.sched[d+1]=[[h,a],[h,a]]; G.cal.mk=G.cal.mk||{}; G.cal.mk[d+1]=[{h,a,from:d,dh:1}]; return {d,h,a}; }
