function po552_fixture(){ fresh(); G.day=G.cal.end; G.cal.sched={}; G.makeup=[]; G.ps=null; const po552_ids=G.teams.map(t=>t.id), po552_r=G.sea.rec; po552_ids.forEach((id,i)=>po552_r[id]=i<4?{w:95-i*3,l:45+i*3,t:0}:i<7?{w:70,l:70,t:0}:{w:40-i,l:100+i,t:0}); const [po552_a,po552_b,po552_c]=po552_ids.slice(4,7); G.user=po552_b; po552_r[po552_a]={w:70,l:69,t:0}; po552_r[po552_b]={w:69,l:70,t:0}; G.sea.tl=G.teams.map(()=>[]); const po552_game=(a,b,ar,br)=>{ G.sea.tl[a].push([Math.sign(ar-br),ar,br,1,b,G.day-1]); G.sea.tl[b].push([Math.sign(br-ar),br,ar,0,a,G.day-1]); }; po552_game(po552_a,po552_b,1,0); po552_game(po552_a,po552_b,1,0); po552_game(po552_b,po552_a,30,0); po552_game(po552_b,po552_c,30,0); po552_game(po552_c,po552_b,1,0); po552_game(po552_a,po552_c,1,0); po552_game(po552_c,po552_a,1,0); G.makeup=[{y:G.year,d:G.day+1,h:po552_a,a:po552_b}]; _poC={k:null}; return {a:po552_a,b:po552_b,c:po552_c,ids:po552_ids}; }
T('[검수 11-18 #552] 마지막 한 경기 세 팀 동률에서 맞대결 득점으로 5위가 바뀔 수 있다 [진출동률검수]',()=>{ const po552_f=po552_fixture(); ok(standingsNow()[4].tid===po552_f.a,'준비 실패: 현재 5위'); const po552_v=playoffOdds(),po552_p=po552_v.find(x=>x.tid===po552_f.b).ps; G.sea.rec[po552_f.a].l++; G.sea.rec[po552_f.b].w++; G.sea.tl[po552_f.a].push([-1,0,1,1,po552_f.b,G.day+1]); G.sea.tl[po552_f.b].push([1,1,0,0,po552_f.a,G.day+1]); ok(standingsNow()[4].tid===po552_f.b,'준비 실패: 이기면 맞대결 득점으로 5위'); ok(po552_p>0&&po552_p<1,'현재 5위 팀이 지면 진출할 수 있는데 확률 '+po552_p); });
function po552_original(){ const po552_r=G.sea.rec,po552_pct=x=>x.w/Math.max(1,x.w+x.l),po552_prev=(G.last&&G.last.order)||[],po552_pr=t=>{const i=po552_prev.findIndex(x=>(x.tid??x)===t);return i<0?99:i;},po552_l=seaTeams().map(t=>({tid:t.id,w:po552_r[t.id].w,l:po552_r[t.id].l,t:po552_r[t.id].t||0})).sort((a,b)=>po552_pct(b)-po552_pct(a)),po552_out=[]; for(let i=0;i<po552_l.length;){let j=i;while(j<po552_l.length&&Math.abs(po552_pct(po552_l[j])-po552_pct(po552_l[i]))<1e-12)j++;const po552_grp=po552_l.slice(i,j),po552_ids=new Set(po552_grp.map(x=>x.tid)),po552_gp=x=>{let w=0,l=0;for(const g of (G.sea.tl||[])[x.tid]||[])if(po552_ids.has(g[4])&&g[4]!==x.tid){if(g[0]>0)w++;else if(g[0]<0)l++;}return w+l?w/(w+l):.5;},po552_gr=x=>{let r=0;for(const g of (G.sea.tl||[])[x.tid]||[])if(po552_ids.has(g[4])&&g[4]!==x.tid)r+=g[1]||0;return r;};po552_out.push(...po552_grp.sort((a,b)=>po552_gp(b)-po552_gp(a)||po552_gr(b)-po552_gr(a)||po552_pr(a.tid)-po552_pr(b.tid)||a.tid-b.tid));i=j;}return po552_out; }
T('[검수 11-18 #552] 공용 순위 비교는 기존 실제 순위의 승률 상대승률 득점 전년 순위를 보존한다 [진출동률검수]',()=>{ const po552_f=po552_fixture(),po552_rand=mulberry(552); for(let po552_i=0;po552_i<48;po552_i++){ G.last={order:po552_i%2?po552_f.ids.slice().reverse():po552_f.ids.map(tid=>({tid}))}; G.sea.tl=G.teams.map(()=>[]); for(const po552_tid of po552_f.ids){ const po552_grp=po552_i%3?Math.floor(po552_rand()*3):0; G.sea.rec[po552_tid]={w:po552_grp?70-po552_grp:0,l:po552_grp?70+po552_grp:0,t:po552_i}; for(const po552_op of po552_f.ids)for(let po552_n=0;po552_n<3;po552_n++)G.sea.tl[po552_tid].push([Math.floor(po552_rand()*3)-1,Math.floor(po552_rand()*12),0,1,po552_op,G.day]); } const po552_before=JSON.stringify(G.sea),po552_rng=__rngState(); ok(JSON.stringify(standingsNow())===JSON.stringify(po552_original()),'기존 실제 순위 변경 상태 '+po552_i); ok(JSON.stringify(G.sea)===po552_before&&__rngState()===po552_rng,'순위 조회 부작용'); } });
T('[검수 11-18 #552] 모든 MC 최종 순위는 실제 순위와 같고 득점은 승패를 지킨다 [진출동률검수]',()=>{ for(let po552_mode=0;po552_mode<4;po552_mode++){ const po552_f=po552_fixture(); if(po552_mode===1){const po552_target=[po552_f.ids[0],po552_f.ids[1],po552_f.ids[2]]; for(let po552_i=0;po552_i<3;po552_i++){const a=po552_target[po552_i],b=[po552_f.a,po552_f.b,po552_f.c][po552_i]; [G.sea.rec[a],G.sea.rec[b]]=[G.sea.rec[b],G.sea.rec[a]];} G.makeup=[{y:G.year,d:G.day+1,h:po552_target[0],a:po552_target[1]}]; } if(po552_mode===2){ G.makeup=[]; G.sea.rec[po552_f.a]={w:70,l:70,t:0}; G.sea.rec[po552_f.b]={w:70,l:70,t:0}; } if(po552_mode===3){ G.cal.sched[G.day+1]=[[po552_f.a,po552_f.b],[po552_f.c,po552_f.ids[7]]]; G.makeup=[]; G.last={order:po552_f.ids.slice().reverse()}; } const po552_fn=seasonStandingsOrder,po552_score=playoffOddsScore; let po552_calls=0,po552_sc=0,po552_inside=false; try{ playoffOddsScore=(won,rnd)=>{const r=po552_score(won,rnd);ok(r.every(x=>Number.isInteger(x)&&x>=0)&&((r[0]>r[1])===won),'승패와 모의 득점 불일치');po552_sc++;return r;}; seasonStandingsOrder=(rows,h,l,r,prev)=>{ if(po552_inside)return po552_fn(rows,h,l,r,prev); const po552_out=po552_fn(rows,h,l,r,prev),po552_saved=[G.sea.rec,G.sea.tl,G.last]; try{po552_inside=true;G.sea.rec=rows.map(x=>({...x}));G.sea.tl=G.teams.map(()=>[]);G.last={order:prev};for(const x of rows)for(const y of rows)if(x.tid!==y.tid){for(let j=0;j<(h[x.tid][y.tid]||0);j++)G.sea.tl[x.tid].push([1,0,0,1,y.tid,G.day]);for(let j=0;j<(l[x.tid][y.tid]||0);j++)G.sea.tl[x.tid].push([-1,0,0,1,y.tid,G.day]);G.sea.tl[x.tid].push([0,r[x.tid][y.tid]||0,0,1,y.tid,G.day]);} ok(JSON.stringify(po552_out.map(x=>x.tid))===JSON.stringify(standingsNow().map(x=>x.tid)),'MC/실제 순위 불일치 '+po552_mode+'/'+po552_calls); ok(JSON.stringify(po552_out.map(x=>x.tid))===JSON.stringify(po552_original().map(x=>x.tid)),'MC/기존 실제 순위 불일치');}finally{[G.sea.rec,G.sea.tl,G.last]=po552_saved;po552_inside=false;}po552_calls++;return po552_out;};const po552_v=playoffOdds();ok(po552_calls===400,'MC 전체 표본 미검사 '+po552_calls);ok(po552_sc===400*(po552_mode===2?0:po552_mode===3?2:1),'모의 득점 누락 '+po552_sc);ok(Math.abs(po552_v.reduce((s,x)=>s+x.ps,0)-5)<1e-9,'진출 확률 합');}finally{seasonStandingsOrder=po552_fn;playoffOddsScore=po552_score;} } });
T('[검수 11-18 #552] 확률 재조회와 캐시 갱신은 경기 난수와 저장을 바꾸지 않는다 [진출동률검수]',()=>{ const po552_f=po552_fixture(),po552_before=JSON.stringify(G),po552_rng=__rngState(),po552_main=FO_RNG,po552_first=playoffOdds(); ok(playoffOdds()===po552_first,'같은 입력 캐시 재사용 안 됨'); _poC={k:null}; ok(JSON.stringify(playoffOdds())===JSON.stringify(po552_first),'강제 재계산 결과 변경'); ok(JSON.stringify(G)===po552_before&&__rngState()===po552_rng&&FO_RNG===po552_main,'조회가 실제 경기 난수/저장을 바꿈'); const po552_baseline=playoffOdds(); G.sea.tl[po552_f.b][0][1]+=100; const po552_changed=playoffOdds(); ok(po552_changed!==po552_baseline,'맞대결 득점 캐시 갱신 누락'); const po552_changed2=po552_changed; G.last={order:po552_f.ids.slice().reverse()}; ok(playoffOdds()!==po552_changed2,'전년 순위 캐시 갱신 누락'); const po552_changed3=playoffOdds(); G.makeup[0].a=po552_f.c; ok(playoffOdds()!==po552_changed3,'같은 수 남은 대진 변경 캐시 누락'); ok(__rngState()===po552_rng&&FO_RNG===po552_main,'갱신 조회가 실제 경기 난수를 바꿈'); });
T('[검수 11-18 #552] 점수 난수 표본을 바꿔도 기존 MC 승패 난수열은 같다 [진출동률검수]',()=>{ const po552_f=po552_fixture(),po552_fn=seasonStandingsOrder,po552_score=playoffOddsScore,po552_seen=[];let po552_mode=0;try{seasonStandingsOrder=(rows,...args)=>{if(!po552_mode)po552_seen.push(JSON.stringify(rows));else ok(JSON.stringify(rows)===po552_seen.shift(),'득점 표본이 MC 승패 난수열을 바꿈');return po552_fn(rows,...args);};playoffOdds();ok(po552_seen.length===400,'MC 표본 누락');po552_mode=1;playoffOddsScore=(won,rnd)=>{for(let j=0;j<100;j++)rnd();return won?[99,0]:[0,99];};_poC={k:null};playoffOdds();ok(!po552_seen.length,'승패 난수열 검사 누락');}finally{seasonStandingsOrder=po552_fn;playoffOddsScore=po552_score;} });

const sc540_setup=()=>{fresh();G.day=G.cal.open+20;G.sea.ulog=[];G.games=[];G._serN=null;const a=otherT(),b=G.teams.find(t=>t.id!==G.user&&t.id!==a).id;G.cal.sched={};return {d:G.day,a,b};};
const sc540_game=(d,a,res='승',kind='',home=true,id=d)=>({gid:id,day:d,home:home?G.user:a,away:home?a:G.user,hs:res==='승'?(home?3:1):(home?1:3),as:res==='승'?(home?1:3):(home?3:1),res,kind});
const sc540_news=d=>{const orig=wire,L=[];wire=(k,t)=>L.push(t);try{seriesNews(d);}finally{wire=orig;}return L.join(' ');};
T('[검수 11-18 #540] 달력 날짜 상세는 DH 두 박스스코어를 모두 연다 [시리즈달력검수]',()=>{const {d,a}=sc540_setup();const x=sc540_game(d,a,'승','',true,5401),y=sc540_game(d,a,'패','',true,5402);x.dh=1;y.dh=2;G.games=[y,x];ulog(x);ulog(y);const F=eval(globalThis.__schedCalSrc()),html=F.calDetail(d,true),ids=[...html.matchAll(/data-a="openGame" data-v="([0-9]+)"/g)].map(m=>+m[1]);ok(ids.length===2&&ids.includes(0)&&ids.includes(1),'달력에서 첫 경기 버튼이 없음 '+ids);});
T('[검수 11-18 #541] 우천 뒤 처음 열린 경기만 개막전으로 부른다 [시리즈달력검수]',()=>{const {a}=sc540_setup();const d=G.cal.open+1;G.sea.rec[G.user]={w:0,l:0,t:0};ok(specialKind(d,G.user,a)==='개막전','늦게 열린 첫 경기 개막전 누락');G.sea.rec[G.user].w=1;ok(specialKind(d,G.user,a)!=='개막전','같은 날 두 번째 경기까지 개막전');});
T('[검수 11-18 #542] 같은 상대라도 홈에서 원정으로 바뀌면 시리즈가 끝난다 [시리즈달력검수]',()=>{const {d,a}=sc540_setup();G.cal.sched[d]=[[G.user,a]];G.cal.sched[d+1]=[[a,G.user]];ok(seriesEnd(d),'홈원정 전환을 같은 시리즈로 판정');});
T('[검수 11-18 #543] DH를 포함한 네 경기 스윕은 실제 네 경기로 보도한다 [시리즈달력검수]',()=>{const {d,a,b}=sc540_setup();G.games=[sc540_game(d,a,'승','',true,5434),sc540_game(d,a,'승','',true,5433),sc540_game(d-1,a,'승','',true,5432),sc540_game(d-2,a,'승','',true,5431)];G.cal.sched[d]=[[G.user,a],[G.user,a]];G.cal.sched[d+1]=[[G.user,b]];const t=sc540_news(d);ok(t.includes('4연전 스윕')&&!t.includes('3연전'),'스윕 경기 수가 다름: '+t);});
T('[검수 11-18 #544] 개막전과 순위 경쟁도 정규 시리즈 집계에 든다 [시리즈달력검수]',()=>{for(const kind of ['개막전','순위 경쟁']){const {d,a,b}=sc540_setup();G.games=[sc540_game(d,a,'승','',true,5443),sc540_game(d-1,a,'패','',true,5442),sc540_game(d-2,a,'승',kind,true,5441)];G.cal.sched[d]=[[G.user,a]];G.cal.sched[d+1]=[[G.user,b]];const t=sc540_news(d);ok(t.includes('3연전 2승 1패'),'연출 표시에 경기 누락: '+kind+' '+t);}});
T('[검수 11-18 #545] 다른 상대 경기를 사이에 둔 승리는 한 시리즈로 묶지 않는다 [시리즈달력검수]',()=>{const {d,a,b}=sc540_setup();G.games=[sc540_game(d,a,'승','',true,5453),sc540_game(d-1,b,'패','',true,5452),sc540_game(d-2,a,'승','',true,5451)];G.cal.sched[d]=[[G.user,a]];G.cal.sched[d+1]=[[G.user,b]];ok(!sc540_news(d),'떨어진 두 경기를 위닝 시리즈로 보도');});
T('[검수 11-18 #546] 재처리 경기만 실제 열린 날도 일일 시리즈 결산을 호출한다 [시리즈달력검수]',()=>{fresh();const d=G.cal.open+20;G.day=d-1;G.noRain=true;G.entryY=G.year;for(const t of G.teams)setEntry(t.id);delete G.cal.sched[d];G.makeup=[{y:G.year,h:G.user,a:otherT(),d:d-1}];const a=seriesEnd,b=seriesNews;let calls=0;seriesEnd=()=>true;seriesNews=()=>calls++;try{processDay();}finally{seriesEnd=a;seriesNews=b;}ok(G.games.some(g=>g.day===d),'재처리 경기 실행 준비 실패');ok(calls===1,'실제 경기일 시리즈 결산 누락 '+calls);});
T('[검수 11-18 #540 호환] 경기 ID 없는 같은 점수 DH도 서로 다른 박스스코어를 연다 [시리즈달력검수]',()=>{const {d,a}=sc540_setup(),x=sc540_game(d,a),y=sc540_game(d,a);delete x.gid;delete y.gid;x.dh=1;y.dh=2;G.games=[y,x];ulog(x);ulog(y);const F=eval(globalThis.__schedCalSrc()),rows=F.calGames(d);ok(rows.length===2&&rows[0].gi===1&&rows[1].gi===0,'같은 점수의 옛 두 경기가 한 박스로 연결 '+JSON.stringify(rows));});
T('[검수 11-18 #547 달력] 가을야구 취소일은 원래 날짜 상세에 취소와 이동일을 표시한다 [시리즈달력검수]',()=>{const {d}=sc540_setup();G.ps={done:false,rain:[{d,rd:d+1,h:G.user,a:otherT(),round:'ks',n:1}]};const F=eval(globalThis.__schedCalSrc()),html=F.calDetail(d,true);ok(html.includes('한국시리즈 1차전 우천 취소')&&html.includes(rainWhere(d+1)),'취소 날짜 상세가 비어 있음');});
function lg554_setup(){fresh();const U=G.user,V=G.teams.find(t=>t.id!==U).id,y=G.year;G.day=KD(11,5);G.gmP={name:'전임단장',age:45,y0:y};G.gmLine=[];G.history=[];G.gmRec={y:y-1,L:[]};G.gmSt={};G.gmLeg=null;G.ps=null;G.last=null;G.myC={tid:U,sal:250,y0:y,y1:y+2,earn:0,seas:[],stints:[]};return {U,V,y};}
T('[검수 11-18 #554] 결산 뒤 단장 교체는 사람과 AI의 완료 승패를 두 번 더하지 않는다 [단장레거시검수]',()=>{for(const mine of [true,false]){const {U,V,y}=lg554_setup(),tid=mine?U:V,k=mine?'u0':team(V).gm.id,n=mine?'전임단장':team(V).gm.name;G.gmRec={y,L:[{k,n,t:tid,y0:y,y1:y,s:1,w:80,l:64,c:0,u:mine?1:0,endD:G.day}]};G.gmSt[tid]={k,n,y,w0:0,l0:0,u:mine?1:0};G.sea.rec[tid]={w:80,l:64,t:0};G.last={y,order:[],ps:{}};if(mine)G.unemp=true;else team(V).gm={...team(V).gm,id:k+'-후임',name:'후임AI'};legTrack();const a=legAt(k,tid);ok(a.w===80&&a.l===64,'완료 기록 중복 '+JSON.stringify(a));}});
T('[검수 11-18 #555] 세대교체 뒤 전임 기록과 합계 이름은 전임에게 남는다 [단장레거시검수]',()=>{const {U,y}=lg554_setup();G.gmRec={y,L:[{k:'u0',n:'전임단장',t:U,y0:y,y1:y,s:1,w:80,l:64,c:1,u:1,endD:G.day}]};G.gmSt[U]={k:'u0',u:1,y,w0:0,l0:0};G.sea.rec[U]={w:80,l:64,t:0};G.last={y,order:[],ps:{}};G.gmLine=[{name:'전임단장',tid:U,from:y,to:y,seas:1,w:80,l:64,champ:1,seasL:[{y,tid:U,w:80,l:64,t:0,ch:1}]}];G.gmP.name='후임단장';legTrack();const p=legPeople().find(x=>x.k==='u0');ok(p.n==='전임단장'&&p.w===80&&p.l===64,'전임 이름·승패 오염 '+JSON.stringify(p));});
T('[검수 11-18 #556] 최종 우승 뒤 떠난 전임도 마지막 결산으로 공로자가 된다 [단장레거시검수]',()=>{const {U,V,y}=lg554_setup();G.gmRec.L=[{k:'u0',n:'전임단장',t:U,y0:y-9,y1:y-1,s:9,w:700,l:596,c:1,u:1,endD:G.day}];G.gmLegFinish={y,by:{[U]:{k:'u0',n:'전임단장',u:1,w:0,l:0,endD:G.day}}};G.user=V;G.gmJoin={y,tid:V,w:80,l:64,t:0,psDone:true};G.last={y,order:G.teams.map(t=>({tid:t.id,w:80,l:64,t:0})),ps:{champ:U,runner:V}};const rng=__rngState();legSeason();ok(__rngState()===rng,'지연 공로자 보도가 주 난수를 소비');const h=G.gmLeg?.hon.find(x=>x.k==='u0'&&x.t===U);ok(h&&h.s===10&&h.c===2&&h.n==='전임단장','마지막 결산 공로자 누락 '+JSON.stringify(G.gmLeg));const n=G.gmLeg.hon.length;legSeason();ok(G.gmLeg.hon.length===n,'공로자 중복');});
T('[검수 11-18 #561] 옛 계보의 두 구단 우승과 승패를 각각 복원한다 [단장레거시검수]',()=>{const {U,V,y}=lg554_setup();delete G.gmRec;G.gmLine=[{name:'전임단장',tid:V,from:y-1,to:y,seas:2,w:161,l:127,champ:2,seasL:[{y:y-1,tid:U,w:80,l:64,t:0,ch:1},{y,tid:V,w:81,l:63,t:0,ch:1}],stintL:[{tid:U,y0:y-1,y1:y-1},{tid:V,y0:y,y1:y}]}];const D=legRec(),A=D.L.filter(x=>x.k==='u0');ok(A.length===2&&A.find(x=>x.t===U)?.c===1&&A.find(x=>x.t===V)?.c===1,'전임 우승이 마지막 구단에 몰림 '+JSON.stringify(A));ok(A.find(x=>x.t===U).w===80&&A.find(x=>x.t===V).w===81,'승패 구단 귀속');const r=__rngState(),s=JSON.stringify(legRec());ok(JSON.stringify(legRec())===s&&__rngState()===r,'복원 조회는 순수·결정적');});
T('[검수 11-18 #562] 옛 경력의 시즌 중 이직한 구단 승패도 복원한다 [단장레거시검수]',()=>{const {U,V,y}=lg554_setup();delete G.gmRec;G.myC.tid=V;G.user=V;G.myC.seas=[{y:y-1,tid:U,w:18,l:12,t:2,part:1,ch:0},{y:y-1,tid:V,w:60,l:54,t:0,ch:0}];G.myC.stints=[{tid:U,y0:y-1,y1:y-1,how:'이직'}];const A=legRec().L.filter(x=>x.k==='u0'),a=A.find(x=>x.t===U);ok(a&&a.w===18&&a.l===12&&a.ties===2&&a.s===0,'이직 전 재임 누락 '+JSON.stringify(A));ok(A.find(x=>x.t===V)?.s===1,'완료 시즌은 후임 구단 1시즌');});
T('[검수 11-18 #563] 무승부만 치른 사람과 AI 단장의 재임도 남긴다 [단장레거시검수]',()=>{for(const mine of [true,false]){const {U,V,y}=lg554_setup(),tid=mine?U:V,k=mine?'u0':team(V).gm.id;G.gmSt[tid]={k,n:'무승부단장',u:mine?1:0,y,w0:0,l0:0,t0:0};G.sea.rec[tid]={w:0,l:0,t:4};if(mine)G.unemp=true;else team(V).gm={...team(V).gm,id:k+'-후임'};legTrack();const a=legRec().L.find(x=>x.k===k&&x.t===tid);ok(a&&a.w===0&&a.l===0&&a.ties===4&&a.s===0,'4무 재임 행 누락 '+JSON.stringify(a));}});
T('[검수 11-18 #554 #555 #561] 상세 기록이 남은 옛 중복 기록을 멱등 복구하고 오래된 기록은 보존한다 [단장레거시검수]',()=>{const {U,V,y}=lg554_setup();G.gmLine=[{name:'전임단장',tid:V,from:y-1,to:y,seas:2,w:161,l:127,champ:2,seasL:[{y:y-1,tid:U,w:80,l:64,t:0,ch:1},{y,tid:V,w:81,l:63,t:0,ch:1}]}];G.gmP.name='후임단장';G.gmRec={y,L:[{k:'u0',n:'후임단장',t:V,y0:y-1,y1:y,s:2,w:322,l:254,c:2,u:1},{k:'very-old',n:'오래된단장',t:U,y0:1900,y1:1901,s:2,w:160,l:128,c:0}]};const r=__rngState();ok(legMigrate()>0,'복구 안 됨');const a=legAt('u0',U),b=legAt('u0',V);ok(a.w===80&&a.c===1&&b.w===81&&b.c===1,'이전 중복·구단 귀속 미복구');ok(legPeople().find(x=>x.k==='u0').n==='전임단장','전임 이름 미복구');ok(G.gmRec.L.some(x=>x.k==='very-old'&&x.w===160),'확인 불가 과거 기록 손실');const s=JSON.stringify(G.gmRec);ok(legMigrate()===0&&JSON.stringify(G.gmRec)===s&&__rngState()===r,'중복 복구 또는 난수 소비');G.gmRec={y,L:[]};legMigrate();ok(legAt('u0',U).w===80&&legAt('u0',V).w===81,'빈 옛 역대 기록도 상세 경력에서 복원');});
T('[검수 11-18 #562 호환] 상세 경력이 잘린 저장은 기존 장기 기록을 지우지 않는다 [단장레거시검수]',()=>{const {U,y}=lg554_setup();G.myC.seas=[{y:y-1,tid:U,w:80,l:64,t:0,ch:0}];G.gmRec={y:y-1,L:[{k:'u0',n:'전임단장',t:U,y0:y-20,y1:y-1,s:20,w:1600,l:1280,c:3,u:1}]};legMigrate();const a=legAt('u0',U);ok(a.s===20&&a.w===1600&&a.c===3,'잘린 원본으로 통산을 덮음 '+JSON.stringify(a));});

const su557_profile=(name='전임단장',age=55)=>{G.gmP={name,age,y0:G.year,d0:G.day,bg:'corp',bgDone:true};};
T('[검수 11-18 #557] 세대 교체 뒤 전임의 구장 명명 제안은 자동 수락되지 않는다 [세대경력검수]',()=>{fresh();G.day=KD(12,1);su557_profile();const U=G.user,name=stadName(U);G.gmRec={y:G.year-1,L:[{k:legMeK(),n:meName(),t:U,y0:G.year-12,y1:G.year-1,s:12,w:900,l:700,c:2,u:1}]};ok(legStadOffer(),'명명 제안 준비');const e=G.evs.find(x=>x.k==='stadNm'&&!x.done);ok(!gmSucceed({name:'후임단장',age:42}),'세대교체 실패');G.day=e.exp+1;evDaily();ok(stadName(U)===name,'전임 명명 제안이 후임에게 자동 적용');ok(!G.gmLeg.stad,'후임 명명 수락 기록 생성');ok(e.done&&e.void,'전임 제안 종료 누락');const m=G.mail.find(x=>x.id===e.mid);ok(!m||(m.acts||[]).length===0,'전임 메일 버튼 잔존');});
T('[검수 11-18 #557 호환] 인물 키 없는 옛 명명 제안도 새 단장에게 적용하지 않는다 [세대경력검수]',()=>{fresh();G.day=KD(12,1);su557_profile();const U=G.user,name=stadName(U);G.gmRec={y:G.year-1,L:[{k:legMeK(),n:meName(),t:U,y0:G.year-12,y1:G.year-1,s:12,w:900,l:700,c:2,u:1}]};legStadOffer();const e=G.evs.find(x=>x.k==='stadNm'&&!x.done);delete e.data.k;G.gmLine=[{name:'전임단장',tid:U,from:G.year-12,to:G.year}];G.gmP={...G.gmP,name:'새단장',d0:G.day};G.day=e.exp+1;evDaily();ok(stadName(U)===name&&!G.gmLeg.stad,'구형 제안이 후임 구장을 변경');});
T('[검수 11-18 #558] 여러 구단을 거친 단장 계보는 개인 경력 시작부터 기록한다 [세대경력검수]',()=>{fresh();const U=G.user,V=otherT(),y=G.year;G.year=y+5;G.day=KD(12,1);su557_profile('여섯시즌단장');G.gmP.y0=y;G.gmSince=y+4;G.myC={tid:U,sal:300,y0:y+4,y1:y+6,earn:0,seas:Array.from({length:6},(_,i)=>({y:y+i,tid:i<4?V:U,w:80,l:64,t:0,ch:0,rank:3})),stints:[{tid:V,y0:y,y1:y+3,how:'이직'}]};ok(!gmSucceed({name:'후임단장',age:42}),'세대교체 실패');const x=G.gmLine.at(-1);ok(x.from===y&&x.to===y+5&&x.seas===6,'계보 기간과 시즌 수 불일치 '+JSON.stringify(x));});
T('[검수 11-18 #559] 77세 정년 예고는 다음 1월 1일 전 실제 선택 기한을 알린다 [세대경력검수]',()=>{fresh();G.day=KD(1,1);su557_profile('정년직전단장',77);gmAgeYear();const m=G.mail.find(x=>(x.body||'').includes('정년으로 물러나'));ok(m,'정년 예고 누락');ok(m.body.includes('12월 31일')&&!m.body.includes('3월 개막 전'),'정년보다 늦은 선택 기한 '+m.body);});
T('[검수 11-18 #560] 정년인 야인은 후임으로 교체되며 옛 구단을 맡지 않는다 [세대경력검수]',()=>{fresh();G.day=KD(1,1);su557_profile('정년야인단장',78);myCInit();const U=G.user,V=otherT(),cash=team(U).cash;G.unemp={y:G.year,d:G.day-10,from:U,k:'resign'};G.myC.tid=null;const r=globalThis.__rngState();gmAgeYear();ok(meAge()<GM_SUCC_FORCE&&G.gmP.name!=='정년야인단장','야인 정년 교체 누락');ok(G.unemp&&G.user===U&&G.myC.tid==null&&team(U).cash===cash,'후임이 옛 구단에 임의 취임');ok(G.gmLine.at(-1).name==='정년야인단장','전임 계보 누락');ok(globalThis.__rngState()===r,'새 야인 정년 처리가 경기 난수를 소비');G.jobs=[];jobOffer(V,false,{sal:250,yrs:2});jobAnswer(V,true);ok(G.user===V&&!G.unemp&&meAge()<78,'후임이 새 제안으로 취업하지 못함');ok(G.gmP.bgDone&&!G.gmP.bgOnJoin,'후임 첫 부임 출신 효과 미적용');});
T('[검수 11-18 #560 방어] 새해 정년 처리 전인 옛 저장도 78세 제안을 수락하지 못한다 [세대경력검수]',()=>{fresh();G.day=KD(1,1);su557_profile('정년지난단장',78);const U=G.user,V=otherT();G.unemp={y:G.year,d:G.day-10,from:U,k:'resign'};G.myC.tid=null;G.jobs=[];jobOffer(V,false,{sal:250,yrs:2});const r=jobAnswer(V,true);ok(G.user===U&&G.unemp&&G.myC.tid==null,'78세 같은 단장으로 취임 '+r);});
T('[검수 11-18 #564] 다른 구단 출장 여부와 무관하게 복귀 구단 누적 경기 수를 잇는다 [세대경력검수]',()=>{for(const played of [false,true]){fresh();G.day=KD(12,1);su557_profile();const U=G.user,V=otherT();G.gmTen={tid:U,g:999};G.gmClub={tid:U,g:999};G.jobs=[];jobOffer(V,false,{sal:300,yrs:2});jobAnswer(V,true);if(played)gmTenTick();jobOffer(U,false,{sal:300,yrs:2});jobAnswer(U,true);gmTenTick();ok(G.gmClub.tid===U&&G.gmClub.g===1000,'중간 경기 '+played+' 뒤 누적 '+JSON.stringify(G.gmClub));ok(achHas('gm1000'),'1000경기 업적 누락 '+played);}});
T('[검수 11-18 #564 호환] 구형 구단 경기 수 복원은 구단별 시즌과 무승부를 포함하고 멱등이다 [세대경력검수]',()=>{fresh();G.day=KD(12,1);su557_profile();const U=G.user,V=otherT();G.gmLine=[{name:'선대단장',tid:V,from:G.year-3,to:G.year-1,w:90,l:80,seasL:[{y:G.year-3,tid:U,w:30,l:20,t:2},{y:G.year-2,tid:V,w:60,l:60,t:3}]}];G.myC.seas=[{y:G.year-1,tid:U,w:40,l:30,t:4}];delete G.gmClub;delete G.gmClubGames;G.gmTen={tid:V,g:0};const r=globalThis.__rngState();ok(typeof gmClubMigrate==='function','구단 경기 복원 함수 없음');gmClubMigrate();ok(G.gmClubGames[U]===126&&G.gmClubGames[V]===123,'구단별 경기 수 복원 실패 '+JSON.stringify(G.gmClubGames));const s=JSON.stringify(G.gmClubGames);gmClubMigrate();ok(JSON.stringify(G.gmClubGames)===s&&globalThis.__rngState()===r,'복원 중복 또는 난수 소비');});
T('[검수 11-18 #557 복원] 옛 명명 제안의 인물 연결과 만료 정리는 멱등이며 난수를 보존한다 [세대경력검수]',()=>{fresh();G.day=KD(12,1);su557_profile();const U=G.user;G.gmRec={y:G.year-1,L:[{k:legMeK(),n:meName(),t:U,y0:G.year-12,y1:G.year-1,s:12,w:900,l:700,c:2,u:1}]};legStadOffer();const e=G.evs.find(x=>x.k==='stadNm'&&!x.done);delete e.data.k;const r=globalThis.__rngState();ok(typeof legStadMigrate==='function','명명 제안 복원 함수 없음');ok(legStadMigrate()===1&&e.data.k===legMeK()&&legStadMigrate()===0,'같은 단장 제안 연결 실패');G.gmLine=[{name:meName(),tid:U,from:G.year-12,to:G.year}];G.gmP={...G.gmP,name:'새단장',d0:G.day};ok(legStadMigrate()===1&&e.done&&e.void&&legStadMigrate()===0,'전임 제안 복원 종료 실패');ok(globalThis.__rngState()===r,'명명 제안 복원이 난수 소비');});
T('[검수 11-18 #564 세대] 구단 누적 값이 없던 옛 재임 카운터도 후임 전에 보존한다 [세대경력검수]',()=>{fresh();G.day=KD(12,1);su557_profile();G.gmTen={tid:G.user,g:999};delete G.gmClub;delete G.gmClubGames;ok(!gmSucceed({name:'후임단장',age:42}),'세대교체 실패');gmTenTick();ok(G.gmTen.g===1&&G.gmClub.g===1000,'개인 재임과 구단 누적 구분 실패 '+JSON.stringify([G.gmTen,G.gmClub]));});
T('[검수 11-18 #560 수동] 시즌 중인 야인도 직접 후임을 정하고 새 제의를 기다린다 [세대경력검수]',()=>{fresh();G.day=G.cal.open+10;su557_profile('야인전임',77);const U=G.user,cash=team(U).cash,trust=team(U).trust;G.unemp={y:G.year,d:G.day,from:U,k:'fired'};G.myC.tid=null;ok(!gmSucceed({name:'야인후임',age:42}),'야인 후임 선택 거절');ok(G.unemp&&G.unemp.k==='succession'&&G.unemp.from==null&&G.myC.tid==null,'전임 경질 이력 또는 구단 승계');ok(G.gmP.name==='야인후임'&&meAge()===42&&team(U).cash===cash&&team(U).trust===trust,'새 사람 상태 또는 옛 구단 변경');});
T('[검수 11-18 #564 복원] 첫 가을 경기의 옛 누적 복원은 정규 승패를 한 경기 빼지 않는다 [세대경력검수]',()=>{fresh();G.day=KD(10,1);su557_profile();G.myC.seas=[];G.sea.rec[G.user]={w:80,l:60,t:4};delete G.gmClub;delete G.gmClubGames;delete G.gmTen;RAIN_GI=null;gmTenTick();ok(G.gmClub.g===145,'가을 경기 복원에서 정규 한 경기 누락 '+JSON.stringify(G.gmClub));});

function ct565Offer(tid,sal,yrs){jobOffer(tid,false,{sal,yrs});return G.jobs.at(-1);}
function ct565Mail(j){return G.mail.find(m=>(m.acts||[]).some(a=>a.a==='jobYes'&&(String(a.v)===String(j.id??j.tid))));}
T('[검수 11-18 #565] 9월 가을야구 종료 뒤 취임한 단장은 다음 시즌부터 급여를 받는다 [단장제안검수]',()=>{fresh();G.day=KD(9,1);const old=G.user,tid=otherT();G.ps={done:true,finDay:G.day+2,champ:old,runner:tid,order:G.teams.map(t=>({tid:t.id}))};G.unemp={y:G.year,from:old,k:'resign',since:G.day-5};G.myC={tid:null,sal:250,y0:G.year-1,y1:G.year+1,earn:0,seas:[],stints:[]};G.personal=null;const j=ct565Offer(tid,270,2),m=ct565Mail(j);jobAnswer(m.acts.find(a=>a.a==='jobYes').v,true);ok(G.user===tid&&G.gmJoin?.psDone,'시즌 종료 후 취임 준비');const C=G.myC,e=C.earn,cash=personalState().cash;ok(C.y0===G.year+1&&C.y1===G.year+2,'시즌 종료 뒤 9월 계약이 그해부터 시작 '+JSON.stringify(C));ok(myCPay()===0&&C.earn===e&&personalState().cash===cash,'치르지 않은 시즌 급여 지급');G.day=KD(9,2);personalMonthlyPay();ok(personalState().cash===cash,'시작 전 월급 지급');});
T('[검수 11-18 #567] 만료 제안의 수락 값은 같은 구단 새 조건을 수락하지 않는다 [단장제안검수]',()=>{fresh();G.day=KD(6,1);const tid=otherT(),old=ct565Offer(tid,300,3),m=ct565Mail(old),ref=m.acts.find(a=>a.a==='jobYes').v;G.day=old.exp;jobsDaily();const current=ct565Offer(tid,195,2),u=G.user,r=jobAnswer(ref,true);ok(G.user===u&&!current.done,'옛 3억3년 버튼이 새 1.95억2년으로 취임 '+r);const n=ct565Mail(current),v=n.acts.find(a=>a.a==='jobYes').v;jobAnswer(v,true);ok(G.user===tid&&G.myC.sal===195&&G.myC.y1-G.myC.y0+1===2,'새 메일의 실제 조건 계약 실패');});
T('[검수 11-18 #567] 예전 거절 값도 새 제의를 닫지 않고 제시 조건을 복사한다 [단장제안검수]',()=>{fresh();G.day=KD(6,1);const tid=otherT(),terms={sal:300,yrs:3};jobOffer(tid,false,terms);const old=G.jobs.at(-1),m=ct565Mail(old),ref=m.acts.find(a=>a.a==='jobNo').v;terms.sal=150;ok(old.terms.sal===300,'외부 조건 수정이 보낸 제의에 전파');G.day=old.exp;jobsDaily();const cur=ct565Offer(tid,195,2);jobAnswer(ref,false);ok(!cur.done,'옛 거절이 새 제의 닫음');const r=__rngState(),a=jobGet(cur.id),b=jobGet(cur.id);ok(a===cur&&b===cur&&__rngState()===r,'제의 조회가 난수 사용');});
T('[검수 11-18 #567 호환] 옛 제안 메일은 당시 만료일로 연결하고 정리는 멱등이다 [단장제안검수]',()=>{fresh();G.day=KD(6,1);const tid=otherT(),d=G.day;G.jobs=[{tid,exp:d+12,done:true,terms:{sal:300,yrs:3}},{tid,exp:d+32,done:false,terms:{sal:195,yrs:2}}];G.mail=[];G.stops=[];const old=mail('구단주실','옛 제의','연봉 3억, 3년',{kind:'경력',acts:[{l:'수락',a:'jobYes',v:tid}]});old.ctx.job=d+12;G.day=d+20;const cur=mail('구단주실','새 제의','연봉 1.95억, 2년',{kind:'경력',acts:[{l:'수락',a:'jobYes',v:tid}]});cur.ctx.job=d+32;const r=__rngState();if(typeof jobMigrate==='function')jobMigrate();const v=cur.acts.find(a=>a.a==='jobYes')?.v,before=JSON.stringify([G.jobs,G.mail,G.jobSeq]);if(typeof jobMigrate==='function')jobMigrate();ok(JSON.stringify([G.jobs,G.mail,G.jobSeq])===before&&__rngState()===r,'제의 마이그레이션 비멱등/난수');const u=G.user;jobAnswer(tid,true);ok(G.user===u&&!G.jobs[1].done,'옛 숫자 버튼이 새 제의에 연결');jobAnswer(v,true);ok(G.user===tid&&G.myC.sal===195,'복원된 새 제의 조건 불일치');});
T('[검수 11-18 #567 호환] 같은 날짜로 구분할 수 없는 옛 제안은 임의 연결하지 않는다 [단장제안검수]',()=>{fresh();const tid=otherT(),d=G.day;G.jobs=[{tid,exp:d+12,done:true,terms:{sal:300,yrs:3}},{tid,exp:d+12,done:false,terms:{sal:195,yrs:2}}];G.mail=[];const m=mail('구단주실','옛 제의','서로 다른 조건',{kind:'경력',acts:[{l:'수락',a:'jobYes',v:tid}]});m.ctx.job=d+12;if(typeof jobMigrate==='function')jobMigrate();ok(!(m.acts||[]).some(a=>a.a==='jobYes')&&m.closed,'모호한 옛 제안이 활성 버튼으로 남음');const u=G.user;jobAnswer(tid,true);ok(G.user===u&&!G.jobs[1].done,'모호한 옛 숫자 값으로 새 제의 수락');});
T('[검수 11-18 #565 호환] 옛 9월 취임 계약은 한 번만 다음 시즌으로 옮긴다 [단장제안검수]',()=>{fresh();G.day=KD(9,2);const C=myCInit();C.y0=G.year;C.y1=G.year+1;G.gmJoin={y:G.year,tid:G.user,psDone:true};const r=__rngState(),e=C.earn,c=personalState().cash;ok(myCPay()===0&&C.earn===e,'옛 시즌 종료 후 계약 급여 지급');if(typeof jobMigrate==='function')jobMigrate();ok(C.y0===G.year+1&&C.y1===G.year+2,'옛 계약 시작 연도 복구');const a=JSON.stringify(C);jobMigrate();personalMonthlyPay();ok(JSON.stringify(C)===a&&personalState().cash===c&&__rngState()===r,'옛 계약 복구 비멱등/월급/난수');});
T('[검수 11-18 #567 수신인] 전임 제의는 후임이 수락할 수 없고 자동 종료는 된다 [단장제안검수]',()=>{fresh();const j=ct565Offer(otherT(),300,3),ref=j.id??j.tid,u=G.user;G.gmLine=(G.gmLine||[]).concat({name:'전임',tid:u});jobAnswer(ref,true);ok(G.user===u&&!j.done,'전임 제의를 후임이 수락');jobAnswer(ref,false,true);ok(j.done,'전임 제의 자동 종료가 수신인 검사에 막힘');});

T('[검수 11-18 #568] 새 상대 단장은 전임의 연락 식사 제한을 물려받지 않는다 [개인경력검수]',()=>{fresh();const t=G.teams.find(t=>t.id!==G.user&&t.gm&&!t.gm.interim),old=t.gm;ok(gmContact(t.id,'call').ok&&gmContact(t.id,'meal').ok,'첫 연락 준비');t.gm={...old,id:old.id+'-new',name:'새단장'};const v=gmContactBulkView([{tid:t.id,id:t.gm.id}]);ok(v.rows[0].ok,'후임 일괄 연락 차단');ok(gmContact(t.id,'call').ok,'후임 첫 전화 차단');ok(gmContact(t.id,'meal').ok,'후임 첫 식사 차단');t.gm=old;ok(!gmContact(t.id,'call').ok&&!gmContact(t.id,'meal').ok,'전임의 원래 제한 소실');});
T('[검수 11-18 #569] 사비 식사한 단장은 개인 인맥에 현재 인물로 나타난다 [개인경력검수]',()=>{fresh();const t=G.teams.find(t=>t.id!==G.user&&t.gm&&!t.gm.interim),S=personalState();S.cash=500;personalActivity('network',t.id);ok(personalGMBond(t.id)===33,'식사 준비 실패');const before=JSON.stringify(G),rng=__rngState(),rows=personalNetworkView(),r=rows.find(x=>x.key===personNetworkKey(t.gm,'gm'));ok(r&&r.bond===33&&r.role==='gm'&&r.history.some(h=>h.kind==='network'),'식사 단장 인맥 누락');ok(JSON.stringify(G)===before&&__rngState()===rng,'인맥 조회 부작용');});
T('[검수 11-18 #570] 구단주 당일 직접 보고는 최근 교류일과 친밀도 유지에 반영한다 [개인경력검수]',()=>{fresh();G.day=KD(10,15);const S=personalState(),C=personalOwnerContact();C.bond=90;C.history=[{day:G.day-200,kind:'meal',text:'지난 식사'}];ownerPersonalReport();ok(plContactLast(C)===G.day,'직접 보고일 누락');plBondDecay(S);ok(C.bond===90,'당일 교류 뒤 오래 안 만난 것으로 감점 '+C.bond);});
T('[검수 11-18 #571] 저장 후 두번째 해외 견학도 첫 출장 14일을 보존한다 [개인경력검수]',()=>{fresh();G.day=KD(11,10);G.ps=null;const S=personalState();S.cash=500;const first=G.day;personalTour('npb');ok(S.trip&&S.trip.to===first+14,'첫 견학 준비');G=JSON.parse(JSON.stringify(G));G.year++;G.cal=buildCalendar(G.year);G.day=KD(11,10);G.ps=null;personalTour('npb');ok(plDutyDays(first,first+14)===14,'첫 출장 제외일 소실 '+plDutyDays(first,first+14));G=JSON.parse(JSON.stringify(G));ok(plDutyDays(first,first+14)===14,'재저장 뒤 첫 출장 소실');});
T('[검수 11-18 #572] 다른 연고지 장학금은 현재 구단 여론 지역 학교 관계를 올리지 않는다 [개인경력검수]',()=>{fresh();const old=G.user,area=teamArea(old),next=G.teams.find(t=>teamArea(t.id)!==area).id,school=Object.values(schList()).find(s=>s.area===area),S=personalState();S.cash=100;S.found={y:G.year-1,paid:G.year-1,area,list:[]};G.user=next;prInit();team(next).cityRel=50;G.pr.fan=50;const before=schRel(school,next);G.draftClass=[];for(const x of Object.values(G.schools))if(x.area===area)x.rel[next]=before;foundYear(S);ok(S.found.list.length===1&&S.cash===95,'장학금 지급 누락');ok(team(next).cityRel===50&&G.pr.fan===50,'다른 지역 현재 구단에 혜택');const awarded=G.schools[S.found.list[0].school];ok(schRel(awarded,next)===before,'다른 지역 현재 구단 학교 친분 증가');});
T('[검수 11-18 #568 호환] 연락 기록은 인물 이동과 재저장을 따르고 후임에게 상속되지 않는다 [개인경력검수]',()=>{fresh();const a=G.teams.find(t=>t.id!==G.user&&t.gm&&!t.gm.interim),b=G.teams.find(t=>t.id!==G.user&&t!==a&&t.gm&&!t.gm.interim),g=a.gm;gmContact(a.id,'call');const before=JSON.stringify(G),rng=__rngState();for(let i=0;i<3;i++){gmContactView(a.id);gmContactBulkView([{tid:999,id:'missing'}]);}ok(JSON.stringify(G)===before&&__rngState()===rng,'쿨다운 조회 부작용');b.gm=g;ok(!gmContact(b.id,'call').ok,'같은 사람이 구단 이동 후 제한 회피');G=JSON.parse(JSON.stringify(G));personalMigrate();const migrated=JSON.stringify(G),r0=__rngState();personalMigrate();ok(JSON.stringify(G)===migrated&&__rngState()===r0,'개인 기록 수리 비멱등·난수');ok(!gmContact(b.id,'call').ok,'저장 뒤 인물 제한 소실');G.gmLine=[{name:'전임'}];ok(gmContact(b.id,'call').ok,'우리 후임이 전임의 제한 상속');});
T('[검수 11-18 #571 호환] 옛 출장 기록 복원은 멱등이며 캠프와 겹친 날을 한번만 제외한다 [개인경력검수]',()=>{fresh();const S=personalState(),d=KD(1,28);G.day=KD(5,1);S.trip={to:KD(12,15),l:'NPB 프런트 견학'};S.history=[{day:d,text:'NPB 프런트 견학: 2주 출장',amount:-30}];delete S.trips;personalMigrate();ok(S.trips.some(t=>t.from===d),'옛 활동 이력 출장 복원 누락');const j=JSON.stringify(G),r=__rngState();personalMigrate();ok(JSON.stringify(G)===j&&__rngState()===r,'출장 복원 부작용');ok(plDutyDays(d,d+14)===14,'캠프 겹친 출장 중복 제외');ok(plDutyDays(d,d+14,false)===14,'AI도 공통 캠프 제외');});
T('[검수 11-18 #572 연고] 재단 연고에 돌아오면 지급과 구단 관계 효과를 다시 받는다 [개인경력검수]',()=>{fresh();const S=personalState(),t=team(G.user);S.cash=100;S.found={y:G.year-1,paid:G.year-1,area:teamArea(G.user),list:[]};t.cityRel=50;prInit();const f0=G.pr.fan;foundYear(S);ok(t.cityRel===52&&G.pr.fan>f0,'같은 지역의 구단 효과 누락');const c=S.cash,rel=t.cityRel;foundYear(S);ok(S.cash===c&&t.cityRel===rel,'같은 해 중복 지급');});

function as573_store(fn){const old=globalThis.localStorage,mem={};globalThis.localStorage={getItem:k=>mem[k]??null,setItem:(k,v)=>mem[k]=String(v),removeItem:k=>delete mem[k]};try{return fn(mem);}finally{if(old===undefined)delete globalThis.localStorage;else globalThis.localStorage=old;_achMem=null;_achChamp0={};}}
function as573_season(){const U=G.user,y=G.year;G.ach={};G.achT={seasons:0,teams:[U],titles:{},profit:0,taxed:false,fired:false,ggMine:0,psRun:0,psBest:0,own:{}};G.myC.seas=[{y,tid:U,w:80,l:64,ch:1}];G.last={y,ps:{champ:U,first:U},order:G.teams.map(t=>({tid:t.id,w:t.id===U?80:70,l:t.id===U?64:74})),fins:{}};G.ps={seeds:[U],done:true,champ:U};return {U,y};}
T('[검수 11-18 #573] 오래 열린 탭의 업적 저장은 다른 탭의 칭호 선택과 해제를 지키며 명시적 선택만 바꾼다 [공용업적검수]',()=>{fresh();as573_store(mem=>{mem[ACH_KEY]=JSON.stringify({u:{dynasty:{at:1},firstYr:{at:2}},champ:{},title:'왕조 설계자'});_achMem=null;const A=achMeta(),ca={..._achChamp0};_achMem=null;achSetTitle('첫해의 기적');_achMem=A;_achChamp0=ca;achUnlock('fWin');ok(JSON.parse(mem[ACH_KEY]).title==='첫해의 기적','새 탭 칭호를 옛 탭이 덮음');const B=achMeta();_achMem=null;achSetTitle(null);_achMem=B;achUnlock('fDebut');ok(JSON.parse(mem[ACH_KEY]).title===null,'다른 탭 칭호 해제가 되돌아감');achSetTitle('왕조 설계자');ok(JSON.parse(mem[ACH_KEY]).title==='왕조 설계자','직접 선택이 저장되지 않음');});});
T('[검수 11-18 #574] 에디터 저장 우승은 공용 우승과 다음 일반 저장의 리그 정복에 섞이지 않는다 [공용업적검수]',()=>{fresh();as573_store(mem=>{const {U}=as573_season();mem[ACH_KEY]=JSON.stringify({u:{},champ:Object.fromEntries(G.teams.filter(t=>t.id!==U).map(t=>[t.id,1])),title:null});_achMem=null;G.edited=true;achCheck({k:'season'});ok(!(achMeta().champ[U]>0),'에디터 우승이 공용 집계에 들어감');ok(!achHas('champ1'),'에디터 개별 업적이 열림');G.edited=false;G.ach={};achProg();ok(!achHas('allMeta'),'편집 우승 때문에 일반 저장 리그 정복이 열림');});});
T('[검수 11-18 #575] 이름 변경은 개장 수를 늘리지 않고 실제 두 신구장만 개장 업적에 든다 [공용업적검수]',()=>{fresh();const U=G.user,S=stadOf(U);G.day=G.cal.open+30;G.gmSinceD=G.day-1;S.names=[];delete S.built;G.chron=[];G.gmLeg={hon:[],pres:null};legStadSet(U,'첫 이름');achFirstDaily();ok(!achHas('stadNew')&&achStadN()===0,'이름 변경으로 신구장 업적');S.proj={stage:'build',k:'big',cap:25000,cost:0,paid:0,done:G.day};newStadTeam(U);achFirstDaily();ok(achHas('stadNew')&&achStadN()===1,'실제 개장을 인정하지 않음');G.day++;legStadSet(U,'또 이름');achProg();ok(!achHas('stad2')&&achStadN()===1,'개장 뒤 이름 변경으로 두 번 개장');G.day++;S.proj={stage:'build',k:'dome',cap:26000,cost:0,paid:0,done:G.day};newStadTeam(U);achProg();ok(achHas('stad2')&&achStadN()===2,'실제 두 번째 개장이 누락');});
T('[검수 11-18 #575 호환] 옛 저장 개장 복원은 명명 이력과 구분하고 재실행·조회가 난수와 저장을 바꾸지 않는다 [공용업적검수]',()=>{fresh();const U=G.user,S=stadOf(U),d=G.day;G.startY=G.year-3;S.built=G.year;S.names=[{until:d-2,n:'옛 구장'},{until:d-1,n:'명명 후'},{until:d,n:'새 구장'}];G.chron=[{k:'honor',tid:U,d:d-2,t:'구장 이름을 바꿈'},{k:'stad',tid:U,d:d-1,t:'첫 새 구장 개장',source:'facility:stad:개장:첫 새 구장::'+(d-1)}];delete S.opens;const r=__rngState();achStadMigrate();const a=JSON.stringify(G);achStadMigrate();ok(JSON.stringify(G)===a&&__rngState()===r,'개장 복원 멱등·난수 위반');ok(achStadOpens(S).length===1&&achStadOpens(S)[0]===d-1,'이름 변경이 개장으로 복원');const b=JSON.stringify(G);achStadN();achStadN();ok(JSON.stringify(G)===b,'개장 조회가 저장 변경');});
T('[검수 11-18 #576] 이적 선수 대기록은 우리 구단 1군 기록만 합산하고 보관 선수도 같다 [공용업적검수]',()=>{for(const archived of [false,true]){fresh();as573_season();const U=G.user,y=G.year,op=otherT(),p=playersOf(U).find(q=>!q.isP);for(const q of Object.values(G.players))q.hist=(q.hist||[]).filter(h=>h.y!==y||h.lvl!=='1군');p.hist.push({y,t:U,lvl:'1군',g:30,pa:100,ab:90,h:20,hr:8},{y,t:op,lvl:'1군',g:110,pa:450,ab:400,h:110,hr:43});if(archived){archPlayer(p);delete G.players[p.id];}achCheck({k:'season'});ok(!achHas('sea50'),'타 구단 43홈런을 더해 대기록 업적 '+archived);const q=archived?archP(G.arch[p.id]):p;const ours=achSeasonMine(U,y).find(x=>x.p.id===p.id);ok(ours&&ours.h.hr===8,'구단 기록 합계가 다름 '+archived);const rows=archived?G.arch[p.id].rows:p.hist;rows.find(r=>r.y===y&&r.t===U).hr=50;delete G.achT.seaY;achCheck({k:'season'});ok(achHas('sea50'),'우리 구단 실제 50홈런이 누락 '+archived);}});

function ac577_last(y,U){G.year=y;G.last={y,ps:{champ:-1,runner:-1},order:G.teams.map(t=>({tid:t.id,w:80,l:64,t:0})),fins:{}};G.ps={seeds:[U]};G.myC.seas.push({y,tid:U,w:80,l:64,t:0,rank:3,ch:0});}
T('[검수 11-18 #577] 야인으로 건너뛴 해는 가을야구 연속 기록을 끊는다 [경력업적검수]',()=>{fresh();const U=G.user;G.ach={};G.achT={seasons:0,teams:[U],titles:{},profit:0,taxed:false,fired:false,ggMine:0,psRun:0,psBest:0,own:{}};G.myC.seas=[];for(let y=2026;y<=2029;y++){ac577_last(y,U);achCheck({k:'season'});}ok(G.achT.psRun===4,'연속 4년 준비');ac577_last(2031,U);achCheck({k:'season'});ok(G.achT.psRun===1&&!achHas('ps5'),'야인 공백이 5년 연속으로 이어짐 '+G.achT.psRun);for(let y=2032;y<=2035;y++){ac577_last(y,U);achCheck({k:'season'});}ok(achHas('ps5'),'실제 5년 연속 진출을 인정하지 않음');});
T('[검수 11-18 #578] 공동 1위는 정렬 앞뒤와 관계없이 첫 선두를 달성한다 [경력업적검수]',()=>{fresh();const U=G.user,A=otherT();G.ach={};G.day=G.cal.open+40;G.gmJoin=null;for(const t of G.teams)G.sea.rec[t.id]={w:5,l:10,t:0};G.sea.rec[U]={w:10,l:5,t:0};G.sea.rec[A]={w:10,l:5,t:0};ok(tieRank(standingsNow(),U)===1&&standingsNow()[0].tid!==U,'공동 1위 뒤 정렬 준비');achFirstDaily();ok(achHas('fLead'),'순위표 공동 1위인데 선두 업적 없음');});
T('[검수 11-18 #579] 경질 구단의 재취임은 다른 구단 재기가 아니다 [경력업적검수]',()=>{fresh();const U=G.user;G.day=G.cal.open+25;G.rep=0;G.ach={};G.achT=null;firedFlow(G.year,'동일 구단 복귀 검증');G.jobs=[{tid:U,exp:G.day+10,fired:false,done:false,terms:{sal:300,yrs:2}}];jobAnswer(U,true);ok(!G.unemp&&G.user===U,'동일 구단 재취임 준비');ok(!achHas('comeback'),'경질됐던 같은 구단에서 재기 업적 달성');});
T('[검수 11-18 #579 구분] 경질 뒤 다른 구단 취임은 재기를 달성한다 [경력업적검수]',()=>{fresh();const U=G.user,A=otherT();G.day=G.cal.open+25;G.rep=0;G.ach={};G.achT=null;firedFlow(G.year,'다른 구단 복귀 검증');G.jobs=[{tid:A,exp:G.day+10,fired:false,done:false,terms:{sal:300,yrs:2}}];jobAnswer(A,true);ok(!G.unemp&&G.user===A&&A!==U,'다른 구단 취임 준비');ok(achHas('comeback'),'실제 다른 구단 재기 누락');});
T('[검수 11-18 #580] 같은 해 후임 부임 이전 포스팅을 복원하지 않는다 [경력업적검수]',()=>{fresh();const U=G.user,d=G.cal.open+120;G.day=d;G.gmP={name:'후임검증',age:42,y0:G.year,d0:d};G.gmSince=G.year;G.gmSinceD=d;G.ach={};G.abroad=[{id:-1,name:'전임출국',from:U,how:'포스팅',club:'시험',y:G.year,d:d-1,foreign:null}];const before=__rngState();achFirstDaily();ok(!achHas('post1'),'전임이 전날 포스팅한 선수를 후임 업적으로 복원');ok(__rngState()===before,'업적 복원이 주 난수를 사용');G.abroad.push({id:-2,name:'후임출국',from:U,how:'포스팅',club:'시험',y:G.year,d:d+1,foreign:null});G.day++;achFirstDaily();ok(achHas('post1'),'후임 부임 후 포스팅도 누락');});
T('[검수 11-18 #580 당일] 동일 날짜 전임의 해외 진출은 후임 실적이 아니다 [경력업적검수]',()=>{fresh();const U=G.user,p=domestic(U).find(q=>!q.isP),d=G.cal.open+100;G.day=d;G.ach={};G.gmLine=[];ovsLeave(p,'MLB','뉴욕',2,500,'포스팅',100);const rec=G.abroad.find(x=>x.id===p.id);ok(rec&&rec.d===d,'실제 포스팅 기록 준비');G.gmLine.push({name:'전임',tid:U,from:G.year,to:G.year});G.gmP={name:'당일후임',age:42,y0:G.year,d0:d};G.gmSinceD=d;G.ach={};achFirstDaily();ok(!achHas('post1'),'같은 날짜의 전임 포스팅을 후임에게 귀속');});
T('[검수 11-18 #581] 올해 자진 사임은 이미 마친 전년도 시즌 수를 깎지 않는다 [경력업적검수]',()=>{fresh();const U=G.user,y=G.year;G.history=[{y:y-1,user:{w:80,l:64,rank:3}}];G.chron=[{y:y-1,d:dnum(y-1,1,1),tid:U,k:'join',gm:1,t:'단장 취임'},{y,d:dnum(y,6,1),tid:U,k:'fired',gm:1,t:'단장 자진 사임: 검증'}];G.myC.seas=[{y:y-1,tid:U,w:80,l:64,t:0,rank:3},{y,tid:U,w:18,l:20,t:0,rank:null,part:1,how:'자진 사임'}];G.achT=null;const T=achT();ok(T.seasons===1,'완료 시즌이 '+T.seasons+'개로 복원');const before=JSON.stringify(T),rng=__rngState();achBackfill(T);ok(JSON.stringify(T)===before&&__rngState()===rng,'경력 복원은 멱등이고 주 난수를 보존해야 함');});
T('[검수 11-18 #580 호환] 개인 키 없는 당일 전임 기록은 추측하지 않고 후임의 실제 포스팅은 인정한다 [경력업적검수]',()=>{fresh();const U=G.user,d=G.cal.open+100;G.day=d;G.gmLine=[{name:'전임',tid:U,from:G.year,to:G.year}];G.gmP={name:'후임',age:42,y0:G.year,d0:d};G.gmSinceD=d;G.ach={};G.abroad=[{id:-1,name:'옛당일',from:U,how:'포스팅',club:'시험',y:G.year,d,foreign:null}];achFirstDaily();ok(!achHas('post1'),'소유자가 없는 당일 전임 기록을 추측');const p=domestic(U).find(q=>!q.isP);ovsLeave(p,'MLB','뉴욕',2,500,'포스팅',100);achFirstDaily();ok(achHas('post1'),'후임 당일 실제 포스팅 누락');});
T('[검수 11-18 #577 결산] 완주 재임이 없는 해의 결산은 연속 기록을 즉시 끊는다 [경력업적검수]',()=>{fresh();const U=G.user;G.ach={};G.achT={seasons:4,teams:[U],titles:{},profit:0,taxed:false,fired:false,ggMine:0,psRun:4,psBest:4,own:{},seaY:G.year-1};G.myC.seas=[{y:G.year-1,tid:U,w:80,l:64,rank:3}];G.last={y:G.year,ps:{champ:-1,runner:-1},order:[]};G.unemp={from:U,k:'fired',since:G.day};achCheck({k:'season'});ok(G.achT.psRun===0&&!achHas('ps5'),'야인 결산 뒤 연속 기록 '+G.achT.psRun);});
T('[검수 11-18 #581 호환] 개인 시즌 표가 없는 옛 저장도 사임한 해와 완료한 해를 구분한다 [경력업적검수]',()=>{fresh();const U=G.user,y=G.year;G.myC.seas=[];G.gmLine=[];G.history=[{y:y-2,user:{}},{y:y-1,user:{}}];G.chron=[{y:y-2,d:dnum(y-2,1,1),tid:U,k:'join',gm:1,t:'단장 취임'},{y:y-1,d:dnum(y-1,6,1),tid:U,k:'fired',gm:1,t:'단장 자진 사임'}];G.achT=null;ok(achT().seasons===1,'완료한 해와 사임한 해가 잘못 복원 '+G.achT.seasons);});

function cr566_ps(){fresh();const y=G.year,U=G.user,ids=[U,...G.teams.map(t=>t.id).filter(t=>t!==U)];G.noRain=true;G.cal.end=KD(9,30);for(let i=0;i<ids.length;i++)G.sea.rec[ids[i]]={w:80-i*3,l:64+i*3,t:0};G.ps={done:true,round:'ks',order:ids.map(tid=>({tid,...G.sea.rec[tid]})),seeds:ids.slice(0,5),res:{wc:[ids[3],ids[4],2,0],spo:[ids[2],ids[3],3,1],po:[ids[1],ids[2],3,2],ks:[ids[0],ids[1],4,3]},champ:ids[0],runner:ids[1],finDay:dnum(y+1,1,2),cur:null};G.day=KD(12,31);G.res=null;G.live=null;G.stops=[];return {y,U,P:G.ps};}
T('[검수 11-18 #566] 새해보다 늦은 결산은 이전 시즌을 보존하고 정해진 날 한 번 마친다 [경력기록검수]',()=>{const {y,U,P}=cr566_ps();processDay();ok(G.ps===P&&G.sea.y===y&&G.year===y,'1월 1일에 결산 전 시즌을 지움');processDay();ok(G.last&&G.last.y===y&&G.last.ps.champ===U,'1월 2일 결산 누락');ok(G.year===y+1&&G.sea.y===y+1,'결산 뒤 새해 처리 누락');ok(G.fa&&G.fa.open&&!G.fa.closed&&G.fa.openDay===G.day+1,'늦은 새해 뒤 FA 시장이 영구 미개장');ok(G.contract&&G.contract.y===y,'지난 시즌 성적의 연봉 협상 누락');ok(G.personal?.advance?.[(y+1)+':'+U]>0,'미뤄진 새해 1월 급여 누락');ok((G.history||[]).filter(h=>h.y===y).length===1,'시즌 결산 중복');const age=playersOf(U)[0].age;processDay();ok(G.year===y+1&&playersOf(U)[0].age===age,'늦은 새해 처리 중복');});
T('[검수 11-18 #566] 직접 새해 처리도 미결산 가을야구를 지우지 않는다 [경력기록검수]',()=>{const {y,P}=cr566_ps();G.day=dnum(y+1,1,1);newYear();ok(G.year===y&&G.ps===P&&G.sea.y===y,'직접 새해 호출에서 기록 유실');});
T('[검수 11-18 #566 호환] 이미 결산한 해는 정상적으로 새해를 연다 [경력기록검수]',()=>{const {y}=cr566_ps();G.last={y};G.day=dnum(y+1,1,1);newYear();ok(G.year===y+1&&G.sea.y===y+1&&G.ps==null,'완료한 시즌의 새해가 막힘');});
function cr582_logs(){fresh();const U=G.user,op=G.teams.find(t=>t.id!==U).id,d=KD(9,22);G.day=d;G.cal.end=d;G.ps=null;G.sea.rec[U]={w:1,l:0,t:0};G.sea.tl=G.teams.map(()=>[]);G.sea.tl[U]=[[1,3,1,1,op,d]];G.games=[];G.gamesOff=[];G.sea.months=[{m:'9월',w:1,l:0,t:0}];G.sea.mark={w:1,l:0,t:0};return {U,op,d};}
T('[검수 11-18 #582] 시즌 마지막 달 마감 성적은 같은 달 이직 복귀 후에도 남는다 [경력기록검수]',()=>{const {U}=cr582_logs();userLogRebuild(U);ok(G.sea.months.some(x=>x.m==='9월'&&x.w===1&&x.l===0),'마감한 당월 성적 삭제');ok(G.sea.mark.w===1,'마감 누계 삭제');});
T('[검수 11-18 #583] 복귀 로그는 동일 점수 DH 두 경기의 ID 차전과 우천일을 복원한다 [경력기록검수]',()=>{const {U,op,d}=cr582_logs();G.sea.tl[U].push([1,3,1,1,op,d]);const g=i=>({gid:5830+i,day:d,home:U,away:op,hs:3,as:1,res:'승',kind:i===1?'개막전':'',dh:i,rmk:d-1});G.gamesOff=[g(2),g(1)];userLogRebuild(U);const L=G.sea.ulog;ok(L.length===2&&L[0].gid===5831&&L[1].gid===5832,'경기 ID 소실 또는 같은 경기 연결 '+JSON.stringify(L));ok(L[0].dh===1&&L[1].dh===2&&L.every(x=>x.rmk===d-1),'DH 순번 또는 우천 정보 소실');ok(L[0].k==='개막전','경기 종류 소실');});
T('[검수 11-18 #582 #583 호환] 기록 수리는 난수를 쓰지 않고 중계 대기를 유지하며 멱등이다 [경력기록검수]',()=>{const {U,op,d}=cr582_logs();G.games=[{gid:5839,day:d,home:U,away:op,hs:3,as:1,res:'승',kind:'',dh:1}];G.sea.ulog=[{d,h:U,a:op,hs:3,as:1,res:'승',k:''}];G.res={i:0};const rng=__rngState();if(typeof userLogMigrate==='function')userLogMigrate();ok(G.sea.ulog[0].gid===5839&&G.sea.months[0].w===1,'불러오기 메타데이터 수리 누락');const saved=JSON.stringify([G.sea.ulog,G.sea.months,G.sea.mark]);userLogMigrate();ok(__rngState()===rng&&G.res.i===0&&JSON.stringify([G.sea.ulog,G.sea.months,G.sea.mark])===saved,'조회 난수 또는 중계 대기 변경·비멱등');});
T('[검수 11-18 #582 #583] 실제 이직 후 같은 달 복귀도 마감 성적과 두 DH 기록을 유지한다 [경력기록검수]',()=>{const {U,op,d}=cr582_logs();G.sea.rec[U]={w:2,l:0,t:0};G.sea.tl[U].push([1,3,1,1,op,d]);G.sea.tl[op]=[[-1,1,3,0,U,d],[-1,1,3,0,U,d]];G.sea.rec[op]={w:0,l:2,t:0};G.games=[{gid:58312,day:d,home:U,away:op,hs:3,as:1,res:'승',kind:'',dh:2},{gid:58311,day:d,home:U,away:op,hs:3,as:1,res:'승',kind:'개막전',dh:1}];switchTeam(op);switchTeam(U);ok(G.sea.months.some(x=>x.m==='9월'&&x.w===2),'실제 복귀 월 성적 소실');ok(G.sea.ulog[0].gid===58311&&G.sea.ulog[1].gid===58312&&G.sea.ulog[0].dh===1&&G.sea.ulog[1].dh===2,'실제 복귀 DH 구분 소실');});

T('[검수 11-18 #582 호환] 날짜 없는 옛 로그나 일부 기록만으로 마감 월별 합계를 지우지 않는다 [경력기록검수]',()=>{const {U,op,d}=cr582_logs();const before=JSON.stringify([G.sea.months,G.sea.mark]),rng=__rngState();for(const L of [[],[[1,3,1,1,op]],[[1,3,1,1,op,d]]]){G.sea.rec[U]={w:2,l:0,t:0};G.sea.tl[U]=L;if(typeof userLogMigrate==='function')userLogMigrate();ok(JSON.stringify([G.sea.months,G.sea.mark])===before,'불완전한 옛 로그가 확정 월 성적 삭제');}ok(__rngState()===rng,'호환 수리가 난수를 소비');});

function lg554_completion(mode){fresh();const U=G.user,y=G.year;G.day=KD(10,15);G.history=[];G.gmP={name:'완주전임',age:45,y0:y};G.myC.seas=[{y,tid:U,w:80,l:64,t:0,ch:1,rank:1}];G.gmLine=[];if(mode==='old')G.gmRec={y:y-1,L:[{k:'u0',n:'완주전임',t:U,y0:y,y1:y,s:1,w:160,l:128,c:1,u:1}]};else delete G.gmRec;const D=legEnsure();ok(legAt(legMeK(),U).w===80,'개인 시즌 복원 준비');G.last={y,order:G.teams.map(t=>({tid:t.id,w:t.id===U?80:60,l:t.id===U?64:84,t:0})),ps:{champ:U}};const rng=__rngState();legSeason({[U]:{k:legMeK(),n:legMeName(),u:1,w:0,l:0,ties:0,endD:G.day}});const a=legAt(legMeK(),U);ok(a.w===80&&a.l===64&&a.s===1&&a.c===1,'복원한 완료 시즌 중복 '+JSON.stringify(a));ok(D.y===y&&D.L.filter(x=>!x.u&&x.y1===y&&x.s===1).length===G.teams.length-1,'다른 단장들의 같은 해 결산이 빠짐');ok(__rngState()===rng,'결산 복원은 주 난수 불변');}
T('[검수 11-18 #554 결산복원] 결산 전 완료 경력을 복원해도 그 단장 시즌은 한 번만 센다 [단장레거시검수]',()=>lg554_completion('none'));
T('[검수 11-18 #554 마이그레이션] 옛 중복 기록 복구 뒤 결산도 한 번만 반영한다 [단장레거시검수]',()=>lg554_completion('old'));
T('[검수 11-18 #556 계보복원] 전임의 최종 시즌 복원과 결산이 겹쳐도 정확한 공로를 남긴다 [단장레거시검수]',()=>{fresh();const U=G.user,y=G.year;G.day=KD(10,15);G.history=[];G.gmP={name:'새후임',age:42,y0:y};G.myC.seas=[];G.gmJoin={y,tid:U,w:80,l:64,t:0,psDone:true};G.gmLine=[{name:'완주전임',tid:U,from:y-9,to:y,seas:10,w:800,l:640,champ:2,seasL:Array.from({length:10},(_,i)=>({y:y-9+i,tid:U,w:80,l:64,t:0,ch:i===0||i===9?1:0,rank:1}))}];delete G.gmRec;G.gmLeg=null;legEnsure();G.last={y,order:G.teams.map(t=>({tid:t.id,w:80,l:64,t:0})),ps:{champ:U}};legSeason({[U]:{k:'u0',n:'완주전임',u:1,w:0,l:0,endD:G.day}});const a=legAt('u0',U),h=G.gmLeg?.hon.find(x=>x.k==='u0'&&x.t===U);ok(a.s===10&&a.w===800&&a.c===2,'계보 최종 시즌 중복 '+JSON.stringify(a));ok(h&&h.s===10&&h.c===2&&h.n==='완주전임','이미 복원한 전임 공로자 누락 '+JSON.stringify(h));});

T('[검수 11-18 #581 결산 복원] 첫 결산에서 경력을 복원해도 올해 완료 시즌을 두 번 세지 않는다 [경력업적교차검수]',()=>{fresh();const U=G.user,y=G.year;G.ach={};G.achT=null;G.myC.seas=[{y,tid:U,w:80,l:64,t:0,rank:3,ch:0}];G.history=[{y,user:{w:80,l:64,rank:3}}];G.last={y,ps:{champ:-1,runner:-1},order:G.teams.map(t=>({tid:t.id,w:80,l:64,t:0})),fins:{}};G.ps={seeds:[U],done:true,finDay:G.day};achCheck({k:'season'});ok(G.achT.seasons===1,'올해 한 시즌이 '+G.achT.seasons+'회로 집계');const n=JSON.stringify(G.achT);achCheck({k:'season'});ok(JSON.stringify(G.achT)===n,'같은 결산 재조회 중복 반영');});
T('[검수 11-18 #580 무일자] 같은 해 새 구단 부임 전 날짜 없는 포스팅은 전임 실적으로 둔다 [경력업적교차검수]',()=>{fresh();const U=G.user,d=G.cal.open+100;G.day=d;G.gmP={name:'이직단장',age:45,y0:G.year,d0:d-100};G.gmLine=[];G.gmSince=G.year;G.gmSinceD=d;G.ach={};G.abroad=[{id:-1,name:'전임출국',from:U,how:'포스팅',club:'시험',y:G.year,foreign:null}];achFirstDaily();ok(!achHas('post1'),'날짜 없는 같은 해 AI 전임 출국을 이직단장에게 귀속');});
T('[검수 11-18 #581 우승 복원] 첫 결산에 복원한 올해 우승은 한 시즌 한 번만 남긴다 [경력업적교차검수]',()=>{fresh();const U=G.user,y=G.year;G.ach={};G.achT=null;G.myC.seas=[{y,tid:U,w:80,l:64,t:0,rank:1,ch:1}];G.history=[{y,user:{w:80,l:64,rank:1},champ:U}];G.chron=[{y,d:G.day,tid:U,k:'join',gm:1,t:'단장 취임'},{y,d:G.day,tid:U,k:'champ',gm:1,t:'한국시리즈 우승'}];G.last={y,ps:{champ:U,runner:-1,first:U},order:G.teams.map(t=>({tid:t.id,w:80,l:64,t:0})),fins:{}};G.ps={seeds:[U],done:true,finDay:G.day};achCheck({k:'season'});ok(G.achT.titles[U].length===1&&achTitlesN(G.achT)===1,'복원 뒤 올해 우승이 중복 '+JSON.stringify(G.achT.titles));});
function pt584Setup(){fresh();G.day=KD(11,28);G.rolled=G.year;G.posting=[];G.evs=[];G.mail=[];G.stops=[];const p=domestic(G.user).find(q=>!q.foreign&&!q.prospect&&!q.ys);delete p.mil;delete p.lastFA;delete p.ovsY;delete p.retFrom;delete p.postPromise;delete p.postPromiseT;p.faN=0;p.faC=false;p.ext=false;p.svc=8;p.age=28;p.mlb=75;p.joinY=G.year-8;setOvr(p,65);return p;}
function pt584Request(p,promised=false){return evNew('post',p.name+' 포스팅 요청','검수',[{l:'허락'},{l:'내년 약속'},{l:'거절'}],{data:{pid:p.id,promised,day:postDay()},def:0,exp:12});}
T('[검수 11-18 #584] 선수 요청 허락과 자동 허락도 12월 5일 신청 마감을 따른다 [포스팅복귀검수]',()=>{for(const auto of [false,true]){const p=pt584Setup(),e=pt584Request(p);G.day=KD(12,6);ok(postGMWhy(p).includes('12월 5일'),'직접 신청 마감 준비');const r=evPick(e.id,0,auto);ok(!(G.posting||[]).some(x=>x.pid===p.id&&!x.void),'늦은 선수 요청 접수 '+auto+' '+r);}});
T('[검수 11-18 #585] 이적한 신청은 결과일까지 기다리지 않고 무효가 되어 새 구단이 신청한다 [포스팅복귀검수]',()=>{const p=pt584Setup(),a=G.user,b=otherT(),x=postStart(p);p.team=b;mvLog('트레이드',p,a,b);G.user=b;ok(!postGMWhy(p).includes('이미 포스팅'),'새 구단 신청이 옛 신청에 막힘');ok(x.void&&x.done,'이적 신청 즉시 정리 누락');const r=postGM(p.id);ok(G.posting.some(q=>q.pid===p.id&&q.tid===b&&!q.void),'새 구단 재신청 실패 '+r);});
T('[검수 11-18 #586] 다른 구단을 거쳐 돌아와도 전 재임 신청이 다시 유효해지지 않는다 [포스팅복귀검수]',()=>{const p=pt584Setup(),a=G.user,b=otherT(),x=postStart(p);p.team=b;mvLog('트레이드',p,a,b);G.day++;p.team=a;mvLog('트레이드',p,b,a);G.day=x.day;withRng(42,()=>ovsDaily());ok(x.void&&x.res==='취소','돌아온 선수의 옛 신청이 일반 결과로 처리 '+JSON.stringify(x));ok(G.players[p.id]===p,'무효 신청으로 해외 진출');});
T('[검수 11-18 #587] 응찰 가능성이 없는 고령 선수는 신청과 계약 전망을 만들지 않는다 [포스팅복귀검수]',()=>{const p=pt584Setup();p.age=38;ok(ovsAgeT(p.age).m===0&&ovsAgeT(p.age).n===0,'나이 준비');const why=postGMWhy(p),E=postEst(p),txt=postEstTxt(E);ok(!!why,'38세 직접 신청 허용');ok(E.n[1]===0&&E.amt[1]===0&&E.fee[1]===0,'응찰 0인데 양수 계약 전망 '+JSON.stringify(E));ok(!txt.includes('보장 연'),'응찰 0인데 계약 예상액 표시 '+txt);const e=pt584Request(p);evPick(e.id,0);ok(!G.posting.some(x=>x.pid===p.id),'선수 요청에서 고령 응찰0 신청');});
T('[검수 11-18 #588] 포스팅 약속 이행은 직접 신청과 요청 허락이 같은 에이전트 기억을 남긴다 [포스팅복귀검수]',()=>{for(const direct of [false,true]){const p=pt584Setup(),ag=Object.values(agInit()).find(a=>!a.self&&a.act!==false);p.agId=ag.id;delete ag.rel;delete ag.mem;p.postPromise=G.year;p.postPromiseT=G.user;const before=agRel(ag,G.user);if(direct)postGM(p.id);else evPick(pt584Request(p,true).id,0);ok(agRel(ag,G.user)===before+1&&agMemOf(ag,G.user)?.c==='kept','약속 이행 누락/중복 '+direct+' '+agRel(ag,G.user));ok(!p.postPromise,'이행 뒤 약속 삭제 누락');}});
T('[검수 11-18 #589] 직접 신청은 열린 요청의 원본 메일과 멈춤 목록까지 닫는다 [포스팅복귀검수]',()=>{const p=pt584Setup(),e=pt584Request(p),m=G.mail.find(m=>m.id===e.mid);ok(m.imp&&m.acts.length===3,'원본 메일 준비');postGM(p.id);ok(e.done&&!m.imp&&m.read&&m.acts.length===0,'직접 신청 후 원본 메일 미결');ok(!G.stops.some(m=>m.id===e.mid),'직접 신청 후 멈춤 목록 잔류');});
T('[검수 11-18 #590] 아시아쿼터 잔류 안내는 실제 25퍼센트 확률을 쓴다 [포스팅복귀검수]',()=>{fresh();G.day=KD(11,1);const p=foreignOf(G.user).find(p=>p.foreign==='아시아');ok(p,'아시아 선수 준비');p.age=28;p.mor=60;p.joinY=G.year-1;p.fMulti=0;p.fCtY=0;delete p.ovsOffer;const a=seasonWar;seasonWar=q=>q.id===p.id?6:0;try{for(let i=0;i<200&&!(G.evs||[]).some(e=>e.k==='fovs'&&e.data.pid===p.id);i++)fOverseas();}finally{seasonWar=a;}const e=G.evs.find(e=>e.k==='fovs'&&e.data.pid===p.id);ok(e,'NPB 제안 생성 실패');ok(fovsKeepOdds(p,'NPB')===.25,'실제 확률 준비');ok(e.opts[0].fx.includes('25%')&&!e.opts[0].fx.includes('절반'),'실제25퍼센트와 안내 불일치 '+e.opts[0].fx);});
T('[검수 11-18 #591] 복귀 계약 결재 거절은 수동 자동 모두 보류권과 미결 협상을 보존한다 [포스팅복귀검수]',()=>{for(const auto of [false,true]){const p=pt584Setup(),tid=G.user;p.team=null;p.retFrom=tid;p.retAsk={sal:100000,yrs:3,lg:'MLB',n:2,exp:G.day+14,post:1};ovsBackAsk(p);const e=G.evs.find(e=>e.k==='ovsback'&&e.data.pid===p.id),m=G.mail.find(m=>m.id===e.mid),check=ovsCapCheck;ovsCapCheck=()=>({ok:false,msg:'구단주 결재 거절',hard:true});try{const r=evPick(e.id,0,auto);ok(p.retFrom===tid&&p.retAsk&&p.team==null,'결재 거절만으로 보류권 해제 '+auto+' '+r);ok(!p.relBan?.[tid]&&!p.freeSince,'결재 거절만으로 재계약 금지/FA');ok(!e.done&&m.acts.length===2&&m.imp,'결재 거절로 협상 카드 종료');}finally{ovsCapCheck=check;}const cc=ovsCapCheck;ovsCapCheck=()=>null;try{evPick(e.id,0,auto);}finally{ovsCapCheck=cc;}ok(p.team===tid&&!p.retAsk&&e.done,'조건 보완 후 다시 계약 불가');}});
T('[검수 11-18 #591 만료] 계약하지 않음을 고른 실제 만료 기본안은 보류권을 해제한다 [포스팅복귀검수]',()=>{const p=pt584Setup(),tid=G.user;p.team=null;p.retFrom=tid;p.retAsk={sal:200,yrs:1,lg:'MLB',n:1,exp:G.day+14,post:1};ovsBackAsk(p);const e=G.evs.find(e=>e.k==='ovsback'&&e.data.pid===p.id);G.day=e.exp+1;evDaily();ok(e.done&&!p.retAsk&&p.retFrom==null&&p.relBan?.[tid]===G.day+365,'실제 기한 만료의 거절 처리 달라짐');});
T('[검수 11-18 #585 #586 호환] 옛 왕복 이적 신청과 요청 정리는 멱등이며 조회 난수를 쓰지 않는다 [포스팅복귀검수]',()=>{const p=pt584Setup(),tid=G.user,b=otherT(),d=G.day,e=pt584Request(p),x=postStart(p);delete x.st;delete x.d;delete x.mv;e.done=false;e.data={pid:p.id,promised:false,day:x.day};const m=G.mail.find(m=>m.id===e.mid);m.acts=[{a:'evPick',v:e.id+':0'}];m.imp=true;G.moves.push({pid:p.id,y:G.year,d:d+1,from:tid,to:b},{pid:p.id,y:G.year,d:d+2,from:b,to:tid});G.day=d+3;const rng=__rngState(),mor=p.mor;if(typeof postFix==='function')postFix();ok(x.void&&e.done&&e.void&&!m.acts.length,'옛 왕복 이적 신청/요청이 유지');const a=JSON.stringify([G.posting,G.evs,G.mail,G.stops]);postFix();postGMWhy(p);postEst(p);ok(JSON.stringify([G.posting,G.evs,G.mail,G.stops])===a&&__rngState()===rng&&p.mor===mor,'이전 신청 정리 비멱등/기분/난수');});
T('[검수 11-18 #584 경계] 마지막 신청일의 요청 허락은 정상 접수한다 [포스팅복귀검수]',()=>{const p=pt584Setup(),e=pt584Request(p);G.day=KD(12,5);evPick(e.id,0);ok(e.done&&G.posting.some(x=>x.pid===p.id&&!x.void),'12월5일 정상 신청 거절');});
T('[검수 11-18 #585 약속] 이동 훅은 새 구단에서 방금 맺은 포스팅 약속을 지우지 않는다 [포스팅복귀검수]',()=>{const p=pt584Setup(),a=G.user,b=otherT();p.team=b;p.postPromise=G.year+1;p.postPromiseT=b;mvLog('FA 영입',p,a,b);ok(p.postPromise===G.year+1&&p.postPromiseT===b,'신규 계약의 새 구단 약속 삭제');});

function wbc600Setup(){fresh();G.year=2030;G.cal=buildCalendar(G.year);G.day=KD(2,24);const p=domestic(G.user).find(p=>!p.isP&&!p.foreign),q=JSON.parse(JSON.stringify(p));q.age=31;for(const k in q.r)if(typeof q.r[k]==='number')q.r[k]=75;delete q.ntcr;delete G.players[p.id];const a={id:q.id,name:q.name,isP:false,pos:posLabel(q),foreign:null,from:G.user,lg:'MLB',club:MLBT[0],how:'포스팅',yrs:1,amt:300,y:2027,y1:2028,age:31,lines:[],back:false,pj:ovsPj(q),d:dnum(2027,11,1),ci:ovlIdx('MLB',MLBT[0])};G.abroad=[a];return {a,q};}
T('[검수 11-18 #600] WBC 해외파는 이미 성장한 현재 나이를 한번만 쓴다 [해외대표검수]',()=>{const {a}=wbc600Setup(),x=ntAbroad()[0];ok(x&&x.sn.age===31,'현재31세를 다시 체류연수만큼 가산 '+x?.sn?.age);const y={id:a.id,name:a.name,pos:a.pos,isP:false,o:75};ntOvsFix(y);ok(y.sn.age===31,'옛 명단 사본에 나이 중복');NT_TMP=[];const p=ntOvsTmp(x);ok(p.age===31,'실제 경기용 선수 나이 중복 '+p.age);for(const id of NT_TMP)delete G.players[id];NT_TMP=[];});
T('[검수 11-18 #601] WBC 해외파 소집일 재검사는 잔류 선수의 새 소속과 모습을 반영한다 [해외대표검수]',()=>{const {a}=wbc600Setup(),N={k:'wbc',y:G.year,ids:[],ovs:ntAbroad()};const q=JSON.parse(a.pj);a.club=MLBT[1];q.bt=q.bt==='좌'?'우':'좌';a.pj=ovsPj(q);ntOvsRecheck(N);ok(N.ovs.length===1&&N.ovs[0].id===a.id,'기존 발탁선수 누락');ok(N.ovs[0].club===a.club&&N.ovs[0].sn.bt===q.bt,'소속 또는 소집일 모습이 옛 발표에 고정 '+N.ovs[0].club);});
T('[검수 11-18 #602] 해외파 WBC 4경기 2홈런은 실제 국내 복귀 뒤 개인 통산에 남는다 [해외대표검수]',()=>{const {a}=wbc600Setup(),T={k:'wbc',y:G.year,res:'4강',done:true,st:{}};T.st['o'+a.id]={P:0,g:4,pa:16,ab:14,h:5,hr:2,rbi:4,bb:2};ntCareerAdd(T);G.day=KD(11,1);a.y1=G.year;const f=ovsBackRoll;ovsBackRoll=()=>true;try{abroadYear();}finally{ovsBackRoll=f;}const p=G.players[a.id];ok(a.back&&p,'실제 국내 복귀 준비 실패');ok(p.ntcr?.b?.g===4&&p.ntcr.b.hr===2&&p.ntcr.ev.length===1,'복귀 선수 대표 통산 누락 '+JSON.stringify(p.ntcr));});
T('[검수 11-18 #600 호환] 현재 해외 나이 조회와 옛 대표 명단 수리는 난수 보존 멱등이다 [해외대표검수]',()=>{const {a}=wbc600Setup(),before=JSON.stringify(G),r=__rngState(),x=ntAbroad()[0];ok(JSON.stringify(G)===before&&__rngState()===r,'선발 조회 부작용');x.sn.age=34;G.nt={k:'wbc',y:G.year,ids:[],ovs:[x]};ntLoadFix();ok(x.sn.age===31,'이미 저장된 중복 나이 복원 실패');const j=JSON.stringify(G);ntLoadFix();ok(JSON.stringify(G)===j&&__rngState()===r,'대표 명단 수리 비멱등·난수');G.nt.tour={done:true};x.sn.age=29;ntLoadFix();ok(x.sn.age===29,'완료 대회의 역사적 모습 변경');});
T('[검수 11-18 #602 호환] 옛 완료 WBC 해외 기록도 복원하고 재저장 뒤 중복 합산하지 않는다 [해외대표검수]',()=>{const {a}=wbc600Setup(),T={k:'wbc',y:G.year,res:'4강',done:true,cr:1,st:{}};T.st['o'+a.id]={P:0,g:4,pa:16,ab:14,h:5,hr:2,rbi:4,bb:2};G.nt={k:'wbc',y:G.year,ids:[],ovs:ntAbroad(),tour:T};const r=__rngState();ntSaveFix();ok(JSON.parse(a.pj).ntcr?.b.hr===2&&a.ntcr?.b.g===4,'옛 해외 기록 복원 실패');G=JSON.parse(JSON.stringify(G));const j=JSON.stringify(G);ntSaveFix();ok(JSON.stringify(G)===j&&__rngState()===r,'해외 통산 복원 중복·난수');const b=G.abroad[0],p=JSON.parse(b.pj);delete p.ntcr;ntAbroadCareerRestore(b,p);ok(p.ntcr.b.hr===2,'원본 사본 누락 시 복귀 보완 실패');p.ntcr.ev.push('2031 프리미어12 우승');p.ntcr.b.hr++;ntAbroadCareerRestore(b,p);ok(p.ntcr.b.hr===3&&p.ntcr.ev.length===2,'복귀 뒤 새 국내 대표 실적을 옛 해외 사본으로 덮음');});
T('[검수 11-18 #602 역할] 국내와 해외 선수는 같은 타격 투구 대표 통산을 따로 합산한다 [해외대표검수]',()=>{const {a}=wbc600Setup(),p=domestic(G.user).find(p=>!p.isP),S={P:0,g:2,pa:8,ab:7,h:3,hr:1,bb:1,x:{P:1,g:1,outs:3,h:1,er:0,so:2}},T={k:'wbc',y:G.year,res:'우승',done:true,st:{}};p.ntc=G.year+2;T.st[p.id]=JSON.parse(JSON.stringify(S));T.st['o'+a.id]=JSON.parse(JSON.stringify(S));const r=__rngState();ok(ntCareerAdd(T)===2,'국내·해외 양쪽 집계 실패');const c=JSON.parse(a.pj).ntcr;ok(JSON.stringify(c)===JSON.stringify(p.ntcr),'국내·해외 통산 규칙 불일치');ok(c.b.h===3&&c.p.h===1&&p.ntc===G.year+2,'역할 혼합 또는 거부권 훼손');const b=JSON.stringify([a,p.ntcr]);ntCareerAdd(T);ok(JSON.stringify([a,p.ntcr])===b&&__rngState()===r,'대회 재집계 중복 또는 난수');});

const wd592_bat=(y,lvl,pa=400,g=Math.round(pa/4.1))=>({y,lvl,c:0,g,pa,ab:Math.round(pa*.85),h:Math.round(pa*.26),d:20,tr:1,hr:12,bb:Math.round(pa*.1),hbp:2,so:80,sb:4,sf:3});
const wd592_setup=()=>{fresh();G.day=KD(7,15);G.abroad=[];G.fmarket=[];G.fwatch=[];const p=newForeign('용병',{market:true,isP:false});p.age=29;p.team=G.user;p.hist=[{...wd592_bat(G.year-1,'1군',500,125),t:G.user}];p.mlbG=0;setOvr(p,57);return p;};
const wd592_rec=(p,lines)=>({id:p.id,name:p.name,isP:!!p.isP,pos:posLabel(p),foreign:p.foreign,from:G.user,lg:'MLB',club:ovlNm('MLB',0),ci:0,how:'KBO 퇴단',y:G.year-2,y1:G.year-1,age:p.age,lines,back:false,fr:ovsSlim(p)});
T('[검수 11-18 #592] 복귀 외국인이 다시 해외 계약을 맺어도 한 사람의 기록을 잇는다 [해외세계검수]',()=>{const p=wd592_setup(),old=wd592_rec(p,[wd592_bat(G.year-1,'MLB',220,54)]);old.back=true;delete old.fr;G.abroad=[old];ovsLeave(p,'NPB',ovlNm('NPB',0),2,200,'외국인');const A=G.abroad.filter(a=>a.id===p.id);ok(A.length===1&&A[0].lg==='NPB'&&!A[0].back,'같은 ID 중복 해외파 '+JSON.stringify(A.map(a=>[a.id,a.lg,a.back])));ok(A[0].lines.length===1&&A[0].lines[0].lvl==='MLB'&&A[0].lines[0].g===54,'재출국에서 과거 MLB 기록 소실');});
T('[검수 11-18 #592 복원] 옛 중복 ID는 최신 행선지와 모든 기록을 보존해 멱등 병합한다 [해외세계검수]',()=>{const p=wd592_setup(),old=wd592_rec(p,[wd592_bat(G.year-1,'MLB',220,54)]),now=wd592_rec(p,[]);old.back=true;delete old.fr;now.lg='NPB';now.y=G.year;now.y1=G.year+1;now.club=ovlNm('NPB',0);G.abroad=[now,old];delete G.players[p.id];const r=__rngState();ok(typeof ovsTrackMigrate==='function','중복 ID 복원 함수 없음');ovsTrackMigrate();ok(G.abroad.length===1&&G.abroad[0]===now&&now.lg==='NPB'&&now.lines[0].g===54,'현재 행선지 또는 역사 소실');const s=JSON.stringify(G.abroad);ovsTrackMigrate();ok(JSON.stringify(G.abroad)===s&&__rngState()===r,'중복 정리 멱등/난수 불변 실패');});
T('[검수 11-18 #594] 혼합 시즌의 보조 MLB 주전 기록도 복귀 제외 조건에 포함한다 [해외세계검수]',()=>{const p=wd592_setup(),a=wd592_rec(p,[{...wd592_bat(G.year,'트리플A',360,90),x:wd592_bat(G.year,'MLB',340,85)}]);delete G.players[p.id];const r=__rngState();ok(ovsRetChance(a)===0,'보조 MLB 340PA 선수가 복귀 후보');a.lines[0].x.pa=40;ok(ovsRetChance(a)>0,'짧은 MLB 콜업도 일괄 제외');a.fr={...a.fr,isP:true,role:'SP'};a.isP=true;a.lines=[{y:G.year,lvl:'트리플A',outs:400,g:24,x:{lvl:'MLB',outs:301,g:18}}];ok(ovsRetChance(a)===0,'보조 MLB 선발 301아웃 선수가 복귀 후보');ok(__rngState()===r,'복귀 가능성 조회 난수 소비');});
T('[검수 11-18 #595] MLB 통산은 혼합 기록의 실제 경기 수를 더하고 재출국에도 중복하지 않는다 [해외세계검수]',()=>{const p=wd592_setup(),id=p.id,a=wd592_rec(p,[wd592_bat(G.year-1,'MLB',20,5),{...wd592_bat(G.year,'트리플A',360,90),x:wd592_bat(G.year,'MLB',220,54)}]);G.abroad=[a];delete G.players[id];const q=ovsRevive(a);ok(q.mlbG===59,'보조 MLB 경기 누락 '+q.mlbG);q.hist=[{...wd592_bat(G.year,'1군',500,125),t:G.user}];q._ovsLg='NPB';dropP(id);const b=G.abroad.find(x=>x.id===id);ok(b&&!b.back&&b.fr,'재출국 준비 실패');G.year++;G.day=KD(12,1);b.lines.push(wd592_bat(G.year,'NPB',400,100));const z=ovsRevive(b);ok(z.mlbG===59,'두 번째 복귀에서 MLB 경기를 다시 합산 '+z.mlbG);});
T('[검수 11-18 #596] 시즌 중 추적을 시작한 후보는 즉시 현재 해외 성적과 주목 목록을 갖는다 [해외세계검수]',()=>{const p=wd592_setup();p.team=null;p.hist=[];p.prevLvl='트리플A';p.prev=wd592_bat(G.year-1,'트리플A');const r=__rngState();ovsTrackCand(p,'MLB');const a=G.abroad.find(x=>x.id===p.id);ok(a?.cur?.y===G.year&&((a.cur.pa||0)+(a.cur.outs||0))>0,'현재 시즌 미생성');ok(ovlTopPool().R.some(x=>x.abr&&x.id===p.id),'진행 중 주목 목록에 새 추적 후보 누락');ok(__rngState()===r,'현재 성적 생성이 본 난수를 소비');});
T('[검수 11-18 #597] 시장에서 돌아온 후보의 올해 누적 기록은 후보군에서 이어진다 [해외세계검수]',()=>{const p=wd592_setup();p.team=null;p.hist=[];p.prevLvl='트리플A';const e=ovpE(p,[ovpLineE(wd592_bat(G.year-1,'트리플A'),G.year-1)]);e.cur=ovpLineE(wd592_bat(G.year,'트리플A',600,150),G.year);G.ovp={v:1,L:[e]};delete G.players[p.id];const q=ovpP(e),pa=q.now.pa,r=__rngState();ok(ovpBack(q),'후보군 복귀 거절');delete G.players[q.id];const z=G.ovp.L.find(x=>x.i===q.id),row=ovpTopRows(G.year).find(x=>x.id===q.id);ok(z?.cur?.y===G.year&&row?.h.pa===pa,'후보군 복귀로 올해 누적 삭제 '+JSON.stringify([z?.cur,row?.h,pa]));ok(__rngState()===r,'후보군 복귀 난수 소비');});
T('[검수 11-18 #598] 이전 시즌과 다른 리그에서 뛴 후보도 올해 새 리그 성적을 공개한다 [해외세계검수]',()=>{const p=wd592_setup();p.team=null;p.hist=[];p.prevLvl='트리플A';const e=ovpE(p,[ovpLineE(wd592_bat(G.year-1,'트리플A'),G.year-1)]);e.l='NPB 1군';e.cur={...ovpLineE(wd592_bat(G.year,'NPB 1군',480,120),G.year)};G.ovp={v:1,L:[e]};delete G.players[p.id];const q=ovpP(e);G.fmarket=[q.id];ok(q.prevLvl==='트리플A'&&q.now?.lvl==='NPB 1군'&&q.now.pa>0,'작년 리그 때문에 현재 NPB 기록 누락');const row=ovlTopPool().R.find(x=>x.id===q.id);ok(row?.lvl==='NPB 1군'&&row.h.pa===q.now.pa,'공개 현재 데이터가 작년 리그에 머묾');ok(ovpBack(q),'후보군 재복귀 거절');const z=G.ovp.L.find(x=>x.i===q.id);ok(z.l==='NPB 1군'&&z.cur.l==='NPB 1군','다시 돌아갈 때 새 리그를 잃음');});
T('[검수 11-18 #599] 미리 안내한 국내 복귀는 해외 이적보다 우선하고 기존 난수 슬롯을 보존한다 [해외세계검수]',()=>{const p=wd592_setup();p.foreign=null;p.age=29;setOvr(p,68);let offers=0;for(let sd=1;sd<=40;sd++){const a={lg:'NPB',club:ovlNm('NPB',0),ci:0,yrs:2,y1:G.year-1,from:G.user,bn:{y:G.year,v:1},lines:[]},b=JSON.parse(JSON.stringify(a));let ra,rb;withRng(sd,()=>{ovsMoveKr(a,p,true,2,true,[],true);ra=R();});withRng(sd,()=>{const r=ovsMoveKr(b,p,true,2,true,[],false);if(r&&r!=='re')offers++;rb=R();});ok(a.lg==='NPB','복귀 예고 뒤 MLB로 이동 '+sd);ok(ra===rb,'막힌 이적이 기존 난수 순서를 바꿈 '+sd);}ok(offers>0,'해외 이적 제안 분기 준비 실패');});
T('[검수 11-18 #612] 해외 현역 국내 선수만으로 120명을 넘어도 현역을 삭제하지 않는다 [해외세계검수]',()=>{fresh();const p=domestic(G.user).find(x=>!x.isP&&!x.prospect),seed={name:p.name,isP:false,foreign:null,from:G.user,lg:'MLB',club:ovlNm('MLB',0),y:G.year-2,y1:G.year-1,lines:[],back:false,pj:ovsPj(p)};G.abroad=Array.from({length:121},(_,i)=>({...seed,id:900001+i}));const ids=G.abroad.map(a=>a.id),r=__rngState();ovsTrim();ok(G.abroad.length===121&&ids.every(id=>G.abroad.some(a=>a.id===id)),'국내 현역 해외 선수 삭제 '+G.abroad.length);ok(__rngState()===r,'기록 정리 난수 소비');});
T('[검수 11-18 #599 진행] 실제 해외 시즌 마감에서도 예고한 NPB 국내 복귀가 열린다 [해외세계검수]',()=>{const p=wd592_setup();p.foreign=null;p.age=29;setOvr(p,68);const proto={id:p.id,name:p.name,isP:false,foreign:null,from:G.user,lg:'NPB',club:ovlNm('NPB',0),ci:0,how:'포스팅',yrs:2,amt:200,y:G.year-2,y1:G.year-1,age:p.age,lines:[wd592_bat(G.year-1,'NPB',400,100)],pj:ovsPj(p)};G.day=KD(11,1);G.ovp={v:1,L:[],y:G.year};for(let sd=1;sd<=12;sd++){const a=JSON.parse(JSON.stringify(proto));a.bn={y:G.year,v:1};a.cur={...wd592_bat(G.year,'NPB',400,100),o:Math.round(ovr(p)*10)/10};G.abroad=[a];delete G.players[p.id];withRng(sd,()=>abroadYear());const q=G.players[p.id];ok(a.back&&a.lg==='NPB'&&q?.retFrom===G.user&&q.retAsk?.post===1,'예고 뒤 다른 해외 계약으로 이동 '+sd+' '+a.lg);}});
T('[검수 11-18 #597 호환] 원래 시즌 사본 없는 옛 시장 후보도 공개된 누적을 그대로 복원한다 [해외세계검수]',()=>{const p=wd592_setup();p.team=null;p.hist=[];p.prevLvl='트리플A';p.prev=wd592_bat(G.year-1,'트리플A');p.ovpY=G.year-1;p.now=wd592_bat(G.year,'트리플A',300,75);delete p.ovpCur;G.ovp={v:1,L:[]};const r=__rngState();ok(ovpBack(p),'옛 후보 복귀 거절');const e=G.ovp.L[0],row=ovpTopRows(G.year).find(x=>x.id===p.id);ok(row?.h.pa===300&&row.h.g===75,'공개된 누적을 다시 비례 축소 '+JSON.stringify(row?.h));ok(__rngState()===r,'옛 후보 복귀가 난수를 소비');delete G.players[p.id];const q=ovpP(e);ok(q.now.pa===300&&q.now.g===75,'재출현 때 누적 변경');});

const wr592_line=(y,lvl='MLB',pa=500)=>({y,lvl,c:0,g:125,pa,ab:Math.round(pa*.9),h:Math.round(pa*.35),d:25,tr:1,hr:35,bb:Math.round(pa*.08),hbp:2,sf:0});
T('[검수 11-18 #592 순서] 옛 중복 배열 순서와 무관하게 최신 현역 해외 상태를 보존한다 [해외세계보강]',()=>{fresh();const p=domestic(G.user).find(q=>!q.isP),id=p.id;delete G.players[id];const old={id,name:p.name,foreign:'용병',isP:false,lg:'MLB',from:G.user,d:G.day-700,y:G.year-3,y1:G.year-2,back:true,backY:G.year-1,lines:[wr592_line(G.year-2)]},now={...old,lg:'NPB',club:ovlNm('NPB',0),d:G.day-1,y:G.year,y1:G.year+1,back:false,backY:undefined,lines:[],fr:ovsSlim(p),cur:{...wr592_line(G.year,'NPB'),o:ovr(p)}};G.abroad=[old,now];const r=__rngState();ovsTrackMigrate();const a=G.abroad[0];ok(G.abroad.length===1&&!a.back&&a.lg==='NPB'&&a.fr&&a.cur,'과거 복귀 기록이 현역 상태를 덮음');ok(__rngState()===r,'중복 기록 선택 난수 소비');});
T('[검수 11-18 #597 누적] 시장에서 한 주 더 쌓은 공개 성적도 후보군 복귀 때 보존한다 [해외세계보강]',()=>{fresh();G.day=KD(7,15);const p=newForeign('용병',{market:true,isP:false});p.age=29;p.team=null;p.hist=[];p.prevLvl='트리플A';p.prev=wr592_line(G.year-1,'트리플A');const e=ovpE(p,[ovpLineE(p.prev,G.year-1)]);e.cur=ovpLineE(wr592_line(G.year,'트리플A',600),G.year);G.ovp={v:1,L:[e]};delete G.players[p.id];const q=ovpP(e);G.fmarket=[q.id];G.fwatch=[];G.day+=7;const rng=FO_RNG;FO_RNG=()=>.99;try{fwatchWeek();}finally{FO_RNG=rng;}ok(G.players[q.id]===q,'후보 유지 준비');const now=JSON.parse(JSON.stringify(q.now)),r=__rngState();ok(ovpBack(q),'후보군 복귀 준비');delete G.players[q.id];const row=ovpTopRows(G.year).find(x=>x.id===q.id);ok(row&&row.h.pa===now.pa&&row.h.h===now.h&&row.h.hr===now.hr&&row.h.g===now.g,'추가 공개된 누적이 복귀 때 바뀜 '+JSON.stringify([row?.h,now]));ok(__rngState()===r,'현재 기록 이동 난수 소비');});
T('[검수 11-18 #592 수상] 중복 시즌은 큰 기록을 남기면서 과거 수상 정보도 합친다 [해외세계보강]',()=>{fresh();const p=domestic(G.user).find(q=>!q.isP),id=p.id;delete G.players[id];const old={id,name:p.name,foreign:'용병',isP:false,lg:'MLB',from:G.user,d:G.day-700,y:G.year-3,y1:G.year-2,back:true,lines:[{...wr592_line(G.year-1,'MLB',300),aw:['AS'],x:{...wr592_line(G.year-1,'트리플A',100),aw:['GG']}}]},now={...old,d:G.day-1,back:false,fr:ovsSlim(p),lines:[{...wr592_line(G.year-1,'MLB',400),x:wr592_line(G.year-1,'트리플A',120)}]};G.abroad=[now,old];ovsTrackMigrate();const L=G.abroad[0].lines;ok(L.length===1&&L[0].pa===400&&L[0].aw?.includes('AS')&&L[0].x.aw?.includes('GG'),'큰 중복 기록 선택에서 수상 정보 소실 '+JSON.stringify(L));});

T('[검수 11-18 #603] NPB 동률 순위표의 상위 세 팀과 실제 가을야구 진출팀은 같다 [해외순위검수]',()=>{fresh();const lg='NPB',L=G.ovl[lg],w=OVL_C[lg].map(c=>71+c[2]);const H=withRng(603,()=>ovlPlay(lg,L,G.year,w));L.h=[H];delete L.cur;const T0=ovlTable(lg,G.year);for(let d=0;d<2;d++){const shown=T0.div[d].L.slice(0,3).map(r=>r.i).sort((a,b)=>a-b),actual=H.po.filter(i=>OVL_C[lg][i][2]===d).sort((a,b)=>a-b);ok(JSON.stringify(shown)===JSON.stringify(actual),'순위표와 진출팀 불일치 '+JSON.stringify({shown,actual}));}ok(H.po.includes(H.ch)&&H.po.includes(H.ru),'결승팀 진출 누락');});
T('[검수 11-18 #603 호환] 옛 완료 시즌 동률은 확정 진출팀을 보존하고 순위 조회는 저장·난수를 바꾸지 않는다 [해외순위검수]',()=>{fresh();const y=G.year,L=G.ovl.NPB;delete L.cur;L.h=[{y,w:OVL_C.NPB.map(c=>71+c[2]),po:[5,3,4,11,9,10],ch:5,ru:11,pn:[5,11],sr:'4-3'}];const saved=JSON.stringify(G),rng=__rngState();for(let n=0;n<2;n++){const V=ovlTable('NPB',y);for(let d=0;d<2;d++)ok(V.div[d].L.slice(0,3).every(r=>L.h[0].po.includes(r.i)),'옛 진출팀이 동률 상위에서 빠짐');}ok(JSON.stringify(G)===saved&&__rngState()===rng,'순위 조회 부작용');});
T('[검수 11-18 #604] 진행중 해외 순위는 매일 리그 전체 승패가 같고 각 구단 기록은 줄지 않는다 [해외순위검수]',()=>{fresh();const prev={};for(let d=KD(3,27);d<=KD(9,28);d++){G.day=d;for(const lg of OVL_LGS){const V=ovlTable(lg,G.year),R=V.div.flatMap(x=>x.L);ok(sum(R.map(r=>r.w))===sum(R.map(r=>r.l)),lg+' 리그 승패 불균형 '+d+' '+sum(R.map(r=>r.w))+'/'+sum(R.map(r=>r.l)));for(const r of R){ok(r.w>=0&&r.l>=0&&r.w+r.l===V.gp,'팀 경기 수 범위');const p=prev[lg+':'+r.i];if(p)ok(r.w>=p.w&&r.l>=p.l,'날짜 진행에 승패 감소 '+lg+' '+r.i);prev[lg+':'+r.i]={w:r.w,l:r.l};}if(d===KD(9,28))for(const r of R)ok(r.w===G.ovl[lg].cur.w[r.i],'최종 확정 승수가 다름');}}const saved=JSON.stringify(G),rng=__rngState();for(const lg of OVL_LGS)ovlTable(lg,G.year);ok(JSON.stringify(G)===saved&&__rngState()===rng,'비례 순위 조회가 저장·난수를 바꿈');});
T('[검수 11-18 #605] 우승 반지 기사는 해당 리그에서 실제 출전한 선수만 포함한다 [해외순위검수]',()=>{fresh();const y=G.year;G.ovl.wy=y;delete G.ovl.wd;G.ovl.MLB.h=[{y,w:OVL_C.MLB.map(()=>81),po:[0,1],ch:0,ru:1,pn:[0,1],sr:'4-3'}];G.wire=[];G.abroad=[{id:60501,name:'미출전선수',foreign:'용병',lg:'MLB',lines:[{y,lvl:'MLB',c:0,g:0,pa:0}]},{id:60502,name:'출전선수',foreign:'용병',lg:'MLB',lines:[{y,lvl:'MLB',c:0,g:10,pa:40,ab:35,h:8}]},{id:60503,name:'무아웃투수',isP:true,lg:'MLB',lines:[{y,lvl:'MLB',c:0,g:0,outs:0,bf:1}]}];ovlChampWire();const text=G.wire.map(w=>w.t).join(' ');ok(text.includes('출전선수')&&text.includes('우승 반지'),'출전 선수 우승 기사 누락');ok(!text.includes('미출전선수'),'0경기 선수를 우승 반지에 포함');ok(text.includes('무아웃투수'),'실제 타자를 상대한 무아웃 투수 누락');});
T('[검수 11-18 #606] 지난 시즌 주목 선수는 현재 KBO 복귀·은퇴 여부와 무관하게 당시 성적과 소속을 보인다 [해외순위검수]',()=>{fresh();const y=G.year-1,p=playersOf(G.user).find(q=>!q.isP),q=playersOf(G.user).find(q=>!q.isP&&q!==p);G.day=KD(4,1);const line={y,lvl:'MLB',c:1,g:125,pa:500,ab:450,h:150,d:25,tr:2,hr:25,bb:45,hbp:5,sf:0};G.abroad=[{id:p.id,name:p.name,lg:'MLB',club:ovlNm('MLB',7),ci:7,from:G.user,isP:false,back:true,backY:G.year,lines:[{...line}]},{id:q.id,name:q.name,lg:'MLB',from:G.user,isP:false,end:G.year,lines:[{...line,c:2}]}];const P=ovlTopPool();for(const id of [p.id,q.id])ok(P.R.some(r=>r.abr&&r.id===id),'복귀 또는 은퇴로 지난 시즌 목록에서 삭제 '+id);const r=P.R.find(r=>r.id===p.id);ok(r.club===ovlNm('MLB',1)&&r.h.y===y,'현재 소속으로 과거 구단/연도 덮음');ok((ovlAlumMap('MLB',y)[1]||[]).some(a=>a.id===p.id),'구단의 과거 선수 목록 누락');G.day=KD(7,1);ok(!ovlTopPool().R.some(r=>r.id===p.id||r.id===q.id),'현재 시즌에 없는 성적 생성');});
T('[검수 11-18 #613] NPB 2군 시즌 요약에는 다른 수준의 1군 순위와 진출 여부를 붙이지 않는다 [해외순위검수]',()=>{fresh();G.day=KD(7,1);const y=G.year;G.abroad=[{id:61301,name:'일본퓨처스',lg:'NPB',from:G.user,isP:false,lines:[{y,lvl:'NPB 2군',c:0,g:60,pa:240,ab:220,h:65,hr:8}]}];const S=ovsSeasonSum(),r=S.R.find(x=>x.a.id===61301);ok(r&&!r.tr,'2군 기록에 센트럴 1군 성적 연결 '+JSON.stringify(r&&r.tr));ok(ovlTeamRec('NPB 2군',0,y)===null,'공통 팀 성적도 2군을 1군으로 읽음');ok(ovlTeamRec('NPB',0,y)&&ovlTeamRec('트리플A',0,y),'실제 지원 리그 성적까지 숨김');ok(!(ovlAlumMap('NPB',y)[0]||[]).some(a=>a.id===61301),'1군 표에 2군 기록을 출전 선수로 표시');});

const ot603LegacyOrd=(I,w)=>[...I].sort((a,b)=>w[b]-w[a]||hn('ovo',a*31+b)-hn('ovo',b*31+a));
function ot603Legacy(lg,L,y,w){ const P=ovlP(lg,L), C=OVL_C[lg]; const H={y,w:w.slice()}; const I=C.map((c,i)=>i), inD=d=>I.filter(i=>C[i][2]===d); let a,b,po;
  if(lg==='MLB'){ const lgSeeds=[0,1].map(k=>{ const divs=[0,1,2].map(d=>ot603LegacyOrd(inD(k*3+d),w)[0]); const top=ot603LegacyOrd(divs,w); const rest=ot603LegacyOrd(I.filter(i=>Math.floor(C[i][2]/3)===k&&!divs.includes(i)),w).slice(0,3); return top.concat(rest); });
    const champ=S=>{ const w1=ovlSeries(P,S[3],S[4],2).w, w2=ovlSeries(P,S[2],S[5],2).w; const d1=ovlSeries(P,S[0],w1,3).w, d2=ovlSeries(P,S[1],w2,3).w; return ovlSeries(P,d1,d2,4).w; };
    a=champ(lgSeeds[0]); b=champ(lgSeeds[1]); po=lgSeeds[0].concat(lgSeeds[1]); }
  else if(lg==='AAA'){ /* 리그(IL·PCL)마다 두 지구 1위가 3전 2승 → 두 리그 우승팀이 단판 */ const S=[0,1,2,3].map(d=>ot603LegacyOrd(inD(d),w)[0]); a=ovlSeries(P,S[0],S[1],2).w; b=ovlSeries(P,S[2],S[3],2).w; po=S; }
  else if(lg==='CPBL'){ /* 한 리그: 2·3위 5전 3승 → 1위와 타이완시리즈 */ const S=ot603LegacyOrd(I,w).slice(0,3); a=S[0]; b=ovlSeries(P,S[1],S[2],3).w; po=S; }
  else if(lg==='LMB'){ /* 지구마다 4위까지 7전 4승 두 판 → 세리에 델 레이 */ const Z=[0,1].map(d=>ot603LegacyOrd(inD(d),w).slice(0,4)); const zc=S=>ovlSeries(P,ovlSeries(P,S[0],S[3],4).w,ovlSeries(P,S[1],S[2],4).w,4).w; a=zc(Z[0]); b=zc(Z[1]); po=Z[0].concat(Z[1]); }
  else { const lgSeeds=[0,1].map(k=>ot603LegacyOrd(inD(k),w).slice(0,3)); const champ=S=>{ const w1=ovlSeries(P,S[1],S[2],2).w; return ovlSeries(P,S[0],w1,4,1).w; };
    a=champ(lgSeeds[0]); b=champ(lgSeeds[1]); po=lgSeeds[0].concat(lgSeeds[1]); }
  const f=ovlSeries(P,a,b,OVL_FN[lg]); H.po=po; H.ch=f.w; H.ru=f.l; H.sr=f.s; H.pn=[a,b];
  return H; }

T('[검수 11-18 #603 난수] 새 동률 대진도 기존 주 난수를 보존하고 같은 대진의 결과는 그대로다 [해외순위검수]',()=>{fresh();for(const lg of OVL_LGS){const L=G.ovl[lg],g=OVL_G[lg];for(const tied of [true,false]){const w=OVL_C[lg].map((_,i)=>tied?Math.floor(g/2):g-i);for(const seed of [60301,60317,60353]){__seed(seed);const B=ot603Legacy(lg,L,G.year,w),state=__rngState();__seed(seed);const A=ovlPlay(lg,L,G.year,w);ok(__rngState()===state,'주 난수 순서 변경 '+lg+' '+tied+' '+seed);const bn=withRng(seed,()=>{ot603Legacy(lg,L,G.year,w);return R();}),an=withRng(seed,()=>{ovlPlay(lg,L,G.year,w);return R();});ok(an===bn,'바깥 고정 난수 순서 변경 '+lg+' '+tied+' '+seed);if(JSON.stringify(B.po)===JSON.stringify(ovlSeeds(lg,w).flat())){const {tie,...rest}=A;ok(JSON.stringify(rest)===JSON.stringify(B),'대진이 같은데 결과 변경 '+lg);}else{__seed(seed+1);const C=ovlPlay(lg,L,G.year,w);ok(JSON.stringify(A)===JSON.stringify(C),'별도 동률 대진 난수가 호출 순서에 영향');}}}}});

function of593_bat(y,h=180){return {y,lvl:'MLB',c:0,g:125,pa:500,ab:450,h,d:30,tr:0,hr:45,bb:45,hbp:5,sf:0,so:90,sb:4,cs:1};}
function of593_player(){return domestic(G.user).find(p=>!p.isP&&!p.foreign);}
T('[검수 11-18 #593] 해외 외국인 시즌 마감은 실제 출장 경기 수를 보존한다 [해외소식검수]',()=>{fresh();const p=JSON.parse(JSON.stringify(of593_player()));p.age=25;const a={id:p.id,name:p.name,foreign:'용병',isP:false,lg:'MLB',ci:0,club:'뉴욕',y:G.year-1,y1:G.year,yrs:3,fr:p,lines:[],cur:{...of593_bat(G.year),o:ovr(p)}};G.abroad=[a];const f=ovsMoveFr,r=FO_RNG;ovsMoveFr=()=>null;FO_RNG=()=>.99;try{ovsForeignYear(a,[]);}finally{ovsMoveFr=f;FO_RNG=r;}ok(a.lines.length===1&&a.lines[0].g===125,'500타석 125경기가 마감 뒤 '+a.lines[0]?.g+'경기');delete a.lines[0].g;const fields=JSON.stringify(a.lines[0]),rng=__rngState();ovsMigrate();ok(a.lines[0].g>0,'옛 저장의 빠진 경기 수 미복원');const repaired={...a.lines[0]};delete repaired.g;ok(JSON.stringify(repaired)===fields,'경기 수 복원이 다른 기존 기록을 변경');const before=JSON.stringify(G.abroad);ovsMigrate();ok(JSON.stringify(G.abroad)===before&&__rngState()===rng,'경기 수 복원은 멱등·주 난수 불변');});
T('[검수 11-18 #607] 시즌 100%에도 확정 올스타 표시를 유지하고 조회는 원본을 보존한다 [해외소식검수]',()=>{fresh();const a={id:9607,name:'올스타검증',isP:false,lg:'MLB',lines:[],asY:G.year,cur:of593_bat(G.year)};const before=JSON.stringify(a),rng=__rngState();ok(ovsCurPart(a,.999).aw.includes('AS'),'99.9% 올스타 준비');const q=ovsCurPart(a,1);ok(q.aw&&q.aw.includes('AS'),'100%에서 올스타 표시 소실');ok(JSON.stringify(a)===before&&__rngState()===rng,'시즌 끝 조회가 원본·주 난수 변경');});
T('[검수 11-18 #608] 같은 ID 해외 주간 계획은 저장과 재활 상태를 구분한다 [해외소식검수]',()=>{fresh();const p=of593_player(),y=G.year,L=of593_bat(y),a={id:9608,name:'캐시검증',isP:false,lg:'MLB',lines:[{y:y-1,lvl:'MLB',pa:10}],pj:JSON.stringify({...p,injOut:0})},A=ovfPlan(a,L),old=G;let B;try{G=JSON.parse(JSON.stringify(old));const b={...a,pj:JSON.stringify({...p,injOut:185})};B=ovfPlan(b,L);ok(B!==A&&B.w.slice(0,13).every(x=>x===0),'다른 저장의 건강한 계획이 185일 재활 계획으로 재사용');b.pj=JSON.stringify({...p,injOut:0});const C=ovfPlan(b,L);ok(C.w.slice(0,13).some(x=>x>0),'같은 저장의 재활 변경도 캐시 갱신 안 됨');}finally{G=old;}});
T('[검수 11-18 #609] 모든 진행 시점의 홈런은 안타보다 많지 않고 단조 증가한다 [해외소식검수]',()=>{fresh();const y=G.year;for(let id=1;id<=30;id++){const L={...of593_bat(y),pa:10,ab:8,h:4,d:1,tr:1,hr:2,bb:2,hbp:0,sf:0},a={id,name:'누적검증',isP:false,lg:'MLB',lines:[],cur:L};let prev=-1,last={};for(let t=0;t<=OVF.nw;t+=.5){const q=ovfCum(a,L,t);ok((q.hr||0)<=(q.h||0),'안타보다 홈런이 많음 id='+id+' t='+t+' '+q.h+'H '+q.hr+'HR');ok((q.hr||0)+(q.d||0)+(q.tr||0)<=(q.h||0),'장타 합이 안타보다 많음');for(const k of ['pa','ab','h','d','tr','hr']){ok((q[k]||0)>=(last[k]||0),'누적 감소 '+k);last[k]=q[k]||0;}ok(q.h<=q.ab&&q.ab<=q.pa,'안타·타수·타석 포함 관계');prev=q.hr||0;}ok(prev===L.hr,'마지막 누적은 시즌 홈런과 일치');}});
T('[검수 11-18 #610] 같은 리그 같은 해의 MVP와 신인왕은 한 명이고 소식도 같은 수상자를 가리킨다 [해외소식검수]',()=>{fresh();const p=of593_player();p.r.def=80;const A={id:9610,name:'먼저마감',lg:'MLB',ci:0,isP:false,lines:[]},B={id:9611,name:'나중마감',lg:'MLB',ci:0,isP:false,lines:[]},N=[],a=of593_bat(G.year,180),b=of593_bat(G.year,200);G.abroad=[A,B];const r=FO_RNG;let n=0;FO_RNG=()=>{n++;return 0;};try{ovsFinish(A,a,p,N);A.lines.push(a);ovsFinish(B,b,p,N);B.lines.push(b);}finally{FO_RNG=r;}ok([a,b].filter(l=>l.aw?.includes('MVP')).length===1,'한 시즌 MVP 중복 '+JSON.stringify([a.aw,b.aw]));ok([a,b].filter(l=>l.aw?.includes('ROY')).length===1,'한 시즌 신인왕 중복');ok(N.filter(x=>x.t.includes('MVP')).length===1,'기사의 MVP 수상자 중복');ok(n===10,'기존 정상 시상 난수 호출 수가 달라짐 '+n);const before=JSON.stringify(G.abroad),rng=__rngState();ovsMigrate();ovsMigrate();ok(JSON.stringify(G.abroad)===before&&__rngState()===rng,'시상 정리는 멱등·주 난수 불변');});
T('[검수 11-18 #611] 전년도 보조 MLB 기록이 신인 자격에 반영되고 기존 난수 호출은 유지된다 [해외소식검수]',()=>{fresh();const p=of593_player();p.r.def=80;const a={id:9612,name:'보조기록검증',lg:'MLB',ci:0,isP:false,lines:[{y:G.year-1,lvl:'트리플A',pa:350,ab:320,h:100,x:{lvl:'MLB',pa:320,ab:290,h:90}}]},L=of593_bat(G.year),N=[],r=FO_RNG;let n=0;FO_RNG=()=>{n++;return 0;};try{ovsFinish(a,L,p,N);}finally{FO_RNG=r;}ok(!L.aw?.includes('ROY'),'작년 MLB 320타석을 뛰고도 신인왕');ok(n===5,'예전 자격 판정의 난수 호출 위치 변경 '+n);});
T('[검수 11-18 #609 보조 수준] 단순 비례와 주간 가중 누적 모두 장타 포함 관계와 마지막 합계를 지킨다 [해외소식검수]',()=>{fresh();const y=G.year,L={...of593_bat(y),pa:10,ab:8,h:4,d:1,tr:1,hr:2,bb:2,hbp:0,sf:0,x:{lvl:'트리플A',c:0,g:3,pa:12,ab:10,h:6,d:2,tr:1,hr:3,bb:2,hbp:0,sf:0}},a={id:9619,name:'두수준누적',isP:false,lg:'MLB',lines:[],cur:L};for(const method of [f=>ovsPart(L,f),f=>ovfCum(a,L,f*OVF.nw)]){const prev={};for(let i=0;i<=200;i++){const q=method(i/200);for(const z of ovsParts(q)){ok((z.d||0)+(z.tr||0)+(z.hr||0)<=(z.h||0),'장타가 안타 밖으로 나옴 '+z.lvl);ok(z.h<=z.ab&&z.ab<=z.pa,'안타 타수 타석 포함 관계');for(const k of ['pa','ab','h','d','tr','hr']){const key=z.lvl+':'+k;ok((z[k]||0)>=(prev[key]||0),'보조 수준 누적 감소 '+key);prev[key]=z[k]||0;}}}const q=method(1);for(const z of ovsParts(L))for(const k of ['pa','ab','h','d','tr','hr'])ok(prev[z.lvl+':'+k]===z[k],'마지막 합계 불일치 '+z.lvl+':'+k);}});
T('[검수 11-18 #610 순서·복원] 마감 순서와 저장 재로드가 달라도 단일 수상자는 같고 옛 중복 기록을 정리한다 [해외소식검수]',()=>{fresh();const base=JSON.stringify(G);for(const order of [[0,1],[1,0]]){G=JSON.parse(base);const p=of593_player();p.r.def=80;const rows=[{a:{id:9620,name:'보통수상',lg:'MLB',ci:0,isP:false,lines:[]},L:of593_bat(G.year,180)},{a:{id:9621,name:'최고수상',lg:'MLB',ci:0,isP:false,lines:[]},L:of593_bat(G.year,200)}],N=[];G.abroad=rows.map(r=>r.a);const rng=FO_RNG;FO_RNG=()=>0;try{for(const i of order){const r=rows[i];ovsFinish(r.a,r.L,p,N);r.a.lines.push(r.L);}}finally{FO_RNG=rng;}ok(rows[1].L.aw.includes('MVP')&&!rows[0].L.aw.includes('MVP'),'마감 순서에 따라 MVP 바뀜 '+order);ok(N.filter(x=>x.t.includes('MVP')).length===1,'마감 순서별 기사 수상자 중복');for(const r of rows){delete r.L.aw0;r.L.aw=['MVP'];}const state=__rngState();ovsMigrate();ok(rows[1].L.aw.includes('MVP')&&!rows[0].L.aw,'옛 중복 MVP 정리 실패');const after=JSON.stringify(G.abroad);G=JSON.parse(JSON.stringify(G));ovsMigrate();ok(JSON.stringify(G.abroad)===after&&__rngState()===state,'수상 복원이 멱등 또는 주 난수 불변 아님');}});
T('[검수 11-18 #610 보조 수준 복원] 대표 마이너 줄의 MLB 수상도 같은 해 단일 수상자로 정리한다 [해외소식검수]',()=>{fresh();const y=G.year,L={y,lvl:'트리플A',c:0,g:146,pa:600,ab:540,h:200,d:30,tr:0,hr:45,bb:55,hbp:5,sf:0,x:{lvl:'MLB',c:0,g:78,pa:320,ab:280,h:90,d:20,tr:0,hr:20,bb:35,hbp:5,sf:0,aw:['MVP']}},B={y,lvl:'MLB',c:0,g:146,pa:600,ab:540,h:240,d:40,tr:0,hr:50,bb:55,hbp:5,sf:0,aw:['MVP']};G.abroad=[{id:9622,name:'혼합수상',isP:false,lg:'MLB',lines:[L]},{id:9623,name:'빅리그수상',isP:false,lg:'MLB',lines:[B]}];const rng=__rngState();ovsAwardsMigrate();ok(G.abroad.flatMap(a=>a.lines.flatMap(ovsParts)).filter(q=>q.lvl==='MLB'&&q.aw?.includes('MVP')).length===1,'보조 MLB MVP가 중복 정리에서 누락');ok(L.x.y==null,'보조 기록에 연도를 임의 생성');const after=JSON.stringify(G.abroad);ovsAwardsMigrate();ok(JSON.stringify(G.abroad)===after&&__rngState()===rng,'보조 수상 복원이 멱등·주 난수 불변 아님');});

T('[검수 11-18 #603] 모든 리그 동률 순서는 부분집합에 무관하고 옛 진출팀과도 일치한다 [해외우선교차검토]',()=>{fresh();for(const lg of OVL_LGS){const C=OVL_C[lg],I=C.map((_,i)=>i),w=I.map(()=>Math.floor(OVL_G[lg]/2)),ord=ovlOrd(I,w);for(let k=0;k<7;k++){const sub=I.filter(i=>(i+k)%3!==0);ok(JSON.stringify(ovlOrd(sub,w))===JSON.stringify(ord.filter(i=>sub.includes(i))),lg+' 부분집합 동률 순서 불일치');}const L=G.ovl[lg],H=withRng(60301+I.length,()=>ovlPlay(lg,L,G.year,w));L.h=[H];delete L.cur;for(const legacy of [false,true]){if(legacy)delete H.tie;const j=JSON.stringify(G),r=__rngState(),V=ovlTable(lg,G.year),quota=lg==='NPB'||lg==='CPBL'?3:lg==='LMB'?4:1;for(const D of V.div){const shown=D.L.slice(0,quota).map(x=>x.i);ok(shown.every(i=>H.po.includes(i)),lg+' 진출팀과 순위 불일치 '+JSON.stringify({legacy,shown,po:H.po}));}ok(JSON.stringify(G)===j&&__rngState()===r,'완료 순위 조회 부작용 '+lg);}}});
T('[검수 11-18 #602] 복귀 뒤 국내 대표 기록은 해외 사본 재복원으로 줄거나 중복되지 않는다 [해외우선교차검토]',()=>{fresh();G.year=2030;G.cal=buildCalendar(G.year);G.day=KD(2,24);const p=domestic(G.user).find(q=>!q.isP),q=JSON.parse(JSON.stringify(p));q.age=31;q.ntcr={ev:['2027 프리미어12 우승'],b:{g:2,pa:8,ab:7,h:3,hr:1}};delete G.players[p.id];const a={id:q.id,name:q.name,isP:false,pos:posLabel(q),foreign:null,from:G.user,lg:'MLB',club:MLBT[0],how:'포스팅',yrs:1,amt:300,y:2029,y1:2030,age:31,lines:[],back:false,pj:ovsPj(q),d:dnum(2029,11,1),ci:ovlIdx('MLB',MLBT[0])};G.abroad=[a];const T={k:'wbc',y:2030,res:'4강',done:true,st:{}};T.st['o'+a.id]={P:0,g:4,pa:16,ab:14,h:5,hr:2,bb:2};ntCareerAdd(T);G.day=KD(11,1);const f=ovsBackRoll;ovsBackRoll=()=>true;try{abroadYear();}finally{ovsBackRoll=f;}const b=G.players[a.id];ok(b.ntcr.b.g===6&&b.ntcr.b.hr===3,'출국 전+해외 통산 미보존');const D={k:'p12',y:2031,res:'준우승',done:true,st:{[b.id]:{P:0,g:3,pa:12,ab:10,h:4,hr:1}}};ntCareerAdd(D);G.nt={k:'wbc',y:2030,ids:[],ovs:[],tour:T};const rng=__rngState();ntAbroadCareerRestore(a,b);ntSaveFix();G=JSON.parse(JSON.stringify(G));ntSaveFix();const c=G.players[b.id].ntcr;ok(c.b.g===9&&c.b.hr===4&&c.ev.length===3,'복귀 뒤 국내 기록 손실/중복 '+JSON.stringify(c));ok(__rngState()===rng,'통산 복원 주 난수 소비');});
T('[검수 11-18 #591] 실제 상한 거절과 저장 재조회는 보류권 계약 결정 기록을 바꾸지 않는다 [해외우선교차검토]',()=>{for(const auto of [false,true]){fresh();G.day=KD(11,28);G.rolled=G.year;G.evs=[];G.mail=[];G.stops=[];const U=G.user,src=domestic(U).find(p=>!p.foreign&&!p.prospect&&!p.ys);src.age=28;src.svc=8;src.faN=0;src.faC=false;src.ext=false;delete src.mil;delete src.freeSince;delete src.retMin;src.draft={y:G.year-8,tid:U,rd:1};src.team=null;src.retFrom=U;src.retAsk={sal:capOf(sponSeason())*4,yrs:3,lg:'MLB',n:3,post:1,exp:G.day+14};ovsBackAsk(src);const pid=src.id;G=JSON.parse(JSON.stringify(G));const p=G.players[pid],e=G.evs.find(x=>x.k==='ovsback'&&x.data.pid===pid),m=G.mail.find(x=>x.id===e.mid),cc=ovsCapCheck(p);ok(cc&&cc.hard&&!cc.ok,'실제 상한 거절 준비');const before=JSON.stringify(G),rng=__rngState();const r=evPick(e.id,0,auto);ok(r.includes('승인')||r.includes('결재'),'거절 사유 없음');ok(JSON.stringify(G)===before&&__rngState()===rng,'거절이 선수·기록·메일·난수를 바꿈');ok(!e.done&&p.retFrom===U&&p.retAsk&&!isFree(p)&&m.acts.length===2,'거절 후 권리/미결 결정 소실');for(const q of domestic(U)){q.sal=MIN_SAL;delete q.newSal;delete q.extNext;delete q.capB;}p.retAsk.sal=MIN_SAL;const c2=ovsCapCheck(p);ok(!c2||c2.ok,'실제 조건 보완 승인 준비');evPick(e.id,0,auto);ok(e.done&&p.team===U&&!p.retAsk&&!p.retFrom&&p.yrs===3&&p.ext,'보완 후 원소속 비FA 복귀 계약 실패');}});
function rt614Player(isP=false,war=5){fresh();G.fd=null;const p=domestic(G.user).find(p=>p.isP===isP&&!p.prospect);p.hist=[];p.svc=0;p.aw=[];p.fr=null;p.age=38;p.pw={};const h={y:G.year-1,lvl:'1군',t:G.user,pos:p.pos,g:100,...(isP?{outs:300,er:30}:{pa:400,ab:350,h:100,bb:50})};p.hist.push(h);if(!isP)p.pw[warKey(h)]=war;return {p,h};}
T('[검수 11-18 #614] 예전 우리 구단 공헌을 이직한 구단 결번 후보에 재사용하지 않는다 [은퇴공헌검수]',()=>{const {p}=rt614Player(false),old=G.user;G.cfg=G.cfg||{};G.cfg.retWar=60;p.hist=[];for(let i=1;i<=8;i++){const h={y:G.year-i,lvl:'1군',t:old,pos:p.pos,g:120,pa:450,ab:400,h:120,bb:50};p.hist.push(h);p.pw[warKey(h)]=6.5;}p.no=56;p.noT=old;p.svc=8;const id=p.id;retireOut(p,'은퇴');const r=G.legends.find(r=>r.pid===id);ok(r&&!r.canRetNo,'처음 높은 기준 준비');const next=G.teams.find(t=>t.id!==old).id;switchTeam(next);G.cfg.retWar=40;ok(!retNoCands().some(x=>x.r===r),'광주8시즌WAR52가 서울 결번 후보가 됨');ok(retireNumber('p'+id)==='대상이 아닙니다.','이직 구단에서 잘못된 결번 실행');switchTeam(old);ok(retNoCands().some(x=>x.r===r),'원래 기여 구단 복귀 후 후보 누락');});
T('[검수 11-18 #622] WAR 37.96 은퇴 선수는 표시 반올림 38.0으로 헌액하지 않는다 [은퇴공헌검수]',()=>{const {p}=rt614Player(false,37.96);ok(!hofWatch().find(x=>x.p.id===p.id)?.met,'현역 기준 준비 실패');const r=retireRecord(p);ok(r.war===38,'소수 첫째 자리 표시 준비');ok(!r.hof,'반올림 WAR로 명예의 전당 기준 통과');});
T('[검수 11-18 #623] 한국시리즈와 올스타 MVP는 정규 MVP 헌액 횟수에서 제외한다 [은퇴공헌검수]',()=>{const {p}=rt614Player(false,5.4);p.aw=[(G.year-2)+' 한국시리즈 MVP',(G.year-1)+' 올스타 MVP'];const r=retireRecord(p);ok(r.mvp===0&&!r.hof,'비정규 MVP 2회로 헌액 '+JSON.stringify({mvp:r.mvp,hof:r.hof}));});
T('[검수 11-18 #624] 명예의 전당의 pid id 형식이 섞여도 같은 선수는 한 명이다 [은퇴공헌검수]',()=>{fresh();G.legends=[];G.hof=[{pid:614624,name:'한선수',y:2020,hof:true,war:40},{id:614624,name:'한선수',y:2020,hof:true,war:40}];ok(hofList().length===1,'pid id 중복 헌액 표시 '+hofList().length);});
T('[검수 11-18 #625] 출장 타석 아웃 없는 빈 일군 줄은 통산 시즌과 순위 대상이 아니다 [은퇴공헌검수]',()=>{const {p,h}=rt614Player(false);p.hist=[{y:G.year,lvl:'1군',t:G.user,g:0,pa:0}];ok(careerOf(p).seasons.size===0,'빈 줄이 통산 시즌으로 집계');ok(!careerBoard().some(x=>x.id===p.id),'빈 줄 선수가 통산 순위에 등장');});
T('[검수 11-18 #626] 방출 뒤 해외 추적이 없어도 실제 은퇴 기록 없이 은퇴로 표시하지 않는다 [은퇴공헌검수]',()=>{fresh();const p=Object.values(G.players).find(p=>p.foreign&&!p.isP&&p.team!=null);p.hist=[{y:G.year,lvl:'1군',t:p.team,g:8,pa:30,ab:27,h:5,bb:3}];story(p,'외국인 교체로 방출','move');archPlayer(p);delete G.players[p.id];G.abroad=[];const r=careerBoard().find(r=>r.id===p.id);ok(r&&!r.lab.includes('은퇴'),'방출 보관 선수를 은퇴로 단정 '+r?.lab);});
T('[검수 11-18 #627] 마이너가 대표 줄인 혼합 시즌도 MLB 보조 줄의 결번 공헌을 센다 [은퇴공헌검수]',()=>{const {p}=rt614Player(false);const major={y:G.year,lvl:'MLB',pa:350,ab:300,h:120,hr:25,bb:45,sf:5,d:20,tr:2,pos:p.pos};G.abroad=[{id:p.id,from:G.user,lg:'MLB',foreign:null,lines:[{y:G.year,lvl:'트리플A',pa:400,ab:350,h:100,x:major}]}];const expected=warOf(major,p);ok(expected>1,'해외 MLB 공헌 준비');ok(Math.abs(ovsWarFrom(p,G.user)-expected)<1e-9,'보조 MLB 줄 공헌 누락 '+ovsWarFrom(p,G.user)+' / '+expected);});
T('[검수 11-18 #637] 은퇴 투구 요약은 1500과 2/3이닝의 아웃 수를 정확히 보존한다 [은퇴공헌검수]',()=>{const {p,h}=rt614Player(true);h.outs=4502;h.er=500;const r=retireRecord(p);ok(r.outs===4502&&r.ip===4502/3,'은퇴 투구 이닝을 정수로 반올림 '+JSON.stringify({outs:r.outs,ip:r.ip}));});
T('[검수 11-18 #614 호환] 옛 잘못된 후보의 구단 귀속은 실제 보관 기록으로 복원하며 멱등이다 [은퇴공헌검수]',()=>{const {p}=rt614Player(false,52),old=G.user,h=p.hist[0];h.g=120;p.no=56;p.noT=old;retireOut(p,'은퇴');const r=G.legends.find(r=>r.pid===p.id);delete r.retByTeam;delete r.mineTid;const next=G.teams.find(t=>t.id!==old).id;switchTeam(next);r.canRetNo=true;r.tid=next;r.retNoRule={war:40,seasons:8};const rng=__rngState();retirementMigrate();ok(!retNoCands().some(x=>x.r===r)&&!r.canRetNo,'옛 잘못된 구단 후보가 남음');const j=JSON.stringify(G);retirementMigrate();ok(JSON.stringify(G)===j&&__rngState()===rng,'은퇴 기록 복원 비멱등·난수');});
T('[검수 11-18 #622 #623 호환] 옛 잘못된 헌액은 실제 WAR와 정규 수상 자료로만 바로잡는다 [은퇴공헌검수]',()=>{for(const badAward of [false,true]){const {p}=rt614Player(false,badAward?5.4:37.96);p.aw=badAward?[(G.year-2)+' KS MVP',(G.year-1)+' 올스타 MVP']:[];retireOut(p,'은퇴');const r=G.legends.find(r=>r.pid===p.id);delete r.warExact;delete r.awRegV;r.hof=true;if(badAward)r.mvp=2;G.hof=[{...r,pid:undefined,id:p.id}];retirementMigrate();ok(!r.hof&&!hofList().some(x=>(x.pid??x.id)===p.id),'잘못된 구형 헌액 유지');const j=JSON.stringify(G),rng=__rngState();retirementMigrate();ok(JSON.stringify(G)===j&&__rngState()===rng,'구형 헌액 복원 중복·난수');}});
T('[검수 11-18 #626 #637 호환] 실제 은퇴와 보관된 아웃 수는 저장 뒤에도 분실하지 않는다 [은퇴공헌검수]',()=>{const {p,h}=rt614Player(true);h.outs=4502;h.er=500;retireOut(p,'정식 은퇴');const r=G.legends.find(r=>r.pid===p.id);delete r.outs;r.ip=1501;G=JSON.parse(JSON.stringify(G));retirementMigrate();const x=G.legends.find(r=>r.pid===p.id),a=G.arch[p.id];ok(x.outs===4502&&x.ip===4502/3,'구형 이닝 정밀도 복원 실패');ok(a.retY===G.year&&careerBoard().find(x=>x.id===p.id).lab===G.year+' 은퇴','실제 은퇴 표시 소실');});
T('[검수 11-18 #623 기준] 같은 실제 WAR의 현역과 은퇴 선수는 정규 MVP 기준이 같다 [은퇴공헌검수]',()=>{const {p}=rt614Player(false,30.001);p.aw=[(G.year-1)+' MVP'];const w=hofWatch().find(x=>x.p.id===p.id);ok(w?.met,'현역 WAR30 MVP1 준비');const r=retireRecord(p);ok(r.hof&&r.mvp===1,'은퇴 시 현역과 다른 헌액 기준');});
T('[검수 11-18 #627 분할] 주 보조 줄의 MLB NPB 공헌만 각각 한 번 합산한다 [은퇴공헌검수]',()=>{const {p}=rt614Player(false),m={...bz(),y:G.year,lvl:'MLB',pa:300,ab:250,h:100,hr:20,bb:40,pos:p.pos},n={...bz(),y:G.year,lvl:'NPB',pa:200,ab:170,h:70,hr:10,bb:30,pos:p.pos};G.abroad=[{id:p.id,from:G.user,foreign:null,lines:[{...m,x:{lvl:'트리플A',pa:1000,ab:800,h:500}},{y:G.year,lvl:'트리플A',pa:500,ab:400,h:200,x:n}]}];const w=warOf(m,p)+warOf(n,p)*.7;ok(Math.abs(ovsWarFrom(p,G.user)-w)<1e-9,'빅리그 부분 누락·마이너 혼입·중복 '+ovsWarFrom(p,G.user)+' / '+w);const j=JSON.stringify(G),rng=__rngState();ovsWarFrom(p,G.user);ok(JSON.stringify(G)===j&&__rngState()===rng,'공헌 조회 부작용');});
T('[검수 11-18 #614 정정] 완전한 원본으로 잘못된 구단 결번만 걷고 정상 불명 기록은 보존한다 [은퇴공헌검수]',()=>{const {p}=rt614Player(false),old=G.user;p.hist=[];for(let i=1;i<=8;i++){const h={y:G.year-i,lvl:'1군',t:old,pos:p.pos,g:120,pa:450,ab:400,h:120,bb:50};p.hist.push(h);p.pw[warKey(h)]=6.5;}p.no=56;p.noT=old;p.svc=8;retireOut(p,'은퇴');const r=G.legends.find(r=>r.pid===p.id);delete r.retByTeam;delete r.retByTeamFull;const next=G.teams.find(t=>t.id!==old).id;switchTeam(next);G.retNos=[{pid:p.id,name:p.name,no:56,y:G.year},{pid:998614,name:'자료 소실',no:67,y:G.year},{pid:999614,name:'일부 보관',no:68,y:G.year}];G.orgT=G.orgT||{};G.orgT[old]={...(G.orgT[old]||{}),retNos:[{pid:p.id,name:p.name,no:56,y:G.year}]};r.retNo=true;r.canRetNo=true;r.tid=next;r.retNoRule={war:40,seasons:8};G.legends.push({pid:998614,name:'자료 소실',war:50,seasons:8,teams:[old,next],retNo:true,tid:next,no:67},{pid:999614,name:'일부 보관',war:50,seasons:8,teams:[old,next],retNo:true,tid:next,no:68});G.arch[999614]={id:999614,name:'일부 보관',isP:false,y:G.year,rows:[{y:G.year-1,t:old,g:100,pa:400,war:5}]};chron('retNo',p.name+' 56번 영구결번 지정',p.id,next,{source:'retNo:'+G.year+':56'});chron('retNo',p.name+' 56번 영구결번 지정',p.id,old,{source:'retNo:'+G.year+':56'});chron('award',p.name+' 정규 MVP',p.id,next,{source:'award:proof:'+p.id});const rng=__rngState();retirementMigrate();ok(!G.retNos.some(x=>x.pid===p.id),'잘못된 서울56결번 유지');ok(G.orgT[old].retNos.some(x=>x.pid===p.id)&&r.retNo&&r.tid===old,'정상 광주56결번 또는 전체 결번표시 소실');ok(G.retNos.some(x=>x.pid===998614)&&G.retNos.some(x=>x.pid===999614),'불명 또는 일부 보관 기록을 추정해 삭제');ok(!G.chron.some(e=>e.k==='retNo'&&e.tid===next&&e.ref===p.id)&&G.chron.some(e=>e.k==='retNo'&&e.tid===old&&e.ref===p.id)&&G.chron.some(e=>e.k==='award'&&e.ref===p.id),'구단별 연대기 정정 범위 오류');const j=JSON.stringify(G);retirementMigrate();ok(JSON.stringify(G)===j&&__rngState()===rng,'결번 정정 비멱등 또는 난수');});

T('[검수 11-18 #622 #624] 명예의전당 배열의 구형 무표식 행도 정밀 WAR 미달이면 정리한다 [은퇴공헌검수]',()=>{fresh();G.arch={};G.ob=[];G.legends=[];G.hof=[{id:622991,name:'구형무표식',y:2020,war:38,warExact:37.96,mvp:0,gg:0,aw:[],awRegV:1},{id:622992,name:'정상무표식',y:2020,war:40,warExact:40,mvp:0,gg:0,aw:[],awRegV:1}];retirementMigrate();ok(!hofList().some(r=>(r.pid??r.id)===622991),'HOF 배열의 hof표식 없는 정밀 미달 선수가 남음');ok(hofList().some(r=>(r.pid??r.id)===622992),'정상 구형 헌액까지 제거');});
T('[검수 11-18 #622 #624 사본] 정밀 미달 근거가 한 사본에만 있어도 같은 선수의 오래된 헌액 표식은 지운다 [은퇴공헌검수]',()=>{fresh();G.arch={};G.ob=[];G.legends=[{pid:622993,name:'사본정밀검증',y:2020,war:38,mvp:0,gg:0,aw:[],awRegV:1,hof:true}];G.hof=[{id:622993,name:'사본정밀검증',y:2020,war:38,warExact:37.96,mvp:0,gg:0,aw:[],awRegV:1,hof:true}];retirementMigrate();ok(!hofList().some(r=>(r.pid??r.id)===622993),'다른 사본의 정밀 미달 근거가 전파되지 않아 잘못된 헌액 유지');});
T('[검수 11-18 #614 번호] 구단 공헌이 있어도 그 구단 등번호를 모르면 다른 구단 번호를 결번으로 쓰지 않는다 [은퇴공헌검수]',()=>{fresh();G.fd=null;const U=G.user,V=G.teams.find(t=>t.id!==U).id,p=domestic(U).find(p=>!p.isP&&!p.prospect);p.hist=[];p.pw={};p.svc=8;p.aw=[];p.noBy={};p.team=V;p.no=56;p.noT=V;for(let i=1;i<=8;i++){const h={y:G.year-i,lvl:'1군',t:U,pos:p.pos,g:120,pa:450,ab:400,h:120,bb:50};p.hist.push(h);p.pw[warKey(h)]=6.5;}G.cfg=G.cfg||{};G.cfg.retWar=40;ok(noAt(p,U)==null,'원 소속 등번호 미상 준비');const r=retireRecord(p);ok(!retNoCands().some(x=>x.r===r),'서울56번을 등번호 미상인 광주 결번 후보로 가져옴');ok(retireNumber('p'+p.id)==='대상이 아닙니다.','다른 구단에서 단 번호를 현재 구단 결번으로 지정');});

function ch615_base(){fresh();const U=G.user,V=G.teams.find(t=>t.id!==U).id,y=G.year;G.day=KD(11,1);G.noRain=true;G.last={y,ps:{champ:U},order:G.teams.map(t=>({tid:t.id,w:80,l:64,t:0})),fins:{}};G.rolled=y;G.ps=null;return {U,V,y};}
function ch615_aw(p,k='mvp',tid=p.team){const y=G.year,c={id:p.id,name:p.name,t:tid,line:'검수 성적',v:100,w:10,s:10};const A={y,gmT:tid,mvp:k==='mvp'?{...c}:null,roy:null,gg:k==='gg'?{SS:{...c}}:{},cand:{mvp:k==='mvp'?[{...c}]:[],roy:[],gg:k==='gg'?{SS:[{...c}]}:{}},pend:{mvp:k==='mvp',gg:k==='gg'}};(G.awards=G.awards||{})[y]=A;return A;}
function ch615_seed(){const y=G.year,U=G.user,p=domestic(U).find(p=>!p.isP),q=domestic(U).find(p=>p.isP);Object.assign(lineFor(p,y,U,'1군'),{g:140,pa:600,ab:510,h:180,hr:40,d:30,tr:2,rbi:110,bb:80,so:90});Object.assign(lineFor(q,y,U,'1군'),{g:30,gs:30,outs:540,er:45,so:190,w:18,l:6,bb:40,h:150,bf:720});return {p,q};}
T('[검수 11-18 #615] 우승팀 핵심 선수는 이적 전 타 구단 홈런을 더하지 않는다 [우승시상검수]',()=>{const {U,V,y}=ch615_base(),p=domestic(U).find(p=>!p.isP);p.hist=[];Object.assign(lineFor(p,y,V,'1군'),{g:100,pa:420,ab:380,h:130,hr:55,rbi:100});Object.assign(lineFor(p,y,U,'1군'),{g:0,pa:0,ab:0,h:0,hr:0,rbi:0});const h={y,champ:U,order:G.last.order};histSnapSeason(h);const q=h.cr.b.find(x=>x.id===p.id);ok(!q||!q.l.includes('55홈런'),'이적 전55홈런을 우승팀 기여로 기록 '+JSON.stringify(q));});
T('[검수 11-18 #616] 우승팀에서 활약한 뒤 떠난 선수와 보관 선수도 우승 기록에 남는다 [우승시상검수]',()=>{for(const gone of [false,true]){const {U,V,y}=ch615_base(),p=domestic(U).find(p=>!p.isP);p.hist=[];Object.assign(lineFor(p,y,U,'1군'),{g:140,pa:600,ab:530,h:170,hr:55,rbi:120});const id=p.id;p.team=V;if(gone)dropP(p.id);const h={y,champ:U,order:G.last.order};histSnapSeason(h);const q=h.cr.b.find(x=>x.id===id);ok(q&&q.l.includes('55홈런'),'우승 기여 선수 누락 '+gone+' '+JSON.stringify(h.cr.b));}});
T('[검수 11-18 #618] 늦은 골든글러브 후보도 투표 시작과 마감을 거쳐 발표한다 [우승시상검수]',()=>{const {y}=ch615_base();G.day=KD(12,12);ch615_seed();const A=seasonAwards(y);ok(A.mvp&&Object.keys(A.gg).length,'실제 후보 준비');for(let n=0;n<5;n++)processDay();ok(A.ggVote.received===A.ggVote.voters,'투표 접수 없이 발표 '+JSON.stringify(A.ggVote));ok(A.ggVote.news.start&&A.ggVote.news.closed,'투표 시작/마감 소식 누락 '+JSON.stringify(A.ggVote.news));ok(!A.pend.gg&&A.cd.gg>A.ggVote.end,'투표 마감 전 수상 확정 또는 미발표');});
T('[검수 11-18 #619 안내] 12월31일 후보 발표도 다음 해 실제 시상 날짜를 안내한다 [우승시상검수]',()=>{const {y}=ch615_base();G.day=KD(12,31);ch615_seed();seasonAwards(y);const m=G.mail.find(x=>String(x.subj).includes('시상식 후보 발표'));ok(m&&!m.body.includes('추후 정해지는 날')&&m.body.includes('1월'),'연말 후보 시상일 미정 '+m?.body.slice(-100));});
T('[검수 11-18 #619 진행] 새해가 되어도 작년 MVP와 골든글러브는 실제 진행에서 발표한다 [우승시상검수]',()=>{const {y}=ch615_base();G.day=KD(12,31);ch615_seed();const A=seasonAwards(y);for(let n=0;n<7;n++)processDay();ok(G.year===y+1,'실제 새해 진행 준비');ok(!A.pend.mvp&&!A.pend.gg&&dobj(A.cd.mvp).y===y+1&&dobj(A.cd.gg).y===y+1,'작년 시상 누락 '+JSON.stringify({pend:A.pend,cd:A.cd}));ok(G.players[A.mvp.id].aw.includes(y+' MVP'),'시상 연도를 새해로 잘못 저장');ok(G.mail.some(m=>m.subj.startsWith(y+' ')&&m.subj.includes('시상식')),'지난 시즌 수상 메일 누락');});
T('[검수 11-18 #620] 은퇴 또는 단장 이직 뒤에도 같은 MVP 연대기는 한 건만 남는다 [우승시상검수]',()=>{for(const mode of ['retire','move']){const {U,V,y}=ch615_base(),p=domestic(U).find(p=>!p.isP);Object.assign(lineFor(p,y,U,'1군'),{g:130,pa:500,ab:450,h:150,hr:30});ch615_aw(p);const id=p.id,name=p.name;if(mode==='retire')dropP(id);else G.user=V;awardCeremony('mvp');const L=clubChron(U).filter(x=>x.k==='award'&&x.ref===id&&x.t===name+' '+y+' MVP');ok(L.length===1,'같은 MVP 연대기 '+mode+' '+L.length);}});
T('[검수 11-18 #621] 골든글러브는 후보 때 구단 대신 시상일 현재 소속으로 발표한다 [우승시상검수]',()=>{for(const watchNew of [false,true]){const {U,V,y}=ch615_base(),p=domestic(U).find(p=>!p.isP);Object.assign(lineFor(p,y,U,'1군'),{g:130,pa:500,ab:450,h:150});const A=ch615_aw(p,'gg');p.team=V;if(watchNew)G.user=V;awardCeremony('gg');const m=G.mail.find(x=>x.subj.includes('골든글러브 시상식'));ok(A.gg.SS.t===V,'수상 소속이 후보 발표 때 구단으로 고정');ok((m.body.includes(p.name+' 골든글러브'))===watchNew,'우리 구단 수상 안내가 시상일 소속과 다름 '+m.body);ok(clubChron(V).some(x=>x.k==='award'&&x.ref===p.id),'시상일 새 구단 연대기 누락');}});
T('[검수 11-18 #632] 같은 시즌 결산을 재전달해도 감독 승패와 우승은 한 번만 남는다 [우승시상검수]',()=>{const {U,y}=ch615_base(),h={y,champ:U,order:G.last.order};histSnapSeason(h);histSnapSeason(JSON.parse(JSON.stringify(h)));const A=G.mgrH[U],w=sum(A.map(x=>x.w)),c=sum(A.map(x=>x.ch));ok(A.length===1&&w===80&&c===1,'감독 재임 중복 '+JSON.stringify(A));});
T('[검수 11-18 #619 업적] 새해 작년 골든글러브 발표는 그해 단장 업적에 한 번 반영한다 [우승시상검수]',()=>{const {U,y}=ch615_base(),P=domestic(U).filter(p=>!p.isP).slice(0,3),A=ch615_aw(P[0],'gg');A.gg={};A.cand.gg={};for(let i=0;i<3;i++){const p=P[i],pos=['C','SS','1B'][i],c={id:p.id,name:p.name,t:U,line:'검수',v:288,w:8,s:8};p.draft={y:y-8,tid:U,rd:i+1};A.gg[pos]={...c};A.cand.gg[pos]=[{...c}];}G.ach={};G.achT=null;const T=achT();T.own[y]=U;T.ggMine=0;A.days={mvp:dnum(y+1,1,1),gg:dnum(y+1,1,3)};A.ggVote={voters:288,start:dnum(y+1,1,1),end:dnum(y+1,1,2),received:288,news:{start:1,closed:2},ballots:{}};G.year=y+1;G.cal=buildCalendar(G.year);G.day=dnum(y+1,1,3);const r=__rngState();awardsDaily();ok(!A.pend.gg&&achHas('gg3')&&T.ggMine===3,'지난 시즌 GG 업적 누락 '+JSON.stringify({pend:A.pend,gg:T.ggMine,ach:G.ach}));awardsDaily();ok(T.ggMine===3&&__rngState()===r,'지난 시즌 GG 업적 중복/주 난수 변경');});
T('[검수 11-18 #615 #619 #620 #632 호환] 옛 우승 명단 중복 연대기 감독 기록과 미결 시상은 멱등 복원한다 [우승시상검수]',()=>{const {U,V,y}=ch615_base(),p=domestic(U).find(p=>!p.isP);p.hist=[];Object.assign(lineFor(p,y,U,'1군'),{g:140,pa:600,ab:530,h:170,hr:35,rbi:100});p.team=V;const h={y,champ:U,order:G.last.order,cr:{b:[],p:[],mg:'당시감독',mvp:null}};G.history=[h];const row={tid:U,y,d:G.day,k:'award',t:p.name+' '+y+' MVP',ref:p.id};G.chron=[{...row},{...row}];G.clubHist={[U]:[{...row},{...row}]};G.mgrH={[U]:[{id:'옛감독',name:'옛감독',y0:y,y1:y,w:80,l:64,t:0,ps:1,ch:1,ru:0,ys:[y]},{id:'옛감독',name:'옛감독',y0:y,y1:y,w:80,l:64,t:0,ps:1,ch:1,ru:0,ys:[y]}]};const A=ch615_aw(p,'gg',U);G.day=KD(12,31);const r=__rngState();ok(awardHistoryMigrate()>0,'옛 기록 정리 안 됨');ok(h.cr.b.some(x=>x.id===p.id&&x.l.includes('35홈런'))&&h.cr.mg==='당시감독','옛 우승 기여 복원 또는 감독 보존 실패');ok(G.chron.length===1&&G.clubHist[U].length===1&&G.mgrH[U].length===1,'연대기/감독 중복 정리 실패');ok(dobj(A.days.gg).y===y+1&&A.days.gg>A.ggVote.end,'옛 연말 시상 일정 복원 실패');const j=JSON.stringify(G);ok(awardHistoryMigrate()===0&&JSON.stringify(G)===j&&__rngState()===r,'옛 기록 정리 비멱등·주 난수 변경');});
T('[검수 11-18 #632 호환] 중복 재임 행이 다음 해까지 이어진 옛 저장도 시즌별 원기록으로 겹침을 뺀다 [우승시상검수]',()=>{const {U,y}=ch615_base();G.year=y+2;G.history=[{y,champ:U,order:[{tid:U,w:80,l:64,t:0}]},{y:y+1,champ:null,order:[{tid:U,w:81,l:63,t:0}]},{y:y+2,champ:null,order:[{tid:U,w:82,l:62,t:0}]}];G.mgrH={[U]:[{id:'같은감독',name:'같은감독',y0:y,y1:y+1,w:161,l:127,t:0,ps:2,ch:1,ru:0,ys:[y,y+1],best:{y,rk:1}},{id:'같은감독',name:'같은감독',y0:y+1,y1:y+2,w:163,l:125,t:0,ps:2,ch:0,ru:0,ys:[y+1,y+2],best:{y:y+1,rk:1}}]};const r=__rngState();histManagerFix();const L=G.mgrH[U];ok(sum(L.map(x=>x.w))===243&&sum(L.map(x=>x.l))===189&&sum(L.map(x=>x.ch))===1,'겹친 연도 감독 통산 중복 '+JSON.stringify(L));ok(L[1].y0===y+2&&L[1].ys.length===1&&L[1].best.y===y+2,'보존한 나머지 시즌 범위가 다름');const j=JSON.stringify(G.mgrH);ok(histManagerFix()===0&&JSON.stringify(G.mgrH)===j&&__rngState()===r,'혼합 중복 복원 비멱등·난수');});

function ta617Setup(){fresh();const y=G.year;G.day=KD(11,1);G.arch={};G.titles={};G.news=[];G.mail=[];for(const p of Object.values(G.players))p.hist=p.hist.filter(h=>h.y!==y);for(const t of G.teams)G.sea.rec[t.id]={w:72,l:72,t:0};G.ps={done:true,order:G.teams.map(t=>({tid:t.id,w:72,l:72,t:0}))};return y;}
function ta617Bat(p,y,hr=50){const h=Object.assign({},ZB,{y,lvl:'1군',t:p.team,g:144,pa:600,ab:530,h:180,hr,rbi:120,r:110,bb:60,sb:15,d:25,tr:2,so:80,pos:p.pos});p.hist.push(h);return h;}
T('[검수 11-18 #617] 옛 시즌 팀 경기 수가 없으면 결산 승패로 규정타석 이닝을 판정한다 [타이틀검수]',()=>{fresh();const y=G.year-1,b=domestic(G.user).find(p=>!p.isP),p=domestic(G.user).find(p=>p.isP);G.tsArch={};const order=G.teams.map(t=>({tid:t.id,w:72,l:72,t:0}));G.history=[{y,order}];G.last={y,order};for(const q of [b,p])q.hist=q.hist.filter(h=>!(h.y===y&&h.lvl==='1군'));b.hist.push(Object.assign({},ZB,{y,lvl:'1군',t:G.user,g:1,pa:1,ab:1,h:1}));p.hist.push(Object.assign({},ZP,{y,lvl:'1군',t:G.user,g:1,outs:3,er:0}));const hb=seasonTotal(b,y,'1군'),hp=seasonTotal(p,y,'1군');ok(!qualPA(b,hb,y)&&!qualIP(p,hp,y),'규정 함수 준비');ok(!titleBoard(y,'avg',false).some(x=>x.p.id===b.id),'1타수1안타 타율 순위 포함');ok(!titleBoard(y,'era',true,true).some(x=>x.p.id===p.id),'1이닝0자책 ERA 순위 포함');ok(tgp(G.user,y)===144,'결산144경기 복원 실패');});
T('[검수 11-18 #617 단축] 옛 단축 시즌 규정은 고정144 대신 그해 실제 경기 수를 쓴다 [타이틀검수]',()=>{fresh();const y=G.year-1,p=domestic(G.user).find(p=>!p.isP);G.tsArch={};G.history=[{y,order:G.teams.map(t=>({tid:t.id,w:50,l:40,t:0}))}];G.last={y,order:[]};p.hist=p.hist.filter(h=>h.y!==y);const h=Object.assign({},ZB,{y,lvl:'1군',t:G.user,g:90,pa:279,ab:250,h:100,bb:29});p.hist.push(h);ok(qualPA(p,h,y),'90경기 279타석 규정 누락');ok(titleBoard(y,'avg',false).some(x=>x.p.id===p.id),'단축 시즌 타율 대상 누락');});
T('[검수 11-18 #628] 시즌 포지션 없는 타이틀 홀더는 선수의 주 포지션 골든글러브 후보다 [타이틀검수]',()=>{const y=ta617Setup(),p=domestic(G.user).find(p=>!p.isP);p.pos='RF';delete p.use;const h=ta617Bat(p,y,61);delete h.pos;delete h.pp;const A=seasonAwards(y);ok(A.cand.mvp.some(c=>c.id===p.id),'MVP 타이틀 홀더 준비');ok((A.cand.gg.OF||[]).some(c=>c.id===p.id),'포지션 누락으로 타이틀 홀더 GG후보 탈락');});
T('[검수 11-18 #629] 6번째 입단 시즌은 신인왕에서 제외하고 5번째 시즌은 포함한다 [타이틀검수]',()=>{const y=ta617Setup(),L=domestic(G.user).filter(p=>!p.isP),p=L[0],q=L[1];for(const [x,entry] of [[p,y-5],[q,y-4]]){x.hist=[];x.foreign=null;x.ovsExp=0;x.draft={y:entry-1,tid:G.user};x.joinY=entry;x.svc=1;ta617Bat(x,y,12);}G.abroad=[];const A=seasonAwards(y),ids=A.cand.roy.map(c=>c.id);ok(!ids.includes(p.id),'입단6시즌 신인왕 후보');ok(ids.includes(q.id),'입단5시즌 신인왕 후보 누락');});
T('[검수 11-18 #630] 선두 동률 세 번째 우리 선수도 타이틀 경쟁 알림을 받는다 [타이틀검수]',()=>{const y=ta617Setup(),p=domestic(G.user).find(p=>!p.isP),O=Object.values(G.players).filter(q=>!q.isP&&q.team!=null&&q.team!==G.user&&q.id<p.id).slice(0,2);ok(O.length===2,'순서 준비');for(const x of [...O,p])ta617Bat(x,y,61);titleRaceNews();const m=G.mail.find(m=>m.subj.includes('우리 선수 타이틀 경쟁'));ok(m&&m.body.includes(p.name)&&m.body.includes('공동 1위'),'세 번째 공동선두 알림 누락 '+JSON.stringify(m));});
T('[검수 11-18 #630 공동2위] 공동2위 묶음은 목록 두 번째 이후 선수까지 모두 알린다 [타이틀검수]',()=>{const y=ta617Setup(),p=domestic(G.user).find(p=>!p.isP),O=Object.values(G.players).filter(q=>!q.isP&&q.team!=null&&q.team!==G.user&&q.id<p.id).slice(0,2);ta617Bat(O[0],y,62);ta617Bat(O[1],y,61);ta617Bat(p,y,61);titleRaceNews();const m=G.mail.find(m=>m.subj.includes('우리 선수 타이틀 경쟁'));ok(m&&m.body.includes(p.name)&&m.body.includes('공동 2위'),'공동2위 묶음 누락');});
T('[검수 11-18 #631] 우리 구단 공동 타이틀 기사 링크는 우리 수상자를 가리킨다 [타이틀검수]',()=>{const y=ta617Setup(),p=domestic(G.user).find(p=>!p.isP),q=Object.values(G.players).find(q=>!q.isP&&q.team!=null&&q.team!==G.user&&q.id<p.id);ta617Bat(q,y,55);ta617Bat(p,y,55);seasonTitles(y);const n=G.news.find(n=>n.t.startsWith(y+' 개인 타이틀'));ok(n&&n.t.includes(tshort(G.user)),'우리 구단 타이틀 기사 준비');ok(n.ref===p.id,'우리 기사 링크가 타팀 공동 수상자 '+n.ref+' / '+p.id);});
T('[검수 11-18 #643] 같은 시즌 타이틀 재집계는 수상 이력 기분 소식 난수를 중복 반영하지 않는다 [타이틀검수]',()=>{const y=ta617Setup(),p=domestic(G.user).find(p=>!p.isP);p.aw=[];p.story=[];p.mor=0;ta617Bat(p,y,55);seasonTitles(y);const a=JSON.stringify(p.aw),story0=JSON.stringify(p.story),mor=p.mor,n=G.news.length,rng=__rngState();seasonTitles(y);ok(p.aw.filter(l=>l===y+' 홈런왕').length===1&&JSON.stringify(p.aw)===a,'홈런왕 수상 이력 중복');ok(JSON.stringify(p.story)===story0&&p.mor===mor&&G.news.length===n&&__rngState()===rng,'재집계 부가 효과 중복');});
T('[검수 11-18 #643 호환] 옛 중복 수상 목록은 선수 보관 해외 사본에서 멱등 복원한다 [타이틀검수]',()=>{const y=ta617Setup(),p=domestic(G.user).find(p=>!p.isP),label=y+' 홈런왕';p.aw=[label,label,y+' 타점왕'];G.arch={9001:{id:9001,name:'보관선수',aw:[label,label]}};G.legends=[{id:9001,name:'보관선수',aw:[label,label]}];G.abroad=[{id:9002,name:'해외선수',aw:[label,label],pj:JSON.stringify({id:9002,aw:[label,label]})}];const rng=__rngState();if(typeof awardListFix==='function')awardListFix();ok(p.aw.length===2&&G.arch[9001].aw.length===1&&G.legends[0].aw.length===1&&G.abroad[0].aw.length===1&&JSON.parse(G.abroad[0].pj).aw.length===1,'옛 중복 수상 목록 잔류');const a=JSON.stringify([p.aw,G.arch,G.legends,G.abroad]);awardListFix();ok(JSON.stringify([p.aw,G.arch,G.legends,G.abroad])===a&&__rngState()===rng,'수상 목록 복원 비멱등/난수');});
T('[검수 11-18 #643 해외] 해외 타이틀 재집계도 보관 선수 이력과 연대기에 한 번만 남긴다 [타이틀검수]',()=>{const y=ta617Setup(),p=domestic(G.user).find(p=>!p.isP);p.aw=[];p.story=[];ta617Bat(p,y,55);archPlayer(p);G.abroad=[{id:p.id,name:p.name,from:G.user,back:false,pj:JSON.stringify(p),aw:[]}];delete G.players[p.id];seasonTitles(y);const a=JSON.stringify(G.abroad),ar=JSON.stringify(G.arch[p.id].aw),rng=__rngState();seasonTitles(y);ok(JSON.stringify(G.abroad)===a&&JSON.stringify(G.arch[p.id].aw)===ar&&__rngState()===rng,'해외 수상 재집계 이력/난수 중복');const q=JSON.parse(G.abroad[0].pj);ok(q.aw.filter(l=>l===y+' 홈런왕').length===1&&q.story.filter(s=>s.t===y+' 홈런왕').length===1,'해외 홈런왕 중복');});

const ft633_setup=(isP=false,ai=false)=>{fresh();G.day=G.cal.open+30;G.noRain=true;const tid=ai?otherT():G.user,p=playersOf(tid).find(q=>q.isP===isP&&!q.foreign&&!q.prospect);p.hist=[];p.story=[];p.feats=[];delete p.cum;delete p.fl;delete p.sct;delete p.hstk;delete p.hstkF;G.feats=[];G.featSeq=0;return p;};
const ft633_has=(p,text)=>(p.story||[]).some(x=>x.t.includes(text))&&(p.feats||[]).some(x=>x.txt.includes(text))&&(G.feats||[]).some(x=>x.pid===p.id&&x.txt.includes(text));
T('[검수 11-18 #633] 안타 연속 기록을 이적 뒤 늘리면 새 경기 구단으로 갱신한다 [진기록검수]',()=>{const p=ft633_setup(),old=p.team,tid=otherT(),r=__rngState();p.hstk=19;featBat(p,{ab:4,h:1},'4월 10일 vs A');const id=p.hstkF;p.team=tid;G.day++;featBat(p,{ab:4,h:1},'4월 11일 vs B');const f=G.feats.find(x=>x.id===id);ok(f.v===21&&f.tid===tid&&f.tid!==old&&f.d===G.day&&f.vs==='4월 11일 vs B','연장 안타 기록의 구단이 옛 팀');ok(p.feats.filter(x=>x.k==='hs').length===1&&p.feats[0].txt==='21경기 연속 안타','선수 기록 중복');ok(__rngState()===r,'연속 안타 연장이 본 난수를 소비');});
T('[검수 11-18 #634] 리그 목록에서 밀려난 연속 기록도 선수의 같은 기록을 갱신한다 [진기록검수]',()=>{const p=ft633_setup();p.hstk=19;featBat(p,{ab:4,h:1},'4월 10일 vs A');const id=p.hstkF;G.feats=Array.from({length:600},(_,i)=>({id:i+2,k:'gs',pid:-1,y:G.year,d:G.day,txt:'다른 기록'}));G.featSeq=601;G.day++;featBat(p,{ab:4,h:1},'4월 11일 vs B');const P=p.feats.filter(x=>x.k==='hs');ok(P.length===1&&P[0].i===id&&P[0].txt==='21경기 연속 안타'&&p.hstkF===id,'프로필에 20/21 두 행 생성 '+JSON.stringify(P));ok(G.feats.length<=600&&G.feats.some(x=>x.id===id&&x.v===21),'현재 연장 기록을 리그 목록에 복원하지 않음');featBat(p,{ab:4,h:0},'4월 12일 vs C');p.hstk=19;featBat(p,{ab:4,h:1},'5월 10일 vs D');ok(p.hstkF!==id&&p.feats.filter(x=>x.k==='hs').length===2,'끊긴 뒤 새 연속 기록까지 합침');});
T('[검수 11-18 #638] 통산 3000안타 예고 뒤 실제 도달 경기에 연표와 진기록이 남는다 [진기록검수]',()=>{const p=ft633_setup();p.hist=[{y:G.year-1,t:p.team,lvl:'1군',pa:9000,ab:8500,h:2999,hr:50,rbi:200,sb:30}];ok(mileWatch().some(x=>x.p.id===p.id&&x.k==='h'&&x.g===3000&&x.left===1),'3000안타 예고 준비');storyGame(p,{ab:4,h:1},G.day,otherT(),{hld:[]},{});ok(p.cum.h===3000&&ft633_has(p,'통산 3000안타'),'3000안타 달성 이력 누락');});
T('[검수 11-18 #639] 통산 100홀드는 판정된 홀드를 받아 달성 기록으로 남긴다 [진기록검수]',()=>{const p=ft633_setup(true);p.hist=[{y:G.year-1,t:p.team,lvl:'1군',g:200,outs:600,hld:99,so:400,w:5,sv:0}];ok(mileWatch().some(x=>x.p.id===p.id&&x.k==='hld'&&x.g===100&&x.left===1),'100홀드 예고 준비');storyGame(p,{outs:3,so:1},G.day,otherT(),{hld:[p.id]},{});ok(p.cum.hld===100&&ft633_has(p,'통산 100홀드'),'100홀드 달성 이력 누락');});
T('[검수 11-18 #640] 같은 경기의 500타점과 200도루를 사용자와 AI 모두 기록한다 [진기록검수]',()=>{for(const ai of [false,true]){const p=ft633_setup(false,ai);p.hist=[{y:G.year-1,t:p.team,lvl:'1군',pa:3000,ab:2700,h:700,hr:50,rbi:499,sb:199}];storyGame(p,{ab:4,h:1,rbi:1,sb:1},G.day,G.teams.find(t=>t.id!==p.team).id,{hld:[]},{});ok(p.cum.rbi===500&&p.cum.sb===200&&ft633_has(p,'통산 500타점')&&ft633_has(p,'통산 200도루'),'타점/도루 달성 누락 '+ai);}});
T('[검수 11-18 #641] 옛 시즌 카운터가 없어도 실제 경기에서 40홈런 200안타를 한 번 센다 [진기록검수]',()=>{fresh();G.day=G.cal.open+20;G.noRain=true;G.entryY=G.year;for(const t of G.teams)setEntry(t.id);const U=G.user,V=otherT(),g=withRng(641,()=>simGame(G.day,U,V,false)),p=G.players[g.S.h.order[0].id];p.hist=[{y:G.year,t:U,lvl:'1군',g:100,pa:450,ab:400,h:199,hr:39,rbi:80,sb:10}];p.story=[];p.feats=[];delete p.sct;delete p.cum;delete p.fl;const x={...bz(),pa:4,ab:4,h:1,hr:1,rbi:1,r:1};g.S.h.box.set(p.id,x);applyGame(G.day,U,V,g,false);const h=seasonTotal(p,G.year,'1군');ok(h.h===200&&h.hr===40,'실제 경기 반영 준비');ok(p.sct.h===200&&p.sct.hr===40,'현재 경기를 중복/누락 계산 '+JSON.stringify(p.sct));ok((p.story||[]).filter(x=>x.t.includes('시즌 200안타')).length===1&&(p.story||[]).filter(x=>x.t.includes('시즌 40홈런')).length===1,'40홈런 200안타 알림 누락');});
T('[검수 11-18 #641 복원] 옛 통산 신규 항목과 시즌 카운터 정리는 멱등이며 난수 불변이다 [진기록검수]',()=>{const p=ft633_setup();p.hist=[{y:G.year-1,t:p.team,lvl:'1군',pa:400,ab:350,h:100,hr:20,rbi:200,sb:30},{y:G.year,t:p.team,lvl:'1군',pa:450,ab:400,h:199,hr:39,rbi:70,sb:10}];p.cum={h:299,hr:59,w:0,sv:0,so:0};p.sct={y:G.year,h:1,hr:1,w:0,sv:0};const r=__rngState();ok(typeof storyCountersMigrate==='function','카운터 복원 함수 없음');storyCountersMigrate();ok(p.cum.rbi===270&&p.cum.sb===40&&p.sct.h===199&&p.sct.hr===39,'실제 누적 복원 실패');const s=JSON.stringify([p.cum,p.fl,p.sct]);ok(storyCountersMigrate()===0&&JSON.stringify([p.cum,p.fl,p.sct])===s&&__rngState()===r,'카운터 복원 멱등 또는 난수 불변 실패');});
T('[검수 11-18 #638 난수] 새 3000안타 기사와 기념 제안이 다음 경기 난수에 영향을 주지 않는다 [진기록검수]',()=>{const p=ft633_setup();p.hist=[{y:G.year-1,t:p.team,lvl:'1군',pa:9000,ab:8500,h:2999,hr:50,rbi:200,sb:30}];const r=__rngState();storyGame(p,{ab:4,h:1},G.day,otherT(),{hld:[]},{});ok(ft633_has(p,'통산 3000안타'),'새 이정표 기사 분기 미실행');ok(__rngState()===r,'새 통산 이정표가 본 경기 난수를 소비');});

function pp635_setup(){fresh();const U=G.user,p=playersOf(U).find(x=>x.isP),op=G.teams.find(x=>x.id!==U).id;delete p.psY;G.psSer={};const g={S:{h:{tid:U,pitchers:[p.id],box:new Map([[p.id,{outs:12,h:2,hr:0,bb:1,so:4,er:0,hbp:2,bf:17}]])},a:{tid:op,pitchers:[],box:new Map()}},dec:{hld:[p.id]}};return {U,p,op,g};}
T('[검수 11-18 #635] 포스트시즌 홀드는 시리즈와 개인 시즌 합계에 모두 남는다 [가을기록검수]',()=>{const {p,g}=pp635_setup();psRec('ks',g);ok(G.psSer[G.year].ks[p.id].hld===1,'라운드 홀드 누락');ok(p.psY[G.year].hld===1,'개인 가을야구 홀드 누락');});
T('[검수 11-18 #636] 가을 투수 기록에 사구와 상대 타자 수를 함께 보존한다 [가을기록검수]',()=>{const {p,g}=pp635_setup();psRec('ks',g);for(const x of [p.psY[G.year],G.psSer[G.year].ks[p.id]])ok(x.outs===12&&x.hbp===2&&x.bf===17,'4이닝 2사구 17타자 보존 실패 '+JSON.stringify(x));});
T('[검수 11-18 #642] 최근 열 경기가 모두 무승부면 최근 승률은 중립이다 [가을기록검수]',()=>{fresh();G.day=G.cal.open+30;G.sea.rec=G.teams.map(()=>({w:10,l:10,t:0}));G.sea.tl=G.teams.map(()=>Array.from({length:10},(_,i)=>i%2?[1,4,0]:[-1,0,4]));pwrWeek();const before=G.pwr.rows.find(x=>x.tid===G.user).s;G.sea.tl[G.user]=Array.from({length:10},()=>[0,2,2]);pwrWeek();ok(G.pwr.rows.find(x=>x.tid===G.user).s===before,'전부 무승부를 0%로 처리');});
T('[검수 11-18 #635 #636 호환] 옛 PS 홀드는 라운드에서, 사구·타자는 완전한 박스로 복원하며 멱등이다 [가을기록검수]',()=>{const {U,p,op}=pp635_setup(),y=G.year;G.psSer[y]={ks:{[p.id]:{t:U,n:p.name,isP:true,g:1,outs:12,hld:1}}};p.psY={[y]:{t:U,isP:true,g:1,outs:12}};G.games=[{gid:6361,day:G.cal.end+20,home:U,away:op,kind:'한국시리즈 1차전',box:{h:{pit:[{id:p.id,outs:12,hbp:2,bf:17}]},a:{pit:[]}}}];const rng=__rngState();if(typeof psRecordMigrate==='function')psRecordMigrate();ok(p.psY[y].hld===1&&p.psY[y].hbp===2&&p.psY[y].bf===17,'옛 합계 복원 누락');const s=JSON.stringify([p.psY,G.psSer]);psRecordMigrate();ok(__rngState()===rng&&JSON.stringify([p.psY,G.psSer])===s,'수리 난수 또는 비멱등');delete p.psY[y].hbp;delete G.psSer[y].ks[p.id].hbp;G.games=[];psRecordMigrate();ok(p.psY[y].hbp==null,'근거 없는 옛 사구 수를 생성');});

T('[검수 11-18 #623 #624] 상세 상 목록으로 제외한 비정규 MVP가 빈 목록의 옛 사본 카운터로 부활하지 않는다 [퇴임사본교차검토]',()=>{fresh();G.arch={};G.ob=[];const id=623924;G.legends=[{pid:id,name:'옛비정규수상',y:2020,war:5.4,mvp:2,gg:0,aw:['2019 한국시리즈 MVP','2020 올스타 MVP'],hof:true}];G.hof=[{id,name:'옛비정규수상',y:2020,war:5.4,mvp:2,gg:0,hof:true}];retirementMigrate();ok(!hofList().some(r=>(r.pid??r.id)===id),'잘못 센2MVP가 옛 사본에서 다시 전파 '+JSON.stringify([G.legends,G.hof]));});
T('[검수 11-18 #623] 수상 상세가 전혀 없는 옛 통산 MVP는 보존한다 [퇴임사본교차검토]',()=>{fresh();G.arch={};G.ob=[];const id=623925;G.legends=[{pid:id,name:'상세없는정규수상',y:2020,war:5.4,mvp:2,gg:0,hof:true}];G.hof=[{id,name:'상세없는정규수상',y:2020,war:5.4,mvp:2,gg:0,hof:true}];retirementMigrate();ok(hofList().some(r=>(r.pid??r.id)===id)&&G.legends[0].mvp===2,'상세 없는 유효 가능 통산을 삭제');const s=JSON.stringify(G),rng=__rngState();retirementMigrate();ok(JSON.stringify(G)===s&&__rngState()===rng,'반복 복원/RNG 변경');});
function tr644_setup(n=1){fresh();makeDraftClass();amLive();G.day=KD(1,12);G.scoutAuto=false;G.tripAuto=false;const base=G.scouts[0];G.scouts=Array.from({length:n},(_,i)=>({...base,id:'tr644-'+i,name:'현장직원'+i,role:'am',region:'수도권',since:G.day-50,skill:3}));return {U:G.user,V:otherT(),s:G.scouts[0]};}
T('[검수 11-18 #644] 이번 주에 적용하는 출장 안은 제목과 적용 날짜가 일치한다 [출장검수]',()=>{const {s}=tr644_setup();tripWeekly(G.day);const T0=G.tripPend,m=G.mail.find(x=>(x.acts||[]).some(a=>a.a==='tripPlanGo'&&a.v===tripPendKey(T0)));ok(m&&m.subj.includes('이번 주'),'당일 시작 계획을 다음 주라고 안내');ok(tripPlanGo(tripPendKey(T0))==='팀장 출장 안대로 보냈습니다.','현재 안 승인 실패');ok(s.trip.from===G.day,'메일 주와 적용 시작일 불일치');});
T('[검수 11-18 #645] 출장 안을 승인하지 않을 때 만료된 배정은 학교 방문으로 돌아간다고 알린다 [출장검수]',()=>{const {s}=tr644_setup();s.trip={k:'ct',from:G.day-7,to:G.day-1};tripWeekly(G.day);const m=G.mail.find(x=>(x.acts||[]).some(a=>a.a==='tripPlanGo'));ok(m&&m.body.includes('만료')&&m.body.includes('학교 방문'),'만료된 출장도 이어간다는 잘못된 안내 '+m?.body);ok(tripOf(s)==='sch','이미 끝난 출장이 계속됨');});
T('[검수 11-18 #646] 담당자가 없어 갱신되지 않은 지난주 출장 안도 승인할 수 없다 [출장검수]',()=>{const {s}=tr644_setup();tripWeekly(G.day);const key=tripPendKey(G.tripPend);G.day+=7;G.scouts=[];tripWeekly(G.day);const q={...s,id:'새직원',trip:{k:'camp',from:G.day,to:G.day+6}};G.scouts=[q];const b=JSON.stringify(q.trip),r=tripPlanGo(key);ok(r!=='팀장 출장 안대로 보냈습니다.'&&r.includes('지난'),'만료 안 성공 처리 '+r);ok(JSON.stringify(q.trip)===b,'과거 주차로 새 배정을 변경');});
T('[검수 11-18 #647] 직원이 교체되면 이전 명단용 출장 안으로 새 직원 배정을 덮지 않는다 [출장검수]',()=>{const {s}=tr644_setup();tripWeekly(G.day);const key=tripPendKey(G.tripPend),q={...s,id:'후임직원',trip:{k:'camp',from:G.day,to:G.day+6}};G.scouts=[q];const b=JSON.stringify(q.trip),r=tripPlanGo(key);ok(JSON.stringify(q.trip)===b,'명단에 없는 새 직원의 배정을 덮음');ok(r!=='팀장 출장 안대로 보냈습니다.','교체된 명단의 안을 승인');});
T('[검수 11-18 #648] 역할과 권역 변경은 이전 지역 수동 출장을 종료한다 [출장검수]',()=>{const {s}=tr644_setup();let k=null;for(let d=KD(3,2);d<KD(8,31)&&!k;d+=7){G.day=d;k=tripOptions(tripWk0(d),s.region).find(x=>x.k.startsWith('wl:'))?.k;}ok(k,'주말리그 준비');tripSet(s.id,k);assignScout(s.id,'intl','jp');assignScout(s.id,'am','영남');ok(tripOf(s)!==k,'이전 서울조 수동 출장 유지');tripApply(G.user,tripPlanWeek(G.user,tripWk0(G.day)),tripWk0(G.day));ok(tripOf(s)!==k,'팀장 안도 잘못된 수동 출장을 보존');assignScout(s.id,'am','수도권');ok(tripOf(s)!==k,'원권역 복귀로 종료된 출장 부활');});
T('[검수 11-18 #649] 지난 일요일로 끝난 수동 출장에는 직접 배지를 붙이지 않는다 [출장검수]',()=>{const {s}=tr644_setup();G.day=KD(7,13);s.trip={k:'ct',from:G.day-7,to:G.day-1,man:true};const F=eval(globalThis.__tr644UiSrc()),html=F.tripBox();ok(!html.includes('학교 방문 <i class="small muted">직접'),'기본 학교 방문에 만료 수동 배지');});
T('[검수 11-18 #650] 동명이인 직원의 현장 보고는 개인과 대회별로 구분한다 [출장검수]',()=>{const {U}=tr644_setup(2);G.scouts.forEach(s=>s.name='동명이인');const p=G.players[G.draftClass[0]],q=G.players[G.draftClass[1]],w0=tripWk0(G.day);G.tripWk={tid:U,w0,L:[['동명이인','t0',p.id,'3안타','p',G.scouts[0].id,U],['동명이인','ct',q.id,'1홈런','p',G.scouts[1].id,U]]};G.day=w0+6;const n=tripReport(G.day),m=G.mail[0];ok(n===2,'같은 이름 두 직원을 한 보고로 합침 '+n);ok(m.body.includes(tripName('t0'))&&m.body.includes(tripName('ct')),'다른 대회명이 누락');});
T('[검수 11-18 #651] 주간 현장 보고는 작성 구단을 떠난 뒤 새 구단 소식함에 도착하지 않는다 [출장검수]',()=>{const {U,V,s}=tr644_setup();const p=G.players[G.draftClass[0]],w0=tripWk0(G.day);G.tripWk={tid:U,w0,L:[[s.name,'t0',p.id,'3안타','p',s.id,U]]};switchTeam(V);G.day=w0+6;const n=G.mail.length;ok(tripReport(G.day)===null&&G.mail.length===n,'전 구단 직원 보고가 새 구단으로 발송');});
T('[검수 11-18 #652] 선수별 마지막 관찰일과 경기 보고는 구단별로 남아 이직·복귀 후에도 섞이지 않는다 [출장검수]',()=>{const {U,V,s}=tr644_setup();const x=Object.values(amPipe().L)[0],d=G.day;obsAdd(x,U,1);obsLogGame(x,{b:'3안타'},s.region,d,s,'이마트배');ok(obsLast(x)===d,'원 구단 관찰 준비');switchTeam(V);ok(obsRaw(x,V)===0,'새 구단 관찰 준비');ok(obsLast(x)==null,'전 구단 관찰 날짜 노출');ok(typeof obsLogList==='function'&&obsLogList(x).length===0,'전 구단 보고 노출');G.day++;obsAdd(x,V,1);obsLogGame(x,{b:'2탈삼진'},'영남',G.day,G.scouts[0],'대학리그');switchTeam(U);ok(obsLast(x)===d,'원 구단 날짜가 새 구단 날짜로 바뀜');const L=obsLogList(x);ok(L.length===1&&L[0][2].includes('3안타')&&!L[0][2].includes('2탈삼진'),'원 구단 보고가 섞임');const rng=__rngState();obsLogMigrate();const before=JSON.stringify([G.obsLogT,x.obsDT]);obsLogMigrate();ok(JSON.stringify([G.obsLogT,x.obsDT])===before&&__rngState()===rng,'방문 이력 복원 멱등·난수 위반');});
T('[검수 11-18 #652 호환] 구단 없는 옛 방문 보고는 관찰 근거가 있는 구단에만 복원한다 [출장검수]',()=>{const {U,V,s}=tr644_setup();const x=Object.values(amPipe().L)[0],d=G.day;x.amObs={[U]:1};x.obsD=d;G.obsLog={[x.id]:[[d,s.name,'옛 현장 보고',2]]};delete G.obsLogT;delete G.obsLogTid;G.user=V;obsLogMigrate();ok(obsLast(x)==null&&obsLogList(x).length===0,'구형 보고를 새 구단 것으로 복원');G.user=U;ok(obsLast(x)===d&&obsLogList(x)[0][2]==='옛 현장 보고','기존 구단 보고 복원 누락');});
T('[검수 11-18 #650 실제 관찰] 같은 이름의 두 현장 직원이 각자 ID와 작성 구단을 남긴다 [출장검수]',()=>{const {U}=tr644_setup(2);const t=AM_TOURS()[0];G.day=amTourSpan(G.year,t)[0];G.scouts.forEach(s=>{s.name='실제 동명이인';tripSet(s.id,t.k);});const p=G.players[G.draftClass[0]];amFollow(p.id,true);_amToday={g:G,d:G.day,L:[{ev:t.k,gk:'실관찰',id:p.id,kind:'p',b:'3안타',sch:p.school}]};const rng=__rngState();tripWatchDaily(G.day);ok(__rngState()===rng,'출장 관찰로 주 난수 소비');const L=obsLogList(p);ok(L.length===2&&L.every(r=>r[4]===U)&&new Set(L.map(r=>r[5])).size===2,'현장 보고에 실제 개인·구단 누락');const W=G.tripWkT[U];ok(W.L.length===2&&new Set(W.L.map(r=>r[5])).size===2,'주간 누적에서 동명이인 혼합');G.day=W.w0+6;ok(tripReport(G.day)===2,'실제 관찰에서 두 사람 보고 합침');});
T('[검수 11-18 #646·648 조회] 같은 ID의 담당 권역 변경도 오래된 안을 무효화하고 조회는 상태·난수를 바꾸지 않는다 [출장검수]',()=>{const {s}=tr644_setup();tripWeekly(G.day);const key=tripPendKey(G.tripPend);s.region='영남';const rng=__rngState(),state=JSON.stringify(G);ok(tripGoWhy(key).includes('권역'),'동일 직원의 권역 변경 안을 승인');tripPendNow();tripOf(s);tripManual(s);obsLast(G.players[G.draftClass[0]]);ok(JSON.stringify(G)===state&&__rngState()===rng,'안·배정·마지막 날짜 조회의 상태 변경');});
T('[검수 11-18 #651·652 옛 저장] 모호한 보고는 보관하고 명확한 구단만 복원하며 재로딩이 멱등이다 [출장검수]',()=>{const {U,V,s}=tr644_setup();const x=Object.values(amPipe().L)[0],d=G.day;x.amObs={[U]:1,[V]:2};x.obsD=d;G.obsLog={[x.id]:[[d,s.name,'작성 구단 미상',2]]};G.tripWk={w0:tripWk0(d),L:[[s.name,'t0',x.id,'3안타','e']]};delete G.obsLogV;delete G.obsLogTid;obsLogMigrate();tripMigrate();for(const tid of [U,V]){G.user=tid;ok(obsLast(x)==null&&obsLogList(x).length===0,'모호한 보고를 현재 구단에 연결');}ok(G.obsLogUnknown[x.id].length===1&&G.tripWkLegacy.L.length===1&&!G.tripWk,'미상 원본 보관 누락');G.user=U;G=JSON.parse(JSON.stringify(G));obsLogMigrate();tripMigrate();const b=JSON.stringify(G),r=__rngState();obsLogMigrate();tripMigrate();ok(JSON.stringify(G)===b&&__rngState()===r,'출장·관찰 복원 멱등 위반');});
T('[검수 11-18 #652 첫 관찰] 이직 후 처음 남긴 관찰이 옛 단일 보고의 작성 구단을 덮지 않는다 [출장검수]',()=>{const {U,V,s}=tr644_setup();const x=Object.values(amPipe().L)[0],d=G.day;x.amObs={[U]:1};x.obsD=d;G.obsLog={[x.id]:[[d,s.name,'전 구단 원본',2]]};delete G.obsLogV;delete G.obsLogTid;G.user=V;G.day++;obsAdd(x,V,1);obsLogGame(x,{b:'새 구단'},'영남',G.day,s,'학교');ok(obsLogList(x).length===1&&!obsLogList(x)[0][2].includes('전 구단 원본'),'첫 방문이 전 구단 보고까지 가져옴');G.user=U;ok(obsLogList(x)[0][2]==='전 구단 원본'&&obsLast(x)===d,'첫 방문으로 전 구단 이력 손실');});
T('[검수 11-18 #646 옛 승인] 작성 구단 없는 옛 안은 로딩 때 보관하고 이전 버튼은 무효이며 재복원이 멱등이다 [출장검수]',()=>{const {s}=tr644_setup();const w0=tripWk0(G.day);G.tripPend={w0,P:{[s.id]:'camp'}};const b=JSON.stringify(s.trip),r=__rngState();ok(tripGoWhy(String(w0)).includes('작성 구단'),'작성 구단 불명 안을 승인 가능');G=JSON.parse(JSON.stringify(G));tripMigrate();ok(!G.tripPend&&G.tripPendLegacy.P[s.id]==='camp','구형 안을 안전하게 보관하지 않음');ok(tripPlanGo(String(w0))!=='팀장 출장 안대로 보냈습니다.','옛 승인 버튼 성공');const state=JSON.stringify(G);tripMigrate();ok(JSON.stringify(G)===state&&__rngState()===r,'옛 출장 안 복원 멱등·난수 위반');ok(JSON.stringify(G.scouts[0].trip)===b,'옛 승인으로 현재 배정 변경');});
T('[검수 11-18 #651 옛 보고] 이후에 관찰한 구단의 마지막 방문 날짜로 오래된 보고의 작성 구단을 추측하지 않는다 [출장검수]',()=>{const {U,V,s}=tr644_setup();const x=Object.values(amPipe().L)[0];x.amObs={[U]:1,[V]:2};x.obsDTid=V;x.obsDT={[V]:G.day};G.tripWk={w0:tripWk0(G.day),L:[[s.name,'t0',x.id,'3안타','e']]};G.user=V;const n=G.mail.length;tripMigrate();ok(!G.tripWk&&G.tripWkLegacy?.L.length===1,'최근 관찰 구단을 옛 보고 작성자로 추측');ok(tripReport(tripWk0(G.day)+6)===null&&G.mail.length===n,'최근 방문 구단에 익명 보고 발송');});

function ow653Setup(n=2){fresh();makeDraftClass();const region=AREA[0].reg,base=G.scouts[0];G.scouts=Array.from({length:n},(_,i)=>({...base,id:'ow653-'+i,name:'관찰담당'+i,role:'am',region,since:G.day,trip:null}));G.amFw={};G.amPr={};G.shortlist=[];G.obsFocusPick={};return G.draftClass.map(id=>G.players[id]).filter(p=>p?.prospect&&p.team==null);}
T('[검수 11-18 #653] 집중 정원은 실제 방문 가능한 아마추어 담당자만 센다 [관심명단검수]',()=>{const E=ow653Setup(2),reg=AREA[0].reg;G.scouts[0].role='pro';G.scouts[1].role='intl';G.scouts[1].region='jp';ok(obsCap(G.user)===0,'프로 해외 직원이 집중 정원 증가 '+obsCap(G.user));const r=obsSetPri(E[0].id,2);ok(!!r&&obsPri(E[0].id)!==2,'아마추어 담당0명 신규집중허용');const tid=otherT();(G.lgStaff=G.lgStaff||{})[tid]={sc:G.scouts.map(s=>({...s})),an:[]};ok(obsCap(tid)===0,'AI 프로 해외 직원도 정원 증가');G.scouts[0].role='am';G.scouts[0].region=reg;ok(obsCap(G.user)===4,'실제AM담당1명4명정원');});
T('[검수 11-18 #654] 담당 감소는 집중을 해제하고 사용자가 계속 볼 네 명을 다시 고른다 [관심명단검수]',()=>{const E=ow653Setup(2).slice(0,8);for(const p of E)ok(obsSetPri(p.id,2)==='','처음집중8명준비');scoutFire(G.scouts[0].id);ok(obsCap(G.user)===4&&obsFocusN(G.user)<=4,'집중8/4가그대로 '+obsFocusN(G.user)+'/'+obsCap(G.user));ok(E.every(p=>obsPri(p.id)===1),'기존집중전원재선택대기아님');ok(G.obsFocusPick?.[G.user]?.ids.length===8,'집중재선택안내정보누락');for(const p of E.slice(4))ok(obsSetPri(p.id,2)==='','사용자가고른집중재설정불가');ok(obsFocusN(G.user)===4&&E.slice(4).every(p=>obsPri(p.id)===2)&&E.slice(0,4).every(p=>obsPri(p.id)===1),'원하는네명선택안됨');});
T('[검수 11-18 #655] 28일 안에 간 학교는 후보에서 빠지고 정확히28일째 다시 갈 수 있다 [관심명단검수]',()=>{ow653Setup(1);G.day=KD(7,15);const d=G.day,s=G.scouts[0],names=obsSchoolsOf(s.region);for(const t of G.teams)if(t.id!==G.user)(G.lgStaff=G.lgStaff||{})[t.id]={sc:[],an:[]};s.trip={k:'sch',from:d,to:d+6,man:true};G.obsVis={[G.user]:Object.fromEntries(names.map(n=>[n,d-7]))};const before=JSON.stringify(G.obsVis[G.user]);obsVisitWeek(d);ok(JSON.stringify(G.obsVis[G.user])===before,'지난주 학교에 재방문');G.obsVis[G.user][names[0]]=d-28;obsVisitWeek(d);ok(G.obsVis[G.user][names[0]]===d&&names.slice(1).every(n=>G.obsVis[G.user][n]===d-7),'28일 경계 또는다른학교제한불일치');});
T('[검수 11-18 #656] 아마추어 화면 관심 해제는 드래프트 보드와 실제 관찰 집합에서도 해제한다 [관심명단검수]',()=>{const p=ow653Setup(1)[0];amFollow(p.id,true);ok(amFollowing(G.user,p.id)&&G.shortlist.includes(p.id),'두목록준비');amFollow(p.id,false);ok(!amFollowing(G.user,p.id)&&!G.shortlist.includes(p.id)&&!obsFollowSet(G.user).has(p.id),'해제했는데보드관찰지속');});
T('[검수 11-18 #657] 졸업 후보를85명담아도 두 관심 목록과 관찰 집합은 같은80명이다 [관심명단검수]',()=>{const E=ow653Setup(1).slice(0,85);ok(E.length===85,'85후보준비');for(const p of E)amFollow(p.id,true);const F=amFollowL(G.user),S=new Set(G.shortlist.filter(id=>G.players[id]?.prospect)),O=obsFollowSet(G.user);ok(F.length===80&&S.size===80&&O.size===80,'관심집합정원불일치 '+F.length+'/'+S.size+'/'+O.size);ok(E.slice(0,5).every(p=>!F.includes(p.id)&&!S.has(p.id)&&!O.has(p.id)),'오래된후보가한목록에남음');});
T('[검수 11-18 #658] 정원으로 밀려난 선수의 집중 우선순위는 재등록해도 복원하지 않는다 [관심명단검수]',()=>{const E=ow653Setup(1).slice(0,81),p=E[0];obsSetPri(p.id,2);for(const x of E.slice(1))amFollow(x.id,true);ok(!obsFollowSet(G.user).has(p.id)&&G.amPr[G.user][p.id]==null,'밀려난선수관찰/집중남음');amFollow(p.id,true);ok(obsPri(p.id)===1,'재등록하자옛집중복원 '+obsPri(p.id));});
T('[검수 11-18 #664] 실제 관찰 화면 상세 선택은 분류와0회필터에 포함된 선수만 쓴다 [관심명단검수]',()=>{fresh();const ui={obsF:'dr',obsSel:1},data=[{k:'fo',id:1,n:'외국인',sub:'외국인',pri:-1,obs:null,know:10,av:{}},{k:'dr',id:2,n:'네번본후보',sub:'후보',pri:1,obs:4,last:null,conf:'보통',ev:'관찰',av:{}},{k:'dr',id:3,n:'아직안본후보',sub:'후보',pri:1,obs:0,last:null,conf:'낮음',ev:'관찰',av:{}}];const code='(function(){const UI=ui,OBS_F=[["all","전체"],["dr","후보"],["fo","외국인"]],obsRowsAll=()=>data,obsCap=()=>4,obsFocusN=()=>0,obsScN=()=>1,schSponSum=()=>({home:0,homeAll:0}),wide=()=>true,esc=String,avImg=()=>"",obsRate=()=>({cur:"-",pot:"-"}),obsDropBtn=()=>"",obsPriBtns=()=>"",obsDay=()=>"",obsDetail=x=>"DETAIL="+(x?x.k+":"+x.id:"none");'+globalThis.__obsUiSrc()+';return obsWatchPage;})()';const renderObs=eval(code);ok(renderObs().includes('DETAIL=dr:2'),'후보필터상세에이전외국인남음');ui.obsF='zero';ui.obsSel=2;ok(renderObs().includes('DETAIL=dr:3'),'0회필터상세에4회후보남음');ui.obsF='am';ok(renderObs().includes('DETAIL=none'),'빈필터에서도이전상세남음');});
T('[검수 11-18 #657 #658 호환] 예전 두 목록의 초과·중복·유령 집중을 난수 없이 한 번만 정리한다 [관심명단검수]',()=>{const E=ow653Setup(1).slice(0,85);G.amFw={[G.user]:E.slice(0,80).map(p=>p.id)};G.shortlist=E.map(p=>p.id);G.amPr={[G.user]:{[E[0].id]:2,[999999]:2}};const r=__rngState();if(typeof obsWatchFix==='function')obsWatchFix();ok(amFollowL(G.user).length===80&&obsFollowSet(G.user).size===80&&G.shortlist.length===80,'옛 초과명단미정리');ok(G.amPr[G.user][E[0].id]==null&&G.amPr[G.user][999999]==null,'옛 유령집중남음');const before=JSON.stringify([G.amFw,G.shortlist,G.amPr,G.obsFocusPick]);obsWatchFix();ok(JSON.stringify([G.amFw,G.shortlist,G.amPr,G.obsFocusPick])===before&&__rngState()===r,'관심명단복원비멱등/난수');});
T('[카페 11-18 보드정렬] 드래프트 보드 수동 순서는 3일 진행·저장/불러오기 뒤에도 그대로, 빠진 후보만 빠지고 새 후보는 끝에 [관심명단검수]',()=>{const E=ow653Setup(1).slice(0,6);for(const p of E.slice(0,4))amFollow(p.id,true);const [a,b,c,d]=E.map(p=>p.id);ok(G.shortlist.join()===[a,b,c,d].join(),'등록 순서 준비');G.shortlist=[d,b,a,c];for(let i=0;i<3;i++)processDay();ok(G.shortlist.join()===[d,b,a,c].join(),'하루 진행 뒤 보드 순서가 되돌아감 '+G.shortlist.join());const r=__rngState();G=JSON.parse(JSON.stringify(G));migrateDraft();ok(G.shortlist.join()===[d,b,a,c].join(),'불러오기 뒤 보드 순서가 되돌아감 '+G.shortlist.join());const s1=JSON.stringify([G.shortlist,G.amFw]);obsWatchFix();ok(JSON.stringify([G.shortlist,G.amFw])===s1&&__rngState()===r,'보드 정리 비멱등/난수');amFollow(b,false);ok(G.shortlist.join()===[d,a,c].join(),'뺀 후보 뒤 순서 섞임 '+G.shortlist.join());amFollow(E[4].id,true);ok(G.shortlist.join()===[d,a,c,E[4].id].join(),'새 후보가 끝에 붙지 않음 '+G.shortlist.join());const t=otherT();G.amFw[t]=[a,c];(G.dClub=G.dClub||{})[t]={shortlist:[c,a]};obsWatchFix();ok(G.dClub[t].shortlist.join()===[c,a].join(),'보관된 구단 보드도 같은 규칙 아님');});
T('[검수 11-18 #653 #654] 배치 변경 직후에도 집중은 정원을 지키고 AI도 같은 정원을 쓴다 [관심명단검수]',()=>{const E=ow653Setup(2).slice(0,8);for(const p of E)obsSetPri(p.id,2);assignScout(G.scouts[0].id,'pro',AREA[0].reg);ok(obsCap(G.user)===4&&obsFocusN(G.user)===0&&G.obsFocusPick?.[G.user]?.ids.length===8,'배치 변경 집중 재선택 누락');const tid=otherT();G.lgStaff[tid]={sc:[{...G.scouts[1]}],an:[]};G.amFw[tid]=E.map(p=>p.id);G.amPr[tid]=Object.fromEntries(E.map(p=>[p.id,2]));const before=JSON.stringify(G),rng=__rngState();ok(obsFocusN(tid)===4&&E.filter(p=>obsPri(p.id,tid)===2).length===4,'AI 정원 초과 집중');ok(JSON.stringify(G)===before&&__rngState()===rng,'정원 조회가 상태나 난수 변경');obsFocusFix(tid);ok(Object.values(G.amPr[tid]).filter(v=>v===2).length===4,'AI 실제 우선순위 미정리');});
T('[검수 11-18 #656 #657] 관심 통합은 현역 관심 선수를 보존하고 후보 재선택은 보통으로 시작한다 [관심명단검수]',()=>{const E=ow653Setup(1),pro=domestic(otherT())[0];G.shortlist=[pro.id];amFollow(E[0].id,true);obsSetPri(E[0].id,2);amFollow(E[0].id,false);amFollow(E[0].id,true);ok(G.shortlist.includes(pro.id)&&G.shortlist.includes(E[0].id)&&obsPri(E[0].id)===1,'현역 관심 삭제 또는 재선택 집중 복원');const s=JSON.stringify(G),rng=__rngState();obsFollowSet(G.user);obsFocusN(G.user);obsFocusPending(G.user);ok(JSON.stringify(G)===s&&__rngState()===rng,'관심 조회가 상태나 난수 변경');});

function oe659_setup(){fresh();makeDraftClass();const p=G.players[G.draftClass.find(id=>G.players[id]?.prospect)],a=AREA.find(a=>a.reg==='수도권');p.area=a.k;p.region=a.reg;p.school=a.hs[0];delete p.amObs;delete p.obsBy;delete p.obsView;delete p.gmObs;delete p.gmSeen;const s=(id,skill,name)=>({id,skill,name,role:'am',region:a.reg,since:G.day-100,loy:50});G.scouts=[s('oeA',1,'실제관찰자'),s('oeB',5,'미방문담당자')];for(const t of G.teams)if(t.id!==G.user)(G.lgStaff=G.lgStaff||{})[t.id]={sc:[],an:[]};G.shortlist=[];amFollowL(G.user).length=0;return {p,a,s};}
function oe659_game(p,s){const d=amTourSpan(G.year,AM_TOURS().find(t=>t.k==='t0'))[0];G.day=d;s.trip={k:'t0',from:d,to:d+6};_amToday={g:G,d,L:[{id:p.id,kind:'p',sch:p.school,b:'4타수 1안타',ev:'t0',gk:'테스트-A'}]};tripWatchDaily(d);}
T('[검수 11-18 #659] 부분 관찰은 오늘 관찰과 같은 0.35회로 표시하고 관찰 전이라 하지 않는다 [관찰평가검수]',()=>{const {p}=oe659_setup();obsAdd(p,G.user,.35);ok(Math.abs(obsCount(p)-.35)<1e-9,'부분 관찰이 '+obsCount(p)+'회로 반올림');ok(!amObsTxt(p).includes('관찰 전')&&amObsTxt(p).includes('0.35회'),'오늘 부분 관찰을 관찰 전으로 표시');});
T('[검수 11-18 #660] 경기장에 실제 간 직원의 관찰로 평가를 열고 미방문 고능력 직원에게 귀속하지 않는다 [관찰평가검수]',()=>{const {p}=oe659_setup(),A=G.scouts[0];oe659_game(p,A);const r=scoutReport(p);ok(r.sc?.id===A.id&&r.who.includes(A.name),'실제관찰 대신 미방문 직원 평가 '+r.who);ok(r.ofp!=null,'실제 부분 관찰 뒤에도 평가가 잠김');});
T('[검수 11-18 #661] 새 직원 배치만으로 두 실제 관찰자의 저장된 의견은 바뀌지 않는다 [관찰평가검수]',()=>{const {p,s,a}=oe659_setup();G.scouts=[s('oeA',1,'관찰A'),s('oeB',2,'관찰B')];const P=G.draftClass.slice(0,16).map(id=>G.players[id]).filter(p=>p?.prospect);for(let i=0;i<P.length;i++){const q=P[i];q.region=a.reg;q.area=a.k;q.pot=44+i*1.5;q.amObs={};delete q.obsBy;delete q.obsView;for(const sc of G.scouts){obsAdd(q,G.user,1);obsByAdd(q,G.user,sc.id);}}const before=P.map(q=>obsOpinions(q).map(v=>v.t));G.scouts.push(s('oeC',5,'새관찰C'));const after=P.map(q=>obsOpinions(q).map(v=>v.t));ok(JSON.stringify(after)===JSON.stringify(before),'관찰하지 않은 C 배치가 A B 과거 의견을 변경');});
T('[검수 11-18 #662] 다른 권역 직원도 전국대회에서 실제 본 후보의 잠재력을 평가한다 [관찰평가검수]',()=>{const {p}=oe659_setup(),A=G.scouts[0];G.scouts=[A];A.region='영남';amFollow(p.id,true);oe659_game(p,A);ok(obsRaw(p,G.user)>=1,'전국대회 실제 관찰 준비');const r=scoutReport(p);ok(r.ofp!=null&&r.sc?.id===A.id,'실제 전국대회 관찰을 담당 없음으로 잠금 '+r.who);});
T('[검수 11-18 #663] 같은 관찰량의 저학년도 두 실제 의견이 있으면 평가 오차가 줄어든다 [관찰평가검수]',()=>{const {a,s}=oe659_setup();G.scouts=[s('oeA',1,'관찰A'),s('oeB',1,'관찰B')];const e={id:9663,n:'저학년검증',a:a.k,s:a.hs[0],c:false,P:false,pos:'SS',gy:G.year+2,pot:55,r:{con:35,pow:35,eye:35,spd:35,def:35},amObs:{[G.user]:4}};obsByAdd(e,G.user,G.scouts[0].id);const first=amEstU(e,G.user).sd;obsByAdd(e,G.user,G.scouts[1].id);ok(obsOpinions(e)?.length===2,'저학년 두 의견 준비');const next=amEstU(e,G.user).sd;ok(Math.abs(next/first-TRIP_TWO)<1e-9,'두 실제 의견의 오차 감소 누락 '+first+' → '+next);});
T('[검수 11-18 #665] 공식 아마 기록이 없는 선수와 표본에는 기록 백분위를 붙이지 않는다 [관찰평가검수]',()=>{const {p}=oe659_setup();const F=eval(globalThis.__sc659CompareSrc());for(const id of G.draftClass){const q=G.players[id];if(!q)continue;delete q.am;q.amY=[];q.amSim=1;}const a=F.obsRecVsEval({k:'dr',x:p});ok(!a.includes('기록 상위'),'기록이 없는 27명 표본에 백분위 '+a);const peers=G.draftClass.map(id=>G.players[id]).filter(q=>q?.prospect&&!!q.isP===!!p.isP&&!!q.college===!!p.college);for(const q of peers.slice(1,16))q.am=q.isP?{outs:90,er:10,so:30}:{pa:100,ab:90,h:30,bb:10};const b=F.obsRecVsEval({k:'dr',x:p});ok(!b.includes('기록 상위'),'본인 기록 없이 타인의 기록 백분위를 표시 '+b);});
T('[검수 11-18 #661] 관찰자 의견은 저장 재독·스카우트 퇴사 뒤에도 같고 구버전 복원은 멱등·난수 불변이다 [관찰평가검수]',()=>{const {p}=oe659_setup();for(const s of G.scouts){obsAdd(p,G.user,1);obsByAdd(p,G.user,s.id,s);}const old=JSON.stringify(obsOpinions(p));G=JSON.parse(JSON.stringify(G));const q=G.players[p.id];G.scouts=[];ok(JSON.stringify(obsOpinions(q))===old,'퇴사 후 실제 관찰 의견 유실');const st=globalThis.__rngState(),sv=JSON.stringify(G);ok(obsViewMigrate()===0&&obsViewMigrate()===0,'신형 자료를 다시 복원');ok(globalThis.__rngState()===st&&JSON.stringify(G)===sv,'자료 조회가 상태 또는 난수 변경');const A={id:'oeLegacyA',name:'옛관찰A',skill:2,role:'am',region:q.region},B={id:'oeLegacyB',name:'옛관찰B',skill:3,role:'am',region:q.region};G.scouts=[A,B];q.obsBy={[G.user]:[A.id,B.id]};delete q.obsView;ok(obsViewMigrate()===2,'구형 실제 관찰자 복원 누락');const a=JSON.stringify(q.obsView);ok(obsViewMigrate()===0&&JSON.stringify(q.obsView)===a,'두 번째 복원이 값 변경');});
T('[검수 11-18 #665] 저학년 무기록은 백분위를 숨기고 유효 공식 기록 표본은 비교를 계속한다 [관찰평가검수]',()=>{const {p}=oe659_setup(),F=eval(globalThis.__sc659CompareSrc()),E=Object.values(amPipe().L).filter(e=>!e.P&&!e.c&&amGrade(e,G.year)===1).slice(0,12);ok(E.length>=8,'저학년 비교군 준비');const yy=G.year-1;for(const e of E)e.y=[];ok(!F.obsRecVsEval({k:'am',x:E[0]}).includes('기록 상위'),'저학년 무기록 백분위');for(const q of G.draftClass.map(id=>G.players[id]).filter(q=>q?.prospect&&!!q.isP===!!p.isP&&!!q.college===!!p.college)){q.amSim=0;q.am=q.isP?{outs:90,er:10,so:30,bb:10,ha:20,hr:1}:{pa:100,ab:90,h:30,bb:10,hbp:0,sf:0,d:5,tr:1,hr:2};}const s=F.obsRecVsEval({k:'dr',x:p});ok(s.includes('기록 상위')&&s.includes('우리 평가 상위'),'유효 공식 기록 비교가 숨겨짐 '+s);p.am=p.isP?{outs:90,er:10}:{pa:100,ab:90,h:30};ok(!F.obsRecVsEval({k:'dr',x:p}).includes('기록 상위'),'불완전한 본인 기록에 백분위');});
T('[검수 11-18 #660~663] 저학년 졸업 뒤에도 실제 관찰자를 유지하고 조회·복원은 게임 난수를 쓰지 않는다 [관찰평가검수]',()=>{const {a}=oe659_setup(),e=Object.values(amPipe().L).find(e=>!e.P&&!e.c);e.a=a.k;for(const s of G.scouts){obsAdd(e,G.user,1);obsByAdd(e,G.user,s.id,s);}const view=JSON.stringify(e.obsBy),p=amMat(e);ok(JSON.stringify(p.obsBy)===view&&obsScoutFor(p)?.id===obsScoutFor(e)?.id&&obsOpinions(p)?.map(v=>v.s.id).join()===obsOpinions(e)?.map(v=>v.s.id).join(),'졸업으로 실제 관찰자 변경');p.obsBy[G.user].splice(0,1,'독립 복사 확인');ok(JSON.stringify(e.obsBy)===view,'졸업 선수가 원본 관찰 기록까지 변경');const old=FO_RNG;let n=0;try{FO_RNG=()=>{n++;return .5;};obsOpinions(p);scoutReport(p);amEstU(e,G.user);obsViewMigrate();obsViewMigrate();}finally{FO_RNG=old;}ok(n===0,'관찰 조회·복원 게임 난수 소비 '+n);});

function sc666Setup(cur=52,pot=75,isP=false){fresh();const p=domestic(G.user).find(p=>p.isP===isP&&!p.foreign&&!p.prospect);p.hist=[];p.age=21;p.pot=pot;p.hidT=0;p.svc=0;p.joinY=G.year;for(const k in p.r)if(typeof p.r[k]==='number')p.r[k]=cur;p.draft={y:G.year-1,tid:G.user,rd:1,no:1};p.acq={k:'draft',tid:G.user,y:G.year-1,d:G.day-100,ep:75};p.dEst={ofp:75,sd:4,who:'지명 담당',tid:G.user,y:G.year-1,d:G.day-100};return p;}
T('[검수 11-18 #666] 잠재력 미확인 지명은 입단만으로 확정 역할을 만들지 않는다 [국내평가검수]',()=>{const p=sc666Setup();p.dEst.ofp=null;p.dEst.sd=99;delete p.acq.ep;const r=scoutReport(p);ok(r.cur!=null&&r.ofp==null&&r.role==null&&r.sd===99,'미확인 잠재력을 현재 능력으로 복사 '+JSON.stringify({cur:r.cur,ofp:r.ofp,role:r.role,sd:r.sd}));});
T('[검수 11-18 #667] 퓨처스 한 타석은 지명 당시 평가를 한 시즌 관찰로 교체하지 않는다 [국내평가검수]',()=>{const p=sc666Setup(35,35),before=scoutReport(p);ok(before.ofp===75,'지명 평가 준비');p.hist=[{...ZB,y:G.year,lvl:'퓨처스',t:G.user,pa:1,ab:1}];const after=scoutReport(p);ok(after.ofp===75&&ownObs(p)===0&&!after.who.includes('1시즌 관찰'),'한 타석으로 잠재력 평가 교체 '+after.ofp+' '+after.who);p.hist[0].pa=100;p.hist[0].ab=90;ok(ownObs(p)===1&&scoutReport(p).ofp<75,'충분한 기록 뒤에도 지명 평가를 계속 고정');});
T('[검수 11-18 #668] 31세의 현재 잠재력 상한은 오래된 지명 평가보다 우선한다 [국내평가검수]',()=>{const p=sc666Setup(52,52);p.age=31;const r=scoutReport(p);ok(r.cur===52&&r.ofp===52&&r.role!=='리그 최정상급','옛 지명75가 성장 종료 상한 덮음 '+r.ofp+' '+r.role);});
T('[검수 11-18 #669] 떠난 우리 선수 자료는 떠날 때 평가에 고정되고 실제 능력 변화가 새지 않는다 [국내평가검수]',()=>{const p=sc666Setup(35,45),old=G.user,next=G.teams.find(t=>t.id!==old).id;delete p.dEst;p.acq=null;G.scouts=[];const before=scoutReport(p);mvLog('보상선수',p,old,next,'');p.team=next;G.day+=14;const first=scoutReport(p);for(const k in p.r)if(typeof p.r[k]==='number')p.r[k]=40;p.pot=70;const j=JSON.stringify(G),rng=__rngState(),r=scoutReport(p);ok(r.who.includes('우리 팀 시절')&&r.cur===first.cur&&r.ofp===first.ofp&&JSON.stringify(r.tools)===JSON.stringify(first.tools),'옛 자료 아래 현재 숨은 능력 노출 '+first.cur+'/'+first.ofp+' → '+r.cur+'/'+r.ofp);ok(r.cur===before.cur&&r.ofp===before.ofp,'떠날 당시 자료와 불일치');ok(JSON.stringify(G)===j&&__rngState()===rng,'보관 평가 조회 부작용');});
T('[검수 11-18 #670] 같은 시즌 12타석 공개 여부는 구단별 6타석씩 나뉘어도 같다 [국내평가검수]',()=>{const p=sc666Setup(40,60),A=G.teams.find(t=>t.id!==G.user).id,B=G.teams.find(t=>t.id!==G.user&&t.id!==A).id;p.team=B;p.acq=null;delete p.dEst;G.scouts=[];p.hist=[{...ZB,y:G.year,lvl:'1군',t:A,pa:12,ab:12,h:3}];const single=scoutReport(p);ok(single.cur!=null&&!single.unseen,'한 팀12타석 준비');p.hist=[{...ZB,y:G.year,lvl:'1군',t:A,pa:6,ab:6,h:2},{...ZB,y:G.year,lvl:'1군',t:B,pa:6,ab:6,h:1}];const split=scoutReport(p);ok(publicP(p)&&split.cur===single.cur&&!split.unseen,'구단 분할 때문에 공개 기록이 미확인으로 바뀜');});
T('[검수 11-18 #671] 평가 가능한 타 구단 선수도 같은 근거로 위험도를 표시한다 [국내평가검수]',()=>{const p=sc666Setup(46,80),tid=G.teams.find(t=>t.id!==G.user).id;p.team=tid;p.acq=null;delete p.dEst;p.inj=.3;const s=mkScout(5);s.role='pro';s.region=teamScoutReg(tid);s.since=G.day-100;G.scouts=[s];const other=scoutReport(p);ok(other.cur===46&&other.ofp>=70,'상대 현재 잠재력 평가 준비 '+other.cur+'/'+other.ofp);p.team=G.user;const mine=scoutReport(p);ok(other.risk===mine.risk&&other.risk==='높음','상대 위험만 판단 불가 '+other.risk+' / '+mine.risk);});
T('[검수 11-18 #672] 기록 담당자 없는 선수가 FA가 되어도 현재 능력을 새로 공개하지 않는다 [국내평가검수]',()=>{const p=sc666Setup(35,60),tid=G.teams.find(t=>t.id!==G.user).id;p.team=tid;p.acq=null;p.tLog=[];delete p.dEst;G.scouts=[];const before=scoutReport(p);ok(before.unseen&&before.cur==null,'상대 구단 미확인 준비');p.team=null;p.faFrom=tid;const r=scoutReport(p);ok(r.unseen&&r.cur==null&&r.ofp==null&&r.tools.length===0,'무소속 전환만으로 현재 능력 공개 '+r.cur);});
T('[검수 11-18 #666] 실제 지명 저장에 평가가 빠져 있어도 미확인을 복원하고 재실행은 순수하다 [국내평가검수]',()=>{const p=sc666Setup();delete p.dEst;delete p.acq.ep;const a=scoutReport(p);ok(a.ofp==null&&a.role==null,'지명 평가 미저장 경로에서 잠재력 생성');domesticScoutMigrate();ok(p.dEst&&p.dEst.ofp==null&&p.dEst.sd===99,'미확인 지명 메타 복원 실패');const s=JSON.stringify(G),rng=__rngState();domesticScoutMigrate();ok(JSON.stringify(G)===s&&__rngState()===rng,'복원 반복/RNG 변경');});
T('[검수 11-18 #667] 관찰 시즌은 구단 내 타석 아웃 합계의 충분한 표본만 센다 [국내평가검수]',()=>{const p=sc666Setup();p.hist=[{...ZB,y:G.year,lvl:'1군',t:G.user,pa:50},{...ZB,y:G.year,lvl:'퓨처스',t:G.user,pa:49}];ok(ownObs(p)===0,'99타석을 충분한 시즌 처리');p.hist[1].pa=50;ok(ownObs(p)===1,'구단 내 분할100타석 누락');p.isP=true;p.hist=[{...ZB,y:G.year,lvl:'1군',t:G.user,outs:45},{...ZB,y:G.year,lvl:'퓨처스',t:G.user,outs:44}];ok(ownObs(p)===0,'89아웃을 충분한 시즌 처리');p.hist[1].outs=45;ok(ownObs(p)===1,'구단 내 분할90아웃 누락');});
T('[검수 11-18 #668] 29세와 30세의 옛 지명 평가는 현재 성장 상한을 넘지 않는다 [국내평가검수]',()=>{const p=sc666Setup(52,75);p.age=29;ok(scoutReport(p).ofp<=56,'29세 상한 무시');p.age=30;ok(scoutReport(p).ofp<=54,'30세 상한 무시');});
T('[검수 11-18 #669] 소속을 먼저 바꾸는 이동도 출발 구단 평가를 보관하며 새 관찰 없는 옛 저장은 숨은 자료를 만들지 않는다 [국내평가검수]',()=>{const p=sc666Setup(35,45),from=G.user,to=G.teams.find(t=>t.id!==from).id;delete p.dEst;p.acq=null;G.scouts=[];const before=scoutReport(p),rng=__rngState();p.team=to;scoutDeparture(p,from,to);ok(p.team===to&&__rngState()===rng,'보관이 소속/RNG를 변경');p.tLog=[{f:from,t:to,d:G.day,y:G.year}];const r=scoutReport(p);ok(r.cur===before.cur&&r.ofp===before.ofp,'현재 소속 때문에 떠날 때 자료가 달라짐');const save=JSON.parse(JSON.stringify(p.proScoutPast));p.proScoutPast=save;for(const k in p.r)if(typeof p.r[k]==='number')p.r[k]=75;p.pot=80;G.day+=20;ok(scoutReport(p).cur===before.cur,'로드 뒤 옛 평가가 현재 값을 읽음');delete p.proScoutPast;const j=JSON.stringify(p),legacy=scoutReport(p);ok(legacy.unseen&&legacy.cur==null&&!legacy.who.includes('우리 팀 시절 자료')&&JSON.stringify(p)===j,'옛 이적 로그만으로 과거 숨은 자료 복원');});
T('[검수 11-18 #670] 공개 투구 표본은 같은 시즌 구단별 아웃을 합치고 서로 다른 시즌은 합치지 않는다 [국내평가검수]',()=>{const p=sc666Setup(40,60,true),A=G.teams.find(t=>t.id!==G.user).id,B=G.teams.find(t=>t.id!==G.user&&t.id!==A).id;p.hist=[{...ZB,y:G.year,lvl:'1군',t:A,outs:4},{...ZB,y:G.year,lvl:'1군',t:B,outs:5}];ok(publicP(p),'분할9아웃 누락');p.hist[1].y--;ok(!publicP(p),'서로 다른 시즌을 합산');});
T('[검수 11-18 #672] 미확인 FA도 지역 담당자의 충분한 평가나 공개 기록이 생기면 보인다 [국내평가검수]',()=>{const p=sc666Setup(35,60),tid=G.teams.find(t=>t.id!==G.user).id;p.team=null;p.faFrom=tid;p.tLog=[];p.acq=null;delete p.dEst;const sc=mkScout(5);sc.role='pro';sc.region=teamScoutReg(tid);sc.since=G.day-100;G.scouts=[sc];ok(scoutReport(p).cur===35&&!scoutReport(p).unseen,'자격 있는 담당자의 FA 평가도 가림');G.scouts=[];p.hist=[{...ZB,y:G.year,lvl:'1군',t:tid,pa:12}];ok(scoutReport(p).cur===35&&!scoutReport(p).unseen,'공개 기록의 FA 현재 능력도 가림');});

const fw673_setup=()=>{fresh();G.day=G.cal.open+7;const p=newForeign('용병',{market:true,isP:false,reg:'jp'});p.team=null;p.orig='jp';p.age=28;G.fmarket=[];G.fwatch=[{id:p.id,since:G.day-7,k:10,dk:8}];G.fwNo=[];G.intl={us:0,la:0,jp:0,tw:0,au:0};G.scouts=[{id:'fw-low',name:'일본하위담당',skill:1,role:'intl',region:'jp',since:G.day-90},{id:'fw-high',name:'일본상위담당',skill:5,role:'intl',region:'jp',since:G.day-90}];return p;};
T('[검수 11-18 #673] 같은 나라 두 스카우트는 명단 순서와 무관하게 최고 담당자로 평가한다 [해외관찰검수]',()=>{const p=fw673_setup(),id=p.id,base=JSON.stringify(G),read=()=>{const q=G.players[id],I=fInfo(G.user,q),rp=scoutReport(q),f=fScout(q,rp);return {k:G.fwatch[0].k,person:I.isc?.id,toolPerson:I.isc0?.id,who:rp.who,why:f.why,sd:rp.sd,raw:f.raw,ms:f.ms};};fwatchWeek();const a=read();G=JSON.parse(base);G.scouts.reverse();fwatchWeek();const b=read();ok(JSON.stringify(a)===JSON.stringify(b),'순서가 파악도·평가자·오차를 바꿈 '+JSON.stringify([a,b]));ok(a.k===26&&a.person==='fw-high'&&a.toolPerson==='fw-high'&&a.who.includes('일본상위담당')&&a.why.some(x=>x.includes('일본상위담당')),'최고 담당자로 진행/표시를 통일하지 않음');const r=__rngState(),s=JSON.stringify(G.scouts);read();ok(__rngState()===r&&JSON.stringify(G.scouts)===s,'담당자 조회가 난수 또는 직원 순서를 변경');});
T('[검수 11-18 #673 동률] 같은 실력 담당자도 고유 직원 기준으로 순서 없이 일관되게 고른다 [해외관찰검수]',()=>{const p=fw673_setup();G.scouts[0].skill=5;G.scouts[0].id='fw-a';G.scouts[1].id='fw-z';const a=fInfo(G.user,p);G.scouts.reverse();const b=fInfo(G.user,p);ok(a.isc?.id===b.isc?.id&&a.isc0?.id===b.isc0?.id&&a.isc?.id===a.isc0?.id,'동률 직원 선택이 순서에 의존');});
T('[검수 11-18 #674] 파견자와 해외망을 바꾼 직후 완료 예상은 현재 주간 증가량을 쓴다 [해외관찰검수]',()=>{const p=fw673_setup(),w=G.fwatch[0];w.k=56;w.dk=16;G.scouts=[G.scouts[1]];ok(fwatchEta(w)===3,'파견자 있는 상태 준비');G.scouts=[];const r=__rngState(),s=JSON.stringify([G.fwatch,G.intl]);ok(fwatchEta(w)===15,'파견자를 빼도 이전 16% 증가량을 사용');G.intl.jp=3;ok(fwatchEta(w)===4,'현재 해외망 투자를 반영하지 않음');G.intl.jp=0;ok(w.k===56&&w.dk===16&&JSON.stringify([G.fwatch,G.intl])===s&&__rngState()===r,'예상 조회가 이전 보고·파악도·난수를 바꿈');});
T('[검수 11-18 #674 호환] 옛 보고에 주간 증가량이 없어도 현재 배치로 남은 기간을 계산한다 [해외관찰검수]',()=>{const p=fw673_setup(),w=G.fwatch[0];delete w.dk;ok(fwatchEta(w)===6,'주간 증가량 없는 옛 관찰의 예상 기간 누락');G.scouts=[];ok(fwatchEta(w)===30,'파견자 없는 현재 증가량 미반영');w.k=100;ok(fwatchEta(w)===0,'완료된 관찰의 예상 기간');});
T('[검수 11-18 #675] 직접 해제는 등록 경로와 무관하게 자동 재등록을 막고 수동 재개는 허용한다 [해외관찰검수]',()=>{for(const auto of [false,true]){const p=fw673_setup(),w=G.fwatch[0];w.auto=auto;G.fmarket=[p.id];const fn=fNeed,mw=mgrWantForeign,kn=fKnows;fNeed=()=>({kind:'용병',isP:false});mgrWantForeign=()=>null;fKnows=()=>true;try{fwatchToggle(p.id);ok(!fwatchOn(p.id)&&(G.fwNo||[]).includes(p.id),'직접 해제한 후보 자동 제외 누락 '+auto);const rng=FO_RNG;FO_RNG=()=>.99;try{fwatchWeek();}finally{FO_RNG=rng;}ok(!fwatchOn(p.id),'다음 주 자동 관찰이 직접 해제한 후보를 복원 '+auto);fwatchToggle(p.id);ok(fwatchOn(p.id)&&!(G.fwNo||[]).includes(p.id),'직접 다시 담은 후보의 자동 제외가 남음');p.team=otherT();const r=FO_RNG;FO_RNG=()=>.99;try{fwatchWeek();}finally{FO_RNG=r;}ok(!fwatchOn(p.id)&&!(G.fwNo||[]).includes(p.id),'계약 완료 자동 정리가 사용자 제외로 저장');}finally{fNeed=fn;mgrWantForeign=mw;fKnows=kn;}}});

T('[검수 11-18 #646·647 구형 버튼] 같은 주에 새 안이 생겨도 구단·안 번호 없는 옛 메일은 새 직원 계획을 승인하지 않는다 [출장검수]',()=>{const {s}=tr644_setup();const w0=tripWk0(G.day);G.tripPend={w0,P:{[s.id]:'camp'}};tripMigrate();G.scouts=[{...s,id:'교체후임644'}];tripWeekly(G.day);const key=tripPendKey(G.tripPend),before=JSON.stringify(G.scouts[0].trip),T0=G.tripPend,r=__rngState();for(const k of [String(w0),':'+w0+':',G.user+':'+w0+':'])ok(tripPlanGo(k)!=='팀장 출장 안대로 보냈습니다.','식별자 없는 옛 메일로 같은 주 새 안을 승인');ok(G.tripPend===T0&&JSON.stringify(G.scouts[0].trip)===before&&__rngState()===r,'구형 메일이 새 안 또는 배정을 변경');ok(tripPlanGo(key)==='팀장 출장 안대로 보냈습니다.','구단·번호를 가진 현재 안은 승인 가능');});

function sl644Twice(check){G=JSON.parse(JSON.stringify(G));migrateDraft();const first=JSON.stringify(check());G=JSON.parse(JSON.stringify(G));migrateDraft();ok(JSON.stringify(check())===first,'스카우트 저장 복원 두 번째 실행이 첫 결과를 변경');}
T('[검수 11-18 #651 #659 통합 로드] 구단별 옛 보고 복원 뒤 담당자 의견 날짜를 연결하고 불명확한 보고는 공개하지 않는다 [스카우트로드검수]',()=>{fresh();makeDraftClass();const [p,q]=G.draftClass.map(id=>G.players[id]).filter(p=>p?.prospect&&p.team==null),u=G.user,a=G.teams.find(t=>t.id!==u).id,d=G.day-17,sc={...G.scouts[0],id:'sl644-old-observer',name:'옛구단 관찰자',role:'am',region:p.region};G.lgStaff=G.lgStaff||{};G.lgStaff[a]={...(G.lgStaff[a]||{}),sc:[sc]};for(const x of [p,q]){x.amObs={[u]:1,[a]:2};delete x.obsD;delete x.obsDT;delete x.obsDTid;delete x.obsView;}p.obsBy={[a]:[sc.id]};q.obsBy={};delete G.obsLogV;delete G.obsLogT;delete G.obsLogTid;delete G.obsLogUnknown;G.obsLog={[p.id]:[[d,sc.name,'옛 구단 관찰',1,a,sc.id]],[q.id]:[[d-1,'구단 미상','불명확한 옛 관찰',2]]};G.tripWk={tid:a,w0:tripWk0(G.day),L:[[sc.name,'sch',p.id,'1홈런','p',sc.id,a]]};delete G.tripWkT;sl644Twice(()=>{const P=G.players[p.id],Q=G.players[q.id],v=obsViewRows(P,a).find(r=>String(r.s.id)===sc.id);ok(obsLogList(P,u).length===0&&obsLast(P,u)==null&&obsLogList(P,a).length===1,'옛 구단 보고/날짜가 현 구단으로 노출');ok(v&&G.obsSc?.[sc.id]?.name===sc.name&&v.d===d&&v.y===dobj(d).y&&!obsViewRows(P,u).length,'구단별 보고 날짜보다 먼저 담당 의견을 복원 '+JSON.stringify(v));ok(obsLogList(Q,u).length===0&&obsLogList(Q,a).length===0&&G.obsLogUnknown?.[q.id]?.length===1,'귀속 불명 보고를 현 구단에 배분');ok(!G.tripWk&&G.tripWkT?.[a]?.L.length===1,'옛 구단 출장 주간 보고를 현재 구단에 노출');return [G.obsLogT,G.obsLogUnknown,P.obsDT,v,Q.obsDT,G.tripWkT];});});
T('[검수 11-18 #666 통합 로드] 실제 로더가 미확인 지명 평가를 복원해도 잠재력을 새로 만들거나 난수를 더 쓰지 않는다 [스카우트로드검수]',()=>{fresh();const p=domestic(G.user).find(p=>!p.foreign&&!p.prospect&&!p.isP);p.hist=[];p.age=21;p.draft={y:G.year-1,tid:G.user,rd:1,no:1};p.acq={k:'draft',tid:G.user,y:G.year-1,d:G.day-50};delete p.dEst;const saved=JSON.stringify(G),funcs=[obsLogMigrate,tripMigrate,obsViewMigrate,obsWatchFix,domesticScoutMigrate],seed=644666;let baseline;try{obsLogMigrate=()=>{};tripMigrate=()=>{};obsViewMigrate=()=>{};obsWatchFix=()=>{};domesticScoutMigrate=()=>{};G=JSON.parse(saved);__seed(seed);migrateDraft();baseline=__rngState();}finally{[obsLogMigrate,tripMigrate,obsViewMigrate,obsWatchFix,domesticScoutMigrate]=funcs;}G=JSON.parse(saved);__seed(seed);migrateDraft();ok(__rngState()===baseline,'새 스카우트 로드 훅이 기존 로더보다 난수를 추가 소비');const check=()=>{const P=G.players[p.id],r=scoutReport(P);ok(P.dEst&&P.dEst.ofp==null&&P.dEst.sd===99&&r.ofp==null&&r.role==null,'실제 로드에서 미확인 잠재력/역할 생성 '+JSON.stringify([P.dEst,r.ofp,r.role]));return [P.dEst,r.ofp,r.role,r.sd];};check();sl644Twice(check);const rng=__rngState();obsLogMigrate();tripMigrate();obsViewMigrate();obsWatchFix();domesticScoutMigrate();ok(__rngState()===rng,'로드 훅만 재실행해도 난수 소비');});
T('[검수 11-18 #654 통합 로드] 정원을 초과한 옛 집중 관찰은 실제 불러오기에서 재선택 대기로 보관한다 [스카우트로드검수]',()=>{fresh();makeDraftClass();const ids=G.draftClass.map(id=>G.players[id]).filter(p=>p?.prospect&&p.team==null).slice(0,8).map(p=>p.id),u=G.user;G.scouts=[{...G.scouts[0],id:'sl644-single-am',role:'am',region:AREA[0].reg,since:G.day,trip:null}];G.amFw={[u]:ids.slice()};G.shortlist=ids.slice();G.amPr={[u]:Object.fromEntries(ids.map(id=>[id,2]))};delete G.obsFocusPick;sl644Twice(()=>{ok(obsCap(u)===4&&obsFocusN(u)===0,'복원 뒤 집중 인원이 정원 초과 또는 자동 선택됨');ok(ids.every(id=>obsPri(id,u)===1),'기존 8명 중 일부를 임의 집중 유지');const pick=G.obsFocusPick?.[u];ok(pick&&pick.cap===4&&pick.ids.length===8&&ids.every(id=>pick.ids.includes(id)),'실제 로더가 원래8명 재선택 대기를 보관하지 않음');return [G.amFw,G.shortlist,G.amPr,G.obsFocusPick];});});

T('[검수 11-18 스카우트 독립교차] 같은 주 재발행된 안과 다른 구단 안의 옛 버튼은 현재 안과 배정을 그대로 보존한다',()=>{tr644_setup();tripWeekly(G.day);const old=tripPendKey(G.tripPend);tripWeekly(G.day);const current=tripPendKey(G.tripPend);ok(old!==current,'재발행 안 번호');const before=JSON.stringify(G),r=__rngState();ok(tripPlanGo(old)!=='팀장 출장 안대로 보냈습니다.','동일 주 옛 버튼으로 새 안 승인');ok(JSON.stringify(G)===before&&__rngState()===r,'거부된 옛 승인 부작용');const T=G.tripPend;T.tid=otherT();const s=JSON.stringify(G);ok(tripPlanGo(current)!=='팀장 출장 안대로 보냈습니다.'&&JSON.stringify(G)===s,'다른 구단 안 승인');});
T('[검수 11-18 스카우트 독립교차] 양 구단 기록을 저장 재독하고 이동해도 명시적인 소유 구단 보고와 날짜만 보인다',()=>{const {U,V,s}=tr644_setup(),x=Object.values(amPipe().L)[0],d=G.day;obsAdd(x,U,1);obsLogGame(x,{b:'구단A'},s.region,d,s,'전국');G.user=V;G.day++;obsAdd(x,V,1);obsLogGame(x,{b:'구단B'},s.region,G.day,s,'전국');G=JSON.parse(JSON.stringify(G));obsLogMigrate();tripMigrate();obsViewMigrate();const q=amPipe().L[x.id];for(const tid of [U,V,U,V]){G.user=tid;const before=JSON.stringify(G),rng=__rngState(),L=obsLogList(q);ok(L.length===1&&L[0][4]===tid&&obsLast(q)===d+(tid===V?1:0),'명시적 구단 이력 교차 노출');ok(JSON.stringify(G)===before&&__rngState()===rng,'소속별 이력 조회 부작용');}});
T('[검수 11-18 스카우트 독립교차] 타 권역 전국대회 관찰자는 퇴사와 저장 재독 뒤에도 그 개인이고 타 구단에는 전해지지 않는다',()=>{const {p}=oe659_setup(),U=G.user,V=otherT(),s=G.scouts[0];G.scouts=[s];s.region='영남';amFollow(p.id,true);oe659_game(p,s);const before=scoutReport(p);ok(before.ofp!=null&&before.sc.id===s.id,'실제 관찰 실패');G=JSON.parse(JSON.stringify(G));G.scouts=[];const q=G.players[p.id],rng=__rngState(),state=JSON.stringify(G),own=scoutReport(q);ok(own.ofp!=null&&own.sc.id===s.id,'퇴사 뒤 관찰자 변경');ok(JSON.stringify(G)===state&&__rngState()===rng,'퇴사 뒤 조회 부작용');G.user=V;G.scouts=[];const other=scoutReport(q);ok(other.ofp==null&&obsCount(q,V)===0&&obsScoutFor(q,V)===null,'다른 구단의 관찰자 공유');});
T('[검수 11-18 스카우트 독립교차] 이동 로그의 과거 평가는 반환 객체 수정·재독·재영입·재이적 뒤에도 당시 내용과 연결된다',()=>{const p=sc666Setup(35,45),U=G.user,V=otherT();delete p.dEst;p.acq=null;G.scouts=[];const at=scoutReport(p);p.team=V;mvLog('보상선수',p,U,V,'');G.day+=2;let r=scoutReport(p);r.tools[0].cur=99;r.notes.push('외부수정');for(const k in p.r)if(typeof p.r[k]==='number')p.r[k]=60;p.pot=70;const old=scoutReport(p);ok(old.cur===at.cur&&!old.notes.includes('외부수정')&&old.tools[0].cur!==99,'보관 자료 객체 공유');G=JSON.parse(JSON.stringify(G));const q=G.players[p.id];ok(scoutReport(q).cur===at.cur,'재독 때 과거값 변경');q.team=U;mvLog('트레이드',q,V,U,'');const now=scoutReport(q);ok(now.cur===60&&!now.historical,'재영입 후 과거값 유지');G.day++;q.team=V;mvLog('트레이드',q,U,V,'');ok(scoutReport(q).cur===now.cur&&scoutReport(q).asOf===G.day,'두 번째 떠난 시점 평가 미갱신');});
function sm696Setup(){fresh();migrateDraft();return domestic(G.user).find(p=>!p.foreign&&!p.isP&&!p.prospect);}
function sm696Load(raw,seed){G=JSON.parse(raw);__seed(seed);const before=__rngState();migrateDraft();return {state:JSON.stringify(G),rng:__rngState(),before};}
T('[검수 11-18 #696] 동일 구형 저장의 누락 성장 유형과 체력은 실제 복원 때 동일하고 본게임 난수를 소비하지 않는다 [저장복원검수]',()=>{const p=sm696Setup();delete p.dt;delete p.r.vit;const raw=JSON.stringify(G),a=sm696Load(raw,101),va=JSON.stringify([G.players[p.id].dt,G.players[p.id].r.vit]),b=sm696Load(raw,909),vb=JSON.stringify([G.players[p.id].dt,G.players[p.id].r.vit]);ok(va===vb,'같은 누락 성장/체력이 재추첨 '+va+' / '+vb);ok(a.state===b.state,'같은 원본 전체 복원 상태가 다름');ok(a.rng===a.before&&b.rng===b.before,'누락 필드 복원이 본게임 난수 소비');});
T('[검수 11-18 #697] 컨디션 연도 표식 복원은 기존 컨디션 피로 누적 소모 최근 기록을 보존한다 [저장복원검수]',()=>{const p=sm696Setup(),q=domestic(G.user).find(x=>x.id!==p.id&&!x.foreign);G.day=G.cal.camp+5;delete G.formY;p.sf={y:G.year,v:1.73,m:.41,lk:.012};p.wear=37;p.fat=80;p.l10=[{d:G.day-2,pa:4,h:2},{d:G.day-1,pa:5,h:1}];delete q.sf;q.wear=12;q.fat=47;q.l10=[{d:G.day-1,pa:1,h:0}];const keep=JSON.stringify([p.sf,p.wear,p.fat,p.l10,q.wear,q.fat,q.l10]),raw=JSON.stringify(G),a=sm696Load(raw,101),P=G.players[p.id],Q=G.players[q.id],sf=JSON.stringify(Q.sf);ok(JSON.stringify([P.sf,P.wear,P.fat,P.l10,Q.wear,Q.fat,Q.l10])===keep,'컨디션 복원이 기존 상태 초기화 '+JSON.stringify([P.sf,P.wear,P.fat,P.l10]));ok(G.formY===G.year&&Q.sf?.y===G.year,'누락된 컨디션만 채우지 않음');const b=sm696Load(raw,909);ok(JSON.stringify(G.players[q.id].sf)===sf&&a.state===b.state,'누락 컨디션 복원이 같은 원본에서 달라짐');ok(a.rng===a.before&&b.rng===b.before,'컨디션 복원이 본게임 난수 소비');});
T('[검수 11-18 #698] 동일 외국인의 누락 적응력은 저장을 다시 열어도 같고 기존 적응력은 그대로다 [저장복원검수]',()=>{sm696Setup();const p=Object.values(G.players).find(p=>p.foreign),q=Object.values(G.players).find(q=>q.foreign&&q.id!==p.id);delete p.adapt;q.adapt=63;const raw=JSON.stringify(G),a=sm696Load(raw,101),adapt=G.players[p.id].adapt,b=sm696Load(raw,909);ok(G.players[p.id].adapt===adapt,'누락 적응력 재추첨 '+adapt+' / '+G.players[p.id].adapt);ok(G.players[q.id].adapt===63,'이미 저장한 적응력 변경');ok(a.state===b.state&&a.rng===a.before&&b.rng===b.before,'적응력 복원의 상태/RNG 불일치');});
T('[검수 11-18 #699] 실제 저장 불러오기는 AI 스카우트 공석을 임의 채용하지 않는다 [저장복원검수]',()=>{sm696Setup();const t=G.teams.find(t=>t.id!==G.user).id,L=G.lgStaff[t];L.sc=L.sc.slice(0,1);const staff=JSON.stringify(L.sc),raw=JSON.stringify(G),a=sm696Load(raw,101);ok(G.lgStaff[t].sc.length===1&&JSON.stringify(G.lgStaff[t].sc)===staff,'불러오기로 AI 공석 채용 '+G.lgStaff[t].sc.length);const b=sm696Load(raw,909);ok(a.state===b.state&&a.rng===a.before&&b.rng===b.before,'AI 공석 복원이 상태/RNG 변경');});
T('[검수 11-18 #707] 트레이드 최초 이탈 복원은 구단주 목표 존재나 버전과 무관하게 수행된다 [저장복원검수]',()=>{const p=sm696Setup(),other=G.teams.find(t=>t.id!==G.user).id,y=G.year-1;G.trades=[{y,d:dnum(y,3,1),me:G.user,with:other,gi:[p.id],go:[],snap:{}}];G.moves=[{pid:p.id,y,d:dnum(y,8,1),from:G.user,to:other}];delete G.plog;const raw=JSON.stringify(G);let expected;for(const goals of [null,{y:G.year,v:2,sup:1},{y:G.year-1,v:0,sup:1}]){G=JSON.parse(raw);G.goals=goals;const rng=__rngState();migrateDraft();ok(G.trades[0].end?.[p.id]===y,'목표 조건 때문에 최초 이탈 복원 누락 '+JSON.stringify(goals));ok(__rngState()===rng,'이탈 기록 복원이 난수 소비');const first=JSON.stringify(G.trades);G=JSON.parse(JSON.stringify(G));migrateDraft();ok(JSON.stringify(G.trades)===first,'최초 이탈 중복 복원');if(expected==null)expected=first;else ok(first===expected,'목표 조건별 거래 종료 결과 다름');}});
T('[검수 11-18 #696 #698 보존] 기존 선수 값과 다른 선수의 누락 복원은 서로의 평가나 난수를 바꾸지 않는다 [저장복원검수]',()=>{sm696Setup();const [p,q]=domestic(G.user).filter(p=>!p.isP&&!p.foreign).slice(0,2),f=Object.values(G.players).find(p=>p.foreign);p.dt='stall';p.r.vit=42;f.adapt=63;delete q.dt;delete q.r.vit;const rng=__rngState(),raw=JSON.stringify(q);playerLoadDefaults(p);playerLoadDefaults(f);playerLoadDefaults(q);const fixed=JSON.stringify([q.dt,q.r.vit]);ok(p.dt==='stall'&&p.r.vit===42&&f.adapt===63,'이미 저장된 선수 필드를 복원에서 덮음');G.players[q.id]=JSON.parse(raw);playerLoadDefaults(G.players[q.id]);ok(JSON.stringify([G.players[q.id].dt,G.players[q.id].r.vit])===fixed&&__rngState()===rng,'다른 선수 복원 횟수 때문에 재추첨하거나 난수 소비');});
T('[검수 11-18 #697 보존] 연도 없는 기존 시즌 컨디션도 피로와 최근 기록을 보존하며 누락 칸만 채운다 [저장복원검수]',()=>{const p=sm696Setup();G.day=G.cal.camp+10;delete G.formY;p.sf={v:1.25,m:.7,lk:.02};p.fat=98;p.wear=12;p.l10=[{d:G.day-1,outs:3}];const keep=JSON.stringify([p.sf.v,p.sf.m,p.sf.lk,p.fat,p.wear,p.l10]),raw=JSON.stringify(G),a=sm696Load(raw,377),P=G.players[p.id];ok(P.sf.y===G.year&&JSON.stringify([P.sf.v,P.sf.m,P.sf.lk,P.fat,P.wear,P.l10])===keep,'연도 누락 컨디션을 새 추첨으로 교체');ok(a.rng===a.before,'연도 표식 복원이 본게임 난수 소비');});
T('[검수 11-18 #697 정상 시즌] 실제 새 시즌 컨디션 추첨은 기존처럼 피로를 초기화하고 본게임 난수를 쓴다 [저장복원검수]',()=>{const p=sm696Setup();p.wear=37;p.fat=80;p.l10=[{d:G.day-1,pa:4}];const before=__rngState();rollForm();ok(p.sf.y===G.year&&p.wear===0&&p.fat===0&&p.l10.length===0,'정상 시즌 컨디션 시작 동작 변경');ok(__rngState()!==before,'정상 새 시즌 추첨까지 결정적 복원으로 변경');});

T('[검수 11-18 #700] 연도 없는 완료 드래프트는 11월 복원 때 후보를 새로 생성하지 않는다 [시즌저장검수]',()=>{fresh();makeDraftClass();for(const p of Object.values(G.players))if(p.prospect)delete G.players[p.id];G.draftClass=[];G.draft={done:true};G.day=KD(11,15);const n=Object.keys(G.players).length,r=__rngState();migrateDraftPool();ok(G.draftClass.length===0&&Object.keys(G.players).length===n,'완료한 옛 드래프트에 새 후보 '+G.draftClass.length+'명 생성');ok(__rngState()===r,'완료 드래프트 복원 난수 소비');const b=JSON.stringify(G);migrateDraftPool();ok(JSON.stringify(G)===b,'완료 드래프트 복원 멱등 위반');});
T('[검수 11-18 #701] 알려진 학교를 기준으로 후보의 권역·담당 지역을 함께 복원한다 [시즌저장검수]',()=>{fresh();makeDraftClass();const p=G.players[G.draftClass[0]];p.school='부산고';p.area='서울';p.region='수도권';p.amObs={[G.user]:3};const snap=JSON.stringify([p.r,p.pot,p.am,p.amY,p.amObs]),r=__rngState();migrateDraftPool();ok(p.area==='부산·울산·경남'&&p.region==='영남','학교와 담당 권역 모순 '+p.area+'/'+p.region);ok(obsSchoolsOf(p.region).includes(p.school),'담당자가 해당 학교를 방문할 수 없음');ok(JSON.stringify([p.r,p.pot,p.am,p.amY,p.amObs])===snap&&__rngState()===r,'권역 수리가 능력·기록·관찰 또는 난수 변경');const b=JSON.stringify(p);migrateDraftPool();ok(JSON.stringify(p)===b,'학교 권역 수리 멱등 위반');});
T('[검수 11-18 #704] 퓨처스 기록 압축 전후 함께 관찰한 시즌 수와 평가 오차를 보존한다 [시즌저장검수]',()=>{fresh();const p=domestic(G.user).find(p=>!p.isP);G.year=2032;G.startY=2027;p.hist=[2027,2028,2029,2030].map(y=>Object.assign({},ZB,{y,t:G.user,lvl:'퓨처스',g:30,pa:120,ab:105,h:30,bb:15,r:15}));/* 8d27c730(검수 644~675)부터 한 해 100타석 이상 관찰한 해만 센다 */const n=ownObs(p),sd=ownSd(p,bestScout()),r=__rngState();ok(n===4,'관찰 4시즌 준비');compactPlayers();ok(ownObs(p)===n,'기록 압축 뒤 관찰 시즌 '+n+' → '+ownObs(p));ok(Math.abs(ownSd(p,bestScout())-sd)<1e-9,'압축 뒤 평가 오차 변경');ok(__rngState()===r,'압축 난수 소비');const b=JSON.stringify(p.hist);compactPlayers();ok(JSON.stringify(p.hist)===b&&ownObs(p)===n,'반복 압축으로 관찰 시즌 변경');});
T('[검수 11-18 #705] 새해에 삭제된 후보는 보드·구단별 우선순위·보관된 구단 보드에서 함께 빠진다 [시즌저장검수]',()=>{fresh();makeDraftClass();const id=G.draftClass[0],U=G.user,V=otherT(),live=domestic(U)[0].id,e=Object.values(amPipe().L).find(e=>e.gy>G.year);ok(e,'저학년 준비');G.shortlist=[id,live];G.amPr={[U]:{[id]:2,[e.id]:1,'s:부산고':2},[V]:{[id]:2}};G.amFw={[U]:[id,e.id,'s:부산고'],[V]:[id]};G.dClub={[V]:{shortlist:[id,live],dmemo:{[id]:{rd:1}}}};G.day=KD(12,31);newYear();ok(!G.players[id],'후보 삭제 준비');ok(!G.shortlist.includes(id),'삭제 후보가 드래프트 보드에 남음');ok(G.shortlist.includes(live),'살아 있는 선수까지 보드에서 삭제');for(const tid of [U,V])ok(!Object.prototype.hasOwnProperty.call(G.amPr[tid],id),'삭제 후보 집중 우선순위 잔존');ok(G.amPr[U][e.id]===1&&G.amPr[U]['s:부산고']===2,'저학년·학교 우선순위 손실');ok(!G.amFw[U].includes(id)&&G.amFw[U].includes(e.id),'관심 이력 정리 불일치');ok(!G.dClub[V].shortlist.includes(id)&&G.dClub[V].shortlist.includes(live)&&!G.dClub[V].dmemo[id],'보관 중인 구단의 삭제 후보 보드·메모 잔존');});
T('[검수 11-18 #706] 같은 날짜 다른 세이브를 열면 옛 경기 캐시는 단장 보고에 쓰이지 않는다 [시즌저장검수]',()=>{fresh();makeDraftClass();const p=G.draftClass.map(id=>G.players[id]).find(p=>AREA.some(a=>a.hs.includes(p.school))),a=AREA.find(a=>a.hs.includes(p.school)),reg=a.reg;G.day=KD(4,15);const saved=JSON.stringify(G);_amToday={g:G,d:G.day,L:[{id:p.id,kind:'p',sch:p.school,b:'4타수 4홈런 전세이브전용706'}]};ok(amTripSeen(reg)?.length===1,'캐시 준비');G=JSON.parse(saved);worldReset();const r=__rngState(),cached=amTripSeen(reg);ok(__rngState()===r,'경기 캐시 조회 난수 소비');gmScoutTrip(reg);ok(!G.mail[0].body.includes('전세이브전용706'),'이전 저장 4홈런 기록이 새 단장 관전 메일에 노출: '+G.mail[0].body);ok(cached===null,'세계 초기화 후 다른 저장의 당일 기록 재사용');_amToday={g:G,d:G.day,L:[{id:p.id,kind:'p',sch:p.school,b:'현재 세계 기록'}]};ok(amTripSeen(reg)?.length===1,'현재 세계 경기 기록 누락');G=JSON.parse(saved);const b=JSON.stringify(G),r2=__rngState();ok(amTripSeen(reg)===null&&JSON.stringify(G)===b&&__rngState()===r2,'세계 식별 조회 실패 또는 조회가 상태 변경');});
T('[검수 11-18 #700·701 호환] 진행 중인 빈 명단은 새로 뽑지 않고 새 시즌의 빈 명단만 만들며 모르는 학교는 창작하지 않는다 [시즌저장검수]',()=>{fresh();makeDraftClass();for(const p of Object.values(G.players))if(p.prospect)delete G.players[p.id];G.draftClass=[];G.draft={done:false,cls:[]};const r=__rngState();migrateDraftPool();ok(G.draftClass.length===0&&G.draft.cls.length===0&&__rngState()===r,'진행 중인 빈 지명 명단을 다시 생성');G.draft=null;migrateDraftPool();ok(G.draftClass.length>0,'새로 필요한 후보 명단까지 생성 차단');const p=G.players[G.draftClass[0]];p.school='기록에만 남은 학교';p.area='부산·울산·경남';p.region='수도권';const r2=__rngState();migrateDraftPool();ok(p.school==='기록에만 남은 학교'&&p.region==='영남','모르는 학교를 만들거나 알려진 권역과 모순');ok(__rngState()===r2,'학교 수리 난수 소비');});
T('[검수 11-18 #704 반복 압축] 관찰한 연도의 공백·구단·중복을 유지하며 합산 줄을 다시 합쳐도 시즌 수가 보존된다 [시즌저장검수]',()=>{fresh();const p=domestic(G.user).find(p=>!p.isP),U=G.user,V=otherT();G.year=2040;G.startY=2030;const row=(y,t=U,pa=120,lvl='퓨처스')=>Object.assign({},ZB,{y,t,lvl,g:pa?30:0,pa,ab:pa?Math.round(pa*.875):0,h:pa?Math.round(pa/4):0,bb:pa?Math.round(pa/8):0,r:pa?Math.round(pa/8):0});/* 8d27c730(검수 644~675)부터 한 해 100타석 이상 관찰한 해만 센다: 기본 120타석 */p.hist=[2029,2030,2032,2034,2038].map(y=>row(y)).concat([row(2031,U,0),row(2033,V),row(2032,U,80,'1군')]);ok(ownObs(p)===4,'공백·구단·중복 관찰 준비');compactPlayers();ok(ownObs(p)===4,'합산 범위의 미출전 연도·다른 구단·중복을 관찰로 셈');const h=p.hist.find(h=>h.lvl==='퓨처스'&&h.t===U&&h.y2);ok(JSON.stringify(h.obsY)===JSON.stringify([2029,2030,2032,2034]),'출전 연도 자체를 보존하지 않음');p.hist.push(row(2039),row(2040));G.year=2044;compactPlayers();ok(ownObs(p)===6,'다음 압축에서 이전 관찰 연도 누락');G=JSON.parse(JSON.stringify(G));const q=G.players[p.id],r=__rngState(),b=JSON.stringify(q.hist);compactPlayers();ok(ownObs(q)===6&&JSON.stringify(q.hist)===b&&__rngState()===r,'저장 재로딩·반복 압축으로 관찰 변경');q.hist=[row(2030)];q.hist[0].y2=2035;const state=JSON.stringify(q),n=ownObs(q);ok(n===1&&JSON.stringify(q)===state,'연도 근거 없는 구형 합산의 중간 시즌 창작 또는 조회 변경');});
T('[검수 11-18 #706 임시 세계] 다른 세계 조회는 기록을 숨기되 원래 세계로 돌아오면 실제 당일 기록이 유지된다 [시즌저장검수]',()=>{fresh();makeDraftClass();const p=G.draftClass.map(id=>G.players[id]).find(p=>AREA.some(a=>a.hs.includes(p.school))),reg=AREA.find(a=>a.hs.includes(p.school)).reg,G0=G;G.day=KD(4,15);_amToday={g:G,d:G.day,L:[{id:p.id,kind:'p',sch:p.school,b:'돌아온 현재 세계706'}]};const r=__rngState();ladderSwap(JSON.parse(JSON.stringify(G)),()=>ok(amTripSeen(reg)===null,'임시 세계가 원래 경기 기록 사용'));ok(G===G0&&amTripSeen(reg)?.[0].b==='돌아온 현재 세계706','임시 세계 방문으로 실제 당일 기록 유실');ok(__rngState()===r,'임시 세계 캐시 조회 난수 소비');});
function po724Setup(){fresh();G.day=G.cal.open+25;G.cal.sched={};G.makeup=[];G.ps=null;G.sea.tl=G.teams.map(()=>[]);G.teams.forEach((t,i)=>{G.sea.rec[t.id]=i<4?{w:95,l:49,t:0}:i===4?{w:70,l:74,t:0}:{w:60,l:84,t:0};t.expW=.5;});_poC={k:null};return G.teams.map(t=>t.id);}
function po724Future(){const id=G.teams.length;G.teams.push({...G.teams[0],id,city:'미래시',nick:'내년팀',born:G.year+1});G.sea.rec[id]={w:0,l:0,t:0};return id;}
T('[검수 11-18 #724] 내년 참가 구단 추가가 올해 참가팀의 진출 확률과 다섯 자리를 바꾸지 않는다 [진출확률검수]',()=>{const L=po724Setup(),before=playoffOdds(),r=__rngState(),future=po724Future(),after=playoffOdds();ok(before.find(x=>x.tid===L[4]).ps===1,'진출 100% 준비');ok(!after.some(x=>x.tid===future),'올해 안 뛰는 내년 구단에 진출 자리 부여');ok(JSON.stringify(after)===JSON.stringify(before),'미래 팀을 추가하자 올해 확률 변경');ok(Math.abs(after.reduce((s,x)=>s+x.ps,0)-5)<1e-9&&__rngState()===r,'진출 자리 합계 또는 주 난수 위반');});
T('[검수 11-18 #725] 올해 진출 확정은 내년 창단팀의 가상 전승 가능성으로 풀리지 않는다 [진출확률검수]',()=>{const L=po724Setup();G.sea.rec[L[4]]={w:80,l:64,t:0};ok(psClinched(L[4]),'현재 참가팀 진출 확정 준비');const future=po724Future(),r=__rngState();ok(psClinched(L[4]),'내년 팀 때문에 올해 수학적 진출 확정 해제');ok(!psClinched(future),'아직 참가하지 않은 팀을 진출 확정으로 판단');ok(__rngState()===r,'진출 확정 조회 난수 소비');});
T('[검수 11-18 #726] 같은 날 남은 대진만 바꿔도 진출 확률 캐시를 다시 계산한다 [진출확률검수]',()=>{const L=po724Setup();G.sea.rec[L[4]]={w:70,l:72,t:0};G.sea.rec[L[5]]={w:70,l:73,t:0};const before=playoffOdds().find(x=>x.tid===L[4]).ps;ok(before===1,'잔여 경기 없는 단독 5위 준비');G.cal.sched[G.day+1]=[[L[4],L[5]]];const r=__rngState(),after=playoffOdds().find(x=>x.tid===L[4]).ps;ok(after>.2&&after<.8,'바뀐 잔여 맞대결 대신 종전 확률 재사용 '+before+' → '+after);ok(__rngState()===r,'확률 재계산 주 난수 소비');const cached=JSON.stringify(playoffOdds());_poC={k:null};ok(JSON.stringify(playoffOdds())===cached,'새 대진 캐시와 독립 재계산 결과 불일치');});
T('[검수 11-18 #727] 19경기 조회 후 같은 날 무승부로 20경기가 되면 확률 보류를 해제한다 [진출확률검수]',()=>{po724Setup();G.teams.forEach(t=>G.sea.rec[t.id]={w:9,l:10,t:0});ok(playoffOdds()===null,'19경기 보류 준비');G.teams.forEach(t=>G.sea.rec[t.id].t=1);const r=__rngState(),v=playoffOdds();ok(v&&v.length===seaTeams().length,'무승부 포함 20경기인데 옛 빈 확률 캐시 유지');ok(__rngState()===r,'무승부 캐시 갱신 난수 소비');});
T('[검수 11-18 #728] 결정전 예상은 맞대결 홈 우선권과 추정 전력을 함께 반영한다 [진출확률검수]',()=>{const L=po724Setup(),A=L[4],B=L[5];G.sea.rec[A]={w:72,l:72,t:0};G.sea.rec[B]={w:72,l:72,t:0};team(A).expW=.95;team(B).expW=.05;for(let i=0;i<12;i++){G.sea.tl[A].push([1,4,0,G.day-i,B]);G.sea.tl[B].push([-1,0,4,G.day-i,A]);}ok(standingsNow()[4].tid===A,'맞대결 홈 우선권 준비');const r=__rngState(),v=playoffOdds(),a=v.find(x=>x.tid===A),b=v.find(x=>x.tid===B);ok(a.str>b.str+.2,'추정 전력 차이 준비');ok(a.ps>.65&&b.ps<.35,'강한 홈팀도 동전 확률로 결정 '+a.ps+'/'+b.ps);ok(Math.abs(a.ps+b.ps-1)<1e-9&&__rngState()===r,'결정전 한 자리 또는 주 난수 위반');});
T('[검수 11-18 #726 순연 캐시] 남은 경기 수가 같아도 순연 대진과 홈·원정이 달라지면 다시 계산한다 [진출확률검수]',()=>{const L=po724Setup();G.sea.rec[L[4]]={w:70,l:72,t:0};G.sea.rec[L[5]]={w:70,l:73,t:0};G.makeup=[{y:G.year,h:L[0],a:L[9],d:G.day-1}];ok(playoffOdds().find(x=>x.tid===L[4]).ps===1,'진출에 무관한 순연 경기 준비');G.makeup=[{y:G.year,h:L[4],a:L[5],d:G.day-1}];const r=__rngState(),v=playoffOdds(),p=v.find(x=>x.tid===L[4]).ps;ok(p>.2&&p<.8,'같은 개수의 다른 순연 경기인데 옛 확률 '+p);G.makeup[0].h=L[5];G.makeup[0].a=L[4];const key=_poC.k;playoffOdds();ok(_poC.k!==key,'홈·원정 교체를 캐시가 무시');ok(__rngState()===r,'순연 대진 조회 주 난수 소비');});
T('[검수 11-18 #724 남은 일정] 내년 구단은 캐시를 비우고 남은 경기까지 모의 진행해도 올해 확률을 바꾸지 않는다 [진출확률검수]',()=>{const L=po724Setup();G.sea.rec[L[4]]={w:70,l:72,t:0};G.sea.rec[L[5]]={w:70,l:73,t:0};G.cal.sched[G.day+1]=[[L[4],L[5]]];const before=JSON.stringify(playoffOdds()),r=__rngState(),future=po724Future();G.makeup.push({y:G.year,h:future,a:L[4],d:G.day-1});_poC={k:null};const after=playoffOdds();ok(JSON.stringify(after)===before,'미참가 팀 때문에 남은 경기 모의 진행 또는 확률 변경');ok(Math.abs(after.reduce((s,x)=>s+x.first,0)-1)<1e-9&&__rngState()===r,'1위 자리 합계 또는 주 난수 위반');});
T('[검수 11-18 #728 순수 조회] 경기 확률은 같은 전력에서 홈에 가산하고 조회·재로딩이 저장 상태와 주 난수를 바꾸지 않는다 [진출확률검수]',()=>{po724Setup();ok(Math.abs(poWinP(.5,.5)-.515)<1e-12,'같은 전력의 홈 이점 누락');ok(poWinP(.65,.35)>poWinP(.5,.5)&&poWinP(.35,.65)<.5,'결정전 전력 차이를 모형이 반영하지 않음');const state=JSON.stringify(G),r=__rngState(),v=JSON.stringify(playoffOdds());psClinched(G.user);ok(JSON.stringify(G)===state&&__rngState()===r,'확률·확정 조회가 저장 또는 난수 변경');G=JSON.parse(state);ok(JSON.stringify(playoffOdds())===v&&__rngState()===r,'같은 세이브 재로딩 뒤 확률 변경');});

const pb710=()=>{fresh();const U=G.user,O=otherT(),S=G.teams.map(t=>t.id).filter(t=>t!==U&&t!==O),order=[U,S[0],S[1],O,S[2]].map((tid,i)=>({tid,w:90-i,l:54+i,t:0})),d=G.cal.end+30;G.day=d;G.ps={y:G.year,seeds:order.map(x=>x.tid),order,res:{ks:[U,O,4,3]},resD:{ks:d},days:{ks:{d:Array.from({length:7},(_,i)=>d-6+i),h:Array(7).fill(U),p:[[2,1],[1,2],[2,1],[1,2],[2,1],[1,2],[5,2]]}},done:true,cur:null};G.games=[{gid:710,day:d,kind:'한국시리즈 7차전',home:U,away:O,hs:5,as:2,pbp:[{},{}],box:{h:{bat:[],pit:[]},a:{bat:[],pit:[]}}}];G.sea.ulog=[{gid:710,d,h:U,a:O,hs:5,as:2,k:'한국시리즈 7차전'}];G._bracketHidden=G.games[0];return {U,O,d,Q:eval(__psBracketReviewSrc())};};
T('[검수 11-18 #710] 숨긴 KS 결정전은 간이·상세 대진 모두 3대3으로 표시한다 [대진검수]',()=>{const {Q}=pb710(),s=Q.psLadder(G.ps.order),D=Q.bkData(G.year),v=Q.bkSeries(D,['ks',0,'po']);ok(!s.includes('4-3')&&s.includes('3-3'),'간이 대진 최종전 노출 '+s.slice(0,300));ok(!v.r&&v.wh===3&&v.wl===3,'상세 숨김 합계 불일치');});
T('[검수 11-18 #711] WC 미확인 승자는 상위 라운드 참가팀으로 새지 않는다 [대진검수]',()=>{const {U,O,d,Q}=pb710(),S=G.ps.seeds;G.ps.res={wc:[S[4],S[3],2,0]};G.ps.resD={wc:d};G.ps.days={wc:{d:[d-1,d],h:[S[3],S[3]],p:[[1,2],[1,2]]}};G.ps.done=false;G.ps.cur=mkSeries('spo',S[2],S[4],d+2);Object.assign(G._bracketHidden,{kind:'와일드카드 결정전 2차전',home:S[3],away:S[4],hs:1,as:2});const D=Q.bkData(G.year),s=Q.bkSeries(D,['spo',2,'wc']);ok(s.lo==null&&!s.c&&!s.r,'다음 라운드 현재 참가팀 노출');const h=Q.psLadder(G.ps.order),m=h.slice(h.indexOf('준플레이오프'),h.indexOf('와일드카드 결정전'));ok(m&&!m.includes(tnick(S[4])),'간이 준PO에 WC 승자 노출');});
T('[검수 11-18 #712] 옛 대진 점수가 없어도 숨긴 마지막 로그·합계는 표시하지 않는다 [대진검수]',()=>{const {Q}=pb710();delete G.ps.days.ks.p;const D=Q.bkData(G.year),s=Q.bkSeries(D,['ks',0,'po']),L=Q.bkGames(D,['ks',0,'po']);ok(!s.r&&s.wh===3&&s.wl===3,'점수 없는 옛 시리즈 최종 합계 노출');ok(!L[6].p&&L[6].u<0,'숨긴 마지막 로그/박스 접근 노출');});
T('[검수 11-18 #718] WC 어드밴티지 진출은 간이 대진에도 진출 구단과 사유가 분명하다 [대진검수]',()=>{const {Q}=pb710(),S=G.ps.seeds;G._bracketHidden=null;G.ps.res={wc:[S[3],S[4],0,1]};G.ps.days={wc:{d:[G.day-1,G.day],h:[S[3],S[3]],p:[[0,1],[1,1]]}};const h=Q.psLadder(G.ps.order);ok(h.includes('어드밴티지')&&h.includes(tnick(S[3]))&&h.includes('진출'),'간이 WC가 종료0-1만 표시');});
T('[검수 11-18 #720] 지난 대진표 모든 구단 이름은 당시 명칭을 쓴다 [대진검수]',()=>{const {U,O,Q}=pb710(),y=G.year;G._bracketHidden=null;G.history=[{y,order:G.ps.order,ps:{...G.ps.res,days:G.ps.days}}];G.ps=null;G.year=y+1;G.day=dnum(y+1,1,5);clubRebrand(U,{nick:'미래새이름'},'검수');const old=(G.tnames[U]||[])[0];ok(old,'이름 이력 준비');Q.UI.psY=y;const h=Q.psBracket();ok(h.includes(old.nick)&&!h.includes('미래새이름'),'과거 대진에 현재 구단명 노출');});
T('[검수 11-18 #721] 옛 점수·로그가 없으면 남은 박스에서 알려진 차전 점수를 복원한다 [대진검수]',()=>{const {Q}=pb710();G._bracketHidden=null;delete G.ps.days.ks.p;G.sea.ulog=[];const L=Q.bkGames(Q.bkData(G.year),['ks',0,'po']);ok(L[6].p?.hs===5&&L[6].p?.as===2&&L[6].u===0,'보관 박스 점수 미표시');G._bracketHidden=G.games[0];const H=Q.bkGames(Q.bkData(G.year),['ks',0,'po']);ok(!H[6].p&&H[6].u<0,'박스 fallback이 미확인 차전 노출');});
T('[검수 11-18 #722] 1월로 순연한 PS는 달력 연도와 무관하게 진행 시즌에 귀속한다 [대진검수]',()=>{const {Q}=pb710(),y=G.year;delete G.ps.y;G.ps.resD.ks=dnum(y+1,1,2);G.ps.days.ks.d[6]=dnum(y+1,1,2);G._bracketHidden=null;ok(Q.psYearOf(G.ps)===y&&Q.bkYears().includes(y)&&!Q.bkYears().includes(y+1),'달력 연도로 PS 분류');G.ps.y=y;ok(Q.psYearOf(G.ps)===y,'명시적 시즌 연도 무시');});
T('[검수 11-18 #720 #722 보관] PS 이름·시즌 스냅샷은 원본 변경과 분리되며 옛 저장 복원은 멱등이다 [대진검수]',()=>{const {U}=pb710(),y=G.year;ok(typeof psArchiveSnapshot==='function'&&typeof psArchiveMetaMigrate==='function','보관 메타 복원 함수 없음');const p=psArchiveSnapshot(G.ps,y),n=JSON.stringify(p.names);G.ps.days.ks.p[6][0]=99;team(U).nick='나중이름';ok(p.days.ks.p[6][0]===5&&JSON.stringify(p.names)===n&&p.y===y,'보관 스냅샷이 현재 상태를 참조');G.history=[{y,order:G.ps.order,ps:p}];delete G.ps.y;const r=__rngState();psArchiveMetaMigrate();const s=JSON.stringify([G.ps,G.history]);psArchiveMetaMigrate();ok(s===JSON.stringify([G.ps,G.history])&&r===__rngState(),'보관 메타 복원 비멱등/난수변경');});

function pp714Setup(own=true){fresh();G.day=G.cal.end+3;G.res=null;G.stops=[];const others=G.teams.filter(t=>t.id!==G.user).map(t=>t.id),h=own?G.user:others[0],a=own?others[0]:others[1];G.ps={y:G.year,seeds:[h,a,...others.filter(t=>t!==h&&t!==a).slice(0,3)],order:standingsNow(),res:{},round:'ks',done:false,cur:mkSeries('ks',h,a,G.day)};G.entryY=G.year;for(const t of G.teams){for(const p of playersOf(t.id)){p.injOut=0;p.fat=0;}setEntry(t.id);}return {h,a};}
function pp714Weather(f){const r=rainPS;try{rainPS=()=>false;return f();}finally{rainPS=r;}}
T('[검수 11-18 #714] 무직 단장은 전 구단의 한국시리즈 경기를 치러도 우리 결과 확인으로 막히지 않는다 [PS진행검수]',()=>{pp714Setup();G.unemp={from:G.user,y:G.year};pp714Weather(()=>psDay(G.day));ok(!G.res&&!blocker().includes('경기 결과'),'전 구단 경기 뒤 결과 확인 차단 '+blocker());ok(!psOursOn(G.ps.cur.days[G.ps.cur.gi]),'무직인데 전 구단 경기 전 정지 대상');G.res={i:0};const raw=JSON.stringify(G);ok(!blocker().includes('경기 결과')&&JSON.stringify(G)===raw,'구형 저장의 남은 전 구단 결과가 무직 진행 차단/조회 부작용');G.res=null;});
T('[검수 11-18 #715] 내년 합류 육성선수는 탈락 구단의 올해 타팀 가을야구 진행을 막지 않는다 [PS진행검수]',()=>{pp714Setup(false);for(const p of Object.values(G.players))if(p.team===G.user)p.ys=false;for(let i=0;i<17;i++){const p=newPlayer({age:20,isP:false,base:30,pot:50,team:G.user,dev:true});p.ys=true;p.joinY=G.year+1;}G.ps.res.po=[G.ps.cur.hi,G.user,3,0];ok(ysN(G.user)===17,'내년 육성17명 준비');ok(blocker()==='','내년 합류 육성이 올해 진행 차단 '+blocker());});
T('[검수 11-18 #716] 시리즈 조기 종료는 열리지 않을 차전 예약과 경기 대기를 같은 날 취소한다 [PS진행검수]',()=>{pp714Setup();const s=G.ps.cur;s.wh=3;s.gi=3;G.day=s.days[3];const d=s.days[4],op=s.lo;G.gmPlan={[d]:{k:'attend',tid:G.user,op,x:'solo',done:false,mid:'pp716-alert'}};G.mail.push({id:'pp716-alert',subj:'내일 직관',acts:[{a:'watchPlan',v:String(d)}]});G.stops.push(G.mail[G.mail.length-1]);G.watchPlanned={day:d,op,tid:G.user};G.matchAwait={day:d,op,tid:G.user};const sg=simGame;try{simGame=(...args)=>{const g=sg(...args),us=args[1]===G.user?'h':'a';g.score[us]=9;g.score[us==='h'?'a':'h']=0;return g;};pp714Weather(()=>psDay(G.day));}finally{simGame=sg;}ok(G.ps.done,'4승 시리즈 종료 준비');const q=G.gmPlan[d];ok(q.done&&q.miss&&!G.watchPlanned&&!G.matchAwait,'열리지 않을 후속 차전 예약이 당일 남음 '+JSON.stringify([q,G.watchPlanned,G.matchAwait]));ok(!G.mail.some(m=>m.id==='pp716-alert')&&!G.stops.some(m=>m.id==='pp716-alert'),'무효 직관 메일/정지 남음');const note=G.mail.find(m=>(m.body||'').includes('시리즈 종료로 열리지 않아'));ok(note&&note.sgid===G.games[0].gid,'조기 종료 취소 소식이 미확인 경기와 연결되지 않음');});
T('[검수 11-18 #717] 총력전 에이스 구원도 피로100 선발 대신 가용한 쉬어 온 선발을 고른다 [PS진행검수]',()=>{fresh();const sp=domestic(G.user).filter(p=>p.isP).slice(0,3),day=G.day+10;for(let i=0;i<sp.length;i++){const p=sp[i];p.injOut=0;p.fat=0;p.ld=[];p.lastApp=day-4;p.lastStart=day-4;for(const k in p.r)p.r[k]=70-i*8;p.r.sta=45;}sp[0].fat=100;const fs={tid:G.user,sp:sp[2],spAll:sp,used:new Set([sp[2].id])};ok(!relAvail(sp[0],day,true)&&relAvail(sp[1],day,true),'일반 불펜 제외/대체 투수 준비');ok(psAceRelief(fs,8,1,day,{fin:true})===sp[1],'피로100 에이스를 총력전 구원으로 선택');});
T('[검수 11-18 #719] 이직 후 같은 날짜 두 경기의 시즌 로그를 박스 경기ID와 차전에 연결한다 [PS진행검수]',()=>{fresh();const tid=G.teams.find(t=>t.id!==G.user).id,d=G.day,op=G.user;G.sea.tl=G.teams.map(()=>[]);G.sea.tl[tid]=[[1,5,4,1,op,d,1,0],[-1,2,3,1,op,d,0,1]];G.games=[{gid:71901,day:d,home:tid,away:op,hs:5,as:4,dh:1},{gid:71902,day:d,home:tid,away:op,hs:2,as:3,dh:2}];G.gamesOff=[];userLogRebuild(tid);const L=G.sea.ulog;ok(L.length===2&&L[0].gid===71901&&L[0].dh===1&&L[1].gid===71902&&L[1].dh===2,'이직 로그에서 경기ID/차전 누락 '+JSON.stringify(L));});
T('[검수 11-18 #723] 포스트시즌 라운드와 개인 통산은 선발 출장 도루실패 총실점을 함께 보관한다 [PS진행검수]',()=>{fresh();const t=G.user,b=domestic(t).find(p=>!p.isP),P=domestic(t).filter(p=>p.isP).slice(0,2),[p,q]=P,op=G.teams.find(t=>t.id!==G.user).id;delete b.psY;delete p.psY;delete q.psY;G.psSer={};const g={S:{h:{tid:t,sp:p,pitchers:[p.id,q.id],box:new Map([[b.id,{pa:5,ab:4,h:2,cs:2,r:1}],[p.id,{outs:15,r:5,er:2,h:6,bf:22,hbp:1}],[q.id,{outs:3,r:0,er:0,bf:3}]])},a:{tid:op,pitchers:[],box:new Map()}},dec:{hld:[q.id]}};psRec('ks',g);const R=G.psSer[G.year].ks;ok(R[p.id].gs===1&&p.psY[G.year].gs===1,'선발 출장 누락');ok(R[b.id].cs===2&&b.psY[G.year].cs===2,'도루 실패 누락');ok(R[p.id].r===5&&p.psY[G.year].r===5&&R[p.id].er===2&&p.psY[G.year].er===2,'총실점/자책점 구분 누락');ok(q.psY[G.year].hld===1&&R[q.id].hld===1,'개인/라운드 홀드 합계 차이');});
T('[검수 11-18 #714 정상] 재직 중인 단장의 가을야구 경기는 결과 확인과 경기 전 사본을 유지한다 [PS진행검수]',()=>{pp714Setup();pp714Weather(()=>psDay(G.day));ok(G.res&&blocker().includes('경기 결과'),'재직 단장 결과 확인을 제거');ok(SPOIL_SNAP&&SPOIL_SNAP.day===G.day,'경기 전 선수 사본 제거');ok(psOursAt(G.ps.cur.days[G.ps.cur.gi]),'재직 단장 다음 경기 예약 불가');});
T('[검수 11-18 #715 정상] 올해 등록 육성 정원은 계속 막고 내년 예약 자리는 계약 한도에 남는다 [PS진행검수]',()=>{pp714Setup(false);for(const p of Object.values(G.players))if(p.team===G.user)p.ys=false;for(let i=0;i<17;i++){const p=newPlayer({age:20,isP:false,base:30,pot:50,team:G.user,dev:true});p.ys=true;p.joinY=G.year;}ok(blocker().includes('육성선수가 17명'),'현재 육성 정원 제한 제거');const p=ysList(G.user)[0];p.joinY=G.year+1;ok(ysN(G.user)===17&&blocker().includes('16명'),'진행 검사와 계약 예약 한도를 잘못 합침');});
T('[검수 11-18 #716 경계] 조기 종료 취소는 다른 경기 상대 업무 구단의 예약을 보존하며 반복해도 같다 [PS진행검수]',()=>{pp714Setup();const s=G.ps.cur,op=s.lo,other=G.teams.find(t=>t.id!==G.user&&t.id!==op).id;s.gi=4;const [a,b,c]=s.days.slice(4);G.cal.sched[a]=[[G.user,other]];G.gmPlan={[a]:{k:'attend',done:false},[b]:{k:'attend',op:other,tid:G.user,done:false},[c]:{k:'school',done:false}};const raw=JSON.stringify(G.gmPlan);G.watchPlanned={day:a,op:other};G.simPlanned={day:b,op,tid:other};G.matchAwait={day:c,op,tid:G.user};const rng=__rngState();psSeriesPlansDone(s);ok(JSON.stringify(G.gmPlan)===raw&&G.watchPlanned&&G.simPlanned&&!G.matchAwait,'다른 상대/업무/구단 예약까지 취소');const state=JSON.stringify(G);psSeriesPlansDone(s);ok(JSON.stringify(G)===state&&__rngState()===rng,'시리즈 종료 취소 반복/RNG 변경');});
T('[검수 11-18 #717 경계] 에이스 구원은 전날 등판과 연투 부하 제한을 지키고 후보 없으면 비운다 [PS진행검수]',()=>{fresh();const P=domestic(G.user).filter(p=>p.isP).slice(0,3),day=G.day+10;for(const p of P){p.fat=0;p.injOut=0;p.r.sta=45;p.lastApp=day-3;p.lastStart=day-3;p.lastPc=10;p.ld=[];}const fs={tid:G.user,sp:P[2],spAll:P,used:new Set([P[2].id])};P[0].lastApp=day-1;P[1].fat=100;ok(!psAceRelief(fs,8,1,day,{fin:true}),'피로/전날 등판 후보를 강제 호출');P[1].fat=0;ok(psAceRelief(fs,8,1,day,{fin:true})===P[1],'가용 후보까지 제외');ok(!psAceRelief(fs,6,1,day,{fin:true})&&!psAceRelief(fs,8,5,day,{fin:true}),'총력전 이닝/접전 조건 변경');});
T('[검수 11-18 #719 호환] 같은 점수 더블헤더도 서로 다른 경기로 보관하고 박스가 압축돼도 로그 메타를 유지한다 [PS진행검수]',()=>{fresh();const tid=G.user,op=G.teams.find(t=>t.id!==tid).id,d=G.day;G.sea.tl=G.teams.map(()=>[]);G.sea.tl[tid]=[[1,5,4,1,op,d,0,0],[1,5,4,1,op,d,0,0]];G.sea.tl[op]=[[-1,4,5,0,tid,d,0,0],[-1,4,5,0,tid,d,0,0]];const box=n=>({gid:71910+n,day:d,home:tid,away:op,hs:5,as:4,dh:n,res:'승'});G.sea.ulog=[];ulog(box(1));ulog(box(2));ok(G.sea.tl[tid][0][8]===71911&&G.sea.tl[tid][1][8]===71912,'같은 점수 차전 메타를 반대로 연결');G.games=[];G.gamesOff=[];userLogRebuild(op);const L=G.sea.ulog;ok(L[0].gid===71911&&L[0].dh===1&&L[1].gid===71912&&L[1].dh===2,'박스 압축 뒤 ID/차전 분실');const keep=JSON.stringify([G.sea.tl,G.sea.ulog]),rng=__rngState();userLogRebuild(op);ok(JSON.stringify([G.sea.tl,G.sea.ulog])===keep&&__rngState()===rng,'로그 복원 반복/RNG 변경');});
T('[검수 11-18 #723 연속] 같은 투수의 선발과 구원 출장을 구분하고 모든 라운드와 개인 누계를 똑같이 합산한다 [PS진행검수]',()=>{fresh();const P=domestic(G.user).filter(p=>p.isP).slice(0,2),[a,b]=P;delete a.psY;delete b.psY;G.psSer={};const g={S:{h:{tid:G.user,sp:a,pitchers:[a.id,b.id],box:new Map([[a.id,{outs:15,r:2,er:1,hbp:1,bf:20}],[b.id,{outs:3,r:1,er:0,hbp:1,bf:4}]])},a:{tid:0,pitchers:[],box:new Map()}},dec:{hld:[b.id]}};psRec('po',g);g.S.h.sp=b;g.S.h.pitchers=[b.id,a.id];psRec('ks',g);ok(a.psY[G.year].g===2&&a.psY[G.year].gs===1&&a.psY[G.year].r===4&&a.psY[G.year].er===2&&a.psY[G.year].hbp===2,'개인 선발 구원/총실점 누계 오류');ok(G.psSer[G.year].po[a.id].gs===1&&!G.psSer[G.year].ks[a.id].gs,'라운드 선발 출장 구분 실패');});

function ps709base(){fresh();const U=G.user,O=otherT(),d=G.cal.end+30;G.day=d;G.ps={y:G.year,done:true,champ:U,res:{ks:[U,O,4,3]},resD:{ks:d},finDay:d+2};const p=(entryOn()?actOf(U):playersOf(U)).find(p=>!p.isP);ok(p,'타자 준비');const g={gid:709,day:d,season:G.year,kind:'한국시리즈 7차전',home:U,away:O,hs:5,as:2,res:'승',pbp:[{},{}],box:{h:{bat:[{id:p.id,pa:5,ab:4,h:2,d:1,tr:0,hr:0,r:1,rbi:1,bb:1,hbp:0,sf:0,sh:0,so:1,sb:0,cs:0}],pit:[]},a:{bat:[],pit:[]}}};G.games=[g];G._ps709Hidden=g;return {U,O,d,p,g,F:eval(__psSpoilerReviewSrc())};}
T('[검수 11-18 #709] 미확인 KS 우승 통지는 소식 목록·확인할 소식·이동 순서에서 가리고 같은 날 다른 업무는 보존한다 [PS스포일러검수]',()=>{const {g,d,F}=ps709base(),m=stop('포스트시즌',tname(G.user)+'이(가) 한국시리즈 우승을 차지했습니다. 우리 구단이 정상에 올랐습니다.'),q=note('포스트시즌','내일 한국시리즈 일정 안내'),a=note('의무','같은 날 선수 검진 안내');ok(!F.mailFilter('all').some(x=>x.id===m.id),'우승 통지가 목록에 노출');ok(!F.ibNeedList().some(x=>x.id===m.id)&&!F.ibUnreadOrder().some(x=>x.id===m.id),'확인/이동 순서 우승 노출');ok(F.mailFilter('all').some(x=>x.id===q.id)&&F.mailFilter('all').some(x=>x.id===a.id),'같은 날 업무를 통째로 가림');G._ps709Hidden=null;ok(F.mailFilter('all').some(x=>x.id===m.id),'중계 종료 뒤 우승 소식 유실');});
T('[검수 11-18 #713] PS 첫 투구 전 선수 카드는 실제 경기 직전 누계를 쓰고 렌더 후 원본을 되돌린다 [PS스포일러검수]',()=>{const {U,O,p,d,F}=ps709base();p.psY={[G.year]:{t:U,isP:false,g:1,pa:4,ab:4,h:1,hr:0,bb:0}};spoilSnapTake(d,[U,O]);p.psY[G.year].g++;p.psY[G.year].pa+=5;p.psY[G.year].ab+=4;p.psY[G.year].h+=2;F.UI.sheet=p.id;const post=JSON.stringify(p.psY),un=F.spoilMask();ok(p.psY[G.year].pa===4,'첫 투구 전 당일 5타석이 PS누계에 포함');un();ok(JSON.stringify(p.psY)===post,'조회 후 실제 누계가 바뀜');});
T('[검수 11-18 #713 저장] 재독한 경기 전 PS누계는 두 번 빼지 않고 구형 사본은 숨긴 한 경기만 역산한다 [PS스포일러검수]',()=>{const {U,p,g,F}=ps709base(),pre={t:U,isP:false,g:1,pa:4,ab:4,h:1,hr:0,bb:0};p.psY={[G.year]:{...pre,g:2,pa:9,ab:8,h:3}};SPOIL_SNAP=null;G.castHold={gid:g.gid,ps:{[p.id]:{psY:{[G.year]:pre}}}};F.UI.sheet=p.id;let un=F.spoilMask();ok(p.psY[G.year].pa===4,'저장된 경기 전 누계를 누락하거나 이중 차감');un();delete G.castHold.ps[p.id].psY;un=F.spoilMask();ok(p.psY[G.year].pa===4&&p.psY[G.year].g===1,'구형 사본에서 숨긴 PS경기만 역산하지 않음');un();ok(p.psY[G.year].pa===9,'구형 사본 역산이 원본에 남음');});
T('[검수 11-18 #729] 순위 규칙 안내가 실제 맞대결 다득점 기준을 명시한다 [PS스포일러검수]',()=>{const {F}=ps709base(),t=F.standRules(10);ok(t.includes('다득점')&&!t.includes('득실차'),'실제 기준과 다른 순위 규칙 '+t);});
T('[검수 11-18 #730] DH 2차전 미확인 중에도 공개된 1차전 점수와 박스스코어 접근은 남는다 [PS스포일러검수]',()=>{const {U,O,d,F}=ps709base(),one={gid:7301,day:d,dh:1,kind:'',home:U,away:O,hs:5,as:4,res:'승',pbp:[{},{}],box:{h:{bat:[],pit:[]},a:{bat:[],pit:[]}}},two={...one,gid:7302,dh:2,hs:1,as:9,res:'패'};G.ps=null;G.games=[two,one];G._ps709Hidden=two;G.sea.ulog=[one,two].map(g=>({gid:g.gid,d,h:U,a:O,hs:g.hs,as:g.as,res:g.res,k:'',dh:g.dh}));const g=F.calGame(d),h=F.calDetail(d);ok(g?.res?.my===5&&g.res.op===4,'공개된 1차전 점수까지 숨김');ok(h.includes('5:4')&&h.includes('data-a="openGame" data-v="1"')&&!h.includes('1:9'),'DH 상세에서 공개박스 접근 유실 또는2차전 결과노출 '+h.slice(0,600));});

T('[검수 11-18 교차 #714] 야인 상태에서는 같은 날 남은 전 구단 중계가 진행 버튼을 막지 않는다 [PS교차검토]',()=>{fresh();G.day=G.cal.end+3;const U=G.user,O=otherT();G.ps={y:G.year,done:false,res:{},seeds:[U,O],order:standingsNow(),cur:mkSeries('ks',U,O,G.day+1)};G.unemp={from:U,y:G.year};G._unD=G.day;G.res=null;G.live={i:0,upto:0};G.games=[{gid:71409,day:G.day,home:U,away:O,kind:'한국시리즈 1차전',line:{a:[0],h:[0]}}];const d=G.day;advance('day');ok(G.day===d+1,'같은 날 야인 자동처리를 마친 옛 전 구단 중계가 진행 차단: '+blocker());});
T('[검수 11-18 교차 #724 #725] 두 미래 구단의 높은 성적과 정규 잔여 대진은 올해 확률과 진출 확정을 바꾸지 않는다 [PS교차검토]',()=>{fresh();G.day=G.cal.open+30;G.ps=null;G.cal.sched={};G.makeup=[];G.sea.tl=G.teams.map(()=>[]);G.teams.forEach((t,i)=>{t.expW=.5;G.sea.rec[t.id]=i<4?{w:95,l:49,t:0}:i===4?{w:80,l:64,t:0}:{w:60,l:84,t:0};});const U=G.teams[4].id,a=JSON.stringify(playoffOdds()),locked=psClinched(U),r=__rngState();for(let i=0;i<2;i++){const id=G.teams.length;G.teams.push({...G.teams[0],id,born:G.year+1,expW:.99,nick:'미래팀'+i});G.sea.rec[id]={w:120,l:0,t:0};G.cal.sched[G.day+i+1]=[[id,U],[G.teams[5].id,id]];}const v=playoffOdds();ok(JSON.stringify(v)===a&&psClinched(U)===locked&&locked,'미래 팀 정규 대진/성적이 올해 계산에 영향');ok(v.length===10&&v.reduce((s,x)=>s+x.ps,0)===5&&__rngState()===r,'현재 참가팀/진출 자리/주 난수 불변 위반');});
T('[검수 11-18 교차 #710 #712 #713 #722] 새해 1월 미확인 한 경기는 옛 PS누계와 두 대진에서 같은 시즌으로 가린다 [PS교차검토]',()=>{fresh();const U=G.user,O=otherT(),y=G.year,d=dnum(y+1,1,2),p=domestic(U).find(x=>!x.isP),rest=G.teams.map(t=>t.id).filter(t=>t!==U&&t!==O),order=[U,rest[0],rest[1],O,rest[2]].map((tid,i)=>({tid,w:90-i,l:54+i,t:0}));G.day=d;G.ps={seeds:order.map(x=>x.tid),order,res:{ks:[U,O,4,3]},resD:{ks:d},days:{ks:{d:Array.from({length:7},(_,i)=>d-6+i),h:Array(7).fill(U)}},done:true,cur:null};const g={gid:710722,day:d,kind:'한국시리즈 7차전',home:U,away:O,hs:5,as:2,box:{h:{bat:[{id:p.id,pa:5,ab:4,h:2}],pit:[]},a:{bat:[],pit:[]}}};G.games=[g];G._ps709Hidden=g;G._bracketHidden=g;G.sea.ulog=[{gid:g.gid,d,h:U,a:O,hs:5,as:2,k:g.kind}];p.psY={[y]:{t:U,isP:false,g:2,pa:9,ab:8,h:3},[y+1]:{t:U,isP:false,g:1,pa:30,ab:25,h:5}};SPOIL_SNAP=null;delete G.castHold;const Q=eval(__psBracketReviewSrc()),F=eval(__psSpoilerReviewSrc());F.UI.sheet=p.id;const post=JSON.stringify(p.psY),un=F.spoilMask();ok(p.psY[y].pa===4&&p.psY[y+1].pa===30,'달력 연도 PS를 차감하거나 지난 시즌 미확인5타석 노출');un();ok(JSON.stringify(p.psY)===post,'가린 뒤 실제 PS누계 복원 실패');const D=Q.bkData(y),L=Q.bkGames(D,['ks',0,'po']);ok(Q.psYearOf(G.ps)===y&&Q.psLadder(order).includes('3-3')&&!L[6].p&&L[6].u<0,'1월 미확인 결과가 대진·로그·박스로 노출');});

T('[검수 11-18 #714 호환 중계] 같은 날 야인 자동 처리 뒤에도 옛 중계 결과는 비우고 재직 중 중계는 지킨다 [PS진행검수]',()=>{fresh();G.unemp={from:G.user,y:G.year};G._unD=G.day;G.live={i:0,upto:0};G.res={i:0};const rng=__rngState();ok(!blocker().includes('경기를 먼저'),'구형 전 구단 중계가 야인 진행 차단');unempAuto();ok(!G.live&&!G.res&&__rngState()===rng,'같은 날 자동처리 조기 반환이 옛 중계/결과 보존');G.unemp=null;const live=G.live={i:0,upto:0};unempAuto();ok(G.live===live&&blocker().includes('경기를 먼저'),'재직 중 정상 중계를 비우거나 대기를 제거');});
