T('[검수 11-18 기강 #737] 이직과 복귀는 양쪽 구단의 기존 기강 보정을 바꾸지 않는다',()=>{const {U,V,p}=d737Setup();G.leadAdj={v:6,until:G.day+45};G.leadAdjT={[V]:{v:3,until:G.day+30}};p.susp=G.day+15;switchTeam(V);ok(leadAdjOf(U)?.v===6&&leadAdjOf(V)?.v===3,'이직 때 구단 기강 효과 손실');switchTeam(U);ok(leadAdjOf(U)?.v===6&&leadAdjOf(V)?.v===3&&p.susp===G.day+15,'복귀 때 보정 손실/출장 정지 변경');});
