T('[검수 11-18 기강 #739] 감독대행이 이끄는 팀은 공석과 구별해 설명한다',()=>{const {U}=d737Setup();G.mgr[U].interim=true;delete G.chem;clubChem(U);const r=chemWhy(U,true).find(x=>x.k==='mgr');ok(r&&r.t.includes('대행')&&!r.t.includes('비어'),'감독대행을 공석으로 설명 '+r?.t);});
T('[검수 11-18 기강 #740] 출전 갈등에서 감독 편에 서면 실제 구단 기강 보정이 생긴다',()=>{const {U,p}=d737Setup();const e=evNew('pt','출전 갈등','갈등',Array.from({length:4},()=>({l:'선택',fx:''})),{data:{pid:p.id}}),before=climateOf(U).S;evPick(e.id,0);ok((leadAdjOf(U)?.v||0)>0&&climateOf(U).S>before,'설명과 달리 기강 그대로');});
T('[검수 11-18 기강 #741] 불참 중징계는 실제 벌금 장부와 현금에 반영되고 무급일도 누적한다',()=>{const {U,p}=d737Setup();p.sal=365;p.boy=G.day+11;const cash=team(U).cash,e=evNew('pboy','훈련 불참','불참',[{l:'중징계',fx:''}],{data:{pid:p.id,ks:['hard']}});evPick(e.id,0);ok(team(U).cash>cash&&G.hoL?.[fyNow()+':'+U]?.inc,'벌금과 현금 모두 변화 없음');const start=G.day;G.day+=4;pdBoyDaily();ok(team(U).cash>cash+Math.round(p.sal*.01),'불참 실제 4일의 무급이 장부에 없음');const b=JSON.stringify([team(U).cash,G.hoL]);pdBoyDaily();ok(JSON.stringify([team(U).cash,G.hoL])===b,'같은 날짜 무급 중복');ok(p.sal===365&&p.boy===start+11,'기본 계약/불참 기간 임의변경');});
T('[검수 11-18 기강 #742] 이미 열린 다른 선수의 갈등 때문에 면담이 안 생기면 제한일을 소비하지 않는다',()=>{const {U,p}=d737Setup(),q=domestic(U).find(x=>x.id!==p.id&&!x.isP&&!x.ys);G.sea.rec[U].w=60;G.sea.rec[U].l=40;for(const x of [p,q]){x.mor=20;x.age=30;x.sal=600;x.e1=false;x.hist=[];}const regular=isRegular;try{isRegular=()=>false;const e=evNew('pt','이미 열린 갈등','갈등',[{l:'대기',fx:''}],{data:{pid:p.id}});delete q.reqDay;delete q.ptDay;delete G.ptLast;requestCheck(q);ok(q.reqDay==null&&q.ptDay==null&&G.ptLast==null,'사건 없이 쿨다운 소비');e.done=true;const oldR=FO_RNG;try{FO_RNG=()=>.99;requestCheck(q);}finally{FO_RNG=oldR;}ok(evOpen().some(x=>x.k==='pt'&&x.data.pid===q.id),'다른 사건 처리 후 실제 면담 생성 실패');}finally{isRegular=regular;}});
T('[검수 11-18 기강 #743] 외국인의 공식 불만은 처리 불가능한 트레이드를 요구하지 않는다',()=>{const {p}=d737Setup();p.foreign='용병';p.grv={pt:20};pdDemand(p);const e=evOpen().find(x=>x.k==='pdem');ok(e&&!e.title.includes('트레이드')&&!e.sit.includes('트레이드')&&!G.news[0].t.includes('공식 트레이드'),'외국인에게 거래 불가능한 공식 트레이드 요구');ok(e.opts.some(x=>x.l.includes('외국인')||x.l.includes('교체')||x.l.includes('면담')),'외국인에 맞는 대응 없음');});
T('[검수 11-18 기강 #737 호환] 구형 현재 구단 보정은 한 번만 구단별로 복원하고 야인·AI·재취임도 잇는다',()=>{const {U,V,p}=d737Setup();G.leadAdj={v:6,until:G.day+45};delete G.leadAdjTid;delete G.leadAdjT;const rng=__rngState();leadAdjMigrate();const b=JSON.stringify([G.leadAdj,G.leadAdjTid,G.leadAdjT]);leadAdjMigrate();ok(JSON.stringify([G.leadAdj,G.leadAdjTid,G.leadAdjT])===b&&__rngState()===rng,'기강 복원 멱등/RNG위반');firedFlow(G.year,'기강검수','resign');ok(leadAdjOf(U)?.v===6,'퇴임으로 구단 보정 삭제');leadDisc(U,p,1);ok(leadAdjOf(U)?.v===9,'야인 동안 AI 기강 보정 누락');switchTeam(V);switchTeam(U);ok(leadAdjOf(U)?.v===9,'AI가 바꾼 효과를 재취임이 덮음');});
T('[검수 11-18 기강 #738 중첩] 새 약한 징계도 이미 잡힌 긴 기강 기간을 단축하지 않는다',()=>{const {U,p}=d737Setup();leadAdjSet(U,{v:6,until:G.day+45});p.susp=G.day+15;leadDisc(U,p,1);ok(leadAdjOf(U).until===G.day+45&&leadAdjOf(U).v===9&&p.susp===G.day+15,'기존 정지/기강 기간이 단축');});
T('[검수 11-18 기강 #741 중복·귀환] 벌금은 사건당 한 번이고 무급은 조기 복귀한 실제 일수만 받는다',()=>{const {U,p}=d737Setup();p.sal=365;p.boy=G.day+11;const d=G.day,e=evNew('pboy','불참','불참',[{l:'중징계',fx:''}],{data:{pid:p.id,ks:['hard']}});evPick(e.id,0);const fine=G.discL[0].fine,cash=team(U).cash;pdDiscipline(p,e.id,{fine:true,unpaid:true});ok(team(U).cash===cash&&G.discL.length===1,'같은 사건의 벌금 재청구');G.day=d+3;p.boy=G.day;pdBoyDaily();const amount=Math.round(G.discL[0].rate*3);ok(G.discL[0].days===3&&G.discL[0].paid===amount&&team(U).cash===cash+amount,'예상11일을 실제3일로 정산하지 않음');const book=G.hoL[fyNow()+':'+U];ok(book.inc['선수 징계 벌금']===fine&&book.inc['훈련 불참 무급 환급']===amount,'장부 항목과 실제 현금 불일치');const before=JSON.stringify([G.discL,team(U).cash,G.hoL]),rng=__rngState();G=JSON.parse(JSON.stringify(G));pdBoyDaily();ok(JSON.stringify([G.discL,team(U).cash,G.hoL])===before&&__rngState()===rng,'재독 뒤 같은 날 급여 이중 환급');});
T('[검수 11-18 기강 #741 구단 귀속] 이직 뒤에도 무급 환급은 제재한 구단 장부에만 남는다',()=>{const {U,V,p}=d737Setup();p.boy=G.day+11;p.sal=365;const e=evNew('pboy','불참','불참',[{l:'중징계',fx:''}],{data:{pid:p.id,ks:['hard']}});evPick(e.id,0);switchTeam(V);const old=team(U).cash,next=team(V).cash;G.day+=4;pdBoyDaily();ok(team(U).cash>old&&team(V).cash===next,'무급 환급이 새 구단에 귀속');ok(G.hoL[fyNow()+':'+U].inc['훈련 불참 무급 환급']>0&&!G.hoL[fyNow()+':'+V]?.inc['훈련 불참 무급 환급'],'구단 장부 혼합');});
T('[검수 11-18 기강 #742 생성 실패] 사건 생성이 예외로 끝나도 요청·팀·선수 제한일을 남기지 않는다',()=>{const {U,p}=d737Setup();G.sea.rec[U].w=60;G.sea.rec[U].l=40;p.age=30;p.sal=600;p.mor=20;p.hist=[];delete p.reqDay;delete p.ptDay;delete G.ptLast;const regular=isRegular,make=EVH.pt.make;try{isRegular=()=>false;EVH.pt.make=()=>{throw new Error('생성 실패');};requestCheck(p);ok(p.reqDay==null&&p.ptDay==null&&G.ptLast==null,'면담 실패가 제한일을 소비');}finally{isRegular=regular;EVH.pt.make=make;}});
T('[검수 11-18 기강 #743 전 단계] 외국인 설명 요구·훈련 불참·인터뷰·AI 대응은 모두 트레이드 처리를 하지 않는다',()=>{const {U,V,p}=d737Setup();p.foreign='용병';p.grv={pt:20};pdDemand(p);let e=evOpen().find(x=>x.k==='pdem');ok(e.data.ks.includes('replace')&&!e.data.ks.includes('list'),'외국인 교체 검토 선택지 없음');const r=evPick(e.id,e.data.ks.indexOf('replace')),m=G.mail.find(x=>x.id===e.mid);ok(r.includes('외국인')&&m.acts.some(a=>a.a==='go'&&a.v==='transfer:foreign')&&!p.listed,'교체 검토에서 거래/교체를 허위 실행');pdBoycott(p);e=evOpen().find(x=>x.k==='pboy');ok(e&&!e.sit.includes('트레이드')&&!e.data.ks.includes('give')&&e.data.ks.includes('replace'),'외국인 훈련 불참이 트레이드 시위');p.pd={st:2};ok(pdIvQs({pid:p.id})[0].q.includes('거취')&&!pdIvQs({pid:p.id})[0].q.includes('트레이드'),'인터뷰에서 불가능한 거래 질문');p.team=V;p.pd={st:2};pdAiReact(p,3);ok(!p.aiListed,'AI 외국인을 거래 매물로 등록');});
T('[검수 11-18 기강 #741 겹친 처분] 같은 불참 기간을 두 사건에서 무급 처리해도 하루 급여를 두 번 받지 않는다',()=>{const {U,p}=d737Setup();p.sal=365;p.boy=G.day+11;const c=team(U).cash;pdDiscipline(p,'겹침A',{fine:true,unpaid:true});pdDiscipline(p,'겹침B',{fine:true,unpaid:true});G.day+=4;pdBoyDaily();const wage=Math.round(G.discL[0].rate*4);ok(G.discL.filter(x=>x.unpaid).length===1&&team(U).cash===c+2*Math.max(1,Math.round(p.sal*.01))+wage,'겹친 무급 기간 이중 환급');});
T('[검수 11-18 기강 #741 선수 이적] 불참 선수의 이동 로그는 호출 전후 소속 변경 순서와 무관하게 이전 구단의 무급을 그날 끝낸다',()=>{for(const first of [true,false]){const {U,V,p}=d737Setup();p.sal=365;p.boy=G.day+11;pdDiscipline(p,'이적정산',{unpaid:true});G.day+=3;if(first)p.team=V;mvLog('트레이드',p,U,V,'기강검수');if(!first)p.team=V;const wage=Math.round(G.discL[0].rate*3),cash=team(U).cash;ok(G.discL[0].paid===wage&&G.discL[0].closed,'이적일까지 급여 환급 미정산');G.day+=5;pdBoyDaily();ok(team(U).cash===cash&&G.discL[0].paid===wage,'이적 뒤에도 전 구단 급여 환급 계속');}});
T('[검수 11-18 기강 #739 저장된 공석 설명] 공석 때 저장된 분위기도 당일 대행 선임 뒤에는 대행으로 안내한다',()=>{const {U}=d737Setup(),m=G.mgr[U];G.mgr[U]=null;delete G.chem;clubChem(U);ok(chemWhy(U,true).some(x=>x.k==='mgr'&&x.t.includes('비어')),'공석 준비');G.mgr[U]={...m,interim:true};const before=JSON.stringify(G),rng=__rngState();ok(chemWhy(U,true).some(x=>x.k==='mgr'&&x.t.includes('대행')),'옛 공석 요인이 대행 선임 뒤에도 공석으로 표시');ok(JSON.stringify(G)===before&&__rngState()===rng,'설명 조회가 상태·난수 변경');});

function pp744Setup(){fresh();G.day=G.cal.open+100;G.fdWait=false;for(const t of G.teams){G.sea.rec[t.id]={w:50,l:50,t:0};setEntry(t.id);}const p=domestic(G.user).find(q=>!q.foreign&&!q.isP&&!q.ys&&!isRegular(q));ok(p,'벤치 타자 준비');p.e1=false;p.age=30;p.sal=800;p.mor=60;p.pers={pro:10,amb:10,loy:15,temp:10};p.hist=p.hist.filter(h=>h.y!==G.year);delete p.promise;delete p.morL;delete p.grv;delete p.pdProm;G._dc=null;return p;}
T('[검수 11-18 #744] 전 구단 타석은 현재 구단 출전 만족과 요구 판정에 들어가지 않는다 [출전약속검수]',()=>{const p=pp744Setup(),old=otherT();Object.assign(lineFor(p,G.year,old,'1군'),{g:100,pa:320,ab:280,h:80});lineFor(p,G.year,p.team,'1군');ok(!isRegular(p),'비주전 준비');ok(!playedReg(p),'전 구단320타석으로 새 구단 주전판정');ok(oppSat(p)?.lv==='불만'&&ptWhyP(p),'새 구단0타석의 불만/요구 누락');});
T('[검수 11-18 #745] 등록 연차가 미확정이면 계약 면담도 FA를 확정하지 않는다 [출전약속검수]',()=>{const p=pp744Setup();p.faC=false;p.svc=faSvc(p)-1;p.svcD=0;delete p.lastFA;G.regTrk=G.year;p.regD={y:G.year,n:0,tm:{[p.team]:0}};ok(!faSvcOk(p),'연차미충족 준비');const a=talkOutcome(p,'contract');ok(a.ex.faTxt!=='이번 시즌이 끝나면 FA입니다'&&/등록|채우|필요/.test(a.line),'미충족인데 FA확정 '+a.line);p.regD.n=145;p.regD.tm[p.team]=145;ok(faSvcOk(p),'연차확정 준비');ok(talkOutcome(p,'contract').ex.faTxt==='이번 시즌이 끝나면 FA입니다','연차확정 뒤에도 FA예정 미표시');});
T('[검수 11-18 #746] 채운 약속은 즉시 만족으로 보이고 부상일에도 이행으로 끝난다 [출전약속검수]',()=>{const p=pp744Setup();p.promise=mkPromise(p,30);const P=p.promise;lineFor(p,G.year,p.team,'1군').pa+=29;const rng=__rngState();ok(oppSat(p)?.lv==='만족'&&!moraleList(p).some(x=>x.wait),'29타석 충족인데 기다리는중');ok(__rngState()===rng&&p.promise===P,'조회가 난수/약속 변경');p.injOut=20;p.promise.until=G.day;moraleWeek();ok(!p.promise&&(p.morL||[]).some(x=>x[1]==='prom'&&x[2]===5),'충족뒤부상이 약속을 연장');});
T('[검수 11-18 #747] 작년에 지킨 약속은 새 시즌에도 이행으로 남는다 [출전약속검수]',()=>{const p=pp744Setup(),y=G.year;p.promise=mkPromise(p,30);lineFor(p,y,p.team,'1군').pa+=30;G.year++;G.cal=buildCalendar(G.year);G.sea.y=G.year;G.day=G.cal.open+1;ok(playPromKept(p),'해가바뀌자작년30타석누락');moraleWeek();ok(!p.promise&&(p.morL||[]).some(x=>x[1]==='prom'&&x[2]===5)&&!(p.grv?.prom>=6),'지킨 약속에 새해위반벌점');});
T('[검수 11-18 #748] 실제 옛 갈등 메일의 기용 건의는 진행 중인 약속 기준과 기한을 바꾸지 않는다 [출전약속검수]',()=>{const p=pp744Setup(),e=evNew('pt','이전 갈등','시험',Array.from({length:4},(_,i)=>({l:'선택'+i,fx:''})),{data:{pid:p.id},ref:p.id});p.promise=mkPromise(p,30);lineFor(p,G.year,p.team,'1군').pa+=20;G.day+=2;const before=JSON.stringify(p.promise),m=p.mor;evPick(e.id,1);ok(JSON.stringify(p.promise)===before,'옛 카드가20타석 기준/기한 초기화');ok(p.mor===m,'중복 약속에 기분 보상 재지급');});
T('[검수 11-18 #749] 단장 이직 뒤에도 양쪽 구단 선수의 약속과 판정은 이어진다 [출전약속검수]',()=>{const p=pp744Setup(),u=G.user,v=otherT(),q=domestic(v).find(x=>!x.isP&&!x.foreign);p.promise=mkPromise(p,30);q.promise=mkPromise(q,30);const a=JSON.stringify(p.promise),b=JSON.stringify(q.promise);switchTeam(v);leaveSweep();ok(p.team===u&&JSON.stringify(p.promise)===a,'원 구단에 남은 선수약속 삭제');ok(JSON.stringify(q.promise)===b,'새 구단 기존약속 변경');lineFor(p,G.year,u,'1군').pa+=30;if(typeof playPromiseTick==='function')playPromiseTick();else moraleWeek();ok(!p.promise&&(p.morL||[]).some(x=>x[1]==='prom'&&x[2]===5),'옛 구단 AI 약속 이행 누락');});
T('[검수 11-18 #750] 이적 후 과거 약속 위반은 당시 구단 이름을 표시한다 [출전약속검수]',()=>{const p=pp744Setup(),u=p.team,v=otherT(),nm=tshort(u);p.promise=mkPromise(p,30);p.promise.until=G.day;moraleWeek();ok((p.morL||[]).some(x=>x[1]==='prom'&&x[2]<0),'위반 기록 준비');p.team=v;mvLog('트레이드',p,u,v,'검수');const r=moraleList(p).find(x=>x.k==='prom'&&x.v<0);ok(r&&r.t.includes(nm)&&/이전 구단/.test(r.t),'새 구단 카드에서 전 구단 위반 출처 누락 '+r?.t);});
T('[검수 11-18 #746 #747 호환] 옛 전 구단 합계 기준은 소속 구단 기준으로 한 번만 복원한다 [출전약속검수]',()=>{const p=pp744Setup(),old=otherT();lineFor(p,G.year,old,'1군').pa=320;lineFor(p,G.year,p.team,'1군').pa=30;p.promise={tid:p.team,until:G.day+10,b:{y:G.year,pa:320,outs:0,g:0}};const rng=__rngState();if(typeof playPromiseFix==='function')playPromiseFix();ok(p.promise.b.tid===p.team&&p.promise.b.pa===0&&playPromKept(p),'옛 합계320 기준을 현재구단0 기준으로 못 복원');const before=JSON.stringify(p.promise);playPromiseFix();ok(JSON.stringify(p.promise)===before&&__rngState()===rng,'약속복원 비멱등/난수사용');});
T('[검수 11-18 #746 #747 투수] 해를 넘긴 5이닝·4경기 이행은 한 번만 보상하고 미달 부상만 미룬다 [출전약속검수]',()=>{pp744Setup();const p=domestic(G.user).find(q=>q.isP&&!q.foreign),y=G.year;p.hist=p.hist.filter(h=>h.y!==y);const h=lineFor(p,y,p.team,'1군');h.outs=6;h.g=2;p.promise=mkPromise(p,30);h.outs+=15;G.year++;G.cal=buildCalendar(G.year);G.sea.y=G.year;G.day=G.cal.open+1;ok(playPromKept(p),'작년약속 뒤15아웃 누락');const m=p.mor;playPromiseTick();const after=p.mor,rng=__rngState();playPromiseTick();ok(after===Math.min(100,m+5)&&p.mor===after&&!p.promise&&__rngState()===rng,'이행보상중복/난수');const q=domestic(G.user).find(x=>x.isP&&x!==p&&!x.foreign);q.hist=q.hist.filter(x=>x.y!==G.year);const z=lineFor(q,G.year,q.team,'1군');q.promise=mkPromise(q,30);z.g+=4;ok(playPromKept(q),'약속뒤4경기누락');q.promise.b.g=4;q.promise.until=G.day;q.injOut=20;moraleWeek();ok(q.promise&&q.promise.until>G.day,'미달 부상 약속을 잘못 완료/위반처리');});
T('[검수 11-18 #748 완료 뒤] 옛 갈등 카드가 끝난 약속을 다시 만들지 않고 새 카드는 새 약속을 만들 수 있다 [출전약속검수]',()=>{const p=pp744Setup(),e=evNew('pt','이전 갈등','시험',Array.from({length:4},(_,i)=>({l:'선택'+i,fx:''})),{data:{pid:p.id,promN:p.playPromN||0},ref:p.id});G.day++;p.promise=mkPromise(p,30);lineFor(p,G.year,p.team,'1군').pa+=30;playPromiseTick();ok(!p.promise,'먼저새약속이행완료');G.day++;const m=p.mor;evPick(e.id,1);ok(!p.promise&&p.mor===m,'완료 뒤 옛카드가 새약속/보상 재생성');let seed=1;while(withRng(seed,()=>R())<.9)seed++;const freshEvent=withRng(seed,()=>EVH.pt.make(p));ok(freshEvent&&freshEvent.data.promN===(p.playPromN||0),'실제새갈등카드 약속세대 미귀속');evPick(freshEvent.id,1);ok(p.promise&&p.promise.b.pa===30&&p.promise.n===p.playPromN,'완료뒤 실제새카드의새약속 불가');});

function cp751Setup(){fresh();const p=domestic(G.user).find(p=>!p.foreign&&!p.isP);G.cal.end=G.cal.open+180;G.day=G.cal.end+1;p.injOut=0;p.injHist=[];p.hist=[];p.ctT=G.user;p.faC=true;p.yrs=2;p.mor=60;return p;}
T('[검수 11-18 #751] 겹친 부상은 합집합 결장57일만 세고 출전 기준 판정을 면제하지 않는다 [계약약속검수]',()=>{const p=cp751Setup(),a=G.cal.open;p.injHist=[{d:a+10,days:52,bk:a+62},{d:a+15,days:52,bk:a+67}];p.hist=[{...ZB,y:G.year,t:G.user,lvl:'1군',pa:0}];ok(cpromPt(p,{c:'pa',n:100},G.year)===false,'실제57일을104일로 합쳐 판정 면제');});
T('[검수 11-18 #752] 예상70일보다 이른11일 실제 복귀를 출전량 약속에 반영한다 [계약약속검수]',()=>{const p=cp751Setup(),a=G.cal.open;p.injHist=[{d:a+10,days:70,bk:a+21}];p.hist=[{...ZB,y:G.year,t:G.user,lvl:'1군',pa:65}];ok(cpromPt(p,{c:'pa',n:100},G.year)===false,'실제11일 대신 예상70일로 출전량 이행');});
T('[검수 11-18 #753] 내년 합류 예정 포수는 올해 포수 보강으로 인정하지 않는다 [계약약속검수]',()=>{const p=cp751Setup(),d=G.day;G.day++;const q=newPlayer({age:26,isP:false,pos:'C',base:60,pot:60,team:G.user});q.mvD=G.day;q.joinY=G.year+1;ok(!cpromSg(p,{tid:G.user},{k:'sg',g:'C',d,y0:G.year,y1:G.year}),'내년 입단으로 올해 보강 달성');});
T('[검수 11-18 #754] 지명타자 한 명으로 내야와 외야 보강을 충족할 수 없다 [계약약속검수]',()=>{const p=cp751Setup(),d=G.day;G.day++;const q=newPlayer({age:26,isP:false,pos:'DH',base:60,pot:60,team:G.user});q.mvD=G.day;const x={k:'sg',d,y0:G.year,y1:G.year};ok(!cpromSg(p,{tid:G.user},{...x,g:'IF'})&&!cpromSg(p,{tid:G.user},{...x,g:'OF'}),'DH를 IF/OF 양쪽 보강으로 인정');});
T('[검수 11-18 #755] 약속 뒤 실제 영입 이행은 점검 전 선수가 다시 떠나도 같은 약속에 남는다 [계약약속검수]',()=>{const p=cp751Setup(),other=G.teams.find(t=>t.id!==G.user).id;p.mor=60;pmApply(p,{pm:{sg:'C',d:G.day}},G.year,1);const C=p.cprom,x=C.L[0];G.day++;const q=newPlayer({age:26,isP:false,pos:'C',base:60,pot:60,team:other});mvLog('트레이드',q,other,G.user);q.team=G.user;ok(cpromSg(p,C,x),'최초 포수 보강 이행 준비');G.day++;mvLog('트레이드',q,G.user,other);q.team=other;ok(cpromSg(p,C,x),'영입 뒤 떠났다고 보강 약속 이행 소멸');cpromSeason(G.year);ok(p.mor===63,'시즌 보강 판정이 실제 이행을 위반으로 변경 '+p.mor);});
T('[검수 11-18 #751 경계] 부상 합집합은 시즌 양끝을 자르고 순서 중복 해외훈련 기록과 무관하게 하루만 센다 [계약약속검수]',()=>{const p=cp751Setup(),a=G.cal.open,b=G.cal.end;p.injHist=[{d:a-10,days:30,bk:a+20},{d:a+10,days:30,bk:a+40},{d:b-10,days:30,bk:b+20},{d:a+10,days:30,bk:a+40,ovs:1}];const keep=JSON.stringify(G),rng=__rngState();ok(promiseInjDays(p,a,b)===50,'시즌 내 합집합50일 오류 '+promiseInjDays(p,a,b));p.injHist.reverse();ok(promiseInjDays(p,a,b)===50,'이력 순서에 따라 결장일 다름');p.injHist.reverse();ok(JSON.stringify(G)===keep&&__rngState()===rng,'결장일 조회 상태/RNG 변경');});
T('[검수 11-18 #752 월간] 주전 보장 유예는 최초70일 예상 대신 실제 복귀11일 뒤28일을 센다 [계약약속검수]',()=>{const p=cp751Setup();G.day=dnum(G.year,7,1);G.ps=null;p.ys=false;p.injOut=0;p.joinY=G.year;p.hold=false;p.roleProm={k:0,t:'B',until:G.year,l:'주전 보장'};for(const k in p.r)p.r[k]=20;p.injHist=[{d:G.day-50,days:70,bk:G.day-39}];const before=p.mor;rolePromCheck(7);ok(p.mor===before-6,'실제 복귀 후39일인데 최초 예상 기간으로 월간 점검 유예 '+p.mor);p.mor=60;p.injHist[0].bk=G.day-27;rolePromCheck(7);ok(p.mor===60,'실제 복귀 뒤28일 이전에도 약속 위반 처리');});
T('[검수 11-18 #753 #755 시점] 같은 날 약속 전 영입과 약속 뒤 영입은 이동 순번으로 구분한다 [계약약속검수]',()=>{const p=cp751Setup(),other=G.teams.find(t=>t.id!==G.user).id,q=newPlayer({age:26,isP:false,pos:'C',base:60,pot:60,team:other});mvLog('트레이드',q,other,G.user);q.team=G.user;pmApply(p,{pm:{sg:'C',d:G.day}},G.year,1);let C=p.cprom,x=C.L[0];ok(!cpromSg(p,C,x),'같은 날 약속 전에 영입한 포수로 새 약속 소급 달성');const z=newPlayer({age:26,isP:false,pos:'C',base:60,pot:60,team:other});mvLog('트레이드',z,other,G.user);z.team=G.user;ok(cpromSg(p,C,x),'같은 날 약속 뒤 실제 영입도 누락');x.d++;ok(!cpromSg(p,C,x),'새 시작일 약속에 옛 이행 근거 재사용');});
T('[검수 11-18 #755 보관] 영입 이행은 명단 이동 기록 선수 삭제 뒤에도 원래 약속에 보관되고 조회는 순수하다 [계약약속검수]',()=>{const p=cp751Setup(),other=G.teams.find(t=>t.id!==G.user).id;pmApply(p,{pm:{sg:'C',d:G.day}},G.year,1);G.day++;const q=newPlayer({age:26,isP:false,pos:'C',base:60,pot:60,team:other});mvLog('트레이드',q,other,G.user);q.team=G.user;ok(p.cprom.L[0].sgKept,'실제 이동에 이행 증거 미기록');G.day++;mvLog('트레이드',q,G.user,other);q.team=other;G.moves=[];delete G.players[q.id];p.cprom=JSON.parse(JSON.stringify(p.cprom));const before=JSON.stringify(G),rng=__rngState();ok(cpromSg(p,p.cprom,p.cprom.L[0]),'저장/압축 뒤 실제 이행 분실');ok(JSON.stringify(G)===before&&__rngState()===rng,'이행 조회 상태/RNG 변경');});
T('[검수 11-18 #755 호환] 옛 이동 장부의 실제 포지션 능력 날짜를 복원하되 약속 전 이동은 소급하지 않는다 [계약약속검수]',()=>{const p=cp751Setup(),other=G.teams.find(t=>t.id!==G.user).id,d=G.day-10,q=newPlayer({age:26,isP:false,pos:'DH',base:30,pot:30,team:other});q.joinY=G.year;const C={tid:G.user},x={k:'sg',g:'C',d,y0:G.year,y1:G.year};G.moves=[{pid:q.id,from:other,to:G.user,y:G.year,d:d+1,o:60,pos:'포수'}];ok(cpromSg(p,C,x),'현재 타팀/지명타자/능력 하락 때문에 옛 포수 영입을 무시');G.moves[0].d=d-1;ok(!cpromSg(p,C,x),'약속 전 포수 영입을 소급 인정');});
T('[검수 11-18 #753 #755 AI] AI 계약도 같은 영입 증거를 남기며 미래 합류 거래는 현재 이행 근거가 되지 않는다 [계약약속검수]',()=>{cp751Setup();const ai=G.teams.find(t=>t.id!==G.user).id,p=domestic(ai).find(p=>!p.foreign&&!p.isP);pmApply(p,{pm:{sg:'C',d:G.day}},G.year,1);const q=newPlayer({age:26,isP:false,pos:'C',base:60,pot:60,team:G.user});q.joinY=G.year+1;G.day++;mvLog('트레이드',q,G.user,ai);q.team=ai;ok(!cpromSg(p,p.cprom,p.cprom.L[0])&&!p.cprom.L[0].sgKept,'AI 미래 합류로 현재 이행');const z=newPlayer({age:26,isP:false,pos:'C',base:60,pot:60,team:G.user});mvLog('트레이드',z,G.user,ai);z.team=ai;ok(cpromSg(p,p.cprom,p.cprom.L[0])&&p.cprom.L[0].sgKept,'AI 실제 보강에 같은 증거를 남기지 않음');});
T('[검수 11-18 #755 연도] 연도 필드 없는 이동도 실제 날짜로 판정해 다음 시즌 영입을 과거 약속에 소급하지 않는다 [계약약속검수]',()=>{const p=cp751Setup(),other=G.teams.find(t=>t.id!==G.user).id,q=newPlayer({age:26,isP:false,pos:'C',base:60,pot:60,team:other}),y=G.year,x={k:'sg',g:'C',d:dnum(y,3,1),y0:y,y1:y};G.moves=[{pid:q.id,from:other,to:G.user,d:dnum(y+1,1,2),o:60,pos:'포수'}];ok(!cpromSg(p,{tid:G.user},x,y),'다음 해 무연도 장부를 전년도 약속에 소급');G.moves[0].d=dnum(y,4,1);ok(cpromSg(p,{tid:G.user},x,y),'날짜로 증명한 같은 시즌 영입까지 제외');});
T('[검수 11-18 #755 이동 증거] 합류 전 이동 훅은 원래 구단 상태에서도 이행을 한 번만 기록하고 난수를 쓰지 않는다 [계약약속검수]',()=>{const p=cp751Setup(),other=G.teams.find(t=>t.id!==G.user).id;pmApply(p,{pm:{sg:'C',d:G.day}},G.year,1);G.day++;const q=newPlayer({age:26,isP:false,pos:'C',base:60,pot:60,team:other}),rng=__rngState();cpromAcquire(q,other,G.user);ok(q.team===other&&p.cprom.L[0].sgKept&&__rngState()===rng,'합류 전 훅의 이행 누락/소속/RNG 변경');const saved=JSON.stringify(G);cpromAcquire(q,other,G.user);ok(JSON.stringify(G)===saved&&__rngState()===rng,'이미 기록한 이행을 반복 변경');});
T('[검수 11-18 #755 구형 이행] 옛 영입 장부가 압축돼도 실제로 소속 중 충족한 보강은 떠날 때 이행 증거로 남는다 [계약약속검수]',()=>{const p=cp751Setup(),other=G.teams.find(t=>t.id!==G.user).id;pmApply(p,{pm:{sg:'C',d:G.day}},G.year,1);G.day++;const q=newPlayer({age:26,isP:false,pos:'C',base:60,pot:60,team:G.user});q.mvD=G.day;G.moves=[];ok(cpromSg(p,p.cprom,p.cprom.L[0]),'구형 저장 현재 충족 상태 준비');G.day++;mvLog('트레이드',q,G.user,other);q.team=other;G.moves=[];ok(cpromSg(p,p.cprom,p.cprom.L[0]),'구형 현재 이행을 실제 이탈 시점에 보관하지 않음');});

function fr756setup(){fresh();G.day=G.cal.open+20;G.entryY=G.year;G.flOn=true;G.futLn={};const tid=G.user,m=G.mgr[tid];mgrFix(m);m.ego=10;m.rel=99;for(const p of playersOf(tid)){p.e1=false;p.ys=false;p.prospect=false;p.joinY=G.year;p.injOut=0;p.susp=0;p.boy=0;p.hold=false;p.frehab=false;p.fLeave=0;p.ntAway=0;p.mil=null;p.ld=[];p.fat=0;delete p.downDay;delete p.futReq;}return {tid,m,B:playersOf(tid).filter(p=>!p.isP&&hn('req'+G.day,p.id)>-1.2),P:playersOf(tid).filter(p=>p.isP)};}
T('[검수 11-18 #756] 실제 콜업 뒤 말소해도 옛 2군 기용 요청은 되살아나 활성4명을 넘지 않는다 [퓨처스요청검수]',()=>{const {tid,B}=fr756setup();ok(B.length>=8,'타자8명 준비');const old=B.slice(0,4),next=B.slice(4,8);for(const p of old)ok(talkOutcome(p,'futreq',{}).out==='fr_ok','첫 요청 거절');const rng=FO_RNG;try{FO_RNG=()=>0;for(const p of old){const r=reqEntry(p.id,true);ok(p.e1,'콜업 준비 실패 '+r);}}finally{FO_RNG=rng;}ok(futReqList(tid).length===0,'콜업 선수 요청이 활성');for(const p of next)ok(talkOutcome(p,'futreq',{}).out==='fr_ok','새4명 요청 거절');for(const p of old){p.e1=false;p.downDay=G.day;}ok(futReqList(tid).length<=4&&!old.some(futReqOn),'콜업 전 요청이 되살아남 '+futReqList(tid).length);});
T('[검수 11-18 #757] 장기 부상으로 뛸 수 없는 요청4명은 출전 가능한 다섯 번째 요청을 막지 않는다 [퓨처스요청검수]',()=>{const {tid,B}=fr756setup();for(const p of B.slice(0,4)){talkOutcome(p,'futreq',{});p.injOut=30;}const p=B[4],o=talkOutcome(p,'futreq',{});ok(o.out==='fr_ok'&&p.futReq,'장기 부상4명 때문에 가용선수 요청 거절 '+o.line);ok(futReqList(tid).length<=4&&!B.slice(0,4).some(futReqOn),'부상선수를 활성 요청에 포함');for(const q of B.slice(0,4))q.injOut=0;ok(futReqList(tid).length===4&&futReqOn(p)&&B.slice(0,5).filter(futReqOn).length===4,'기존4명 복귀 후5명 우선권 부활');const before=JSON.stringify(G),rng=__rngState();for(let i=0;i<3;i++){futReqList(tid);B.slice(0,5).forEach(futReqOn);}ok(JSON.stringify(G)===before&&__rngState()===rng,'조회가 상태나 난수를 바꿈');});
T('[검수 11-18 #758] 우선 요청이 만료되면 기존 주간 로테이션 대신 현재 유효 선발 기준을 쓴다 [퓨처스요청검수]',()=>{const {tid,P}=fr756setup();ok(P.length>=7,'투수7명 준비');for(const p of P){p.r.stf=70;p.r.ctl=70;p.r.sta=70;p.role='RP';}const p=P[0];p.r.stf=20;p.r.ctl=20;p.r.sta=20;p.futReq={until:G.day+1};futuresWeek();ok(G.futLn[tid].rot[0]===p.id,'주간 우선 로테이션 준비');G.day+=2;flInit();G.fl.rot[tid]=0;ok(!futReqOn(p),'만료 준비');const s=flSide(tid,G.day);ok(s&&s.sp.id!==p.id,'만료된 요청 투수가 캐시로 선발 재등판');});
T('[검수 11-18 #759] 비시즌과 훈련 불참에는 2군 주전 요청도 기분 보너스도 주지 않는다 [퓨처스요청검수]',()=>{const {B}=fr756setup(),p=B[0];G.day=dnum(G.year,12,15);let o=talkOutcome(p,'futreq',{});ok(!p.futReq&&o.d===0,'비시즌 요청 접수·기분 보너스 '+o.line);G.day=G.cal.open+20;p.boy=G.day+12;o=talkOutcome(p,'futreq',{});ok(!p.futReq&&o.d===0,'훈련 불참 요청 접수·기분 보너스 '+o.line);});
T('[검수 11-18 #760] 부상 선수 포지션 건의는 일반 건의와 같은 불가 사유로 끝나 관계를 깎지 않는다 [퓨처스요청검수]',()=>{const {B,m}=fr756setup(),p=B[0];p.pos='1B';p.pexp={'3B':60};for(const k of Object.keys(p.r))p.r[k]=20;p.injOut=10;m.ego=90;m.rel=50;const r=mgrUseAsk(p.id,'pos:3B');ok(r.sys.includes('부상'),'포지션 건의 부상 가드 건너뜀 '+r.sys);ok(m.rel===50&&!G.posAsk?.[p.id]&&!G.useNo?.[p.id],'불가 선수에게 감독 경쟁 판정·관계 감점');});
T('[검수 11-18 #761] 직전 팀 경기 DNP 뒤에도 최근2일 안의 본인 활약을 면담에서 찾는다 [퓨처스요청검수]',()=>{const {tid,B}=fr756setup(),p=B[0],op=otherT();G.games=[{day:G.day,home:tid,away:op,box:{h:{bat:[],pit:[]},a:{bat:[],pit:[]}}},{day:G.day-1,home:tid,away:op,box:{h:{bat:[{id:p.id,ab:5,h:4,hr:1}],pit:[]},a:{bat:[],pit:[]}}}];const e=talkEvent(p);ok(e&&e.k==='good'&&e.d===G.day-1&&e.t.includes('4안타')&&e.t.includes('1홈런'),'직전 결장 때문에 본인 활약 면담 누락');});

T('[검수 11-18 #756·757] 저장 복원 뒤에도 실제 로테이션 우선권은 최근 가용4명까지만 적용한다 [퓨처스요청검수]',()=>{const {tid}=fr756setup(),P=flPool(tid,G.day).P;ok(P.length>=9,'투수9명 준비');for(const p of P){p.r.stf=75;p.r.ctl=75;p.r.sta=75;p.role='RP';}const old=P.slice(0,4),next=P[4];for(const p of old){p.r.stf=10;p.r.ctl=10;p.r.sta=10;talkOutcome(p,'futreq',{});p.injOut=30;}next.r.stf=10;next.r.ctl=10;next.r.sta=10;ok(talkOutcome(next,'futreq',{}).out==='fr_ok','다섯째 가용 요청 거절');old.forEach(p=>p.injOut=0);const selected=futReqList(tid).map(p=>p.id),dropped=old.find(p=>!futReqOn(p));ok(selected.length===4&&selected.includes(next.id)&&dropped,'우선권 한도 또는 최신 요청 누락');G=JSON.parse(JSON.stringify(G));ok(JSON.stringify(futReqList(tid).map(p=>p.id))===JSON.stringify(selected),'저장 복원으로 우선권 변경');flInit();G.fl.rot[tid]=0;const side=flSide(tid,G.day);ok(side&&side.spAll.slice(0,4).every(p=>selected.includes(p.id))&&!side.spAll.some(p=>p.id===dropped.id),'실제 선발 후보에 비활성 요청 가산 '+JSON.stringify({selected,dropped:dropped.id,rot:side?.spAll.map(p=>p.id),pool:flPool(tid,G.day).P.map(p=>p.id)}));});

function pc747(){fresh();G.day=G.cal.open+110;const U=G.user,V=otherT(),p=domestic(U).find(x=>!x.isP&&!x.foreign&&!x.ys);p.hist=p.hist.filter(h=>h.y!==G.year);p.mor=60;p.pers={pro:10,amb:10,loy:15,temp:10};delete p.promise;delete p.morL;delete p.grv;delete p.playPromLast;G.mail=[];G.evs=[];return {U,V,p};}
T('[검수 11-18 교차 #747 #749] 단장 이직 뒤 원구단의 완료 약속은 새해 재독 후에도 한 번 이행되고 같은 구단으로 표시한다 [선수교차검토]',()=>{const {U,V,p}=pc747(),id=p.id,y=G.year;p.promise=mkPromise(p,30);lineFor(p,y,U,'1군').pa+=30;switchTeam(V);G.year=y+1;G.cal=buildCalendar(G.year);G.sea.y=G.year;G.day=G.cal.open+2;G=JSON.parse(JSON.stringify(G));playPromiseFix();const q=G.players[id],rng=__rngState(),before=q.mor;playPromiseTick();const m=moraleList(q).find(x=>x.k==='prom');ok(!q.promise&&q.playPromLast?.kept&&q.playPromLast.tid===U&&q.mor===Math.min(100,before+5),'옛 구단 AI가 새해 약속 이행 누락/위반');ok(m&&m.t.includes(tshort(U))&&!m.t.includes('이전 구단'),'단장만 이직했는데 선수 현재구단의 약속을 이전구단으로 표시 '+m?.t);ok(!G.mail.some(x=>x.ref===id&&(x.subj||'').includes('면담')),'새 구단 사용자에게 옛 구단 선수 이행 통지');const a=JSON.stringify([q.playPromLast,q.mor,q.morL,q.grv]);playPromiseTick();ok(JSON.stringify([q.playPromLast,q.mor,q.morL,q.grv])===a&&__rngState()===rng,'같은 약속 재보상/주 난수 변경');});
T('[검수 11-18 교차 #748] 먼저 열린 갈등 카드는 이후 이행 완료한 약속을 새 약속으로 다시 열지 않는다 [선수교차검토]',()=>{const {p}=pc747(),e=evNew('pt','이전 갈등','시험',Array.from({length:4},(_,i)=>({l:'선택'+i,fx:''})),{data:{pid:p.id},ref:p.id});G.day++;p.promise=mkPromise(p,30);lineFor(p,G.year,p.team,'1군').pa+=30;G.day++;playPromiseTick();ok(!p.promise&&p.playPromLast?.kept,'기존 약속 이행 준비');const m=p.mor,old=JSON.stringify(p.playPromLast);evPick(e.id,1);ok(!p.promise&&p.mor===m&&JSON.stringify(p.playPromLast)===old,'해결된 옛 카드로 새 약속/기분 보상 생성 '+JSON.stringify(p.promise));});
T('[검수 11-18 교차 #737] GM 부재 중 AI가 바꾼 기강은 재독·재취임 후에도 실제 기강 계산에 한 번 반영한다 [선수교차검토]',()=>{const {U,V}=pc747();leadAdjSet(U,{v:6,until:G.day+45});leadAdjSet(V,{v:3,until:G.day+30});switchTeam(V);leadAdjBoost(U,3,45);const r=__rngState();G=JSON.parse(JSON.stringify(G));leadAdjMigrate();const a=climateOf(U).S;const saved=leadAdjOf(U);leadAdjSet(U,{v:0,until:saved.until});const base=climateOf(U).S;leadAdjSet(U,saved);ok(a-base===9,'AI 원구단 기강이 실제 수치에 누락/중복 '+a+'/'+base);switchTeam(U);ok(leadAdjOf(U)?.v===9&&leadAdjOf(V)?.v===3&&climateOf(U).S===a,'재취임이 타구단/원구단 기강을 덮음');const b=JSON.stringify([G.leadAdj,G.leadAdjT,G.leadAdjTid]);leadAdjMigrate();ok(JSON.stringify([G.leadAdj,G.leadAdjT,G.leadAdjTid])===b,'재취임 후 복원 비멱등');});
T('[검수 11-18 교차 #756] 자동 엔트리 보강·부상 말소·회복·재독 후에도 옛 우선기용이 새4명을 밀어내지 않는다 [선수교차검토]',()=>{const {U}=pc747();G.day=G.cal.open+20;G.entryY=G.year;G.flOn=true;for(const p of playersOf(U)){p.e1=false;p.ys=false;p.prospect=false;p.joinY=G.year;p.injOut=0;p.susp=0;p.boy=0;p.hold=false;p.frehab=false;p.fLeave=0;p.ntAway=0;p.mil=null;delete p.downDay;delete p.upDay;delete p.futReq;for(const k in p.r)p.r[k]=60;}const B=playersOf(U).filter(p=>!p.isP),old=B.slice(0,4),next=B.slice(4,8);for(const p of old)ok(talkOutcome(p,'futreq',{}).out==='fr_ok','첫4명 요청 준비');entryUpgrade(U,old,'교차 자동콜업');ok(old.every(p=>p.e1)&&futReqList(U).length===0,'자동 콜업 경로 준비');for(const p of next){for(const k in p.r)p.r[k]=20;ok(talkOutcome(p,'futreq',{}).out==='fr_ok','새4명 요청 준비');}for(const p of old)p.injOut=4;entryManage(U,false,true);ok(old.every(p=>!p.e1)&&next.every(p=>!p.e1),'자동 부상 말소/새 요청 대기 준비');for(const p of old)p.injOut=0;const oldIds=old.map(p=>p.id),ids=next.map(p=>p.id).sort((a,b)=>a-b);G=JSON.parse(JSON.stringify(G));const rng=__rngState(),state=JSON.stringify(G),live=futReqList(U).map(p=>p.id).sort((a,b)=>a-b);ok(JSON.stringify(live)===JSON.stringify(ids)&&!oldIds.some(id=>futReqOn(G.players[id])),'자동 콜업 전 요청이 재독 후 새 요청을 밀어냄');ok(futReqList(U).length===4&&__rngState()===rng&&JSON.stringify(G)===state,'최대4/순수조회/난수 불변 위반');});

T('[검수 11-18 #737 #747 #749 통합 복원] 실제 저장 로더는 이직한 원구단의 약속과 양쪽 기강을 재독해도 보존한다 [선수통합검수]',()=>{const {U,V,p}=pc747(),id=p.id,y=G.year;leadAdjSet(U,{v:6,until:G.day+500});leadAdjSet(V,{v:3,until:G.day+500});p.promise=mkPromise(p,30);lineFor(p,y,U,'1군').pa+=30;switchTeam(V);G.year=y+1;G.cal=buildCalendar(G.year);G.sea.y=G.year;G.day=G.cal.open+2;const check=()=>{const q=G.players[id];ok(q.promise?.tid===U&&playPromKept(q),'실제 복원에서 원구단 완료 약속이 사라짐');ok(leadAdjOf(U)?.v===6&&leadAdjOf(V)?.v===3,'실제 복원에서 구단 기강 혼합');return JSON.stringify([q.promise,q.playPromLast,q.mor,leadAdjOf(U),leadAdjOf(V),G.teams.map(t=>[t.cap,t.capName])]);};G=JSON.parse(JSON.stringify(G));migrateDraft();const one=check();G=JSON.parse(JSON.stringify(G));migrateDraft();ok(check()===one,'실제 로더 반복이 약속·기강·주장 귀속을 바꿈');});
T('[검수 11-18 #746 #749 통합 진행] 실제 하루 처리 끝에 전 구단 선수의 이미 채운 약속도 한 번 이행된다 [선수통합검수]',()=>{const {U,V,p}=pc747(),id=p.id;p.promise=mkPromise(p,30);lineFor(p,G.year,U,'1군').pa+=30;switchTeam(V);G.stops=[];processDay();const q=G.players[id];ok(!q.promise&&q.playPromLast?.kept&&q.playPromLast.tid===U,'실제 하루 진행에서 AI 원구단 이행 누락');const rows=()=>JSON.stringify((q.morL||[]).filter(x=>x[1]==='prom'));const one=rows();ok((q.morL||[]).filter(x=>x[1]==='prom'&&x[2]===5).length===1,'하루 진행 이행 보상 누락/중복');playPromiseTick();ok(rows()===one,'끝난 약속을 다시 보상');ok(!G.mail.some(m=>m.ref===id&&(m.subj||'').includes('면담')),'새 구단에 옛 구단 선수 약속 메일 전송');});
function gp762Setup(){fresh();G.day=G.cal.open+10;G.ps=null;G.entryY=G.year;G.res=null;G.stops=[];for(const t of G.teams){for(const p of playersOf(t.id)){p.injOut=0;p.fat=0;p.hold=false;p.frehab=false;p.fLeave=0;p.boy=0;p.susp=0;if(p.isP){p.ld=[];delete p.lastApp;delete p.lastStart;}}setEntry(t.id);}const h=G.user,a=G.teams.find(t=>t.id!==h).id;G.fl={y:G.year,rot:{},games:[],rec:Object.fromEntries(G.teams.map(t=>[t.id,{w:0,l:0,d:0,rs:0,ra:0}]))};return {h,a,d:G.day};}
function gp762Arm(tid){const m=G.mgr[tid];m.interim=false;G.mgrDir={arm:{ok:true,mid:m.id}};ok(armDirOn(tid),'투수 관리 지시 준비');}
function gp762Farm(h,a,d){for(const p of Object.values(G.players))if((p.team===h||p.team===a)&&!p.isP){p.e1=false;p.r.def=65;}return {h:flSide(h,d),a:flSide(a,d)};}
T('[검수 11-18 #762] 선발 불펜 후보 전원이 당일 던졌으면 이미 쓴 선발 대신 후보 없음으로 처리한다 [투수자격검수]',()=>{const {h,d}=gp762Setup(),D=depth(h);for(const p of [...D.sp,...D.pen])p.lastApp=d;const before=JSON.stringify(G),rng=__rngState();ok(pickStarter(h,D,d,false)===null,'전원 당일 등판인데 선발 재선택');ok(JSON.stringify(G)===before&&__rngState()===rng,'후보 없음 조회가 상태/RNG 변경');});
T('[검수 11-18 #763] 혹사 금지의 비상 교체도 당일 등판 투수를 재투입하지 않고 계속 투구를 명시한다 [투수자격검수]',()=>{const {h,a,d}=gp762Setup();gp762Arm(h);const S={h:gameSide(h,d,false),a:gameSide(a,d,false)};for(const p of actOf(h).filter(p=>p.isP&&p.id!==S.h.sp.id)){p.lastApp=d;p.fat=95;}S.h.box.get(S.h.sp.id).pc=100;const g=simGame(d,h,a,false,{sides:S,pitchRecords:false});const repeated=S.h.pitchers.slice(1).filter(id=>G.players[id].lastApp===d);ok(!repeated.length,'관리 지시가 당일 투수 재등판 '+repeated.join(','));ok((S.h.armEmergency||[]).length>0&&g.ev.some(e=>e.t.includes('비상 계속 투구')),'대체 후보 없는 계속 투구 예외 표시 없음');});
T('[검수 11-18 #764] 실제 퓨처스 불펜 소진 뒤에도 1군 등록 투수의 등판 기록과 피로를 건드리지 않는다 [투수자격검수]',()=>{const {h,a,d}=gp762Setup();gp762Arm(h);const first=actOf(h).filter(p=>p.isP),ids=first.map(p=>p.id),snap=JSON.stringify(first.map(p=>[p.id,p.fat,p.ld,p.hist]));const S=gp762Farm(h,a,d);ok(S.h&&S.a&&ids.length>0,'실제 퓨처스/1군 명단 준비');const allowed=new Set([S.h.sp.id,...S.h.pen.map(p=>p.id),...S.h.spAll.map(p=>p.id)]);for(const p of [...S.h.pen,...S.h.spAll])S.h.used.add(p.id);S.h.curIsSP=false;S.h.box.get(S.h.cur.id).outs=3;S.h.box.get(S.h.cur.id).pc=35;const g=simGame(d,h,a,false,{sides:S,pitchRecords:false});applyFarm(d,g);ok(S.h.pitchers.every(id=>allowed.has(id)),'퓨처스가 허가 명단 밖 투수 호출 '+S.h.pitchers.filter(id=>!allowed.has(id)).join(','));ok(JSON.stringify(ids.map(id=>{const p=G.players[id];return[p.id,p.fat,p.ld,p.hist];}))===snap,'1군 투수에 퓨처스 피로/등판 기록 반영');});
T('[검수 11-18 #769] 실제 대승 휴식 교체로 빠진 퓨처스 선발 야수도 저장 박스에 남긴다 [투수자격검수]',()=>{const {h,a,d}=gp762Setup();G.mgr[h].rest=85;const S=gp762Farm(h,a,d),out=outcome;let hr=0,g;try{outcome=(b,p,dv,fp,fs)=>fs.tid===a&&hr++<9?'HR':'OUT';g=simGame(d,h,a,false,{sides:S,pitchRecords:false});}finally{outcome=out;}const replaced=S.h.out.filter(p=>(S.h.box.get(p.id)?.pa||0)>0);ok(replaced.length>=1,'실제 대승 교체 준비 실패');flRecord(G.fl,d,h,a,g);const box=G.fl.games[G.fl.games.length-1].box.h.bat,missing=replaced.filter(p=>!box.some(r=>r[0]===p.id));ok(!missing.length,'출장한 교체 선발이 저장 박스에서 빠짐 '+missing.map(p=>p.name).join(','));});
T('[검수 11-18 #762 경계] 후보 없으면 경기 구성에서 명시적으로 거절하고 가용 선발은 난수 없이 선택한다 [투수자격검수]',()=>{const {h,d}=gp762Setup(),D=depth(h);const rng=__rngState();ok(pickStarter(h,D,d,false)&&__rngState()===rng,'정상 선발 선택이 RNG 소비');for(const p of playersOf(h).filter(p=>p.isP))p.lastApp=d;let why='';try{gameSide(h,d,false);}catch(e){why=e.message;}ok(why.includes('등판 가능한'),'전원 당일 등판에서 경기 구성이 후보 없음 처리하지 않음 '+why);});
T('[검수 11-18 #763 등록] 임의 불펜 후보에 끼어도 미등록 투수는 호출하거나 자동 등록하지 않는다 [투수자격검수]',()=>{const {h,a,d}=gp762Setup();gp762Arm(h);const S={h:gameSide(h,d,false),a:gameSide(a,d,false)},outside=depth(h).futP.find(p=>!p.e1);ok(outside,'미등록 투수 준비');for(const p of actOf(h).filter(p=>p.isP&&p!==S.h.sp)){p.lastApp=d;p.fat=95;}outside.lastApp=d-10;outside.fat=0;S.h.pen.unshift(outside);S.h.spAll.push(outside);S.h.box.get(S.h.sp.id).pc=100;const ent=JSON.stringify(Object.values(G.players).map(p=>[p.id,p.e1,p.upDay,p.downDay]));simGame(d,h,a,false,{sides:S,pitchRecords:false});ok(!S.h.pitchers.includes(outside.id)&&!outside.e1,'등록 밖 후보를 비상 등판');ok(JSON.stringify(Object.values(G.players).map(p=>[p.id,p.e1,p.upDay,p.downDay]))===ent,'경기 중 등록 명단 자동 변경');});
T('[검수 11-18 #763 대체] 오늘 던지지 않은 등록 선발이 있으면 관리 지시의 합법 대체 투수로 쓴다 [투수자격검수]',()=>{const {h,a,d}=gp762Setup();gp762Arm(h);const S={h:gameSide(h,d,false),a:gameSide(a,d,false)},q=S.h.spAll.find(p=>p!==S.h.sp);for(const p of actOf(h).filter(p=>p.isP&&p!==S.h.sp)){p.lastApp=d;p.fat=95;}q.lastApp=d-5;q.lastStart=d-5;q.fat=0;S.h.box.get(S.h.sp.id).pc=100;simGame(d,h,a,false,{sides:S,pitchRecords:false});ok(S.h.pitchers.includes(q.id)&&S.h.pitchers.every(id=>id===S.h.sp.id||id===q.id),'합법 대체 선발을 제외하거나 당일 등판자를 함께 사용');});
T('[검수 11-18 #764 경계] 퓨처스 명단의 당일 등판자와 나중에 끼워 넣은 1군 후보 모두 제외한다 [투수자격검수]',()=>{const {h,a,d}=gp762Setup();gp762Arm(h);const outside=actOf(h).find(p=>p.isP),S=gp762Farm(h,a,d);for(const p of [...S.h.pen,...S.h.spAll])if(p!==S.h.sp)p.lastApp=d;S.h.pen.unshift(outside);S.h.spAll.push(outside);S.h.box.get(S.h.cur.id).pc=100;simGame(d,h,a,false,{sides:S,pitchRecords:false});ok(S.h.pitchers.length===1&&S.h.pitchers[0]===S.h.sp.id&&!S.h.box.has(outside.id),'허가 명단 밖/당일 투수가 퓨처스 교체 후보');});
T('[검수 11-18 #764 지시없음] 지시 없이 불펜이 소진돼도 허가된 현 투수가 계속 던지고 예외를 명시한다 [투수자격검수]',()=>{const {h,a,d}=gp762Setup();G.mgrDir={};const S=gp762Farm(h,a,d);for(const p of [...S.h.pen,...S.h.spAll])S.h.used.add(p.id);S.h.box.get(S.h.cur.id).pc=150;const g=simGame(d,h,a,false,{sides:S,pitchRecords:false});ok(S.h.pitchers.length===1&&(S.h.armEmergency||[]).length===1&&g.ev.some(e=>e.t.includes('이번 퓨처스 명단')),'퓨처스 소진 처리의 계속 투구 표식 누락');});
T('[검수 11-18 #764 상무] 원구단 등록 표시가 남은 복무 선수도 실제 상무 명단 안에서는 허용한다 [투수자격검수]',()=>{const {h,d}=gp762Setup(),A=G.teams.filter(t=>t.id!==h).map(t=>t.id),mil=Object.values(G.players).filter(p=>A.includes(p.team)&&!p.foreign&&!p.prospect),B=mil.filter(p=>!p.isP).slice(0,14),P=mil.filter(p=>p.isP).slice(0,12);for(const p of [...B,...P]){p.mil={unit:'상무',from:d-1,until:d+500};p.e1=true;p.injOut=0;p.fat=0;p.ld=[];delete p.lastApp;delete p.lastStart;}for(const p of playersOf(h))if(!p.isP)p.e1=false;const S={h:flSide(h,d),a:flSide(FL_SM,d)};ok(S.h&&S.a,'상무 실제 명단 준비');const allowed=new Set(S.a.pitchPool),g=simGame(d,h,FL_SM,false,{sides:S,pitchRecords:false});applyFarm(d,g);ok(S.a.pitchers.length>0&&S.a.pitchers.every(id=>allowed.has(id)),'상무 권한 명단을 잘못 제외/확장');const used=P.find(p=>S.a.pitchers.includes(p.id));ok(used&&(seasonTotal(used,G.year,'퓨처스')?.g||0)>0,'실제 상무 등판 기록 반영 안됨');});
T('[검수 11-18 #769 집계] 퓨처스 교체 박스는 출장 야수를 한 번씩 보관하며 실제 기록 합계와 같다 [투수자격검수]',()=>{const {h,a,d}=gp762Setup();G.mgr[h].rest=85;const S=gp762Farm(h,a,d),out=outcome;let hr=0,g;try{outcome=(b,p,dv,fp,fs)=>fs.tid===a&&hr++<9?'HR':'OUT';g=simGame(d,h,a,false,{sides:S,pitchRecords:false});}finally{outcome=out;}flRecord(G.fl,d,h,a,g);const rows=G.fl.games[G.fl.games.length-1].box.h.bat,actual=[...S.h.box].filter(([id])=>!S.h.pitchers.includes(id));ok(new Set(rows.map(r=>r[0])).size===rows.length&&rows.length===actual.length,'선발/교체 야수 중복 또는 누락');for(const [index,key] of [[2,'ab'],[3,'r'],[4,'h'],[5,'rbi'],[6,'hr'],[7,'bb'],[8,'so']])ok(sum(rows.map(r=>r[index]||0))===sum(actual.map(([,x])=>x[key]||0)),'박스 합계 불일치 '+key);});
T('[검수 11-18 #762 정상 난수] 자격 문제 없는 같은 고정 경기의 투수 선택과 난수 흐름을 기록한다 [투수자격검수]',()=>{const {h,a,d}=gp762Setup(),out=outcome;let g;try{outcome=()=> 'K';__seed(76200);g=simGame(d,h,a,false,{pitchRecords:false});}finally{outcome=out;}ok(g.score.h===0&&g.score.a===0&&g.S.h.pitchers.length>1,'정상 교체 고정 경기 준비');console.log('GP762_NORMAL '+JSON.stringify({score:g.score,pitchers:['h','a'].map(k=>g.S[k].pitchers.map(id=>[id,g.S[k].box.get(id).pc,g.S[k].box.get(id).outs])),rng:__rngState()}));});

function ge765World(){fresh();G.day=G.cal.open+30;const [H,A]=G.teams.filter(t=>t.id!==G.user).map(t=>t.id);for(const tid of [H,A]){G.mgr[tid].small=0;G.mgr[tid].interim=false;for(const p of playersOf(tid)){p.fat=0;if(!p.isP)for(const k in p.r)if(typeof p.r[k]==='number')p.r[k]=20;}}return {H,A};}
function ge765Game(seq,cfg={}){const [H,A]=G.teams.filter(t=>t.id!==G.user).map(t=>t.id),old={outcome,runAdvance,dpF,stealTry,FO_RNG},cnt={};let force=null;for(const t of [H,A])G.mgr[t].small=cfg.bunt&&t===A?100:0;FO_RNG=()=>{if(force!=null){const n=force;force=null;return n;}return (old.FO_RNG||FO_RNG0)();};outcome=(b,p,dv,fp,fs)=>{const n=cnt[fs.tid]=(cnt[fs.tid]||0)+1,it=fs.tid===H?(seq[n-1]||'K'):'K',q=typeof it==='string'?{o:it}:it;if(fs.tid===H&&cfg.activate===n)G.mgr[A].small=100;LBIP=q.o==='OUT'?{t:q.t||'GB',pos:'SS',side:'L'}:null;if(q.o==='OUT')force=q.error?0:.99;return q.o;};runAdvance=()=>({send:true,safe:true});dpF=()=>0;stealTry=()=>0;try{return simGame(G.day,H,A,false,{pitchRecords:cfg.pitchRecords!==false,bipLog:true});}finally{outcome=old.outcome;runAdvance=old.runAdvance;dpF=old.dpF;stealTry=old.stealTry;FO_RNG=old.FO_RNG;}}
function ge765Box(g){return g.S.h.box.get(g.S.h.sp.id);}
function ge765ERLogs(g){return g.pbp.filter(z=>typeof z[1]==='number'&&z[0]===0).reduce((n,z)=>n+(z[11]?.length||0),0);}
T('[검수 11-18 자책 #765] 실책 출루 주자를 번트 포스아웃한 타자 주자도 비자책을 승계한다',()=>{ge765World();let g=null,row=null;for(let s=1;s<=1000&&!row;s++){__seed(s);const x=ge765Game([{o:'OUT',error:true},'HR'],{bunt:true});const r=x.pbp.find(z=>typeof z[1]==='number'&&z[0]===0&&z[16]);if(r&&x.score.a===2){g=x;row=r;}}ok(g&&row,'정확한 실책→번트FC→투런 경로 없음');const x=ge765Box(g);ok(x.roe===1&&x.r===2,'강제 시퀀스/실점 불일치');ok(x.er===1&&ge765ERLogs(g)===1,'2실점 중 번트FC 주자를 자책으로 처리 '+x.er);});
T('[검수 11-18 자책 #766] 3루타→실책 득점→4볼넷은 가상 이닝의 두 정상 주자를 2자책으로 센다',()=>{ge765World();const g=ge765Game(['3B',{o:'OUT',error:true},'BB','BB','BB','BB']),x=ge765Box(g);ok(x.roe===1&&x.r===3&&g.score.a===3,'정확한3루타/실책/4볼넷3실점 경로 없음');ok(x.er===2,'독립 이닝 재구성 기대2자책, 실제'+x.er);ok(ge765ERLogs(g)===2,'타석로그와재구성 자책 불일치 '+ge765ERLogs(g));});
T('[검수 11-18 자책 #767] 실책으로 먼저 들어온 3루 주자는 이후 희생플라이와 득점 땅볼로도 재판정한다',()=>{ge765World();for(const t of ['FB','GB']){const g=ge765Game(['3B',{o:'OUT',error:true},'BB','BB',{o:'OUT',t}]),x=ge765Box(g),rows=g.pbp.filter(z=>typeof z[1]==='number'&&z[0]===0);ok(x.roe===1&&x.r===2&&rows[4][6]===1,'정확한2실점 '+t+' 경로 없음');ok((t==='FB'?rows[4][13]===1:true),'희생플라이 준비');ok(x.er===1&&ge765ERLogs(g)===1,'실책 없는 이닝에서는 원3루주자가 '+t+'로 득점하는데 '+x.er+'자책');}});
T('[검수 11-18 자책 #768] 모든 번트 득점권 플래그는 실제 그 타석 시작 베이스와 같다',()=>{ge765World();for(const seq of [['BB','BB'],['3B','1B']]){let g=null;for(let s=1;s<=100&&!g;s++){__seed(s);const x=ge765Game(seq,{activate:2}),rows=x.pbp.filter(z=>typeof z[1]==='number'&&z[0]===0);if(rows.some(z=>z[3]==='SAC'||z[16]||z[15]?.pitches?.slice(-1)[0]?.res==='번트'))g=x;}ok(g,'번트 시퀀스 준비');const rows=g.pbp.filter(z=>typeof z[1]==='number'&&z[0]===0),W=g.W.filter(w=>w[0]===splAdd&&w[1].team===g.S.a.tid);let base=[0,0,0],bad=0;for(let i=0;i<rows.length;i++){const z=rows[i],bunt=z[3]==='SAC'||z[16]||z[15]?.pitches?.slice(-1)[0]?.res==='번트';if(bunt&&!!W[i][5]!==!!(base[1]||base[2]))bad++;base=z[4]>=3?[0,0,0]:z[5];}ok(!bad,'앞 타석의 득점권 플래그를 받은 번트 '+bad+'건');}});
T('[검수 11-18 자책 확장] 두 번 실책 득점한 정상 주자도 뒤의 진루로 각각 한 번만 자책 처리한다',()=>{ge765World();const g=ge765Game(['3B',{o:'OUT',error:true},'3B',{o:'OUT',error:true},'BB','BB','BB']),x=ge765Box(g);ok(g.score.a===4&&x.r===4&&x.roe===2,'두 실책·네 실점 시퀀스 준비');ok(x.er===2&&ge765ERLogs(g)===2,'정상 3루타 주자 둘을 2자책으로 재구성하지 못함 '+x.er);});
T('[검수 11-18 자책 확장] 타순이 돌아 같은 선수가 다시 출루해도 실책 출루와 새 타석을 섞지 않는다',()=>{ge765World();const g=ge765Game(['3B',{o:'OUT',error:true},...Array(12).fill('BB'),'HR']),S=g.S.h,r=S.pitchers.reduce((n,id)=>n+(S.box.get(id).r||0),0),er=S.pitchers.reduce((n,id)=>n+(S.box.get(id).er||0),0);ok(g.score.a===15&&r===15,'15실점 타순 순환 준비 '+r);ok(er===14&&ge765ERLogs(g)===14,'유일한 실책 출루 1점 외 14점을 자책으로 분리하지 못함 '+er);});
T('[검수 11-18 자책 메타] 네 번트 결과와 정상 야수선택·실책을 기록된 공 없이도 같은 의미로 읽는다',()=>{ge765World();const found={};for(let seed=1;seed<=1000&&Object.keys(found).length<4;seed++){__seed(seed);const g=ge765Game(['BB','BB','HR'],{activate:2}),row=g.pbp.find(z=>typeof z[1]==='number'&&z[0]===0&&z[18]?.bunt);if(row)found[row[18].bunt]={seed,row};}ok(Object.keys(found).length===4,'네 종류 번트 준비 '+Object.keys(found));for(const [kind,{seed,row}]of Object.entries(found)){const m=gamePA(row);ok(m.bunt===kind&&m.ab===(kind==='sac'?0:1)&&m.fc===(kind==='fc')&&m.fielder==='3B'&&m.bipType==='GB','번트 의미가 실제 박스/타구와 다름 '+kind);if(kind==='fc')ok(m.outRunner===row[16]&&[2,3].includes(m.outBase),'번트 목적지·주자 누락');__seed(seed);const no=ge765Game(['BB','BB','HR'],{activate:2,pitchRecords:false}),r=no.pbp.find(z=>typeof z[1]==='number'&&z[0]===0&&z[18]?.bunt);ok(r&&!r[15]&&gamePA(r).bunt===kind,'공별 기록을 꺼 번트 의미 유실');const old=JSON.parse(JSON.stringify(row));delete old[18];ok(gamePA(old).bunt===kind&&gamePA(old).ab===m.ab,'구형 실제 공·포스아웃 호환 '+kind);}
  let fc=null;for(let s=1;s<=200&&!fc;s++){__seed(s);const g=ge765Game(['BB',{o:'OUT',t:'GB'}]);fc=g.pbp.find(z=>typeof z[1]==='number'&&z[0]===0&&z[18]?.fc);}ok(fc&&gamePA(fc).fc&&!gamePA(fc).error&&gamePA(fc).outBase===2,'정상 야수선택을 실책으로 분류');const e=ge765Game([{o:'OUT',error:true}]).pbp.find(z=>typeof z[1]==='number'&&z[0]===0);ok(gamePA(e).error&&!gamePA(e).fc,'실책을 야수선택으로 분류');const sf=ge765Game(['3B',{o:'OUT',t:'FB'}]).pbp.filter(z=>typeof z[1]==='number'&&z[0]===0)[1];ok(gamePA(sf).sf===1&&gamePA(sf).ab===0,'희생플라이 타수');const before=JSON.stringify([fc,e,sf]),rng=__rngState();for(let i=0;i<3;i++){gamePA(fc);gamePA(e);gamePA(sf);}ok(JSON.stringify([fc,e,sf])===before&&__rngState()===rng,'의미 조회 상태·난수 변경');});
function ge765Hash(j){let h=2166136261;for(let i=0;i<j.length;i++){h^=j.charCodeAt(i);h=Math.imul(h,16777619);}return h>>>0;}
function ge765RngWorld(){const old=buildWorld,now=Date.now;__seed(765001);try{Date.now=()=>1795003200000;buildWorld=opts=>old({...opts,lite:true});return ge765World();}finally{buildWorld=old;Date.now=now;}}
function ge765Fingerprint(g){const normalize=z=>[...Array(9)].map((_,i)=>z[i]).concat([z[9]||0,z[10]||[],z[11]||[],z[12]||0,z[13]||0,z[14]||[],z[16]||0,z[17]||'']);const j=JSON.stringify([g.score,g.line,g.dec,g.pbp.map(normalize),['h','a'].map(k=>[g.S[k].pitchers,[...g.S[k].box]]),__rngState()]);let h=2166136261;for(let i=0;i<j.length;i++){h^=j.charCodeAt(i);h=Math.imul(h,16777619);}return h>>>0;}
T('[검수 11-18 자책 난수 호환] 실책 없는 정상 경기의 기존 결과·박스·로그와 주 난수 흐름을 유지한다',()=>{ge765RngWorld();const seqs=[['BB','HBP','1B','HR'],['3B',{o:'OUT',t:'FB'},'2B','1B',{o:'OUT',t:'GB'}],['BB','BB',{o:'OUT',t:'GB'},'2B','HR']],got=[ge765Hash(JSON.stringify(G))];for(let i=0;i<seqs.length;i++){__seed([18,29,101][i]);got.push(ge765Fingerprint(ge765Game(seqs[i])));}const expected=[2322877399,1110575513,690656528,266401240]; /* 11-19 3차 갱신: #258(생년월일)이 선수·해외 주목 선수에 월일(bd)을 저장해 고정 세계 JSON 해시(첫 값)만 바뀜. 주 난수 211864회·상태 1154911425 그대로, bd 항목을 빼고 잰 해시는 앞 기준값 1898699847 그대로, 경기 지문 세 개 그대로 */ /* 11-19 2차 갱신: #254(AI 규칙 동등·트레이드)로 창단 세계에서 AI 보강 트레이드가 실제로 일어나 고정 세계 해시(첫 값)와 선수 구성이 바뀜. 직전 병합(ca932dcd)까지는 앞 기준값 통과 */ /* 기준값 갱신(11-19): fd81502d 브랜치 세계에서 만든 값이 PR #202에서 검수 430~785 묶음과 합쳐지며 세계(첫 값)·경기 지문이 함께 바뀌었다. #202 병합 직후(33350dee)와 지금의 경기 지문 세 개가 같음을 확인 */if(!expected)console.log('GE765_BASE_ORACLE '+JSON.stringify(got));else ok(JSON.stringify(got)===JSON.stringify(expected),'기존 정상 경기 또는 주 난수 순서 변경 '+got);});
function ge765Physical(g){const P=g.pbp.map(z=>[...Array(9)].map((_,i)=>z[i]).concat([z[9]||0,z[10]||[],z[12]||0,z[13]||0,z[14]||[],z[16]||0,z[17]||''])),B=['h','a'].map(k=>[g.S[k].pitchers,[...g.S[k].box].map(([id,x])=>{const y={...x};delete y.er;return [id,y];})]);const j=JSON.stringify([g.score,g.line,g.dec,P,B,__rngState()]);let h=2166136261;for(let i=0;i<j.length;i++){h^=j.charCodeAt(i);h=Math.imul(h,16777619);}return h>>>0;}
T('[검수 11-18 자책 오류 난수] 자책 재판정만 달라지는 실책 경기에서도 실제 경기 진행과 주 난수 소비는 같다',()=>{ge765RngWorld();const seqs=[['3B',{o:'OUT',error:true},'BB','BB','BB','BB'],['3B',{o:'OUT',error:true},'BB','BB',{o:'OUT',t:'FB'}]],got=[ge765Hash(JSON.stringify(G))];for(let i=0;i<seqs.length;i++){__seed([901,902][i]);got.push(ge765Physical(ge765Game(seqs[i])));}const expected=[2322877399,1430852347,888927379]; /* 11-19 3차 갱신: 위와 같은 이유(#258 생년월일 bd 저장, 첫 값만) */ /* 11-19 2차 갱신: 위와 같은 이유(#254 병합 28d1fc80부터 세계 변경) */ /* 기준값 갱신(11-19): 위와 같은 이유. 33350dee와 지금 값이 같음 */if(!expected)console.log('GE765_ERROR_ORACLE '+JSON.stringify(got));else ok(JSON.stringify(got)===JSON.stringify(expected),'실책 재구성이 실제 결과/주 난수까지 변경 '+got);});

function gc771Fixture(o='OUT',mode='fc'){fresh();const H=G.user,A=otherT(),bat=domestic(A).find(p=>!p.isP&&!p.foreign),r1=domestic(A).find(p=>!p.isP&&p!==bat),r2=domestic(A).find(p=>!p.isP&&p!==bat&&p!==r1),pit=domestic(H).find(p=>p.isP),box=t=>({bat:domestic(t).filter(p=>!p.isP).slice(0,9).map((p,i)=>({id:p.id,n:p.name,pos:['C','1B','2B','3B','SS','LF','CF','RF','DH'][i],o:i})),pit:domestic(t).filter(p=>p.isP).map(p=>({id:p.id,n:p.name,pos:'P'}))}),pre=[0,r1.id,pit.id,'BB',0,[r1.id,mode==='force'?r2.id:0,0],0,0,0],row=[0,bat.id,pit.id,o,1,mode==='out'?[r1.id,0,0]:mode==='force'?[bat.id,r1.id,0]:[bat.id,0,0],0,0,0];if(mode==='fc')row[14]=[{id:r1.id,from:1,to:2,result:'out'}];if(mode==='force'){row[14]=[{id:r2.id,from:2,to:3,result:'out'}];row[16]=r2.id;}if(mode!=='fc')row[15]={v:1,pitches:[{t:'직구',v:140,x:.5,y:.5,b:0,s:0,res:'번트'}]};row[17]='GB:SS';return {g:{day:1000,home:H,away:A,box:{h:box(H),a:box(A)},pbp:[pre,row],line:{h:[0],a:[0]},hs:0,as:0},x:row,U:eval(globalThis.__gameCommentaryUISrc())};}
T('[검수 11-18 #771] 실책0인 일반 야수선택은 기본해설·생중계·타구 장면에서 실책이 아니다 [경기해설검수]',()=>{const {g,x,U}=gc771Fixture(),p=U.plan(g,1,U.cBefore(g,1));ok(!/실책|실수/.test(U.base(g,1).c+' '+U.live(g,1).c),'야수선택에 실책선언');ok(!p.errPos&&!/실책/.test(p.kind),'야수선택이 실책 장면 '+p.kind);ok(/야수선택|포스아웃/.test(U.base(g,1).c),'야수선택 실제아웃 설명누락');});
T('[검수 11-18 #772] 번트안타는 기본·생중계 해설과 타구·스윙이 번트다 [경기해설검수]',()=>{const {g,x,U}=gc771Fixture('1B','hit');x[4]=0;const p=U.plan(g,1,U.cBefore(g,1),true);ok(/번트/.test(U.base(g,1).c)&&/번트/.test(U.live(g,1).c),'번트안타를 중전안타로 해설');ok(U.buntSwing(x,x[15].pitches[0],true),'마지막 번트가 풀스윙 분기');ok(p.gb&&!p.arc&&/번트/.test(p.kind),'번트안타가 외야풀스윙 타구');});
T('[검수 11-18 #773] 타자만 아웃인 번트 실패도 결과칩·기본·생중계에 번트로 남는다 [경기해설검수]',()=>{const {g,x,U}=gc771Fixture('OUT','out');ok(/번트.*실패|번트.*아웃/.test(U.paK(x)[0]),'타자아웃번트 결과칩 범타');ok(/번트/.test(U.base(g,1).c)&&/번트/.test(U.live(g,1).c),'실패번트를 일반1루수땅볼로 해설');});
T('[검수 11-18 #774] 실제 3루 포스아웃은 2D·3D의 실행 분기에서도 3루로 처리한다 [경기해설검수]',()=>{const {g,U}=gc771Fixture('OUT','force'),a=U.out2(g,1),b=U.out3(g,1);ok(a.includes(3)&&!a.includes(1),'2D 아웃목적지 '+a);ok(b.includes(3)&&!b.includes(1),'3D 아웃목적지 '+b);});
T('[검수 11-18 #775] 저장된 GB:SS 방향과 유격수 시작 병살을 해설·타구·3D경로가 따른다 [경기해설검수]',()=>{const {g,x,U}=gc771Fixture('OUT','out');delete x[15];x[5]=[g.pbp[0][5][0],0,0];let d=1;for(;d<5000;d++){g.day=d;const r=U.pcH(g,1,'ot');if(r>.6&&r<.83&&U.pcPick(g,1,'fp',['LF','CF','RF','CF'])==='CF')break;}ok(d<5000,'반대방향 고정시드 준비');const c=U.base(g,1).c,p=U.plan(g,1,U.cBefore(g,1));ok(/유격수/.test(c)&&/땅볼/.test(c)&&!/중견수/.test(c),'GB:SS무시 '+c);ok(p.opos==='SS'&&p.gb&&!p.arc,'GB:SS 타구방향/성질무시');x[3]='DP';x[4]=2;x[5]=[0,0,0];x[14]=[{id:g.pbp[0][5][0],from:1,to:2,result:'out'}];for(d=1;d<5000;d++){g.day=d;if(U.pcPick(g,1,'dp',U.dpPats())[0]==='2B')break;}const dp=U.base(g,1).c,path=U.dp(g,1,{pos:'SS'},[38,50]);ok(/6-4-3|6-3/.test(dp)&&!/4-6-3/.test(dp),'유격수병살표기무시 '+dp);ok(/^6-/.test(path.label),'3D병살경로무시 '+path.label);});

function gp776setup(){fresh();G.day=G.cal.open+20;const b=playersOf(G.user).find(p=>!p.isP),p=playersOf(otherT()).find(p=>p.isP);return {b,p,u:eval(__game776UiSrc())};}
function gp776row(b,p,o,meta={}){const x=[0,b.id,p.id,o,1,[0,0,0],0,0,0];if(meta.sf)x[13]=true;if(meta.bunt){x[15]={pitches:[{res:'번트'}]};x[18]={bunt:meta.bunt,fc:meta.bunt==='fc',outBase:meta.bunt==='fc'?2:1,ab:meta.bunt==='sac'?0:1};if(meta.bunt==='fc'){x[16]=999;x[5]=[b.id,0,0];}}return x;}
function gp776game(b,p,rows){const g={day:G.day,home:p.team,away:b.team,pbp:rows,box:{h:{tid:p.team,bat:[],pit:[{id:p.id}]},a:{tid:b.team,bat:[{id:b.id}],pit:[]}}};G.games=[g];return g;}
T('[검수 11-18 #776] 맞대결 카드의 희생플라이0타수와 번트포스아웃1타수는 현재 타석 전후 모두 실제 누계와 같다 [경기패널검수]',()=>{const {b,p,u}=gp776setup();let g=gp776game(b,p,[gp776row(b,p,'OUT',{sf:true})]);b.vs={y:G.year,m:{[p.id]:[10,9,2,0,0,0]}};ok(u.cStory(g,0,b,p,false).includes('9타수')&&u.cStory(g,1,b,p,false).includes('9타수'),'희생플라이가 타수를 바꿈');g=gp776game(b,p,[gp776row(b,p,'OUT',{bunt:'fc'})]);b.vs.m[p.id]=[11,10,2,0,0,0];ok(u.cStory(g,0,b,p,false).includes('9타수')&&u.cStory(g,1,b,p,false).includes('10타수'),'번트 포스아웃 타수 누락');});
T('[검수 11-18 #777] 감독 운영에 희생번트·번트안타·타자아웃·포스아웃 네 번트 결정이 모두 남는다 [경기패널검수]',()=>{const {b,p,u}=gp776setup(),g=gp776game(b,p,[gp776row(b,p,'SAC',{bunt:'sac'}),gp776row(b,p,'1B',{bunt:'hit'}),gp776row(b,p,'OUT',{bunt:'out'}),gp776row(b,p,'OUT',{bunt:'fc'})]),E=u.mdMgrEvents(g,4);ok(E.length===4,'번트 네 종류 중 '+E.length+'건만 표시');ok(E.some(e=>e.kind==='번트 안타')&&E.some(e=>e.kind.includes('포스아웃')),'번트 결과 종류를 구분하지 않음');ok(u.mdMgrEvents(g,2).length===2,'아직 보지 않은 감독 결정 노출');});
T('[검수 11-18 #778] 새 맞대결은 볼넷과 사구를 분리하고 옛 합산은 임의로 볼넷이라 하지 않는다 [경기패널검수]',()=>{const {b,p,u}=gp776setup();delete b.vs;vsAdd(b,p,'HBP',true,0);const a=b.vs.m[p.id];ok(a[4]===1&&a[6]===0&&a[7]===1,'새 사구를 볼넷과 구분해 저장하지 않음');const g=gp776game(b,p,[]),s=u.cStory(g,0,b,p,false);ok(s.includes('사구 1')&&!s.includes('볼넷 1'),'사구 카드가 볼넷으로 표시 '+s);b.vs.m[p.id]=[5,3,1,0,2,0];const before=JSON.stringify(b.vs),rng=__rngState(),old=u.cStory(g,0,b,p,false);ok(old.includes('볼넷·사구')&&!old.includes('볼넷 2'),'옛 합산을 볼넷으로 단정 '+old);ok(JSON.stringify(b.vs)===before&&__rngState()===rng,'옛 기록 조회가 상태·난수를 바꿈');vsAdd(b,p,'BB',true,0);const n=b.vs.m[p.id];ok(n[4]===3&&n[6]===1&&n[7]===0&&n[8]===2,'옛 미분류 합산 또는 새 볼넷 손실');});
T('[검수 11-18 #779] 투수 실책 당사자도 박스스코어 실책 명단에 표시한다 [경기패널검수]',()=>{const {b,p,u}=gp776setup(),s={bat:[{id:b.id,n:'타자기록',pos:b.pos,ab:1,h:0,hr:0,rbi:0,r:0,bb:0,so:0}],pit:[{id:p.id,n:'투수실책당사자',e:1}]},html=u.batBox(s);ok(html.includes('실책: 투수실책당사자'),'실책1개인 투수가 명단에서 빠짐');});
T('[검수 11-18 #780] 경기전 순위 스냅샷은 실제 리그 순위표의 동률 정렬과 같고 미래 경기를 섞지 않는다 [경기패널검수]',()=>{fresh();const T=G.teams.slice(0,4),[B,A,C,D]=T.map(t=>t.id),day=G.cal.open+10;G.teams=T;G.sea={y:G.year,rec:{},tl:{}};G.last={order:[{tid:B},{tid:A},{tid:C},{tid:D}]};for(const t of T){G.sea.rec[t.id]={w:0,l:0,t:0};G.sea.tl[t.id]=[];}const add=(h,a,hs,as)=>{for(const [id,op,s,opS,home] of [[h,a,hs,as,1],[a,h,as,hs,0]]){const r=s>opS?1:s<opS?-1:0;G.sea.tl[id].push([r,s,opS,home,op,day-1]);G.sea.rec[id][r>0?'w':r<0?'l':'t']++;}};add(A,B,3,2);add(A,C,1,0);add(D,A,2,1);add(B,C,4,0);add(B,D,2,1);add(C,D,4,0);const order=standingsNow(),u=eval(__game776UiSrc()),html=u.standTableRows(order),snap=broadcastTeamFacts(day,A,B),before=JSON.stringify(G),rng=__rngState();ok(order[0].tid===A&&html.includes('<td>1</td><td><button class="lnk tname" data-a="lteamGo" data-v="'+A+'"'),'실제 순위표 맞대결 정렬 준비');ok(snap.teams[A].rank===1&&snap.teams[B].rank===2,'중계 순위가 리그 순위표와 다름 '+snap.teams[A].rank+'/'+snap.teams[B].rank);G.sea.tl[B].push([1,90,0,1,A,day+1]);ok(JSON.stringify(broadcastTeamFacts(day,A,B))===JSON.stringify(snap),'경기전 순위에 미래 기록 혼입');G.sea.tl[B].pop();ok(JSON.stringify(G)===before&&__rngState()===rng,'순위 조회가 상태·난수를 바꿈');});

T('[검수 11-18 #773·777] 옛 투구기록과 새 메타데이터 모두 같은 번트칩과 네 감독 결정을 렌더한다 [경기패널검수]',()=>{const {b,p,u}=gp776setup(),kinds=['sac','hit','out','fc'],labels=['희생번트','번트 안타','번트 실패','번트 실패 · 포스아웃'];const rows=kinds.map(k=>gp776row(b,p,k==='sac'?'SAC':k==='hit'?'1B':'OUT',{bunt:k})),g=gp776game(b,p,rows);for(let i=0;i<rows.length;i++)ok(u.paK(rows[i])[0]===labels[i],'새 메타데이터 번트칩 '+kinds[i]);rows.forEach(x=>delete x[18]);ok(u.mdMgrEvents(g,4).length===4,'옛 lastpitch.res 번트 결정 누락');for(let i=0;i<rows.length;i++)ok(u.paK(rows[i])[0]===labels[i],'옛 투구기록 번트칩 '+kinds[i]);const fc=gp776row(b,p,'OUT');fc[5]=[b.id,0,0];ok(u.paK(fc)[0]==='야수선택','일반 FC를 실책으로 표시');});
T('[검수 11-18 #778] 두 맞대결 카드의 분리 수치는 미래 타석을 가리고 옛 합산을 유지한다 [경기패널검수]',()=>{const {b,p,u}=gp776setup();b.vs={y:G.year,m:{[p.id]:[6,4,1,0,2,0]}};vsAdd(b,p,'BB',true,0);const g=gp776game(b,p,[gp776row(b,p,'BB')]);let text=u.cStory(g,0,b,p,false),match=u.cMatchupHtml(u.cMatchup(g,0,b.id,p.id));ok(text.includes('볼넷·사구 2')&&!text.includes('볼넷 1'),'미공개 볼넷이 스토리 카드에 노출 '+text);ok(match.includes('볼넷·사구 2')&&!match.includes('볼넷 1')&&!match.includes('NaN'),'미공개 볼넷 또는 NaN이 대결 카드에 노출 '+match);text=u.cStory(g,1,b,p,false);ok(text.includes('볼넷 1')&&text.includes('볼넷·사구 2'),'본 볼넷 또는 옛 미분류 기록 손실');const saved=JSON.stringify(b.vs);G=JSON.parse(JSON.stringify(G));const b2=G.players[b.id],p2=G.players[p.id],g2=G.games[0],before=JSON.stringify(G),rng=__rngState();for(let i=0;i<3;i++){u.cStory(g2,1,b2,p2,false);u.cMatchupHtml(u.cMatchup(g2,0,b2.id,p2.id));}ok(JSON.stringify(b2.vs)===saved&&JSON.stringify(G)===before&&__rngState()===rng,'저장 복원 후 조회로 누계 변경');});
T('[검수 11-18 #780] 맞대결 다득점과 지난 시즌 순위도 실제 순위표 순서대로 고정한다 [경기패널검수]',()=>{fresh();const T=G.teams.slice(0,4),ids=T.map(t=>t.id),[a,b,c,d]=ids,day=G.cal.open+12;G.teams=T;G.sea={y:G.year,rec:{},tl:{}};G.last={order:[{tid:b},{tid:a},{tid:d},{tid:c}]};for(const tid of ids){G.sea.rec[tid]={w:1,l:1,t:0};G.sea.tl[tid]=[];}const pair=(h,a,hs,as)=>{G.sea.tl[h].push([hs>as?1:-1,hs,as,1,a,day-1]);G.sea.tl[a].push([as>hs?1:-1,as,hs,0,h,day-1]);};pair(a,b,9,1);pair(b,a,2,1);pair(c,d,1,0);pair(d,c,1,0);const order=standingsNow(),snap=broadcastTeamFacts(day,a,b);ok(order.every((r,i)=>snap.teams[r.tid].rank===i+1),'다득점 또는 지난 순위가 실제 정렬과 다름');ok(snap.teams[a].rank<snap.teams[b].rank,'전년 하위였어도 맞대결 다득점 팀이 앞서지 않음');G.sea.tl[a]=[];G.sea.tl[b]=[];G.sea.tl[c]=[];G.sea.tl[d]=[];for(const tid of ids)G.sea.rec[tid]={w:0,l:0,t:0};const order2=standingsNow(),snap2=broadcastTeamFacts(day,a,b);ok(order2.every((r,i)=>snap2.teams[r.tid].rank===i+1)&&snap2.teams[b].rank===1,'상대 전적·득점까지 같을 때 지난 순위 무시');});

function gc781(){fresh();const U=G.user,V=otherT(),a=domestic(U).find(p=>!p.isP),b=domestic(V).find(p=>!p.isP),pa=domestic(U).find(p=>p.isP),pb=domestic(V).find(p=>p.isP);a.name='실제홈우수타자';b.name='실제원정타자';const side=(t,bat,pit)=>({tid:t,start:[{id:bat.id,o:0,pos:'CF'}],order:[bat],changes:[],sp:pit,pitchers:[pit.id],box:new Map([[bat.id,bz()],[pit.id,pz()]])}),g={S:{h:side(U,a,pa),a:side(V,b,pb)},score:{h:1,a:0},pbp:[[0,b.id,pa.id,'OUT',3,[0,0,0],0,0,0]],line:{h:[1],a:[0]},dec:{},inn:9,walk:false},c={aHome:true,CA:{e:{h:'entry-home',name:'홈',year:G.year},off:0},CB:{e:{h:'entry-away',name:'원정',year:G.year},off:0},key:'review',i:0};const row=(half,bat,pit,o,outs,bases,n,as,hs)=>[half,bat.id,pit.id,o,outs,bases,n,as,hs];return {a,b,pa,pb,g,c,row};}
T('[검수 11-18 #770] 단장 대전 30경기 OPS는 희생플라이를 출루율 분모에 포함한다 [대회기록검수]',()=>{fresh();const s='L2026W47',A=ladderAuto(s,{name:'대전A'}),B=ladderAuto(s,{name:'대전B'}),sim=simGame,after=ladderAfter,rest=ladderRest;let out;try{simGame=(d,h,a,ps,o)=>{for(const x of [o.sides.h,o.sides.a])for(const p of x.order)Object.assign(x.box.get(p.id),{pa:4,ab:3,h:1,d:0,tr:0,hr:0,bb:0,hbp:0,sf:1});return {S:o.sides,score:{h:0,a:0},dec:{},inn:9};};ladderAfter=()=>{};ladderRest=()=>{};const raw=JSON.stringify(G);out=ladderSeries(A,B,{games:30,seed:'SF'});ok(out.ok&&JSON.stringify(G)===raw,'희생플라이 대전/커리어 보존 준비');}finally{simGame=sim;ladderAfter=after;ladderRest=rest;}ok(out.a.bat.length&&out.a.bat.every(b=>b.ops===.583)&&out.b.bat.every(b=>b.ops===.583),'SF포함 OPS .583 대신 '+JSON.stringify(out.a.bat));});
T('[검수 11-18 #781] 실책·병살 득점은 타점 없는 결승점이며 결승타와 타점 하이라이트를 만들지 않는다 [대회기록검수]',()=>{for(const kind of ['error','dp']){const {a,pb,g,c,row}=gc781(),x=row(1,a,pb,kind==='dp'?'DP':'OUT',kind==='dp'?2:0,[a.id,0,0],1,0,1);x[12]=0;if(kind==='error')x[9]=pb.id;g.pbp=[x];const r=cupGameOut(g,c);ok(!r.wh&&!r.log.includes('결승타 '+a.name),'타점0 '+kind+'에 결승타');ok(!r.hl.some(h=>h.plays.some(p=>p.includes('타점')||p.includes('득점타'))),'타점0을 타점 하이라이트로 기록 '+JSON.stringify(r.hl));}});
T('[검수 11-18 #782] 번트 앞 주자 포스아웃은 대회 중계에도 번트와 실제 아웃 베이스를 표시한다 [대회기록검수]',()=>{const {a,b,pb,g,c,row}=gc781(),x=row(1,a,pb,'OUT',1,[a.id,b.id,0],0,0,0);x[16]=b.id;x[14]=[{id:b.id,from:2,to:3,result:'out'}];x[18]={bunt:'fc',fc:true,outBase:3,ab:1};g.pbp=[x];g.score={h:0,a:0};const r=cupGameOut(g,c);ok(r.log.includes('번트')&&r.log.includes('3루')&&!r.log.includes('중견수 플라이'),'번트FC가 일반 플라이로 변함 '+r.log);});
T('[검수 11-18 #783] 무승부 MVP는 양쪽에서 뽑고 A/B 표기와 무관하게 같은 선수를 고른다 [대회기록검수]',()=>{const {a,b,g,c}=gc781();Object.assign(g.S.h.box.get(a.id),{pa:4,ab:4,h:3,d:1,rbi:1,r:1});Object.assign(g.S.a.box.get(b.id),{pa:4,ab:4,h:1,rbi:1,r:1});g.score={h:1,a:1};g.line={h:[1],a:[1]};const before=JSON.stringify(G),rng=__rngState(),x=cupGameOut(g,c),y=cupGameOut(g,{...c,aHome:false,CA:c.CB,CB:c.CA});ok(x.mvp?.name===a.name&&y.mvp?.name===a.name,'무승부 A/B 변경으로 MVP 차이 '+JSON.stringify([x.mvp,y.mvp]));ok(JSON.stringify(G)===before&&__rngState()===rng,'대회 기록 조회가 커리어/주난수 변경');});
T('[검수 11-18 #784] 대회 타자·투수 박스와 새 투수 누계는 볼넷0 사구1을 나눠 보존한다 [대회기록검수]',()=>{const {a,pb,g,c}=gc781();Object.assign(g.S.h.box.get(a.id),{pa:1,bb:0,hbp:1});Object.assign(g.S.a.box.get(pb.id),{bb:0,hbp:1});const r=cupGameOut(g,c);ok(r.bat.split('\\n')[0].includes('HBP')&&r.pit.split('\\n')[0].includes('HBP'),'새 박스에 사구 열 없음');const p=r.stats.pit.find(x=>x.name===pb.name);ok(p.bb===0&&p.hbp===1,'사구를 투수BB에 합산 '+JSON.stringify(p));ok(r.stats.bat.find(x=>x.name===a.name).bb===0&&r.stats.bat.find(x=>x.name===a.name).hbp===1,'타자 분리 집계');});
T('[검수 11-18 #785] 뒤짐→동점→리드를 연속 득점으로 되찾으면 역전 횟수와 래더 태그에 반영한다 [대회기록검수]',()=>{const {a,b,pa,pb,g,c,row}=gc781();const x=row(0,b,pa,'HR',0,[0,0,0],1,1,0),y=row(1,a,pb,'HR',0,[0,0,0],1,1,1),z=row(1,a,pb,'HR',0,[0,0,0],1,1,2);for(const q of [x,y,z])q[12]=1;g.pbp=[x,y,z];g.score={h:2,a:1};g.line={h:[2],a:[1]};const r=cupGameOut(g,c);ok(r.lc===1&&ulGameTag(r.sa,r.sb,r)==='역전승','동점을 거친 역전을 누락 '+r.lc+'/'+ulGameTag(r.sa,r.sb,r));ok(r.log.includes('역전'),'중계에서 동점 뒤 역전 흐름 누락');});
T('[검수 11-18 #781 타점 구분] 무타점 결승점 뒤 보험 홈런도 결승타가 아니며 정상 땅볼 타점은 인정한다 [대회기록검수]',()=>{const {a,b,pb,g,c,row}=gc781(),e=row(1,a,pb,'OUT',0,[a.id,0,0],1,0,1),h=row(1,b,pb,'HR',0,[0,0,0],1,0,2);e[9]=pb.id;h[12]=1;g.pbp=[e,h];g.score={h:2,a:0};let r=cupGameOut(g,c);ok(!r.wh,'나중 보험타를 결승타로 지정');const f=row(1,a,pb,'OUT',1,[0,0,0],1,0,1);f[12]=1;f[17]='GB:SS';g.pbp=[f];g.score={h:1,a:0};r=cupGameOut(g,c);ok(r.wh?.id===a.id&&r.hl[0].plays[0].includes('타점'),'정상 땅볼 타점까지 결승타에서 제외');});
T('[검수 11-18 #783 동률] 같은 점수 MVP도 구단 표기 순서가 아니라 같은 선수 키로 정한다 [대회기록검수]',()=>{const {a,b,g,c}=gc781();for(const [s,p] of [[g.S.h,a],[g.S.a,b]])Object.assign(s.box.get(p.id),{pa:4,ab:4,h:2,d:1,rbi:1,r:1});g.score={h:1,a:1};const rng=__rngState(),raw=JSON.stringify(G),x=cupGameOut(g,c),y=cupGameOut(g,{...c,aHome:false,CA:c.CB,CB:c.CA});ok(x.mvp?.key&&x.mvp.key===y.mvp?.key&&x.mvp.name===y.mvp.name,'MVP 동률에서 A/B 순서 의존');ok(__rngState()===rng&&JSON.stringify(G)===raw,'MVP 동률 조회가 상태/난수 변경');});
T('[검수 11-18 #784 호환] 옛 투수 배열 위치·합계는 보존하고 새 사구는 끝 칸에 쌓으며 미분리는 명시한다 [대회기록검수]',()=>{fresh();const C=FrontOfficeCore,old=['g','gs','outs','h','bb','so','r','er','hr','w','l','sv'];ok(JSON.stringify(C.UL_PF.slice(0,12))===JSON.stringify(old)&&C.UL_PF[12]==='hbp','구형 투수 열 순서 변경');const ps={p:{n:'옛투수',P:1,s:{'S1|0':{p:[2,1,9,4,3,5,2,1,1,1,0,1]}}}};let x=C.ulPsRows(ps,'p',{})[0];ok(x.outs===9&&x.so===5&&x.bb===3&&x.bbMixed&&x.whip==null,'옛 합계를 분리된 볼넷으로 단정 '+JSON.stringify(x));C.ulPsAdd(ps,{sid:'S1',tier:0,lid:1,P:[],pit:[{id:'p',g:1,outs:3,h:1,bb:0,hbp:1,so:2,er:0}],bat:[]});x=C.ulPsRows(ps,'p',{})[0];ok(x.outs===12&&x.so===7&&x.bb===3&&x.hbp===1&&x.bbMixed,'새 사구가 옛 열을 밀거나 미분리 표식 소실');const freshPs={};C.ulPsAdd(freshPs,{sid:'S1',tier:0,lid:1,P:[],pit:[{id:'n',g:1,outs:3,h:0,bb:0,hbp:1,so:2,er:0}],bat:[]});const n=C.ulPsRows(freshPs,'p',{})[0];ok(n.bb===0&&n.hbp===1&&!n.bbMixed&&n.whip===0,'새 기록의 사구가 WHIP 볼넷에 포함');const txt=['팀 연도 이름','IP','H','BB','SO'].join(String.fromCharCode(9))+String.fromCharCode(10)+'구형 숫자 보존',label=cupBoxLabel(txt);ok(label.includes('BB/HBP')&&label.endsWith('구형 숫자 보존')&&cupBoxLabel(label)===label,'구형 박스 합계 이름/멱등성');const state=JSON.stringify(ps),rng=__rngState();C.ulPsRows(ps,'p',{});ok(JSON.stringify(ps)===state&&__rngState()===rng,'구형 합계 조회가 저장/난수 변경');});

function gx762World(){fresh();G.day=G.cal.open+21;G.entryY=G.year;G.ps=null;G.res=null;G.makeup=[];const h=G.user,a=G.teams.find(t=>t.id!==h).id;for(const tid of [h,a]){for(const p of playersOf(tid)){p.injOut=0;p.fat=0;delete p.hold;delete p.frehab;delete p.fLeave;delete p.susp;delete p.boy;if(p.isP){p.ld=[];delete p.lastApp;delete p.lastStart;}}setEntry(tid);}return {h,a,d:G.day};}
T('[검수 11-18 독립 #762] 실제 일일 리그 경로는 전원 당일 등판 때 재시도 후 순연하고 투구 기록을 남기지 않는다 [경기독립검수]',()=>{const {h,a,d}=gx762World();G.cal.sched[d]=[[h,a]];for(const p of Object.values(G.players))if(p.team===h&&p.isP)p.lastApp=d;const arms=Object.values(G.players).filter(p=>p.team===h&&p.isP),snap=JSON.stringify(arms.map(p=>[p.id,p.fat,p.ld,p.hist,p.lastApp])),r=JSON.stringify(G.sea.rec),rot=team(h).rot;playDay(d);ok(G.makeup.some(m=>m.h===h&&m.a===a&&m.d===d),'전원 당일 등판 경기가 실제로 순연되지 않음');ok(JSON.stringify(G.sea.rec)===r&&JSON.stringify(arms.map(p=>[p.id,p.fat,p.ld,p.hist,p.lastApp]))===snap,'순연 경기에 승패/피로/등판 기록이 남음');ok(team(h).rot===rot,'후보 없는 경기 재시도가 선발 순번을 소비');});
T('[검수 11-18 독립 #764] 지시 없는 실제 퓨처스 소진 경기 반영도 1군 등판 피로와 기록을 보존한다 [경기독립검수]',()=>{const {h,a,d}=gx762World();G.mgrDir={};const arms=actOf(h).filter(p=>p.isP),snap=JSON.stringify(arms.map(p=>[p.id,p.fat,p.ld,p.hist,p.lastApp]));for(const p of Object.values(G.players))if([h,a].includes(p.team)&&!p.isP)p.e1=false;G.fl={y:G.year,rot:{},games:[],rec:Object.fromEntries(G.teams.map(t=>[t.id,{w:0,l:0,d:0,rs:0,ra:0}]))};const S={h:flSide(h,d),a:flSide(a,d)};ok(S.h&&S.a,'실제 퓨처스 명단 준비');const allowed=new Set(S.h.pitchPool);for(const p of [...S.h.pen,...S.h.spAll])if(p!==S.h.cur)S.h.used.add(p.id);S.h.box.get(S.h.cur.id).pc=180;const g=simGame(d,h,a,false,{sides:S,pitchRecords:false});applyFarm(d,g);ok(S.h.pitchers.every(id=>allowed.has(id)),'실제 허가 명단 밖에서 교체');ok((S.h.armEmergency||[]).some(x=>x.id===S.h.sp.id),'계속 투구 예외 누락');ok(JSON.stringify(arms.map(p=>[p.id,p.fat,p.ld,p.hist,p.lastApp]))===snap,'1군 투수에 퓨처스 투구 부하/기록 반영');ok((seasonTotal(S.h.sp,G.year,'퓨처스')?.g||0)>0,'허가된 퓨처스 투수의 실제 경기 기록 누락');});
function gx765Script(seq,swapAfter){const {h,a,d}=gx762World();for(const tid of [h,a]){G.mgr[tid].small=0;for(const p of playersOf(tid))if(!p.isP){p.r.spd=20;p.r.def=20;}}const old={outcome,runAdvance,dpF,stealTry,FO_RNG},counts={};let force=null;FO_RNG=()=>{if(force!=null){const q=force;force=null;return q;}return (old.FO_RNG||FO_RNG0)();};outcome=(b,p,dv,fp,fs)=>{const n=counts[fs.tid]=(counts[fs.tid]||0)+1,q=fs.tid===h?(seq[n-1]||'K'):'K',o=typeof q==='string'?q:q.o;LBIP=o==='OUT'?{t:(typeof q==='object'&&q.t)||'GB',pos:'SS',side:'L'}:null;if(o==='OUT')force=q.error?0:.99;if(fs.tid===h&&n===swapAfter)fs.box.get(p.id).pc=150;return o;};runAdvance=()=>({send:true,safe:true});dpF=()=>0;stealTry=()=>0;try{return simGame(d,h,a,false,{pitchRecords:false});}finally{outcome=old.outcome;runAdvance=old.runAdvance;dpF=old.dpF;stealTry=old.stealTry;FO_RNG=old.FO_RNG;}}
T('[검수 11-18 독립 #767 경계] 희생플라이가 가상 세 번째 아웃이면 앞서 실책으로 득점한 주자를 자책으로 바꾸지 않는다 [경기독립검수]',()=>{const g=gx765Script(['K','3B',{o:'OUT',error:true},'BB','BB',{o:'OUT',t:'FB'}]),rows=g.pbp.filter(z=>typeof z[1]==='number'&&z[0]===0),x=g.S.h.box.get(g.S.h.sp.id);ok(rows[1][3]==='3B'&&rows[2][9]&&rows[5][13]===1&&x.r===2,'K→3루타→실책 득점→2BB→SF 실제 경로');ok(x.er===0,'실책을 아웃으로 재구성하면 SF가 3아웃인데 이전 득점 자책 전환 '+x.er);});
