T('[검수 11-18 GAME 스키마 교차] 실제 엔진 번트 메타는 경기 저장과 JSON 복원 뒤 UI·대회 중계에서 같은 뜻이다 [게임스키마교차]',()=>{fresh();G.day=G.cal.open+20;const H=G.user,A=otherT(),out=outcome;let g;for(const tid of [H,A]){G.mgr[tid].small=100;for(const p of playersOf(tid))if(!p.isP){p.r.spd=20;for(const k of ['con','pow','eye'])p.r[k]=25;}}try{let n=0;outcome=()=>n++%4===0?'BB':'K';__seed(78602);g=simGame(G.day,H,A,false,{pitchRecords:false,bipLog:true});}finally{outcome=out;}const bunts=g.pbp.filter(x=>gamePA(x).bunt);ok(bunts.length>0,'실제 번트 생성 준비');const r=gameRecord(G.day,H,A,g,'정규시즌'),saved=JSON.parse(JSON.stringify(r)),u=eval(__game776UiSrc()),rng=__rngState();for(const x of bunts){const j=g.pbp.indexOf(x),a=gamePA(x),b=gamePA(saved.pbp[j]);ok(JSON.stringify(a)===JSON.stringify(b),'저장 꼬리 메타 변화');ok(u.paK(saved.pbp[j])[0].includes('번트'),'독립 엔진의 gamePA를 UI에서 조회 불가');ok(x[18]&&x[18].ab===(x[3]==='SAC'?0:1)&&x[18].error===false,'번트 메타가 일반 아웃 메타로 덮임');}const c={aHome:true,CA:{e:{h:'home',name:'홈',year:G.year},off:0},CB:{e:{h:'away',name:'원정',year:G.year},off:0},key:'schema',i:0},cup=cupGameOut(g,c);ok(cup.log.includes('번트'),'동일 실제 경기 대회 중계가 번트를 잃음');ok(__rngState()===rng,'저장·뷰 변환이 RNG 소비');});
T('[검수 11-18 GAME 스키마 교차] 옛 리그 최종 누계의 미분리 볼넷·사구는 시즌 마감과 CSV에서도 알려진 볼넷이 되지 않는다 [게임스키마교차]',()=>{fresh();const e=cupEntryNow(),p=e.P.find(p=>p.isP),key=UL_ME+':'+p.id,U={ps:{},opp:{}},L={id:1,tier:0,teams:[{e,name:e.name,kind:'me'}],series:[],bat:{},pit:{[key]:{key,name:p.name,g:1,gs:1,outs:9,h:2,bb:3,so:4,er:1,r:1,hr:0,w:1,l:0,sv:0}}};ulAccum(U,JSON.parse(JSON.stringify(L)),[],{id:'S1'});G.uld={v:2,hist:[],ps:JSON.parse(JSON.stringify(U.ps)),seasons:[]};const x=FrontOfficeCore.ulPsRows(G.uld.ps,'p',{})[0],raw=JSON.stringify(G.uld),rng=__rngState(),csv=eval(__gameSchemaCsvSrc())('pit')[1];ok(x.bbMixed&&x.whip==null,'마지막 경기 전 구형 리그 누계를 정확한 BB로 단정 '+JSON.stringify(x));ok(csv.includes('3 (BB/HBP)')&&csv.includes('미분리'),'CSV에서 미분리 합계를 볼넷3 사구0으로 발명 '+csv);ok(JSON.stringify(G.uld)===raw&&__rngState()===rng,'CSV가 저장/RNG 변경');});
T('[검수 11-18 GAME 스키마 교차] 새 사구와 옛 배열 꼬리의 승·세이브는 여러 시즌 JSON 복원·CSV 후에도 각각 보존된다 [게임스키마교차]',()=>{fresh();const C=FrontOfficeCore,ps={old:{n:'구형',P:1,s:{'S1|0':{p:[2,1,12,3,4,5,2,1,1,1,0,2]}}}};C.ulPsAdd(ps,{sid:'S2',tier:1,lid:2,P:[{id:'old',name:'구형',isP:1,pos:'RP'}],pit:[{id:'old',g:1,gs:0,outs:3,h:1,bb:0,hbp:2,so:1,r:0,er:0,hr:0,w:0,l:0,sv:1}],bat:[]});G.uld={v:2,hist:[],ps:JSON.parse(JSON.stringify(ps)),seasons:[]};const x=C.ulPsRows(G.uld.ps,'p',{})[0],csv=eval(__gameSchemaCsvSrc())('pit')[1],old=x.tsplits.find(x=>x.sid==='S1'),now=x.tsplits.find(x=>x.sid==='S2');ok(x.outs===15&&x.w===1&&x.sv===3&&x.so===6&&x.hbp===2,'추가 사구가 기존 투수 꼬리 열을 밀음');ok(old.bbMixed&&old.bb===4&&old.whip==null&&!now.bbMixed&&now.bb===0&&now.hbp===2&&now.whip===1,'시즌별 미분리/분리 경계 손실');ok(csv.includes('4 (BB/HBP)')&&csv.includes('미분리')&&csv.includes('S2'),'실제 CSV의 원본/신규 시즌 누락');});

T('[검수 11-18 #771~775] 새 메타데이터가 옛 방향 문자열보다 우선하고 표시 조회는 저장·경기난수를 바꾸지 않는다 [경기해설검수]',()=>{const {g,x,U}=gc771Fixture('OUT','force');delete x[15];delete x[16];x[18]={bunt:'fc',fc:true,error:false,fielder:'3B',bipType:'GB',outBase:3,outRunner:g.pbp[0][5][1],ab:1};const snap=JSON.stringify(g),rng=__rngState();for(let i=0;i<3;i++){const p=U.plan(g,1,U.cBefore(g,1));ok(p.opos==='3B'&&p.gb&&!p.errPos&&/번트/.test(p.kind),'새 번트메타보다 옛GB:SS를 우선');ok(/3루.*포스아웃/.test(U.base(g,1).c)&&/3루.*포스아웃/.test(U.live(g,1).c),'실제3루아웃 해설누락');ok(U.out2(g,1).includes(3)&&U.out3(g,1).includes(3),'메타데이터 아웃목적지누락');}ok(JSON.stringify(g)===snap&&__rngState()===rng,'해설·장면조회가 저장이나 경기난수변경');delete x[18];delete x[17];delete x[14];x[5]=[x[1],0,0];const c=U.base(g,1).c;ok(/야수선택/.test(c)&&!/실책|1루에서.*아웃/.test(c),'목적지없는 옛야수선택을 실책이나1루아웃으로 단정');ok(U.out2(g,1).length===0&&U.out3(g,1).length===0,'목적지없는 옛야수선택에 가짜1루송구');});
T('[검수 11-18 #778] 옛 합산을 새 형식으로 옮긴 뒤 과거 중계를 열어도 미공개 사구가 남지 않는다 [경기패널검수]',()=>{const {b,p,u}=gp776setup(),g=gp776game(b,p,[gp776row(b,p,'HBP')]);b.vs={y:G.year,m:{[p.id]:[10,9,2,0,1,0]}};vsAdd(b,p,'BB',true,0);const later={...g,day:G.day+1,pbp:[gp776row(b,p,'BB')]};G.games=[later,g];const before=JSON.stringify(b.vs),text=u.cMatchupHtml(u.cMatchup(g,0,b.id,p.id));ok(text.includes('9타수')&&!text.includes('볼넷·사구')&&!text.includes('볼넷 1')&&!text.includes('사구 1'),'미공개 옛 합산이 새 형식에서 결과 노출 '+text);ok(JSON.stringify(b.vs)===before,'표시 보정이 원본 기록 변경');});

