T('[검수 11-18 #812 다년] 포스팅 다년 복귀와 해외 FA 복귀의 계약 구분은 유지한다 [해외복귀검수]',()=>{fr810Fresh();const origin=otherT(),p=fr810Pending(origin);p.retAsk.yrs=3;ovsBackSign(p);ok(p.team===origin&&p.faC&&p.ext&&p.yrs===3&&p.cyrs===3,'비FA 다년 복귀 계약 변경');const q=fr810Pending(G.user);q.retAsk.post=0;q.retAsk.yrs=2;ovsBackSign(q);ok(q.team===G.user&&q.faC&&!q.ext&&q.yrs===2,'해외 FA 복귀가 비FA로 변경');});
T('[검수 11-18 #813] 정원으로 실패한 옛 복귀 보정은 자리 확보 뒤 재시도하고 해외 연차는 한 번만 뺀다 [해외복귀검수]',()=>{fr810Fresh();const tid=otherT(),p=fr810Pending(tid),by=G.year-1;p.college=false;p.svc=8;p.retAsk=null;delete p.retFrom;p.ctFree=G.year;p.faFrom=tid;p.story=[{y:by,t:'MLB 생활을 마치고 복귀(1년 연 8억)',k:'move'}];delete p.lastFA;G.abroad=[{id:p.id,name:p.name,from:tid,lg:'MLB',how:'포스팅',y:G.year-3,y1:G.year-2,lines:[{y:G.year-2,pa:300}],back:true,backY:by}];G.fa={y0:G.year,pool:[p.id],offers:{[p.id]:[]},ai:{},neg:{},closed:false,results:[],outN:{}};const sample=domestic(tid)[0];let id=-813000;while(rosterN(tid)<ROSTER_MAX){const q=JSON.parse(JSON.stringify(sample));q.id=id--;q.ys=false;q.foreign=null;q.joinY=G.year;G.players[q.id]=q;}ok(rosterN(tid)===ROSTER_MAX,'준비: 원소속 정원 불일치');const seed=__rngState();ovsPostFix();ok(p.team==null&&G.fa.pool.includes(p.id),'정원인데 보류 복귀');ok(p.svc===7&&p.svc<faSvc(p),'첫 해외 연차 보정/FA 미달 준비 불일치');const room=domestic(tid).find(q=>q.id!==p.id&&!q.ys);delete G.players[room.id];ovsPostFix();ok(p.team===tid&&!G.fa.pool.includes(p.id),'자리 확보 뒤 복귀 보정을 다시 하지 않음');ok(p.svc===7,'재시도에서 해외연차 중복 차감');const before=JSON.stringify(G);ovsPostFix();ok(JSON.stringify(G)===before&&__rngState()===seed,'보정 반복이 저장/주난수 변경');});
T('[검수 11-18 #814] 기한 지난 복귀 요청은 AI도 계약하지 않고 자유계약으로 정리한다 [해외복귀검수]',()=>{fr810Fresh();const tid=otherT(),p=fr810Pending(tid),av=aiVal,am=aiCapMul;p.retAsk.exp=G.day-3;team(tid).cash=100000;try{aiVal=()=>100;aiCapMul=()=>100;ovsBackSweep();ok(p.team==null&&!p.retAsk&&p.freeSince!=null,'만료 복귀 요청을 AI가 체결');ok(!(G.moves||[]).some(m=>m.pid===p.id&&m.t==='해외 복귀'),'만료 요청으로 복귀 이동 기록 생성');}finally{aiVal=av;aiCapMul=am;}});
T('[검수 11-18 #814 이벤트] 열린 결정 카드가 남아도 사용자와 AI의 같은 만료 기한을 적용한다 [해외복귀검수]',()=>{fr810Fresh();const p=fr810Pending();ovsBackAsk(p);const e=G.evs.find(e=>!e.done&&e.k==='ovsback'&&e.data.pid===p.id);p.retAsk.exp=G.day-3;ovsBackSweep();ok(p.team==null&&!p.retAsk&&isFree(p),'열린 결정 때문에 만료 우선협상이 유지');ok(e.done,'만료한 복귀 결정이 열린 채로 남음');const before=JSON.stringify(p);EVH.ovsback.pick(e,0);ok(JSON.stringify(p)===before,'만료 카드 선택이 선수 상태 재변경');});
T('[검수 11-18 #814 직접] 만료 당일까지는 유효하고 지난 요청의 직접 수락은 체결하지 않는다 [해외복귀검수]',()=>{fr810Fresh();const p=fr810Pending();p.retAsk.exp=G.day-1;ovsBackSign(p);ok(p.team==null&&!p.retAsk&&isFree(p),'직접 복귀 수락이 만료를 우회');const q=fr810Pending(otherT());q.retAsk.exp=G.day;ovsBackSign(q);ok(q.team===otherT()&&!q.retAsk,'만료 당일의 유효한 요청까지 거절');});
T('[검수 11-18 #810 옛 저장 복귀보정추가] 복귀 보정은 우선협상 중 옛 무적·FA 등록만 정리하고 요구 계약을 보존한다 [해외복귀검수]',()=>{fr810Fresh();const p=fr810Pending(),q=JSON.stringify(p.retAsk);G.fa={y0:G.year,pool:[p.id],offers:{[p.id]:{a:999}},ai:{[p.id]:[]},neg:{[p.id]:{}},closed:false};const seed=__rngState();ovsPostFix();ok(p.freeSince==null&&p.freeDay==null&&p.tryK==null,'옛 무적 기록 미정리');ok(!G.fa.pool.includes(p.id)&&!G.fa.offers[p.id]&&!G.fa.ai[p.id]&&!G.fa.neg[p.id],'우선협상 선수에게 FA 협상도 남음');ok(JSON.stringify(p.retAsk)===q&&p.team==null,'저장 보정이 복귀 요구 계약을 변경');const before=JSON.stringify(G);ovsPostFix();ok(JSON.stringify(G)===before&&__rngState()===seed,'복귀 상태 보정 반복/난수 변경');});
T('[검수 11-18 #810 옛 계약 복귀보정추가] 이미 계약한 선수의 옛 복귀 카드만 종료하고 현재 계약과 이동 기록을 보존한다 [해외복귀검수]',()=>{fr810Fresh();const p=fr810Pending(),tid=otherT();ovsBackAsk(p);const e=G.evs.find(e=>!e.done&&e.k==='ovsback'&&e.data.pid===p.id);p.team=tid;p.sal=1495;p.yrs=2;p.faC=true;p.ext=false;const moves=JSON.stringify(G.moves),seed=__rngState();ovsPostFix();ok(p.team===tid&&p.sal===1495&&p.yrs===2&&!p.retAsk&&p.retFrom==null,'보정이 현재 계약을 덮거나 옛 요청 미정리');ok(e.done&&!(G.mail.find(m=>m.id===e.mid).acts||[]).length,'옛 복귀 메일 선택지가 남음');ok(JSON.stringify(G.moves)===moves,'현재 계약 보정에 새 이동 생성');const before=JSON.stringify(G);ovsPostFix();ok(JSON.stringify(G)===before&&__rngState()===seed,'계약 보정이 반복/난수 변경');});
T('[검수 11-18 #812 옛 1년 복귀보정추가] 이미 연차 보정된 옛 포스팅 1년 계약의 ext만 고치고 다년 잔여 1년은 유지한다 [해외복귀검수]',()=>{fr810Fresh();const tid=otherT(),p=domestic(tid).find(p=>!p.foreign&&!p.ys),q=domestic(tid).find(q=>!q.foreign&&!q.ys&&q!==p);for(const x of [p,q]){x.svc=faSvc(x)-1;x.story=[{y:G.year,t:'MLB 생활을 마치고 복귀(연봉 계약)',k:'move'}];delete x.lastFA;}Object.assign(p,{faC:false,ext:true,yrs:1});delete p.cyrs;Object.assign(q,{faC:true,ext:true,yrs:1,cyrs:3});G.abroad=[p,q].map(x=>({id:x.id,from:tid,how:'포스팅',back:true,backY:G.year,nsv:1,lines:[]}));const seed=__rngState();ovsPostFix();ok(!p.ext&&preFA(p),'옛 1년 복귀의 ext 표시 미정리');ok(q.faC&&q.ext&&q.cyrs===3,'3년 계약의 잔여1년을 단년계약으로 변경');const before=JSON.stringify(G);ovsPostFix();ok(JSON.stringify(G)===before&&__rngState()===seed,'옛 단년 계약 보정 반복/난수 변경');});
T('[검수 11-18 #810 실제 불러오기] 직렬화한 옛 우선협상 무적 기록은 실제 로더에서 한 번 정리되고 요청은 유지된다 [해외복귀검수]',()=>{fr810Fresh();migrateDraft();const p=fr810Pending();ovsBackAsk(p);G=JSON.parse(JSON.stringify(G));const pid=p.id,seed=__rngState();migrateDraft();const q=G.players[pid];ok(q.retAsk&&q.retFrom===G.user&&q.team==null&&!isFree(q)&&q.freeSince==null,'실제 로더가 옛 복귀/무적 중복을 정리하지 않음');const before=JSON.stringify(G);migrateDraft();ok(JSON.stringify(G)===before&&__rngState()===seed,'실제 복귀 로더 반복/주난수 변경');});

/* foreign-rules-815-tests.txt */
const foreign815Case=(ai=false,born=0,mix=[true,true,false,false])=>{fresh();G.day=KD(11,10);G.last={y:G.year};G.rolled=G.year;const tid=ai?otherT():G.user;for(const q of Object.values(G.players))if(q.team===tid&&q.foreign)q.team=null;team(tid).born=born||G.year;const L=mix.map((isP,i)=>{const q=newForeign('용병',{isP});q.team=tid;q.sal=100;q.newSal=100;q.age=28;q.rsy=0;q.fy=G.year;delete q.fMulti;delete q.joinY;setOvr(q,65);return q;});G.contract={y:G.year,tid,ended:[],foreignEnd:L.map(q=>q.id),foreignDrop:[],released:[],fre:Object.fromEntries(L.map(q=>[q.id,{n:1,ok:true}])),done:false};return {tid,L,C:G.contract,y:G.year};};
T('[검수 11-18 #815] 신생 구단 재계약 총액에는 다음 시즌의 창단 가산이 포함된다 [외국인규정검수]',()=>{const {L,C,y,tid}=foreign815Case();const target=fTotCap()+10*USD*L.length+700;L.forEach(q=>q.newSal=target/L.length);const f=fReCapInfo();ok(f.tot===target&&f.over===0,'창단14억 가산 누락 '+JSON.stringify(f));ok(f.cap>=target,'창단가산 cap');const r=confirmContracts();ok(C.done&&L.every(q=>q.team===tid),'적법한 4명 계약 확정 실패 '+r);});
T('[검수 11-18 #816] 신생 구단의 투수3명 구성은 신규 영입과 재계약이 함께 허용한다 [외국인규정검수]',()=>{const {L,C,tid}=foreign815Case(false,0,[true,true,true]);ok(!fYBMixErr(tid,L),'준비: 신규 구성은 적법');ok(!fReMixBad(),'재계약만 투수3명을 금지');const r=confirmContracts();ok(C.done&&L.every(q=>q.team===tid),'적법한 구성 확정 실패 '+r);});
T('[검수 11-18 #817] 창단 혜택이 끝나는 다음 시즌에는 네 명 재계약을 확정할 수 없다 [외국인규정검수]',()=>{const {L,C,tid}=foreign815Case();team(tid).born=G.year-1;ok(fMaxYB(tid,G.year)===4&&fMaxYB(tid,G.year+1)===3,'준비: 혜택 종료');const snap=L.map(q=>q.sal),r=confirmContracts();ok(!C.done&&L.every(q=>q.team===tid&&q.sal===snap[L.indexOf(q)]),'네 명 유지 계약이 완료됨 '+r);ok(typeof r==='string'&&r.includes('3'),'정원 거절 안내 없음');});
T('[검수 11-18 #818] AI 재계약도 다음 시즌 유효 인센티브를 합쳐 총액 초과를 정리한다 [외국인규정검수]',()=>{const {tid,L,y}=foreign815Case(true,0,[true,true,false]);delete team(tid).born;for(const q of Object.values(G.players))if(q.foreign&&q.team!==tid)q.team=null;const [a,b,p]=L;a.sal=b.sal=1700;a.fy=b.fy=y+1;a.rsy=b.rsy=1;for(const q of [a,b]){q.ctT=tid;q.opt={a:900,from:y+1,until:y+1,c:optCrit(q)};}p.sal=1500;setOvr(a,70);setOvr(b,70);setOvr(p,60);p.hist=[Object.assign({y,t:tid,lvl:'1군'},ZB,{pa:500,ab:450,h:160,d2:35,d3:3,hr:25,bb:50,g:130})];const ns=newSalary;try{newSalary=q=>q===p?1800:ns(q);G.contract=null;contractStart();}finally{newSalary=ns;}const kept=foreignOf(tid).filter(q=>q.foreign==='용병'),total=sum(kept.map(q=>fCommit(q,y+1)));ok(total<=fCap(tid),'AI 인센티브 포함 총액 초과 '+total+'/'+fCap(tid));ok(kept.length<3,'초과 선수 세 명 모두 잔류');});
T('[검수 11-18 #826] 시즌 중 외국인 계약은 인센티브 금액과 출전 기준을 같은 비율로 줄인다 [외국인규정검수]',()=>{fresh();G.day=KD(7,20);G.last=null;G.rolled=G.year-1;for(const q of foreignOf(G.user))q.team=null;const q=newForeign('용병',{isP:false});q.ask=700;G.fmarket.push(q.id);const fr=remainFrac();ok(fr>0&&fr<.5,'준비: 잔여일정 비율 '+fr);const e=signForeignT(G.user,q.id,700,300);ok(!e&&q.team===G.user,'준비: 실제 계약 '+e);ok(q.opt.a===Math.round(300*fr),'금액 비례 누락');q.hist=[Object.assign({y:G.year,t:G.user,lvl:'1군'},ZB,{pa:Math.ceil(510*fr),ab:Math.ceil(480*fr),h:Math.ceil(150*fr),g:Math.ceil(120*fr)})];G.day=G.cal.end;G.sea.rec[G.user]={w:72,l:72,t:0};ok(optEarned(q),'풀시즌510PA페이스인데 지급 미달 '+q.hist[0].pa);const a=optSettle(G.user);ok(a===Math.round(300*fr)&&optSettle(G.user)===0,'인센티브 정산 금액 또는 중복 지급');});
T('[검수 11-18 #827] 다음 시즌 옵션은 올해 외국인 총액에서 제외하고 유효 시즌에만 포함한다 [외국인규정검수]',()=>{fresh();G.day=KD(6,1);G.last=null;G.rolled=G.year-1;const p=foreignOf(G.user).find(q=>q.foreign==='용병');p.sal=500;p.ctT=p.team;p.opt={a:200,from:G.year+1,until:G.year+1,c:optCrit(p)};ok(!optEarned(p),'준비: 올해 지급 없음');const r=__rngState(),s=JSON.stringify(p);ok(fCommit(p,G.year)===500,'시작 전 옵션이 올해 한도에 포함');ok(fCommit(p,G.year+1)===700&&fCommit(p,G.year+2)===500,'유효기간 총액 계산');ok(fCommit(p)===500&&JSON.stringify(p)===s&&__rngState()===r,'기본시즌 또는 조회가 저장·난수 변경');});
T('[검수 11-18 #817 마감] 자동 확정도 다음 시즌 정원을 맞춘 뒤 계약을 마친다 [외국인규정검수]',()=>{const {L,C,tid}=foreign815Case();team(tid).born=G.year-1;confirmContracts(true);const kept=L.filter(q=>q.team===tid&&G.players[q.id]);ok(C.done&&kept.length===3,'마감 확정 후 네 명 유지 또는 확정 누락 '+kept.length);ok(kept.filter(q=>q.isP).length<3&&kept.filter(q=>!q.isP).length<3,'마감 뒤 구성 위반');});
T('[검수 11-18 #816 마감] 신생 구단의 적법한 세 투수는 자동 확정으로 잃지 않는다 [외국인규정검수]',()=>{const {L,C,tid}=foreign815Case(false,0,[true,true,true]);confirmContracts(true);ok(C.done&&L.every(q=>G.players[q.id]&&q.team===tid),'마감에 적법한 세 투수 중 결별');});
T('[검수 11-18 #826 기준] 인센티브 출전량만 비례하고 타율·OPS·ERA와 수상 기준은 그대로다 [외국인규정검수]',()=>{fresh();G.day=KD(7,20);G.sea.rec[G.user]={w:72,l:72,t:0};const p=domestic(G.user).find(q=>!q.isP),sp=domestic(G.user).find(q=>q.isP);p.ctT=p.team;sp.ctT=sp.team;for(const [c,field,n] of [['b','pa',400],['bg','g',120],['sp','outs',360],['rp','outs',150],['rpg','g',50],['sv','sv',20],['hld','hld',20]]){const q=['sp','rp','rpg','sv','hld'].includes(c)?sp:p;q.opt={a:100,from:G.year,until:G.year,c,fr:.5};const h=Object.assign({},q.isP?ZP:ZB,{[field]:n*.5});ok(optMet(c,h,q,1),'비례 출전 기준 미달 '+c);h[field]--;ok(!optMet(c,h,q,1),'비례 출전 기준 미달인데 달성 '+c);}p.opt={a:100,from:G.year,until:G.year,c:'avg',fr:.5};let h=Object.assign({},ZB,{pa:225,ab:200,h:60});ok(optMet('avg',h,p,1),'절반 규정타석 .300 미인정');h.h=59;ok(!optMet('avg',h,p,1),'타율 .295를 .300옵션 달성으로 할인');sp.opt={a:100,from:G.year,until:G.year,c:'era',fr:.5};h=Object.assign({},ZP,{outs:216,er:28});ok(optMet('era',h,sp,1),'절반 규정이닝 ERA3.50 미인정');h.er=29;ok(!optMet('era',h,sp,1),'ERA한도까지 할인');p.opt.c='as';p.aw=[];ok(!optEarned(p),'비례만으로 수상 인정');p.aw=[G.year+' 올스타(나눔)'];ok(optEarned(p),'실제 올스타는 인정');});
T('[검수 11-18 #826 복원] 시즌 중 외국인 옵션은 JSON 복원 뒤 같은 기준과 지급액을 유지한다 [외국인규정검수]',()=>{fresh();G.day=KD(7,20);for(const q of foreignOf(G.user))q.team=null;const p=newForeign('용병',{isP:false});p.ask=700;G.fmarket.push(p.id);const fr=remainFrac();ok(!signForeignT(G.user,p.id,700,300),'준비: 실제 계약');const id=p.id;G=JSON.parse(JSON.stringify(G));const q=G.players[id];q.hist=[Object.assign({y:G.year,t:G.user,lvl:'1군'},ZB,{pa:Math.ceil(450*fr),ab:Math.ceil(400*fr),h:Math.ceil(120*fr)})];const r=__rngState(),s=JSON.stringify(q);ok(optEarned(q)&&optEarned(q),'JSON 뒤 비례기준 소실');ok(__rngState()===r&&JSON.stringify(q)===s,'반복 기준 조회가 난수·선수 저장 변경');});
T('[검수 11-18 #826 구형] 실제 입단일과 일정이 남은 옛 옵션만 무난수 멱등으로 복원한다 [외국인규정검수]',()=>{fresh();G.day=KD(7,20);for(const q of foreignOf(G.user))q.team=null;const p=newForeign('용병',{isP:false});p.ask=700;G.fmarket.push(p.id);const fr=remainFrac();ok(!signForeignT(G.user,p.id,700,300),'준비: 실제 계약');delete p.opt.fr;p.hist=[Object.assign({y:G.year,t:G.user,lvl:'1군'},ZB,{pa:Math.ceil(450*fr),ab:Math.ceil(400*fr),h:Math.ceil(120*fr)})];const r=__rngState();ok(optProrationFix(p)===1&&Math.abs(p.opt.fr-fr)<1e-12,'옛 현재시즌 비율 복원');const s=JSON.stringify(p);ok(optProrationFix(p)===0&&JSON.stringify(p)===s&&__rngState()===r,'정리가 무난수 멱등 아님');ok(optEarned(p),'복원한 출전 조건 미적용');const q={...p,opt:{...p.opt}};delete q.opt.fr;delete q.fjD;ok(optProrationFix(q)===0&&!('fr'in q.opt),'입단 근거 없는 저장을 추측 수정');});
T('[검수 11-18 외국인 규정] 미리보기와 새해 조회는 같은 계약 시즌 명단을 무난수로 계산한다 [외국인규정검수]',()=>{const {tid,L,C,y}=foreign815Case();L[0].fInc=200;const f=fReCapInfo();const r=__rngState(),s=JSON.stringify(G);const a=fYBInfo(tid,fReRoster(tid,y+1,C),y+1);ok(a.tot===f.tot&&a.cap===f.cap&&a.max===4,'사용자 전망과 공통값 불일치');ok(JSON.stringify(G)===s&&__rngState()===r,'공통 미리보기 저장·난수 변경');G.year=y+1;G.day=dnum(G.year,1,5);G.last={y};const b=fReCapInfo();ok(b.tot===f.tot&&b.cap===f.cap&&b.max===4,'새해에 같은 계약 대상 시즌 값이 변경');});
T('[검수 11-18 #818 난수] 새 인센티브 위반은 주 난수를 더 쓰지 않고 옛 보장 초과의 한 자리는 보존한다 [외국인규정검수]',()=>{const {tid,L,y}=foreign815Case(true,0,[true,true,false]);delete team(tid).born;G.contract=null;for(const q of L){q.sal=1700;q.rsy=1;q.ctT=tid;q.opt={a:900,from:y+1,until:y+1,c:optCrit(q)};setOvr(q,60);}let n=0;const prev=FO_RNG;FO_RNG=()=>{n++;return .25;};try{fAiRePrune(tid,y+1);}finally{FO_RNG=prev;}ok(n===0,'새 옵션 위반이 주 난수 소비 '+n);ok(fYBInfo(tid,foreignOf(tid),y+1).over===0,'새 위반 정리 누락');const next=foreign815Case(true,0,[true,true,false]);delete team(next.tid).born;G.contract=null;next.L.forEach(q=>{q.sal=2500;delete q.opt;setOvr(q,60);});n=0;FO_RNG=()=>{n++;return .25;};try{fAiRePrune(next.tid,next.y+1);}finally{FO_RNG=prev;}ok(n===1,'기존 초과 분기의 난수 자리 변경 '+n);});
T('[검수 11-18 #826 표시] 실제 최소 타석·아웃 수를 표시하고 전 시즌·율·수상 조건은 유지한다 [외국인규정검수]',()=>{fresh();const p=domestic(G.user).find(q=>!q.isP),q=domestic(G.user).find(q=>q.isP);p.opt={a:100,c:'b',from:G.year,until:G.year,fr:.55};ok(optCountNeed(p,'b')===220&&optLabel(p).startsWith('220타석'),'실제 최소타석 표시 '+optLabel(p));ok(optMet('b',Object.assign({},ZB,{pa:220}),p,1),'부동소수 경계 220PA 미인정');q.opt={a:100,c:'sp',from:G.year,until:G.year,fr:.36};ok(optCountNeed(q,'sp')===130&&optLabel(q).startsWith('43.1이닝'),'아웃카운트 표시 '+optLabel(q));p.opt.fr=1;ok(optLabel(p)==='400타석','풀시즌 조건이 변경');for(const c of ['avg','ops','era','gg','as']){p.opt.c=c;p.opt.fr=.36;ok(optLabel(p).startsWith(OPT_CRIT[c][2]),'율·수상 조건 표시 변경 '+c);}p.opt.c='b';const before=optLabel(p),r=__rngState();p.opt=JSON.parse(JSON.stringify(p.opt));ok(optLabel(p)===before&&__rngState()===r,'JSON·표시 조회로 조건 변경');});
T('[검수 11-18 #818 확정] 인센티브 없는 새 합의는 전망과 실제 계약에서 모두 옛 옵션을 대체한다 [외국인규정검수]',()=>{const {tid,L,C,y}=foreign815Case(false,0,[true,true,false]);const p=L[0];p.ctT=tid;p.opt={a:900,c:optCrit(p),from:y+1,until:y+1};const f=fReCapInfo();ok(f.tot===300,'명시적인 무옵션 합의 전망');confirmContracts();ok(C.done&&!p.opt,'실제 무옵션 합의 뒤 옛 옵션 잔류');ok(fYBInfo(tid,foreignOf(tid),y+1).tot===f.tot,'확정 전후 총액 차이');});

/* foreign-exit-819-tests.txt */
/* 검수 810~829: 이미 체결한 외국인 계약과 구단에 남은 제안·계약 종료. */
const FE819_WORLD=()=>{globalThis.__seed(819001);buildWorld({lite:true});claimTeam(6);G.day=KD(11,20);G.last={y:G.year};G.rolled=G.year;G.evs=[];G.contract=null;G.moves=[];G.fmarket=[];return G;};
const FE819_PLAYER=(tid,kind)=>{for(const old of foreignOf(tid))old.team=null;const p=newForeign(kind||'용병',{isP:false,pos:'1B',team:tid,age:30});p.team=tid;p.fy=G.year;p.sal=1000;p.yrs=1;p.rsy=0;p.mor=60;setOvr(p,61);delete p.fCtY;delete p.fMulti;delete p.kept;delete p.fRel;delete p.opt;delete p.fInc;return p;};
T('[검수 11-18 #819] 해외 제안을 막고 체결한 다음 시즌 계약은 같은 겨울 재계약 대상이 되지 않는다 [외국인종료검수]',()=>{FE819_WORLD();const p=FE819_PLAYER(G.user),tid=p.team;p.ovsOffer={lg:'NPB',club:NPBT[0],yrs:2,amt:300,y:G.year};globalThis.__seed(7);const res=EVH.fovs.pick({data:{pid:p.id,ks:3570}},0);ok(p.kept&&p.sal===3570&&!p.ovsOffer,'설득 성공 준비 '+res);p.fout={y:G.year,k:'일본',v:6000};contractStart();ok(!G.contract.foreignEnd.includes(p.id)&&p.fCtY>=G.contract.y+1,'잔류 계약을 맺고 같은 겨울 재계약 대상에 다시 등록');const r=p.rsy;confirmContracts(true);ok(G.players[p.id]&&p.team===tid&&p.sal===3570&&p.rsy===r&&!(G.abroad||[]).some(x=>x.id===p.id&&!x.back),'두 번째 해외 제안이 이미 체결한 계약을 덮어씀');});
T('[검수 11-18 #820 AI] 아시아쿼터 해외 잔류 판단은 유효 인센티브를 더한 개인 상한으로 확인한다 [외국인종료검수]',()=>{FE819_WORLD();const tid=otherT(),p=FE819_PLAYER(tid,'아시아');p.sal=264;p.ctT=tid;p.opt={a:100,c:'pa400',from:G.year+1,until:G.year+1};ok(390<=asiaReCap(p)&&390+100>asiaReCap(p),'개인 상한 경계 준비');ok(!fovsAiTry(p,390),'AI가 보장 3.9억+인센티브 1억의 상한 초과 잔류를 허용');});
T('[검수 11-18 #820 사용자] 잔류 버튼도 인센티브 때문에 개인 상한을 넘으면 계약하지 않는다 [외국인종료검수]',()=>{FE819_WORLD();const p=FE819_PLAYER(G.user,'아시아');p.sal=264;p.ctT=p.team;p.opt={a:100,c:'pa400',from:G.year+1,until:G.year+1};p.ovsOffer={lg:'NPB',club:NPBT[0],yrs:1,amt:30,y:G.year};globalThis.__seed(7);EVH.fovs.pick({data:{pid:p.id,ks:390}},0);ok(!G.players[p.id]||!p.kept||fCommit(p,G.year+1)<=asiaReCap(p),'사용자 잔류가 보장·인센티브 상한을 초과');});
T('[검수 11-18 #821] 실제 이직은 전 구단 해외 제안을 후임 AI가 종결하고 결과·해외 이력을 남긴다 [외국인종료검수]',()=>{FE819_WORLD();const p=FE819_PLAYER(G.user),old=G.user,tid=otherT();team(old).plan={k:'tight',y:G.year};p.ovsOffer={lg:'NPB',club:NPBT[0],yrs:1,amt:600,y:G.year};const e=evNew('fovs','외국인 해외 제안','이직 인계 검수',[{l:'잔류',fx:''},{l:'출국',fx:''}],{data:{pid:p.id,ks:7000},def:1});switchTeam(tid);ok(e.done&&!p.ovsOffer,'이직 후 이벤트만 닫고 선수의 해외 제안이 남음');ok((G.abroad||[]).filter(x=>x.id===p.id&&!x.back).length===1&&!(G.players||{})[p.id],'후임의 결별 판단이 해외 이력과 실제 출국으로 이어지지 않음');ok(e.res&&String(e.res).length>0,'이직 처리 결과가 결정 기록에 없음');});
T('[검수 11-18 #822] AI 외국인 계약 종료도 사용자와 같은 선수 이동 기록과 보류권을 남긴다 [외국인종료검수]',()=>{FE819_WORLD();const tid=otherT(),p=FE819_PLAYER(tid);p.age=35;contractStart();ok(!G.players[p.id],'AI 계약 종료 준비');const m=(G.moves||[]).filter(x=>x.pid===p.id&&x.t==='외국인 계약 종료');ok(m.length===1&&m[0].from===tid&&m[0].to==null,'AI 계약 종료에서 선수 이동 이력이 없음');ok(foResFor(p)&&foResFor(p).tid===tid,'일반 결별의 원구단 보류권이 없음');});
T('[검수 11-18 #823] 보류권 해제 조항이 있는 AI 외국인도 계약 종료 뒤 같은 국내 시장에 등록된다 [외국인종료검수]',()=>{FE819_WORLD();const tid=otherT(),p=FE819_PLAYER(tid);p.age=33;p.fRel=true;contractStart();ok(G.players[p.id]===p&&p.team==null&&(G.fmarket||[]).includes(p.id),'AI가 권리 해제된 33세 OVR61 외국인을 국내 시장 대신 삭제');ok(!foResFor(p)&&!p.fRel&&!p.opt,'새 국내 계약에 옛 권리·계약 조항이 남음');ok((G.moves||[]).some(x=>x.pid===p.id&&x.t==='외국인 계약 종료'&&x.from===tid),'권리 해제 이동 이력 누락');});
T('[검수 11-18 #819 AI] 실제 AI 잔류 성공도 다음 시즌 계약을 즉시 잠그고 같은 제안을 다시 만들지 않는다 [외국인종료검수]',()=>{FE819_WORLD();const tid=otherT(),p0=FE819_PLAYER(tid);team(tid).plan={k:'win',y:G.year};team(tid).cash=100000;const id=p0.id,S=JSON.stringify(G),sw=seasonWar;let p=null;try{seasonWar=x=>x.id===id?6:0;for(let s=1;s<=100;s++){G=JSON.parse(S);globalThis.__seed(819100+s);fOverseas();if(G.players[id]&&G.players[id].kept){p=G.players[id];break;}}ok(p,'실제 AI 잔류 성공 표본 준비');ok(p.fCtY===G.year+1&&p.rsy===1,'AI 잔류 성공을 다음 시즌 계약으로 기록하지 않음');const j=JSON.stringify(G),r=globalThis.__rngState();fOverseas();ok(JSON.stringify(G)===j&&globalThis.__rngState()===r,'계약을 마친 AI 선수에게 새 해외 제안을 다시 생성');}finally{seasonWar=sw;}});
T('[검수 11-18 #822~823 공통] 같은 권리 해제 계약의 사용자·AI 종료는 시장·계약 정리·이동 기록이 같다 [외국인종료검수]',()=>{const rows=[];for(const ai of [false,true]){FE819_WORLD();const tid=ai?otherT():G.user,p=FE819_PLAYER(tid);p.age=33;p.fRel=true;p.ctT=tid;p.opt={a:100,c:'pa400',from:G.year,until:G.year};p.kept={y:G.year-1,sal:p.sal,base:800};p.fCtY=G.year;const id=p.id;if(ai)contractStart();else fReFinish({y:G.year,tid,foreignEnd:[id],foreignDrop:[id],fre:{},fFree:[]},tid);const q=G.players[id],m=(G.moves||[]).filter(x=>x.pid===id&&x.t==='외국인 계약 종료');rows.push({market:!!q&&q.team==null&&G.fmarket.includes(id),terms:!!q&&!q.opt&&!q.ctT&&!q.fRel&&!q.fCtY&&!q.kept,moves:m.length,from:m[0]&&m[0].from===tid,to:m[0]&&m[0].to==null,rights:!!foResFor(p)});}ok(rows.every(x=>x.market&&x.terms&&x.moves===1&&x.from&&x.to&&!x.rights),'사용자·AI 계약 종료 의미 불일치 '+JSON.stringify(rows));});
T('[검수 11-18 #819~821 불러오기] 실제 불러오기는 옛 잔류 계약과 AI의 미결 제안을 복구하며 반복해도 결정을 중복하지 않는다 [외국인종료검수]',()=>{FE819_WORLD();migrateDraft();const p=FE819_PLAYER(G.user),q=FE819_PLAYER(otherT()),y=G.year;p.kept={y,sal:3570,base:1000};p.sal=3570;p.rsy=2;delete p.fCtY;q.ovsOffer={lg:'NPB',club:NPBT[0],yrs:1,amt:600,y};team(q.team).plan={k:'tight',y};const e=evNew('fovs','옛 단장에게 온 해외 제안','인계 복원',[{l:'잔류',fx:''},{l:'출국',fx:''}],{data:{pid:q.id},def:1});e.done=true;G=JSON.parse(JSON.stringify(G));const r=globalThis.__rngState();migrateDraft();ok(G.players[p.id].fCtY===y+1&&G.players[p.id].rsy===3,'옛 잔류 계약을 실제 불러오기에서 복원하지 않음');ok(!G.players[q.id]&&(G.abroad||[]).filter(x=>x.id===q.id&&!x.back).length===1,'옛 단장이 떠난 AI 구단 제안이 복원되지 않음');ok(globalThis.__rngState()===r,'불러오기 인계가 주 난수를 소비');const j=JSON.stringify(G);migrateDraft();ok(JSON.stringify(G)===j&&globalThis.__rngState()===r,'실제 두 번째 불러오기가 저장 또는 난수를 변경');});
T('[검수 11-18 #821 계약 인계] 연봉 협상 중 이직해도 이미 온 해외 제안을 새 계약으로 덮지 않고 후임이 마무리한다 [외국인종료검수]',()=>{FE819_WORLD();const p=FE819_PLAYER(G.user),tid=otherT(),old=G.user;team(old).plan={k:'tight',y:G.year};p.ovsOffer={lg:'NPB',club:NPBT[0],yrs:1,amt:600,y:G.year};p.newSal=1000;G.contract={y:G.year,tid:old,ended:[],foreignEnd:[p.id],foreignDrop:[],released:[],done:false,fre:{},neg:{}};const e=evNew('fovs','해외 제안 대기 중 이직','계약보다 먼저 온 제안',[{l:'잔류',fx:''},{l:'출국',fx:''}],{data:{pid:p.id},def:1});switchTeam(tid);ok(!G.players[p.id]&&e.done&&e.res&&(G.abroad||[]).some(x=>x.id===p.id&&x.from===old),'이직의 연봉 인계가 실제 해외 제안을 누락하거나 덮어씀');});
T('[검수 11-18 #821 난수] 같은 해외 제안 인계는 주 난수 없이 한 번만 처리하고 메일·결정 장부를 함께 닫는다 [외국인종료검수]',()=>{FE819_WORLD();const tid=otherT(),p=FE819_PLAYER(tid);team(tid).plan={k:'tight',y:G.year};p.ovsOffer={lg:'NPB',club:NPBT[0],yrs:1,amt:600,y:G.year};const e=evNew('fovs','후임 처리 제안','중복 방지',[{l:'잔류',fx:''},{l:'출국',fx:''}],{data:{pid:p.id},def:1}),r=globalThis.__rngState();ok(fovsHandOff(tid)===1&&globalThis.__rngState()===r,'인계가 주 난수를 사용하거나 처리하지 않음');const mail0=G.mail.find(x=>x.id===e.mid);ok(e.done&&e.res&&mail0.acts.length===0&&!mail0.imp&&(G.evlog||[]).filter(x=>x.id===e.id).length===1,'이벤트·메일·결정 장부가 함께 종결되지 않음');const j=JSON.stringify(G);ok(fovsHandOff(tid)===0&&JSON.stringify(G)===j&&globalThis.__rngState()===r,'같은 인계가 중복 출국이나 기록을 만듦');});
T('[검수 11-18 #819 약정] 기존 해외 제안 카드보다 뒤에 국내 재계약에 합의했으면 그 약정을 보존한다 [외국인종료검수]',()=>{FE819_WORLD();const p=FE819_PLAYER(G.user),sal=p.sal;p.newSal=1800;p.fInc=100;p.ovsOffer={lg:'NPB',club:NPBT[0],yrs:1,amt:600,y:G.year};G.contract={y:G.year,tid:G.user,ended:[],foreignEnd:[p.id],foreignDrop:[],released:[],done:false,fre:{[p.id]:{ok:true}},neg:{}};const r=globalThis.__rngState();EVH.fovs.pick({data:{pid:p.id,ks:5000}},1);ok(G.players[p.id]&&p.team===G.user&&p.sal===sal&&p.newSal===1800&&p.fInc===100&&!p.ovsOffer&&globalThis.__rngState()===r,'옛 해외 제안이 이후 국내 약정을 덮거나 출국시킴');});
T('[검수 11-18 #821~824 해외 결별] 실제 사용자·AI 역수출도 계약 조항대로 보류권을 유지하거나 모두 해제한다 [외국인종료검수]',()=>{for(const ai of [false,true])for(const free of [false,true]){FE819_WORLD();const tid=ai?otherT():G.user,p=FE819_PLAYER(tid);p.fRel=free;if(free)foResAdd(p,tid);const id=p.id,sw=seasonWar,ko=fovsKeepOdds;try{if(ai){team(tid).plan={k:'tight',y:G.year};seasonWar=q=>q.id===id?6:0;fovsKeepOdds=()=>0;for(let k=1;k<=50&&G.players[id];k++){globalThis.__seed(821000+k);fOverseas();}}else{p.ovsOffer={lg:'NPB',club:NPBT[0],yrs:1,amt:600,y:G.year};EVH.fovs.pick({data:{pid:id}},1);}ok(!G.players[id]&&(G.abroad||[]).filter(x=>x.id===id&&!x.back).length===1,'실제 역수출 경로 출국 준비');const h=foResFor(p);ok(free?!h:!!h&&h.tid===tid,'역수출의 보류권 조항 불일치 AI='+ai+' 해제='+free);}finally{seasonWar=sw;fovsKeepOdds=ko;}}});
T('[검수 11-18 #819 새 계약] 다음 시즌 신규 계약으로 복귀한 선수에게도 옛 해외 제안 카드가 적용되지 않는다 [외국인종료검수]',()=>{FE819_WORLD();const p=FE819_PLAYER(G.user);p.fy=G.year+1;p.sal=1500;p.ovsOffer={lg:'NPB',club:NPBT[0],yrs:1,amt:600,y:G.year};const r=globalThis.__rngState();EVH.fovs.pick({data:{pid:p.id}},1);ok(G.players[p.id]===p&&p.team===G.user&&p.sal===1500&&!p.ovsOffer&&globalThis.__rngState()===r,'이후 체결한 신규 계약을 옛 해외 제안이 취소');});
T('[검수 11-18 #815~820 안내] 실제 해외 제안 메일은 신생 구단 다음 시즌 정원과 아시아 개인 총액 상한을 구분해 안내한다 [외국인종료검수]',()=>{for(const kind of ['용병','아시아']){FE819_WORLD();team(G.user).born=G.year;const p=FE819_PLAYER(G.user,kind),id=p.id,S=JSON.stringify(G),sw=seasonWar;let e=null;try{seasonWar=q=>q.id===id?6:0;for(let k=1;k<=50&&!e;k++){G=JSON.parse(S);globalThis.__seed(820500+k);fOverseas();e=(G.evs||[]).find(x=>x.k==='fovs'&&x.data.pid===id);}ok(e,'해외 제안 메일 준비');const fx=e.opts[0].fx,m=G.mail.find(x=>x.id===e.mid);ok(m&&m.body.includes(fx),'실제 소식함 메일에 제안 규정이 없음');ok(e.opts[0].l.includes('연봉 '+money(e.data.ks)),'실제 메일 버튼 금액과 저장한 잔류 약정액이 다름');if(kind==='아시아')ok(fx.includes('보장 연봉과 인센티브 합계')&&fx.includes('개인 상한')&&!fx.includes('상한이 없'),'아시아쿼터를 개인 상한 없는 계약으로 안내');else ok(fx.includes('다음 시즌 일반 외국인 4명')&&!fx.includes('3명 총액'),'신생 구단 다음 시즌 정원이 3명으로 안내');}finally{seasonWar=sw;}}});

T('[검수 11-18 #819 결별 뒤 잔류] 같은 겨울 결별 표시 뒤 해외 제안 잔류에 성공하면 실제 유지 선수를 다음 시즌 명단·총액에 포함한다 [외국인종료검수]',()=>{FE819_WORLD();const p=FE819_PLAYER(G.user),sy=G.year+1;p.ctT=p.team;p.opt={a:150,c:'pa400',from:sy,until:sy};p.ovsOffer={lg:'NPB',club:NPBT[0],yrs:1,amt:300,y:G.year};p.newSal=1000;G.contract={y:G.year,tid:G.user,ended:[],foreignEnd:[p.id],foreignDrop:[p.id],released:[],done:false,fre:{},neg:{}};const ko=fovsKeepOdds;try{fovsKeepOdds=()=>1;EVH.fovs.pick({data:{pid:p.id,ks:2000}},0);const kept=G.players[p.id]===p&&p.team===G.user&&p.sal===2000&&p.fCtY===sy,info=fReCapInfo(),listed=fReRoster(G.user,sy).some(q=>q.id===p.id);console.log('DROP_STAY_EDGE',JSON.stringify({kept,foreignDrop:G.contract.foreignDrop,foreignEnd:G.contract.foreignEnd,pending:fRePending(),listed,projected:info.tot,actual:fCommit(p,sy)}));ok(kept,'실제 잔류 성공 준비');ok(listed&&info.tot===fCommit(p,sy)&&!G.contract.foreignDrop.includes(p.id)&&!fRePending().includes(p.id),'유지한 선수가 결별 목록에 남아 다음 시즌 명단·총액에서 누락');}finally{fovsKeepOdds=ko;}});
T('[검수 11-18 #819 결별 명단 복원] 옛 잔류 계약의 결별 명단 충돌만 복원하고 이후 신규 계약·합의는 보존한다 [외국인종료검수]',()=>{FE819_WORLD();migrateDraft();const p=FE819_PLAYER(G.user),sy=G.year+1;p.kept={y:G.year,sal:2000,base:1000};p.sal=2000;p.fCtY=sy;p.rsy=3;p.fleft=true;p.ctT=G.user;p.opt={a:150,c:'pa400',from:sy,until:sy};G.contract={y:G.year,tid:G.user,foreignEnd:[p.id],foreignDrop:[p.id],ended:[],released:[],done:false,fre:{},fneg:{[p.id]:true},neg:{}};G=JSON.parse(JSON.stringify(G));const r=globalThis.__rngState();migrateDraft();const q=G.players[p.id];ok(!G.contract.foreignDrop.includes(p.id)&&!G.contract.foreignEnd.includes(p.id)&&!q.fleft&&!G.contract.fneg[p.id]&&q.rsy===3&&fReCapInfo().tot===2150&&fRePending().length===0,'옛 유지 계약이 결별·협상 명단에 남아 예산에서 빠짐');const j=JSON.stringify(G);migrateDraft();ok(JSON.stringify(G)===j&&globalThis.__rngState()===r,'결별 명단 복원이 중복 연차·난수·저장을 변경');q.newSal=1800;q.fInc=100;G.contract.foreignEnd=[q.id];G.contract.foreignDrop=[];G.contract.fre={[q.id]:{ok:true}};const newer=JSON.stringify(G);fovsMigrate();ok(JSON.stringify(G)===newer,'옛 kept가 이후 새 국내 합의를 지움');G.contract.fre={};q.fy=sy;q.sal=2000;q.newSal=1700;G.contract.foreignDrop=[q.id];const fresh=JSON.stringify(G);fovsMigrate();ok(JSON.stringify(G)===fresh,'옛 kept가 이후 신규 계약의 결정 기록을 지움');});

/* foreign-rights-824-tests.txt */
/* 824·825·828·829 담당: 제품 편집 허용 전 baseline 재현 준비. */
const FR824=()=>{fresh();G.day=KD(12,15);G.contract=null;G.fRes=[];return G.user;};
T('[검수 11-18 #824] 실제 재계약 결별의 보류권 해제는 예전 중복 권리도 지워 다른 구단의 영입을 허용한다 [외국인권리검수]',()=>{const tid=FR824(),p=foreignOf(tid).find(x=>x.foreign==='용병'),other=otherT();ok(p,'외국인 준비');p.age=33;for(const k in p.r)p.r[k]=65;p.rsy=3;p.fRel=true;p.newSal=300;G.fRes=[{pid:p.id,name:p.name,nat:p.nat,tid,y:G.year-2,until:G.year+5},{name:p.name,nat:p.nat,tid,y:G.year-1,until:G.year+5},{pid:p.id+999999,name:p.name,nat:p.nat,tid,y:G.year,until:G.year+5}];const C={y:G.year,foreignEnd:[p.id],foreignDrop:[p.id],fFree:[],fre:{}};G.contract=C;fReFinish(C,tid);ok(G.players[p.id]===p&&p.team==null&&(G.fmarket||[]).includes(p.id),'준비: 해제 공지와 국내 시장');for(const x of foreignOf(other))x.team=null;p.ask=100;ok(!foResFor(p),'해제 후 예전 보류권 남음');ok((G.fRes||[]).some(x=>x.pid===p.id+999999),'ID가 다른 동명이인 권리까지 제거');ok(!foreignCheck(other,p),'해제 후 타 구단 영입 거절 '+foreignCheck(other,p));});
T('[검수 11-18 #825] 해외 추적과 JSON 복원 뒤 원구단 재영입은 실제 같은 구단 재계약 연차와 총액 가산을 보존한다 [외국인권리검수]',()=>{const tid=FR824(),p=foreignOf(tid).find(x=>x.foreign==='용병'&&!x.isP),id=p.id;p.age=29;for(const k in p.r)p.r[k]=65;p.rsy=3;p._ovsLg='NPB';p.hist=Array.from({length:4},(_,i)=>({...ZB,y:G.year-3+i,t:tid,lvl:'1군',g:130,pa:500,ab:450,h:145,hr:20,bb:45}));foResAdd(p,tid);dropP(id);let a=(G.abroad||[]).find(x=>x.id===id);ok(a&&a.fr&&!G.players[id],'실제 해외 추적 준비');a.lines=[{...ZB,y:G.year,lvl:'NPB',g:130,pa:500,ab:450,h:145,hr:20,bb:45}];G=JSON.parse(JSON.stringify(G));G.year++;G.cal=buildCalendar(G.year);G.day=dnum(G.year,1,2);G.contract=null;a=G.abroad.find(x=>x.id===id);const q=ovsRevive(a);ok(q&&q.id===id&&foResFor(q)?.tid===tid,'원구단 보류권과 같은 선수 복귀 준비');const cap0=fCap(tid);q.ask=100;const e=signForeign(tid,id);ok(!e,'원구단 실제 계약 준비 '+e);ok(q.rsy===3&&fCap(tid)-cap0===30*USD,'원구단 재계약 연차/가산 소실 '+q.rsy+'/'+(fCap(tid)-cap0));});
T('[검수 11-18 #828] 실제 신규 영입을 허용한 결별 예정 자리는 스카우트 필요 판정에서도 같은 유형의 빈자리다 [외국인권리검수]',()=>{const tid=FR824(),F=foreignOf(tid),p=F.find(x=>x.foreign==='용병'&&x.isP);ok(F.filter(x=>x.foreign==='용병').length===3&&F.some(x=>x.foreign==='아시아')&&p,'정원 준비');for(const q of F){q.newSal=300;delete q.fRel;}G.contract={y:G.year,done:false,foreignEnd:F.map(x=>x.id),foreignDrop:[p.id],fFree:[],fre:{}};const q=newForeign('용병',{isP:true,market:true});q.ask=100;ok(!foreignCheck(tid,q),'준비: 신규 영입 허용 '+foreignCheck(tid,q));const need=fNeed(tid);ok(need&&need.kind==='용병'&&need.isP===true,'영입 가능한 빈자리를 스카우트가 놓침 '+JSON.stringify(need));});
T('[검수 11-18 #829] 실제 단장 이직 직후 전 구단의 30일 관찰과80퍼센트 지식은 경쟁 구단과 평가에 계속 반영된다 [외국인권리검수]',()=>{const tid=FR824(),other=otherT(),q=newForeign('용병',{market:true});q.ask=100;G.fmarket=(G.fmarket||[]).concat(q.id);G.fwatch=[{id:q.id,since:G.day-30,k:80}];G.fwatchT={};G.fwAI={};ok(fWatchers(q).includes(tid)&&fwatchKT(tid,q.id)===80,'현 소속 관찰 준비');switchTeam(other);ok(G.fwatchT[tid]?.some(w=>w.id===q.id&&w.k===80),'실제 이직 기록 인계 준비');ok(fWatchers(q).includes(tid)&&fwatchKT(tid,q.id)===80,'이직 직후 전 구단 관심·관찰 지식 소실');G=JSON.parse(JSON.stringify(G));const j=JSON.stringify(G),r=__rngState();ok(fWatchers(G.players[q.id]).filter(t=>t===tid).length===1&&fwatchKT(tid,q.id)===80,'JSON 복원·중복 구단 조회 변경');ok(JSON.stringify(G)===j&&__rngState()===r,'조회가 저장·주 난수 변경');});
T('[검수 11-18 #824 옛 저장] 명시적인 마지막 해제 이동이 있는 시장 후보만 중복 권리를 무난수 멱등 정리한다 [외국인권리검수]',()=>{const tid=FR824(),p=newForeign('용병',{market:true}),q=newForeign('용병',{market:true});G.fmarket=(G.fmarket||[]).concat(p.id,q.id);foResAdd(p,tid);foResAdd(q,tid);G.fRes.push({name:p.name,nat:p.nat,tid,y:G.year-1,until:G.year+4});mvLog('외국인 계약 종료',p,tid,null,'재계약 결렬 · 보류권 해제 · 다른 구단과 계약 가능');G=JSON.parse(JSON.stringify(G));const r=__rngState(),rest=JSON.stringify({...G,fRes:null});ok(foResFix()===2&&!foResFor(G.players[p.id]),'명시 해제의 옛 권리 미정리');ok(foResFor(G.players[q.id])?.tid===tid,'해제 증거 없는 후보 권리까지 정리');const j=JSON.stringify(G);ok(foResFix()===0&&JSON.stringify(G)===j,'정리 반복이 저장 변경');ok(JSON.stringify({...G,fRes:null})===rest&&__rngState()===r,'권리 외 장부나 주 난수 변경');});
T('[검수 11-18 #825 옛 저장] 연차 사본 없는 해외 복귀도 마지막 연속 원구단 기록만 복원하고 타 구단 신규 계약은0이다 [외국인권리검수]',()=>{const tid=FR824(),other=otherT(),p=foreignOf(tid).find(x=>x.foreign==='용병'&&!x.isP),id=p.id;p.age=29;for(const k in p.r)p.r[k]=65;p.rsy=3;p._ovsLg='NPB';p.hist=Array.from({length:4},(_,i)=>({...ZB,y:G.year-3+i,t:tid,lvl:'1군',g:130,pa:500,ab:450,h:145,hr:20,bb:45}));foResAdd(p,tid);dropP(id);let a=G.abroad.find(x=>x.id===id);a.lines=[{...ZB,y:G.year,lvl:'NPB',g:130,pa:500,ab:450,h:145}];delete a.fr.rsy;delete a.fr.rsyT;for(const h of G.fRes)delete h.rsy;G=JSON.parse(JSON.stringify(G));G.year++;G.cal=buildCalendar(G.year);G.day=dnum(G.year,1,2);a=G.abroad.find(x=>x.id===id);const q=ovsRevive(a);q.ask=100;ok(q.rsy===3&&!signForeign(tid,id),'옛 실제 원구단4시즌 연차 미복원 '+q.rsy);foResRelease(q,tid);q.team=null;for(const x of foreignOf(other))x.team=null;q.ask=100;const base=fCap(other),e=signForeign(other,id);ok(!e&&q.rsy===0&&fCap(other)===base,'타 구단 신규 계약에 옛 원구단 연차 전이 '+e+'/'+q.rsy);});
T('[검수 11-18 #825 출처] 원구단 연차 조회는 다른 구단·끊긴 시즌·만료 권리를 합산하지 않고 저장과 난수를 보존한다 [외국인권리검수]',()=>{const tid=FR824(),other=otherT(),p=foreignOf(tid).find(x=>x.foreign==='용병'&&!x.isP),a={from:tid,y:G.year,fr:{rsy:12,rsyT:other}};foResAdd(p,tid);for(const h of G.fRes)delete h.rsy;p.hist=Array.from({length:4},(_,i)=>({...ZB,y:G.year-3+i,t:tid,lvl:'1군',g:130,pa:500}));const j=JSON.stringify(G),r=__rngState();ok(ovsRenewYears(a,p)===3&&ovsRenewYears(a,p)===3,'다른 구단 사본을 실제 원구단 기록보다 우선');ok(JSON.stringify(G)===j&&__rngState()===r,'연차 조회가 저장·난수 변경');p.hist[2].t=other;ok(ovsRenewYears(a,p)===0,'중간 타 구단 이전의 원구단 시즌 합산');p.hist=p.hist.filter(h=>h.y!==G.year-1);ok(ovsRenewYears(a,p)===0,'빠진 시즌을 추측해 합산');for(const h of G.fRes)h.until=G.year-1;a.fr={rsy:12,rsyT:tid};ok(ovsRenewYears(a,p)===0,'만료 권리에 재계약 가산');});
T('[검수 11-18 #829 주간·복귀] 인계 관찰은 AI 주간 진척과 종료를 따르고 새 단장은 현재 구단의AI지식만 이어받는다 [외국인권리검수]',()=>{const tid=FR824(),other=otherT(),p=newForeign('용병',{market:true}),q=newForeign('용병',{market:true});G.fmarket=(G.fmarket||[]).concat(p.id,q.id);G.fwatch=[{id:p.id,since:G.day-30,k:80}];G.fwatchT={};G.fwAI={[other]:[{id:q.id,since:G.day-25,k:60}]};switchTeam(other);ok(G.fwatch.some(w=>w.id===q.id&&w.k===60)&&!G.fwatch.some(w=>w.id===p.id),'취임 구단의AI지식 미인계·전구단 지식 전이');G.fwAI[tid]=[{id:p.id,since:G.day-5,k:20}];ok(fWatchers(p).filter(t=>t===tid).length===1&&fwatchKT(tid,p.id)===80,'중복 인계 관찰이 구단수·파악도를 변경');const old={fNeed,fTop3};try{let keep=true;fNeed=()=>({kind:'용병',isP:null});fTop3=t=>t===tid&&keep?[G.players[p.id]]:[];const r=__rngState();fwAiWeek();const k=fwatchKT(tid,p.id);ok(k>80&&G.fwatchT[tid].find(w=>w.id===p.id)?.k===k,'AI 주간 지식이 인계 사본에 미반영');keep=false;fwAiWeek();ok(!fWatchers(p).includes(tid)&&fwatchKT(tid,p.id)===0&&G.fwatchT[tid].length===0,'AI 관찰 종료 뒤 옛 인계본이 관심을 되살림');ok(__rngState()===r,'AI 관찰 주간 정리가 주 난수 소비');}finally{fNeed=old.fNeed;fTop3=old.fTop3;}G=JSON.parse(JSON.stringify(G));switchTeam(tid);ok(!G.fwatch.some(w=>w.id===p.id),'복귀가 종료한 옛 관찰을 되살림');});
T('[검수 11-18 #825 이미 복귀] 이미 시장이나 원구단에 복원된 옛 선수의 확인 가능한 연차만 보완하고 반복 정리는 무난수다 [외국인권리검수]',()=>{const tid=FR824(),other=otherT(),p=foreignOf(tid).find(x=>x.foreign==='용병'&&!x.isP),id=p.id;p.rsy=0;p.hist=Array.from({length:4},(_,i)=>({...ZB,y:G.year-4+i,t:tid,lvl:'1군',g:100,pa:400}));G.fRes=[{pid:id,tid,y:G.year-1,until:G.year+4}];G.abroad=[{id,from:tid,foreign:p.foreign,back:true,backY:G.year,y:G.year-1,lines:[]}];G=JSON.parse(JSON.stringify(G));const r=__rngState();ok(ovsRenewFix()===1&&G.players[id].rsy===3,'이미 복귀한 선수 연차 미복원');const j=JSON.stringify(G);ok(ovsRenewFix()===0&&JSON.stringify(G)===j&&__rngState()===r,'복귀 연차 정리가 멱등·무난수가 아님');G.players[id].team=other;G.players[id].rsy=0;ok(ovsRenewFix()===0&&G.players[id].rsy===0,'다른 구단 선수에 원구단 연차 보완');});
T('[검수 11-18 #824~825 실제 로드] 해제된 옛 시장 권리와 이미 복귀한 원구단 연차는 실제 불러오기에서 함께 무난수 멱등 정리된다 [외국인권리검수]',()=>{const tid=FR824(),p=newForeign('용병',{market:true}),q=foreignOf(tid).find(x=>x.foreign==='용병'&&!x.isP),id=q.id;G.fmarket=(G.fmarket||[]).concat(p.id);foResAdd(p,tid);mvLog('외국인 계약 종료',p,tid,null,'재계약 결렬 · 보류권 해제 · 다른 구단과 계약 가능');q.rsy=0;q.hist=Array.from({length:4},(_,i)=>({...ZB,y:G.year-4+i,t:tid,lvl:'1군',g:100,pa:400}));G.fRes.push({pid:id,tid,y:G.year-1,until:G.year+4});G.abroad=(G.abroad||[]).concat({id,from:tid,foreign:q.foreign,back:true,backY:G.year,y:G.year-1,lg:'NPB',isP:q.isP,lines:[]});G=JSON.parse(JSON.stringify(G));const r=__rngState();migrateDraft();ok(!foResFor(G.players[p.id])&&G.players[id].rsy===3,'실제 loader가 권리/연차 정리 누락');ok(__rngState()===r,'실제 loader의 권리/연차 정리가 주 난수 변경');const j=JSON.stringify(G);migrateDraft();ok(JSON.stringify(G)===j&&__rngState()===r,'실제 loader 두번째 실행이 저장·주 난수 변경');});

