function fc810World(){__seed(810900);buildWorld({lite:true});claimTeam(6);G.day=KD(11,20);G.last={y:G.year};G.rolled=G.year;G.evs=[];G.contract=null;G.moves=[];G.fmarket=[];return G.user;}
function fc810Player(tid,kind){const p=newForeign(kind||'용병',{isP:false,pos:'1B',team:tid,age:30});p.team=tid;p.fy=G.year;p.sal=1000;p.yrs=1;p.rsy=0;p.mor=60;for(const k in p.r)p.r[k]=61;delete p.fCtY;delete p.fMulti;delete p.kept;delete p.fRel;delete p.opt;delete p.fInc;return p;}
T('[검수 11-18 교차 #819·827] 이미 열린 재계약 묶음에서 해외잔류 후 확정해도 유효옵션과 연차는 한 번만 유지된다 [외국인통합교차검수]',()=>{const U=fc810World();for(const q of foreignOf(U))q.team=null;const p=fc810Player(U),sy=G.year+1;p.ctT=U;p.opt={a:150,from:sy,until:sy,c:'b'};p.newSal=1800;G.contract={y:G.year,tid:U,ended:[],foreignEnd:[p.id],foreignDrop:[],released:[],done:false,fre:{},neg:{}};p.ovsOffer={lg:'NPB',club:NPBT[0],yrs:2,amt:300,y:G.year};__seed(7);const s=EVH.fovs.pick({data:{pid:p.id,ks:2000}},0);ok(p.kept&&p.sal===2000&&!p.ovsOffer,'실제잔류준비 '+s);const opt=JSON.stringify(p.opt),rsy=p.rsy;p.fout={y:G.year,k:'일본',v:6000};const first=confirmContracts(true);ok(G.contract.done&&G.players[p.id]===p&&p.team===U,'열린재계약 확정이 이미맺은잔류를 재출국 '+first);ok(p.fCtY===sy&&p.rsy===rsy&&JSON.stringify(p.opt)===opt,'잔류의계약잠금·옵션·연차를확정이덮음');ok(fCommit(p,sy)===2150,'다음시즌한도에 유효옵션미반영');const raw=JSON.stringify(G),rng=__rngState();confirmContracts(true);ok(JSON.stringify(G)===raw&&__rngState()===rng,'확정반복이 같은계약을중복반영');});
T('[검수 11-18 교차 #823~825] 실제해제→국내시장→다른구단신규계약은 옛권리·연차·조건을넘기지않는다 [외국인통합교차검수]',()=>{const U=fc810World(),V=otherT();G.day=KD(12,15);for(const q of foreignOf(U))q.team=null;for(const q of foreignOf(V))q.team=null;const p=fc810Player(U);p.age=33;p.rsy=3;p.fRel=true;p.ctT=U;p.opt={a:150,from:G.year,until:G.year,c:'b'};p.fCtY=G.year;p.fMulti=G.year;p.kept={y:G.year-1,sal:p.sal};G.fRes=[{pid:p.id,name:p.name,nat:p.nat,tid:U,y:G.year-1,until:G.year+5,rsy:3},{name:p.name,nat:p.nat,tid:U,y:G.year-2,until:G.year+4}];const C={y:G.year,tid:U,foreignEnd:[p.id],foreignDrop:[p.id],fFree:[],fre:{}};G.contract=C;fReFinish(C,U);ok(G.players[p.id]===p&&p.team==null&&G.fmarket.includes(p.id),'권리해제후 실제국내시장진입 실패');C.done=true;p.ask=300;const e=signForeignT(V,p.id,300,100);ok(!e&&p.team===V,'다른구단 실제신규계약이 옛보류권때문에거절 '+e);ok(!foResFor(p)&&p.rsy===0&&!p.kept&&!p.fMulti,'신규구단으로 옛권리·연차·확정잔류이력전이');ok(p.ctT===V&&p.opt&&p.opt.a===100&&p.opt.from===G.year+1&&p.opt.until===G.year+1,'새계약에 옛인센티브조건·소속전이');const rows=(G.moves||[]).filter(x=>x.pid===p.id);ok(rows.filter(x=>x.t==='외국인 계약 종료').length===1&&rows.some(x=>x.t==='외국인'&&x.to===V),'해제와 신규입단 이동흐름누락');});
T('[검수 11-18 교차 불러오기 #810·819·824·826] 서로다른 옛계약상태를 실제로더가 함께복구하고 두번째에는완전히멱등이다 [외국인통합교차검수]',()=>{const U=fc810World(),V=otherT();G.last=null;G.rolled=null;G.day=KD(7,20);migrateDraft();const p=domestic(U).find(q=>!q.ys&&!q.isP);Object.assign(p,{team:null,e1:false,freeSince:G.year-3,freeDay:G.day-800,tryK:'indie',retFrom:U,retAsk:{sal:800,yrs:1,lg:'MLB',n:1,post:1,exp:G.day+14}});ovsBackAsk(p);const q=newForeign('용병',{market:true});G.fmarket.push(q.id);foResAdd(q,U);G.fRes.push({name:q.name,nat:q.nat,tid:U,y:G.year-1,until:G.year+4});mvLog('외국인 계약 종료',q,U,null,'재계약 결렬 · 보류권 해제 · 다른 구단과 계약 가능');const r=fc810Player(U);r.ctT=U;r.fjD=G.day;r.opt={a:108,from:G.year,until:G.year,c:'b'};r.hist=[Object.assign({y:G.year,t:U,lvl:'1군'},ZB,{g:50,pa:184,ab:160,h:48})];const s=fc810Player(V);s.fy=G.year-2;s.sal=2000;s.rsy=2;s.kept={y:G.year-1,sal:2000,base:1000};const ids=[p.id,q.id,r.id,s.id];G=JSON.parse(JSON.stringify(G));const rng=__rngState();migrateDraft();const [a,b,c,d]=ids.map(id=>G.players[id]);ok(a&&a.retAsk&&a.team==null&&a.freeSince==null&&!isFree(a),'통합로더가 우선협상과무적중복유지');ok(!foResFor(b),'통합로더가 명시해제옛권리미정리');ok(c.opt.fr>0&&c.opt.fr<1&&optEarned(c),'통합로더가 실제입단근거의옵션비율미복구');ok(d.fCtY===G.year&&d.rsy===3,'통합로더가 옛확정잔류계약미복구');ok(__rngState()===rng,'통합복구가 주난수사용');const raw=JSON.stringify(G);migrateDraft();ok(JSON.stringify(G)===raw&&__rngState()===rng,'순서섞인도메인복구가 두번째저장·난수변경');});

