const fb830=()=>{const F=fo1117(),A=G.user,B=otherT(),C=G.teams.find(t=>t.id!==A&&t.id!==B).id,d=G.cal.open+40;G.day=d-1;G.cal.sched={[d]:[[A,B]]};G.cal.rain={};G.cal.mk={};G.makeup=[];RAIN_GI=null;G.spend.fan=0;F.cheer=0;F.yt=0;F.crew={};delete F.cs;F.sup=null;F.boost=null;F.last={};F.plans={};delete F.bk;return {A,B,C,d,F};};
T('[팬예약검수] [검수 11-18 #830] 시구 예약 뒤 실제 이직·복귀·취소·결산을 거쳐도 환불한 행사비는 청구하지 않는다',()=>{const {A,B,d}=fb830();const m=fanEvent('pitch');ok(G.fanOps.bk?.length&&(G.spend.fan||0)===30,'예약 준비 '+m);switchTeam(B);switchTeam(A);G.cal.sched[d]=[];G.day=d;fanBkDaily();ok(!G.fanOps.bk&&(G.spend.fan||0)===-30,'돌아온 뒤 취소 환불 준비');r464_ps();withRng(830,()=>settlement());const fin=G.last.fins[A],cost=fin.exp.filter(x=>x[0]==='팬 마케팅·구단 이벤트').reduce((n,x)=>n+x[1],0);ok(cost===0,'취소한 시구 결산 비용 '+cost);});
T('[팬예약검수] [검수 11-18 #831 차전] 같은 상대 더블헤더의 첫 경기 시구는 2차전 호출로 소진되지 않는다',()=>{const {A,B,d,F}=fb830();G.cal.sched[d]=[[A,B],[A,B]];fanEvent('pitch');G.day=d;RAIN_GI={day:d,h:A,a:B,i:2,dh:true};try{fanPlansGame(A,d,B);ok(F.bk?.length===1&&F.last.pitch==null,'2차전에서 1차전 시구 실행');RAIN_GI.i=1;fanPlansGame(A,d,B);ok(!F.bk&&F.last.pitch===d,'예약한 1차전 시구 실행 누락');}finally{RAIN_GI=null;}});
T('[팬예약검수] [검수 11-18 #831 순연] 더블헤더 취소 기록 순서와 무관하게 시구가 예약한 차전의 새 날짜를 따른다',()=>{const {A,B,d,F}=fb830();G.cal.sched[d]=[[A,B],[A,B]];fanEvent('pitch');G.day=d;G.cal.sched[d]=[];G.cal.sched[d+3]=[[A,B]];G.cal.sched[d+8]=[[A,B]];G.cal.rain[d]=[{h:A,a:B,ordinal:2,sourcePairN:2,to:d+8,targetOrdinal:1},{h:A,a:B,ordinal:1,sourcePairN:2,to:d+3,targetOrdinal:1}];fanBkDaily();ok(F.bk?.[0]?.d===d+3,'예약한 1차전 대신 먼저 나온 2차전 날짜 '+JSON.stringify(F.bk));});
T('[팬예약검수] [검수 11-18 #832] 취소한 시구는 같은 상대의 별개 재처리 경기에 붙지 않고 즉시 환불한다',()=>{const {A,B,d,F}=fb830();fanEvent('pitch');G.day=d;G.cal.sched[d]=[];G.makeup=[{y:G.year,h:A,a:B,d:d-3,from:d-4}];fanBkDaily();ok(!F.bk&&(G.spend.fan||0)===0&&F.last.pitch==null,'별개 대기 경기 때문에 환불을 보류 '+JSON.stringify(F.bk));G.day=d+1;fanPlansGame(A,d+1,B);ok(F.last.pitch==null,'별개 경기에서 취소한 시구가 실행');});
T('[팬예약검수] [검수 11-18 #833] 다른 상대 홈경기와 겹친 프로모션 예산은 예약에 저장된 상대를 사용한다',()=>{const {A,B,C,d}=fb830(),to=d+5;G.cal.sched[to]=[[A,C],[A,B]];team(B).market=5;team(C).market=.1;const P=promoOf(A);P.bk[d]={k:'women',a:B,gk:gmGameKey(d,A,B,1)};ok(promoRainout(A,d,to,{h:A,a:B,ordinal:1,sourcePairN:1,targetOrdinal:1,to})===1&&P.bk[to].a===B,'다른 상대 뒤 순연 준비');const e=promoEst(A,to,'women',B),wrong=promoEst(A,to,'women',C);ok(Math.round(e.inc)!==Math.round(wrong.inc),'상대별 예산 차이 준비 '+e.inc+'/'+wrong.inc);const inc=[],exp=[];promoBudget(inc,exp);const actual=(inc.find(x=>x[0]==='프로모션 부대 수입')||[0,0])[1];ok(actual===Math.round(e.inc),'예약 상대 기대수입 '+Math.round(e.inc)+' 대신 '+actual);});
T('[팬예약검수] [검수 11-18 #834] 같은 날 두 번째 상대의 프로모션도 테마와 곱하지 않고 큰 효과 하나만 쓴다',()=>{const {A,B,C,d,F}=fb830();G.cal.sched[d]=[[A,C],[A,B]];G.day=d;F.boost={from:d,until:d+7};const P=promoOf(A);P.bk[d]={k:'cap',a:B,gk:gmGameKey(d,A,B,1)};RAIN_GI={day:d,h:A,a:B,i:1,dh:true};try{const promo=promoAttM(A,B,d),actual=fanAttM(d,A)*promo;ok(promo>1.08,'프로모션 효과 준비 '+promo);ok(Math.abs(actual-Math.max(1.08,promo))<1e-10,'테마 중복 배율 '+actual+' / 프로모션 '+promo);}finally{RAIN_GI=null;}});
T('[팬예약검수] [검수 11-18 #835] 자동 테마의 예정 두 행사는 예산에 잡히며 실제 청구 합계와 일치한다',()=>{const {A,B,d,F}=fb830();for(const x of [d,d+3,d+40,d+43])G.cal.sched[x]=[[A,B]];const row=b=>(b.exp.find(x=>x[0]==='팬 마케팅·구단 이벤트')||[0,0])[1],before=row(budget());fanPlanSet('theme',true);const state=JSON.stringify(G),rng=__rngState(),after=row(budget());ok(after-before===100,'자동 테마 예정비용 100 대신 '+(after-before));ok(JSON.stringify(G)===state&&__rngState()===rng,'자동 행사 전망이 저장·난수를 변경');const c=G.spend.fan||0;for(const x of [d,d+3,d+40,d+43]){G.day=x;fanPlansGame(A,x,B);}ok((G.spend.fan||0)-c===100,'자동 테마 실제 청구 준비');});
T('[팬예약검수] [검수 11-18 #836] 새 회계연도 전 구단의 실제 갱신 여론은 프로모션에서도 같은 구단 기록으로 조회한다',()=>{const {A,B,F}=fb830();F.cheer=2;G.pr.fan=24;switchTeam(B);G.day=G.cal.end+31;G.last={y:G.year};fanAwayMonthly();const p=G.clubT[A].pr;ok(p.fan>24&&G.clubT[A].fy!==sponSeason(),'새 회계연도 전 구단 여론 갱신 준비');ok(prOf(A)===p,'프로모션 여론 조회가 갱신된 전 구단 기록 대신 기본값 사용');});
T('[팬예약검수] [검수 11-18 #830 재이직] 복귀 뒤 환불하고 다시 떠나도 이직 장부의 비용과 이미 반영한 현금이 함께 상쇄된다',()=>{const {A,B,d}=fb830();fanEvent('pitch');switchTeam(B);switchTeam(A);G.cal.sched[d]=[];G.day=d;fanBkDaily();switchTeam(B);const H=G.hoL[fyNow()+':'+A],cost=H.exp['팬 마케팅·구단 이벤트']||0;ok(cost===0,'환불 뒤 재이직한 행사 장부 비용 '+cost);ok(Math.abs(H.net-(sum(Object.values(H.inc))-sum(Object.values(H.exp))))<1e-9,'이직 장부 net이 명세 합계와 다름');});
T('[팬예약검수] [검수 11-18 #830 회계경계] 전 회계연도에 낸 예약의 환불은 새 장부에 음수 비용으로 남고 반복 취소는 중복 환급하지 않는다',()=>{const {A,B,d}=fb830();fanEvent('pitch');switchTeam(B);G.last={y:G.year};G.day=G.cal.end+31;const F=G.fanYrT[A];F.bk[0].d=G.day;G.cal.sched[G.day]=[];const cash=team(A).cash;fanAway(A,fanBkDaily,true);const H=G.hoL[fyNow()+':'+A],v=H.exp['팬 마케팅·구단 이벤트'];ok(v===-30&&H.net===30&&team(A).cash===cash+30,'새 회계연도 환불 장부를 0으로 잘라 명세·현금 불일치 '+JSON.stringify(H));const s=JSON.stringify(H);fanAway(A,fanBkDaily,true);ok(JSON.stringify(H)===s&&team(A).cash===cash+30,'반복 취소 환급 중복');});
T('[팬예약검수] [검수 11-18 #831 옛저장] 순번 없는 옛 더블헤더 예약은 임의 차전에 붙이지 않고 한 번만 환불한다',()=>{const {A,B,d,F}=fb830();G.cal.sched[d]=[[A,B],[A,B]];fanEvent('pitch');delete F.bk[0].gk;const rng=__rngState();fanOpsFix();ok(!F.bk&&(G.spend.fan||0)===0,'모호한 옛 더블헤더 시구를 유지');const s=JSON.stringify(G);fanOpsFix();ok(JSON.stringify(G)===s&&__rngState()===rng,'옛 예약 정리 멱등·난수');});
T('[팬예약검수] [검수 11-18 #831 실제불러오기] 유일한 옛 예약은 실제 불러오기에서 편성 키를 복원하고 반복해도 저장·난수가 같다',()=>{const {A,B,d}=fb830();fanEvent('pitch');delete G.fanOps.bk[0].gk;G=JSON.parse(JSON.stringify(G));const rng=__rngState();migrateDraft();const b=G.fanOps.bk[0];ok(b.gk?.d===d&&b.gk.h===A&&b.gk.a===B&&b.gk.i===1,'실제 불러오기 편성 키 미복원');const s=JSON.stringify(G);migrateDraft();ok(JSON.stringify(G)===s&&__rngState()===rng,'실제 옛 예약 복원 멱등·난수');});
T('[팬예약검수] [검수 11-18 #836 재부임] 회계연도가 달라져 복귀해도 팬 여론은 이어받고 지난 시즌 목표는 되살리지 않는다',()=>{const {A,B,F}=fb830();F.cheer=2;G.pr.fan=24;const goal=G.goals;switchTeam(B);G.day=G.cal.end+31;G.last={y:G.year};fanAwayMonthly();const p=G.clubT[A].pr,value=p.fan;switchTeam(A);ok(G.pr.fan===value&&G.pr===p,'다음 회계연도 복귀 팬 여론 초기화 '+G.pr.fan+'/'+value);ok(G.goals!==goal,'지난 회계연도 목표를 새해 목표로 복원');});
T('[팬예약검수] [검수 11-18 #835 예약중복] 이미 지급한 시구 예약은 자동 운영 비용 전망에 두 번 청구하지 않는다',()=>{const {A,B,d}=fb830();for(const x of [d,d+3,d+40,d+43])G.cal.sched[x]=[[A,B]];fanEvent('pitch');fanPlanSet('pitch',true);const s=JSON.stringify(G),rng=__rngState(),cost=fanPlanCost();ok(cost===30,'이미 낸 예약과 이후 자동 시구 전망 '+cost);ok(JSON.stringify(G)===s&&__rngState()===rng,'예약/자동 전망이 상태 변경');for(const x of [d,d+3,d+40,d+43]){G.day=x;fanPlansGame(A,x,B);}ok((G.spend.fan||0)===60,'예약1회+자동1회 실제 비용 '+G.spend.fan);});
const fb833Change=multi=>{const {A,B,d}=fb830(),to=multi?d+5:d;promoBook(A,d,'women');if(multi){G.cal.sched[to]=[[A,B],[A,B]];ok(promoRainout(A,d,to,{h:A,a:B,ordinal:1,sourcePairN:1,targetOrdinal:2,to})===1,'2차전 순연 준비');}const P=promoOf(A),key=JSON.stringify(P.bk[to].gk);promoBook(A,to,'local');ok(P.bk[to].a===B&&JSON.stringify(P.bk[to].gk)===key&&P.bk[to].k==='local','행사 종류 변경이 예약 경기를 변경');const e=promoEst(A,to,'local',B,P.bk[to].gk),inc=[],exp=[];promoBudget(inc,exp);ok((exp.find(x=>x[0]==='프로모션 데이 비용')||[0,0])[1]===Math.round(e.cost),'변경한 예약의 예산이 실제 경기 전망과 다름');RAIN_GI={day:to,h:A,a:B,i:multi?2:1,dh:multi};try{ok(promoAttM(A,B,to)>1,'예약한 차전의 행사 효과 누락');if(multi){RAIN_GI.i=1;ok(promoAttM(A,B,to)===1,'2차전 예약 효과가 1차전에도 적용');}}finally{RAIN_GI=null;}};
T('[팬예약검수] [검수 11-18 #833 변경] 일반 단일 홈경기의 행사 종류를 바꿔도 예약·예산·실제 효과가 같은 경기에 남는다',()=>fb833Change(false));
T('[팬예약검수] [검수 11-18 #833 2차전변경] 순연된 더블헤더 2차전의 행사 종류를 바꿔도 경기 순번을 보존한다',()=>fb833Change(true));
T('[팬예약검수] [검수 11-18 정상난수] 정상 단일 홈경기 시구는 수정 전과 같은 주 난수·여론·비용으로 실행한다',()=>{globalThis.__seed(830901);const {A,B,d,F}=fb830();fanEvent('pitch');G.day=d;fanPlansGame(A,d,B);ok(__rngState()===-2042200833&&Math.abs(G.pr.fan-52.96)<1e-10&&F.last.pitch===857&&G.spend.fan===30&&!F.bk,'정상 시구의 수정 전 난수/효과 기준값 변경 '+JSON.stringify({rng:__rngState(),fan:G.pr.fan,last:F.last.pitch,spent:G.spend.fan,held:!F.bk}));});

T('[팬예약검수] [검수 11-18 #830 옛환불장부] 실제 불러오기는 잘린 미결 팬 환불만 복원하고 현금·종료 원장·난수를 보존한다',()=>{const {A,B,C}=fb830(),fy=fyNow(),k=fy+':'+A;team(A).cash+=30;const cash=team(A).cash;G.hoL={[k]:{inc:{},exp:{'팬 마케팅·구단 이벤트':0},net:30},[(fy-1)+':'+A]:{inc:{},exp:{'팬 마케팅·구단 이벤트':0},net:30},[fy+':'+B]:{inc:{},exp:{'별도 비용':0},net:30},[fy+':'+C]:{inc:{},exp:{'팬 마케팅·구단 이벤트':0},net:0}};const controls=()=>JSON.stringify([(G.hoL||{})[(fy-1)+':'+A],(G.hoL||{})[fy+':'+B],(G.hoL||{})[fy+':'+C]]),before=controls(),rng=__rngState();migrateDraft();const H=G.hoL[k];ok(H.exp['팬 마케팅·구단 이벤트']===-30&&H.net===30&&team(A).cash===cash,'잘린 옛 환불 장부 복원/현금 '+JSON.stringify(H));ok(controls()===before,'종료FY·팬라벨없음·정상장부를 변경');const state=JSON.stringify(G);migrateDraft();ok(JSON.stringify(G)===state&&__rngState()===rng,'옛 환불 장부 불러오기 멱등·난수');r464_ps();const settledCash=team(A).cash;withRng(83018,()=>settlement());const f=G.last.fins[A],credit=f.exp.filter(x=>x[0]==='팬 마케팅·구단 이벤트').reduce((n,x)=>n+x[1],0);ok(credit===-30,'옛 환불이 실제 결산 명세에서 소실 '+credit);ok(Math.abs(f.cash-(settledCash-30+f.net-(f.div||0)-(f.sweep||0)))<1e-6,'옛 선반영 환불을 실제 결산에서 중복/누락');});

let fc837World=null;
function fc837Fresh(){if(!fc837World){__seed(837001);fresh();fc837World=JSON.stringify(G);}else{G=JSON.parse(fc837World);worldReset();}G.day=KD(6,30);G.fanOps={cheer:0,yt:0,sub:0,last:{},yr:{},boost:null,sup:null,log:[],crew:{}};delete team(G.user).fanOps;G.fanYrT={};G.spend.fan=0;G.spend.fanIn=0;G.spend.etc=0;G.spend.trC=0;G.pr={fan:55,press:50,hist:[]};G.news=[];G.wire=[];}
function fc837Member(id,extra){return Object.assign({id,name:'검수단원'+id,age:22,yrs:1,vis:10,pop:10,svc:10,dance:10,sta:10,dil:10,fat:0,on:true,inj:0,sl:0,app:0,fol:0},extra||{});}
function fc837Squad(n=8,ag='han'){const S={ag,L:Array.from({length:n},(_,i)=>fc837Member(i+1)),nid:n,auto:true,ev:null,last:null};G.fanOps.cs=S;return S;}
function fc837Poor(){const t=team(G.user);t.indie=true;t.cash=0;ok(spendable(G.user)===0&&fanCashWhy(5).includes('부족'),'준비: 일반 행사 자금 부족 아님');}
function fc837Hash(v){const s=JSON.stringify(v);let h=2166136261;for(let i=0;i<s.length;i++)h=Math.imul(h^s.charCodeAt(i),16777619);return h>>>0;}
T('[검수 11-18 #837 대행사] 행사 자금이 없는 독립구단은 응원단 신규 계약을 맺지 못한다 [응원단검수]',()=>{fc837Fresh();fc837Poor();const before=JSON.stringify(G),seed=__rngState(),r=cheerAg('sky');ok(!G.fanOps.cs&&r.includes('부족'),'무자금 대행사 계약 성사 '+r);ok(JSON.stringify(G)===before&&__rngState()===seed,'자금 거절이 저장/주난수 변경');});
T('[검수 11-18 #837 확대] 행사 자금이 없는 독립구단은 응원단을 대폭 확대하지 못한다 [응원단검수]',()=>{fc837Fresh();fc837Squad();fc837Poor();const before=JSON.stringify(G),seed=__rngState(),r=fanSet('cheer',2);ok(G.fanOps.cheer===0&&G.fanOps.cs.L.length===8&&r.includes('부족'),'무자금 응원단 대폭 확대 '+r);ok(JSON.stringify(G)===before&&__rngState()===seed,'확대 거절이 저장/주난수 변경');});
T('[검수 11-18 #837 사인회] 행사 자금이 없는 독립구단은 치어리더 유료 사인회를 열지 못한다 [응원단검수]',()=>{fc837Fresh();const S=fc837Squad();fc837Poor();const before=JSON.stringify(G),seed=__rngState(),r=cheerMeet();ok(S.ev==null&&!G.spend.fan&&r.includes('부족'),'무자금 사인회 지출/진행 '+r);ok(JSON.stringify(G)===before&&__rngState()===seed,'사인회 거절이 저장/주난수 변경');});
