T('[검수 11-18 #840] 같은 인기 단원 이적은 전 구단에도 소식과 같은 팬 여론 효과를 남긴다 [응원단검수]',()=>{fc837Fresh();const A=G.user,B=otherT();G.day=KD(1,1);const proto=fc837Member(1,{pop:20,age:22,dil:10});let seed=null,home=null,hr=null;for(let s=1;s<=200&&!seed;s++){G.fanOps.cs={ag:'han',L:[JSON.parse(JSON.stringify(proto))],nid:1,auto:true};G.news=[];G.pr={fan:55,press:50,hist:[]};__seed(s);cheerYear(G.fanOps.cs);if(!G.fanOps.cs.L.some(m=>m.id===1)&&G.news.some(n=>n.t.includes(proto.name)&&n.t.includes('다른 구단'))){seed=s;home=G.pr.fan;hr=__rngState();}}ok(seed&&home<55,'준비: 실제 인기 단원 이적/기사 없음');fc837Fresh();G.day=KD(1,1);const F=G.fanOps;F.cs={ag:'han',L:[JSON.parse(JSON.stringify(proto))],nid:1,auto:true};switchTeam(B);G.day=KD(1,1);G.clubT[A].pr={fan:55,press:50,hist:[]};G.pr={fan:55,press:50,hist:[]};G.wire=[];__seed(seed);fanAway(A,()=>cheerYear(F.cs));ok(!F.cs.L.some(m=>m.id===1),'같은 단원이 전 구단에서는 이적하지 않음');ok(G.wire.some(w=>w.t.includes(proto.name)&&w.t.includes('다른 구단')),'전 구단 인기 단원 이적 소식 누락');ok(Math.abs(G.clubT[A].pr.fan-home)<1e-9,'같은 기사 전 구단 여론 효과 다름 '+G.clubT[A].pr.fan+' / '+home);ok(G.pr.fan===55&&__rngState()===hr,'전 구단 기사가 현 구단 여론/주난수 변경');});
