T('[검수 11-18 #837 기존실제요금] 월청구 직후에도 현재 대행사의 알려진 높은 요금을 새 배정 상한과 함께 보존한다 [응원단검수] [응원단기존요금]',()=>{fc837Fresh();G.day=G.cal.open-5;const S=fc837Squad(8,'sky'),t=team(G.user);S.L.forEach(m=>{m.pop=20;m.dance=20;});S.payPeak=0;t.indie=true;t.cash=31;ok(cheerPay()===32,'준비: 기존 월요금32');const before=JSON.stringify(G),seed=__rngState();const r=cheerAg('sae');ok(S.ag==='sky'&&r.includes('부족'),'기존32를 놓치고 신규상한16만으로 계약');ok(JSON.stringify(G)===before&&__rngState()===seed,'기존요금 경계 거절 저장/주난수 변경');t.cash=32;cheerAg('sae');ok(S.ag==='sae'&&S.payPeak===32&&t.cash===32&&!G.spend.fan,'기존32와신규16중복차감/기존요금소멸');});

function fe842(){globalThis.__seed(830842);buildWorld({lite:true});claimTeam(6);G.tut={done:true,step:99};G.ps=null;G.last=null;myCInit();return {U:G.user,Y:G.year};}
function fe842Order(tid){return [tid,...G.teams.map(t=>t.id).filter(x=>x!==tid)].map((x,i)=>({tid:x,w:80-i,l:64+i,t:0}));}
T('[검수 11-18 #842] 종료 시즌 결산과 새해 뒤 지역 채용 가산비는 사용자·AI 모두 남지 않는다 [팬시설경력검수]',()=>{const {U,Y}=fe842(),A=G.teams.find(t=>t.id!==U).id;for(const tid of [U,A]){const t=team(tid),F=facSt(tid);F.it.indoor=3;t.cityOb=[{k:'indoor',city:t.city,y0:Y-3,y1:Y,prog:30,help:3000,miss:0}];t.cash=10000;}G.last={y:Y,order:fe842Order(U)};for(const tid of [U,A])facDealsYear(team(tid));G.day=dnum(Y+1,1,1);ok(newYear()!==false&&G.year===Y+1,'실제 새해 준비 실패');const r=__rngState();for(const tid of [U,A]){const t=team(tid),a=facCityUp(t),raw=JSON.stringify(t);ok(a===0,'만료 다음해 지역채용 유지비 남음 '+tid+':'+a);ok(facCityUp(t)===0&&JSON.stringify(t)===raw,'반복 비용 조회가 계약 변경');}ok(__rngState()===r,'유지비 조회가 주 난수 변경');});
T('[검수 11-18 #843] 명명권3년 모두 조건을 지키면4000 전액과 정상종료 보너스를 받는다 [팬시설경력검수]',()=>{const {U,Y}=fe842(),t=team(U);G.fac=facSt(U);G.fac.it.indoor=2;t.cash=20000;const c=t.cash,pop=t.pop;ok(facFundGo(U,'indoor','spon',8000)==='','실제8000 시설착공 실패');const D=t.facSpon;ok(D.help===4000&&D.paid===1333,'40억 3년 분할 준비 실패');const initial=D.paid;for(let i=0;i<3;i++){G.year=Y+i;G.last={y:G.year,order:fe842Order(U)};G.sea.att={[U]:{n:72,sum:1440000,cap:1440000,so:72}};facDealsYear(t);}const paid=initial+(t.cash-(c-(8000-initial)));ok(paid===4000,'조건3년 모두이행해도 명명권 총액누락 '+paid);ok(!t.facSpon&&Math.abs(t.pop-(pop+.01))<1e-9,'반올림잔여액으로 정상종료·인기보너스 누락');ok((G.news||[]).some(n=>n.t.includes('명명권 계약 만료')&&n.b.includes('약속대로')),'정상이행 만료 안내 누락');});
T('[검수 11-18 #844] 기한지난 구장 합의는 직접착공과 AI일일처리 모두 비용없이 만료한다 [팬시설경력검수]',()=>{for(const ai of [false,true]){const {U,Y}=fe842(),tid=ai?G.teams.find(t=>t.id!==U).id:U,t=team(tid),S=stadOf(tid);G.day=dnum(Y,11,15);S.proj=null;S.xq={k:'of',stage:'ok',st:G.day-100,exp:G.day-10,...(ai?{esc:500}:{})};t.cash=100000;t.trust=90;const c=t.cash,s=G.spend.stad||0,r=__rngState();if(ai)stadXpDaily();else stadXpStart(tid);ok(!S.xq||S.xq.stage!=='build','만료된 '+(ai?'AI':'사용자')+' 합의가 착공');ok(t.cash===c+(ai?500:0)&&(G.spend.stad||0)===s,'만료합의 비용청구/예치금환급 오류');ok(__rngState()===r,'만료처리가 주 난수 사용');}});
function fe845Join(){const {U,Y}=fe842(),V=G.teams.find(t=>t.id!==U).id;G.day=dnum(Y,9,30);G.sea.y=Y;G.sea.rec[V]={w:70,l:60,t:10};G.ps={done:true,finDay:G.day+2,order:fe842Order(V),champ:V,runner:U};personalState().cash=10000;const j=jobOffer(V,false,{sal:600,yrs:3}),msg=jobAnswer(j.id,true);ok(G.user===V&&G.myC.y0===Y+1&&G.myC.sal===600,'한국시리즈 후 실제 취임 준비 실패 '+msg);return {U,V,Y};}
T('[검수 11-18 #845] 다음시즌 시작 계약을 올해 사임해도 근무한척 경력행을 만들지 않는다 [팬시설경력검수]',()=>{const {Y}=fe845Join(),before=JSON.stringify(G.myC.stints),r=__rngState();myCEnd('사임',Y);ok(JSON.stringify(G.myC.stints)===before,'아직 시작하지 않은6억계약이 올해 재임행 생성 '+JSON.stringify(G.myC.stints));ok(G.myC.tid==null&&__rngState()===r,'사임종료/난수 오류');});
