T('[검수 11-18 #843 AI·멱등] AI명명권의 마지막잔액도 전액받고 같은연도처리를반복해도 금액·인기·소식은같다 [팬시설경력검수]',()=>{const {U,Y}=fe842(),t=G.teams.find(t=>t.id!==U),F=facSt(t.id);F.it.indoor=2;t.cash=20000;const c=t.cash,pop=t.pop;ok(facFundGo(t.id,'indoor','spon',8000)==='','AI실제후원착공준비');const initial=t.facSpon.paid;for(let i=0;i<3;i++){G.year=Y+i;G.last={y:G.year,order:fe842Order(t.id)};G.sea.att={[t.id]:{n:72,sum:1440000,cap:1440000,so:72}};facDealsYear(t);const raw=JSON.stringify(G),r=__rngState();facDealsYear(t);ok(JSON.stringify(G)===raw&&__rngState()===r,'같은해AI후원 중복지급/기록');}ok(initial+t.cash-(c-(8000-initial))===4000&&!t.facSpon&&Math.abs(t.pop-(pop+.01))<1e-9,'AI정상3년전액/인기보너스불일치');});
T('[검수 11-18 #842~843 옛저장] 처리된결산근거만 복원해 지급중복과 만료부담을 실제로더에서 무난수멱등정리한다 [팬시설경력검수]',()=>{const {U,Y}=fe842();migrateDraft();const t=team(U);G.day=KD(11,20);G.last={y:Y,order:fe842Order(U)};G.ceco={yr:Y};t.cash=10000;t.facSpon={k:'indoor',n:'옛분할',y0:Y,y1:Y+2,help:4000,paid:1333,miss:0};t.cityOb=[{k:'indoor',city:t.city,y0:Y-3,y1:Y,prog:30,help:3000,miss:0},{k:'dorm',city:t.city,y0:Y-2,y1:Y+1,prog:30,help:3000,miss:0}];G=JSON.parse(JSON.stringify(G));const cash=team(U).cash,r=__rngState();migrateDraft();ok(team(U).facSpon.lastY===Y&&team(U).cityOb.length===1&&team(U).cityOb[0].lastY===Y,'실제로드가확정처리연도/만료계약미복구');ok(team(U).cash===cash&&__rngState()===r,'옛계약복원이과거지급추정/난수사용');const raw=JSON.stringify(G);migrateDraft();facDealsYear(team(U));ok(JSON.stringify(G)===raw&&__rngState()===r,'로드반복또는이미처리연도재처리가금액/상태변경');delete G.ceco;delete team(U).facSpon.lastY;ok(facDealsMigrate()===0&&team(U).facSpon.lastY==null,'정산근거없는지난지급을추정');});
T('[검수 11-18 #844 경계] 착공기한당일은 유효하고 지난사용자합의환급·만료알림은한번뿐이다 [팬시설경력검수]',()=>{const {U,Y}=fe842(),t=team(U),S=stadOf(U);G.day=dnum(Y,11,15);t.indie=true;t.cash=100000;S.proj=null;S.xq={k:'of',stage:'ok',st:G.day-100,exp:G.day,esc:500};ok(stadXpStart(U)===''&&S.xq.stage==='build','기한당일까지무효화');S.xq={k:'of',stage:'ok',st:G.day-100,exp:G.day-1,esc:500};const cash=t.cash,n=(G.mail||[]).length,r=__rngState();stadXpStart(U);ok(!S.xq&&t.cash===cash+500,'만료합의예치금반환누락');const raw=JSON.stringify(G);stadXpStart(U);stadXpDaily();ok(JSON.stringify(G)===raw&&__rngState()===r,'만료합의중복환급·알림');ok(G.mail.length===n+1&&G.mail[0].subj.includes('합의 만료'),'만료메일누락/중복');});
T('[검수 11-18 #845 재계약] 미개시재계약을떠나면 실제근무한기존행·옛연봉·결산만종료하고 반복종료는무작업이다 [팬시설경력검수]',()=>{const {U,Y}=fe842();G.day=KD(11,20);G.last={y:Y};G.gmJoin=null;G.myC={tid:U,sal:600,y0:Y+1,y1:Y+3,earn:1234,seas:[{y:Y,tid:U,w:80,l:64,t:0}],stints:[{tid:U,y0:Y-2,y1:Y,sal:300,how:'재계약',fin:{y:Y,f:{net:10}}}]};const r=__rngState();myCEnd('사임',Y);ok(G.myC.stints.length===1&&G.myC.stints[0].sal===300&&G.myC.stints[0].y0===Y-2&&G.myC.stints[0].y1===Y&&G.myC.stints[0].how==='사임'&&G.myC.stints[0].fin.f.net===10,'기존재임행/실제연봉/결산손실');const raw=JSON.stringify(G);myCEnd('사임',Y);ok(JSON.stringify(G)===raw&&__rngState()===r,'종료계약반복이 새행/난수생성');});
T('[검수 11-18 #846 이전실적] 시즌종료후취임해도 앞구단에서실제치른그해부분승패는임시누계에보존한다 [팬시설경력검수]',()=>{const {U,Y}=fe842(),V=G.teams.find(t=>t.id!==U).id;G.day=G.cal.end+1;G.myC={tid:U,sal:600,y0:Y+1,y1:Y+3,earn:0,stints:[],seas:[{y:Y,tid:V,w:3,l:2,t:1,part:1,how:'이직'}]};G.gmJoin={y:Y,tid:U,w:70,l:60,t:10,psDone:true};G.sea.rec[U]={w:80,l:68,t:12};const raw=JSON.stringify(G),r=__rngState(),s=myCStats();ok(s.now&&s.now.w===3&&s.now.l===2&&s.now.t===1,'새구단전임실적을섞거나앞구단실제성적삭제 '+JSON.stringify(s.now));ok(JSON.stringify(G)===raw&&__rngState()===r,'통산조회저장/난수변경');});

/* 교차 경계: 서로 다른 팬 운영 수정이 실제 인계·로드·재처리에서 같은 장부와 경기 키를 공유한다. */
function FX830(){__seed(830999);fresh();const F=fanOps(),A=G.user,B=otherT(),C=G.teams.find(t=>t.id!==A&&t.id!==B).id;G.noRain=true;G.contract=null;G.ps=null;G.last=null;G.spend={};G.fanYrT={};G.hoL={};Object.assign(F,{cheer:0,yt:0,crew:{},last:{},yr:{},plans:{},boost:null,sup:null,log:[]});delete F.cs;delete F.bk;delete team(A).fanOps;team(A).cash=100000;team(A).indie=false;G.pr={fan:55,press:50,hist:[]};G.makeup=[];G.cal.rain={};G.cal.mk={};G.cal.sched={};RAIN_GI=null;return {A,B,C,F};}
function FX830_load(){G=JSON.parse(JSON.stringify(G));migrateDraft();}
function FX830_money(A){return JSON.stringify({cash:team(A).cash,ho:G.hoL,sp:G.spend,F:G.fanOps,other:G.fanYrT,img:G.cimg,imgO:G.cimgO});}
T('[팬교차검수] 환불·첫달 일할·이직·두 번 불러오기 뒤 결산은 하나의 비용 명세와 실제 현금을 유지한다',()=>{const {A,B}=FX830();G.day=KD(6,30);const d=G.day+1;G.cal.sched[d]=[[A,B]];fanEvent('pitch');cheerAg('sky');const S=G.fanOps.cs;S.L.forEach((m,i)=>Object.assign(m,{pop:i<6?20:17,dance:i<6?20:17,fol:0}));S.payPeak=cheerPay();ok(S.payPeak===30&&G.spend.fan===30,'시구30·응원단 월30 준비');switchTeam(B);G.day=d;const cb=team(A).cash,seed=__rngState();fanAwayMonthly();ok(team(A).cash===cb+34&&__rngState()===seed,'첫달 하루 수수료1·상품수입35 현금 불일치');switchTeam(A);G.cal.sched[d]=[];FX830_load();const stable=FX830_money(A),rng=__rngState();FX830_load();ok(FX830_money(A)===stable&&__rngState()===rng,'실제 두 번째 로드가 팬 장부·단원·현금·주 난수 변경');fanBkDaily();const H=G.hoL[fyNow()+':'+A];ok(G.spend.fan===-30&&H.exp['팬 마케팅·구단 이벤트']===31,'예약비와 월일할 인계/현재 환불 분리 실패');ok(H.net===sum(Object.values(H.inc))-sum(Object.values(H.exp)),'인계 명세와 현금net 불일치');const before=team(A).cash,hn=H.net;r464_ps();withRng(830995,()=>settlement());const f=G.last.fins[A],expense=f.exp.filter(x=>x[0]==='팬 마케팅·구단 이벤트').reduce((n,x)=>n+x[1],0);ok(expense===1,'시구 환불과 첫달 응원단을 합친 결산비용1 대신 '+expense);ok(f.net===sum(f.inc.map(x=>x[1]))-sum(f.exp.map(x=>x[1])),'결산 net이 명세 합계와 다름');ok(Math.abs(f.cash-(before-hn+f.net-f.div-f.sweep))<1e-7,'인계 선반영/결산 현금 이중 반영');});
T('[팬교차검수] 처리 실패 시구는 재처리1차전·기존 레트로는 정규2차전을 따라가며 자동테마 예산과 실제 청구가 일치한다',()=>{const {A,B,F}=FX830();const d=G.cal.open+60;G.day=d-1;for(const x of [d,d+1,d+3])G.cal.sched[x]=[[A,B]];fanEvent('pitch');G.day=d;const r=fanEvent('retro',false,d+1);ok(F.bk?.some(x=>x.k==='retro'),'정규 경기 레트로 예약 준비 '+r);fanPlanSet('theme',true);for(const t of G.teams)setEntry(t.id);const sg=simGame;try{simGame=()=>{throw Error('fan-cross-retry');};playDay(d);}finally{simGame=sg;}const pitch=F.bk?.find(x=>x.k==='pitch'),retro=F.bk?.find(x=>x.k==='retro');ok(pitch?.d===d+1&&pitch.gk?.i===1&&retro?.d===d+1&&retro.gk?.i===2,'실제 실패 뒤 시구/레트로 경기 순번 연결 '+JSON.stringify(F.bk));const state=JSON.stringify(G),rng=__rngState(),forecast=typeof fanPlanCost==='function'?fanPlanCost():0;ok(forecast===50,'재처리DH 자동테마 예정비용50 대신 '+forecast);ok(JSON.stringify(G)===state&&__rngState()===rng,'전망이 예약·장부·난수 변경');const billed=G.spend.fan,merch=G.spend.merch||0;G.day=d+1;RAIN_GI={day:d+1,h:A,a:B,i:1,dh:true};try{fanPlansGame(A,d+1,B);ok(F.last.pitch===d+1&&(G.spend.merch||0)===merch&&F.bk?.some(x=>x.k==='retro'),'재처리1차전이 기존 레트로를 소진');RAIN_GI.i=2;fanPlansGame(A,d+1,B);ok((G.spend.merch||0)>merch&&!F.bk,'정규2차전 레트로 실행 누락');}finally{RAIN_GI=null;}G.day=d+3;fanPlansGame(A,G.day,B);ok(G.spend.fan-billed===forecast,'예약비를 다시 청구하거나 자동테마 예산/실제 불일치');});
T('[팬교차검수] 모호한 옛 예약 환불과 소속 불명 사진 보존을 실제 로더로 함께 수리해도 장부와 난수는 멱등이다',()=>{const {A,B}=FX830(),d=G.cal.open+70;G.day=d-1;G.cal.sched[d]=[[A,B],[A,B]];fanEvent('pitch');delete G.fanOps.bk[0].gk;cheerAg('han');const m=G.fanOps.cs.L[0],old='P:cheerm:'+m.id;G.fanYrT[B]={cheer:0,log:[],cs:{ag:'han',L:[{...m,name:'다른 구단 단원'}],nid:m.id}};G.cimg={[old]:'소속 불명 옛 사진'};G.cimgO={[old]:'옛 자르기 원본'};const rng=__rngState();FX830_load();ok(!G.fanOps.bk&&(G.spend.fan||0)===0,'모호한 DH 예약을 추측해 보존하거나 환불 누락');ok(G.cimg[old]==='소속 불명 옛 사진'&&G.cimgO[old]==='옛 자르기 원본'&&!G.cimg['P:cheerm:'+A+':'+m.id]&&!G.cimg['P:cheerm:'+B+':'+m.id],'모호한 단원 사진을 구단으로 추측/삭제');const st=FX830_money(A);FX830_load();ok(FX830_money(A)===st&&__rngState()===rng,'예약 환불/옛 사진 통합 로드 반복으로 장부·현금·주 난수 변경');});

