const club847SeasonFinal=tid=>{const ids=[tid,...G.teams.map(t=>t.id).filter(id=>id!==tid)],order=ids.map((id,i)=>({tid:id,w:90-i*4,l:54+i*4,t:0}));for(const x of order)G.sea.rec[x.tid]={w:x.w,l:x.l,t:0};G.day=G.cal.end+25;G.ps={order,seeds:ids.slice(0,5),champ:ids[0],runner:ids[1],res:{wc:[ids[3],ids[4],1,0],spo:[ids[2],ids[3],3,1],po:[ids[1],ids[2],3,1],ks:[ids[0],ids[1],4,2]},done:true,finDay:G.day};for(const t of G.teams)t.trust=80;asSnap();};
T('[검수 11-18 #847] 개막 전 실제 인수로 올해 적용을 발표한 정책은 올해 우승 결산에도 적용한다 [구단주재정검수]',()=>{fresh();const tid=G.user,t=team(tid),y=G.year;t.indie=false;t.owner='profit';t.cash=10000;G.goals={y,owner:'profit',rank:5,sup:.6,fan:50};delete t.finOwner;const O=ownershipInit(),S=O.clubs[tid];O.since=y-20;O.lastAcquisitionY=y-20;O.lastMajorY=y-20;S.lastEventY=y-20;S.parent.since=y-15;S.parent.health=75;let seed='';for(let i=0;i<100;i++){const k='club847:'+i;if(['win','pr','profit'][Math.floor(seededRand(k+':'+(S.generation+1)+':policy')()*3)]==='win'){seed=k;break;}}ok(seed,'준비: 인수 성적우선 seed');G.year=y-1;G.cal=buildCalendar(G.year);G.day=dnum(G.year,12,15);G.last=null;ok(ownershipStart(tid,'acquisition',{seed}),'준비: 실제 인수 협상 시작');const q=S.pending;ok(q.fy===y,'준비: 새해부터 계약 정책');G.year=y;G.cal=buildCalendar(y);G.day=dnum(y,2,1);ownershipDaily();ok(!S.pending&&t.owner==='win','준비: 실제 2월 인수 완료');const h=S.history.find(h=>h.kind==='acquired');ok(h&&h.text.includes(y+'시즌부터'),'준비: 올해 정책 발표 누락');club847SeasonFinal(tid);withRng(847,()=>{const prev=FO_RNG;let first=true;FO_RNG=()=>{if(first){first=false;return .5;}return prev();};try{settlement();}finally{FO_RNG=prev;}});const f=G.last.fins[tid],paid=(f.inc.find(x=>x[0]==='모기업 우승 보너스')||[0,0])[1];ok(G.last.pool===8700,'준비: 총수입14500/배분8700 '+G.last.pool);ok(paid===4350&&f.owner==='win','발표와 다른 전임 정책 결산 '+paid+'/'+f.owner);});
T('[검수 11-18 #850] 다음 시즌 지자체 보조 계약은 직전 시즌 후속 처리에서 교실 비용을 청구하지 않는다 [구단주재정검수]',()=>{fresh();facInit();G.day=KD(11,15);const y=G.year;G.last={y};G.rolled=y;const t=team(G.user),k=FAC_CITY.k.find(k=>G.fac.it[k]<FAC_MAX&&!G.fac.bld[k]);ok(k,'준비: 시 보조 시설');t.cash=10000;const c=FACI[k].c[G.fac.it[k]+1];facFundGo(t.id,k,'city',c);const o=t.cityOb.at(-1);ok(o.y0===y+1&&o.prog>0,'준비: 실제 다음 시즌 계약 '+JSON.stringify(o));const cash=t.cash,sp=G.spend.fac||0,rel=cityRel(t.id);facDealsYear(t);ok(t.cash===cash&&(G.spend.fac||0)===sp&&cityRel(t.id)===rel&&o.miss===0,'시작 전 교실 비용·관계 판정 '+(cash-t.cash)+'/'+((G.spend.fac||0)-sp));});
T('[검수 11-18 #851] 실제 이직으로 보관된 전 구단 여론은 그 구단 광고 상품 결산에 반영된다 [구단주재정검수]',()=>{const former=f486_setup(),next=otherT(),snapshot=JSON.stringify(G);const run=v=>{G=JSON.parse(snapshot);G.pr={fan:v,press:v,hist:[]};switchTeam(next);ok(G.clubT[former]&&G.clubT[former].pr.fan===v,'준비: 실제 이직 여론 인계');const t=team(former),m=(G.mktT[former]||{}).v??2000,expected=Math.round((2200*ecoIdx(G.year)+m*1.6)*t.market*t.pop*(.85+v/333)*(.95+v/1000));withRng(851,()=>settlement());return {paid:(G.last.fins[former].inc.find(x=>x[0]==='광고·상품')||[0,0])[1],expected};};const a=run(0),b=run(100);ok(a.paid===a.expected&&b.paid===b.expected&&b.paid>a.paid,'전 구단 여론 무시 '+JSON.stringify({a,b}));});
T('[검수 11-18 #852] 사장이 실제 발급한 다년계약 지시의 보상과 메일은 사장에게 귀속한다 [구단주재정검수]',()=>{fresh();G.day=G.cal.open+40;team(G.user).indie=false;for(const z of domestic(G.user)){z.sal=MIN_SAL;delete z.newSal;}const p=domestic(G.user).find(q=>!q.isP&&!q.foreign&&!q.prospect&&!q.ys&&!milServing(q));ok(p,'준비: 다년계약 선수');p.age=27;p.faC=false;p.ext=false;p.yrs=1;p.svc=faSvc(p)-1;delete p.extNext;delete p.joinY;p.hist=[Object.assign({y:G.year,t:G.user,lvl:'1군'},ZB,{pa:400,ab:350,h:130,d:25,tr:3,hr:30,bb:40,g:100})];let order=null;for(let i=0;i<200;i++){G.ownOrder=null;const o=withRng(85200+i,()=>cwOrdIssue('ceo'));if(o&&o.k==='ext'&&o.base.pid===p.id){order=o;break;}}ok(order&&order.person===bossOf(G.user).ceo.id,'준비: 실제 사장 다년 지시');const annual=Math.ceil(Math.max(extDemandAll(p,4)*1.3,extFloor(p))/5)*5;const r=offerExtension(p.id,annual,4,false,{annual,years:4,bonus:0,opt:0,role:null});ok(r.ok&&p.extNext,'준비: 실제 다년 합의 '+JSON.stringify(r));const B=bossOf(G.user);B.ceo.rap=30;B.own.rap=30;const rng=__rngState();cwOrdDaily();const m=G.mail[0];ok(order.st==='ok','사장 지시 성공 처리 누락');ok(B.ceo.rap===33&&B.own.rap===30,'사장 대신 회장 친밀도 보상 '+B.ceo.rap+'/'+B.own.rap);ok(m&&m.from==='사장실'&&m.body.includes(B.ceo.name)&&!m.body.includes(B.own.name),'지시자와 다른 완료 메일 '+JSON.stringify(m));ok(__rngState()===rng,'완료 처리에서 추가 난수');});
T('[검수 11-18 #853] 기한 뒤 관중 지시 판정에도 마감 다음 날 경기는 실적에 포함하지 않는다 [구단주재정검수]',()=>{fresh();const start=G.cal.open+10,until=start+21;G.day=until+3;const O={k:'att',d0:start,until,tid:G.user,who:'own',person:bossOf(G.user).own.id,st:'open',base:{ratio:.8,tg:.85}};G.games=[{day:start+5,home:G.user,away:otherT(),att:800,cap:1000},{day:until+1,home:G.user,away:otherT(),att:1000,cap:1000}];const rng=__rngState(),s=JSON.stringify(O),e=cwOrdEval(O);ok(e.done&&!e.ok&&e.txt.includes('홈 1경기')&&e.txt.includes('80%'),'기한 뒤 매진까지 합쳐 성공 '+JSON.stringify(e));ok(JSON.stringify(O)===s&&__rngState()===rng,'관중 지시 조회가 상태·난수 변경');});
T('[검수 11-18 #847 옛저장] 개막전 정책 이력은 근거가 있을 때만 읽고 실제 불러오기 두 번에도 저장·난수가 같다 [구단주재정검수]',()=>{fresh();migrateDraft();const tid=G.user,t=team(tid),y=G.year;ownershipInit();G.day=G.cal.open+30;G.last=null;t.owner='win';t.finOwner={y,owner:'profit',ownerId:'former',plan:'win'};G.goals={...(G.goals||{}),y,owner:'profit'};const h={kind:'acquired',y,d:G.cal.open-30,to:{effectiveYear:y,policy:'win',ownerId:'after'}};G.ownership.clubs[tid].history.push(h);G=JSON.parse(JSON.stringify(G));const rng=__rngState();migrateDraft();const s=JSON.stringify(G);ok(financeSeasonOwner(tid,y).owner==='win'&&financeSeasonOwner(tid,y).ownerId==='after','발표된 당해 금융 정책 옛 이력 미반영');migrateDraft();ok(JSON.stringify(G)===s&&__rngState()===rng,'실제 두번째 불러오기·순수 금융조회가 저장·난수 변경');const H=G.ownership.clubs[tid].history.at(-1);delete H.d;ok(financeSeasonOwner(tid,y).owner==='profit','실제 날짜 없는 이력으로 약속 변경');H.d=G.cal.open;ok(financeSeasonOwner(tid,y).owner==='profit','개막 당일 변경을 개막 전으로 취급');H.d=G.cal.open-30;H.to.effectiveYear=y+1;ok(financeSeasonOwner(tid,y).owner==='profit','다음해 발표로 올해 금융약속 변경');H.to.effectiveYear=y;G.last={y};ok(financeSeasonOwner(tid,y).owner==='profit','끝난 시즌 금융약속 소급 변경');});
T('[검수 11-18 #850 경계] 교실 비용은 약정 첫해와 마지막해에 한번씩만 청구하고 과거에는 표식을 만들지 않는다 [구단주재정검수]',()=>{fresh();facInit();const t=team(G.user),y=G.year,k='indoor';t.cash=10000;t.cityOb=[{k,city:t.city,y0:y+1,y1:y+2,prog:40,help:1000,miss:0}];const o=t.cityOb[0],cash=t.cash,rng=__rngState();G.last={y};facDealsYear(t);ok(t.cash===cash&&o.lastY==null&&o.miss===0,'약정 전 표식·현금 변경');G.last.y=y+1;facDealsYear(t);const c1=t.cash,sp=G.spend.fac||0;ok(cash-c1===40&&o.lastY===y+1&&t.cityOb.length===1,'첫해 청구 누락');facDealsYear(t);ok(t.cash===c1&&(G.spend.fac||0)===sp,'첫해 중복 청구');G.last.y=y+2;facDealsYear(t);ok(t.cash===c1-40&&t.cityOb.length===0,'마지막해 누락/만료 실패');ok(__rngState()===rng,'시작연도 처리 추가 난수');});
T('[검수 11-18 #852 경계] 회장 지시와 구형 지시는 기존 보상을 유지하고 사장 교체 지시는 취소한다 [구단주재정검수]',()=>{fresh();const tid=G.user;team(tid).indie=false;const p=playersOf(tid)[0];p.extNext={yrs:3};const B=bossOf(tid);B.own.rap=30;B.ceo.rap=30;G.ownOrder={k:'ext',t:'기존 지시',d0:G.day,until:G.day+1,base:{pid:p.id},st:'open'};const rng=__rngState();cwOrdDaily();ok(B.own.rap===33&&B.ceo.rap===30&&G.mail[0].from==='구단주실','구형 회장 지시 보상 변경');const j=JSON.stringify(G);cwOrdDaily();ok(JSON.stringify(G)===j,'이미 완료된 지시 중복 보상');G.ownOrder={k:'ext',t:'사장 지시',d0:G.day,until:G.day+1,base:{pid:p.id},tid,who:'ceo',person:'old-ceo',st:'open'};const trust=team(tid).trust,mails=G.mail.length;cwOrdDaily();ok(G.ownOrder.st==='cancelled'&&team(tid).trust===trust&&G.mail.length===mails&&B.ceo.rap===30,'전임 사장 지시 보상/벌점 발생');ok(__rngState()===rng,'지시 종료 추가 난수');});
T('[검수 11-18 #852 미달] 사장 발급 미달 보고도 사장실과 해당 인물을 표시한다 [구단주재정검수]',()=>{fresh();team(G.user).indie=false;const B=bossOf(G.user),p=playersOf(G.user)[0];delete p.extNext;G.ownOrder={k:'ext',t:'연장',base:{pid:p.id},d0:G.day-2,until:G.day,tid:G.user,who:'ceo',person:B.ceo.id,st:'open'};const trust=team(G.user).trust,rng=__rngState();cwOrdDaily();const m=G.mail[0];ok(G.ownOrder.st==='fail'&&team(G.user).trust===trust-1&&m.from==='사장실'&&m.subj.includes('사장 지시 미달')&&m.body.includes(B.ceo.name),'사장 미달을 회장이 보고 '+JSON.stringify(m));ok(__rngState()===rng,'미달 처리 추가 난수');});
T('[검수 11-18 #853 경계] 지시일은 제외하고 마감일 더블헤더 두 경기는 실제 좌석 합계로 집계한다 [구단주재정검수]',()=>{fresh();const tid=G.user,d=G.cal.open+10,until=d+21;G.day=until+1;G.games=[{day:d,home:tid,att:1000,cap:1000},{day:until,home:tid,att:900,cap:1000,dh:1},{day:until,home:tid,att:500,cap:1000,dh:2},{day:until+1,home:tid,att:1000,cap:1000}];const O={k:'att',d0:d,until,base:{tg:.75}},j=JSON.stringify(G),rng=__rngState(),e=cwOrdEval(O);ok(e.done&&!e.ok&&e.txt.includes('홈 2경기')&&e.txt.includes('70%'),'기한/차전/좌석 집계 '+JSON.stringify(e));ok(JSON.stringify(G)===j&&__rngState()===rng,'판정 조회가 저장·난수 변경');});

/* 847~863: 원본 7건+옛 저장 경계/실제 로더 회귀. */
const CI849_PREP=()=>{fresh();G.day=G.cal.open+100;G.last=null;G.tnames={};const tid=G.user,t=team(tid),S=stadOf(tid);t.city='광주';t.nick='블레이즈';t.cash=100000;t.market=1;t.region='호남·충청';S.name='광주 야구장';S.names=[];S.built=2015;S.cap=17000;S.lv.prem=2;S.build=[];S.proj=null;S.xq=null;for(const k of ['reloc','opened','debt','attStart','xd','xdh'])delete S[k];return {tid,t,S};};
const CI849_LEGACY=()=>{const P=CI849_PREP(),{tid,t}=P,d=G.cal.open+20;G.tnames[tid]=[{y0:-Infinity,y1:G.year-1,city:'광주',nick:t.nick},{y0:G.year,y1:null,d0:d,city:'전주',nick:t.nick}];t.city='전주';return {...P,d};};
T('[검수 11-18 #849] 실제 옛 연고 이전 보정은 옛구장24경기만 빼고 새구장36경기와 구단전체60경기를 보존한다 [구단정체성검수]',()=>{const {tid,S,d}=CI849_LEGACY();const old={name:'광주 야구장',n:24,sum:24*19000,cap:24*24000,so:3},nw={name:'전주 야구장',n:36,sum:36*15300,cap:36*17000,so:9};G.sea.att={[tid]:{n:60,sum:old.sum+nw.sum,cap:old.cap+nw.cap,so:12,venues:[old,nw]}};const all=JSON.stringify(G.sea.att[tid]);ciMigrate();const A=stadVenueAtt(tid),D=stadXpDem(tid);ok(A&&A.n===36&&A.sum===nw.sum&&A.cap===nw.cap&&A.so===nw.so,'새 구장 실제관중 차감 '+JSON.stringify(A));ok(D&&D.n===36,'36경기 증설심사 누락 '+JSON.stringify(D));ok(JSON.stringify(G.sea.att[tid])===all&&G.sea.att[tid].n===60,'구단 전체60경기 재정 장부 변경');});
T('[검수 11-18 #854] 야인 전구단의 인수 후 변경 판정도 같은난수의 일반AI구단처럼 실제 이전예약을 남긴다 [구단정체성검수]',()=>{const {tid,t}=CI849_PREP();t.market=.86;t.region='호남';t.indie=false;G.unemp={y:G.year,from:tid};const data=JSON.stringify(G),other=otherT();let seed=null,want=null;for(let n=1;n<=100;n++){G=JSON.parse(data);G.user=other;__seed(854000+n);ciOnSale(tid);if(team(tid).ciPend?.city){seed=854000+n;want=JSON.stringify(team(tid).ciPend);break;}}ok(seed!=null,'실제 AI 이전 판정 준비');G=JSON.parse(data);__seed(seed);ciOnSale(tid);ok(team(tid).ciPend?.city&&JSON.stringify(team(tid).ciPend)===want,'야인 전구단만 인수 변경 건너뜀');});
T('[검수 11-18 #855] 실제 이름결정 카드의 후보를 다른 구단이 먼저 쓰면 이름과신뢰를 바꾸지 않는다 [구단정체성검수]',()=>{const {tid,t}=CI849_PREP(),other=otherT();ciOnSale(tid);const e=G.evs.find(x=>x.k==='rebrand'&&x.data?.tid===tid&&!x.done);ok(e&&e.data.a,'이름 카드 준비');clubRebrand(other,{nick:e.data.a},'검수855 먼저 선택');const name=t.nick,trust=t.trust;evPick(e.id,0);ok(t.nick===name&&t.trust===trust,'옛 카드가 중복 이름과 신뢰 보상 적용');ok(G.teams.filter(x=>x.nick===e.data.a).length===1,'중복 구단 이름');});
T('[검수 11-18 #856] 따로 예약한 연고 이전과 이름 변경은 실제 결산 적용에서 함께 남는다 [구단정체성검수]',()=>{const {tid,t}=CI849_PREP();ok(ciSched(tid,{city:'전주'},'검수 이전')==='pend','이전 예약 준비');ok(ciSched(tid,{nick:'팰컨스'},'검수 별칭')==='pend','이름 예약 준비');ok(t.ciPend.city==='전주'&&t.ciPend.nick==='팰컨스','두번째 결정이 앞 예약 덮어씀');G.last={y:G.year};ciPendApply();ok(t.city==='전주'&&t.nick==='팰컨스'&&!t.ciPend,'실제 결산 적용이 두 결정을 잃음');});
T('[검수 11-18 #857] 같은날같은시즌 두 이름 변경도 실제 구단 연대기에 각각 한 건씩 남는다 [구단정체성검수]',()=>{const {tid,t}=CI849_PREP();G.last={y:G.year};clubRebrand(tid,{nick:'팰컨스'},'검수857 첫변경');clubRebrand(tid,{nick:'타이탄즈'},'검수857 둘째변경');const L=clubChron(tid).filter(x=>x.k==='rebrand'&&x.t.includes('검수857'));ok(t.nick==='타이탄즈'&&L.length===2,'실제 두 변경 중 연대기 누락 '+JSON.stringify(L));ok(L.some(x=>x.t.includes('첫변경'))&&L.some(x=>x.t.includes('둘째변경')),'같은 시즌 다른 사건이 중복키로 합쳐짐');});
T('[검수 11-18 #858] 기존 새도시 임시구장 이력이 있어도 옛 이전 복구 뒤 경기일 장소는 날짜순으로 맞는다 [구단정체성검수]',()=>{const {tid,S,d}=CI849_LEGACY();S.names=[{n:'전주 임시구장',until:d+20}];ciMigrate();ok(stadNameAt(tid,d-1)==='광주 야구장','이전 전 장소 오조회 '+stadNameAt(tid,d-1));ok(stadNameAt(tid,d+10)==='전주 임시구장'&&stadNameAt(tid,d+21)==='전주 야구장','이전 후 이름 이력 또는 현재구장 손실');const r=__rngState(),s=JSON.stringify(G);stadNameAt(tid,d-1);ok(JSON.stringify(G)===s&&__rngState()===r,'경기일 이름 조회가 저장·난수 변경');});
T('[검수 11-18 #863] 옛 연고 이전 보정은 실제 현재도시의 시장규모와권역도 복원한다 [구단정체성검수]',()=>{const {t,tid}=CI849_LEGACY();ciMigrate();ok(stadName(tid)==='전주 야구장','구장 복원 준비');ok(t.market===.86&&t.region==='호남','전주 구장에 옛 광주 경제권 잔류 '+t.market+'/'+t.region);});
T('[검수 11-18 #849 #858 #863 옛 로드] 실제 이전 보정은 구장별관중·날짜별이름·현재도시경제권을 함께 복구하고 두번저장도 무난수다 [구단정체성검수]',()=>{const {tid,t,S,d}=CI849_LEGACY();S.names=[{n:'전주 임시구장',until:d+20}];G.sea.att={[tid]:{n:60,sum:1006800,cap:1188000,so:12,venues:[{name:'광주 야구장',n:24,sum:456000,cap:576000,so:3},{name:'전주 야구장',n:36,sum:550800,cap:612000,so:9}]}};G=JSON.parse(JSON.stringify(G));const r=__rngState();ciMigrate();ok(stadVenueAtt(tid).n===36&&G.sea.att[tid].n===60,'구장 관중 구분 누락');ok(stadNameAt(tid,d-1)==='광주 야구장'&&team(tid).market===.86&&team(tid).region==='호남','이름·경제권 복구 누락');const save=JSON.stringify(G);ciMigrate();ok(JSON.stringify(G)===save&&__rngState()===r,'실제 이전 보정 두번이 저장·난수 변경');});
T('[검수 11-18 #863 이전완료옛저장] 구장이 이미복구된 옛 저장도 현재도시가 확인되면 경제권을 보정하고 다른도시는 추측하지 않는다 [구단정체성검수]',()=>{const {tid,t,S,d}=CI849_LEGACY();S.name='전주 야구장';S.reloc={y:G.year,d,from:'광주',to:'전주',fix:1};S.opened=d;ciMigrate();ok(t.market===.86&&t.region==='호남','이전완료표시 때문에 옛 경제권 유지');const v=JSON.stringify(G),r=__rngState();ciMigrate();ok(JSON.stringify(G)===v&&__rngState()===r,'경제권 정리가 멱등·무난수 아님');t.city='사용자도시';t.market=1.23;t.region='맞춤권역';ciMigrate();ok(t.market===1.23&&t.region==='맞춤권역','현재도시 근거 없이 옛 예약지 경제권으로 덮어씀');});
T('[검수 11-18 #849 이전보정완료] 옛 fix marker와 잘못된 전체 attStart가 있어도 명시장소24대36으로 수리한다 [구단정체성검수]',()=>{const {tid,S,d}=CI849_LEGACY();S.name='전주 야구장';S.names=[{n:'광주 야구장',until:d}];S.reloc={y:G.year,d,from:'광주',to:'전주',fix:1};G.sea.att={[tid]:{n:60,sum:1006800,cap:1188000,so:12,venues:[{name:'광주 야구장',n:24,sum:456000,cap:576000,so:3},{name:'전주 야구장',n:36,sum:550800,cap:612000,so:9}]}};S.attStart={y:G.year,n:60,sum:1006800,cap:1188000,so:12};const total=JSON.stringify(G.sea.att[tid]);ciMigrate();ok(stadVenueAtt(tid).n===36&&JSON.stringify(G.sea.att[tid])===total,'이미보정 marker 때문에 새36경기 누락');const st=JSON.stringify(G),r=__rngState();ciMigrate();ok(JSON.stringify(G)===st&&__rngState()===r,'marker 재정합이 멱등·무난수 아님');});
T('[검수 11-18 #849 정상변경] 실제 이전당일은 현재구장0으로 시작하고 다음 실제홈경기만1 증가한다 [구단정체성검수]',()=>{const {tid,S,t}=CI849_PREP();G.last={y:G.year};G.sea.att={[tid]:{n:24,sum:456000,cap:576000,so:3,best:24000}};const before=JSON.stringify(G.sea.att[tid]);ok(clubRebrand(tid,{city:'전주'},'정상 이전 검수'),'실제 이전 준비');ok(stadVenueAtt(tid).n===0&&G.sea.att[tid].n===24,'새 이전에 옛 경기 잔류');stadGame(G.day,tid,otherT());ok(stadVenueAtt(tid).n===1&&G.sea.att[tid].n===25,'다음 실제경기 분리 누락');const B=JSON.stringify(S.attStart);ciMigrate();ok(JSON.stringify(S.attStart)===B&&stadVenueAtt(tid).n===1,'이미 정상 경계를 뒤로 옮김');});
T('[검수 11-18 #857 옛연대기] 같은연도 source충돌 두전이를 보존하고 실제날짜가남은 누락전이만 복구한다 [구단정체성검수]',()=>{const {tid,t}=CI849_PREP(),d=G.day,y=G.year;G.tnames[tid]=[{y0:y-1,y1:y-1,city:t.city,nick:'블레이즈'},{y0:y,y1:y-1,d0:d,city:t.city,nick:'팰컨스'},{y0:y,y1:y-1,d0:d,city:t.city,nick:'타이탄즈'},{y0:y,y1:null,d0:d+1,city:t.city,nick:'마린스'}];t.nick='마린스';const source='rebrand:'+tid+':'+y,entries=[{tid,y,d,k:'rebrand',source,t:t.city+' 블레이즈 → '+t.city+' 팰컨스'},{tid,y,d,k:'rebrand',source,t:t.city+' 팰컨스 → '+t.city+' 타이탄즈'}];G.clubHist={[tid]:entries};G.chron=[];G.clubHistV=1;G=JSON.parse(JSON.stringify(G));const st=JSON.stringify(G),r=__rngState(),L=clubChron(tid).filter(x=>x.k==='rebrand');ok(L.length===3&&L.some(x=>x.t.includes('타이탄즈 →')),'옛 source충돌/실제전이 복구 누락 '+JSON.stringify(L));ok(JSON.stringify(G)===st&&__rngState()===r,'연대기 조회가 저장·난수 변경');chronArchiveInit();const a=JSON.stringify(G);chronArchiveInit();ok(JSON.stringify(G)===a&&__rngState()===r,'복구 연대기 중복 저장');});
T('[검수 11-18 #849 #858 #863 실제로더] 실제 migrateDraft로 옛 구장/날짜/경제권을 JSON왕복 두번해도 동일하고 무난수다 [구단정체성검수]',()=>{const {tid,S,d}=CI849_LEGACY();S.names=[{n:'전주 임시구장',until:d+20}];G.sea.att={[tid]:{n:60,sum:1006800,cap:1188000,so:12,venues:[{name:'광주 야구장',n:24,sum:456000,cap:576000,so:3},{name:'전주 야구장',n:36,sum:550800,cap:612000,so:9}]}};G=JSON.parse(JSON.stringify(G));const r=__rngState();migrateDraft();ok(stadVenueAtt(tid).n===36&&G.sea.att[tid].n===60&&stadNameAt(tid,d-1)==='광주 야구장'&&team(tid).market===.86&&team(tid).region==='호남','실제 로더 hook 누락');const a=JSON.stringify(G);G=JSON.parse(a);migrateDraft();ok(JSON.stringify(G)===a&&__rngState()===r,'실제 로더 JSON재로드 두번 상태·난수 변경');});
T('[검수 11-18 #857 JSON뒤새변경] 새 JSON에서 처음 실행한 실제 개명도 복구연대기와 이중 기록되지 않는다 [구단정체성검수]',()=>{const {tid,t}=CI849_PREP();G.last={y:G.year};G=JSON.parse(JSON.stringify(G));const r=__rngState();ok(clubRebrand(tid,{nick:'팰컨스'},'JSON뒤 새결정'),'실제 새 개명 준비');const L=clubChron(tid).filter(x=>x.k==='rebrand'&&x.t.includes('JSON뒤 새결정'));ok(L.length===1,'실제 새 전이를 옛 복구와 중복 '+JSON.stringify(L));const a=JSON.stringify(G);ok(!clubRebrand(tid,{nick:'팰컨스'},'JSON뒤 새결정')&&JSON.stringify(G)===a&&__rngState()===r,'같은 실제 결정 재호출이 중복/난수 변경');});

function cs848(){__seed(847848);buildWorld({lite:true});claimTeam(6);G.tut={done:true,step:99};G.ps=null;G.last=null;G.moves=[];return {U:G.user,Y:G.year};}
T('[검수 11-18 #848] 신청때자금이있어도 초대형승인일0원인 독립구단은 착공·분담금없이보류한다 [구장847검수]',()=>{const {U,Y}=cs848(),t=team(U),S=stadOf(U);G.day=KD(10,15);t.indie=true;t.cash=100000;t.market=1.3;t.trust=90;S.cap=17000;S.dome=false;S.build=[];S.xq=null;S.proj={stage:'plan',start:G.day};S.xdh=[Y-3,Y-2,Y-1].map(y=>({y,occ:.95,so:50,n:72}));ok(!newStadMegaWhy(U),'3년관중·시장 준비');ok(newStadPick('mega')===''&&S.proj.mr>G.day,'실제초대형신청실패');G.day=S.proj.mr;S.proj.mp=1;t.cash=0;ok(spendable(U)===0,'승인일가용자금0준비');newStadTeam(U);ok(!S.proj||S.proj.stage!=='build','0원인데초대형착공 '+JSON.stringify(S.proj));ok(newStadDue(U)===0&&t.cash===0,'승인후첫분담금과부채생성');});
T('[검수 11-18 #859 청구] paid없는옛9000분담계약은 실제결산에서3000을청구하고납부액을남긴다 [구장847검수]',()=>{const {U,Y}=cs848(),t=team(U),S=stadOf(U);S.debt={cost:9000,opened:G.day-30,city:t.city,name:stadName(U)};G=JSON.parse(JSON.stringify(G));ok(newStadDue(U)===3000,'paid없는옛부채정기청구0 '+newStadDue(U));G.day=G.cal.end+3;const O=G.teams.map(x=>x.id).filter(x=>x!==U);G.ps={done:true,champ:U,runner:O[0],order:[U,...O].map(tid=>({tid})),res:{po:[O[0],O[1]],spo:[O[1],O[2]],wc:[O[2],O[3]]},finDay:G.day};settlement();const f=G.last.fins[U];ok(f.exp.some(x=>x[0]==='신구장 분담금'&&x[1]===3000),'실제결산명세의옛부채청구누락');ok(stadOf(U).debt.paid===3000,'결산납부액복구누락');});
T('[검수 11-18 #859 이전] paid없는옛부채도 실제연고이전때정산하고새구장에넘기지않는다 [구장847검수]',()=>{const {U}=cs848(),t=team(U),S=stadOf(U);G.day=KD(11,15);t.indie=true;t.cash=20000;S.debt={cost:9000,opened:G.day-500,city:t.city,name:stadName(U)};G=JSON.parse(JSON.stringify(G));const c=team(U).cash,r=__rngState();clubRebrand(U,{city:'전주'},'옛부채검수');ok(!stadOf(U).debt&&team(U).cash===c-9000,'옛부채미정산·새구장전이 '+JSON.stringify(stadOf(U).debt));ok(__rngState()===r,'이전부채정산이주난수사용');const raw=JSON.stringify(G);ciMigrate();ciMigrate();ok(JSON.stringify(G)===raw&&__rngState()===r,'이전복원이분담금을중복청구');});
T('[검수 11-18 #860] 같은도시신구장은기존36홈경기총합을보존하되자체증설수요는0경기부터센다 [구장847검수]',()=>{const {U}=cs848(),S=stadOf(U),H=homeGames(U,G.cal.open,G.cal.end).slice(0,36);ok(H.length===36,'홈36경기일정준비');for(const [d,a] of H){G.day=d;stadGame(d,U,a);}const A=G.sea.att[U],keep={n:A.n,sum:A.sum,cap:A.cap,tk:A.tk,fb:A.fb,so:A.so};G.day=H[35][0]+1;S.proj={stage:'build',k:'dome',cap:18000,cost:16000,paid:16000,done:G.day};__seed(860860);const fn=FO_RNG;let calls=0;const tick=()=>{calls++;FO_RNG=fn;try{return R();}finally{FO_RNG=tick;}};FO_RNG=tick;try{newStadTeam(U);}finally{FO_RNG=fn;}ok(Object.entries(keep).every(([k,v])=>G.sea.att[U][k]===v),'신구장개장으로구단전체관중/수입변경');ok(stadVenueAtt(U).n===0,'새구장이옛36경기를현재수요로사용 '+stadVenueAtt(U).n);ok(!stadXpDem(U),'신구장0경기에옛구장증설명분전이');ok(calls===32&&__rngState()===-1518575268,'기준엔진의같은개장난수흐름변경 '+calls+'/'+__rngState());const d=G.day+1,a=G.teams.find(t=>t.id!==U).id;stadGame(d,U,a);ok(G.sea.att[U].n===37&&stadVenueAtt(U).n===1,'개장후첫관중의구단/구장집계분리실패');});
T('[검수 11-18 #861] 실제담장공사를마친해새돔을개장해도옛규격·그해공사제한을잇지않는다 [구장847검수]',()=>{const {U}=cs848(),t=team(U),S=stadOf(U);G.day=KD(11,2);t.indie=true;t.cash=100000;const D={lf:95,cf:120,rf:95,wl:8,wc:8,wr:8};ok(fenceSet(D)===''&&S.fenceY===sponSeason(),'실제옛구장담장공사준비');G.day++;S.proj={stage:'build',k:'dome',cap:18000,cost:16000,paid:16000,done:G.day};newStadTeam(U);const d=stadDim(U),next={...d,lf:d.lf+1},err=fenceSet(next);ok(JSON.stringify(d)!==JSON.stringify(D)&&err==='','새돔옛규격승계/공사제한: '+JSON.stringify(d)+' / '+err);});
T('[검수 11-18 #862]9월결산후다음시즌구장전망은월경계로예정돔을빼거나더하지않는다 [구장847검수]',()=>{const {U,Y}=cs848(),S=stadOf(U),a=otherT(),d=dnum(Y,3,29);G.cal={y:Y,open:d,end:d,sched:{[d]:[[U,a]]}};G.sea.att={};G.sea.rec[U]={w:0,l:0,t:0};G.last={y:Y};G.rolled=Y;G.day=dnum(Y,9,30);S.dome=false;S.proj={stage:'build',k:'dome',cap:18000,cost:16000,paid:16000,done:dnum(Y+1,2,1)};const A=stadProj(U,true);G.day=dnum(Y,10,1);const B=stadProj(U,true);ok(sponSeason()===Y+1,'두날회계연도준비');ok(A.ad===B.ad&&A.att===B.att&&A.n===B.n,'같은다음시즌의9월/10월전망불일치 '+JSON.stringify([A,B]));ok(A.ad>=2500,'9월전망이이미확정된다음시즌돔수입누락');const r=__rngState();stadProj(U,true);stadProj(U,true);ok(__rngState()===r,'구장전망반복이주난수소비');});

T('[검수 11-18 #848 AI독립] AI독립구단도시승인일무자금이면초대형을착공하지않으며기존판정난수한자리는유지한다 [구장847검수]',()=>{const {U,Y}=cs848(),t=G.teams.find(t=>t.id!==U),S=stadOf(t.id);G.day=KD(10,15);t.indie=true;t.cash=100000;t.market=1.3;t.trust=90;S.cap=17000;S.dome=false;S.build=[];S.xq=null;S.proj={stage:'plan',start:G.day};S.xdh=[Y-3,Y-2,Y-1].map(y=>({y,occ:.95,so:50,n:72}));ok(newStadPick('mega',t.id)===''&&S.proj.mr>G.day,'AI합법신청준비');G.day=S.proj.mr;t.cash=0;S.proj.mp=1;const fn=FO_RNG;let calls=0;FO_RNG=()=>{calls++;return 0;};try{newStadTeam(t.id);}finally{FO_RNG=fn;}ok(!S.proj||S.proj.stage!=='build','AI0원초대형착공');ok(calls===1&&newStadDue(t.id)===0&&t.cash===0,'AI거절에서기존판정난수/자금변경 '+calls);});
