function FC890_fault(){const f=FC889(),pair=f.P.find(p=>p[0]!==FL_SM&&p[1]!==FL_SM),[h,a]=pair,before=FC889_players(pair),rot=JSON.stringify(f.F.rot),af=applyFarm,lf=lineFor;let inApply=false,hit=false;try{applyFarm=(d,g)=>{inApply=g.S.h.tid===h&&g.S.a.tid===a;try{return af(d,g);}finally{inApply=false;}};lineFor=(p,...args)=>{if(inApply&&p.team===a&&!hit){hit=true;throw Error('FC890 away-record injected');}return lf(p,...args);};flPlayDay(f.d);}finally{applyFarm=af;lineFor=lf;}ok(hit,'선수기록 반영 도중 실제 오류 주입 미실행');return {...f,h,a,before,rot};}
T('[퓨처스핵심검수] [검수 11-18 #889] 일부 실패한 날 다시 진행하면 실패 경기만 복구하고 이미 확정한 결과·선수·난수는 중복 반영하지 않는다',()=>{const {F,d,r,P}=FC889(),[h,a]=P[0],sg=simGame;let hit=0;try{simGame=(dd,hh,aa,...args)=>{if(hh===h&&aa===a){hit++;throw Error('FC889 first game injected');}return sg(dd,hh,aa,...args);};flPlayDay(d);}finally{simGame=sg;}ok(hit===1&&F.games.length===P.length-1,'실패1·나머지 실제경기 확정 준비');const others=flTeams().filter(t=>!([h,a].includes(t))),players=FC889_players(others),games=JSON.stringify(F.games),round=F.round,n=flPlayDay(d);ok(n===1&&F.games.length===P.length&&F.games.some(g=>g.d===d&&g.h===h&&g.a===a),'같은 날 재진입이 실패 경기를 영구 누락');ok(F.round===round&&F.games.filter(g=>g.d===d).every(g=>g.r===r),'실패 재처리가 다음 라운드로 바뀜');ok(FC889_players(others)===players&&JSON.stringify(F.games.filter(g=>!(g.h===h&&g.a===a)))===games,'확정된 다른 경기/선수 중복 반영');const saved=JSON.stringify({F,players:G.players}),rng=__rngState();ok(flPlayDay(d)===0&&JSON.stringify({F,players:G.players})===saved&&__rngState()===rng,'완료된 날 세 번째 실행이 결과·선수·난수 변경');});
T('[퓨처스핵심검수] [검수 11-18 #890 결과] 선수 기록 반영 중 오류가 난 경기는 결과와 순위도 확정하지 않는다',()=>{const {F,d,h,a}=FC890_fault();ok(!F.games.some(g=>g.d===d&&g.h===h&&g.a===a),'반만 반영한 경기의 점수·승패를 확정');for(const t of [h,a])ok(Object.values(F.rec[t]).every(v=>v===0),'선수기록 실패 경기의 순위 승패/득실 반영');});
