T('[검수 11-18 #873] 실제7일전 포스트시즌 등록마감 안내는 임시외국인을 빼고 정식가능2명으로 중요알림을 낸다 [대체AI검수]',()=>{const {tid,o,q}=TA873_WORLD();G.day=KD(8,7);G.cal.end=KD(10,1);o.injHist=[{d:G.day,days:60,k:'back',t:tid}];ok(!signTempForeign(tid,o.id,q.id),'실제 임시 등록 준비');ok(foreignOf(tid).filter(p=>p.foreign==='용병'&&healthy(p)).length===3,'두 정식+한 임시 준비');G.cal.sched[G.day+1]=[];G.makeup=[];const N=note,S=stop,L=[];try{note=(k,msg,...a)=>{if(String(msg).includes('포스트시즌 등록 마감'))L.push({imp:false,msg});return N(k,msg,...a);};stop=(k,msg,...a)=>{if(String(msg).includes('포스트시즌 등록 마감'))L.push({imp:true,msg});return S(k,msg,...a);};processDay();}finally{note=N;stop=S;}const m=L.find(x=>x.msg.includes('7일'));ok(m&&m.imp&&m.msg.includes('2명'),'임시선수를 PS 가능인원에 포함 '+JSON.stringify(L));});
