T('[검수 11-18 #886] 하드5계약의 실제지급 이력합과 결산장부·메일이 같은반올림을 쓴다 [후원수입검수]',()=>{fresh();G.cfg=G.cfg||{};G.cfg.hard=true;sponInit();const y=G.year;G.spon.c={};G.spon.off=[];G.spon.hist=[];G.spon.cutL=[];for(const k of Object.keys(SPON_SLOT).filter(k=>!SPON_SLOT[k].indie))G.spon.c[k]={co:'동일액'+k,ind:'스포츠용품',amt:1005,ps:0,champ:0,y0:y,until:y,first:1};const ids=G.teams.map(t=>t.id),me=G.user,oth=ids.filter(id=>id!==me);G.day=G.cal.end+25;SP17ps([me,...oth.slice(0,4)],oth.slice(4),oth[0]);settlement();const hist=G.spon.hist.filter(c=>c.y0===y&&c.co.startsWith('동일액')),total=sum(hist.map(c=>c.paidY)),book=SI879_ROW(G.last.fins[me].inc,'스폰서 계약'),m=G.mail.find(x=>(x.subj||'').includes(y+' 스폰서 결산'));ok(hist.length===5&&m&&m.subj.includes(money(book)),'실제5계약 이력·결산 메일 준비');ok(total===book&&G.spon.paid.v===total,'지급 이력합과 결산 불일치 '+JSON.stringify({paid:hist.map(c=>c.paidY),sum:total,book,stored:G.spon.paid.v,mail:m.subj}));});
