let PA949_BASE=null,PA949_SEED=949007;const PA949_NORMAL_HASH=2060643170;
function PA949(){if(!PA949_BASE){__seed(949001);fresh();G.noRain=true;G.makeup=[];G.res=null;G.last=null;G.psSer={};for(const p of Object.values(G.players)){p.inj=0;p.injOut=0;p.fat=0;delete p.psY;}for(const t of G.teams)setEntry(t.id);const U=G.user,A=G.teams.find(t=>t.id!==U).id,start=KD(10,20),s=mkSeries('ks',U,A,start),ids=[U,A,...G.teams.map(t=>t.id).filter(t=>t!==U&&t!==A)];s.wh=3;s.wl=3;s.gi=6;s.pts=Array.from({length:6},(_,i)=>s.homes[i]===(i%2?A:U)?[2,1]:[1,2]);G.day=s.days[6];G.cal.end=G.day-15;G.ps={y:G.year,seeds:ids.slice(0,5),order:ids.map(tid=>({tid})),res:{wc:[ids[3],ids[4],1,0],spo:[ids[2],ids[3],3,0],po:[A,ids[2],3,1]},round:'ks',done:false,cur:s};PA949_BASE=JSON.stringify(G);}
  const reset=()=>{G=JSON.parse(PA949_BASE);worldReset();};reset();if(PA949_SEED==null){for(let i=1;i<=240;i++){reset();const s=G.ps.cur,g=withRng(949000+i,()=>simGame(G.day,G.user,s.lo,{elim:true,fin:true,elimT:[s.lo,s.hi],noTie:false}));if(g.walk&&g.score.h>g.score.a){PA949_SEED=949000+i;break;}}ok(PA949_SEED!=null,'실제 끝내기 우승 경기 seed 준비');reset();}__seed(949042);return{U:G.user,A:G.ps.cur.lo,d:G.day,seed:PA949_SEED};}
function PA949_PLAY(f,fail){const sg=simGame,gr=gameRecord;let last=null,n=0,hit=false,error=false;try{simGame=(...a)=>{n++;last=withRng(f.seed,()=>sg(...a));ok(last.walk&&last.score.h>last.score.a,'실제 끝내기 경기 재현 불일치');return last;};if(fail)gameRecord=(...a)=>{hit=true;throw Error('PA949 result-card injected');};try{psDay(f.d);}catch(e){error=true;}}finally{simGame=sg;gameRecord=gr;}return{last,n,hit,error};}
function PA949_RECOVER(){const f=PA949(),x=PA949_PLAY(f,true);ok(x.hit&&x.error,'실제 결과 카드 생성 오류 주입 미실행');G.day=f.d+1;const sg=simGame;try{simGame=(...a)=>withRng(f.seed,()=>sg(...a));psCatchUp(G.day);psDay(G.day);}finally{simGame=sg;}ok(G.ps.done&&G.ps.champ===f.U&&G.ps.finDay===f.d+2,'기존 우승 복구 준비 실패');return{...f,...x};}
T('[PS원자검수] [검수 11-18 #949 박스] 우승 결정전 결과 카드 오류 뒤 실제 복구는 마지막 경기 박스스코어도 한 건 보존한다',()=>{const f=PA949_RECOVER(),L=G.games.filter(g=>g.day===f.d&&g.home===f.U&&g.away===f.A);ok(L.length===1&&L[0].box&&L[0].hs===f.last.score.h&&L[0].as===f.last.score.a,'우승만 복구하고 실제 마지막 경기 박스스코어가 없음');const saved=JSON.stringify({games:G.games,ps:G.ps,stats:G.psSer,players:Object.values(G.players).map(p=>[p.id,p.psY])}),rng=__rngState();psCatchUp(G.day+1);psDay(G.day+1);ok(JSON.stringify({games:G.games,ps:G.ps,stats:G.psSer,players:Object.values(G.players).map(p=>[p.id,p.psY])})===saved&&__rngState()===rng,'확정 복구 재호출이 경기·시리즈·개인 기록 또는 주난수 중복 변경');});
