T('[검수 11-18 #948] 실제한국시리즈우승뒤새감독을선임해도우승팀과감독시즌기록은우승당시감독이다 [우승보관948검수]',()=>{const {U,O,Y}=ca948();G.day=G.cal.open-5;ok(hireMgr(G.mmarket[0].id,3)==='','실제우승전임선임준비');const old=G.mgr[U];old.name='우승전임감독';G.day=G.cal.end+5;for(const t of G.teams){for(const p of playersOf(t.id)){p.injOut=0;p.fat=0;}setEntry(t.id);}const order=[U,O,...G.teams.map(t=>t.id).filter(id=>id!==U&&id!==O)].map((tid,i)=>({tid,w:i?70:74,l:i?74:68,t:i?0:2}));G.sea.rec[U]={w:74,l:68,t:2};const s=mkSeries('ks',U,O,G.day);s.gi=6;s.wh=3;s.wl=3;s.pts=Array.from({length:6},()=>[3,2]);G.day=s.days[6];G.ps={y:Y,order,seeds:order.slice(0,5).map(x=>x.tid),res:{wc:[order[3].tid,order[4].tid,2,0],spo:[order[2].tid,order[3].tid,3,1],po:[O,order[2].tid,3,2]},round:'ks',done:false,cur:s};const sim=simGame;let ran=0;try{simGame=(...a)=>{const g=sim(...a);ran++;g.score.h=Math.max(g.score.h,g.score.a+1);return g;};psDay(G.day);}finally{simGame=sim;}ok(ran===1&&G.ps.done&&G.ps.champ===U&&G.games.some(g=>g.kind==='한국시리즈 7차전'),'실제최종전·우승확정준비');const next=G.mmarket.find(m=>m.id!==old.id);next.name='결산신임감독';ok(hireMgr(next.id,3)===''&&G.mgr[U].id===next.id,'실제결산전감독교체준비');const h={y:Y,champ:U,runner:O,order,ps:psArchiveSnapshot(G.ps,Y)};G.history.push(h);histSnapSeason(h);const rows=G.mgrH[U]||[];ok(h.cr?.mg===old.name&&rows.some(x=>x.id===old.id&&x.w===74&&x.l===68&&x.ch===1)&&!rows.some(x=>x.id===next.id&&x.ch),'새감독에게우승·시즌귀속 '+JSON.stringify({cr:h.cr?.mg,rows}));});
