function gg961FieldGame(apply=true){const {h,a,d}=gg961Fresh();G.mgr[h].dfn=95;G.mgr[h].small=0;const S={h:gameSide(h,d,false),a:gameSide(a,d,false)},q=S.h.bench.find(p=>!p.isP&&!isC(p));ok(q,'준비: 대수비후보 없음');q.pos='SS';q.pexp={SS:100};q.r.def=100;const starter=S.h.order.find(p=>S.h.posOf[p.id]==='SS');ok(starter,'준비: 선발SS없음');for(const p of S.h.order)p.r.def=100;starter.r.def=0;S.h.bench=[q];q.hist=(q.hist||[]).filter(x=>x.y!==G.year||x.lvl!=='1군');Object.assign(lineFor(q,G.year,h,'1군'),{g:79,pa:300,ab:280,h:50,bb:20,pos:'SS',pp:{SS:300}});q.use={y:G.year,g:79,pos:{SS:79},slot:{8:79}};const rival=playersOf(a).find(p=>!p.isP);rival.hist=(rival.hist||[]).filter(x=>x.y!==G.year||x.lvl!=='1군');Object.assign(lineFor(rival,G.year,a,'1군'),{g:144,pa:650,ab:550,h:300,d:40,tr:10,hr:70,bb:100,rbi:200,r:200,sb:100,pos:'SS',pp:{SS:650}});rival.use={y:G.year,g:144,pos:{SS:144},slot:{4:144}};const old=outcome;let hr=0,g;try{outcome=(b,p,dv,fp,fs)=>{LBIP=null;return fs.tid===a&&hr++===0?'HR':'OUT';};__seed(961003);g=simGame(d,h,a,false,{sides:S,pitchRecords:false});}finally{outcome=old;}ok(S.h.subIn?.[q.id]!=null&&S.h.posOf[q.id]==='SS'&&S.h.changes.some(c=>c.lineup.some(x=>x.id===q.id&&x.pos==='SS')),'준비: 실제simGame SS대수비 안나옴');if(apply)applyGame(d,h,a,g,false);return {h,a,d,q,starter,g,hs:seasonTotal(q,G.year,'1군')};}
T('[검수 #961 실제수비교체] 실제 SS 대수비 한경기는79경기 장부를80으로 올리되 선발79경기는 유지한다 [골든포지션검수]',()=>{const {q,hs}=gg961FieldGame();ok(hs.g===80&&q.use.g===79,'준비: 실제80경기/선발79경기 아님 '+hs.g+'/'+q.use.g);ok((q.use.fpos?.SS??q.use.pos.SS)===80,'actual simGame 대수비에도 시즌80/SS장부'+(q.use.fpos?.SS??q.use.pos.SS));});
