function ld985Installed(a,b){return withRng(985101,()=>ladderSwap(JSON.parse(ladderWorldJson({season:'cup'})),()=>{const kA=cupIdBase(a),CA=cupInstall(0,a,kA),CB=cupInstall(1,b,cupIdBase(b,kA)),D=FrontOfficeCore.dv;return [CA,CB].map(C=>{const s=ladderSide(C,G.day),rot=C.rot.filter(p=>!(p.injOut>0)),pen=C.pen.filter(p=>!(p.injOut>0)).map(penV).sort((a,b)=>b-a).slice(0,5);return{ids:s.order.map(p=>p.id),p:{off:D(avg(s.order.map(offV))),pow:D(avg(s.order.map(p=>p.r.pow))),con:D(avg(s.order.map(p=>p.r.con))),def:D(avg(s.order.filter(p=>s.posOf[p.id]!=='DH').map(p=>defAt(p,s.posOf[p.id])))),sp:D(avg(rot.map(spV))),pen:D(pen.length?avg(pen):0)}};});}));}
T('[검수 #985 옛ID] 숙련·다재다능·세부수비가없는옛덱도실제설치ID의대체선수와전체프로필을쓴다 [래더덱검수]',()=>{const a=ld985Legacy(),b=ld980Fresh();let raw=JSON.stringify([a,b]),rng=__rngState();for(let n=0;n<6;n++){a.name='ID탐사'+n;a.h=FrontOfficeCore.cupEntryHash(a);const want=ld985Installed(a,b)[0],got=ulProfile(a);ok(JSON.stringify(got)===JSON.stringify(want.p),'실제설치전체프로필불일치 '+JSON.stringify([got,want.p]));const ids=ulReadyLineup(a).map(x=>x[0].id);ok(JSON.stringify(ids)===JSON.stringify(want.ids),'실제대체ID불일치 '+JSON.stringify([ids,want.ids]));}ok(__rngState()===rng,'옛ID조회가주난수소비');});
T('[검수 #985 해시충돌] 같은해시앞자리 두덱의 B측회피ID와수비까지실제컵설치와같다 [래더덱검수]',()=>{const a=ld985Legacy(),b=JSON.parse(JSON.stringify(a)),ka=cupIdBase(a);let found=false;for(let n=0;n<4096;n++){b.name='충돌'+n;b.h=FrontOfficeCore.cupEntryHash(b);if(cupIdBase(b)===ka){found=true;break;}}ok(found,'해시앞자리충돌준비실패');const raw=JSON.stringify([a,b]),rng=__rngState(),want=ld985Installed(a,b),got=ulProfile(b,ka);ok(JSON.stringify(got)===JSON.stringify(want[1].p),'B측실제회피ID/수비불일치 '+JSON.stringify([got,want[1].p]));const ids=ulReadyLineup(b,ka).map(x=>x[0].id);ok(JSON.stringify(ids)===JSON.stringify(want[1].ids),'B측실제대체ID불일치');const V=ulVs(a,b),W=ulVs(b,a,true);ok(V.rows.every(x=>x.me===want[0].p[x.k]&&x.op===want[1].p[x.k])&&W.rows.every(x=>x.me===want[1].p[x.k]&&x.op===want[0].p[x.k]),'실제A/B순서비교불일치');ok(JSON.stringify([a,b])===raw&&__rngState()===rng,'옛ID비교가입력/주난수변경');});


const lc982Setup=()=>{ fresh(); const U=uld();U.tier=0;const e=cupAiEntries(1,'ul')[0];e.name='봄 구단';e.payRef=Math.max(e.payRef||0,e.pay||0);for(const p of e.P)delete p.injOut;e.h=FrontOfficeCore.cupEntryHash(e);ok(!ulSetDeck(e,'now'),'첫 등록');ok(ulMakeLeague({seed:982991}).ok,'리그 생성');return U.league; };
T('[래더계약검수 #982] 실제 정규 경기의 구단명은 재등록과 JSON 이력에서도 당시 이름이다',()=>{const L=lc982Setup(),s=ulRunSeries(L),score=JSON.stringify(s.g);ok(s.a===0||s.b===0,'우리 경기 fixture');const side=s.a===0?0:1;ok(s.nm?.[side]==='봄 구단','당시 이름 없음');const e=JSON.parse(JSON.stringify(uld().deck.e));e.name='가을 구단';ok(!ulSetDeck(e,'now')&&!ulEditDeck(uld().deck.e),'재등록');ok(L.teams[0].name==='가을 구단'&&s.nm[side]==='봄 구단'&&JSON.stringify(s.g)===score,'옛 경기 이름/점수 변경');const pack=JSON.parse(JSON.stringify(ulLgPack(L)));ok(pack.series[0].nm[side]==='봄 구단'&&pack.teams[0].name==='가을 구단','이력 이름 소멸');});
T('[래더계약검수 #982] 실제 포스트시즌 구단명도 다음 덱 편집으로 바뀌지 않는다',()=>{const L=lc982Setup();L.next=L.sched.length;L.post={seeds:[0,1,2,3],S:[{id:'SF1',k:'s',a:0,b:1,best:3,g:[],bx:[],w:null}],next:0,champ:null,runner:null};const s=ulRunPost(L);ok(s.nm?.[0]==='봄 구단','PS 당시 이름 없음');const score=JSON.stringify(s.g),e=JSON.parse(JSON.stringify(uld().deck.e));e.name='가을 구단';ok(!ulEditDeck(e),'PS 뒤 편집');const pack=JSON.parse(JSON.stringify(ulLgPack(L)));ok(pack.post.S[0].nm[0]==='봄 구단'&&JSON.stringify(s.g)===score,'PS 이름/점수 변경');});
T('[래더계약검수 #982] 옛 이름 자료가 없는 이력 pack은 추정하거나 상태 난수를 바꾸지 않는다',()=>{const L=lc982Setup();ulRunSeries(L);delete L.series[0].nm;const raw=JSON.stringify(G),rng=__rngState(),a=JSON.stringify(ulLgPack(L)),b=JSON.stringify(ulLgPack(L));ok(a===b&&JSON.stringify(G)===raw&&__rngState()===rng,'옛 pack 조회 변경');ok(!JSON.parse(a).series[0].nm,'옛 이름 추정');});
T('[래더계약검수 #982] 경기 이름 이력 사본은 원본과 분리되고 본게임 난수를 소비하지 않는다',()=>{const L=lc982Setup(),rng=__rngState();const s=ulRunSeries(L),pack=ulLgPack(L);ok(__rngState()===rng,'정규 경기 본게임 난수 소비');ok(Array.isArray(s.nm),'원본 당시 이름');const n=s.nm[0];pack.series[0].nm[0]='다른 사본';ok(s.nm[0]===n,'pack 이름 alias');});
T('[래더계약검수 #991] 실제 서버 확인 키는 전송 덱과 세계 자동 참가를 구분하고 본 상태를 바꾸지 않는다',()=>{const L=lc982Setup(),U=uld();let enabled=true,intent='0';const UL_INTENT_K='fo-ul-auto-intent',ulLs=()=>intent,ulAutoOn=()=>enabled,key=eval(__contracts978KeySrc());const k=key(U),raw=JSON.stringify(G),rng=__rngState();ok(key(U)===k&&JSON.stringify(G)===raw&&__rngState()===rng,'동일 키/조회 부작용');U.deck.e.h='오래된 hash';ok(key(U)===k,'저장 hash를 실제 payload보다 신뢰');const e=JSON.parse(JSON.stringify(U.deck.e));[e.ln[0],e.ln[1]]=[e.ln[1],e.ln[0]];ok(key(U,e)!==k,'실제 수정 payload 무시');const w=G.wid;G.wid=w+'-다른세계';ok(key(U)!==k,'다른 세계 무시');G.wid=w;U.deck.auto=1;const on=key(U);enabled=false;ok(key(U)!==on,'자동 참가 끄기 무시');enabled=true;const prior=key(U);intent='새참가의사';ok(key(U)!==prior,'같은 ON의 새 참가 의사 무시');});


