T('[검수 11-18 #987 부분·완료] 옛전체와부분coverage는 전체순위를만들지 않고 관측실책만 보존하며 정상27경기0은0·1위다 [래더기록검수]',()=>{const L=UR987_WORLD();ulLgMig(L);L.series.push({id:5,r:2,a:0,b:1,g:[[1,0,9],[0,1,9],[2,1,9]]});L.next=6;L.te[1]=2;const s=JSON.stringify(L),r=__rngState(),partial=ulTeamStats(L);ok(partial.T.every(x=>x.e==null)&&partial.rank.e.every(x=>x==null)&&partial.lg.e==null,'부분 legacy 실책을 시즌전체 순위로 단정');ok(partial.T[0].eObserved===0&&partial.T[1].eObserved===2&&partial.T[0].eGames===3&&partial.T[2].eObserved==null,'관측0·관측2·미관측 구분');ok(JSON.stringify(L)===s&&__rngState()===r,'coverage 조회가 저장/RNG 변경');const full={...L,series:Array.from({length:9},(_,round)=>L.series.slice(0,5).map((x,i)=>({...x,id:round*5+i,r:round+1}))).flat(),next:45};delete full.te;delete full.teP;ulLgMig(full);ok(full.teP===45&&ulTeamStats(full).T.every(x=>x.e==null),'옛 완료27경기를0실책으로 단정');const modern={...full,te:Array(10).fill(0)};delete modern.teP;const known=ulTeamStats(modern);ok(known.T.every(x=>x.e===0&&x.eGames===27)&&known.rank.e.every(x=>x===1)&&known.lg.e===0,'정상27경기 실제0실책 소실');});
