function ld989Html(x){const now=Date.now,at=now();try{Date.now=()=>at+15*864e5;return x.ui.ulSeasonEndHtml(x.U);}finally{Date.now=now;}}
function ld989(rank,champ){fresh();ulSetDeck(cupEntryNow({name:'결산검수'}),'now');const L=ulMakeLeague({seed:989}).league,order=Array.from({length:10},(_,i)=>i).filter(i=>i!==0);order.splice(rank-1,0,0);L.series=L.sched.map(s=>({r:s.r,a:s.a,b:s.b,g:Array.from({length:3},()=>order.indexOf(s.a)<order.indexOf(s.b)?[3,1]:[1,3]),bx:[]}));L.next=L.sched.length;const seeds=ulStand(L).slice(0,4).map(s=>s.key),p1=[seeds[0],seeds[3]],p2=[seeds[1],seeds[2]],w1=p1.includes(0)?0:p1[0],w2=p2.includes(0)?0:p2[0],other=w1===0?w2:w1,winner=champ?0:other,runner=champ?other:0,final=[w1,w2].sort((a,b)=>seeds.indexOf(a)-seeds.indexOf(b)),series=(id,k,p,w,best)=>({id,k,a:p[0],b:p[1],best,w,g:Array.from({length:best===5?3:2},()=>w===p[0]?[3,1]:[1,3]),bx:[]});L.post={seeds,S:[series('SF1','s',p1,w1,3),series('SF2','s',p2,w2,3),series('F','f',final,winner,5)],next:3,champ:winner,runner};const result=ulFinish(),U=G.uld;ok(result.rank===rank&&result.ps.my===(champ?'c':'r'),'실제리그결산원자료 '+JSON.stringify({rank:result.rank,ps:result.ps.my}));delete U.seenS;return {U,result,ui:eval(__ladder988Ui())};}
