function F993Base(){__seed(993001);_achMem=achMetaFix(null);_achChamp0={};buildWorld({lite:true});claimTeam(6);G.day=G.cal.open+50;G.entryY=G.year;G.contract=null;G.evs=[];G.evf=[];G.evlog=[];G.fmarket=[];G.moves=[];G.stops=[];G.mail=[];const t=G.user;for(const p of Object.values(G.players))if(p.team===t&&p.foreign)p.team=null;G.sea.repl[t]=0;G.sea.fspend[t]=0;const mk=(isP,teamId=t)=>{const p=newForeign('용병',{isP,team:teamId,age:28});p.team=teamId;p.sal=p.ask=500;p.yrs=1;p.fy=G.year;p.rsy=0;p.adapt=50;delete p.opt;delete p.fRel;delete p.fCtY;delete p.fMulti;p.injOut=0;setOvr(p,55);return p;};const o=mk(true),a=mk(true),q=mk(false,null);o.injOut=60;o.injHist=[{id:'long993',d:G.day,days:60,ret:G.day+60,n:'장기 부상'}];G.fmarket=[q.id];return {t,o,a,q,mk};}
function F993Temp(){const f=F993Base();const err=signTempForeign(f.t,f.o.id,f.q.id);ok(!err&&f.q.ftmp&&f.o.frehab===f.q.id,'준비: 실제 타자 임시 등록 '+err);return f;}
const F993Players=f=>JSON.stringify({o:G.players[f.o.id],q:G.players[f.q.id],fsp:G.sea.fspend[f.t],repl:G.sea.repl[f.t]});
T('[외국인대체추가검수 #993 유형] 옛 원 선수 복귀 카드는 새 투수 영입 뒤 구성 초과면 양 선수 계약을 보존하고 거절한다',()=>{const f=F993Temp(),{t,o,q,mk}=f;o.injOut=0;fTmpDaily();const e=G.evs.find(e=>!e.done&&e.k==='ftmp'&&e.data.qid===q.id);ok(e,'준비: 실제 복귀 결정');const c=mk(true,null);G.fmarket.push(c.id);ok(!signForeign(t,c.id),'준비: 실제 새 투수 합법 영입');ok(!fYBMixErr(t,foreignOf(t).filter(p=>p.foreign==='용병'))&&fBackErr(o,q),'준비: 현재 합법/복귀 투수3명 초과');const raw=F993Players(f);evPick(e.id,0);ok(F993Players(f)===raw&&G.players[q.id]===q&&o.frehab===q.id,'옛 복귀 카드가 대체 타자를 내보내고 원 투수도 잠금');});
T('[외국인대체추가검수 #993 총액] 옛 원 선수 복귀 카드는 총액이 바뀌어 한도를 넘으면 양 선수와 비용을 바꾸지 않는다',()=>{const f=F993Temp(),{t,o,q,a}=f;o.injOut=0;o.sal=900;q.sal=100;fTmpDaily();const e=G.evs.find(e=>!e.done&&e.k==='ftmp'&&e.data.qid===q.id);ok(e,'준비: 복귀 결정');a.sal=fCap(t)-o.sal+100;ok(!fTmpFitErr(t,foreignOf(t),null)&&fBackErr(o,q),'준비: 현재 합법/복귀 총액 초과');const raw=F993Players(f);evPick(e.id,0);ok(F993Players(f)===raw&&G.players[q.id]===q&&o.frehab===q.id,'복귀 총액 초과가 대체 계약과 비용을 변경');});
T('[외국인대체추가검수 #994] 긴 유효 재활 기록 뒤 짧은 겹부상이 추가돼도 6주 자격 안내 실제 계약을 유지한다',()=>{const {t,o,q}=F993Base();o.injOut=38;o.injHist=[{id:'long994',d:G.day-4,days:42,ret:G.day+38,n:'기존 장기 부상'},{id:'short994',d:G.day,days:4,ret:G.day+4,n:'짧은 겹부상'}];const dx=fTmpDx(o),why=fTmpErr(t,o,q),notice=fTmpNotify(o),err=signTempForeign(t,o.id,q.id);ok(dx>=42&&!why&&notice&&!err&&q.ftmp&&G.mail.some(m=>m.ref===o.id),'유효42일 진단을 마지막4일 기록으로 무시 '+JSON.stringify({dx,why,notice,err,contract:!!q.ftmp}));});
T('[외국인대체추가검수 #995] 2048년 부상 대체 월 상한 안내는 실제 경제지수 계약액과 일치한다',()=>{const {t,o,q}=F993Base();G.year=2048;G.cal=buildCalendar(G.year);G.day=G.cal.open+50;G.ps=null;G.ecoFix=15873;for(const p of [o,q])p.fy=G.year;o.injOut=60;o.injHist=[{id:'long995',d:G.day,days:60,ret:G.day+60,n:'장기 부상'}];q.ask=q.sal=fNewCap();ok(fTmpNotify(o),'준비: 실제 안내');const msg=G.mail.find(m=>m.ref===o.id),err=signTempForeign(t,o.id,q.id);ok(!err&&q.ftmp,'준비: 실제 계약 '+err);ok(q.ftmp.fee===Math.round(F_TMP_MON*fEcoK())&&msg.body.includes(money(q.ftmp.fee)),'안내/실제 월액 불일치 '+JSON.stringify({k:fEcoK(),fee:q.ftmp.fee,announced:money(F_TMP_MON),actual:money(q.ftmp.fee)}));});
T('[외국인대체추가검수 #996] 단축 정규시즌 뒤 포스트시즌에는 옛 마감 카드로 원 선수 방출이나 정식 전환을 하지 않는다',()=>{const f=F993Temp(),{o,q}=f;G.day=foreignDL()-7;G.cal.end=G.day;fTmpDLWarn();const e=G.evs.find(e=>!e.done&&e.k==='ftmp3'&&e.data.qid===q.id);ok(e,'준비: 실제 마감 카드');G.day++;G.ps={y:G.year,done:false};ok(period()==='post'&&!foreignOpen(),'준비: 일반 신규 계약이 막힌 PS');const raw=F993Players(f);evPick(e.id,0);ok(F993Players(f)===raw&&G.players[o.id]===o&&q.ftmp,'PS 옛 마감 카드가 원 선수를 방출하고 대체 선수를 정식 계약');});
T('[외국인대체정상대조] 구성과 총액이 그대로인 실제 복귀는 원 선수만 등록하고 대체 계약을 한 번 끝낸다',()=>{const {t,o,q}=F993Temp();o.injOut=0;fTmpDaily();const e=G.evs.find(e=>!e.done&&e.k==='ftmp'&&e.data.qid===q.id);ok(e&&!fBackErr(o,q),'준비: 정상 복귀');const rng=__rngState();evPick(e.id,0);ok(G.players[o.id]===o&&!o.frehab&&!G.players[q.id]&&e.done&&__rngState()===rng,'정상 복귀/난수 변화');});
T('[외국인대체정상대조] 단일42일 진단의 재활38일은 현재도 실제 안내와 대체 계약 자격을 유지한다',()=>{const {t,o,q}=F993Base();o.injOut=38;o.injHist=[{id:'normal42',d:G.day-4,days:42,ret:G.day+38,n:'장기 부상'}];ok(fTmpDx(o)===42&&!fTmpErr(t,o,q)&&fTmpNotify(o),'기존 단일 진단 기준');ok(!signTempForeign(t,o.id,q.id)&&q.ftmp,'기존 실제 계약');});
T('[외국인대체정상대조] 2026년 월 상한은 실제 계약140과 안내1.4억이 같다',()=>{const {t,o,q}=F993Base();q.ask=q.sal=fNewCap();ok(fTmpNotify(o),'기존 안내');const m=G.mail.find(m=>m.ref===o.id);ok(!signTempForeign(t,o.id,q.id)&&q.ftmp.fee===140&&m.body.includes(money(q.ftmp.fee)),'2026 월 상한');});
T('[외국인대체정상대조] 8월 단축시즌의 포스트시즌은 일반 신규 외국인 계약부터 차단한다',()=>{const {t,q}=F993Base();G.day=foreignDL()-6;G.cal.end=G.day-1;G.ps={y:G.year,done:false};const raw=JSON.stringify(q),why=signForeign(t,q.id);ok(period()==='post'&&!foreignOpen()&&why&&q.team==null&&JSON.stringify(q)===raw,'기존 일반 계약 PS 사전 검사');});
