  const sr=scoutReport, pt=potTierP, rp=rosterProj, dp=doPick; let got=null; scoutReport=p=>({ofp:p===A?80:60,cur:50}); potTierP=(r,p)=>({n:p===A?1:4}); rosterProj=()=>0; doPick=id=>{ got=id; };
