  G.mpick={y:G.year,mid:m.id,ids:[dom[1].id],back:null,day:G.day}; const eOld={data:{ids:[dom[1].id],mid:m.id}};
  const oldId=m.id; hireMgr(G.mmarket[0].id,2); m=G.mgr[G.user]; ok(m.id!==oldId,'준비 실패: 감독 교체');
