  for(const q of L.slice(4,10)){ blockAdd(q.id,'any'); q.urgent=true; } autoSet('tro',true); G.trades=[]; G.offers=[]; G.autoLog=[]; const m0=(G.mail||[]).length; for(let i=0;i<30;i++)blockDaily();
