T('[검수 11-09zg] 백분위: 그 항목 값이 있는 비교 대상이 15명 미만이면 0이나 50을 찍지 않고 비운다',()=>{ fresh(); const p=playersOf(G.user).find(q=>q.isP), y=G.year, P0=pctPool; try{ pctPool=()=>Array.from({length:131},()=>({velo:null})); ok(pctOf(p,'velo',151,y)===null,'비교 0명인데 '+pctOf(p,'velo',151,y)); pctPool=()=>[{velo:151}].concat(Array.from({length:130},()=>({velo:null}))); ok(pctOf(p,'velo',151,y)===null,'본인 한 명인데 '+pctOf(p,'velo',151,y)); pctPool=()=>Array.from({length:20},(_,i)=>({velo:140+i})); ok(pctOf(p,'velo',151,y)>50&&pctOf(p,'velo',151,y)<65,'충분한 표본 백분위 '+pctOf(p,'velo',151,y)); } finally{ pctPool=P0; } });
