T('[검수 11-09zf] 끝내기 안타의 루타 조정이 타구 지도(타구 분포)에도 같게 남는다',()=>{ fresh(); const T2=G.teams.map(t=>t.id); let wo=0, bad=0;
  for(let i=0;i<400;i++){ const n0={}; for(const p of Object.values(G.players))n0[p.id]=(p.spr&&p.spr.points||[]).length; const g=simGame(G.day,T2[i%10],T2[(i+4)%10],false); for(const [f,...a] of g.W)f(...a); /* 타구 기록은 경기 반영 때 쓴다(검수 11-09zt) */ const L=g.line.h; if(!(L.length>=9&&g.score.h>g.score.a&&L[L.length-1]>0))continue; const r=g.pbp[g.pbp.length-1]; if(!r||typeof r[1]!=='number'||!['1B','2B','3B'].includes(r[3]))continue; const b=G.players[r[1]], P=b&&b.spr&&b.spr.points; if(!P||P.length===n0[b.id])continue; wo++; if(P[P.length-1][1]!==r[3])bad++; }
  ok(wo>0,'준비 실패: 끝내기 안타 없음'); ok(!bad,'타구 지도 결과가 중계와 다른 끝내기 '+bad+'/'+wo); });
