T('[검수 11-09zp] 영구결번은 그 구단에서 단 번호이고 OB 카드에도 표시된다',()=>{ fresh(); const w0=warOf; try{ warOf=()=>9; G.startY=G.year-12; /* 창단 게임: 창단 이후 기록만 우리 구단 경력 */ const old=G.user, to=G.teams.find(t=>t.id!==old).id; G.retNos=[]; const p=playersOf(old).find(q=>!q.isP&&!q.foreign); p.hist=p.hist.filter(h=>h.lvl!=='1군'); p.svc=0; for(let k=1;k<=10;k++)lineFor(p,G.year-k,old,'1군').pa=10; const n0=jno(p);
    p.team=to; const used=teamNos(to,p); let n1=1; while(used.has(n1)||n1===n0)n1++; ok(setPlayerNo(p.id,String(n1))==='','번호 변경 실패'); lineFor(p,G.year,to,'1군').pa=10; retireOut(p,'은퇴');
    const r=G.legends.find(r=>r.pid===p.id); ok(r&&r.canRetNo&&r.no===n0,'결번 후보 번호 '+(r&&r.no)+' 기대 '+n0); const msg=retireNumber('p'+p.id); ok(G.retNos.some(x=>x.no===n0)&&!G.retNos.some(x=>x.no===n1),'다른 구단 번호가 결번: '+msg);
    const ob=G.ob.find(o=>o.fid===p.id); ok(ob&&ob.retNo&&ob.no===n0,'OB 카드 결번 누락'); } finally { warOf=w0; } });
