  o1.injOut=0; fTmpEnd(q1,'원 선수 복귀'); fTmpDaily(); const reg=foreignOf(G.user).filter(x=>x.foreign==='용병'); ok(!(reg.length>=3&&reg.every(x=>x.isP)),'투수 3명 등록: '+reg.map(x=>x.name+(x.isP?'(투)':'(타)')).join(',')); ok(o1.frehab==='hold','원 선수가 재활 명단에 남지 않음');
  const t=G.teams.find(x=>x.id!==G.user&&foreignOf(x.id).some(p=>p.foreign==='용병')); const o=foreignOf(t.id).find(x=>x.foreign==='용병'); o.injOut=60; const q=newForeign('용병',{isP:o.isP,market:true}); for(const k in q.r)q.r[k]=25; roundR(q); G.fmarket.push(q.id);
