T('[검수 11-09zl] 경쟁 제시액: 감당 못 하는 구단은 빠지고 남은 구단 수로만 값이 오른다',()=>{ fresh(); G.fwatch=[]; const [t1,t2]=G.teams.filter(x=>x.id!==G.user); for(const t of [t1,t2])for(const p of foreignOf(t.id))dropP(p.id);
  const q=newForeign('용병',{isP:true,market:true}); for(const k in q.r)q.r[k]=75; roundR(q); delete q.prev; delete q.prev2; /* 지난 리그 기록은 올리기 전 능력으로 만든 것이라 지운다(AI도 기록을 보고 판단: fCandEst) */ q.ask=60*USD; G.fmarket.push(q.id);
  const b1=newForeign('용병',{isP:false,team:t2.id}), b2=newForeign('용병',{isP:false,team:t2.id}); for(const b of [b1,b2]){ b.rsy=0; delete b.opt; } b1.sal=Math.round((F_TOTAL_CAP-q.ask-5)/2); b2.sal=F_TOTAL_CAP-q.ask-5-b1.sal;
  ok(foRivalTeams(q).includes(t2.id)&&foRivalTeams(q).includes(t1.id),'준비 실패: 두 구단이 관심 없음'); const R=foRivals(q); ok(!R.some(r=>r.tid===t2.id),'감당 못 하는 구단이 경쟁자로 남음'); ok(R.some(r=>r.tid===t1.id),'준비 실패');
  for(const r of R){ const want=Math.min(foCap(q),Math.round(q.ask*(1+.07*Math.max(0,R.length-1))*(1+.03*hn('fr'+r.tid,q.id)))); ok(r.g+r.i===want,tshort(r.tid)+' 제시 '+(r.g+r.i)+' ≠ '+want+'(탈락 구단이 값을 올림)'); } });
T('[검수 11-09zl] 보류권: 계약 불가 후보는 AI 상위 칸을 차지하지 않고, 우리만 계약할 수 있는 후보는 관심·몸값이 오르지 않는다',()=>{ fresh(); G.fwatch=[]; G.fmarket=[]; /* 시험 후보끼리만 비교: 상주 외국인 후보군(해외 활성화 3단계)이 생긴 뒤 기록 없는 시험 후보는 종합 추정이 낮아 실제 후보에 밀렸다(규칙 문제 아님) */ const [t,h]=G.teams.filter(x=>x.id!==G.user); for(const p of foreignOf(t.id))dropP(p.id); t.cash=5000;
  const mk=v=>{ const p=newForeign('용병',{isP:true,market:true}); for(const k in p.r)p.r[k]=v; roundR(p); p.ask=60*USD; G.fmarket.push(p.id); return p; }; const X=[mk(80),mk(80),mk(80)]; for(const x of X)foResAdd(x,h.id); const q=mk(78);
  const pk=aiForeignPick(t.id); ok(pk&&!X.includes(pk),'보류권 후보를 영입 대상으로 고름'); ok(foRivalTeams(q).includes(t.id),'계약 불가 후보가 상위 칸을 차지해 경쟁이 숨음');
  const m=mk(78); foResAdd(m,G.user); fwatchToggle(m.id); ok(fInterest(m)===0,'우리 보류권 선수에게 다른 구단 관심 '+fInterest(m)); const a0=m.ask; fBidWeek(); ok(m.ask===a0,'경쟁 제안이 없는데 몸값이 오름 '+a0+' → '+m.ask); });
T('[검수 11-09zl] 같은 날 주전을 방출하면 외국인 후보가 보는 출전 기회도 바로 바뀐다',()=>{ fresh(); const d=depth(G.user); const k=['1B','LF','RF','3B','CF','2B','SS','C'].find(x=>d.ln[x]&&!d.ln[x].foreign); ok(k,'준비 실패'); const p=d.ln[k]; const s0=faCtx().slot[G.user][k];
  releasePlayer(p.id); ok(p.team!==G.user,'준비 실패: 방출 안 됨'); const s1=faCtx().slot[G.user][k]; _faCtx=null; const s2=faCtx().slot[G.user][k]; ok(s1===s2,'방출 전 평가 '+s0+'가 남음: '+s1+' / 새 계산 '+s2); });
T('[검수 11-09zh] 경기 진행과 1군 엔트리: 9명 미만 타순 금지·연기 경기 기록/선발 순번 보존·비상 선발 정원과 오늘 등판·건강한 포수 보호·백업 포수 보호·선발 요청 안내',()=>{ fresh(); simTo(()=>period()==='season'&&G.day>=G.cal.open+3&&ourGameOn(G.day+1)); const U=G.user, ent=()=>playersOf(U).filter(p=>p.e1), fill=()=>{ for(const q of playersOf(U).filter(canUp)){ if(ent().length>=entryLimit())break; q.e1=true; q.upDay=G.day; } };
  /* 1: 엔트리가 꽉 차도 다친 야수를 2군 야수로 바꿔 건강한 야수 9명 */ fill(); const hurt=ent().filter(p=>!p.isP&&!isC(p)).slice(0,6); hurt.forEach(p=>p.injOut=2); ok(ent().filter(p=>!p.isP&&healthy(p)).length<9,'준비 실패: 건강한 야수 9명 이상');
  entryManage(U,false,true); ok(ent().filter(p=>!p.isP&&healthy(p)).length>=9&&ent().length<=entryLimit(),'건강한 1군 야수 '+ent().filter(p=>!p.isP&&healthy(p)).length+'명, 엔트리 '+ent().length);
  { const B=playersOf(U).filter(p=>!p.isP), s0=B.map(p=>[p.injOut,p.downDay]); B.forEach(p=>{ if(p.e1)p.injOut=2; else p.downDay=G.day; }); let err=''; try{ gameSide(U,G.day,false); }catch(e){ err=e.message; } B.forEach((p,i)=>{ p.injOut=s0[i][0]; p.downDay=s0[i][1]; }); ok(err.includes('9명'),'야수 9명 미만인데 경기 준비 통과'); }
  hurt.forEach(p=>p.injOut=0);
  /* 2·3: 상대 선발이 없어 실패한 경기(재시도 포함)는 타구·좌우 기록과 선발 순번을 남기지 않는다 */ { const op=G.teams.find(t=>t.id!==U).id, snap=()=>JSON.stringify([...playersOf(U),...playersOf(op)].map(p=>[p.spr||null,p.spl||null]))+':'+team(U).rot+':'+team(op).rot; const s0=snap(), oP=pickStarter;
    try{ pickStarter=(tid,d,day,ps,o)=>tid===U?null:oP(tid,d,day,ps,o); for(let i=0;i<2;i++){ let thrown=false; try{ simGame(G.day,U,op,false); }catch(e){ thrown=true; } ok(thrown,'선발 없는 경기가 진행됨'); } }finally{ pickStarter=oP; }
    ok(snap()===s0,'실패한 경기의 기록 또는 선발 순번이 남음');
    const r0=team(U).rot||0, g=simGame(G.day,U,op,false); ok((team(U).rot||0)===r0,'경기 저장 전에 순번이 넘어감'); applyGame(G.day,U,op,g,false); ok(team(U).rot===g.S.h.rot&&g.S.h.rot!=null,'저장한 경기의 순번이 반영되지 않음'); }
  /* 4: 비상 선발은 1군 정원을 넘기지 않는다 */ { fill(); const P=ent().filter(p=>p.isP); P.forEach(p=>p.injOut=2); const lim=entryLimit(), n0=ent().length; const c=pickStarter(U,depth(U),G.day,false); const n1=ent().length; P.forEach(p=>p.injOut=0); ok(c&&c.e1&&!P.includes(c),'2군 비상 선발 없음'); ok(n0===lim&&n1<=lim,'비상 선발로 엔트리 '+n0+' → '+n1+'(정원 '+lim+')'); }
  /* 5: 오늘 던진 투수는 비상 선발이 아니다 */ { const [a,b]=ent().filter(p=>p.isP&&healthy(p)); a.lastApp=G.day; b.lastApp=G.day-5; b.lastStart=G.day-5; const c=pickStarter(U,{sp:[],pen:[a,b],start:[]},G.day,false); ok(c===b,'오늘 등판한 투수를 비상 선발로: '+(c&&c.name)); a.lastApp=b.lastApp=null; }
  /* 7: 하나뿐인 백업 포수는 휴식일 대체·대수비로 다른 자리에 쓰지 않는다 */ { for(let g=0;g<3&&!depth(U).bench.some(isC);g++){ const q=depth(U).bench.find(p=>!p.isP&&!isC(p)); if(!q)break; q.pos='C'; } /* 포수가 아예 없는 세계면 첫 전환 선수가 주전 포수가 되므로 벤치에 포수가 생길 때까지(최대 3명, 11-11) */ /* 세계에 따라 포수가 주전 하나뿐이면 벤치 야수 하나를 포수로(준비) */ depth(U).bench.filter(isC).slice(1).forEach(p=>{ p.pos='1B'; }); /* 벤치 포수가 둘 이상인 세계는 하나만 남긴다(준비) */ const d=depth(U), bc=d.bench.filter(isC); ok(bc.length===1,'준비 실패: 벤치 포수 '+bc.length+'명'); const c=bc[0]; d.bench.forEach(p=>{ if(p!==c)for(const k in p.r)if(typeof p.r[k]==='number')p.r[k]=1; }); d.start.forEach(p=>{ if(!isC(p))p.fat=100; }); const bad=s=>s.order.includes(c)&&s.posOf[c.id]!=='C';
    let n=0; for(let i=0;i<25;i++){ const s=gameSide(U,G.day,false); n+=s.order.some(p=>!d.start.includes(p))?1:0; ok(!bad(s),'휴식일 대체로 백업 포수가 '+s.posOf[c.id]); } ok(n,'준비 실패: 휴식일 대체 없음');
    d.start.forEach(p=>p.fat=0); const s=gameSide(U,G.day,false); s.order.forEach(p=>{ if(!isC(p))p.r.def=1; }); c.r.def=99; const m=G.mgr[U]; mgrAttr(m); const dfn=m.dfn; try{ m.dfn=99; defSub(s); }finally{ m.dfn=dfn; } ok(!bad(s),'대수비로 하나뿐인 백업 포수를 '+s.posOf[c.id]+'에'); }
  /* 6: 다친 포수는 포수 보호 인원에 세지 않는다 */ { let C=playersOf(U).filter(isC); while(C.length<3){ const x=playersOf(U).find(p=>!p.isP&&!isC(p)&&!p.e1&&canUp(p)); x.pos='C'; C.push(x); } C=C.slice(0,3); const hi=p=>{ for(const k in p.r)if(typeof p.r[k]==='number')p.r[k]=90; }; C.forEach(p=>{ p.e1=true; p.injOut=0; p.downDay=null; }); hi(C[0]); hi(C[2]); for(const k in C[1].r)if(typeof C[1].r[k]==='number')C[1].r[k]=15; C[2].injOut=2;
    while(ent().length>entryLimit()){ const x=ent().find(p=>!p.isP&&!isC(p)); x.e1=false; } fill(); const back=playersOf(U).find(p=>!p.isP&&!isC(p)&&canUp(p)); ok(back,'준비 실패: 복귀 후보 없음'); hi(back); entryUpgrade(U,[back],'검수'); const hc=ent().filter(p=>isC(p)&&healthy(p)).length; C[2].injOut=0; ok(hc>=2,'복귀 등록으로 건강한 1군 포수 '+hc+'명'); }
  /* 8: 선발 요청을 받아들여도 선발 5명에 못 들면 그렇게 안내한다 */ { const p=ent().find(q=>q.isP&&!depth(U).sp.includes(q)); for(const k in p.r)if(typeof p.r[k]==='number')p.r[k]=20; p.r.sta=99; delete (G.prole||{})[p.id]; const r=proleSet(p.id,'sp'); ok(!depth(U).sp.includes(p)&&p.role==='RP'&&r.includes('계투로 나갑니다'),'선발 5명 밖인데 안내 없음: '+r+' / '+p.role); }
});
T('[검수 11-09zh] 선발 예고와 투수 운용: 다음 선발·계투 전환·세이브 교체·연투 대체·보충 경기·상대 부상 비교·뎁스 조회 무변경·기조 변경·가을 에이스 휴식·더블헤더 등판 수',()=>{ fresh(); simTo(()=>period()==='season'&&G.day>=G.cal.open+3&&ourGameOn(G.day+1)); const U=G.user; G.makeup=[]; const nd=()=>teamGames(U,G.day+1,1)[0].d, act=()=>pickStarter(U,depth(U),nd(),false), pre=()=>projStarters(U,1)[0].sp;
  /* 9: 첫 순번 투수가 어제 구원 등판했으면 예고도 다음 투수 */ { const sp=depth(U).sp; team(U).rot=0; const L0=sp.map(p=>[p.lastApp,p.lastStart]); sp.forEach(p=>{ p.lastStart=nd()-6; p.lastApp=nd()-6; }); sp[0].lastApp=nd()-1; ok(pre()===act()&&pre()!==sp[0],'예고 '+pre().name+' 실제 '+act().name);
  /* 12: 선발 전원이 연투 제한이면 예고도 쉬어 온 불펜 */ sp.forEach(p=>p.lastApp=nd()-1); const a=act(); ok(!sp.includes(a)&&pre()===a,'연투 대체 예고 '+pre().name+' 실제 '+a.name); sp.forEach((p,i)=>{ p.lastApp=L0[i][0]; p.lastStart=L0[i][1]; }); }
  /* 10: 같은 날 계투 전환을 승인하면 예고에서 빠진다 */ { const p=pre(); G.prole=G.prole||{}; G.prole[p.id]={k:'rp',d:G.day,tid:U}; p.role='RP'; ok(pre()!==p,'계투 전환한 투수가 예고 선발에 남음'); delete G.prole[p.id]; }
  /* 11: 같은 날짜의 다른 세이브로 바꾸면 그 세이브 선수로 */ { const p=pre(), G1=G; try{ G=JSON.parse(JSON.stringify(G)); G.players[p.id].name='검수다른이름'; const q=pre(); ok(q===G.players[p.id]&&q.name==='검수다른이름','이전 세이브 선수 객체가 남음'); }finally{ G=G1; } }
  /* 13: 미룬 보충 경기가 다음 날 예고에 먼저 */ { const op=G.teams.find(t=>t.id!==U).id; G.makeup=[{y:G.year,h:U,a:op,d:G.day-1}]; const g=projStarters(U,1)[0]; G.makeup=[]; ok(g.d===G.day+1&&g.mk&&g.op===op,'보충 경기 예고 없음: '+g.d+' / '+(G.day+1)); }
  /* 14: 상대 에이스 부상이 같은 날 전력 비교에 반영 */ { const op=G.teams.find(t=>t.id!==U).id, ace=(leagueSlots(),leagueSlots())[op].SP.ps[0]; ace.injOut=10; const v=leagueSlots()[op].SP.ps; ace.injOut=0; ok(!v.includes(ace),'부상한 상대 에이스가 전력 비교에 남음'); }
  /* 15: 뎁스 조회는 보직을 바꾸지 않는다 */ { const p=depth(U).sp[0]; p.role='RP'; const r0=JSON.stringify(Object.values(G.players).map(q=>q.role||'')); for(const t of G.teams)depth(t.id); ok(JSON.stringify(Object.values(G.players).map(q=>q.role||''))===r0,'뎁스 조회로 보직이 바뀜'); roleSync(U); ok(p.role==='SP','보직 확정에서 선발로 바뀌지 않음'); }
  /* 16: 운영 기조를 바꾸면 그날 투수 운용 값도 새로 */ { G.policy=null; mgrPush(U); setPolicy('youth'); const b=mgrPush(U); G._push=null; ok(mgrPush(U)===b,'기조 변경 뒤 투수 운용 값이 이전 값'); }
  /* 17: 가을야구 에이스 구원은 어제 구원 등판까지 쉰 날로 센다 */ { const P=depth(U).sp, ace=P[0], fs={tid:U,spAll:[ace],sp:P[1],used:new Set()}, d=G.day; ace.lastStart=d-5; ace.lastApp=d-1; ace.lastPc=4; ok(!psAceRelief(fs,8,1,d,{fin:true}),'어제 구원 등판한 에이스가 총력전 불펜 후보'); ace.lastApp=d-5; ok(psAceRelief(fs,8,1,d,{fin:true})===ace,'쉰 에이스가 후보가 아님'); }
  /* 18: 같은 날 두 경기 등판은 두 경기로 */ { const p=playersOf(U).find(q=>q.isP); p.ld=[]; loadLog(p,G.day,25,false); loadLog(p,G.day,30,false); ok(loadText(p).includes('최근 7일 2경기 55구'),loadText(p)); }
});
T('[검수 11-09zr] 복원: 후보가 빈 6월 저장을 같은 내용으로 두 번 열어도 외국인 후보가 같고, 채우기는 다음 날짜 진행에서 한다',()=>{ fresh(); G.day=KD(6,10); ok(foreignOpen(),'준비: 6월에 외국인 시장이 닫힘'); G.fmarket=[]; const s=JSON.stringify(G);
  G=JSON.parse(s); migrateDraft(); const a=JSON.stringify(G.fmarket), na=Object.keys(G.players).length; G=JSON.parse(s); migrateDraft(); const b=JSON.stringify(G.fmarket);
  ok(a===b,'두 번 연 후보가 다름: '+a+' / '+b); ok(Object.keys(G.players).length===na,'복원만으로 선수가 늘어남'); ok(!G.fmarket.length,'복원하자마자 후보를 채움'); refreshFMarket(0); ok(G.fmarket.length>0,'다음 진행에서 채울 후보가 없음'); });
T('[피드백 11-09k] 후보 선수 트레이드 요청: 출전 적은 백업만, 30일·한 해 3번 제한, 시즌 밖은 따로',()=>{ fresh(); G.day=G.cal.open+30; G.sea.rec[G.user].w=15; G.sea.rec[G.user].l=15; const d=depth(G.user);
  const k=Object.keys(d.ln).find(k=>k!=='DH'&&!d.ln[k].foreign), s=d.ln[k]; const b=d.bench.filter(p=>!p.foreign&&!p.ys).sort((x,y)=>ovr(x)-ovr(y))[0]; /* 가장 약한 백업: 주전 자리로 옮겨도 주전을 밀어내지 않게 */ ok(s&&b,'준비 실패'); for(const p of playersOf(G.user)){ initPers(p); p.pers.amb=5; }
  Object.assign(b,{pos:k,age:28,mor:50,injOut:0,mil:null,tLog:[],listed:false}); b.hist=(b.hist||[]).filter(h=>h.y!==G.year); Object.assign(b.pers,{amb:16,loy:10,temp:10}); s.pers.amb=16; s.mor=40;
  const was=treqCands().includes(b); b.hist.push({y:G.year,lvl:'퓨처스',g:22,pa:90,ab:78,h:30,d:7,tr:1,hr:5,bb:10,hbp:1,sf:1}); /* 2군에서 잘 치는 백업 */
  ok(isRegular(b)===false&&treqCands().includes(b),'자격 있는 백업이 후보가 아님 '+was); ok(!treqCands().includes(s),'주전이 후보'); ok(treqCands().every(p=>!isRegular(p)&&!p.foreign),'주전·외국인 포함');
  b.injOut=5; ok(!treqCands().includes(b),'부상 선수가 후보'); b.injOut=0; b.tLog=[{y:G.year,d:G.day-10,f:0,t:G.user}]; ok(!treqCands().includes(b),'막 데려온 선수가 후보'); b.tLog=[]; b.mor=80; ok(!treqCands().includes(b),'기분 좋은 선수가 후보'); b.mor=50;
  G.treqLog={y:G.year,n:1,last:G.day-10}; ok(EVH.treq.check()==null,'30일 안에 또 나옴'); G.treqLog={y:G.year,n:3,last:G.day-60}; ok(EVH.treq.check()==null,'한 해 3번 넘음'); G.treqLog={y:G.year,n:1,last:G.day-40}; ok(EVH.treq.check()===b,'제한이 풀렸는데 안 나옴');
  const n0=G.evs?G.evs.length:0; treqWeek(); ok((G.evs?G.evs.length:0)===n0,'시즌 중 treqWeek가 따로 사건을 만듦(evWeek 몫)');
  EVH.treq.make(b); const e=evOpen().find(x=>x.k==='treq'); ok(e&&e.data.pid===b.id&&b.treq&&!b.treq.done,'사건 없음'); ok(G.treqLog.n===2&&G.treqLog.last===G.day,'제한 기록 안 됨'); ok(/단장실을 찾아왔습니다/.test(e.sit)&&/트레이드를 생각해/.test(e.sit),'시즌 문구 '+e.sit); ok(!e.data.ks.includes('farm'),'28세에게 2군 선택지'); ok(e.opts[e.def].l.includes('기다려'),'기본안이 거절이 아님');
  b.treq.done=true; ok(!treqCands().includes(b),'같은 선수가 곧바로 또 요청'); G.day+=121; G.sea.rec[G.user].w=60; G.sea.rec[G.user].l=60; ok(treqCands().includes(b)===treqLowPT(b,G.year,120),'넉 달 뒤에도 다시 못 함');
  G.day=G.cal.end+20; ok(period()==='off','스토브리그 준비 실패'); delete b.treq; EVH.treq.make(b); const e2=G.evs[G.evs.length-1]; ok(/쉬는 기간/.test(e2.sit)&&/지난 시즌/.test(e2.sit),'시즌 밖 문구 '+e2.sit); });
T('[카페 11-17 신인 트레이드 요청] 지난 시즌 가을에 지명돼 1월에 입단한 신인은 지난 시즌 출전으로 트레이드를 요청하지 않는다',()=>{ fresh(); G.day=G.cal.end+20; ok(period()==='off','준비 실패: 스토브리그');
  const y=G.year; const b=depth(G.user).bench.filter(p=>!p.foreign&&!p.ys).sort((x,z)=>ovr(x)-ovr(z))[0]; ok(b,'준비 실패'); for(const p of playersOf(G.user)){ initPers(p); p.pers.amb=5; }
  Object.assign(b,{age:23,mor:50,injOut:0,mil:null,tLog:[],listed:false}); delete b.treq; Object.assign(b.pers,{amb:16,loy:10,temp:10}); b.hist=(b.hist||[]).filter(h=>h.y!==y); b.hist.push({y,lvl:'퓨처스',g:22,pa:90,ab:78,h:30,d:7,tr:1,hr:5,bb:10,hbp:1,sf:1});
  const base=treqCands().includes(b); b.draft={y,r:1,n:3}; b.joinY=y+1; ok(!treqCands().includes(b),'그해 가을 지명·다음 해 입단 신인이 후보');
  G.day=dnum(y+1,1,2); ok(!treqCands().includes(b),'1월 입단 직후 신인이 지난 시즌 출전으로 후보');
  b.draft={y:y-1,r:1,n:3}; b.joinY=y; G.day=G.cal.end+20; ok(treqCands().includes(b)===base,'지난해 지명 선수는 예전처럼 판정되어야 함'); });
T('[사용자 11-12] 선수 인격체: 불만은 기억되고, 열기가 차면 언론 플레이 → 트레이드 요구 → 묵살하면 훈련 불참', ()=>{ fresh(); G.day=G.cal.open+40; const d=depth(G.user); const p=d.start.find(q=>!q.foreign); ok(p,'준비 실패'); initPers(p); Object.assign(p.pers,{amb:17,temp:16,loy:5,pro:6}); p.grv=null;
  grvAdd(p,'pt',8); grvAdd(p,'prom',6); ok(grvHeat(p)>=14,'성격이 불만을 키우지 않음 '+grvHeat(p)); const h0=grvHeat(p); grvCut(p,.88); ok(grvHeat(p)<h0,'불만이 잊히지 않음');
  G.evs=[]; pdStatement(p); const e1=G.evs.find(e=>e.k==='pmed'&&!e.done); ok(e1,'언론 플레이 결정이 생기지 않음'); ok((G.news||[]).some(n=>n.t.includes(p.name)),'기사가 없음');
  const m0=p.mor; evPick(e1.id,e1.data.ks.indexOf('rebut')); ok(p.mor<m0&&(p.grv.crit||0)>=4,'공개 반박이 기억(체면)으로 남지 않음');
  grvAdd(p,'pt',10); p.pd={st:1,d:G.day-30}; G.evs=[]; pdDemand(p); const e2=G.evs.find(e=>e.k==='pdem'&&!e.done); ok(e2,'트레이드 요구 결정이 없음'); ok(EV_KEY.has('pdem'),'트레이드 요구가 핵심 결정이 아님');
  evPick(e2.id,e2.data.ks.indexOf('wait')); const f=G.evf.find(x=>x.k==='pdem'); ok(f,'묵살 후속이 없음'); EVH.pdem.follow(f.data,G.user); ok(p.boy>G.day,'묵살했는데 시위로 번지지 않음'); ok(!p.e1,'시위 중인데 1군 등록');
  ok(!canUp(p),'시위 중인데 콜업 가능'); const e3=G.evs.find(e=>e.k==='pboy'&&!e.done); ok(e3,'시위 대응 결정이 없음'); evPick(e3.id,e3.data.ks.indexOf('give')); ok(!(p.boy>G.day)&&p.listed,'요구를 들어줬는데 복귀·명단 등록 안 됨'); });
T('[사용자 11-12] 트레이드 요구 뒤 받은 출전 약속이 깨지면 바로 시위로 번진다, 다른 구단은 핵심이 아니면 싸게 내놓는다', ()=>{ fresh(); G.day=G.cal.open+40; const d=depth(G.user); const p=d.bench.find(q=>!q.foreign&&!q.ys)||d.start.find(q=>!q.foreign); initPers(p); p.pdProm=true; G.evs=[]; pdPromBroken(p); ok(p.boy>G.day,'깨진 약속이 시위로 번지지 않음'); ok((p.grv.prom||0)>=6,'깨진 약속을 기억하지 않음');
  const t=G.teams.find(x=>x.id!==G.user); const q=playersOf(t.id).filter(x=>!x.foreign&&!x.ys&&!pdCore(x)&&!hasNtc(x))[0]; ok(q,'준비 실패(타 구단)'); pdAiReact(q,2); ok(q.aiListed&&q.aiUrg,'핵심이 아닌 불만 선수를 급매로 내놓지 않음');
  const c=playersOf(t.id).find(x=>!x.foreign&&pdCore(x)&&!hasNtc(x)); if(c){ for(let i=0;i<20;i++){ delete c.aiListed; delete c.aiUrg; c.promise=null; pdAiReact(c,2); if(c.aiListed)break; } ok(!c.aiUrg,'핵심 선수를 급매로 내놓음'); } });
T('[사용자 11-12] 1군을 원하는 2군 선수 목록(면담 안건용)과 감독-선수 갈등 결정', ()=>{ fresh(); G.day=G.cal.open+40; const L=playerWantsUp(G.user); ok(Array.isArray(L),'목록 함수 없음'); ok(L.every(x=>x.p&&!x.p.e1&&typeof x.weeks==='number'&&x.t),'목록 항목 모양이 다름');
  const p=playersOf(G.user).find(q=>!q.foreign&&!q.e1&&!q.ys&&healthy(q)&&!isAway(q)&&!q.prospect); if(p){ initPers(p); p.pers.amb=15; p.downDay=null; p.hist=(p.hist||[]).filter(h=>h.y!==G.year); p.hist.push({y:G.year,lvl:'퓨처스',g:30,pa:120,ab:100,h:38,d:9,tr:1,hr:6,bb:16,hbp:1,sf:1,outs:p.isP?120:0,er:p.isP?10:0}); const w=wantUp(p); if(w&&!p.isP)ok(playerWantsUp(G.user).some(x=>x.p===p),'1군 원하는 선수가 목록에 없음'); }
  const m=G.mgr[G.user]; ok(m,'감독 없음'); const s=d=>{ const q=depth(G.user).start.find(x=>!x.foreign); return q; }; const q=s(); initPers(q); G.evs=[]; EVH.mpcf.make(q); const e=G.evs.find(x=>x.k==='mpcf'); ok(e,'감독-선수 갈등 결정이 없음'); const r0=m.rel; evPick(e.id,e.data.ks.indexOf('mgr')); ok(m.rel>r0,'감독 편을 들었는데 감독 관계가 그대로'); });
T('[사용자 11-12] 외국인 KBO 적합도(숨김): 넓은 분포, 적응이 높으면 부진 폭이 준다, 태업은 경기력을 깎는다',()=>{ fresh();
  const L=[]; for(let i=0;i<400;i++){ const p={foreign:'용병'}; L.push(fKfit(p)); } const flop=L.filter(x=>x<-2).length/400, over=L.filter(x=>x>1.5).length/400;
  ok(flop>=.28&&flop<=.45,'부진형 비율 '+flop); ok(over>=.12&&over<=.3,'기대 이상 비율 '+over);
  const p=foreignOf(G.user).find(x=>x.foreign==='용병'); ok(p,'준비 실패'); p.kfit=-4; p.adapt=50; const b0=fBoost(p); p.adapt=85; const b1=fBoost(p); ok(b1>b0&&b1<0,'적응이 높아도 부진 폭이 줄지 않음 '+b0+' '+b1);
  p.fslk={until:G.day+10,b:-3}; ok(fBoost(p)<b1-11,'태업이 경기력에 안 들어감'); delete p.fslk; delete p.kfit; });
T('[사용자 11-12] 외국인 사건: 우리 선수는 결정, 귀국 휴가·꾀병 휴식은 결장, 방출은 방출 처리',()=>{ fresh(); G.day=G.cal.open+40;
  const p=foreignOf(G.user).find(x=>x.foreign==='용병'); ok(p,'준비 실패'); initPers(p);
  fDramaUser(p,'home'); const e=G.evs.find(x=>x.k==='fdrama'&&!x.done); ok(e&&e.data.keys.includes('leave'),'귀국 결정이 없음');
  evPick(e.id,e.data.keys.indexOf('leave')); ok(p.fLeave>G.day&&!healthy(p),'귀국 휴가인데 출전 가능');
  p.fLeave=0; fDramaUser(p,'fake'); const f=G.evs.find(x=>x.k==='fdrama'&&!x.done&&x.data.t==='fake'); evPick(f.id,f.data.keys.indexOf('rest')); ok(!healthy(p),'휴식인데 출전 가능'); p.fLeave=0;
  fDramaUser(p,'slack'); const s=G.evs.find(x=>x.k==='fdrama'&&!x.done&&x.data.t==='slack'); evPick(s.id,s.data.keys.indexOf('release')); ok(!G.players[p.id]||G.players[p.id].team!==G.user,'방출했는데 남아 있음'); });
T('[사용자 11-12] 외국인 사건: 다른 구단은 AI가 처리하고 소식으로, 같은 선수는 한 해 한 번',()=>{ fresh(); G.day=G.cal.open+40; const t=G.teams.find(x=>x.id!==G.user&&foreignOf(x.id).some(q=>q.foreign==='용병'))||G.teams.find(x=>x.id!==G.user); let p=foreignOf(t.id).find(x=>x.foreign==='용병'); if(!p){ p=newForeign('용병',{isP:true}); p.team=t.id; p.fy=G.year; } ok(p,'준비 실패');
  const w0=(G.wire||[]).length; fDramaAI(p,'clash'); ok((G.wire||[]).length>w0,'소식이 없음'); p.fdY=G.year; const r0=Math.random; Math.random=()=>0; try{ fDramaWeekly(); }finally{ Math.random=r0; } ok(!(G.evs||[]).some(e=>e.k==='fdrama'&&e.data.pid===p.id),'다른 구단 선수가 우리 결정으로'); });
T('[피드백 11-09k] 후보 선수 트레이드 요청: 선택지마다 효과와 후속 판정',()=>{ fresh(); G.day=G.cal.open+30; G.sea.rec[G.user].w=15; G.sea.rec[G.user].l=15; const d=depth(G.user); const b=d.bench.find(p=>!p.foreign&&!p.ys); initPers(b); Object.assign(b,{age:27,mor:50}); b.pers.temp=10; const m=G.mgr[G.user];
  const go=(key,o)=>{ delete b.listed; delete b.promise; delete b.treq; EVH.treq.make(b,o&&o.hard); const e=G.evs[G.evs.length-1]; const i=e.data.ks.indexOf(key); ok(i>=0,'선택지 없음 '+key); const m0=b.mor; evPick(e.id,i); return {e,dm:b.mor-m0}; };
  let r=go('list'); ok(b.listed&&b.treq.done&&r.dm===6,'명단 올리기: 명단 '+b.listed+' 기분 '+r.dm);
  const rel0=m.rel; r=go('promise'); ok(b.promise&&r.dm===4&&m.rel===Math.max(0,rel0-1),'기회 건의: 약속 '+!!b.promise+' 기분 '+r.dm); const f=G.evf.find(x=>x.k==='treq'&&x.data.c==='promise'); ok(f&&f.day===G.day+32,'후속 예약 없음');
  EVH.treq.follow(f.data,G.user); ok(G.evf.some(x=>x.k==='treq'&&x.day===G.day+7&&x!==f),'약속 판정 전인데 미루지 않음'); G.evf=[]; delete b.promise;
  const nE=G.evs.length; const gotH={y:G.year,lvl:'1군',t:G.user,pa:30,outs:30,g:10}; b.hist=(b.hist||[]).concat([gotH]); EVH.treq.follow(f.data,G.user); b.hist=b.hist.filter(h=>h!==gotH); ok(G.evs.length===nE,'기회를 얻었는데 다시 요청'); /* 약속 뒤 우리 구단 1군 30타석(투수 30아웃·10경기)을 실제 기록으로 더한다. 기준을 음수로 두던 옛 방식은 #744·#747(21833c1f) 뒤 기준이 0 아래로 내려가지 않아 쓸 수 없다 */
  EVH.treq.follow(f.data,G.user); const h=G.evs[G.evs.length-1]; ok(G.evs.length===nE+1&&h.data.hard&&/두 번째/.test(h.title)&&/달라진 게 없었습니다/.test(h.sit),'기회를 못 얻었는데 다시 요청하지 않음');
  b.mor=50; r=go('wait'); ok(r.dm===-5&&b.treq.done&&b.treqNo===1,'거절 기분 '+r.dm); const o=playersOf(G.user).find(q=>q!==b&&!isRegular(q)&&!q.foreign); initPers(o); o.pers.amb=15; o.mor=50; b.mor=50; r=go('wait',{hard:true}); ok(r.dm===-9,'두 번째 강한 요청 거절 '+r.dm); ok(o.mor===48,'거듭 거절해도 다른 후보 동요 없음 '+o.mor);
  const w=G.evf.filter(x=>x.k==='treq'&&x.data.c==='wait'); ok(w.length===2,'거절 후속 없음'); b.mor=60; const nw=(G.news||[]).length; EVH.treq.follow(w[0].data,G.user); ok((G.news||[]).length===nw,'기분이 풀렸는데 기사');
  b.age=23; b.mor=50; const fs=seasonTotal(b,G.year,'퓨처스')||{}; r=go('farm'); ok(r.dm===3,'2군 약속 기분 '+r.dm); const ff=G.evf.find(x=>x.k==='treq'&&x.data.c==='farm'); ok(ff&&ff.data.g===(fs.g||0),'2군 후속 없음'); const m1=b.mor; EVH.treq.follow(ff.data,G.user); ok(b.mor===m1-5,'2군에서 못 뛰었는데 실망 없음');
  b.listed=false; delete b.treq; EVH.treq.make(b); const e3=G.evs[G.evs.length-1]; const tm=otherT(); b.team=tm; ok(/떠/.test(evPick(e3.id,0)),'떠난 선수에게 결정 적용'); });
T('[검수 11-09zw] 자매구단 코치 연수: 이직 전 연수도 귀국하고, 이적한 코치도 성장하며, 연수 중 세부 훈련은 빈자리',()=>{ fresh(); const S=sisInit(); for(const k in S.p)delete S.p[k]; const jp=OCL.find(c=>c.c==='jp'); S.p[jp.id]={tid:G.user,y:G.year,d:G.day}; G.day=dnum(G.year,11,5);
  const A=G.user, CA=G.coach[A]; const ra=CKEYS.find(k=>CA[k]); const ca=CA[ra]; ca.sk=60; const ya=cAb(ca).yng??45; ok(sisCoachSend(jp.id,ra)==='','첫 연수 실패'); ok(trnCoachV(ca,A,CDOM[ca.role][0])===45,'연수 중인데 세부 훈련에 반영 '+trnCoachV(ca,A,CDOM[ca.role][0]));
  const B=G.teams.find(t=>t.id!==A).id; G.user=B; S.p[jp.id].tid=B; const rb=CKEYS.find(k=>G.coach[B][k]&&k!==ra)||CKEYS.find(k=>G.coach[B][k]); const cb=G.coach[B][rb]; ok(sisCoachSend(jp.id,rb)==='','새 구단 연수 실패');
  const T3=G.teams.find(t=>t.id!==A&&t.id!==B).id; G.coach[A][ra]=null; G.coach[T3][ra]=ca; /* 연수 중 이적 */
  G.day=Math.max(S.ct.to,ca.sisAway); sisCoachBack(); ok(ca.sisAway==null&&(cAb(ca).yng??45)>ya&&ca.sk>=60,'전 구단 코치 귀국·성장 없음 '+ya+'→'+cAb(ca).yng+' '+ca.sisAway); /* 성장은 연수 분야(yng)에 */ ok(cb.sisAway==null,'새 구단 코치 귀국 없음'); ok(!(S.ctq||[]).length,'끝난 연수가 남음'); });
T('[검수 11-09zw] 코치 시장: 사임한 전 구단도 월간 영입, 우선 협상 후보 보호, 관심 구단은 자격 있는 곳만, 63세 재영입 안내',()=>{ fresh(); G.day=dnum(G.year,2,1); /* 비시즌이지만 AI끼리 코치 빼 가기(11~1월)가 없는 달: 다른 구단 자리가 비는 일 없이 전 구단 영입만 본다 */ const me=G.user; G.unemp=true;
  for(const t of G.teams){ if(t.id===me)continue; const p=G.coach[t.id].pc||(G.coach[t.id].pc=mkCoach('pc')); p.sk=90; p.dv=90; } /* 다른 구단 자리가 비어 있으면 그 구단이 먼저 데려간다: 모두 채워 둔다 */ G.coach[me].pc=null; const c=mkCoach('pc'); c.sk=70; c.dv=70; c.sal=100; c.age=50; G.cmarket=[c]; let n=0; while(G.cmarket.includes(c)&&n++<40)cmAiMonthly(); ok(G.coach[me].pc===c,'전 구단이 월간 영입에서 빠짐');
  G.unemp=false; G.coach[me].pc=null; const d=mkCoach('pc'); d.sk=70; d.dv=70; d.sal=100; d.age=66; ok(!cmRivals(d).length,'66세 코치에 관심 구단'); d.age=50; for(const t of G.teams){ const p=G.coach[t.id].pc; if(p&&t.id!==me){ p.sk=50; p.dv=50; } } const r1=cmRivals(d); ok(r1.length,'준비: 관심 구단'); d.from=r1[0].tid; d.fromY=G.year; ok(!cmRivals(d).some(x=>x.tid===d.from),'방금 내보낸 구단이 관심 구단');
  const e=mkCoach('bc'); e.res=G.user; G.cmarket=[e,...[...Array(95)].map(()=>mkCandCoach('bc'))]; for(let i=0;i<24;i++){ G.cmMonth=null; G.day+=31; coachMarketMonth(); } ok(G.cmarket.includes(e),'우선 협상 후보가 월간 정리에서 빠짐');
  const C=G.coach[me]; const x=mkCoach('hc'), y=mkCoach('pc'); x.age=63; y.age=58; x.yrs=1; y.yrs=1; C.hc=x; C.pc=y; delete x.expN; delete y.expN; delete x.cs; delete y.cs; coachExpNote(); const m=G.mail.find(z=>/올해로 계약이 끝나는 코치/.test(z.subj)); ok(m&&m.body.includes(x.name+'(63세)은(는) 은퇴를 앞둬')&&!m.body.includes(y.name+'(58세)은(는)'),'63세 재영입 안내 '+(m&&m.body)); });
T('[검수 11-09zw] 우선 협상 OB 코치는 AI 빈자리 채용(obAiCoach)으로 데려가지 않는다',()=>{ const {ob,c}=obCoachSetup(); G.coach[G.user].pc=null; c.res=G.user; c.yrs=0; G.cmarket=[c].concat(G.cmarket.filter(x=>x!==c));
  const other=G.teams.find(t=>t.id!==G.user).id; let took=0; for(let i=0;i<200;i++){ const r=obAiCoach(other,'pc'); if(r&&r.ob===ob.id)took++; } ok(!took&&G.cmarket.includes(c),'우선 협상 후보를 AI가 데려감 '+took); });
T('[검수 11-09zw] 스태프 시장: AI 예산은 월초 두 번째 처리·경쟁 입찰에도 적용, 월초 무산 메일, 조회는 난수 없음, 이적 소식 한 줄',()=>{ fresh(); stInit(); G.day=dnum(G.year,11,1);
  const ai=G.teams.filter(t=>t.id!==G.user); const over=t=>{ const L=G.lgStaff[t.id]; const top=[...L.sc].sort((a,b)=>b.skill-a.skill)[0]; top.sal+=stAiPlan(t).payMax; }; ai.forEach(over);
  const p0=ai.map(t=>stAiPay(G.lgStaff[t.id])); for(let i=0;i<20;i++){ stAiMonthly(); stAiStaff(); } ai.forEach((t,i)=>ok(stAiPay(G.lgStaff[t.id])<=p0[i],tshort(t.id)+' 예산 초과 채용 '+p0[i]+'→'+stAiPay(G.lgStaff[t.id])));
  const s=scoutMkt()[0]; s.skill=5; ok(!stInterest(s).length,'예산이 없는 구단이 관심 구단'); const t=ai[0]; s.bid={t:t.id,sal:s.sal,v:999,k:'sc',exp:G.day-1}; stBidExpire(); ok(!G.lgStaff[t.id].sc.includes(s),'예산 초과 경쟁 입찰이 성사됨');
  const L=G.lgStaff[t.id]; L.sc.forEach(x=>x.sal=50); L.an.forEach(x=>x.sal=50); L.sc.splice(4); const s2=scoutMkt().find(x=>x!==s)||s; s2.bid={t:t.id,sal:s2.sal,v:999,k:'sc',exp:G.day-1}; const m0=G.mail.length; stBidSettle(); ok(L.sc.includes(s2),'준비: 월초 경쟁 구단 계약'); ok(G.mail.slice(0,G.mail.length-m0).some(m=>m.subj.includes(s2.name+' 영입 무산')),'월초 확정인데 무산 메일 없음');
  const s3=scoutMkt().find(x=>x!==s&&x!==s2); delete s3._im; delete s3.int; const q={id:'zwq'}; const r0=__rngState(); stInterest(s3); stInterest(s3); stAttr(q); ok(__rngState()===r0,'관심 구단 조회가 난수를 씀'); ok(s3.int==null&&s3._im==null,'조회 결과가 후보 데이터에 저장됨');
  const sc=G.scouts[0]; sc.skill=5; G.wire=G.wire||[]; stLeave({k:'sc',id:sc.id,tid:t.id,sal:sc.sal}); ok(L.sc.includes(sc),'준비: 이적'); ok(G.wire.filter(w=>String(w.t).includes(sc.name)).length===1,'이적 소식 줄 수 '+G.wire.filter(w=>String(w.t).includes(sc.name)).length); });
T('[검수 11-09zw] 새 감독대행은 이전 대행의 직원 관계를 물려받지 않는다',()=>{ fresh(); fireMgr(); const s=G.scouts[0]; staffRelAdd(s,'scout',G.user,'mgr',3); ok(staffRel(s,G.user,'mgr')===53,'준비: 관계 상승'); const a=G.mgr[G.user]; G.coach[G.user].hc=null; G.day++; G.mgr[G.user]=mkInterim(); ok(G.mgr[G.user].id!==a.id&&staffRel(s,G.user,'mgr')===50,'새 대행이 관계 53을 물려받음'); });
T('[검수 11-09zx] 로스터와 연봉: AI 정리는 rosterN 기준·육성 한도는 차출 포함·군보류 제외·입대 취소 연봉은 이직과 무관·야인에게 협상 없음·육성 전환은 미계약 종료·복무 중 전환은 정원 검사 제외',()=>{ fresh();
  const op=G.teams.find(t=>t.id!==G.user&&playersOf(t.id).some(p=>p.foreign)).id; const f=playersOf(op).find(p=>p.foreign); ok(f,'준비 실패: 외국인 없음'); f.frehab=-1;
  while(rosterN(op)<ROSTER_MAX)newPlayer({age:22,isP:false,base:35,pot:40,team:op}); while(rosterN(op)>ROSTER_MAX){ const q=domestic(op).find(p=>!p.ys); q.team=null; }
  const out=trimRoster(op,ROSTER_MAX); ok(out.length===0&&rosterN(op)===ROSTER_MAX,'정원 68명인데 정리함: '+out.length+'명, '+rosterN(op)); delete f.frehab;
  const D=domestic(G.user).filter(p=>!p.ys&&!p.mil); ok(D.length>YS_MAX+4,'준비: 국내 선수'); D.slice(0,YS_MAX).forEach(p=>{ p.ys=true; }); const a=D[0]; a.mil={unit:'상무',from:G.day-1,until:G.day+100}; const b=D[1]; b.ntFrom=G.day-1; b.ntAway=G.day+10;
  ok(ysN(G.user)===YS_MAX-1,'군보류는 빼고 차출은 세야 함: '+ysN(G.user)); const c=D[YS_MAX]; c.sal=50; c.faC=false; c.ext=false; delete c.extNext; toYS(c.id); ok(c.ys&&ysN(G.user)===YS_MAX,'군보류 빈자리로 전환 안 됨'); const c2=D[YS_MAX+1]; c2.sal=50; c2.faC=false; c2.ext=false; delete c2.extNext; ok(toYS(c2.id).includes('까지'),'한도 15명을 넘겨 전환됨'); ok(!c2.ys,'전환됨');
  b.ntAway=0; while(rosterN(G.user)<ROSTER_MAX)newPlayer({age:22,isP:false,base:35,pot:40,team:G.user}); ok(period()!=='season'||G.day>=KD(5,1),'준비: 기간'); { const r5=fromYS(a.id); ok(r5.includes('꽉 찼')&&a.ys,'전역일에 69명이 되는데 복무 중 정식 전환 허용(검수 11-17 #415: 전역일 정원은 검사): '+r5); } const e=playersOf(G.user).find(q=>!q.ys&&!q.mil&&!q.foreign&&!D.includes(q)); e.mil={unit:'상무',from:G.day+5,until:G.day+600}; ok(rosterN(G.user)===ROSTER_MAX,'준비: 지금 정원 68명'); /* 지금은 꽉 찼지만 전역일엔 자리가 있다: 현재 정원은 보지 않는다 */ const r6=fromYS(a.id); ok(r6===''&&!a.ys,'복무 중 육성선수가 정원 때문에 전환 거절: '+r6); e.mil=null;
  const mk=()=>{ const p=D.find(q=>!q.ys&&!q.mil&&!q.faC&&q!==c&&!q._t); p._t=1; p.mil=null; p.sal=80; p.newSal=100; return p; };
  const p1=mk(), p2=mk(); G.contract={y:G.year,tid:G.user,done:false,ended:[p1.id,p2.id],foreignEnd:[],foreignDrop:[],released:[],neg:{[p1.id]:{off:80,ask:85,cur:100,st:'open',wk:-1},[p2.id]:{off:80,ask:85,cur:100,st:'open',wk:-1}}};
  ok(enlistNow(p1.id)===''&&enlistNow(p2.id)==='','입대 예약 실패'); ok(p1.mil.neg&&p1.mil.neg.v===100,'예약 전 협상이 선수에게 없음');
  const C=G.contract; p1.sal=p1.newSal; delete p1.newSal; C.done=true; ok(enlistCancel(p1.id)===''&&p1.sal===100,'바로 취소한 연봉: '+p1.sal);
  C.done=false; contractHandOff(G.user); ok(G.contract.done&&!G.contract.neg,'인계로 협상 기록이 닫히지 않음'); ok(enlistCancel(p2.id)===''&&p2.sal===p1.sal,'이직 뒤 취소한 연봉이 다름: '+p2.sal+' vs '+p1.sal);
  c.ys=false; const h=D.find(q=>!q.ys&&!q.faC&&!q.ext&&!q.extNext&&!q._t&&q!==c); h.sal=100; holdStart(h,100,150); ok(toYS(h.id)===''&&!h.hold,'육성 전환 뒤 미계약이 남음'); ok(holdPay(h.id).includes('아닙니다')&&h.sal<=MIN_SAL,'육성 전환 뒤 요구액 계약: '+h.sal);
  G.contract=null; G.unemp={y:G.year,since:G.day,from:G.user,k:'resign'}; contractStart(); ok(G.contract.ended.length===0&&G.contract.foreignEnd.length===0,'야인에게 전 구단 협상이 열림'); ok(domestic(G.user).every(p=>p.newSal==null),'전 구단 선수가 협상 중으로 남음');
  const L=domestic(G.user).filter(p=>!p.ys).slice(0,40); L.forEach(p=>{ p.age=22; p.mil=null; setOvr(p,35); }); milNewYear(); ok(L.some(p=>p.mil&&p.mil.unit==='현역'),'야인 기간에 전 구단만 자동 입대를 건너뜀'); G.unemp=null;
  const s=domestic(G.user).find(p=>!p.ys&&!p.mil&&p.age<=27); ok(s,'준비 실패: 미필'); s.mil={app:'jun'}; toFree(s,'방출',0,true); ok(!(s.mil&&s.mil.app),'방출 뒤에도 상무 지원이 남음'); });
T('[검수 11-09zx] 병역과 1·2군 운영: 전역 당일 엔트리·건강한 야수 9명 보호·당일 말소 투수 퓨처스·2군 리포트·육성 약속 보너스·미계약 보유 사유',()=>{ fresh(); simTo(()=>period()==='season'&&G.day>=G.cal.open+3&&entryOn());
  const F=playersOf(G.user).filter(x=>x.e1&&!x.isP&&healthy(x)); ok(F.length>=9,'준비: 1군 야수'); F.slice(9).forEach(x=>{ x.e1=false; x.downDay=G.day; }); playersOf(G.user).filter(x=>!x.isP&&!x.e1).forEach(x=>{ x.downDay=G.day; });
  while(playersOf(G.user).filter(x=>x.e1).length<entryLimit()){ const q=playersOf(G.user).find(x=>x.isP&&!x.e1&&canUp(x)); if(!q)break; q.e1=true; }
  const r=reqEntry(F[0].id,false); ok(F[0].e1&&r.includes('9명'),'건강한 야수 8명으로 말소됨: '+r);
  const v=Object.values(G.players).find(x=>x.team===G.user&&!x.isP&&!x.foreign&&!x.e1&&!x.ys&&healthy(x)); ok(v,'준비: 2군 야수'); for(const k in v.r)if(k!=='vit')v.r[k]=80; delete v.downDay; v.mil={unit:'상무',from:G.day-MIL_DAYS,until:G.day}; ok(playersOf(G.user).filter(x=>x.e1).length>=entryLimit(),'준비: 1군 정원');
  milDaily(); ok(v.e1,'전역한 주전급이 2군에 남음');
  const pp=playersOf(G.user).find(x=>x.isP&&x.e1&&isSPr(x)&&healthy(x)); pp.e1=false; pp.downDay=G.day; const o0=(seasonTotalT(pp,G.year,'퓨처스',G.user)||{}).outs||0; futuresWeek(); ok(((seasonTotalT(pp,G.year,'퓨처스',G.user)||{}).outs||0)===o0,'당일 말소 선발이 퓨처스에서 던짐'); ok(!G.futLn[G.user].rot.includes(pp.id),'당일 말소 투수가 퓨처스 로테이션에 들어감');
  for(const p of Object.values(G.players))if(p.team===G.user)p.hist=p.hist.filter(h=>!(h.y===G.year&&h.lvl==='퓨처스')); G.fut0=null;
  const cu=Object.values(G.players).find(x=>x.team===G.user&&!x.isP&&!x.foreign&&!x.e1&&!x.ys&&healthy(x)&&x!==v); for(const k in cu.r)if(k!=='vit')cu.r[k]=80; delete cu.downDay; G.mail=G.mail.filter(m=>!m.subj.includes('2군 리포트')); futuresReport(); const m1=G.mail[0]; ok(m1&&m1.subj.includes('2군 리포트')&&m1.body.includes('콜업 후보'),'콜업 후보만 있는 달에 리포트가 없음');
  const hr=playersOf(G.user).find(x=>x.e1&&!x.isP&&!x.foreign); Object.assign(lineFor(hr,G.year,G.user,'퓨처스'),{g:15,pa:60,ab:54,h:18,hr:6,bb:6,d2:3}); G.mail=G.mail.filter(m=>!m.subj.includes('2군 리포트')); futuresReport(); ok(G.mail[0].subj.includes('2군 리포트')&&G.mail[0].body.includes(hr.name),'콜업된 선수의 2군 성적이 빠짐');
  const y=Object.values(G.players).find(x=>x.team===G.user&&!x.isP&&!x.foreign&&!x.e1&&!x.ys); y.age=21; G.mgr[G.user].pl=Object.assign({},G.mgr[G.user].pl,{youth:1}); G.mgr[G.user].interim=false; const op=G.teams.find(t=>t.id!==G.user).id; const hh=Object.assign(lineFor(y,G.year,op,'퓨처스'),{g:15,pa:60,ab:54,h:20,hr:3,bb:6,d2:5}); const lean=teamLean(G.user); const e1=entryVal(G.user,y,lean); hh.t=G.user; const e2=entryVal(G.user,y,lean); ok(e2-e1>2.9,'현 구단 기록 보너스 확인 실패 '+(e2-e1)); hh.t=op; ok(Math.abs(entryVal(G.user,y,lean)-e1)<1e-9,'전 구단 퓨처스 기록으로 약속 보너스');
  const k=Object.values(G.players).find(x=>x.team===G.user&&!x.foreign&&!x.e1&&!x.ys&&!x.mil&&!(x.injOut>0)&&!seasonTotal(x,G.year,'1군')); ok(k,'준비: 1군 기록 없는 선수'); const rc=G.sea.rec[G.user]; rc.w=Math.max(rc.w,10); k.age=21; k.pot=ovr(k)+15; k.hold={off:50,ask:80,d:G.day}; ok(!keepWhy(k).includes('출전 시간'),'미계약 선수에게 2군 출전 사유: '+keepWhy(k)); });
/* 검수 11-09zt: 타석 결과·교체 시점을 고정한 경기(A 홈, B 원정). cfg.A는 A가 수비할 때(B 공격) n번째 타석, cfg.B는 그 반대. 항목: 'K' 같은 결과 또는 {o,chg(다음 확인 때 교체),av(불펜 가능 여부),lb(타구)}. lock이면 A 불펜은 처음에 잠금 */
const ztGame=cfg=>{ const [A,B]=G.teams.filter(t=>t.id!==G.user).map(t=>t.id); for(const t of [A,B]){ const m=G.mgr[t]; if(m){ m.small=cfg.small&&t===B?100:0; m.interim=false; } }
  const oOut=outcome, oMP=mgrPush, oST=stealTry, oRA=relAvail, cnt={}, fl={}, av={}; cnt[A]=cnt[B]=0; if(cfg.lock)av[A]=false;
  outcome=(b,p,dv,fp,fs)=>{ const t=fs.tid, n=++cnt[t]; fl[t]=false; const f=cfg[t===A?'A':'B'], it=(f&&f(n))||'K', o=typeof it==='string'?it:it.o; if(it.chg)fl[t]=true; if(it.av!=null)av[t]=!!it.av; LBIP=it.lb?Object.assign({side:'L'},it.lb):null; return o; };
  mgrPush=t=>fl[t]?-1000:oMP(t); relAvail=p=>av[p.team]!=null?av[p.team]:true; stealTry=()=>0;
  try{ return simGame(G.day,A,B,false); } finally { outcome=oOut; mgrPush=oMP; stealTry=oST; relAvail=oRA; } };
T('[검수 11-09zt] 승계주자가 번트 실패(야수선택)로 아웃돼도 타자 주자는 앞 투수 책임: 실점·자책·패전, 번트 공별 기록',()=>{ fresh(); const B0=G.teams.filter(t=>t.id!==G.user)[1].id; for(const q of playersOf(B0))if(!q.isP)for(const k in q.r)if(typeof q.r[k]==='number')q.r[k]=20;
  let g=null, row=null; for(let s=1;s<=600&&!row;s++){ globalThis.__seed(s); const x=ztGame({small:1,A:n=>n===1?{o:'BB',chg:1}:n===2?'HR':'K'}); const r=x.pbp.find(z=>typeof z[1]==='number'&&z[0]===0&&z[16]); if(r){ g=x; row=r; } }
  ok(row,'준비 실패: 번트 실패 없음'); const P=g.S.h.pitchers, bx=id=>g.S.h.box.get(id); ok(g.score.a===2&&g.score.h===0&&P.length>=3,'준비 실패: 점수 '+g.score.a+':'+g.score.h+' 투수 '+P.length);
  ok(bx(P[0]).r===1&&bx(P[0]).er===1&&bx(P[1]).r===0&&bx(P[2]).r===1,'실점 선발 '+bx(P[0]).r+'·구원1 '+bx(P[1]).r+'·구원2 '+bx(P[2]).r+'(기대 1·0·1)');
  ok(g.dec.l===P[0],'패전이 결승 주자를 내보낸 선발이 아님');
  const seq=row[15]&&row[15].pitches; ok(seq&&seq[seq.length-1].res==='번트','번트 실패 마지막 공이 '+(seq&&seq[seq.length-1].res)); });
