  G.gmSince=G.year; switchTeam(nt.id); ok(ot.form&&ot.form.b===2&&ot.mpick&&ot.mpick.back,'옛 구단 시즌 효과가 사라짐'); ok(G.form&&G.form.b===1.5&&G.mpick&&G.mpick.ids[0]===nt.mpick.ids[0],'새 구단 시즌 효과를 못 이어받음');
