  const cp=capPay; capPay=()=>5000; G.moves=[]; ok(!opRival(u),'아무도 쓰지 않았는데 라이벌 근거가 나옴'); const c=others[7].tid; G.moves.push({y:G.year,d:G.day,t:'FA',pid:-5,n:'가상',to:c,from:null,sal:4000});
