  G.year++; G.rolled=G.year; G.day=KD(11,20); ovsLeave(p,'MLB',MLBT[0],1,800,'포스팅',usd(postFee(800))); ok(!G.players[id],'포스팅 계약 뒤에도 KBO 선수단에 남음'); const a=G.abroad.find(x=>x.id===id); ok(a&&a.how==='포스팅'&&a.from===G.user,'해외 기록 없음');
  { const pj=JSON.parse(a.pj); pj.age=34; a.pj=JSON.stringify(pj); } G.year++; a.bn={y:G.year,v:1}; abroadYear(); const q=G.players[id]; ok(a.back&&q,'준비 실패: 복귀 안 함');
  ok(q.svc===7,'해외 시즌이 FA 연차에 더해짐: '+q.svc); ok(q.team==null&&q.retFrom===G.user&&q.retAsk&&q.retAsk.post===1,'원소속 보류 협상이 아님'); ok(!q.ext&&!q.extNext&&!(q.faC&&q.yrs===4),'출국 전 다년계약이 남음 '+JSON.stringify({faC:q.faC,ext:q.ext,yrs:q.yrs}));
