  ok(g.box&&g.box.h.bat.length>=9&&g.box.a.pit.length>=1,'박스스코어 없음'); ok(g.mvp&&g.mvp.id!=null,'올스타전 MVP 없음'); if(g.win)ok(g.mvp.side===g.win,'진 진영 선수가 MVP');
