  const p=ulAutoPlan(Date.UTC(2026,10,20,3),true,{src:'now'}); ok(p&&p.skip==='edited'&&p.msg===EDITED_MSG,'자동 등록이 거절되지 않음 '+JSON.stringify(p&&{skip:p.skip,due:p.due}));
