let TR1041world=null;
function TR1041fresh(){if(!TR1041world){DEMO.on=false;_achMem=achMetaFix(null);_achChamp0={};withRng(1041001,()=>{buildWorld({lite:true});claimTeam(6);hireMgr(G.mmarket[0].id,3);});TR1041world=JSON.stringify(G);}G=JSON.parse(TR1041world);worldReset();G.day=dnum(G.year,9,2);G.spend={};G.auto={};G.autoLog=[];G.ovs=[];G.ovsAutoY={};delete G.ovsAutoClubY;G.fall=null;G.fallT={};G.ovsAi=null;G.ovsHold=null;G.pitchCommit=[];const a=G.user,b=G.teams.find(t=>t.id!==a).id;for(const p of Object.values(G.players))if(p.team===a||p.team===b){p.age=23;p.hold=false;p.joinY=G.year;p.injOut=0;p.foreign=null;p.prospect=false;p.mil={done:true};p.pot=Math.max(p.pot,ovr(p)+10);}worldReset();for(const id of [a,b]){team(id).indie=true;team(id).cash=1000;}return {a,b};}
T('[검수 #1041] 수동 교육리그 신청은 자동과 같은 가용액으로 검사하고 부족한 신청은 기존 상태를 보존한다 [교육연수추가검수]',()=>{const {a}=TR1041fresh();team(a).cash=100;ok(spendable(a)===100&&fallPool(a).length===22&&fallFit(a,'jp')==='ul','준비: 가용액과 자동 울산 선택');const raw=JSON.stringify({f:G.fall,s:G.spend,c:team(a).cash}),err=setFall('jp');ok(err&&JSON.stringify({f:G.fall,s:G.spend,c:team(a).cash})===raw,'수동 미야자키가 가용액100으로 비용300 신청');});
T('[검수 #1042] 불참 결정은 떠난 구단에 남고 새 구단의 교육리그 자동 신청을 막지 않는다 [교육연수추가검수]',()=>{const {a,b}=TR1041fresh();setFall(null);switchTeam(b);ok(fallPool(b).length===22&&spendable(b)>=300,'준비: 새 구단 명단과 자금');ok(fallAutoApply()&&G.fall.k==='jp','옛 구단 불참이 새 구단 신청을 막음');switchTeam(a);ok(G.fall&&G.fall.y===G.year&&G.fall.k===null&&!fallAutoApply(),'원 구단의 명시적 불참이 보존되지 않음');});
T('[검수 #1043] 한 구단의 해외 연수 자동 신청 완료는 다른 구단의 같은 해 빈자리를 막지 않는다 [교육연수추가검수]',()=>{const {a,b}=TR1041fresh();G.auto={ovsb:['abl']};ok(autoRoutine(['ovsb'])&&(G.ovs||[]).length===6,'준비: 첫 구단 실제6명 신청');switchTeam(b);const v=ovsBulkView('abl');ok(v.left===6&&v.rows.filter(x=>x.on).length===6,'준비: 새 구단 남은6/추천6');ok(autoRoutine(['ovsb'])&&(G.ovs||[]).filter(x=>x.prog==='abl').length===6,'전 구단 연도 표시로 새 구단 신청이 막힘');switchTeam(a);const before=(G.ovs||[]).length;ok(!autoRoutine(['ovsb'])&&(G.ovs||[]).length===before,'원 구단 재취임에 같은 프로그램을 재신청');});
T('[검수 #1044] 교육리그 완료 상태는 참가 프로그램을 보이고 직원 면담이나 다음 월요일로 안내하지 않는다 [교육연수추가검수]',()=>{TR1041fresh();G.auto={fall:true};ok(!setFall('jp'),'준비: 실제 미야자키 신청');const s=delegStatus('fall');ok(s.includes('미야자키')&&!s.includes('모든 직원')&&!s.includes('다음 월요일'),'교육리그 확정 상태가 면담 범위/다음 월요일로 표시 '+s);});
T('[검수 #1045] 해외 연수만 처리한 날짜가 직원 면담의 최근 처리일을 덮지 않는다 [교육연수추가검수]',()=>{TR1041fresh();G.auto={ovsb:['abl'],stalk:true};const staff=autoRoutine(['stalk']);ok(staff&&staff.includes('직원'),'준비: 실제 직원 면담');const before=delegStatus('stalk');G.day=dnum(G.year,9,9);ok(autoRoutine(['ovsb']),'준비: 실제 해외 연수만 처리');ok(delegStatus('stalk')===before,'해외 연수 날짜가 직원 면담 처리일로 표시 '+delegStatus('stalk'));});
T('[교육연수 정상] 이미 낸 교육리그 참가비는 변경 시 실제 환급할 현금으로 인정한다',()=>{const {a,b}=TR1041fresh();ok(!setFall('ul'),'울산 준비');switchTeam(b);switchTeam(a);ok(G.fall.paid&&G.spend.dev===0,'이미 낸 울산 예약 인계');team(a).cash=250;ok(!setFall('jp')&&G.fall.k==='jp'&&G.spend.dev===300&&team(a).cash===310,'선결제 환급60과 가용250으로 신청하지 못함');team(a).cash=100;ok(!setFall('ul')&&G.spend.dev===60,'울산 재변경');const raw=JSON.stringify([G.fall,G.spend,team(a).cash]);ok(setFall('jp')&&JSON.stringify([G.fall,G.spend,team(a).cash])===raw,'부족한 변경이 기존 예약/장부 변경');ok(setFall('unknown')&&JSON.stringify([G.fall,G.spend,team(a).cash])===raw,'없는 교육리그가 예약/장부 변경');});
T('[교육연수 정상] 이어받은 교육리그의 참가비는 취소와 반복 취소에서 한 번만 현금 환급한다',()=>{const {a,b}=TR1041fresh();setFall('jp');switchTeam(b);switchTeam(a);ok(G.fall.paid,'선결제 신청 인계');const cash=team(a).cash;setFall(null);const once=team(a).cash;setFall(null);ok(once===cash+300&&team(a).cash===once&&G.fall.k===null,'선결제 신청 환급이 누락되거나 중복');});
T('[교육연수 정상] 참가 선수가 없으면 사용자 수동과 자동 및 AI의 같은 예산 판정이 모두 거절한다',()=>{const {a,b}=TR1041fresh();for(const p of Object.values(G.players))if(p.team===a||p.team===b)p.age=31;worldReset();const rng=__rngState(),raw=JSON.stringify([G.fall,G.spend,team(a).cash]);ok(!fallFit(a,'jp')&&!fallFit(b,'jp')&&setFall('jp')&&!fallAutoApply(),'참가 명단 없는 경로 간 불일치');ok(JSON.stringify([G.fall,G.spend,team(a).cash])===raw&&__rngState()===rng,'참가 거절이 장부나 난수 변경');});
T('[교육연수 정상] 같은 가용액의 사용자와 AI는 같은 교육리그를 고르고 정상 수동 신청은 난수를 소비하지 않는다',()=>{const {a,b}=TR1041fresh();team(a).cash=100;team(b).cash=100;const rng=__rngState();ok(fallFit(a,'jp')==='ul'&&fallFit(b,'jp')==='ul','사용자/AI 같은100에서 선택 불일치');ok(!setFall('ul')&&G.fall.k==='ul'&&G.spend.dev===60,'정상 울산 신청 실패');const raw=JSON.stringify([G.fall,G.spend,team(a).cash]);ok(!setFall('ul')&&JSON.stringify([G.fall,G.spend,team(a).cash])===raw&&__rngState()===rng,'반복 정상 신청이 중복 비용/난수 변경');});
T('[교육연수 옛저장] 구단을 입증할 수 있는 옛 연수 완료 표시는 실제 예약 구단에만 옮기며 두 번 정리해도 같다',()=>{const {a,b}=TR1041fresh();G.auto={ovsb:['abl']};autoRoutine(['ovsb']);G.ovsAutoY={abl:G.year};delete G.ovsAutoClubY;G.user=b;const rng=__rngState(),cash=G.teams.map(t=>t.cash),spend=JSON.stringify(G.spend);trainingDelegationMigrate();ok(ovsAutoDone('abl',a)&&!ovsAutoDone('abl',b),'옛 예약 구단을 현재 구단으로 오인');const once=JSON.stringify(G);trainingDelegationMigrate();ok(JSON.stringify(G)===once&&JSON.stringify(G.spend)===spend&&JSON.stringify(G.teams.map(t=>t.cash))===JSON.stringify(cash)&&__rngState()===rng,'반복 정리가 상태/비용/난수 변경');});
T('[교육연수 옛저장] 소속을 입증할 예약이 없는 전역 완료 표시는 현재 구단에 임의로 귀속하지 않는다',()=>{const {b}=TR1041fresh();G.user=b;G.ovsAutoY={abl:G.year};const rng=__rngState();trainingDelegationMigrate();ok(!ovsAutoDone('abl',b)&&G.ovsAutoUnknownY.abl===G.year,'구단 없는 옛 표시를 현재 구단에 귀속');const once=JSON.stringify(G);trainingDelegationMigrate();ok(JSON.stringify(G)===once&&__rngState()===rng,'알 수 없는 옛 표시 반복 정리 변경');});
T('[교육연수 옛저장] 실제 불러오기 전체 정리는 JSON 저장 재불러오기 뒤 두 번 실행해도 교육리그 예약과 비용을 바꾸지 않는다',()=>{const {a}=TR1041fresh();G.auto={ovsb:['abl'],fall:true};setFall('ul');autoRoutine(['ovsb']);G.ovsAutoY={abl:G.year};delete G.ovsAutoClubY;migrateDraft();G=JSON.parse(JSON.stringify(G));worldReset();const cash=JSON.stringify(G.teams.map(t=>t.cash)),spend=JSON.stringify(G.spend),f=JSON.stringify(G.fall),rng=__rngState();migrateDraft();const meta=JSON.stringify([G.fall,G.ovsAutoClubY,G.ovsAutoUnknownY]);G=JSON.parse(JSON.stringify(G));worldReset();migrateDraft();ok(JSON.stringify([G.fall,G.ovsAutoClubY,G.ovsAutoUnknownY])===meta&&JSON.stringify(G.fall)===f&&JSON.stringify(G.spend)===spend&&JSON.stringify(G.teams.map(t=>t.cash))===cash&&ovsAutoDone('abl',a)&&__rngState()===rng,'불러오기 전체 정리의 교육연수 상태/비용/난수 변경');});
T('[교육연수 정상] 이전 형식의 종류 없는 정기 업무 기록을 직원 면담 처리일로 추측하지 않는다',()=>{TR1041fresh();G.auto={stalk:true};G.autoLog=[{d:G.day,t:'정기 업무(운영팀)',c:'과거 연수 신청',k:'auto'}];const s=delegStatus('stalk');ok(!s.includes('최근 처리'),'종류 없는 과거 정기 업무를 직원 면담으로 귀속');});
T('[교육연수 정상] 교육리그 위임 상태는 신청 전 개시일과 마감 및 자금 부족을 사실대로 알린다',()=>{const {a}=TR1041fresh();G.auto={fall:true};G.day=dnum(G.year,8,20);ok(delegStatus('fall').includes('9월 1일'),'개시 전 안내 오류');G.day=dnum(G.year,9,2);team(a).cash=10;ok(delegStatus('fall').startsWith('대기:')&&delegStatus('fall').includes('부족'),'자금 부족 안내 오류');G.day=dnum(G.year,10,11);ok(delegStatus('fall').includes('신청 마감')&&!delegStatus('fall').includes('다음 월요일'),'마감 뒤 다음 월요일을 안내');});
T('[교육연수 정상] AI 계획도 그 구단의 명시적 교육리그 불참을 다시 참가로 바꾸지 않는다',()=>{const {b}=TR1041fresh();G.fallT[b]={y:G.year,tid:b,k:null};const out=withRng(1042001,()=>ovsAiPlan());ok(!out.fall[b]&&G.fallT[b].k===null,'AI 계획이 인계된 명시적 불참을 변경');});
T('[교육연수 정상] 다른 구단에서 처리한 직원 면담 기록을 새 구단의 처리일로 가져오지 않는다',()=>{const {b}=TR1041fresh();G.auto={stalk:true};ok(autoRoutine(['stalk']),'첫 구단 면담');switchTeam(b);ok(!delegStatus('stalk').includes('최근 처리'),'전 구단 직원 면담 날짜를 새 구단에 표시');});
T('[교육연수 정상] 야인 상태의 수동 교육리그 변경은 거절하고 위임 상태는 옛 구단 완료 대신 중지로 표시한다',()=>{const {a}=TR1041fresh();G.auto={fall:true,stalk:true};setFall('jp');ok(!resignGM()&&G.unemp,'실제 사임');const raw=JSON.stringify([G.fall,G.fallT,G.spend,team(a).cash]);ok(setFall(null)&&JSON.stringify([G.fall,G.fallT,G.spend,team(a).cash])===raw,'야인이 옛 구단 예약을 취소/환급');ok(delegStatus('fall').includes('일시 중지')&&delegStatus('stalk').includes('일시 중지'),'야인 위임 상태에 전 구단 완료/처리예정 표시');});
T('[교육연수 정상] 실제 사임 뒤 AI도 옛 구단의 교육리그 불참과 이미 낸 참가비를 보존한다',()=>{for(const k of [null,'jp']){const {a,b}=TR1041fresh();setFall(k);ok(!resignGM()&&G.unemp,'실제 사임');ok(!G.fall&&G.fallT[a]&&G.fallT[a].k===k,'사임한 구단의 결정 인계 누락');const cash=team(a).cash;trainingLeave(a);ok(team(a).cash===cash,'반복 인계가 현금 변경');const out=withRng(1042002,()=>ovsAiPlan());ok(k?out.fall[a]===k:!out.fall[a],'AI가 명시적 결정 변경');const trainingCost=OVSK.reduce((v,p)=>v+((out[p][a]||[]).length?OVS[p].c*out[p][a].length+OVS[p].fix:0),0);ok(team(a).cash===cash-trainingCost,'이미 낸 교육리그 참가비를 AI 계획에서 다시 지출');switchTeam(b);switchTeam(a);ok(G.fall&&G.fall.k===k,'다른 구단 취임 후 돌아와 결정 유실');}});
T('[교육연수 정상] 사임 후 해외 연수 예약은 AI 정원에 한 번만 포함되고 새 구단과 복귀 구단은 각자의 완료 표시를 쓴다',()=>{const {a,b}=TR1041fresh();G.auto={ovsb:['abl']};autoRoutine(['ovsb']);const ids=G.ovs.map(x=>x.pid);ok(ids.length===6&&!resignGM(),'실제6명 신청/사임');trainingLeave(a);ok(new Set(G.ovsAi.abl[a]).size===6&&G.ovsAi.abl[a].length===6,'반복 인계 예약 중복');G.day=dnum(G.year,10,11);tabDaily(G.day);const held=G.ovsAi.abl[a];ok(held.length===6&&ids.every(id=>held.includes(id)),'AI 계획이 기존6명 밖으로 같은 프로그램을 추가');for(const k of OVSK){const idsB=G.ovsAi[k][b]||[];if(idsB.length){team(b).cash+=OVS[k].c*idsB.length+OVS[k].fix;delete G.ovsAi[k][b];}}switchTeam(b);ok(ovsBulkView('abl').left===6&&autoRoutine(['ovsb'])&&G.ovs.length===6,'새 구단 연도 완료가 잘못 승계');switchTeam(a);ok(G.ovs.filter(x=>x.prog==='abl').length===6&&!autoRoutine(['ovsb']),'복귀 구단 예약/완료 표가 중복되거나 유실');});
T('[교육연수 정상] 구형 전역 완료 표시가 남아 있어도 권한 상태 조회는 저장과 주난수를 바꾸지 않는다',()=>{TR1041fresh();G.auto={ovsb:['abl'],stalk:true,fall:true};G.ovsAutoY={abl:G.year};const raw=JSON.stringify(G),rng=__rngState();delegStatus('ovsb');delegStatus('stalk');delegStatus('fall');ok(JSON.stringify(G)===raw&&__rngState()===rng,'권한 상태 조회가 옛 완료 표시를 변경하거나 난수를 소비');});
T('[교육연수 정상 난수] 기존 정상 AI 연수 계획의 선택 명단 현금과 다음 난수는 기준 커밋과 같다',()=>{TR1041fresh();const rng=__rngState(),r=withRng(1041002,()=>{const out=ovsAiPlan();return {hash:FrontOfficeCore.cupHashStr(JSON.stringify(out)),next:R(),cash:FrontOfficeCore.cupHashStr(JSON.stringify(G.teams.map(t=>t.cash)))};});ok(r.hash==='80d173a3'&&r.next===0.36397000844590366&&r.cash==='0ecc864b','정상 AI 계획/현금/난수 순서가 기준과 달라짐 '+JSON.stringify(r));ok(__rngState()===rng,'보조 난수 계획이 주난수 변경');});

T('[교육연수 예산] 미결 울산 참가비가 현금에서 빠지지 않은 독립구단은 가용250으로 미야자키300을 신청할 수 없다',()=>{const {a}=TR1041fresh();setFall('ul');team(a).cash=250;ok(!G.fall.paid&&G.spend.dev===60&&spendable(a)===250,'미결 울산/현금250 준비');const raw=JSON.stringify([G.fall,G.spend,team(a).cash]);ok(setFall('jp')&&JSON.stringify([G.fall,G.spend,team(a).cash])===raw,'장부 취소만 가능한 참가비를 현금처럼 더함');const predicted=fallRefundFunds(a,G.fall);setFall(null);ok(predicted===spendable(a)&&predicted===250,'미결 독립구단 취소의 실제 자금과 사전 계산이 다름');});
T('[교육연수 예산] 모기업 구단의 미결 참가비 취소로 실제 예산 여유가 복원되는 만큼만 변경 자금에 반영한다',()=>{const {a}=TR1041fresh();team(a).indie=false;team(a).cash=0;ok(!setFall('ul'),'일반 구단 울산 준비');const b=budget();G.spend.etc=(G.spend.etc||0)+b.roomGoal-250;ok(spendable(a)===250,'일반 구단 예산 여유250 준비');const raw=JSON.stringify([G.fall,G.spend,team(a).cash]),predicted=fallRefundFunds(a,G.fall);ok(predicted===310&&!fallEntryWhy(a,'jp',true)&&JSON.stringify([G.fall,G.spend,team(a).cash])===raw,'예산 복원액60을 순수하게 계산하지 못함');setFall(null);ok(spendable(a)===predicted&&team(a).cash===0,'미결 비용 실제 취소 후 예산과 미리보기 불일치');});
T('[교육연수 예산] 모기업 구단의 목표 예산 적자가 남으면 미결 참가비 취소를 추가 현금처럼 세지 않는다',()=>{const {a}=TR1041fresh();team(a).indie=false;team(a).cash=250;ok(!setFall('ul'),'일반 구단 울산 준비');const b=budget();G.spend.etc=(G.spend.etc||0)+b.roomGoal+100;ok(budget().roomGoal===-100&&spendable(a)===250,'목표 적자100/가용250 준비');const raw=JSON.stringify([G.fall,G.spend,team(a).cash]),predicted=fallRefundFunds(a,G.fall);ok(predicted===250&&setFall('jp')&&JSON.stringify([G.fall,G.spend,team(a).cash])===raw,'복원 후에도 남는 적자에 가짜 현금60을 더함');setFall(null);ok(spendable(a)===predicted&&team(a).cash===250,'실제 취소 뒤 가용액과 불일치');});
T('[교육연수 예산] 선결제 참가비의 모기업 현금 환급과 자체 현금 분담 변화는 실제 취소한 가용액과 같다',()=>{const {a,b}=TR1041fresh();setFall('ul');switchTeam(b);switchTeam(a);ok(G.fall.paid,'선결제 인계');team(a).indie=false;team(a).cash=4000;const q=budget();G.spend.etc=(G.spend.etc||0)+q.roomGoal+1000;const cash=team(a).cash,raw=JSON.stringify([G.fall,G.spend,team(a).cash]),predicted=fallRefundFunds(a,G.fall);ok(JSON.stringify([G.fall,G.spend,team(a).cash])===raw,'환급 자금 미리보기가 기록 변경');setFall(null);ok(Math.abs(spendable(a)-predicted)<1e-8&&team(a).cash===cash+60,'실제 현금 환급/예산 분담과 미리보기 불일치');});

/* 1046–1053: behavior checks. The original eight assertions must fail on the pre-fix engine. */
let MT1046base=null;
function MT1046fresh(){if(!MT1046base){DEMO.on=false;_achMem=achMetaFix(null);_achChamp0={};withRng(1046001,()=>{buildWorld({lite:true});claimTeam(6);hireMgr(G.mmarket[0].id,3);});MT1046base=JSON.stringify(G);}G=JSON.parse(MT1046base);worldReset();G.day=G.cal.open+30;G.tut={done:true,step:99};G.spend={};G.auto={};G.autoLog=[];G.deleg={};G.evPol={};G.evs=[];G.evf=[];G.evlog=[];G.mail=[];G.stops=[];G.mentor=null;G.vetAsk=null;delete G.vetAskByClub;return {a:G.user,b:G.teams.find(t=>t.id!==G.user).id};}
function MT1046vet(tid=G.user){const p=playersOf(tid).find(q=>!q.foreign&&!q.prospect);initPers(p);p.age=36;p.pers.pro=20;return p;}
function MT1046ob({ys=10,war=30,rn=false,legacy=false,path='media'}={}){G.ob=G.ob||[];G.retNos=[];const id=777000+G.ob.length,o=obMake({fid:id,name:'LEGEND'+id,team:G.user,ys,war,seasons:ys,age:38,retY:G.year,path,pers:{pro:15,amb:10,loy:15,temp:10},pos:'1루수'});o.mineWar=war;if(rn){o.canRetNo='p'+id;o.no=18;(G.legends=G.legends||[]).push({pid:id,name:o.name,tid:G.user,canRetNo:true,no:18,y:G.year,mine:{war,ys}});}obRetireEvents([o]);const e=G.evs.filter(e=>e.k==='ret'&&e.data.ob===o.id).at(-1);if(legacy)delete e.key;return {o,e};}
T('[검수 #1046 멘토위임검수] 소식함 일괄 위임은 레전드·결번·5시즌·옛 저장과 단장 고유 결정을 그대로 남긴다',()=>{const errors=[];for(const cfg of [{ys:10,war:30},{ys:5,war:2},{ys:3,war:2,rn:true},{ys:5,war:2,legacy:true}]){MT1046fresh();const {e}=MT1046ob(cfg),raw=JSON.stringify([G.spend,G.retNos]);const n=evHandAll(G.mail);if(n||e.done||JSON.stringify([G.spend,G.retNos])!==raw)errors.push(JSON.stringify(cfg)+' '+n+'/'+e.done);}ok(!errors.length,'보호할 은퇴 결정을 일괄 처리함 '+errors.join('; '));});
T('[검수 #1047 멘토위임검수] 앞으로 베테랑 제안을 맡기는 명시적 선택은 이번 건과 다음 제안 모두에 적용된다',()=>{MT1046fresh();G.evPol={vet:'self'};const p=MT1046vet();EVH.vet.make(p);const e=G.evs.at(-1);ok(mailDelegOpts(G.mail.find(m=>m.id===e.mid)).some(o=>o.a==='evDeleg'&&/앞으로/.test(o.d)),'실제 앞으로 위임 선택 없음');evDeleg(e.id);ok(e.done,'이번 건 미처리');G.year++;G.day=dnum(G.year,5,1);const candidate=EVH.vet.check();ok(candidate,'다음 시즌 정상 후보 없음');EVH.vet.make(candidate);ok(G.evs.at(-1).done&&evDelegOn('vet'),'앞으로 위임했지만 직접 결정 기준이 남음');});
T('[검수 #1048 멘토위임검수] 일상 업무를 가져올 때 유지되는 개별 멘토 자동 기준을 명확히 알린다',()=>{MT1046fresh();G.evPol={vet:'yes'};autoSet('ev',true);const msg=takeBack('ev');ok(!autoOn('ev')&&evPolOf('vet')==='yes','개별 자동 기준 우선 정책 변경');ok(/베테랑|멘토|개별/.test(msg)&&/자동|별도|예외|유지/.test(msg),'모두 직접 한다는 안내만 남음: '+msg);EVH.vet.make(MT1046vet());ok(G.evs.at(-1).done&&(G.spend.etc||0)===50,'명시적 개별 자동 승낙 효과 변경');});
T('[검수 #1049 멘토위임검수] 실제 방출된 멘토는 원구단 젊은 선수에게 성장 보너스를 남기지 않는다',()=>{MT1046fresh();const p=MT1046vet(),q=playersOf(G.user).find(q=>q.id!==p.id&&!q.foreign);q.age=22;EVH.vet.make(p);evPick(G.evs.at(-1).id,0);releasePlayer(p.id);ok(p.team==null,'실제 방출 실패');const got=coachDevMult(q),M=G.mentor;G.mentor=null;const plain=coachDevMult(q);G.mentor=M;ok(Math.abs(got-plain)<1e-10,'방출 뒤에도 성장 '+got/plain+'배');});
T('[검수 #1050 멘토위임검수] A구단 거절은 실제 B구단 이직 뒤 B구단의 정상 멘토 후보를 막지 않는다',()=>{const {a,b}=MT1046fresh();EVH.vet.make(MT1046vet(a));evPick(G.evs.at(-1).id,1);const p=MT1046vet(b);switchTeam(b);const got=EVH.vet.check();ok(got&&got.team===b,'A구단의 전역 연도 표시로 B구단 후보 누락 '+p.id);});
T('[검수 #1051 멘토위임검수] AI는 첫 주 자금 부족 뒤 실제 자금과 후보가 생기면 다시 지정한다',()=>{const {b}=MT1046fresh(),t=team(b),p=MT1046vet(b);for(const q of playersOf(b))if(q!==p&&q.age>=33){initPers(q);q.pers.pro=5;}t.plan={k:'next'};t.cash=49;aiMentorPick();ok(!((G.clubT||{})[b]||{}).mentor,'자금 부족인데 AI 멘토 지정');t.cash=500;G.day+=7;aiMentorPick();const M=((G.clubT||{})[b]||{}).mentor;ok(M&&M.id===p.id&&M.y===G.year&&t.cash===450,'첫 실패를 시즌 완료로 저장해 재시도하지 않음');});
T('[검수 #1052 멘토위임검수] 결번 행사 대신 실제 은퇴식만 열렸으면 소식·이력·자동 기록도 실제 비용을 쓴다',()=>{MT1046fresh();team(G.user).indie=true;team(G.user).cash=65;const {e}=MT1046ob({rn:true});const msg=evPick(e.id,0),mail=G.mail.find(m=>m.id===e.mid),row=G.evlog[0];ok((G.spend.etc||0)===50&&!G.retNos.length&&/은퇴식만/.test(msg),'실제 5천만 은퇴식 fallback 설정');ok(!/영구결번|1억/.test(row.c)&&/5천만|5,000만/.test(row.c),'실제 비용과 다른 결정 이력 '+row.c);ok(!/\\[결정\\][^\\n]*(영구결번|1억)/.test(mail.body),'메일 결정 줄이 원래 1억을 성공으로 기록');});
T('[검수 #1053 멘토위임검수] 명시한 감독 업무 조율은 감독 공백 때 다른 무료 면담으로 바뀌지 않는다',()=>{MT1046fresh();G.auto={stalk:true,stalkT:'coord'};G.mgr[G.user]=null;const before=JSON.stringify([G.coach[G.user],G.scouts,G.analysts,G.coachX,G.autoLog]);const msg=autoRoutine(['stalk']);ok(!msg&&JSON.stringify([G.coach[G.user],G.scouts,G.analysts,G.coachX,G.autoLog])===before,'coord 설정에서 listen 관계 상승 '+msg);ok(stalkMode()==='coord','선택한 방식 변경');});

/* Run after the definitions in mentor-1046-common-T.js; no source edits needed. */
T('[멘토위임 정상] 짧은 은퇴 행사 일괄 처리는 이번 건만 처리하고 권한은 바꾸지 않는다',()=>{MT1046fresh();G.evPol={vet:'self'};const {e}=MT1046ob({ys:4,war:2});const raw=JSON.stringify([G.auto,G.deleg,G.evPol]);ok(evHandAll(G.mail)===1&&e.done&&e.pick===e.opts.length-1,'짧은 경력의 기본 은퇴 결정 변경');ok(JSON.stringify([G.auto,G.deleg,G.evPol])===raw,'이번 건 일괄 처리로 미래 권한 변경');});
